SELECT public.ceds_tmp_valueset('LearningResourceType', 'The predominate type or kind characterizing the learning resource.', NULL, 'scheme: C000928', NULL, $j$[{"v": "AlternateAssessment", "n": "Alternate Assessment", "d": "An assessment that is used to evaluate the performance of students who are unable to participate in general state assessments even with accommodations.", "u": null, "notes": "concept: NI000928115239", "dep": null}, {"v": "AssessmentItem", "n": "Assessment Item", "d": "A specific prompt, that defines a question or protocol for a measurable activity that triggers a response from a person used to determine whether the person has mastered a learning objective.", "u": null, "notes": "concept: NI000928115278", "dep": null}, {"v": "Course", "n": "Course", "d": "A series of units and lessons used to teach the skills and knowledge required by its curriculum.", "u": null, "notes": "concept: NI000928115514", "dep": null}, {"v": "DemonstrationSimulation", "n": "Demonstration/Simulation", "d": "An imitation or modeling of a real-world process.", "u": null, "notes": "concept: NI000928115544", "dep": null}, {"v": "EducatorCurriculumGuide", "n": "Educator/Curriculum Guide", "d": "A document that defines what concepts should be taught and/or how a concept should be taught effectively.", "u": null, "notes": "concept: NI000928115628", "dep": null}, {"v": "FormativeAssessment", "n": "Formative assessment", "d": "A process used by teachers and students during instruction that provides feedback to adjust ongoing teaching and learning to improve students' achievement of intended instructional outcomes. (CCSSO FAST SCASS, 2006)", "u": null, "notes": "concept: NI000928115759", "dep": null}, {"v": "ImagesVisuals", "n": "Images/Visuals", "d": "Visual media, including but not limited to pictures, graphics, diagrams, figures, illustrations, charts, and maps.", "u": null, "notes": "concept: NI000928115898", "dep": null}, {"v": "InterimSummativeAssessment", "n": "Interim/Summative Assessment", "d": "An assessment instrument used to evaluate student learning at the end of an instructional unit by comparing it against some standard or benchmark. A learning resource of this type may be an \"assessment form,\" i.e. one instance of the assessment instrument that can equate scores with another instance of the same assessment.", "u": null, "notes": "concept: NI000928115950", "dep": null}, {"v": "LearningActivity", "n": "Learning Activity", "d": "Activities engaged in by the learner for the purpose of acquiring certain skills, concepts, or knowledge, whether guided by an instructor or not. A Lesson may define one or more learning activities.", "u": null, "notes": "concept: NI000928116014", "dep": null}, {"v": "Lesson", "n": "Lesson", "d": "A detailed description of the course of instruction for a �short period of time that is used by a teacher to guide class instruction.  A Unit contains one or more lessons.", "u": null, "notes": "concept: NI000928116021", "dep": null}, {"v": "Other", "n": "Other", "d": "A type of learning resource in a category not yet defined by CEDS.", "u": null, "notes": "concept: NI000928116356", "dep": null}, {"v": "PrimarySource", "n": "Primary Source", "d": "An artifact, document, recording, or other source of information that was created at the time under study and provides first-hand testimony or direct evidence concerning a topic under investigation.", "u": null, "notes": "concept: NI000928116599", "dep": null}, {"v": "RubricScoringGuide", "n": "Rubric/Scoring Guide", "d": "A document or guide that is used to delineate consistent criteria for grading.", "u": null, "notes": "concept: NI000928116780", "dep": null}, {"v": "SelfAssessment", "n": "Self Assessment", "d": "An assessment in which the user gathers information about and reflects on his or her own knowledge, skills, learning, or attitudes.", "u": null, "notes": "concept: NI000928116839", "dep": null}, {"v": "Text", "n": "Text", "d": "The body of a printed work, to include reading passages.", "u": null, "notes": "concept: NI000928117033", "dep": null}, {"v": "Textbook", "n": "Textbook", "d": "A book used as a standard source of information on a particular subject.", "u": null, "notes": "concept: NI000928117034", "dep": null}, {"v": "Unit", "n": "Unit", "d": "A long-range plan of instruction on a particular concept; it contains multiple lessons that are related.", "u": null, "notes": "concept: NI000928117112", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CompetencyDefinitionNodeAccessibilityProfile', 'When the Competency Definition is used as a node in a learning map, this element supports alternative pathways based on a learner''s accessibility profile. The type selected indicates which accessibility profile the node is designed to address.', NULL, 'scheme: C001408', NULL, $j$[{"v": "Communication", "n": "Communication", "d": "The node in the educational framework is designed to address alternative pathways for learners with impaired communication.", "u": null, "notes": "concept: NI001408115464", "dep": null}, {"v": "General", "n": "General", "d": "The node in the educational framework is designed for a general audience.", "u": null, "notes": "concept: NI001408115801", "dep": null}, {"v": "Hearing", "n": "Hearing", "d": "The node in the educational framework is designed to address alternative pathways for learners with impaired hearing.", "u": null, "notes": "concept: NI001408115842", "dep": null}, {"v": "Mobility", "n": "Mobility", "d": "The node in the educational framework is designed to address alternative pathways for learners with impaired mobility.", "u": null, "notes": "concept: NI001408116136", "dep": null}, {"v": "Vision", "n": "Vision", "d": "The node in the educational framework is designed to address alternative pathways for learners with impaired vision.", "u": null, "notes": "concept: NI001408117156", "dep": null}]$j$::jsonb);
