SELECT public.ceds_tmp_valueset('OrganizationType', 'The type of educational organization or entity.', NULL, 'scheme: C001156', NULL, $j$[{"v": "CourseSection", "n": "Course Section", "d": "A setting in which organized instruction of course content is provided to one or more students for a given period of time.", "u": null, "notes": "concept: NI001156173051", "dep": null}, {"v": "AdultEducationProvider", "n": "Adult Education Provider", "d": "An organization with information about programs that help adults get the basic skills they need to be productive workers, family members, and citizens.", "u": null, "notes": "concept: NI001156173052", "dep": null}, {"v": "EmergencyResponseAgency", "n": "Emergency Response Agency", "d": "The local, state, or federal agency that has primary responsibility for responding to an emergency situation.", "u": null, "notes": "concept: NI001156173053", "dep": null}, {"v": "EarlyCollege", "n": "Early College", "d": "An institution in which all students participate in a comprehensive plan that integrates their high school course of study and an intentionally designed authentic postsecondary experience leading to their regular high school diploma, an official college transcript and transferable college credit towards a recognized postsecondary degree or credential.", "u": null, "notes": "concept: NI001156173054", "dep": null}, {"v": "Campus", "n": "Campus", "d": "A location where the postsecondary institution provides services (admin, residential, education). May be virtual or physical. May be called by other terms (e.g., branch, location site regional campus).", "u": null, "notes": "concept: NI001156173055", "dep": null}, {"v": "PostsecondarySystem", "n": "Postsecondary System", "d": "A network of peer-level educational organizations intended to provide shared services or collective procurement.", "u": null, "notes": "concept: NI001156173056", "dep": null}, {"v": "SHEEOAgency", "n": "SHEEO Agency", "d": "An entity tasked with overseeing higher education in its state and is led by a state higher education executive officer.", "u": null, "notes": "concept: NI001156173057", "dep": null}, {"v": "Course", "n": "Course", "d": "The organization of subject matter and related learning experiences provided for the instruction of students on a regular or systematic basis, usually for a predetermined period of time (e.g., a semester or two-week workshop) to an individual or group of students (e.g., a class).", "u": null, "notes": "concept: NI001156173058", "dep": null}, {"v": "CharterSchoolAuthorizingOrganization", "n": "Charter School Authorizing Organization", "d": "An organization responsible for authorizing charter schools.", "u": null, "notes": "concept: NI001156173059", "dep": null}, {"v": "CharterSchoolManagementOrganization", "n": "Charter School Management Organization", "d": "A separate legal entity that 1) contracts with one or more charter schools to manage, operate, and oversee the charter schools; or 2) holds a charter, or charters, to operate multiple charter schools. (see Charter School Management Organization Type)", "u": null, "notes": "concept: NI001156173060", "dep": null}, {"v": "StaffDevelopmentProvider", "n": "Staff Development Provider", "d": "An individual or organization who provides a planned, structured process through which an individual improves his or her job-related knowledge, skills, or attitudes. Such a process is deigned to enable a staff member to grow within a profession or organization or to attain an initial or additional credential.", "u": null, "notes": "concept: NI001156173061", "dep": null}, {"v": "ServiceProvider", "n": "Service Provider", "d": "An organization responsible for administering services to an individual or organization participating in a program or receiving services.", "u": null, "notes": "concept: NI001156173062", "dep": null}, {"v": "SEA", "n": "State Education Agency (SEA)", "d": "The agency of the state charged with primary responsibility for coordinating and supervising public instruction, including the setting of standards for elementary and secondary instruction programs, and it is the state agency that administers federal grant programs.", "u": null, "notes": "concept: NI001156173063", "dep": null}, {"v": "Recruiter", "n": "Recruiter", "d": "An organization responsible for identifying and/or selecting prospective employees to fill vacant positions in an organization.", "u": null, "notes": "concept: NI001156173064", "dep": null}, {"v": "Program", "n": "Program", "d": "An organization that supplements the regular school program or serves as early childhood education and care for children prior to reaching school-attendance age. These programs and services are often, but not solely, available through federal, state, or local agencies, non-profit organizations and/or other community-based organizations (or assistance provided by these entities). Services may be instructional or non-instructional in nature, may be direct or in-direct, and may be provided within or outside of a school building.", "u": null, "notes": "concept: NI001156173065", "dep": null}, {"v": "ProfessionalMembershipOrganization", "n": "Professional Membership Organization", "d": "An association or corporation established for the purpose of providing services on a nonprofit basis to its members.", "u": null, "notes": "concept: NI001156173066", "dep": null}, {"v": "PostsecondaryInstitution", "n": "Postsecondary Institution", "d": "An organization that provides educational programs for individuals who have completed or otherwise left educational programs in secondary school(s).", "u": null, "notes": "concept: NI001156173067", "dep": null}, {"v": "LEA", "n": "Local Education Agency (LEA)", "d": "An administrative unit at the local level which exists primarily to operate schools or to contract for educational services. These units may or may not be co-extensive with county, city, or town boundaries.", "u": null, "notes": "concept: NI001156173068", "dep": null}, {"v": "K12School", "n": "K12 School", "d": "An institution that provides educational services; has one or more grade groups (PK through 12); has one or more teachers; is located in one or more buildings; has an assigned administrator(s).", "u": null, "notes": "concept: NI001156173069", "dep": null}, {"v": "IEU", "n": "Intermediate Educational Unit (IEU)", "d": "A regional, multi-services public agency authorized by State law to develop, manage, and provide services, programs, or other support (e.g., construction, food services, technology services) to LEAs.", "u": null, "notes": "concept: NI001156173070", "dep": null}, {"v": "IDEAPartCLeadAgency", "n": "IDEA Part C Lead Agency", "d": "The lead agency within a State/Jurisdiction responsible for administering IDEA Part C.", "u": null, "notes": "concept: NI001156173071", "dep": null}, {"v": "GoverningBoard", "n": "Governing Board", "d": "An institution that is responsible for the policy decisions of an educational entity.", "u": null, "notes": "concept: NI001156173072", "dep": null}, {"v": "Facility", "n": "Facility", "d": "An installation in which an organization is housed; includes all buildings, structures, and other stationary items that are located on a single site or on contiguous or adjacent sites and that are used for district or system administrative purposes.", "u": null, "notes": "concept: NI001156173073", "dep": null}, {"v": "Employer", "n": "Employer", "d": "A business, firm, institution, or other organization for whom an individual works (including self-employment) in return for financial or other compensation.", "u": null, "notes": "concept: NI001156173074", "dep": null}, {"v": "EmployeeBenefitContributor", "n": "Employee Benefit Contributor", "d": "An individual or organization that contributes monetary, in kind, or other types of contributions to an employee's benefit plan.", "u": null, "notes": "concept: NI001156173075", "dep": null}, {"v": "EmployeeBenefitCarrier", "n": "Employee Benefit Carrier", "d": "An organization or institution that administers benefit plans or services to a staff member.", "u": null, "notes": "concept: NI001156173076", "dep": null}, {"v": "EducationOrganizationNetwork", "n": "Education Organization Network", "d": "A self-organized membership network of peer-level educational organizations intended to provide shared services or collective procurement.", "u": null, "notes": "concept: NI001156173077", "dep": null}, {"v": "EducationInstitution", "n": "Education Institution", "d": "A public or private institution, organization, or agency that provides instructional or support services to students or staff at any level.", "u": null, "notes": "concept: NI001156173078", "dep": null}, {"v": "CredentialingOrganization", "n": "Credentialing Organization", "d": "An institution, organization, federation, or other such group that is responsible for accrediting or endorsing an individual's preparation, skills, or performance.", "u": null, "notes": "concept: NI001156173079", "dep": null}, {"v": "AffiliatedInstitution", "n": "Affiliated Institution", "d": "An institution that has an ongoing, functional relationship with the education institution in order to provide improved educational experiences to an individual and/or the school.", "u": null, "notes": "concept: NI001156173080", "dep": null}, {"v": "AccreditingOrganization", "n": "Accrediting Organization", "d": "An authority that reviews an organization's educational program and staff for quality, and certifies whether the organization meets a minimal set of standards.", "u": null, "notes": "concept: NI001156173081", "dep": null}, {"v": "Region", "n": "Region", "d": "An area or other organizational construct that is identified by defined characteristics and is typically used to group other related organizations.", "u": null, "notes": "concept: NI001156173082", "dep": null}, {"v": "EarlyLearningOrganization", "n": "Early Learning Organization", "d": "An organization that provides educational and developmental services to children from birth through the age of kindergarten entry, including but not limited to child care centers, Head Start programs, pre-kindergarten programs, family child care homes, and other settings that support early childhood learning and development.", "u": null, "notes": "concept: NI001156928211", "dep": null}]$j$::jsonb);
