SELECT public.ceds_tmp_valueset('AdultEducationSpecialProgramType', 'The type, by location or delivery mode, of adult education instruction program in which an adult participates.', NULL, 'scheme: C000782', NULL, $j$[{"v": "CorrectionalEducation", "n": "Correctional education program", "d": "A program of Adult Basic Education (ABE), Adult Secondary Education (ASE), or English Language Learner (ELL) instruction for adult criminal offenders in correctional institutions.", "u": null, "notes": "concept: NI000782151954", "dep": null}, {"v": "DistanceEducation", "n": "Distance Education", "d": "Formal learning activity where students and instructors are separated by geography, time, or both for the majority of the instructional period. Distance learning materials are delivered through a variety of media, including but not limited to, print, audio recording, videotape, broadcasts, computer software, web-based programs, and other online technology. Teachers support distance learners through communication by mail, telephone, e-mail, or online technologies and software.", "u": null, "notes": "concept: NI000782151955", "dep": null}, {"v": "Homeless", "n": "Program for the Homeless", "d": "Program for the Homeless is specified as the type, by location or delivery mode, of adult education instruction program in which an adult participates.", "u": null, "notes": "concept: NI000782151956", "dep": null}, {"v": "WorkplaceLiteracy", "n": "Workplace Adult Education and Literacy Activities", "d": "Adult education and literacy activities offered by an eligible provider in collaboration with an employer or employee organization at a workplace or an off-site location that is designed to improve the productivity of the workforce.", "u": null, "notes": "concept: NI000782151957", "dep": null}, {"v": "FamilyLiteracy", "n": "Family Literacy Program", "d": "A program with a literacy component for parents and children or other intergenerational literacy components.", "u": null, "notes": "concept: NI000782151958", "dep": null}, {"v": "Co-enrollment", "n": "Co-enrollment in adult education and postsecondary education", "d": "Co-enrollment in adult education and postsecondary education is specified as the type, by location or delivery mode, of adult education instruction program in which an adult participates.", "u": null, "notes": "concept: NI000782151959", "dep": null}, {"v": "CommunityCorrections", "n": "Community Corrections Programs", "d": "A community-based rehabilitation facility or halfway house.", "u": null, "notes": "concept: NI000782151960", "dep": null}, {"v": "IntegratedEducationTraining", "n": "Integrated Education and Training (IET)", "d": "A service approach that provides adult education and literacy activities concurrently and contextually with workforce preparation activities and workforce training for a specific occupation or occupational cluster for the purpose of educational and career advancement.", "u": null, "notes": "concept: NI000782151961", "dep": null}, {"v": "OtherInstitutional", "n": "Other Institutional Programs", "d": "Any other medical or special institution.", "u": null, "notes": "concept: NI000782151962", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AttendanceStatus', 'The status of a person''s attendance associated with an Attendance Event Type and Attendance Event Date in an organization-person-role context.', NULL, 'scheme: C000076', NULL, $j$[{"v": "EarlyDeparture", "n": "Early Departure", "d": "Leaves before the official close of the daily session. Reasons may include a special activity for curricular enrichment, doctor's appointment, and family emergency. State, local, and school regulations may distinguish excused and unexcused early departures. When officially approved on a regular basis, early departures immediately prior to the close of the session are considered to be released time.", "u": null, "notes": "concept: NI000076115614", "dep": null}, {"v": "ExcusedAbsence", "n": "Excused Absence", "d": "Not present but is temporarily excused from attendance because the person is: 1) is ill and attendance would endanger his or her health or the health of others; 2) has an immediate family member who is seriously ill or has died; 3) is observing a recognized religious holiday of his or her faith; or 4) is otherwise excused in accordance with policies.", "u": null, "notes": "concept: NI000076115673", "dep": null}, {"v": "Present", "n": "Present", "d": "Present is specified as the status of a person's attendance associated with an Attendance Event Type, Calendar Event Date, in an organization-person-role context.", "u": null, "notes": "concept: NI000076116594", "dep": null}, {"v": "Tardy", "n": "Tardy", "d": "Is absent at the time a given schedule when attendance begins but is present before the close of that time period.", "u": null, "notes": "concept: NI000076116995", "dep": null}, {"v": "UnexcusedAbsence", "n": "Unexcused Absence", "d": "Not present without acceptable cause or authorization.", "u": null, "notes": "concept: NI000076117109", "dep": null}]$j$::jsonb);
