SELECT public.ceds_tmp_valueset('MilitaryExpertise', 'A list of expertise that the person developed during the service period.', NULL, 'scheme: C002036', NULL, $j$[{"v": "CommunicationSkills", "n": "Communication skills", "d": "While serving in the military, a person developed effective communication skills for communicating with colleagues, superiors, and civilians.", "u": null, "notes": "concept: NI002036181430", "dep": null}, {"v": "CulturalAwareness", "n": "Cultural awareness", "d": "While serving in the military, a person acquired an understanding of different cultures and customs.", "u": null, "notes": "concept: NI002036181431", "dep": null}, {"v": "LeadershipAndManagement", "n": "Leadership and management", "d": "While serving in the military, a person trained to take on leadership roles and manage teams to accomplish objectives.", "u": null, "notes": "concept: NI002036181432", "dep": null}, {"v": "LogisticsAndMaintenance", "n": "Logistics and maintenance", "d": "While serving in the military, a person trained to manage movement and maintenance of personnel, equipment, and supplies", "u": null, "notes": "concept: NI002036181433", "dep": null}, {"v": "SecurityAndSafety", "n": "Security and safety", "d": "While serving in the military, a person trained in security and safety protocols, such as handling weapons and explosives, and in providing security for military installations and personnel.", "u": null, "notes": "concept: NI002036181434", "dep": null}, {"v": "TechnicalSkills", "n": "Technical skills", "d": "While serving in the military, a person gained technical expertise in areas such as mechanics, electronics, computer systems, and engineering.", "u": null, "notes": "concept: NI002036181435", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": "The military expertise of a person is unknown.", "u": null, "notes": "concept: NI002036181436", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('MilitaryDuties', 'A description of the duties encompassed within a period of military service.', NULL, 'scheme: C002037', NULL, $j$[{"v": "AdministrativeDuties", "n": "Administrative duties", "d": "Military personnel responsible for various administrative duties such as maintaining records, processing paperwork, and handling personnel issues.", "u": null, "notes": "concept: NI002037181437", "dep": null}, {"v": "CombatAndMissions", "n": "Combat and missions", "d": "Military personnel deployed on various operations and missions, which may involve combat or non-combat activities such as humanitarian assistance, disaster relief, or peacekeeping.", "u": null, "notes": "concept: NI002037181438", "dep": null}, {"v": "LogisticsAndSupplyChainManagement", "n": "Logistics and supply chain management", "d": "Military personnel responsible for managing the flow of personnel, equipment, and supplies to ensure that they are available when needed.", "u": null, "notes": "concept: NI002037181439", "dep": null}, {"v": "MaintenanceAndRepairs", "n": "Maintenance and repairs", "d": "Military personnel responsible for ensuring that equipment and vehicles are properly maintained and repaired to ensure that they are in good working condition.", "u": null, "notes": "concept: NI002037181440", "dep": null}, {"v": "OperationsAndTraining", "n": "Operations and training", "d": "Military personnel who undergo specialized training and participate in operations and missions to maintain readiness and proficiency.", "u": null, "notes": "concept: NI002037181441", "dep": null}, {"v": "Other", "n": "Other", "d": "Military personnel who have other duties according to their specific military occupational specialty or role within the military.", "u": null, "notes": "concept: NI002037181442", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": "Duties of military personnel are unknown or cannot be categorized.", "u": null, "notes": "concept: NI002037181443", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('MilitaryDischargeCategory', 'A kind of discharge a person received from military services.', NULL, 'scheme: C002044', NULL, $j$[{"v": "AdministrativeDischarge", "n": "Administrative discharge", "d": "A non-punitive discharge given to military personnel who are separated from service due to administrative reasons such as reduction in force or convenience of the government.", "u": null, "notes": "concept: NI002044181444", "dep": null}, {"v": "BadConductDischarge", "n": "Bad conduct discharge", "d": "A discharge given to military personnel who have committed serious offenses such as insubordination, desertion, or assault.", "u": null, "notes": "concept: NI002044181445", "dep": null}, {"v": "DishonorableDischarge", "n": "Dishonorable discharge", "d": "The most severe type of discharge given to military personnel who have committed serious crimes such as espionage, murder, or rape.", "u": null, "notes": "concept: NI002044181446", "dep": null}, {"v": "EntryLevelSeparation", "n": "Entry level separation", "d": "A discharge given to military personnel who have been in service for less than 180 days and are deemed unsuitable for military service.", "u": null, "notes": "concept: NI002044181447", "dep": null}, {"v": "GeneralDischargeUnderHonorableConditions", "n": "General discharge under honorable conditions", "d": "A discharge given to military personnel who have generally met the standards of performance and conduct, but may have had some minor disciplinary issues.", "u": null, "notes": "concept: NI002044181448", "dep": null}, {"v": "HonorableDischarge", "n": "Honorable discharge", "d": "The highest discharge status given to military personnel who have met or exceeded the military's standards for performance and personal conduct during their service.", "u": null, "notes": "concept: NI002044181449", "dep": null}, {"v": "MedicalDischarge", "n": "Medical discharge", "d": "A non-punitive discharge given to military personnel who are medically unfit to continue service due to injury or illness.", "u": null, "notes": "concept: NI002044181450", "dep": null}, {"v": "OtherThanHonorableDischarge", "n": "Other than honorable discharge", "d": "A discharge given to military personnel who have engaged in serious misconduct or have repeatedly violated military rules and regulations.", "u": null, "notes": "concept: NI002044181451", "dep": null}, {"v": "RetirementDischarge", "n": "Retirement discharge", "d": "A non-punitive discharge given to military personnel who have served for a specified period of time and have met the requirements for retirement.", "u": null, "notes": "concept: NI002044181452", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('MilitaryCampaigns', 'A military campaign in which the person has been involved during the service period.', NULL, 'scheme: C002050', NULL, $j$[{"v": "None", "n": "None", "d": "Person has not been involved in a campaign during their U.S. military service", "u": null, "notes": "concept: NI002050181453", "dep": null}, {"v": "Other", "n": "Other", "d": "Person has been involved in an Other campaign during their U.S. military service", "u": null, "notes": "concept: NI002050181454", "dep": null}, {"v": "GulfWar", "n": "The Gulf War (1990-1991)", "d": "Person has been involved in the Gulf War during their U.S. military service", "u": null, "notes": "concept: NI002050181455", "dep": null}, {"v": "IraqWar", "n": "The Iraq War (2003-2011)", "d": "Person has been involved in the Iraq War during their U.S. military service", "u": null, "notes": "concept: NI002050181456", "dep": null}, {"v": "KoreanWar", "n": "The Korean War (1950-1953)", "d": "Person has been involved in the Korean War during their U.S. military service", "u": null, "notes": "concept: NI002050181457", "dep": null}, {"v": "VietnamWar", "n": "The Vietnam War (1955-1975)", "d": "Person has been involved in the Vietnam War during their U.S. military service", "u": null, "notes": "concept: NI002050181458", "dep": null}, {"v": "WarInAfganistan", "n": "The War in Afghanistan (2001-2021)", "d": "Person has been involved in the War in Afghanistan during their U.S. military service", "u": null, "notes": "concept: NI002050181459", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": "Person's campaign involvement during their U.S. military service is Unknown", "u": null, "notes": "concept: NI002050181460", "dep": null}, {"v": "WorldWarII", "n": "World War II (1939-1945)", "d": "Person has been involved in World War II during their U.S. military service", "u": null, "notes": "concept: NI002050181461", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('MilitaryDeploymentStatusCode', 'Deployment status code issued to military personnel by the U.S. military.', NULL, 'scheme: C002051', NULL, $j$[{"v": "AvailableForDeployment", "n": "Available for deployment", "d": "A person is available for deployment.", "u": null, "notes": "concept: NI002051181462", "dep": null}, {"v": "CurrentlyDeployed", "n": "Currently deployed", "d": "A person is currently mobilized and deployed.", "u": null, "notes": "concept: NI002051181463", "dep": null}, {"v": "NonDeployable", "n": "Nondeployable", "d": "A person is nondeployable due to administrative reasons, or, due to legal or disciplinary reasons.", "u": null, "notes": "concept: NI002051181464", "dep": null}, {"v": "PermanentDeploymentExemption", "n": "Permanent deployment exemption", "d": "A person has a permanent medical or administrative exemption from deployment, or, is exempt due to compassionate or hardship reasons.", "u": null, "notes": "concept: NI002051181465", "dep": null}, {"v": "RetiredOrSeparatedFromMilitaryService", "n": "Retired or separated from military service", "d": "A person is retired or separated from military service", "u": null, "notes": "concept: NI002051181466", "dep": null}, {"v": "Temporary exemption from deployment", "n": "Temporary deployment exemption", "d": "A person has a temporary medical or administrative exemption from deployment, including due to pregnancy or childbirth.", "u": null, "notes": "concept: NI002051181467", "dep": null}]$j$::jsonb);
