SELECT public.ceds_tmp_valueset('FinancialAccountGASBRevenueClassification', 'The classification of Governmental Accounting Standards Board (GASB) revenues.', NULL, 'scheme: C002066', NULL, $j$[{"v": "100", "n": "Charges for Services", "d": "The broad category of program revenues that arise from charges to customers, applicants, or others who purchase, use, or directly benefit from the goods, services, or privileges provided, or are otherwise directly affected by the services.", "u": null, "notes": "concept: NI002066181468", "dep": null}, {"v": "400", "n": "General Revenue", "d": "All revenue unless required to be reported as program revenue.", "u": null, "notes": "concept: NI002066181469", "dep": null}, {"v": "300", "n": "Program-specific capital grants and contributions.", "d": "Revenue arising from mandatory and voluntary nonexchange transactions with other governments, organizations, or individuals that are restricted for use in a particular program and that may be used for either operating expenses or for capital expenditures of the program at the discretion of the reporting government.", "u": null, "notes": "concept: NI002066181470", "dep": null}, {"v": "200", "n": "Program-specific operating grants and contributions", "d": "Revenue arising from mandatory and voluntary nonexchange transactions with other governments, organizations, or individuals that are restricted for use in a particular program and that consist of capital assets or resources that are restricted for capital purposes - to purchase, construct, or renovate capital assets associated with a specific program.", "u": null, "notes": "concept: NI002066181471", "dep": null}]$j$::jsonb);
