SELECT public.ceds_tmp_valueset('StudentDropoutStatus', 'An indication of the status of this student as dropout.', NULL, 'scheme: C002068', NULL, $j$[{"v": "Potential", "n": "Potential Dropout", "d": "This status is assigned when the student is not enrolled, and their whereabouts cannot be determined, indicating a potential dropout. The designated reporting deadline, as defined by local, state, or federal authorities for identifying dropout status, has not yet been reached.", "u": null, "notes": "concept: NI002068181473", "dep": null}, {"v": "Reported", "n": "Reported Dropout", "d": "This status is assigned when the student is not enrolled, and their whereabouts cannot be determined. The designated reporting deadline, as defined by local, state, or federal authorities for identifying dropout status, has been reached. This student is reported as a dropout.", "u": null, "notes": "concept: NI002068181474", "dep": null}, {"v": "VerifiedReported", "n": "Verified Reported Dropout", "d": "This status is assigned when an authoritative source provides documentation, in addition to the student's non-enrollment, indicating that this student is a dropout. The designated reporting deadline, as defined by local, state, or federal authorities for identifying dropout status, has been reached. This student is reported as a dropout.", "u": null, "notes": "concept: NI002068181475", "dep": null}]$j$::jsonb);
