SELECT public.ceds_tmp_valueset('CodingSystemOrganizationType', 'The type of organization that created the coding system for this element.', NULL, 'scheme: C002073', NULL, $j$[{"v": "LEA", "n": "Local Education Agency", "d": "An administrative unit at the local level which exists primarily to operate schools or to contract for educational services. These units may or may not be co-extensive with county, city, or town boundaries.", "u": null, "notes": "concept: NI002073181482", "dep": null}, {"v": "Other", "n": "Other", "d": "Other", "u": null, "notes": "concept: NI002073181483", "dep": null}, {"v": "SEA", "n": "State Education Agency", "d": "The agency of the state charged with primary responsibility for coordinating and supervising public instruction, including the setting of standards for elementary and secondary instruction programs, and administering federal grant programs.", "u": null, "notes": "concept: NI002073181484", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('EducationJobType', 'A broad categorization of the job as it relates to education.', NULL, 'scheme: C002074', NULL, $j$[{"v": "1000", "n": "Instructional", "d": "This type of job comprises positions and assignments that involve the responsibility and accountability for providing instruction.", "u": null, "notes": "concept: NI002074181485", "dep": null}, {"v": "1002", "n": "Non-Instructional Support and Services", "d": "This type of job comprises positions and assignments in an education environment that support the overall operation and management of the organization and are not directly involved in instruction of students.", "u": null, "notes": "concept: NI002074181486", "dep": null}, {"v": "9999", "n": "Other", "d": "The broad categorization of the job as it relates to education is an option that is not yet defined in CEDS.", "u": null, "notes": "concept: NI002074181487", "dep": null}, {"v": "1001", "n": "Student Support Staff", "d": "This type of job comprises positions and assignments that provide non-instructional services to support the general welfare of students, including students with disabilities.", "u": null, "notes": "concept: NI002074181488", "dep": null}]$j$::jsonb);
