SELECT public.ceds_tmp_valueset('JobPositionStatusCancelledReason', 'The reason why the job position was given the job position status of cancelled.', NULL, 'scheme: C002080', NULL, $j$[{"v": "1001", "n": "Budgetary Reduction", "d": "The job position has been cancelled because the organization does not have the funding to support the job position.", "u": null, "notes": "concept: NI002080181498", "dep": null}, {"v": "1003", "n": "Enrollment Changes", "d": "The job position has been cancelled due to significant pupil enrollment changes.", "u": null, "notes": "concept: NI002080181499", "dep": null}, {"v": "1002", "n": "Organizational Restructure", "d": "The job position has been cancelled through changes in roles and responsibilities across the organization, the job position is no longer needed, or has become redundant.", "u": null, "notes": "concept: NI002080181500", "dep": null}, {"v": "9999", "n": "Other", "d": "The job position has been cancelled for a reason not yet defined in CEDS.", "u": null, "notes": "concept: NI002080181501", "dep": null}, {"v": "1004", "n": "Specific Grant or Funding Expiration", "d": "The job position has been cancelled as the grant or funding that previously supported it has expired, and there are no available funds to sustain it.", "u": null, "notes": "concept: NI002080181502", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('NeglectedProgramType', 'The type of neglected programs under Title I, Part D, Subpart 1 (State Agency) of ESEA as amended.', NULL, 'scheme: C002084', NULL, $j$[{"v": "CMNTYDAYPRG", "n": "Community Day Programs", "d": "The term \"community day program\" means a regular program of instruction provided by a state agency at a community day school operated specifically for neglected children and youth.", "u": null, "notes": "concept: NI002084181552", "dep": null}, {"v": "GRPHOMES", "n": "Group Homes", "d": "A group home is a facility in which residents are allowed contact with the community, such as attending school or holding a job.", "u": null, "notes": "concept: NI002084181553", "dep": null}, {"v": "OTHER", "n": "Other Programs", "d": "Any other programs, not defined above, which receive Title I, Part D funds and serve neglected or delinquent children and youth.", "u": null, "notes": "concept: NI002084181554", "dep": null}, {"v": "RSDNTLTRTMTHOME", "n": "Residential Treatment Home", "d": "A residential treatment home is a program that provides clinical treatment services in a 24-hour living environment.", "u": null, "notes": "concept: NI002084181555", "dep": null}, {"v": "SHELTERS", "n": "Shelters", "d": "A shelter is a short-term facility that provides temporary care in a physically unrestricting environment. Includes runaway/homeless shelters and other types of shelters.", "u": null, "notes": "concept: NI002084181556", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('DelinquentProgramType', 'The type of delinquent programs under Title I, Part D, Subpart 1 (State Agency) of ESEA as amended or under Title I, Part D, Subpart 2 (LEA) of ESEA, as amended.', NULL, 'scheme: C002085', NULL, $j$[{"v": "ADLTCORR", "n": "Adult Correction", "d": "An adult correctional institution is a facility in which persons, including persons 21 and under, are confined as a result of conviction for a criminal offense.", "u": null, "notes": "concept: NI002085181557", "dep": null}, {"v": "CMNTYDAYPRG", "n": "Community day programs", "d": "The term \"community day program\" means a regular program of instruction provided by a State agency at a community day school operated specifically for delinquent children and youth", "u": null, "notes": "concept: NI002085181558", "dep": null}, {"v": "GRPHOMES", "n": "Group Homes", "d": "A group home is a long-term facility in which residents are allowed extensive contact with the community, such as attending school or holding a job. Includes halfway houses.", "u": null, "notes": "concept: NI002085181559", "dep": null}, {"v": "JUVDET", "n": "Juvenile detention centers", "d": "A juvenile detention center is a shorter term institution that provide care to children who require secure custody pending court adjudication, court disposition, or execution of a court order, or care to children after commitment.", "u": null, "notes": "concept: NI002085181560", "dep": null}, {"v": "JUVLNGTRMFAC", "n": "Long-term secure juvenile facility", "d": "A long-term secure facility is a public or private residential facility that provides confinement of its residents, for the care of children who have been adjudicated to be delinquent or in need of supervision. Similar to juvenile correctional facility.", "u": null, "notes": "concept: NI002085181561", "dep": null}, {"v": "OTHER", "n": "Other programs", "d": "Any other facility or program, not defined above, which meet the definition of an institution for delinquent children and youth.", "u": null, "notes": "concept: NI002085181562", "dep": null}, {"v": "RNCHWLDRNSCMPS", "n": "Ranch/wilderness camps", "d": "A ranch/wilderness camp is a long-term residential facility for persons whose behavior does not necessitate the strict confinement of a long-term secure facility, often allowing them greater contact with the community. Includes ranches, forestry camps, wilderness or marine programs, or farms.", "u": null, "notes": "concept: NI002085181563", "dep": null}, {"v": "RSDNTLTRTMTCTRS", "n": "Residential treatment centers", "d": "A residential treatment center is a facility that focuses on providing some type of individually planned treatment program for youth (substance abuse, sex offender, mental health, etc.) in conjunction with residential care.", "u": null, "notes": "concept: NI002085181564", "dep": null}, {"v": "SHELTERS", "n": "Shelters", "d": "A shelter is a short-term facility that provides temporary care similar to that of a detention center, but in a physically unrestricting environment.", "u": null, "notes": "concept: NI002085181565", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('PartBPostsecondaryOutcomesIndicator', 'An indication of the status of a person within one year of leaving secondary school and who had an individualized education program in effect at the time they left secondary school.', NULL, 'scheme: C002086', NULL, $j$[{"v": "1003", "n": "Other postsecondary education or training within one year", "d": "A person who was enrolled on a full-time or part-time basis for at least one complete term at any time in the year since leaving high school in an education or training program such as Job Corps, adult education, workforce development program, or vocational technical school which is less than a two-year program and does not meet the definition of option \"Higher education within one year.\"", "u": null, "notes": "concept: NI002086181571", "dep": null}, {"v": "9997", "n": "Unknown", "d": "The indication of the status of a person within one year of leaving secondary school and who had an individualized education program in effect at the time they left secondary school is unknown due to either non-response from a direct survey of the individual or a lack of data through other data collection methods.", "u": null, "notes": "concept: NI002086181572", "dep": null}, {"v": "1002", "n": "Competitively employed within one year", "d": "Competitive employment means 1) A person who has worked for pay at or above the minimum wage in a setting with others who are nondisabled for a period of 20 hours a week for at least 90 days at any time in the year since leaving high school. This includes military employment. Or 2) A person who has performed work on a full-time or part-time basis for which that person is compensated at or above minimum wage and comparable to the company rate paid by the employer to employees without disabilities performing similar duties and with similar training and experience; receiving the same level of benefits provided to other employees without disabilities in similar positions; at a location where the employee interacts with other individuals without disabilities; and presented opportunities for advancement similar to other employees without disabilities in similar positions. For defining the rate of compensation for persons working on a \"part-time basis\" under this category, the standard of 20 hours per week for at least 90 days at any time in the year since leaving high school is required as part of this option. This definition applies to military employment.", "u": null, "notes": "concept: NI002086181566", "dep": null}, {"v": "1001", "n": "Higher education within one year", "d": "A person who was enrolled on a full-time or part-time basis in a community college (two-year program) or college or university (four or more-year program) for at least one complete term at any time in the year since leaving high school.", "u": null, "notes": "concept: NI002086181567", "dep": null}, {"v": "9998", "n": "Not engaged Part B outcomes", "d": "The indication of the status of a person within one year of leaving secondary school and who had an individualized education program in effect at the time they left secondary school is an option other than the specific Part B Postsecondary Outcomes of: 1) Higher education within one year, 2) Competitively employed within one year, 3) Other postsecondary education or training within one year, or 4) Other employment within one year", "u": null, "notes": "concept: NI002086181568", "dep": null}, {"v": "9999", "n": "Other", "d": "The indication of the status of a person within one year of leaving secondary school and who had an individualized education program in effect at the time they left secondary school is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI002086181569", "dep": null}, {"v": "1004", "n": "Other employment within one year", "d": "A person has worked for pay or been self-employed for a period of at least 90 days at any time in the year since leaving high school but does not meet the definition of \"Competitively employed within one year.\"", "u": null, "notes": "concept: NI002086181570", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('PerkinsPostProgramPlacementIndicator', 'An indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.', NULL, 'scheme: C002087', NULL, $j$[{"v": "1001", "n": "Advanced training", "d": "Advanced training is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181573", "dep": null}, {"v": "1010", "n": "Employment", "d": "Employment is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181574", "dep": null}, {"v": "1002", "n": "Military service", "d": "Military service is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181575", "dep": null}, {"v": "1101", "n": "National or community service", "d": "National or community service refers to a service program that receives assistance under title I of the National and Community Service Act of 1990 (42 U.S.C. 12511 et seq.).", "u": null, "notes": "concept: NI002087181576", "dep": null}, {"v": "1003", "n": "National or community service or Peace Corps", "d": "National or community service refers to a service program that receives assistance under title I of the National and Community Service Act of 1990 (42 U.S.C. 12511 et seq.). Peace Corps refers to volunteers as described in section 5(a) of the Peace Corps Act (22 U.S.C. 2504(a)).", "u": null, "notes": "concept: NI002087181577", "dep": null}, {"v": "9998", "n": "Not engaged Perkins Post-Program Placement", "d": "The indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education is an option other than the specific Perkins Post-Program Placement of: 1) Advanced training, 2) Military service, 3) National or community service or Peace Corps, 4) Employment, 5) Postsecondary education, 6) Postsecondary certificate, 7) Postsecondary associate degree, or 8) Postsecondary baccalaureate degree", "u": null, "notes": "concept: NI002087181578", "dep": null}, {"v": "9999", "n": "Other", "d": "The indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI002087181579", "dep": null}, {"v": "1009", "n": "Peace Corps", "d": "Peace Corps refers to volunteers as described in section 5(a) of the Peace Corps Act (22 U.S.C. 2504(a)).", "u": null, "notes": "concept: NI002087181580", "dep": null}, {"v": "1007", "n": "Postsecondary associate degree", "d": "Postsecondary associate degree is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181581", "dep": null}, {"v": "1008", "n": "Postsecondary baccalaureate degree", "d": "Postsecondary baccalaureate degree is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181582", "dep": null}, {"v": "1006", "n": "Postsecondary certificate", "d": "Postsecondary certificate is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181583", "dep": null}, {"v": "1005", "n": "Postsecondary education", "d": "Postsecondary education is an indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education.", "u": null, "notes": "concept: NI002087181584", "dep": null}, {"v": "9997", "n": "Unknown", "d": "The indication of the post-program status of a CTE Concentrator in the second quarter after exiting from secondary education is unknown due to either non-response from a direct survey of the individual or a lack of data through other data collection methods.", "u": null, "notes": "concept: NI002087181585", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AccessibleFormatIssuedIndicator', 'An indication that the student was issued an accessible format according to their IEP or 504 Plan.', NULL, 'scheme: C002088', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI002088100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI002088100002", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AccessibleFormatType', 'An alternative manner or form that gives an eligible person access to the work when the copy or phonorecord in the accessible format is used exclusively by the eligible person to permit him or her to have access as feasibly and comfortably as a person without such disability (20 U.S.C. � 121(d)(1)).', NULL, 'scheme: C002089', NULL, $j$[{"v": "1000", "n": "Audio", "d": "Audio format is human-recorded or synthetic voice narration to present information. Audio can be stored and transmitted through both analog and digital means.", "u": null, "notes": "concept: NI002089181586", "dep": null}, {"v": "1001", "n": "Audio Described Video", "d": "Audio description is the verbal explanation of essential visual elements in a video or other multimedia resource, providing access to the visual content when the audio component alone is insufficient for perceiving on-screen actions. (Note: While video is not covered by Section 121/Chafee Amendment of the Copyright Act, it is a material that can be enhanced for accessibility for use by students with disabilities.)", "u": null, "notes": "concept: NI002089181587", "dep": null}, {"v": "1002", "n": "Braille", "d": "Braille code is a tactile system of raised dots that enables students who are blind or have low vision to read through touch. Braille consists of patterns of raised dots arranged in cells of up to six dots in a 3x2 configuration. Each cell represents letters of the alphabet, punctuation, numbers, and whole words. (iii) In the case of a child who is blind or visually impaired, provide for instruction in Braille and the use of Braille unless the IEP Team determines, after an evaluation of the child's reading and writing skills, needs, and appropriate reading and writing media (including an evaluation of the child's future needs for instruction in Braille or the use of Braille), that instruction in Braille or the use of Braille is not appropriate for the child; Sec. 300.324 (a) (2) (iii)", "u": null, "notes": "concept: NI002089181588", "dep": null}, {"v": "1003", "n": "Captioned Video", "d": "Captions are the text representation of the audio content in a video or other multimedia production. Captions are synced with the video and include the words spoken, as well as other important information in the audio track. (Note: While video is not covered by Section 121/Chafee Amendment of the Copyright Act, it is a material that can be enhanced for accessibility for use by students with disabilities.)", "u": null, "notes": "concept: NI002089181589", "dep": null}, {"v": "1004", "n": "Digital Text", "d": "Digital text format refers to accessible file formats that contain both text and images. An accessible digital text file must be usable by the student requiring this format. Examples of file types include accessible EPUB, HTML, MathML, and tagged PDF.", "u": null, "notes": "concept: NI002089181590", "dep": null}, {"v": "1005", "n": "Large Print", "d": "Large print format is provided in a hard copy document containing a font size of 18 points or larger. Additional formatting considerations pertain to styles used for font face and punctuation; format options; use of color; paper selection; and document size.", "u": null, "notes": "concept: NI002089181591", "dep": null}, {"v": "1006", "n": "Tactile Graphics", "d": "Tactile graphics convey non-textual information to people who are blind or have low vision. These may include tactile representations of pictures, maps, graphs, diagrams and other images. Students who are blind or have low vision can feel these raised lines and surfaces to access the same information as students who are sighted. (Note: While graphics are not covered by Section 121/Chafee Amendment of the Copyright Act, it is a material that can be enhanced for accessibility for use by students with disabilities.)", "u": null, "notes": "concept: NI002089181592", "dep": null}, {"v": "1007", "n": "Text Transcripts of Audio", "d": "Transcripts are a text version of the speech and non-speech audio information needed to understand the content in an audio-only file. (Note: While audio is not covered by Section 121/Chafee Amendment of the Copyright Act, it is a material that can be enhanced for accessibility for use by students with disabilities.)", "u": null, "notes": "concept: NI002089181593", "dep": null}, {"v": "1008", "n": "Video with Synchronized American Sign Language (ASL)", "d": "Synchronized ASL is pre-produced sign language interpretation of audio content in a video or other multimedia resource. ASL is synchronized with and displayed alongside media, integrated into the media (picture-in-picture), displayed in a separate window, or displayed on a second screen. (Note: While audio is not covered by Section 121/Chafee Amendment of the Copyright Act, it is a material that can be enhanced for accessibility for use by students with disabilities.)", "u": null, "notes": "concept: NI002089181594", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AccessibleFormatRequiredIndicator', 'An indication that the student requires an accessible format according to their IEP or 504 Plan.', NULL, 'scheme: C002092', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI002092100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI002092100002", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": null, "u": null, "notes": "concept: NI002092100003", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('LEAGFSAAssuranceofComplianceIndicator', 'Indicates if a Local Education Agency (LEA) has provided an assurance that it is in compliance with the State law requiring that a student who brings a firearm to school, or possesses a firearm at school, be expelled for one year, except that such State law shall allow the chief administering officer of a local educational agency to modify such expulsion requirement for a student on a case-by-case basis if such modification is in writing.', NULL, 'scheme: C002096', NULL, $j$[{"v": "Not Provided", "n": "Not Provided", "d": "No assurance was provided from an LEA regarding compliance with State law in accordance with the Gun Free Schools Act requirements.", "u": null, "notes": "concept: NI002096181595", "dep": null}, {"v": "Provided", "n": "Provided", "d": "The LEA has provided an assurance that it is in compliance with State law in accordance with the Gun Free Schools Act requirements.", "u": null, "notes": "concept: NI002096181596", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('LEAGFSAPolicyAssuranceIndicator', 'Indicates if a Local Education Agency has provided an assurance that it is in compliance with the requirement in Section 4141(h) that an LEA receiving ESEA funds have in place a policy requiring referral to the criminal justice or juvenile delinquency system of any student who brings a firearm to a school or possesses a firearm at school.', NULL, 'scheme: C002097', NULL, $j$[{"v": "Not Provided", "n": "Not Provided", "d": "No assurance was provided from an LEA regarding compliance with Section 4141(h) of the Gun Free Schools Act requirements.", "u": null, "notes": "concept: NI002097181597", "dep": null}, {"v": "Provided", "n": "Provided", "d": "The LEA has provided an assurance that it is in compliance with Section 4141(h) of the Gun Free Schools Act requirements.", "u": null, "notes": "concept: NI002097181598", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('BoardMemberPositionType', 'The position or role the person performs on the board.', NULL, 'scheme: C002104', NULL, $j$[{"v": "Chair", "n": "Chair", "d": "Chair is the position or role the person performs on the board.", "u": null, "notes": "concept: NI002104181599", "dep": null}, {"v": "Member", "n": "Member", "d": "Member is the position or role the person performs on the board.", "u": null, "notes": "concept: NI002104181600", "dep": null}, {"v": "Other", "n": "Other", "d": "The position or role the person performs on the board is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI002104181601", "dep": null}, {"v": "Secretary", "n": "Secretary", "d": "Secretary is the position or role the person performs on the board.", "u": null, "notes": "concept: NI002104181602", "dep": null}, {"v": "Treasurer", "n": "Treasurer", "d": "Treasurer is the position or role the person performs on the board.", "u": null, "notes": "concept: NI002104181603", "dep": null}, {"v": "ViceChair", "n": "Vice Chair", "d": "Vice Chair is the position or role the person performs on the board.", "u": null, "notes": "concept: NI002104181604", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('BoardMembershipType', 'The type of membership for the board member.', NULL, 'scheme: C002105', NULL, $j$[{"v": "Appointed", "n": "Appointed", "d": "The type of membership for the board member is appointed.", "u": null, "notes": "concept: NI002105181605", "dep": null}, {"v": "Elected", "n": "Elected", "d": "The type of membership for the board member is elected.", "u": null, "notes": "concept: NI002105181606", "dep": null}, {"v": "Other", "n": "Other", "d": "The type of membership for the board member is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI002105181607", "dep": null}]$j$::jsonb);
