SELECT public.ceds_tmp_valueset('DropoutReasonType', 'The reason or reasons the student dropped out of school.', NULL, 'scheme: C002113', NULL, $j$[{"v": "1002", "n": "Absenteeism", "d": "The reason the student dropped out was due to excessive absences resulting in a loss or potential loss of course credits.", "u": null, "notes": "concept: NI002113181615", "dep": null}, {"v": "1001", "n": "Academic issues", "d": "The reason the student dropped out was due to a lack of academic success.", "u": null, "notes": "concept: NI002113181616", "dep": null}, {"v": "1003", "n": "Adult Education Program", "d": "The reason the student dropped out was to enroll in an adult education or GED program.", "u": null, "notes": "concept: NI002113181617", "dep": null}, {"v": "1004", "n": "Adult High School Enrollment", "d": "The reason the student dropped out was to enroll in an adult high school program that offers a high school diploma.", "u": null, "notes": "concept: NI002113181618", "dep": null}, {"v": "1010", "n": "Care for a family member", "d": "The reason the student dropped out was due to a need to provide care for a family member.", "u": null, "notes": "concept: NI002113181619", "dep": null}, {"v": "1009", "n": "Childcare", "d": "The reason the student dropped out was due a need to provide childcare.", "u": null, "notes": "concept: NI002113181620", "dep": null}, {"v": "1025", "n": "Compulsory attendance age", "d": "The reason the student dropped out was due to being outside of the compulsory attendance age requirements.", "u": null, "notes": "concept: NI002113181621", "dep": null}, {"v": "1006", "n": "Discipline or Behavioral issues", "d": "The reason the student dropped out was due to discipline or behavioral issues.", "u": null, "notes": "concept: NI002113181622", "dep": null}, {"v": "1011", "n": "Disengaged", "d": "The reason the student dropped out was due to a lack of engagement and/or disengagement with teachers, other students, or school activities.", "u": null, "notes": "concept: NI002113181623", "dep": null}, {"v": "1007", "n": "Employment necessity", "d": "The reason the student dropped out was due to a financial need creating an employment necessity.", "u": null, "notes": "concept: NI002113181624", "dep": null}, {"v": "1008", "n": "Employment preference", "d": "The reason the student dropped out was due to their preference of employment over school.", "u": null, "notes": "concept: NI002113181625", "dep": null}, {"v": "1016", "n": "Home environment instability", "d": "The reason the student dropped out was due to instability in the home environment or homelessness.", "u": null, "notes": "concept: NI002113181626", "dep": null}, {"v": "1015", "n": "Illness or health-related issues", "d": "The reason the student dropped out was due to illness or other health-related issues.", "u": null, "notes": "concept: NI002113181627", "dep": null}, {"v": "1017", "n": "Incarceration without high school diploma services", "d": "The reason the student dropped out was due to incarceration in a facility that does not provide education services leading toward a high school diploma.", "u": null, "notes": "concept: NI002113181628", "dep": null}, {"v": "1012", "n": "Lack of expectations", "d": "The reason the student dropped out was due to a lack of expectations from others to complete schooling stemming from either cultural, family, or peer expectations that education beyond a certain age or grade is unnecessary.", "u": null, "notes": "concept: NI002113181629", "dep": null}, {"v": "1018", "n": "Language barrier", "d": "The reason the student dropped out was due to a language barrier.", "u": null, "notes": "concept: NI002113181630", "dep": null}, {"v": "1019", "n": "Marriage", "d": "The reason the student dropped out was due to their own marriage.", "u": null, "notes": "concept: NI002113181631", "dep": null}, {"v": "1020", "n": "Moved", "d": "The reason the student is considered a dropout is because the student is known to or is suspected to have moved and schooling status cannot be verified.", "u": null, "notes": "concept: NI002113181632", "dep": null}, {"v": "9999", "n": "Other", "d": "The reason the student dropped out was due to a reason that is not yet defined in CEDS.", "u": null, "notes": "concept: NI002113181633", "dep": null}, {"v": "1013", "n": "Permanent expulsion", "d": "The reason the student dropped out of school was due to permanent expulsion which is a removal in which the student cannot return to the same school.", "u": null, "notes": "concept: NI002113181634", "dep": null}, {"v": "1005", "n": "Postsecondary enrollment", "d": "The reason the student dropped out was due to enrollment in a postsecondary institution that leads toward a postsecondary degree.", "u": null, "notes": "concept: NI002113181635", "dep": null}, {"v": "1021", "n": "Pregnancy", "d": "The reason the student dropped out was due to their own pregnancy.", "u": null, "notes": "concept: NI002113181636", "dep": null}, {"v": "1023", "n": "Psychological or emotional issues", "d": "The reason the student dropped out was due to psychological or emotional issues.", "u": null, "notes": "concept: NI002113181637", "dep": null}, {"v": "1014", "n": "Removal", "d": "The reason the student dropped out of school was due to removal from the school as a result of one or more exclusionary discipline actions taken by the school.", "u": null, "notes": "concept: NI002113181638", "dep": null}, {"v": "1022", "n": "Runaway", "d": "The reason the student dropped out was due to running away.", "u": null, "notes": "concept: NI002113181639", "dep": null}, {"v": "1000", "n": "Substance abuse", "d": "The reason the student dropped out was due to suspected or confirmed substance abuse.", "u": null, "notes": "concept: NI002113181640", "dep": null}, {"v": "1024", "n": "Unknown", "d": "The reason the student dropped out is unknown.", "u": null, "notes": "concept: NI002113181641", "dep": null}]$j$::jsonb);
