SELECT public.ceds_tmp_valueset('COSRatingA', 'Child''s level of functioning in positive social-emotional skills (including social relationships).', NULL, 'scheme: C001507', NULL, $j$[{"v": "01", "n": "Does not show functioning expected at age - does not include immediate foundational skills", "d": "Child does not yet show functioning expected of a child his or her age in any situation. Child's functioning does not yet include immediate foundational skills upon which to build age-appropriate functioning. Child functioning reflects skills that developmentally come before immediate foundational skills.", "u": null, "notes": "concept: NI001507105747", "dep": null}, {"v": "02", "n": "Occasionally uses immediate foundational skills across settings and situations", "d": "Child occasionally uses immediate foundational skills across settings and situations. More functioning reflects skills that are not immediate foundational than are immediate foundational.", "u": null, "notes": "concept: NI001507105748", "dep": null}, {"v": "03", "n": "Does not show functioning expected at age - uses immediate foundational skills", "d": "Child does not yet show functioning expected of a child of his or her age in any situation. Child uses immediate foundational skills, most or all of the time, across settings and situations. Immediate foundational skills are the skills upon which to build age-appropriate functioning.", "u": null, "notes": "concept: NI001507105749", "dep": null}, {"v": "04", "n": "Shows occasional age-appropriate functioning across settings and situations", "d": "Child shows occasional age-appropriate functioning across settings and situations. More functioning is not age-appropriate than age-appropriate.", "u": null, "notes": "concept: NI001507105750", "dep": null}, {"v": "05", "n": "Shows functioning expected at age some of the time and/or in some settings and situations", "d": "Child shows functioning expected for his or her age some of the time and/or in some settings and situations. Child's functioning is a mix of age-appropriate and not age-appropriate behaviors and skills.", "u": null, "notes": "concept: NI001507105751", "dep": null}, {"v": "06", "n": "Functioning generally is considered appropriate for age but there are some significant concerns", "d": "Child's functioning generally is considered appropriate for his or her age but there are some significant concerns about the child's functioning in this outcome area. These concerns are substantial enough to suggest monitoring or possible additional support.", "u": null, "notes": "concept: NI001507105752", "dep": null}, {"v": "07", "n": "Shows functioning expected for age in all or almost all everyday situations", "d": "Child shows functioning expected for his or her age in all or almost all everyday situations that are part of the child's life. Functioning is considered appropriate for his or her age.", "u": null, "notes": "concept: NI001507105753", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('COSRatingB', 'Child''s level of functioning in the acquisition and use of knowledge and skills (including early language/communication.', NULL, 'scheme: C001508', NULL, $j$[{"v": "01", "n": "Does not show functioning expected at age - does not include immediate foundational skills", "d": "Child does not yet show functioning expected of a child his or her age in any situation. Child's functioning does not yet include immediate foundational skills upon which to build age-appropriate functioning. Child functioning reflects skills that developmentally come before immediate foundational skills.", "u": null, "notes": "concept: NI001508105747", "dep": null}, {"v": "02", "n": "Occasionally uses immediate foundational skills across settings and situations", "d": "Child occasionally uses immediate foundational skills across settings and situations. More functioning reflects skills that are not immediate foundational than are immediate foundational.", "u": null, "notes": "concept: NI001508105748", "dep": null}, {"v": "03", "n": "Does not show functioning expected at age - uses immediate foundational skills", "d": "Child does not yet show functioning expected of a child of his or her age in any situation. Child uses immediate foundational skills, most or all of the time, across settings and situations. Immediate foundational skills are the skills upon which to build age-appropriate functioning.", "u": null, "notes": "concept: NI001508105749", "dep": null}, {"v": "04", "n": "Shows occasional age-appropriate functioning across settings and situations", "d": "Child shows occasional age-appropriate functioning across settings and situations. More functioning is not age-appropriate than age-appropriate.", "u": null, "notes": "concept: NI001508105750", "dep": null}, {"v": "05", "n": "Shows functioning expected at age some of the time and/or in some settings and situations", "d": "Child shows functioning expected for his or her age some of the time and/or in some settings and situations. Child's functioning is a mix of age-appropriate and not age-appropriate behaviors and skills.", "u": null, "notes": "concept: NI001508105751", "dep": null}, {"v": "06", "n": "Functioning generally is considered appropriate for age but there are some significant concerns", "d": "Child's functioning generally is considered appropriate for his or her age but there are some significant concerns about the child's functioning in this outcome area. These concerns are substantial enough to suggest monitoring or possible additional support.", "u": null, "notes": "concept: NI001508105752", "dep": null}, {"v": "07", "n": "Shows functioning expected for age in all or almost all everyday situations", "d": "Child shows functioning expected for his or her age in all or almost all everyday situations that are part of the child's life. Functioning is considered appropriate for his or her age.", "u": null, "notes": "concept: NI001508105753", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('COSRatingC', 'Child''s level of functioning in the use of appropriate behaviors to meet their needs.', NULL, 'scheme: C001509', NULL, $j$[{"v": "01", "n": "Does not show functioning expected at age - does not include immediate foundational skills", "d": "Child does not yet show functioning expected of a child his or her age in any situation. Child's functioning does not yet include immediate foundational skills upon which to build age-appropriate functioning. Child functioning reflects skills that developmentally come before immediate foundational skills.", "u": null, "notes": "concept: NI001509105747", "dep": null}, {"v": "02", "n": "Occasionally uses immediate foundational skills across settings and situations", "d": "Child occasionally uses immediate foundational skills across settings and situations. More functioning reflects skills that are not immediate foundational than are immediate foundational.", "u": null, "notes": "concept: NI001509105748", "dep": null}, {"v": "03", "n": "Does not show functioning expected at age - uses immediate foundational skills", "d": "Child does not yet show functioning expected of a child of his or her age in any situation. Child uses immediate foundational skills, most or all of the time, across settings and situations. Immediate foundational skills are the skills upon which to build age-appropriate functioning.", "u": null, "notes": "concept: NI001509105749", "dep": null}, {"v": "04", "n": "Shows occasional age-appropriate functioning across settings and situations", "d": "Child shows occasional age-appropriate functioning across settings and situations. More functioning is not age-appropriate than age-appropriate.", "u": null, "notes": "concept: NI001509105750", "dep": null}, {"v": "05", "n": "Shows functioning expected at age some of the time and/or in some settings and situations", "d": "Child shows functioning expected for his or her age some of the time and/or in some settings and situations. Child's functioning is a mix of age-appropriate and not age-appropriate behaviors and skills.", "u": null, "notes": "concept: NI001509105751", "dep": null}, {"v": "06", "n": "Functioning generally is considered appropriate for age but there are some significant concerns", "d": "Child's functioning generally is considered appropriate for his or her age but there are some significant concerns about the child's functioning in this outcome area. These concerns are substantial enough to suggest monitoring or possible additional support.", "u": null, "notes": "concept: NI001509105752", "dep": null}, {"v": "07", "n": "Shows functioning expected for age in all or almost all everyday situations", "d": "Child shows functioning expected for his or her age in all or almost all everyday situations that are part of the child's life. Functioning is considered appropriate for his or her age.", "u": null, "notes": "concept: NI001509105753", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('ProfessionalDevelopmentActivityTargetAudience', 'A categorization of the audience for which the professional development activity is intended.', NULL, 'scheme: C001492', NULL, $j$[{"v": "AdministrativeSupportStaff", "n": "Administrative Support Staff", "d": "Staff members who provide direct support to administrators, business office support, data processing, or support of the teaching and administrative duties of the office of the principal or department chairpersons, including clerical staff and secretaries.", "u": null, "notes": "concept: NI001492115195", "dep": null}, {"v": "Administrators", "n": "Administrators", "d": "Executive officers or managers of education agencies or institutions, including superintendents, deputies, and assistant superintendents; other persons with district-wide responsibilities: e.g., business managers, administrative assistants, and professional instructional support staff. In addition, staff members whose activities are concerned with directing and managing the operation of a particular school including principals, assistant principals, and other assistants; persons who supervise school operations, assign duties to staff members, supervise and maintain the records of the school, and coordinate school instructional activities with those of the education agency, including department chairpersons.", "u": null, "notes": "concept: NI001492115200", "dep": null}, {"v": "AllOtherSupportStaff", "n": "All Other Support Staff", "d": "Support staff not reported in instructional or student support. Other support staff includes employees such as data processing, health, plant and equipment maintenance, bus drivers, security, and food service workers.", "u": null, "notes": "concept: NI001492115235", "dep": null}, {"v": "BehavioralSpecialists", "n": "Behavioral Specialists", "d": "Behavioral Specialists", "u": null, "notes": "concept: NI001492115350", "dep": null}, {"v": "ELAssistantTeachers", "n": "Early Leaning Assistant Teachers", "d": "Assistant Teachers of general level instruction and/or services delivery classified by state and local practice from birth to Kindergarten.", "u": null, "notes": "concept: NI001492115629", "dep": null}, {"v": "ElementaryTeachers", "n": "Elementary Teachers", "d": "Teachers of general level instruction classified by state and local practice as elementary and composed of any span of grades not above grade 8.", "u": null, "notes": "concept: NI001492115631", "dep": null}, {"v": "ELTeachers", "n": "Early Learning Teachers", "d": "Teachers of general level instruction and/or service delivery classified by state and local practice from birth to Kindergarten.", "u": null, "notes": "concept: NI001492115639", "dep": null}, {"v": "FamilyServiceWorkers", "n": "Family Service Workers", "d": "Professional staff members assigned specific duties related to staff providing in-home and other services (including needs assessment, development of service plans, family advocacy, and coordination of service delivery) to families of children participating in early care and education programs.", "u": null, "notes": "concept: NI001492115718", "dep": null}, {"v": "HealthSpecialists", "n": "Health Specialists", "d": "Professional staff members or supervisors assigned specific duties related to providing any Health services that are not specific to mental health.", "u": null, "notes": "concept: NI001492115841", "dep": null}, {"v": "HomeVisitors", "n": "Home Visitors", "d": "Professional staff members assigned specific duties related to visiting a child or pregnant woman's home for the purpose of assisting parents in fostering the growth and development of their child.", "u": null, "notes": "concept: NI001492115873", "dep": null}, {"v": "InstructionalCoordinators", "n": "Instructional Coordinators", "d": "Staff supervising instructional programs including professional staff members or supervisors in an early learning program assigned specific duties related to instruction , or supervisors at a school district or sub-district level including curriculum coordinators or supervisors; in-service training staff; Title I supervisors; home economics supervisors; educational television staff; coordinators and supervisors of audiovisual services; and staff engaged in development of computer-assisted instruction.", "u": null, "notes": "concept: NI001492115940", "dep": null}, {"v": "KindergartenTeachers", "n": "Kindergarten Teachers", "d": "Teachers of a group or class that is part of a public school program and is taught during the year preceding the first grade.", "u": null, "notes": "concept: NI001492115992", "dep": null}, {"v": "LibraryMediaSpecialists", "n": "Librarians/Media Specialists", "d": "A professional staff member or supervisor assigned specific duties and school time for professional library and media service activities. Activities include: selecting, acquiring, preparing, cataloging, and circulating books and other printed materials; planning the use of library and media services by students, teachers and other members of the instructional staff; and guiding individuals in their use of media services and library materials, (whether maintained separately or as part of an instructional materials center).", "u": null, "notes": "concept: NI001492116030", "dep": null}, {"v": "LibraryMediaSupportStaff", "n": "Library/Media Support Staff", "d": "Staff members who render other library or media services, such as preparing, caring for, and making available to members of the instructional staff the equipment, films, filmstrips, transparencies, tapes, TV programs, and similar materials (whether maintained separately as part of an instructional materials center).", "u": null, "notes": "concept: NI001492116031", "dep": null}, {"v": "MentalHealthSpecialists", "n": "Mental Health Specialists", "d": "Professional staff members or supervisors assigned specific duties related to Mental Health.", "u": null, "notes": "concept: NI001492116098", "dep": null}, {"v": "NutritionSpecialists", "n": "Nutrition Specialists", "d": "Professional staff members or supervisors assigned specific duties related to Nutrition.", "u": null, "notes": "concept: NI001492116295", "dep": null}, {"v": "Other", "n": "Other", "d": "The professional development activity is intended for an audience category not yet defined in CEDS.", "u": null, "notes": "concept: NI001492116401", "dep": null}, {"v": "Paraprofessionals", "n": "Paraprofessionals", "d": "Paraprofessionals are employees who provide instructional support, including those who: (1) provide one-on-one tutoring if such tutoring is scheduled at a time when a student would not otherwise receive instruction from a teacher, (2) assist with classroom management, such as organizing instructional and other materials, (3) provide instructional assistance in a computer laboratory, (4) conduct parental involvement activities, (5) provide support in a library or media center, (6) act as a translator, or (7) provide instructional support services under the direct supervision of a teacher.", "u": null, "notes": "concept: NI001492116481", "dep": null}, {"v": "PartCEarlyInterventionists", "n": "Part C Early Interventionists", "d": "Professional staff members employed to provide early intervention services to infants and toddlers with disabilities or at-risk of experiencing a substantial developmental delay as defined by Part C of the Individuals with Disabilities Education Act (IDEA): The Early Intervention Program for Infants and Toddlers with Disabilities.", "u": null, "notes": "concept: NI001492116492", "dep": null}, {"v": "PartCServiceCoordinators", "n": "Part C Service Coordinators", "d": "Professional staff members employed to coordinate early intervention services to infants and toddlers with disabilities or at-risk of experiencing a substantial developmental delay as defined by Part C of the Individuals with Disabilities Education Act (IDEA): The Early Intervention Program for Infants and Toddlers with Disabilities.", "u": null, "notes": "concept: NI001492116494", "dep": null}, {"v": "SchoolCounselors", "n": "School Counselors", "d": "Professional staff members assigned specific duties and school time for any of the following activities: counseling with students and parents, consulting with other staff members on learning problems, evaluating student abilities, assisting students in making education and career choices, assisting students in personal and social development, providing referral assistance, and/or working with other staff members in planning and conducting guidance programs for students. School counselors may be reported by elementary and secondary level when that information is available.", "u": null, "notes": "concept: NI001492116808", "dep": null}, {"v": "SecondaryTeachers", "n": "Secondary Teachers", "d": "Teachers of a general level of instruction classified by state and local practice as secondary and composed of any span of grades beginning with the next grade following the elementary grades and ending with or below grade 12.", "u": null, "notes": "concept: NI001492116834", "dep": null}, {"v": "SocialWorkers", "n": "Social Workers", "d": "Social workers assist people by helping them cope with and solve issues in their everyday lives, such as family and personal problems and dealing with relationships.", "u": null, "notes": "concept: NI001492116874", "dep": null}, {"v": "SpecialEducationTeachers", "n": "Special Education Teachers", "d": "Special Education teachers include teachers employed to provide special education services to children with disabilities, including preschool teachers, itinerant/consulting teachers, and home/hospital teachers. This count should include teachers of children with disabilities in separate schools and facilities.", "u": null, "notes": "concept: NI001492116894", "dep": null}, {"v": "SpecialNeedsSpecialists", "n": "Special Needs Specialists", "d": "Professional staff members or supervisors assigned specific duties related to special needs learners.", "u": null, "notes": "concept: NI001492116899", "dep": null}, {"v": "StudentSupportServicesStaff", "n": "Student Support Services Staff", "d": "Professional and supervisory staff providing non-instructional services to students including attendance officers; staff providing health, psychology, speech pathology, audiology, or social services; and supervisors of the preceding staff and of health, transportation, and food service workers.", "u": null, "notes": "concept: NI001492116964", "dep": null}, {"v": "UngradedTeachers", "n": "Ungraded Teachers", "d": "Teachers of classes or programs to which students are assigned without standard grade designation.", "u": null, "notes": "concept: NI001492117111", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AccreditationAgency', 'The agency that accredited a program.', NULL, 'scheme: C000982', NULL, $j$[{"v": "COA", "n": "Council on Accreditation", "d": "Council on Accreditation", "u": null, "notes": "concept: NI000982115446", "dep": null}, {"v": "NAC", "n": "National Accreditation Commission", "d": "National Accreditation Commission", "u": null, "notes": "concept: NI000982116175", "dep": null}, {"v": "NAEYC", "n": "National Association for the Education of Young Children", "d": "National Association for the Education of Young Children", "u": null, "notes": "concept: NI000982116176", "dep": null}, {"v": "NAFCC", "n": "National Association for Family Child Care", "d": "National Association for Family Child Care", "u": null, "notes": "concept: NI000982116177", "dep": null}, {"v": "NECPA", "n": "National Early Childhood Program Accreditation", "d": "National Early Childhood Program Accreditation", "u": null, "notes": "concept: NI000982116193", "dep": null}, {"v": "NotAccredited", "n": "Not accredited", "d": "Not accredited", "u": null, "notes": "concept: NI000982116255", "dep": null}, {"v": "Other", "n": "Other Accreditation Agency", "d": "Other Accreditation Agency", "u": null, "notes": "concept: NI000982116346", "dep": null}, {"v": "SACS", "n": "Southern Association of Colleges and Schools", "d": "Southern Association of Colleges and Schools", "u": null, "notes": "concept: NI000982116782", "dep": null}]$j$::jsonb);
