SELECT public.ceds_tmp_valueset('IndividualizedProgramPlannedServiceFrequency', 'The frequency that a service is planned to be provided.', NULL, 'scheme: C001519', NULL, $j$[{"v": "Annually", "n": "Annually", "d": "The service is planned to be provided Annually.", "u": null, "notes": "concept: NI001519115249", "dep": null}, {"v": "Bimonthly", "n": "Bimonthly", "d": "The service is planned to be provided Bimonthly.", "u": null, "notes": "concept: NI001519115362", "dep": null}, {"v": "Biweekly", "n": "Biweekly", "d": "The service is planned to be provided Biweekly.", "u": null, "notes": "concept: NI001519115365", "dep": null}, {"v": "Daily", "n": "Daily", "d": "The service is planned to be provided Daily.", "u": null, "notes": "concept: NI001519115530", "dep": null}, {"v": "Monthly", "n": "Monthly", "d": "The service is planned to be provided Monthly.", "u": null, "notes": "concept: NI001519116140", "dep": null}, {"v": "Other", "n": "Other", "d": "The service is planned to be provided at a frequency not yet defined in CEDS.", "u": null, "notes": "concept: NI001519116414", "dep": null}, {"v": "Quarterly", "n": "Quarterly", "d": "The service is planned to be provided Quarterly.", "u": null, "notes": "concept: NI001519116674", "dep": null}, {"v": "Semiannually", "n": "Semiannually", "d": "The service is planned to be provided Semiannually.", "u": null, "notes": "concept: NI001519116846", "dep": null}, {"v": "Weekly", "n": "Weekly", "d": "The service is planned to be provided Weekly.", "u": null, "notes": "concept: NI001519117178", "dep": null}]$j$::jsonb);
