SELECT public.ceds_tmp_valueset('ReasonForDelayOfTransitionConference', 'The reasons for the delay of a transition conference.', NULL, 'scheme: C001521', NULL, $j$[{"v": "BeyondProgramControl", "n": "Other beyond the control of the program", "d": "The reasons for the delay of a transition conference is other, beyond the control of the program.", "u": null, "notes": "concept: NI001521115359", "dep": null}, {"v": "Family", "n": "Family", "d": "The reasons for the delay of a transition conference is attributed to the family.", "u": null, "notes": "concept: NI001521115711", "dep": null}, {"v": "Program", "n": "Program", "d": "The reasons for the delay of a transition conference is attributed to the program.", "u": null, "notes": "concept: NI001521116630", "dep": null}, {"v": "Promotion", "n": "Promotion or advancement", "d": "The reasons for the delay of a transition conference is attributed to promotion or advancement.", "u": null, "notes": "concept: NI001521116638", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AdultEducationInstructionalProgramType', 'The type of instructional program in which an adult is enrolled.', NULL, 'scheme: C001077', NULL, $j$[{"v": "ABE", "n": "Adult Basic Education", "d": "A program of academic instruction and education services below the secondary level that increases an individual's ability to read, write, and speak in English and perform mathematics necessary to attain a secondary school diploma or its recognized equivalent, transition to postsecondary education or training, and obtain employment.", "u": null, "notes": "concept: NI001077151995", "dep": null}, {"v": "ASE", "n": "Adult Secondary Education", "d": "A program of academic instruction and education services at the secondary level that increases an individual's ability to read, write, and perform mathematics necessary to attain a secondary school diploma or its recognized equivalent, transition to postsecondary education or training, and obtain employment.", "u": null, "notes": "concept: NI001077151997", "dep": null}, {"v": "ELA", "n": "English as a Second Language/English Language Acquisition Program", "d": "A program of instruction designed to help eligible individuals who are English language learners (ELLs) achieve competence in reading, writing, speaking, and comprehension of the English language, and that leads to attainment of a secondary school diploma or its recognized equivalent and transition to postsecondary education and training or employment.", "u": null, "notes": "concept: NI001077151998", "dep": null}, {"v": "IEL", "n": "Integrated English Literacy and Civics Education", "d": "A program of instruction funded under WIOA, Section 243, which includes education services provided to English language learners who are adults, including professionals with degrees and credentials in their native countries, that enables such adults to achieve competency in the English language and acquire the basic and more advanced skills needed to function effectively as parents, workers, and citizens in the United States. It includes instruction in literacy and English language acquisition and instruction on the rights and responsibilities of citizenship and civic participation and may include workforce training. In addition, the program must be provided in combination with Integrated Education and Training (IET).", "u": null, "notes": "concept: NI001077151999", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AdultEducationProviderType', 'The type of institution responsible for providing adult education instructional services.', NULL, 'scheme: C001078', NULL, $j$[{"v": "CommunityBasedOrganization", "n": "Community-Based Organization", "d": "Community-Based Organization is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078115466", "dep": null}, {"v": "CorrectionalInstitution", "n": "Correctional Institution", "d": "Correctional Institution is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078115503", "dep": null}, {"v": "LEA", "n": "Local Education Agency", "d": "Local Education Agency is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116011", "dep": null}, {"v": "Library", "n": "Library", "d": "Library is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116029", "dep": null}, {"v": "Other", "n": "Other", "d": "Other is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116372", "dep": null}, {"v": "OtherAgency", "n": "Other state or local government agency", "d": "Other state or local government agency is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116432", "dep": null}, {"v": "OtherInstitution", "n": "Other Institution", "d": "Other Institution is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116448", "dep": null}, {"v": "PostsecondaryInstitution", "n": "Postsecondary Institution", "d": "Postsecondary Institution is specified as the type of institution responsible for providing adult education instructional services.", "u": null, "notes": "concept: NI001078116570", "dep": null}]$j$::jsonb);
