SELECT public.ceds_tmp_valueset('SCEDCourseSubjectArea', 'The intended major subject area of the education course.', NULL, 'scheme: C001518', NULL, $j$[{"v": "01", "n": "English Language and Literature", "d": "English Language and Literature is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118404", "dep": null}, {"v": "02", "n": "Mathematics", "d": "Mathematics is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118405", "dep": null}, {"v": "03", "n": "Life and Physical Sciences", "d": "Life and Physical Sciences is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118406", "dep": null}, {"v": "04", "n": "Social Sciences and History", "d": "Social Sciences and History is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118407", "dep": null}, {"v": "05", "n": "Visual and Performing Arts", "d": "Visual and Performing Arts is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118408", "dep": null}, {"v": "07", "n": "Religious Education and Theology", "d": "Religious Education and Theology is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118410", "dep": null}, {"v": "08", "n": "Physical, Health, and Safety Education", "d": "Physical, Health, and Safety Education is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118411", "dep": null}, {"v": "09", "n": "Military Science", "d": "Military Science is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118412", "dep": null}, {"v": "10", "n": "Information Technology", "d": "Information Technology is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118413", "dep": null}, {"v": "11", "n": "Communication and Audio/Visual Technology", "d": "Communication and Audio/Visual Technology is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118414", "dep": null}, {"v": "12", "n": "Business and Marketing", "d": "Business and Marketing is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118415", "dep": null}, {"v": "13", "n": "Manufacturing", "d": "Manufacturing is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118416", "dep": null}, {"v": "14", "n": "Health Care Sciences", "d": "Health Care Sciences is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118417", "dep": null}, {"v": "15", "n": "Public, Protective, and Government Service", "d": "Public, Protective, and Government Service is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118418", "dep": null}, {"v": "16", "n": "Hospitality and Tourism", "d": "Hospitality and Tourism is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118419", "dep": null}, {"v": "17", "n": "Architecture and Construction", "d": "Architecture and Construction is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118420", "dep": null}, {"v": "18", "n": "Agriculture, Food, and Natural Resources", "d": "Agriculture, Food, and Natural Resources is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118421", "dep": null}, {"v": "19", "n": "Human Services", "d": "Human Services is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118422", "dep": null}, {"v": "20", "n": "Transportation, Distribution and Logistics", "d": "Transportation, Distribution and Logistics is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118423", "dep": null}, {"v": "21", "n": "Engineering and Technology", "d": "Engineering and Technology is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118424", "dep": null}, {"v": "22", "n": "Miscellaneous", "d": "Miscellaneous is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118425", "dep": null}, {"v": "23", "n": "Non-Subject-Specific", "d": "Non-Subject-Specific is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118426", "dep": null}, {"v": "24", "n": "World Languages", "d": "World Languages is the intended major subject area of the education course.", "u": null, "notes": "concept: NI001518118427", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('SCEDCourseCode', 'The five-digit SCED code. The first two-digits of the code represent the Course Subject Area and the next three digits identify the course number. These identifiers are fairly general but provide enough specificity to identify the course''s topic and to distinguish it from other courses in that subject area.', NULL, 'scheme: C001517', NULL, $j$[{"v": "24394", "n": "Classical Hebrew IV", "d": "Classical Hebrew IV courses prepare students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Classical Hebrew IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Classical Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162954", "dep": null}, {"v": "24395", "n": "Classical Hebrew V", "d": "Classical Hebrew V courses prepare students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Classical Hebrew V courses promote students' understanding of the relationships among the products, practices, and perspectives of Classical Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162955", "dep": null}, {"v": "24396", "n": "Particular Topics in Classical Hebrew", "d": "Particular Topics in Classical Hebrew courses examine particular topics focused on Classical Hebrew language or culture, such as drama, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162956", "dep": null}, {"v": "24401", "n": "Chinese Languages Immersion (prior-to-secondary)", "d": "Chinese Languages Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Chinese languages and grade-specific content using Chinese languages as the language(s) of instruction. Chinese Languages Immersion courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Chinese language-speaking cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162957", "dep": null}, {"v": "24402", "n": "Chinese Languages I", "d": "Designed to introduce students to Chinese languages and culture, Chinese Languages I courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Chinese language-speaking cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162958", "dep": null}, {"v": "24403", "n": "Chinese Languages II", "d": "Chinese Languages II courses build upon skills developed in Chinese Languages I, preparing students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Chinese Languages II courses introduce the relationships among the products, practices, and perspectives of Chinese language-speaking cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162959", "dep": null}, {"v": "24404", "n": "Chinese Languages III", "d": "Chinese Languages III courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Chinese language-speaking countries and cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162960", "dep": null}, {"v": "24405", "n": "Chinese Languages IV", "d": "Chinese Languages IV courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Chinese Languages IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Chinese language-speaking countries and cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162961", "dep": null}, {"v": "24406", "n": "Chinese Languages V", "d": "Chinese Languages V courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Chinese Languages V courses promote students' understanding of the relationships among the products, practices, and perspectives of Chinese language-speaking countries and cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162962", "dep": null}, {"v": "24407", "n": "Chinese Languages for Native Speakers", "d": "Chinese Languages for Native Speakers courses prepare native and heritage speakers to communicate in Chinese languages in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Chinese Languages for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Chinese language-speaking world. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162963", "dep": null}, {"v": "24408", "n": "Chinese Languages Field Experience", "d": "Chinese Languages Field Experience courses place students in environments in which they interact with native Chinese languages speakers, typically in settings where a Chinese language is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162964", "dep": null}, {"v": "24417", "n": "IB Language A: Language and Literature�Chinese Languages", "d": "IB Language A: Language and Literature�Chinese Languages courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Chinese languages in an academic context. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162965", "dep": null}, {"v": "24418", "n": "IB Language Ab Initio�Chinese Languages", "d": "IB Language Ab Initio�Chinese Languages courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162966", "dep": null}, {"v": "24409", "n": "Chinese Languages Conversation and Culture", "d": "Chinese Languages Conversation and Culture courses provide students with an introduction to the Chinese languages and the culture(s) of Chinese language-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162967", "dep": null}, {"v": "24410", "n": "Chinese Languages Literature", "d": "Chinese Languages Literature courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Chinese languages. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Chinese cultures into literature, and exploring interdisciplinary connections. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162968", "dep": null}, {"v": "24411", "n": "Particular Topics in Chinese Languages", "d": "Particular Topics in Chinese Languages courses examine particular topics focused on Chinese languages or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162969", "dep": null}, {"v": "24412", "n": "IB Language A: Literature�Chinese Languages", "d": "IB Language A: Literature�Chinese Languages courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Chinese languages in an academic context and is intended for students with native or near-native fluency in the languages. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162970", "dep": null}, {"v": "24413", "n": "IB Language B�Chinese Languages", "d": "IB Language B�Chinese Languages courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language). These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162971", "dep": null}, {"v": "24414", "n": "AP Chinese Languages: Language and Culture", "d": "Designed by the College Board to parallel fourth semester college-level courses in Mandarin Chinese language, AP Chinese Languages: Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in Chinese languages, both orally and in writing. These courses also help students understand and interpret written and spoken Chinese languages. In addition, students explore the culture of Chinese language-speaking people in historical and contemporary contexts. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162972", "dep": null}, {"v": "24416", "n": "IB Language B (Chinese Languages), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Chinese Languages), Middle Years Program courses enable students to gain competence in modern Chinese languages and encourage respect for and understanding of other languages and cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517162973", "dep": null}, {"v": "24455", "n": "Japanese IV", "d": "Japanese IV courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Japanese IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Japanese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162974", "dep": null}, {"v": "24464", "n": "AP Japanese Language and Culture", "d": "Designed by the College Board to parallel third-year college-level courses in Japanese language, AP Japanese Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in Japanese, both orally and in writing. These courses also help students understand and interpret written and spoken Japanese. In addition, students explore the culture of Japanese-speaking people in historical and contemporary contexts.", "u": null, "notes": "concept: NI001517162975", "dep": null}, {"v": "24466", "n": "IB Language B (Japanese), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Japanese), Middle Years Program courses enable students to gain competence in modern Japanese and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162976", "dep": null}, {"v": "24456", "n": "Japanese V", "d": "Japanese V courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Japanese V courses promote students' understanding of the relationships among the products, practices, and perspectives of Japanese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162977", "dep": null}, {"v": "24449", "n": "Chinese�Other", "d": "Other Chinese courses", "u": null, "notes": "concept: NI001517162978", "dep": null}, {"v": "24450", "n": "Japanese for Young Learners (prior-to-secondary)", "d": "Japanese for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Japanese and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Japanese-speaking cultures.", "u": null, "notes": "concept: NI001517162979", "dep": null}, {"v": "24451", "n": "Japanese Immersion (prior-to-secondary)", "d": "Japanese Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Japanese and grade-specific content using Japanese as the language of instruction. Japanese Immersion courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Japanese-speaking cultures.", "u": null, "notes": "concept: NI001517162980", "dep": null}, {"v": "24452", "n": "Japanese I", "d": "Designed to introduce students to Japanese language and culture, Japanese I courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Japanese-speaking cultures.", "u": null, "notes": "concept: NI001517162981", "dep": null}, {"v": "24453", "n": "Japanese II", "d": "Japanese II courses build upon skills developed in Japanese I, preparing students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Japanese II courses introduce the relationships among the products, practices, and perspectives of Japanese-speaking cultures.", "u": null, "notes": "concept: NI001517162982", "dep": null}, {"v": "24454", "n": "Japanese III", "d": "Japanese III courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Japanese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162983", "dep": null}, {"v": "24457", "n": "Japanese for Native Speakers", "d": "Japanese for Native Speakers courses prepare native and heritage speakers to communicate in Japanese in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Japanese for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Japanese-speaking world.", "u": null, "notes": "concept: NI001517162984", "dep": null}, {"v": "24458", "n": "Japanese Field Experience", "d": "Japanese Field Experience courses place students in environments in which they interact with native Japanese speakers, typically in settings where Japanese is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162985", "dep": null}, {"v": "24459", "n": "Japanese Conversation and Culture", "d": "Japanese Conversation and Culture courses provide students with an introduction to the Japanese language and the culture(s) of Japanese-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162986", "dep": null}, {"v": "24460", "n": "Japanese Literature", "d": "Japanese Literature courses prepare students to communicate authentically in Japanese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Japanese. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Japanese cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162987", "dep": null}, {"v": "02033", "n": "Mathematics (grade 3)", "d": "Mathematics (grade 3) courses typically emphasize number, operation, and quantitative reasoning; patterns, relationships, and algebraic thinking; geometry and spatial reasoning; and measurement. These courses often require students to improve their numerical fluency, adding multiplication and division to addition and subtraction operations, using whole numbers and parts (quarters, thirds, halves), develop an understanding of unitizing (unit fractions), and estimation. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163266", "dep": null}, {"v": "02034", "n": "Mathematics (grade 4)", "d": "Mathematics (grade 4) courses typically emphasize number, operation, and quantitative reasoning; patterns, relationships, and algebraic thinking; geometry and spatial reasoning; and measurement. Course content may include activities that help students increase operational fluency, make connections between abstract symbols and concrete events or concepts, build an understanding of fraction equivalence, order, and decimal notation for fractions, or present conclusions based on data. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163267", "dep": null}, {"v": "02035", "n": "Mathematics (grade 5)", "d": "Mathematics (grade 5) courses typically emphasize number, operation, and quantitative reasoning; patterns, relationships, and algebraic thinking; geometry and spatial reasoning; and measurement, including exploring the concept of volume. Course content may include activities that help students increase operational fluency, make connections between abstract symbols and concrete events or concepts, or present their mathematical reasoning. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163268", "dep": null}, {"v": "02036", "n": "Mathematics (grade 6)", "d": "Mathematics (grade 6) courses typically emphasize skills in numerical operations (including basic operations and their proper order); ratios and proportional relationships; patterns; simple functions; geometry; and concepts of data analysis, including statistics and probability. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163269", "dep": null}, {"v": "02037", "n": "Mathematics (grade 7)", "d": "Mathematics (grade 7) courses typically emphasize proficiency in skills involving numbers and operations; ratios and proportional relationships; patterns; functions; algebraic formulas; geometry; and concepts of data analysis, including statistics and probability. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163270", "dep": null}, {"v": "02038", "n": "Mathematics (grade 8)", "d": "Mathematics (grade 8) courses typically emphasize proficiency in skills involving numbers and operations, measurement, patterns, simple functions, algebra, geometry, statistics, and probability. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163271", "dep": null}, {"v": "02039", "n": "Mathematics�General", "d": "Mathematics�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Mathematics, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163272", "dep": null}, {"v": "02054", "n": "Algebra I�Part 2", "d": "The second part in a multipart sequence of Algebra I. This course generally covers the same topics as the second semester of Algebra I, including the study of properties of the real number system and operations, evaluating rational algebraic expressions, solving and graphing first-degree equations and inequalities, translating word problems into equations, operations with and factoring of polynomials, and solving quadratics. Specific content depends upon state standards.", "u": null, "notes": "concept: NI001517163273", "dep": null}, {"v": "02079", "n": "Geometry�Other", "d": "Other Geometry courses.", "u": null, "notes": "concept: NI001517163274", "dep": null}, {"v": "02101", "n": "Number Theory", "d": "Number Theory courses review the properties and uses of integers and prime numbers, and extend this information to congruencies and divisibility.", "u": null, "notes": "concept: NI001517163275", "dep": null}, {"v": "02102", "n": "Discrete Mathematics", "d": "Discrete Mathematics courses include the study of topics such as number theory, discrete probability, set theory, symbolic logic, Boolean algebra, combinatorics, recursion, basic algebraic structures and graph theory.", "u": null, "notes": "concept: NI001517163276", "dep": null}, {"v": "02103", "n": "Trigonometry", "d": "Trigonometry courses prepare students for eventual work in calculus and typically include the following topics: trigonometric and circular functions; their inverses and graphs; relations among the parts of a triangle; trigonometric identities and equations; solutions of right and oblique triangles; the use of the unit circle; modeling trigonometric data; and complex numbers.", "u": null, "notes": "concept: NI001517163277", "dep": null}, {"v": "02104", "n": "Mathematic Analysis", "d": "Mathematic Analysis courses include the study of polynomial, logarithmic, exponential, and rational functions and their graphs; vectors; set theory; Boolean algebra and symbolic logic; mathematical induction; matrix algebra; sequences and series; and limits and continuity. They may also include some study of trigonometry and/or pre-calculus topics.", "u": null, "notes": "concept: NI001517163278", "dep": null}, {"v": "02055", "n": "Transition Algebra", "d": "Transition Algebra courses review and extend algebra and geometry concepts for students who have already taken Algebra I and Geometry. Transition Algebra courses include a review of such topics as properties and operations of real numbers; evaluation of rational algebraic expressions; solutions and graphs of first-degree equations and inequalities; translation of word problems into equations; operations with and factoring of polynomials; quadratics; properties of plane and solid figures; rules of congruence and similarity; coordinate geometry including lines, segments, and circles in the coordinate plane; and angle measurement in triangles including trigonometric ratios.", "u": null, "notes": "concept: NI001517163279", "dep": null}, {"v": "02056", "n": "Algebra II", "d": "Algebra II course topics typically include developing an understanding of the relationships between the symbolic, graphic, tabular and verbal representations of functions; utilizing the various representations to interpret function behavior and solve equations; operations with rational and irrational expressions; factoring of rational expressions; in-depth study of linear equations and inequalities; quadratic equations; solving systems of linear and quadratic equations; graphing of constant, linear, and quadratic equations; properties of higher-degree equations; exponential functions; inverse functions; statistical modeling; modeling linear and quadratic data; and operations with rational and irrational exponents.", "u": null, "notes": "concept: NI001517163280", "dep": null}, {"v": "02057", "n": "Algebra III", "d": "Algebra III courses review and extend algebraic concepts for students who have already taken Algebra II. Course topics include (but are not limited to) applying an understanding of the relationships between the symbolic, graphic, tabular and verbal representations of functions to additional families of functions; utilizing the various representations to interpret function behavior, solve equations and understand compositions of functions; operations with rational and irrational expressions, factoring of rational expressions, linear equations and inequalities, quadratic equations, solving systems of linear and quadratic equations, properties of higher-degree equations, and operations with rational and irrational exponents. The courses may introduce topics in discrete mathematics, elementary probability and statistics; matrices and determinants; logarithmic and exponential functions; inverse functions; step functions; piecewise defined functions; statistical modeling; creating functions to model apparent trends in data; modeling linear, quadratic and exponential data; and sequences and series.", "u": null, "notes": "concept: NI001517163281", "dep": null}, {"v": "02058", "n": "Particular Topics in Algebra", "d": "These courses examine a specific topic in algebra, such as linear equations or rational numbers, rather than provide an overview of algebra concepts.", "u": null, "notes": "concept: NI001517163282", "dep": null}, {"v": "02062", "n": "Integrated Mathematics I", "d": "Integrated Mathematics I courses emphasize proficiency in skills involving numbers and operations, algebra, geometry, statistics, mathematical modeling, and probability. These courses are offered as the first course in a 3- or 4-year sequence of college-preparatory mathematics courses that replace traditional Algebra 1, Geometry, and Algebra 2 courses.", "u": null, "notes": "concept: NI001517163283", "dep": null}, {"v": "02063", "n": "Integrated Mathematics II", "d": "Integrated Mathematics II courses emphasize proficiency in skills involving numbers and operations, algebra, geometry, statistics, mathematical modeling, and probability. These courses are offered as the second course in a 3- or 4-year sequence of college-preparatory mathematics courses that replace traditional Algebra 1, Geometry, and Algebra 2 courses.", "u": null, "notes": "concept: NI001517163284", "dep": null}, {"v": "02064", "n": "Integrated Mathematics III", "d": "Integrated Mathematics III courses emphasize proficiency in skills involving numbers and operations, algebra, geometry, statistics, mathematical modeling, and probability. These courses are offered as the third course in a 3- or 4-year sequence of college-preparatory mathematics courses that replace traditional Algebra 1, Geometry, and Algebra 2 courses.", "u": null, "notes": "concept: NI001517163285", "dep": null}, {"v": "02065", "n": "Integrated Mathematics IV", "d": "Integrated Mathematics IV courses emphasize proficiency in skills involving numbers and operations, algebra, geometry, statistics, mathematical modeling, and probability. These courses are offered as the fourth course in a 4-year sequence of college-preparatory mathematics courses that replace traditional Algebra 1, Geometry, and Algebra 2 courses.", "u": null, "notes": "concept: NI001517163286", "dep": null}, {"v": "02069", "n": "Algebra�Other", "d": "Other Algebra courses.", "u": null, "notes": "concept: NI001517163287", "dep": null}, {"v": "02071", "n": "Informal Geometry", "d": "Informal Geometry courses emphasize a practical approach to the study of geometry and deemphasize an abstract, formal approach. Topics typically include properties of and work with plane and solid figures; inductive methods of reasoning and use of logic; concepts of congruence, similarity, parallelism, perpendicularity, and proportion; and rules of angle measurement in triangles, quadrilaterals, vertical angles, lines intersected by a transversal, etc.", "u": null, "notes": "concept: NI001517163288", "dep": null}, {"v": "02072", "n": "Geometry", "d": "Geometry courses, emphasizing an abstract, formal approach to the study of geometry, typically include topics such as properties of plane and solid figures; deductive methods of reasoning and use of logic; geometry as an axiomatic system including the study of postulates, theorems, and formal proofs; concepts of congruence, similarity, parallelism, perpendicularity, and proportion; and rules of angle measurement in triangles, quadrilaterals, vertical angles, lines intersected by a transversal, etc.", "u": null, "notes": "concept: NI001517163289", "dep": null}, {"v": "02073", "n": "Analytic Geometry", "d": "Analytic Geometry courses include the study of the nature and intersection of lines and planes in space, including vectors, the polar coordinate system, equations and graphs of conic sections, rotations and transformations, and parametric equations.", "u": null, "notes": "concept: NI001517163290", "dep": null}, {"v": "02074", "n": "Principles of Algebra and Geometry", "d": "Principles of Algebra and Geometry courses combine the study of some pre-algebra and algebra topics with introductory geometry topics. These courses include the study of formulas, algebraic expressions, first-degree equations and inequalities, the rectangular coordinate system, area, perimeter, and volume of geometric figures, surface area of geometric figures, and properties of triangles and circles.", "u": null, "notes": "concept: NI001517163291", "dep": null}, {"v": "02075", "n": "Particular Topics in Geometry", "d": "These courses examine specific topics in geometry, such as solid or technical geometry, rather than provide a general study of the field of geometry.", "u": null, "notes": "concept: NI001517163292", "dep": null}, {"v": "02105", "n": "Trigonometry/Mathematic Analysis", "d": "Covering topics of both Trigonometry and Mathematic Analysis, these courses prepare students for eventual work in calculus. Topics typically include the study of trigonometric and circular functions, inverses, and graphs; trigonometric identities and equations; solutions of right and oblique triangles; complex numbers; numerical tables; polynomial, logarithmic, exponential, and rational functions and their graphs; vectors; set theory; Boolean algebra and symbolic logic; mathematical induction; matrix algebra; sequences and series; modeling linear, quadratic, exponential, and trigonometric data; and limits and continuity.", "u": null, "notes": "concept: NI001517163293", "dep": null}, {"v": "02106", "n": "Trigonometry/Algebra", "d": "Trigonometry/Algebra courses combine trigonometry and advanced algebra topics, and are usually intended for students who have attained Algebra I and Geometry objectives. Topics typically include trigonometric and circular functions, inverses, and graphs; trigonometric identities and equations; solutions of right and oblique triangles; complex numbers; numerical tables; field properties and theorems; set theory; operations with rational and irrational expressions; factoring of rational expressions; in-depth study of linear equations and inequalities; quadratic equations; solving systems of linear and quadratic equations; graphing of constant, linear, and quadratic equations; modeling linear, quadratic, exponential, and trigonometric data; and properties of higher-degree equations.", "u": null, "notes": "concept: NI001517163294", "dep": null}, {"v": "02107", "n": "Trigonometry/Analytic Geometry", "d": "Covering topics of both Trigonometry and Analytic Geometry, these courses prepare students for eventual work in calculus. Topics typically include the study of trigonometric and circular functions, inverses, and graphs; trigonometric identities and equations; solutions of right and oblique triangles; complex numbers; numerical tables; vectors; the polar coordinate system; equations and graphs of conic sections; transformations; and parametric equations.", "u": null, "notes": "concept: NI001517163295", "dep": null}, {"v": "02108", "n": "Mathematic Analysis/Analytic Geometry", "d": "Covering topics from both Mathematic Analysis and Analytic Geometry, these courses prepare students for eventual work in calculus. Topics include the study of polynomial, logarithmic, exponential, and rational functions and their graphs; vectors; set theory; Boolean algebra and symbolic logic; mathematical induction; matrix algebra; sequences and series; and limits and continuity; the polar coordinate system; equations and graphs of conic sections; transformations; and parametric equations.", "u": null, "notes": "concept: NI001517163296", "dep": null}, {"v": "02109", "n": "Elementary Functions", "d": "Elementary Functions courses, while preparing students for eventual work in calculus, include the study of relations and functions, including polynomial, logarithmic, exponential, rational, trigonometric, and circular functions, and their inverses, graphs, and applications.", "u": null, "notes": "concept: NI001517163297", "dep": null}, {"v": "02110", "n": "Pre-Calculus", "d": "Pre-Calculus courses combine the study of Trigonometry, Elementary Functions, Analytic Geometry, and Mathematic Analysis topics as preparation for calculus. Topics typically include the study of complex numbers; polynomial, logarithmic, exponential, rational, trigonometric, and circular functions, and their relations, inverses and graphs; trigonometric identities and equations; solutions of right and oblique triangles; vectors; the polar coordinate system; conic sections; Boolean algebra and symbolic logic; mathematical induction; matrix algebra; sequences and series; modeling linear, quadratic, exponential, and trigonometric data; and limits and continuity.", "u": null, "notes": "concept: NI001517163298", "dep": null}, {"v": "02111", "n": "Linear Algebra", "d": "Linear Algebra courses include a study of matrices, vectors, tensors, and linear transformations and are typically intended for students who have attained pre-calculus objectives.", "u": null, "notes": "concept: NI001517163299", "dep": null}, {"v": "02112", "n": "Linear Programming", "d": "Linear Programming courses include a study of mathematical modeling and the simplex method to solve linear inequalities and are typically intended for students who have attained pre-calculus objectives.", "u": null, "notes": "concept: NI001517163300", "dep": null}, {"v": "02113", "n": "Abstract Algebra", "d": "Abstract Algebra courses include a study of the properties of the number system from an abstract perspective, including such topics as number fields (i.e., rational, real, and complex numbers), integral domains, rings, groups, polynomials, and the fundamental theorem of algebra. Abstract Algebra is typically geared towards students who have attained pre-calculus objectives.", "u": null, "notes": "concept: NI001517163301", "dep": null}, {"v": "02121", "n": "Calculus", "d": "Calculus courses include the study of derivatives, differentiation, integration, the definite and indefinite integral, and applications of calculus. Typically, students have previously attained knowledge of pre-calculus topics (some combination of trigonometry, elementary functions, analytic geometry, and mathematic analysis).", "u": null, "notes": "concept: NI001517163302", "dep": null}, {"v": "02122", "n": "Multivariate Calculus", "d": "Multivariate Calculus courses include the study of hyperbolic functions, improper integrals, directional directives, and multiple integration and its applications.", "u": null, "notes": "concept: NI001517163303", "dep": null}, {"v": "02123", "n": "Differential Calculus", "d": "Differential Calculus courses include the study of elementary differential equations including first- and higher-order differential equations, partial differential equations, linear equations, systems of linear equations, transformations, series solutions, numerical methods, boundary value problems, and existence theorems.", "u": null, "notes": "concept: NI001517163304", "dep": null}, {"v": "02124", "n": "AP Calculus AB", "d": "Following the College Board's suggested curriculum designed to parallel college-level calculus courses, AP Calculus AB provides students with an understanding of the concepts of calculus and experience with its methods and applications. These courses introduce calculus and include the following topics: functions, graphs, limits, and continuity; differential calculus (including definition, application, and computation of the derivative; derivative at a point; derivative as a function; and second derivatives); and integral calculus (including definite integrals and antidifferentiation).", "u": null, "notes": "concept: NI001517163305", "dep": null}, {"v": "05124", "n": "Technology/Electronic Music", "d": "Technology/Electronic Music courses emphasize current technology as a means to create, record, mix, and otherwise interact with music and music media. These courses focus on experimenting with electronic music technology as part of the process for creating music.", "u": null, "notes": "concept: NI001517163611", "dep": null}, {"v": "05128", "n": "Music (early childhood education)", "d": "Music (early childhood education) courses provide developmentally appropriate activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Specific course content conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163612", "dep": null}, {"v": "05109", "n": "Individual Technique�Instrumental Music", "d": "Individual Technique�Instrumental Music courses provide individuals with instruction in instrumental literature and techniques. These courses may be conducted either individually or in a small group; formal and informal performances are typically included as well as experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163613", "dep": null}, {"v": "05110", "n": "Chorus", "d": "Chorus courses develop students' vocal skills within the context of a large choral ensemble in which they perform a variety of styles of repertoire. These courses are designed to develop students' vocal techniques and their ability to sing parts and include experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163614", "dep": null}, {"v": "05111", "n": "Vocal Ensemble", "d": "Vocal Ensemble courses help students develop vocal techniques and refine their ability to sing parts in small ensembles (e.g., madrigal, barber shop, gospel). Course goals may include helping students develop their solo singing ability and emphasize one or several ensemble literature styles. These ensembles may include both instrumental and vocal music and include experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163615", "dep": null}, {"v": "05112", "n": "Individual Technique�Vocal Music", "d": "Individual Technique�Vocal Music courses provide instruction in and encourage the refinement of vocal techniques and repertoire other than the ability to sing in groups. These courses may be conducted individually or in small groups. Formal and informal performances may be part of the instructional program as well as experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163616", "dep": null}, {"v": "05113", "n": "Music Theory", "d": "Music Theory courses provide students with an understanding of the fundamentals of music and include the following topics: composition, arranging, analysis, aural development, and sight reading.", "u": null, "notes": "concept: NI001517163617", "dep": null}, {"v": "05114", "n": "AP Music Theory", "d": "AP Music Theory courses are designed to be the equivalent of a first-year music theory college course as specified by the College Board. AP Music Theory develops students' understanding of musical structure and compositional procedures. Usually intended for students who already possess performance-level skills, AP Music Theory courses extend and build upon students' knowledge of intervals, scales, chords, metric/rhythmic patterns, and the ways they interact in a composition. Musical notation, analysis, composition, and aural skills are important components of the course.", "u": null, "notes": "concept: NI001517163618", "dep": null}, {"v": "05115", "n": "IB Music", "d": "IB Music courses prepare students to take the International Baccalaureate Music exams. IB Music courses develop students' knowledge and understanding of music through study of musical perception, including study of musical elements, form and structure, notations, musical terminology and context. These courses include exploration of music from different places, cultures, and time periods. They also involve training in at least one of the following: creating, solo performing, and group performing.", "u": null, "notes": "concept: NI001517163619", "dep": null}, {"v": "05116", "n": "Music History/Appreciation", "d": "Music History/Appreciation courses survey different musical styles and periods with the intent of increasing students' understanding of music and its importance in relation to the human experience. Music History/Appreciation courses may focus on how various styles of music apply musical elements to create an expressive or aesthetic impact. Students also have the ability for informal music performance and creation within the classroom.", "u": null, "notes": "concept: NI001517163620", "dep": null}, {"v": "05117", "n": "Music History", "d": "Music History courses provide students with an understanding of music, its importance, and context in a selected range of historical periods and/or cultural styles. Students also have the ability for informal music performance and creation within the classroom.", "u": null, "notes": "concept: NI001517163621", "dep": null}, {"v": "05118", "n": "Music Appreciation", "d": "Music Appreciation courses provide students with an understanding of music and its importance in their lives. Course content focuses on how various styles of music apply musical elements to create an expressive or aesthetic impact. Students also have the ability for informal music performance and creation within the classroom.", "u": null, "notes": "concept: NI001517163622", "dep": null}, {"v": "05119", "n": "Composition/Songwriting", "d": "Composition/Songwriting courses prepare students to express themselves through creating music. These courses may use conventional or unconventional notation and may include instrumental and vocal music. Along with musical instruments and vocals, technology may be used for creating, recording, and performing music. Students will also perform compositions formally or informally and respond to music created in the classroom.", "u": null, "notes": "concept: NI001517163623", "dep": null}, {"v": "05120", "n": "Strings", "d": "Strings courses provide students an introduction to, and refine the fundamentals of, music and bowed-string instrument literature and techniques and may include more advanced techniques. These courses teach students the appropriate care, handling, and maintenance of musical instruments. Formal and informal performances are included as part of string instrument instructionalprograms as well as experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163624", "dep": null}, {"v": "05121", "n": "Contemporary Vocal Ensemble", "d": "Contemporary Vocal Ensemble courses help students develop vocal techniques while focusing primarily on contemporary stage literature styles, such as traditional jazz, jazz improvisation, and rock. These courses may also focus on gospel, show choir, or barbershop choral group dynamics. The ensembles provide performance opportunities and include experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163625", "dep": null}, {"v": "05122", "n": "Culturally Influenced Ensemble", "d": "Culturally Influenced Ensemble courses help students perform a variety of cultural music styles, such as Mariachi band, steel drum band, Indian gamelan, or African drumming ensembles. At the same time, these courses help students develop techniques on instruments appropriate to the style(s) performed�brass, woodwind, string, percussion instruments, and/or electronic and provide experiences in creating and responding to music. Courses emphasize instrumental music but may also include vocal music. Advanced coursework provides students with opportunities for growth through rehearsal and performance, improvisation, or creating and performing their own compositions.", "u": null, "notes": "concept: NI001517163626", "dep": null}, {"v": "05129", "n": "Music (pre-kindergarten)", "d": "Music (pre-kindergarten) courses provide developmentally appropriate activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Specific course content conforms to existing state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163627", "dep": null}, {"v": "05152", "n": "Art History", "d": "Art History courses introduce students to significant works of art, artists, and artistic movements that have shaped the world and influenced or reflected various periods of history. These courses may emphasize the sequential evolution of art forms, techniques, symbols, and themes. Art History courses also develop an understanding of art in relation to social, cultural, political, and historical events throughout the world, while covering multiple artists, aesthetic issues, and the evolution of art.", "u": null, "notes": "concept: NI001517163628", "dep": null}, {"v": "05153", "n": "AP Art History", "d": "Designed to parallel college-level Art History courses, AP Art History courses provide the opportunity for students to critically examine and respond to works of art within their historical and cultural contexts. In covering the art and movements of several centuries (not necessarily in chronological order), students learn to identify different styles, techniques, media and influences. Students formulate and articulate their reactions to various kinds of artwork to understand and appreciate themselves, others, and the world around them.", "u": null, "notes": "concept: NI001517163629", "dep": null}, {"v": "05130", "n": "Music (kindergarten)", "d": "Music (kindergarten) courses provide developmentally appropriate activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Specific course content conforms to any existing state standards for kindergarten.", "u": null, "notes": "concept: NI001517163630", "dep": null}, {"v": "05131", "n": "Music (grade 1)", "d": "Music (grade 1) courses provide activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and establishing the ability to discern and critique. Specific course content conforms to any existing state standards for grade 1.", "u": null, "notes": "concept: NI001517163631", "dep": null}, {"v": "05132", "n": "Music (grade 2)", "d": "Music (grade 2) courses provide activities to enable students to create and perform music, listen and respond to musical compositions, and to incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and establishing the ability to discern and critique. Specific course content conforms to any existing state standards for grade 2.", "u": null, "notes": "concept: NI001517163632", "dep": null}, {"v": "05133", "n": "Music (grade 3)", "d": "Music (grade 3) courses provide activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and establishing the ability to discern and critique. Specific course content conforms to any existing state standards for grade 3.", "u": null, "notes": "concept: NI001517163633", "dep": null}, {"v": "05134", "n": "Music (grade 4)", "d": "Music (grade 4) courses provide activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and establishing the ability to discern and critique. Specific course content conforms to any existing state standards for grade 4.", "u": null, "notes": "concept: NI001517163634", "dep": null}, {"v": "05135", "n": "Music (grade 5)", "d": "Music (grade 5) courses provide activities to enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and establishing the ability to discern and critique. Specific course content conforms to any existing state standards for grade 5.", "u": null, "notes": "concept: NI001517163635", "dep": null}, {"v": "05136", "n": "Music (grade 6)", "d": "Music (grade 6) courses enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and refining the ability to discern and critique. Specific course content conforms to any existing state standards for grade 6.", "u": null, "notes": "concept: NI001517163636", "dep": null}, {"v": "05137", "n": "Music (grade 7)", "d": "Music (grade 7) courses enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and refining the ability to discern and critique. Specific course content conforms to any existing state standards for grade 7.", "u": null, "notes": "concept: NI001517163637", "dep": null}, {"v": "05138", "n": "Music (grade 8)", "d": "Music (grade 8) courses enable students to create and perform music, listen and respond to musical compositions, and incorporate their musical experiences with other activities and subjects. Course content usually involves understanding music as creative expression and communication, developing skill with the voice and/or musical instruments, and refining the ability to discern and critique. Specific course content conforms to any existing state standards for grade 8.", "u": null, "notes": "concept: NI001517163638", "dep": null}, {"v": "01043", "n": "Reading (grade 3)", "d": "Reading (grade 3) courses focus on reading skills and may emphasize independent reading in a variety of assignments. Some emphasis may also be placed on presentation skills. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163639", "dep": null}, {"v": "01044", "n": "Reading (grade 4)", "d": "Reading (grade 4) courses focus on reading skills and may emphasize independent reading in a variety of assignments and require students to respond to different material in different ways. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163640", "dep": null}, {"v": "01045", "n": "Reading (grade 5)", "d": "Reading (grade 5) courses focus on reading skills and may extend students' skills in distinguishing meaning and literary functions in texts, and fluency in reading. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163641", "dep": null}, {"v": "01046", "n": "Reading (grade 6)", "d": "Reading (grade 6) courses build upon students' prior knowledge and skill in reading and may emphasize the use of language for different effects, in different contexts, and for different purposes. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163642", "dep": null}, {"v": "01047", "n": "Reading (grade 7)", "d": "Reading (grade 7) courses build upon students' prior knowledge and skill in reading and may emphasize the use of language for different effects, in different contexts, and for different purposes. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163643", "dep": null}, {"v": "01048", "n": "Reading (grade 8)", "d": "Reading (grade 8) courses build upon students' prior knowledge and skill in reading. Typically, these courses use various genres of literature to improve reading skills, and link exercises for different purposes to those reading selections. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163644", "dep": null}, {"v": "01049", "n": "Reading�General", "d": "Reading�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Reading, early childhood education through grade 8.]", "u": null, "notes": "concept: NI001517163645", "dep": null}, {"v": "01051", "n": "English/Literature (freshmen and sophomores)", "d": "English/Literature (freshmen and sophomores) courses are designed for freshmen and/or sophomores and typically introduce them to two or more genres of literature (novel, short story, poetry, and so on). Exploration of each genre's literary elements; determination of theme and intent; and examination of vocabulary and semantics are often included in the course content. Writing assignments are required as an additional method to improve understanding and comprehension.", "u": null, "notes": "concept: NI001517163646", "dep": null}, {"v": "01052", "n": "English/Literature (juniors and seniors)", "d": "English/Literature (juniors and seniors) courses are designed for juniors and/or seniors and emphasize comprehension, discernment, and critical-thinking skills in the reading of texts and literature. These courses introduce and explore more advanced literary techniques (irony, satire, humor, connotation, tone, rhythm, symbolism, and so on) through two or more literary genres, with the aim of creating sophisticated readers. Writing assignments are required as an additional method to develop and improve critical-thinking and analytic skills.", "u": null, "notes": "concept: NI001517163647", "dep": null}, {"v": "01053", "n": "Literature", "d": "Literature courses offer the opportunity for students to study and reflect upon the themes presented in the body of literature being presented. Students improve their critical-thinking skills as they determine the underlying assumptions and values within the reading selection and as they understand how the work reflects society's problems and culture. Oral discussion is an integral part of literature courses, and written compositions are often required. Literature courses may survey representative works, reflect a particular genre or a specific theme, or survey works of a particular time or people.", "u": null, "notes": "concept: NI001517163648", "dep": null}, {"v": "05139", "n": "Music�General", "d": "Music�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Music, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163649", "dep": null}, {"v": "11051", "n": "Audio/Visual Production", "d": "Audio/Visual Production courses provide students with the knowledge and skills necessary for television, video, film, and/or radio production. Writing scripts, camera operation, use of graphics and other visuals, lighting, audio techniques, editing, production principles, and career opportunities are typical topics covered within production courses. Students are usually required to produce their own program or segment. Additional topics such as broadcast industry regulations, radio/TV operation, power of the medium, photography, transmission technology, and so on may be included.", "u": null, "notes": "concept: NI001517163923", "dep": null}, {"v": "11052", "n": "Commercial Photography", "d": "Commercial Photography courses provide instruction in the use of cameras and laboratory film- processing techniques. Topics covered in the course include composition and color dynamics; contact printing; enlarging; developing audio and visual images; use of camera meters, air brushes, and other photographic equipment; portrait, commercial, and industrial photography; processing microfilm; and preparing copy for printing or for graphic arts processing.", "u": null, "notes": "concept: NI001517163924", "dep": null}, {"v": "11053", "n": "Photographic Laboratory and Darkroom", "d": "Photographic Laboratory and Darkroom courses prepare students to develop and print still or motion picture film. Topics covered in the course may include controlling resultant prints; touching up negatives; and finishing, coloring, restoring, and copying prints.", "u": null, "notes": "concept: NI001517163925", "dep": null}, {"v": "11054", "n": "Photo Imaging", "d": "Photo Imaging courses provide students with the opportunity to effectively communicate ideas and information via digital, film, still and video photography. Topics covered typically include composition, layout, lighting and supplies. More advanced courses may include instruction in specialized camera and equipment maintenance, application to commercial and industrial need and photography business operations.", "u": null, "notes": "concept: NI001517163926", "dep": null}, {"v": "11055", "n": "Video", "d": "Video courses enable students to explore video communications, incorporating both the technical and artistic aspects of video media. Topics covered in the course include the use of video equipment and techniques, and students typically create a video presentation. Advanced course topics may include creating various forms of film media including silent film; sport and music video; and self portrait video.", "u": null, "notes": "concept: NI001517163927", "dep": null}, {"v": "11103", "n": "Broadcasting Technology", "d": "Broadcasting Technology courses provide students with the knowledge and skills to produce television broadcast programs. Typically, students prepare and produce short programs, learning the technical aspects of the operation and how to evaluate programming and assess audience reaction and impact.", "u": null, "notes": "concept: NI001517163928", "dep": null}, {"v": "11104", "n": "Publication Production", "d": "Publication Production courses provide students with the knowledge and skills necessary to produce the school newspaper, yearbook, literary magazine, or other printed publication. Students may gain experience in several components (writing, editing, layout, production, and so on) or may focus on a single aspect while producing the publication.", "u": null, "notes": "concept: NI001517163929", "dep": null}, {"v": "11105", "n": "Particular Topics in Journalism and Broadcasting", "d": "These courses examine specific topics in journalism and broadcasting other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163930", "dep": null}, {"v": "11106", "n": "Emerging Technologies in Journalism", "d": "Emerging Technologies in Journalism courses promote the development of the necessary skills for journalism. Course topics may include an exploration of the role media and the communications industry has in society, technical skills related to journalistic writing and interviewing, electronic communications, journalistic blogging, and the ethical and legal issues related to technology in media and communications.", "u": null, "notes": "concept: NI001517163931", "dep": null}, {"v": "11107", "n": "Radio Production", "d": "Radio Production courses address practices related to the management and operation of a broadcasting station. Students are introduced to the radio industry, news reporting, and broadcast engineering. In these courses, students learn basic electricity and electronics, including all aspects of safety. Topics typically include operating audio boards, announcing, creating and producing audio scripts, and using digital audio software. Advanced courses may explore direct programming, on-air performance, and analysis of ratio markets.", "u": null, "notes": "concept: NI001517163932", "dep": null}, {"v": "11147", "n": "Journalism and Broadcasting�Independent Study", "d": "Journalism and Broadcasting�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to journalism, broadcasting, and mass media. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163933", "dep": null}, {"v": "11148", "n": "Journalism and Broadcasting�Workplace Experience", "d": "Journalism and Broadcasting�Workplace Experience courses provide students with work experience in a field related to journalism or broadcasting. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163934", "dep": null}, {"v": "11149", "n": "Journalism and Broadcasting�Other", "d": "Other Journalism and Broadcasting courses.", "u": null, "notes": "concept: NI001517163935", "dep": null}, {"v": "11151", "n": "Digital Media Technology", "d": "These courses are designed to give students the skills necessary to support and enhance their learning about digital medial technology. Topics covered in the course may include internet research, copyright laws, web-publishing, use of digital imagery, electronic forums, newsgroups, mailing lists, presentation tools, and project planning.", "u": null, "notes": "concept: NI001517163936", "dep": null}, {"v": "11152", "n": "Desktop Publishing", "d": "Desktop Publishing courses integrate the knowledge and skills learning in word processing with the concepts, procedures and application of desktop publishing. Students learn to format, create and proofread brochures, programs, newsletters, web pages, presentations and manuscripts.", "u": null, "notes": "concept: NI001517163937", "dep": null}, {"v": "11153", "n": "Digital Media Design and Production", "d": "Digital Media Design and Production courses teach students the fundamentals of graphic design and production and provide students with the opportunity to apply these principles to printed media, digital presentation media, and interactive media.", "u": null, "notes": "concept: NI001517163938", "dep": null}, {"v": "12002", "n": "Office Procedures�Comprehensive", "d": "Office Procedures�Comprehensive courses provide students with numerous opportunities to explore and understand the responsibilities and duties common to most office personnel. These comprehensive courses cover such topics as communication skills, project management, reception skills, technologies for distance communications, filing and record management, mail handling, scheduling meetings and conferences, creating itineraries, and word processing.", "u": null, "notes": "concept: NI001517163939", "dep": null}, {"v": "12003", "n": "Office and Administrative Technologies", "d": "Office and Administrative Technologies courses provide students with instruction and experience in developing technical, problem-solving, and decision-making skills essential for office and/or administrative occupations. Emphasis is placed on integrating and applying knowledge and skills to realistic office and administrative situations utilizing current and relevant technology.", "u": null, "notes": "concept: NI001517163940", "dep": null}, {"v": "12004", "n": "Office Services", "d": "Office Services courses introduce students to and help them refine their clerical and office assistant skills. Course content typically covers filing, telephone, and keyboarding skills; reprographic machinery and procedures; communications skills; and so on.", "u": null, "notes": "concept: NI001517163941", "dep": null}, {"v": "12005", "n": "Keyboarding", "d": "Keyboarding courses provide students with an introduction to the keyboard (letters, numbers, and symbols), basic machine operation, and proper keystroke technique. As students progress, they improve their speed and accuracy and produce increasingly complex documents. Such courses help students develop keyboard proficiency, document production skills, and problem-solving skills.", "u": null, "notes": "concept: NI001517163942", "dep": null}, {"v": "12006", "n": "Word Processing", "d": "Word Processing courses introduce students to automated document production using one or more software packages. These courses may introduce keyboarding techniques or may require prior experience. A parallel focus is placed on the use of software commands and functions to create, edit, format, and manipulate documents, capitalizing on the power offered by word processing software programs. These courses may also cover file and disk management and other computer-related skills.", "u": null, "notes": "concept: NI001517163943", "dep": null}, {"v": "12007", "n": "Recordkeeping", "d": "Recordkeeping courses help students develop knowledge and skills related to the principles and procedures involved in recording personal financial transactions as well as transactions typically undertaken by small businesses. Emphasis may be placed on software packages for accounting, database management, personal banking, budgeting, and income tax calculations. Additional emphasis is usually placed on cashier and clerk procedures, inventory control for small businesses, database management, merchandising, and payroll.", "u": null, "notes": "concept: NI001517163944", "dep": null}, {"v": "11998", "n": "Communication and Audio/Video Technology�Workplace Experience", "d": "Communication and Audio/Video Technology�Workplace Experience courses provide students with work experience in a field related to communication or audio/visual technology. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163945", "dep": null}, {"v": "11999", "n": "Communication and Audio/Video Technology�Other 1199", "d": "Other Communication and Audio/Video Technology courses.", "u": null, "notes": "concept: NI001517163946", "dep": null}, {"v": "12001", "n": "Business/Office Career Exploration", "d": "Business/Office Career Exploration courses expose students to the occupational opportunities available in business including, but not limited to, general business, business information management, human resources management, operations management, administrative support, accounting, and marketing fields. Emphasis is placed on responsibilities, qualifications, work environments, and career paths. These courses may also include consumer education topics, keyboard exposure, and/or hands-on experience within the various occupational areas.", "u": null, "notes": "concept: NI001517163947", "dep": null}, {"v": "12051", "n": "Introductory Business", "d": "Introductory Business courses survey an array of topics and concepts related to the field of business. These courses introduce business concepts such as banking and finance, the role of government in business, consumerism, credit, investment, and management. They usually provide a brief overview of the U.S. economic system, small businesses, and corporate organizations. Introductory Business courses may also expose students to the varied opportunities in administration, accounting, management, and related fields.", "u": null, "notes": "concept: NI001517163948", "dep": null}, {"v": "12060", "n": "Business Ethics", "d": "Business Ethics courses focus on the study of ethical principles and the application of those principles to situations relevant to decision-making in the professional and business worlds.", "u": null, "notes": "concept: NI001517163949", "dep": null}, {"v": "12097", "n": "Management�Independent Study", "d": "Management�Independent Study courses, often conducted with instructors as mentors, enable students to explore business management-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163950", "dep": null}, {"v": "12098", "n": "Management�Workplace Experience", "d": "Management�Workplace Experience courses provide students with work experience in fields related to business management. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163951", "dep": null}, {"v": "12099", "n": "Management�Other", "d": "Other Management courses.", "u": null, "notes": "concept: NI001517163952", "dep": null}, {"v": "12101", "n": "Banking and Finance", "d": "Banking and Finance courses provide students with an overview of the United States' monetary and banking systems, as well as types of financial institutions and the services and products that they offer. Course content may include government regulations; checking, savings, and money market accounts; loans; investments; and negotiable instruments.", "u": null, "notes": "concept: NI001517163953", "dep": null}, {"v": "12102", "n": "Banking", "d": "Banking courses expose students to the United States' monetary and banking systems. These courses may also examine and apply the methods used for measuring the financial performance of banks in addition to examining specialized brokerage products, current issues, and future trends in banking.", "u": null, "notes": "concept: NI001517163954", "dep": null}, {"v": "12103", "n": "Finance", "d": "Finance courses are similar to Banking and Finance courses, but they focus specifically on finance, addressing how businesses raise, distribute, and use financial resources while managing risk. Course content typically involves modeling financial decisions (such as borrowing, selling equity or stock, lending or investing) typically undertaken by businesses.", "u": null, "notes": "concept: NI001517163955", "dep": null}, {"v": "12052", "n": "Business Management", "d": "Business Management courses acquaint students with management opportunities and effective human relations. These courses provide students with the skills to perform planning, staffing, financing, and controlling functions within a business. In addition, they usually provide a macro-level study of the business world, including business structure and finance, and the interconnections among industry, government, and the global economy. The course may also emphasize problem-based, real-world applications of business concepts and use accounting concepts to formulate, analyze, and evaluate business decisions.", "u": null, "notes": "concept: NI001517163956", "dep": null}, {"v": "12053", "n": "Entrepreneurship", "d": "Entrepreneurship courses help students develop the knowledge and skills necessary to own and operate their own businesses. The course content typically covers topics from a number of fields: economics, marketing principles, human relations and psychology, business and labor law, legal rights and responsibilities of ownership, business and financial planning, finance and accounting, communication, information management, risk management, and strategic management. Several topics surveyed in Business Management courses may also be included.", "u": null, "notes": "concept: NI001517163957", "dep": null}, {"v": "12054", "n": "Business Law (12054)", "d": "Business Law courses emphasize legal concepts that are relevant to business and business organizations. Topics examined in these courses typically include contracts, buying/renting property, installment buying, insurance, buyer/seller relationships, negotiable instruments, employment, taxes, insurance, commercial papers, legal organizational structures, and consumer liabilities.", "u": null, "notes": "concept: NI001517163958\nprefLabel: Business Law", "dep": null}, {"v": "12055", "n": "Business Principles and Management", "d": "Business Principles and Management courses are designed to provide students with an understanding of the U.S. business system, its organizations, and its management. These courses examine the various leadership and management styles of a variety of successful business organizations, large and small.", "u": null, "notes": "concept: NI001517163959", "dep": null}, {"v": "12056", "n": "International Business and Marketing", "d": "International Business and Marketing courses examine business management and administration in a global economy. Topics covered in this course typically include the principles and processes of export sales, trade controls, foreign operations and related problems, monetary issues, international business and policy, and applications of doing business in specific countries and markets.", "u": null, "notes": "concept: NI001517163960", "dep": null}, {"v": "12008", "n": "Particular Topics in Administration", "d": "These courses examine specific topics related to business administration not otherwise described, such as a focus on dictation or office machinery, rather than provide a general study of office administration principles and techniques.", "u": null, "notes": "concept: NI001517163961", "dep": null}, {"v": "12009", "n": "Business Communications", "d": "Business Communications courses help students to develop an understanding and appreciation for effective communication in business situations and environments. Emphasis is placed on all phases of communication: speaking, listening, thinking, responding, reading, writing, communicating nonverbally, and utilizing technology for communication. Business communication functions, processes, and applications in the context of business may be practiced through problem-based projects and real world application.", "u": null, "notes": "concept: NI001517163962", "dep": null}, {"v": "12047", "n": "Administration�Independent Study", "d": "Administration�Independent Study courses, often conducted with instructors as mentors, enable students to explore business administration-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163963", "dep": null}, {"v": "12048", "n": "Administration�Workplace Experience", "d": "Administration�Workplace Experience courses provide students with work experience in fields related to business administration. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163964", "dep": null}, {"v": "12049", "n": "Administration�Other", "d": "Other Administration courses.", "u": null, "notes": "concept: NI001517163965", "dep": null}, {"v": "18148", "n": "Animal Systems�Workplace Experience", "d": "Animal Systems�Workplace Experience courses provide work experience in fields related to animal systems (management, care, and/or processing). Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164262", "dep": null}, {"v": "18311", "n": "Viticulture", "d": "Viticulture courses prepare students for further studies in grape-growing, viticulture, and wine-making industry. Course topics typically include establishing and managing vineyards; harvesting; fermentation and wine making; marketing; and exploring career options within the industry. Agricultural applications specific to vineyards and wineries are emphasized.", "u": null, "notes": "concept: NI001517164263", "dep": null}, {"v": "18347", "n": "Agricultural Production and Processing�Independent Study", "d": "Courses in Agricultural Production and Processing�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to agricultural production and processing. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164264", "dep": null}, {"v": "18348", "n": "Agricultural Production and Processing�Workplace Experience", "d": "Agricultural Production and Processing�Workplace Experience courses provide students with work experience in fields related to agricultural production and processing. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164265", "dep": null}, {"v": "18149", "n": "Animal Systems�Other", "d": "Other Animal Systems courses.", "u": null, "notes": "concept: NI001517164266", "dep": null}, {"v": "18201", "n": "Agribusiness Management", "d": "Agribusiness Management courses provide students with the information and skills necessary for success in agribusiness and in operating entrepreneurial ventures in the agricultural industry. These courses may cover topics such as economic principles, budgeting, risk management, finance, business law, marketing and promotion strategies, insurance, and resource management. Other possible topics include developing a business plan, employee/employer relations, problem-solving and decisionmaking, commodities, and building leadership skills. These courses may also incorporate a survey of the careers within the agricultural industry.", "u": null, "notes": "concept: NI001517164267", "dep": null}, {"v": "18202", "n": "Agricultural Entrepreneurship", "d": "Agricultural Entrepreneurship courses focus on the personal skills necessary for success in entrepreneurial ventures in the agricultural industry. Topics include setting goals, assessing and solving problems, evaluating financial progress and success, business planning, information management and evaluation, and recordkeeping.", "u": null, "notes": "concept: NI001517164268", "dep": null}, {"v": "18305", "n": "Food Product Processing", "d": "Food Product Processing courses impart the knowledge and skills needed to produce and manufacture food products for the consumer market. These courses focus on food products while covering a variety of topics, such as quality selection and preservation, equipment care and sanitation, government regulations, marketing, consumer trends, and product research and development.", "u": null, "notes": "concept: NI001517164269", "dep": null}, {"v": "18306", "n": "Aquaculture", "d": "Aquaculture courses impart the knowledge and skills needed for producing fish, plants, and other species living in an aquatic environment, and course topics typically include the selection, propagation, harvesting, and marketing of those species. Instruction may also address aquatic and marine biology, ecosystems, water quality and management, and business practices.", "u": null, "notes": "concept: NI001517164270", "dep": null}, {"v": "18307", "n": "Agriculture and Society", "d": "Agriculture and Society courses provide an overview of the importance of, impact on, and relationships between agricultural endeavors and society at large. These courses typically emphasize economic and environmental factors and impacts (such as urban and agricultural water use) and the influences of society on agricultural endeavors (including production, processing, and distribution). Current technological advances (such as genetic engineering) may also be discussed.", "u": null, "notes": "concept: NI001517164271", "dep": null}, {"v": "18308", "n": "Agricultural Biotechnology", "d": "Agricultural Biotechnology courses apply biological principles and understanding to plant and animal science in order to produce or refine agricultural products. Course topics typically include but are not limited to microbiology, genetics, growth and reproduction, structural basis of function in living systems, chemistry of living systems, quantitative problem-solving, and data acquisition and display. These courses also often cover the ethics of biotechnology.", "u": null, "notes": "concept: NI001517164272", "dep": null}, {"v": "18309", "n": "Particular Topics in Agricultural Production/Processing", "d": "These courses examine specific topics related to producing and processing agricultural products (such as meat cutting) rather than provide a general study of production or processing.", "u": null, "notes": "concept: NI001517164273", "dep": null}, {"v": "18310", "n": "Sustainable/Alternative Agriculture", "d": "Sustainable/Alternative Agriculture courses explore technological and environmental changes and concerns. These courses address alternative approaches to food production including, but not limited to, organics, low-input, natural, and sustainable production methodology and practices. Course content may include comparing the effects of alternative production practices to those of conventional production practices.", "u": null, "notes": "concept: NI001517164274", "dep": null}, {"v": "18106", "n": "Particular Topics in Animal Systems", "d": "These courses examine specific topics related to animal care and management, production, or processing, such as equine training or animal waste management, rather than provide a general study of animal care and the systems related to their growth and management.", "u": null, "notes": "concept: NI001517164275", "dep": null}, {"v": "18107", "n": "Animal Nutrition", "d": "Animal Nutrition courses provide students with opportunities to study the structure and function of organic and inorganic nutrients. Topics may include the essential nutritive requirements of domestic livestock, poultry, and companion animals; digestion, absorption, metabolism, and barriers for nutrient utilization; sources of nutrients; application of energy systems and concepts; and regulation of feed intake in animals. These courses also teach students how to compare and contrast the nutritional levels for animal maintenance and production.", "u": null, "notes": "concept: NI001517164276", "dep": null}, {"v": "18108", "n": "Animal Genetics", "d": "Animal Genetics courses explore genetic inheritance in agricultural animals and the identification of livestock breeds by the origin, significance, distribution, and domestication of animal species. These courses allow students to compare and contrast the hierarchical classification of the major agricultural animal species and identify breeding system options based on the principles of genetics. These courses also address selecting animals based on quantitative breeding values for specific characteristics.", "u": null, "notes": "concept: NI001517164277", "dep": null}, {"v": "18109", "n": "Integrated Pest Management", "d": "Integrated Pest Management courses help students develop an understanding of the life cycles of and damage caused by pests, diseases, and weeds. Course topics may include the application of pesticides and/or herbicides to manage pest populations and assessing the effectiveness of pest management plans.", "u": null, "notes": "concept: NI001517164278", "dep": null}, {"v": "18147", "n": "Animal Systems�Independent Study", "d": "Courses in Animal Systems�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to animal systems. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164279", "dep": null}, {"v": "18349", "n": "Agricultural Production and Processing�Other", "d": "Other Agricultural Production and Processing courses.", "u": null, "notes": "concept: NI001517164280", "dep": null}, {"v": "18401", "n": "Agriculture Mechanics/Equipment/Structures", "d": "Agriculture Mechanics/Equipment/Structures courses provide students with the skills and knowledge that are specifically applicable to the tools and equipment used in the industry. While learning to apply their knowledge of the basic principles of technological design and production skills (engine mechanics, power systems, welding, and carpentry, among others), students may explore a broad range of topics, including the operation, mechanics, and care of tools and machines; the construction and repair of structures integral to agricultural operations; a study of electricity and power principles; and the study of alternative fuels, technology and engineering, and safety procedures.", "u": null, "notes": "concept: NI001517164281", "dep": null}, {"v": "18402", "n": "Agriculture Mechanics and Equipment", "d": "Agriculture Mechanics and Equipment courses provide students with the engineering, power, and mechanical technology principles, skills, and knowledge that are specifically applicable to the agricultural industry. Typical topics include the operation, maintenance, and repair of power, electrical, hydraulic, pneumatic, renewable, wind, solar, and mechanical systems.", "u": null, "notes": "concept: NI001517164282", "dep": null}, {"v": "18403", "n": "Agriculture Structures", "d": "Agriculture Structures courses provide students with the skills and knowledge that are specifically applicable to the construction, maintenance, and repair of structures integral to the agricultural industry, including but not limited to animal enclosures, irrigation systems, and storage facilities. In these courses, students typically study technology, design, planning, and construction knowledge and skills (such as measurement, carpentry, plumbing, concrete, and electrical systems), in addition to the safe operation of tools, technology and machines.", "u": null, "notes": "concept: NI001517164283", "dep": null}, {"v": "18404", "n": "Agricultural Metal Fabrication Technology", "d": "Formerly known as Agriculture Welding, Agricultural Metal Fabrication Technology courses provide students with the skills and knowledge that are specifically applicable to the tools and equipment used in the industry. In learning to apply basic technical knowledge and skills (engines, power, welding, and structures, among others), students may explore a broad range of topics, including the operation, mechanics, and care of tools, technology and machines; the construction and repair of structures integral to agricultural operations; an introduction or review of electricity and power; and safety procedures.", "u": null, "notes": "concept: NI001517164284", "dep": null}, {"v": "18405", "n": "Particular Topics in Agricultural Mechanics and Construction", "d": "These courses examine specific topics related to agricultural mechanics and construction, such as specific vehicles or structures, rather than provide a general study of mechanics and construction techniques.", "u": null, "notes": "concept: NI001517164285", "dep": null}, {"v": "18406", "n": "Water Treatment", "d": "Water Treatment courses provide instruction regarding the environmental hazards associated with identifying and accepting waste water disposal. Course topics typically include waste water, the steps in waste water treatment, compliance with applicable regulations, and the use of water-testing instruments and water-treatment equipment to treat wastewater.", "u": null, "notes": "concept: NI001517164286", "dep": null}, {"v": "18447", "n": "Agricultural Mechanics and Construction�Independent Study", "d": "Courses in Agricultural Mechanics and Construction�Independent Study, often conducted with instructors as mentors, enable students to topics of interest related to agricultural mechanics and/or construction. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164287", "dep": null}, {"v": "18448", "n": "Agricultural Mechanics and Construction�Workplace Experience", "d": "Agricultural Mechanics and Construction�Workplace Experience courses provide work experience in fields related to agricultural mechanics and construction. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164288", "dep": null}, {"v": "18547", "n": "Natural Resources�Independent Study", "d": "Courses in Natural Resources�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to natural resources. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164289", "dep": null}, {"v": "19052", "n": "Child Development", "d": "Child Development courses provide students with knowledge about the physical, mental, emotional, social, and moral growth and development of children from conception to pre-school age, emphasizing the application of this knowledge in child care settings and/or home environments. Brain development and current developmental research are addressed. These courses typically include related topics such as the appropriate care of infants, toddlers, and young children.", "u": null, "notes": "concept: NI001517164290", "dep": null}, {"v": "19053", "n": "Elder Care", "d": "Elder Care courses emphasize the care of human beings as they grow older. These courses involve the study of the biological, physiological, social, and psychological needs and concerns of the elderly, and deal with economic and legal issues, the aging process, death, and dying in a realistic manner. Elder Care courses may cover work and personal habits appropriate to the field, and may also offer the opportunity to explore various careers.", "u": null, "notes": "concept: NI001517164291", "dep": null}, {"v": "18548", "n": "Natural Resources�Workplace Experience", "d": "Natural Resources�Workplace Experience courses provide students with work experience in fields related to natural resources. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164292", "dep": null}, {"v": "18549", "n": "Natural Resources�Other", "d": "Other Natural Resources courses.", "u": null, "notes": "concept: NI001517164293", "dep": null}, {"v": "18995", "n": "Agriculture, Food, and Natural Resources�Aide", "d": "Agriculture, Food, and Natural Resources�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164294", "dep": null}, {"v": "18203", "n": "Agricultural Leadership", "d": "Agricultural Leadership courses help students develop leadership skills with a focus on opportunities in the food, fiber, and natural resources industries. Topics may include but are not limited to human relationships and effective communication, decisionmaking and problem-solving, leadership qualities and styles, and ensuring successful completion of group activities.", "u": null, "notes": "concept: NI001517164295", "dep": null}, {"v": "18204", "n": "Particular Topics in Agribusiness", "d": "These courses examine specific topics related to Agribusiness, such as international agriculture or commodities, rather than provide a general study of agribusiness principles.", "u": null, "notes": "concept: NI001517164296", "dep": null}, {"v": "18205", "n": "Agriculture Computers and Technology", "d": "Agriculture Computers and Technology courses help students develop their knowledge and skills in using computer and other technology to operate and manage agricultural businesses. These courses allow students to use computer hardware, software, and the Internet to find information, record and analyze financial and production data, track market trends and economic forecasts, monitor weather, utilize global positioning systems, and prepare communications and reports.", "u": null, "notes": "concept: NI001517164297", "dep": null}, {"v": "18247", "n": "Agribusiness�Independent Study", "d": "Courses in Agribusiness�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to agribusiness. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164298", "dep": null}, {"v": "18248", "n": "Agribusiness�Workplace Experience", "d": "Agribusiness�Workplace Experience courses provide work experience in fields related to agribusiness. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164299", "dep": null}, {"v": "18249", "n": "Agribusiness�Other", "d": "Other Agribusiness Courses", "u": null, "notes": "concept: NI001517164300", "dep": null}, {"v": "18301", "n": "Agricultural Production", "d": "Agricultural Production courses combine content related to animal and plant production, providing comprehensive coverage of the production functions of the agricultural industry. These courses typically cover such topics as care and management of farm animals, crop production and harvesting, plant and animal insect and disease control, efficient resource management, analyses of qualitative/quantitative data for decisionmaking, and farm management.", "u": null, "notes": "concept: NI001517164301", "dep": null}, {"v": "18302", "n": "Agricultural Processing", "d": "Agricultural Processing courses impart the knowledge and skills needed to bring animal and plant products to market. They may cover a wide variety of topics, including care and maintenance of animals or plants, quality selection and preservation, equipment care and sanitation, government regulations, and marketing and consumer trends. Agricultural Processing courses may present an overview of agricultural processing or may specialize in particular types of products.", "u": null, "notes": "concept: NI001517164302", "dep": null}, {"v": "24461", "n": "Particular Topics in Japanese", "d": "Particular Topics in Japanese courses examine particular topics focused on Japanese language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described. elsewhere in this classification system", "u": null, "notes": "concept: NI001517162988", "dep": null}, {"v": "24462", "n": "IB Language A: Literature�Japanese", "d": "IB Language A: Literature�Japanese courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Japanese in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162989", "dep": null}, {"v": "24463", "n": "IB Language B�Japanese", "d": "IB Language B�Japanese courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162990", "dep": null}, {"v": "24467", "n": "IB Language A: Language and Literature�Japanese", "d": "IB Language A: Language and Literature�Japanese courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Japanese in an academic context.", "u": null, "notes": "concept: NI001517162991", "dep": null}, {"v": "24512", "n": "IB Language A: Literature�Korean", "d": "IB Language A: Literature�Korean courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Korean in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162992", "dep": null}, {"v": "24513", "n": "IB Language B�Korean", "d": "IB Language B�Korean courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162993", "dep": null}, {"v": "24516", "n": "IB Language B (Korean), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Korean), Middle Years Program courses enable students to gain competence in modern Korean and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162994", "dep": null}, {"v": "24468", "n": "IB Language Ab Initio�Japanese", "d": "IB Language Ab Initio�Japanese courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517162995", "dep": null}, {"v": "24499", "n": "Japanese�Other", "d": "Other Japanese courses", "u": null, "notes": "concept: NI001517162996", "dep": null}, {"v": "24500", "n": "Korean for Young Learners (prior-to-secondary)", "d": "Korean for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Korean and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Korean-speaking cultures.", "u": null, "notes": "concept: NI001517162997", "dep": null}, {"v": "23001", "n": "Early Childhood Education", "d": "Early Childhood Education courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for early childhood education.", "u": null, "notes": "concept: NI001517163003", "dep": null}, {"v": "24501", "n": "Korean Immersion (prior-to-secondary)", "d": "Korean Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Korean and grade-specific content using Korean as the language of instruction. Korean Immersion courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Korean-speaking cultures.", "u": null, "notes": "concept: NI001517162998", "dep": null}, {"v": "24502", "n": "Korean I", "d": "Designed to introduce students to Korean language and culture, Korean I courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Korean-speaking cultures.", "u": null, "notes": "concept: NI001517162999", "dep": null}, {"v": "24503", "n": "Korean II", "d": "Korean II courses build upon skills developed in Korean I, preparing students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Korean II courses introduce the relationships among the products, practices, and perspectives of Korean-speaking cultures.", "u": null, "notes": "concept: NI001517163000", "dep": null}, {"v": "24504", "n": "Korean III", "d": "Korean III courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Korean-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163001", "dep": null}, {"v": "23002", "n": "Pre-kindergarten", "d": "Pre-kindergarten courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163002", "dep": null}, {"v": "22999", "n": "Miscellaneous�Other", "d": "Other Miscellaneous courses.", "u": null, "notes": "concept: NI001517163004", "dep": null}, {"v": "22998", "n": "Miscellaneous�Workplace Experience", "d": "Miscellaneous�Workplace Experience courses provide students with work experience in a field related to their interests. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace. Note: if the particular subject area is known, use the code associated with the Workplace Experience course within that subject area.", "u": null, "notes": "concept: NI001517163005", "dep": null}, {"v": "22997", "n": "Miscellaneous�Independent Study", "d": "Miscellaneous�Independent Study courses, typically organized as a mentorship with a teacher or outside professional, enable students to conduct investigations related to their field(s) of interest. Note: if the particular subject area is known, use the code associated with the Independent Study course within that subject area.", "u": null, "notes": "concept: NI001517163006", "dep": null}, {"v": "22995", "n": "Miscellaneous�Aide", "d": "Miscellaneous�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula or to assist other staff members in fulfilling their duties. Students may provide tutorial or instructional assistance to other students. Note: if the particular subject area is known, use the code associated with the Aide course within that subject area.", "u": null, "notes": "concept: NI001517163007", "dep": null}, {"v": "22260", "n": "IB Personal Project, Middle Years Program", "d": "International Baccalaureate (IB) Personal Project, Middle Years Program courses occur during the final year of the program and should result in a significant piece of work that is the product of the student's own initiative and creativity. Students choose their projects, which may take many forms, and complete them under the supervision of a teacher. Projects involve planning, research, and a high degree of personal reflection.", "u": null, "notes": "concept: NI001517163008", "dep": null}, {"v": "22254", "n": "Developmental Support", "d": "Developmental Support courses are customized according to each student's condition and needs, emphasizing an increase in skill or control of body and mind function. Examples of support may include refinement of gross and fine motor skills, development of visual perception, and improvement in eye-hand coordination.", "u": null, "notes": "concept: NI001517163009", "dep": null}, {"v": "22253", "n": "Social Development Instruction", "d": "Social Development Instruction courses teach students the social skills needed for independent functioning with the community. Topics may include self-control, self-expression, obeying rules, decision-making, appropriate situational behavior, interacting with others, and maintaining relationships. Students may develop independence, self-confidence, and self-reliance.", "u": null, "notes": "concept: NI001517163010", "dep": null}, {"v": "22252", "n": "Communication Instruction", "d": "Communication Instruction courses are typically indiviualized according to each student's condition and needs. Increasing the student's communication skills�oral expression, listening comprehension, reading, and writing�is emphasized; communication techniques in several areas (Educational, social, and vocational) are often explored.", "u": null, "notes": "concept: NI001517163011", "dep": null}, {"v": "24505", "n": "Korean IV", "d": "Korean IV courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Korean IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Korean-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163012", "dep": null}, {"v": "24506", "n": "Korean V", "d": "Korean V courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Korean V courses promote students' understanding of the relationships among the products, practices, and perspectives of Korean-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163013", "dep": null}, {"v": "24507", "n": "Korean for Native Speakers", "d": "Korean for Native Speakers courses prepare native and heritage speakers to communicate in Korean in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Korean for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Korean-speaking world.", "u": null, "notes": "concept: NI001517163014", "dep": null}, {"v": "24508", "n": "Korean Field Experience", "d": "Korean Field Experience courses place students in environments in which they interact with native Korean speakers, typically in settings where Korean is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163015", "dep": null}, {"v": "24509", "n": "Korean Conversation and Culture", "d": "Korean Conversation and Culture courses provide students with an introduction to the Korean language and the culture(s) of Korean-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163016", "dep": null}, {"v": "24510", "n": "Korean Literature", "d": "Korean Literature courses prepare students to communicate authentically in Korean by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Korean. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Korean cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163017", "dep": null}, {"v": "24511", "n": "Particular Topics in Korean", "d": "Particular Topics in Korean courses examine particular topics focused on Korean language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163018", "dep": null}, {"v": "24517", "n": "IB Language A: Language and Literature�Korean", "d": "IB Language A: Language and Literature�Korean courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Korean in an academic context.", "u": null, "notes": "concept: NI001517163019", "dep": null}, {"v": "24549", "n": "Korean�Other", "d": "Other Korean courses", "u": null, "notes": "concept: NI001517163020", "dep": null}, {"v": "24550", "n": "Vietnamese for Young Learners (prior-to-secondary)", "d": "Vietnamese for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Vietnamese and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Vietnamese-speaking cultures.", "u": null, "notes": "concept: NI001517163021", "dep": null}, {"v": "24551", "n": "Vietnamese Immersion (prior-to-secondary)", "d": "Vietnamese Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Vietnamese and grade-specific content using Vietnamese as the language of instruction. Vietnamese Immersion courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Vietnamese-speaking cultures.", "u": null, "notes": "concept: NI001517163022", "dep": null}, {"v": "24552", "n": "Vietnamese I", "d": "Designed to introduce students to Vietnamese language and culture, Vietnamese I courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Vietnamese-speaking cultures.", "u": null, "notes": "concept: NI001517163023", "dep": null}, {"v": "24553", "n": "Vietnamese II", "d": "Vietnamese II courses build upon skills developed in Vietnamese I, preparing students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Vietnamese II courses introduce the relationships among the products, practices, and perspectives of Vietnamese-speaking cultures.", "u": null, "notes": "concept: NI001517163024", "dep": null}, {"v": "24554", "n": "Vietnamese III", "d": "Vietnamese III courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Vietnamese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163025", "dep": null}, {"v": "24555", "n": "Vietnamese IV", "d": "Vietnamese IV courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Vietnamese IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Vietnamese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163026", "dep": null}, {"v": "24608", "n": "Filipino Field Experience", "d": "Filipino Field Experience courses place students in environments in which they interact with native Filipino speakers, typically in settings where Filipino is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163027", "dep": null}, {"v": "24609", "n": "Filipino Conversation and Culture", "d": "Filipino Conversation and Culture courses provide students with an introduction to the Filipino language and the culture(s) of Filipino-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163028", "dep": null}, {"v": "02125", "n": "AP Calculus BC", "d": "Following the College Board's suggested curriculum designed to parallel college-level calculus courses, AP Calculus BC courses provide students with an understanding of the concepts of calculus and experience with its methods and applications. These courses cover all of the calculus topics in AP Calculus AB as well as the following topics: parametric, polar, and vector functions; applications of integrals; and polynomial approximations and series, including series of constants and Taylor series. See SCED Code 02124 for more details.", "u": null, "notes": "concept: NI001517163306", "dep": null}, {"v": "02126", "n": "Particular Topics in Calculus", "d": "These courses examine specific topics in calculus (such as integral calculus, special functions or series, or the applications of calculus to mathematical modeling), rather than provide a general overview of calculus.", "u": null, "notes": "concept: NI001517163307", "dep": null}, {"v": "02201", "n": "Probability and Statistics", "d": "Probability and Statistics courses introduce the study of likely events and the analysis, interpretation, and presentation of quantitative data. Course topics generally include basic probability and statistics: discrete probability theory, odds and probabilities, probability trees, populations and samples, frequency tables, measures of central tendency and variation, and presentation of data (including graphs). Course topics may also include normal distribution and measures of variability.", "u": null, "notes": "concept: NI001517163308", "dep": null}, {"v": "02202", "n": "Inferential Probability and Statistics", "d": "Probability and Statistics courses focus on descriptive statistics, with an introduction to inferential statistics. Topics typically include event probability, normal probability distribution, collection and description of data, frequency tables and graphs, measures of central tendency and variability, random variables, and random sampling. Course topics may also include covariance and correlation, central limit theorem, confidence intervals, and hypothesis testing.", "u": null, "notes": "concept: NI001517163309", "dep": null}, {"v": "02135", "n": "IB Mathematics, Middle Years Program", "d": "International Baccalaureate (IB) Mathematics, Middle Years Program courses are built on a framework of five branches of mathematics: number, algebra, geometry and trigonometry, statistics and probability, and discrete mathematics. The program encourages students to develop an understanding of mathematical reasoning and processes, the ability to apply mathematics and evaluate the significance of results, the ability to develop strategies for problems in which solutions are not obvious, and the acquisition of mathematical intuition.", "u": null, "notes": "concept: NI001517163310", "dep": null}, {"v": "02136", "n": "Finite Mathematics", "d": "Finite Mathematics acquaints students with a variety of noncalculus mathematical topics including linear functions and programming, methods to solve linear and quadratic equations and inequalities, matrices, set theory, counting techniques, and basic concepts of probability and statistics (including measures of central tendency and variation).", "u": null, "notes": "concept: NI001517163311", "dep": null}, {"v": "02137", "n": "Mathematical Modeling", "d": "Mathematical Modeling courses build upon students' knowledge of algebra and geometry to analyze information and make sense of data using statistical methods and probability, simulate change using mathematical relationships and spatial and geometric modeling, and critically assess and make decisions or solve problems based on quantitative data and logical reasoning.", "u": null, "notes": "concept: NI001517163312", "dep": null}, {"v": "02138", "n": "College Mathematics Preparation", "d": "College Mathematics Preparations courses solidify quantitative literacy through the use and extension of algebraic, geometric, and statistical concepts. These courses prepare students for postsecondary liberal studies mathematics coursework; they are not intended to serve as remedial mathematics courses. Course content typically includes algebraic operations, solutions of equations and inequalities, number sets, coordinate geometry, functions and graphs, probability and statistics, and data representation.", "u": null, "notes": "concept: NI001517163313", "dep": null}, {"v": "02141", "n": "Particular Topics in Analytic Mathematics", "d": "These courses examine particular topics in analytic mathematics (such as mathematical proofs and structures or numerical analysis), not otherwise described above.", "u": null, "notes": "concept: NI001517163314", "dep": null}, {"v": "02149", "n": "Analytic Mathematics�Other", "d": "Other Analytic Mathematics courses.", "u": null, "notes": "concept: NI001517163315", "dep": null}, {"v": "02151", "n": "General Applied Mathematics", "d": "General Applied Mathematics courses reinforce general mathematics skills; extend these skills to include some pre-algebra and algebra topics; and use these skills in a variety of practical, consumer, business, and occupational applications. While these courses prepare students for a variety of practical applications, they are not intended to serve as remedial mathematics courses. Course topics typically include rational numbers, measurement, basic statistics, ratio and proportion, basic geometry, formulas, and simple equations.", "u": null, "notes": "concept: NI001517163316", "dep": null}, {"v": "02152", "n": "Occupationally Applied Mathematics", "d": "Occupationally Applied Mathematics courses reinforce general mathematics skills, extend these skills to include some pre-algebra and algebra topics, and use these skills primarily in occupational applications. While these courses prepare students for a variety of occupational applications, they are not intended to serve as remedial mathematics courses. Course topics typically include rational numbers, measurement, basic statistics, ratio and proportion, basic geometry, formulas, and simple equations.", "u": null, "notes": "concept: NI001517163317", "dep": null}, {"v": "02153", "n": "Technical Mathematics", "d": "Technical Mathematics courses extend students' proficiency in mathematics, and often apply these skills to technical and/or industrial situations and problems. While these courses prepare students for a variety of technical applications, they are not intended to serve as remedial mathematics courses. Technical Mathematics topics may include but are not limited to rational numbers; systems of measurements; tolerances; numerical languages; geometry; algebra; statistics; and using tables, graphs, charts, and other data displays. Technology is integrated as appropriate.", "u": null, "notes": "concept: NI001517163318", "dep": null}, {"v": "02154", "n": "Business Mathematics", "d": "Business Mathematics courses reinforce general mathematics skills, emphasize speed and accuracy in computations, and use these skills in a variety of business applications. While these courses prepare students for a variety of business applications, they are not intended to serve as remedial mathematics courses. Business Mathematics courses reinforce general mathematics topics (e.g., arithmetic, measurement, statistics, ratio and proportion, exponents, formulas, and simple equations) by applying these skills to business problems and situations. Applications might include wages, hourly rates, payroll deductions, sales, receipts, accounts payable and receivable, financial reports, discounts, and interest.", "u": null, "notes": "concept: NI001517163319", "dep": null}, {"v": "02155", "n": "Business Mathematics with Algebra", "d": "Business Mathematics with Algebra courses teach and have students apply algebra concepts to a variety of business and financial situations. Applications usually include income, insurance, credit, banking, taxation, stocks and bonds, and finance.", "u": null, "notes": "concept: NI001517163320", "dep": null}, {"v": "02156", "n": "Computer Mathematics with Algebra", "d": "Intended for students who have attained the objectives of Algebra I, Computer Mathematics with Algebra courses include a study of computer systems and programming, and use the computer to solve mathematics problems.", "u": null, "notes": "concept: NI001517163321", "dep": null}, {"v": "02157", "n": "Consumer Mathematics", "d": "Consumer Mathematics courses reinforce general mathematics topics (such as arithmetic using rational numbers, measurement, ratio and proportion, and basic statistics) and apply these skills to consumer problems and situations. While these courses prepare students for a variety of practical applications, they are not intended to serve as remedial mathematics courses. Applications typically include budgeting, taxation, credit, banking services, insurance, buying and selling products and services, home and/or car ownership and rental, managing personal income, and investment.", "u": null, "notes": "concept: NI001517163322", "dep": null}, {"v": "02203", "n": "AP Statistics", "d": "Following the College Board's suggested curriculum designed to parallel college-level statistics courses, AP Statistics courses introduce students to the major concepts and tools for collecting, analyzing, and drawing conclusions from data. Students are exposed to four broad conceptual themes: exploring data, sampling and experimentation, anticipating patterns, and statistical inference.", "u": null, "notes": "concept: NI001517163323", "dep": null}, {"v": "03003", "n": "Environmental Science", "d": "Environmental Science courses examine the mutual relationships between organisms and their environment. In studying the interrelationships among plants, animals, and humans, these courses usually cover the following subjects: photosynthesis, recycling and regeneration, ecosystems, population and growth studies, pollution, and conservation of natural resources.", "u": null, "notes": "concept: NI001517163324", "dep": null}, {"v": "03004", "n": "Astronomy", "d": "Astronomy courses offer students the opportunity to study the solar system, stars, galaxies, and interstellar bodies. These courses usually introduce and use astronomic instruments and typically explore theories regarding the origin and evolution of the universe, space, and time.", "u": null, "notes": "concept: NI001517163325", "dep": null}, {"v": "03005", "n": "Marine Science", "d": "Courses in Marine Science focus on the content, features, and possibilities of the earth's oceans. They explore marine organisms, conditions, and ecology and sometimes cover marine mining, farming, and exploration.", "u": null, "notes": "concept: NI001517163326", "dep": null}, {"v": "03006", "n": "Meteorology", "d": "Meteorology courses examine the properties of the earth's atmosphere. Topics usually include atmospheric layering, changing pressures, winds, water vapor, air masses, fronts, temperature changes and weather forecasting.", "u": null, "notes": "concept: NI001517163327", "dep": null}, {"v": "03007", "n": "Physical Geography", "d": "Physical Geography courses equip students with an understanding of the constraints and possibilities that the physical environment places on human development. These courses include discussion of the physical landscape through geomorphology and topography, the patterns and processes of climate and weather, and natural resources.", "u": null, "notes": "concept: NI001517163328", "dep": null}, {"v": "03008", "n": "Earth and Space Science", "d": "Earth and Space Science courses introduce students to the study of the earth from a local and global perspective. In these courses, students typically learn about time zones, latitude and longitude, atmosphere, weather, climate, matter, and energy transfer. Advanced topics often include the study of the use of remote sensing, computer visualization, and computer modeling to enable earth scientists to understand earth as a complex and changing planet.", "u": null, "notes": "concept: NI001517163329", "dep": null}, {"v": "03009", "n": "Particular Topics in Earth Science", "d": "Particular Topics in Earth Science courses concentrate on a particular subtopic within the field of earth science (such as mineralogy) that is not otherwise described within this classification system.", "u": null, "notes": "concept: NI001517163330", "dep": null}, {"v": "03010", "n": "Earth/Space Science (prior-to-secondary)", "d": "Earth/Space Science (prior-to-secondary) covers basic principles of earth and space science. These may include plate tectonics, rocks and the rock cycle, weather, ocean currents, movements of the Earth, moon, and planets, components of the galaxy and universe, or other topics consistent with state academic standards for earth and space science.", "u": null, "notes": "concept: NI001517163331", "dep": null}, {"v": "03011", "n": "Physical Science (prior-to-secondary)", "d": "Physical Science (prior-to-secondary) courses cover basic principles of physical science, such as matter, energy, force, and motion. Topics may include conservation of energy and matter, the atomic model, the periodic table, electricity, or other topics consistent with state academic standards for physical science.", "u": null, "notes": "concept: NI001517163332", "dep": null}, {"v": "03012", "n": "Energy and the Environment", "d": "Energy and the Environment courses expose students to the scientific principles associated with energy transformation, collection, extraction, transmission and storage. Course content may emphasize energy's significance in society and the effects of its use on the environment. Topics may include the distribution, availability, patterns of use, and environmental impacts of energy resources.", "u": null, "notes": "concept: NI001517163333", "dep": null}, {"v": "02204", "n": "Particular Topics in Probability and Statistics", "d": "These courses examine particular topics in Probability and Statistics, such as regression or hierarchical linear modeling, rather than provide a general overview.", "u": null, "notes": "concept: NI001517163334", "dep": null}, {"v": "02205", "n": "Statistics", "d": "Statistics courses involve the major concepts and methods used to collect, analyze, and draw conclusions from data. Topics typically include populations and samples, measures of central tendency and variability, hypothesis testing, presentation, and making statistical inferences.", "u": null, "notes": "concept: NI001517163335", "dep": null}, {"v": "02207", "n": "Probability and Statistics�Independent Study", "d": "Probability and Statistics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to probability and statistics. These courses may be offered in conjunction with other rigorous math courses, or may serve as an opportunity to explore a topic of special interest. They may also serve as an opportunity to prepare for AP exams if the school does not offer specific courses for that endeavor.", "u": null, "notes": "concept: NI001517163336", "dep": null}, {"v": "02209", "n": "Probability and Statistics�Other", "d": "Other Probability and Statistics courses", "u": null, "notes": "concept: NI001517163337", "dep": null}, {"v": "02991", "n": "History of Mathematics", "d": "History of Mathematics courses include a study of the historical development of numbers, computation, algebra, and geometry. Figures critical to the development of mathematics or important developments (e.g., pi, decimal fractions, probability theory, calculus) often form the backbone of these classes.", "u": null, "notes": "concept: NI001517163338", "dep": null}, {"v": "02993", "n": "Mathematics�Test Preparation", "d": "Mathematics�Test Preparation courses provide students with activities in analytical thinking and with the skills and strategies associated with standardized test taking (such as the PSAT, SAT, and ACT). Topics covered include strategies for arithmetic, algebra, geometry, and quantitative comparison problems as well as time management, scoring procedures, calculator usage, and management of test-related stress.", "u": null, "notes": "concept: NI001517163339", "dep": null}, {"v": "02994", "n": "Mathematics Proficiency Development", "d": "Mathematics Proficiency Development courses are designed to assist students in acquiring the skills necessary to pass proficiency examinations.", "u": null, "notes": "concept: NI001517163340", "dep": null}, {"v": "02995", "n": "Mathematics�Aide", "d": "Mathematics�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course materials. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163341", "dep": null}, {"v": "02996", "n": "Mathematics�Supplemental", "d": "Mathematics�Supplemental courses, designed to be taken in addition to or in coordination with other mathematics courses, provide instruction to assist students in acquiring mathematic skills so that students attain necessary grade-level skills or reach a desired competency level.", "u": null, "notes": "concept: NI001517163342", "dep": null}, {"v": "02997", "n": "Mathematics�Independent Study", "d": "Mathematics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to mathematics. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163343", "dep": null}, {"v": "02998", "n": "Mathematics�Workplace Experience", "d": "Mathematics�Workplace Experience courses provide students with work experience in a field related to mathematics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163344", "dep": null}, {"v": "02999", "n": "Mathematics�Other", "d": "Other Mathematics courses.", "u": null, "notes": "concept: NI001517163345", "dep": null}, {"v": "03001", "n": "Earth Science", "d": "Earth Science courses offer insight into the environment on earth and the earth's environment in space. While presenting the concepts and principles essential to students' understanding of the dynamics and history of the earth, these courses usually explore oceanography, geology, astronomy, meteorology, and geography.", "u": null, "notes": "concept: NI001517163346", "dep": null}, {"v": "03002", "n": "Geology", "d": "Geology courses provide an in-depth study of the forces that formed and continue to affect the earth's surface. Earthquakes, volcanoes, and erosion are examples of topics that are presented.", "u": null, "notes": "concept: NI001517163347", "dep": null}, {"v": "03047", "n": "Earth Science�Independent Study", "d": "Earth Science�Independent Study courses, often conducted with instructors as mentors, enable students to explore scientific topics of interest, using advanced methods of scientific inquiry and experimentation. These courses may be offered in conjunction with other science courses or may serve as an opportunity to explore a topic of special interest.", "u": null, "notes": "concept: NI001517163348", "dep": null}, {"v": "03063", "n": "Particular Topics in Biology", "d": "Particular Topics in Biology courses concentrate on a particular subtopic within the field of biology (such as botany, zoology, genetics, and so on) that is not otherwise described within this classification system.", "u": null, "notes": "concept: NI001517163349", "dep": null}, {"v": "03064", "n": "Regional Biology", "d": "Regional Biology courses are designed to provide information regarding the fundamental concepts of life and life processes as related to the local environment. Course topics may include nature appreciation, local flora and fauna, biology, and zoology.", "u": null, "notes": "concept: NI001517163350", "dep": null}, {"v": "05147", "n": "Music�Independent Study", "d": "Music�Independent Study courses, often conducted with instructors, professional musicians, or voice coaches as mentors, enable students to explore music-related topics. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular form or style, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163650", "dep": null}, {"v": "05148", "n": "Music�Workplace Experience", "d": "Music�Workplace Experience courses provide students with work experience in a field related to music. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163651", "dep": null}, {"v": "05149", "n": "Music�Other", "d": "Other Music courses.", "u": null, "notes": "concept: NI001517163652", "dep": null}, {"v": "05151", "n": "Art Appreciation", "d": "Art Appreciation courses introduce students to the historical study of and foundation for many forms of art. These courses help students form an aesthetic framework to examine social, political, and historical events in the world and how visual images express the ideas of individuals and society. Students are involved in the creative process through research and lecture, responding and dialogue, observation and interpretation with art works and artifacts.", "u": null, "notes": "concept: NI001517163653", "dep": null}, {"v": "05160", "n": "Printmaking/Graphics", "d": "Printmaking/Graphics courses emphasize applying the fundamental processes of artistic expression to both printmaking and visual communications design. These courses help students investigate printmaking media, techniques, and processes, in addition to providing instruction about the purposeful arrangement of images, symbols, and text to communicate a message. Printmaking/Graphics courses also include a study of historical and contemporary printmaking and visual communications design and provide instruction in the critique process.", "u": null, "notes": "concept: NI001517163654", "dep": null}, {"v": "05161", "n": "Printmaking", "d": "Printmaking courses provide students with experience in a variety of traditional, non-traditional and digital printmaking media, techniques, and processes. These courses emphasize fundamental processes of artistic expression through the creation of realistic and abstract prints. Students learn and practice responding to their own art and that of others including master printmakers through analysis, critique, and interpretation for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163655", "dep": null}, {"v": "05162", "n": "Visual Communications Design", "d": "Formerly known as Graphic Design, Visual Communications Design courses emphasize applying fundamental processes of artistic expression through the exploration of the purposeful arrangement of images, symbols, and text to communicate a message. These courses may include investigations of how technology influences the creation of graphic and digital designs and study historical and contemporary visual communications design. These courses also provide instruction in the process of responding to their own art and that of others including master designers through analysis, critique, and interpretation for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163656", "dep": null}, {"v": "05163", "n": "Advertising Design", "d": "Advertising Design courses emphasize applying the fundamental processes of artistic expression used in the fields of advertising and commercial art for the purpose of visual communication. These courses offer practical experiences in generating advertisements, commercial art, logos, executing layouts, illustrations, displays, lettering, and works with a variety of media, techniques, and processes. They also include preparing artwork for reproduction and presentation. Advertising Design courses present an historical and contemporary view of advertising art and commercial art. Students learn and practice responding to their own art and that of others including professional designers through analysis, critique, and interpretation for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163657", "dep": null}, {"v": "05164", "n": "Fibers and Textile Design", "d": "Formerly known as Textiles, Fibers and Textile Design courses emphasize applying the fundamental processes of artistic expression in creating textiles and fiber works using fiber and fiber-related media, techniques, and processes. These courses may help students understand the suitability of design to materials and the artist's intent in creating textile works of art. Students may create their own work following and breaking from traditional conventions. They may also include the study of the history of fiber and textile art from a worldwide perspective. Students respond to their art and that of others including professional fiber artists through analysis, critique, and interpretation for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163658", "dep": null}, {"v": "05154", "n": "Visual Arts�Comprehensive", "d": "Visual Arts�Comprehensive courses enable students to explore one or several art forms (e.g., drawing, painting, two- and three-dimensional design, and sculpture) and to create individual works of art. Initial courses emphasize observations, interpretation of the visual environment, visual communication, imagination, and symbolism. Courses cover the language, materials, media, and processes of a particular art form and the design elements used. Advanced courses encourage students to refine their skills while also developing their own artistic styles following and breaking from traditional conventions. Courses may also include the study of major artists, art movements, and styles.", "u": null, "notes": "concept: NI001517163659", "dep": null}, {"v": "05185", "n": "Art (grade 5)", "d": "Art (grade 5) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, make connections to other content areas, develop their own aesthetic, and strengthen their critical abilities. Although typically involving the visual arts (drawing, painting, sculpture, crafts, and the like), these courses may also include other forms of art (for example, dance, music, and theater). Specific course content conforms to any existing state standards for grade 5.", "u": null, "notes": "concept: NI001517163660", "dep": null}, {"v": "05186", "n": "Art (grade 6)", "d": "Art (grade 6) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, make connections to other content areas, develop their own aesthetic, and strengthen their critical abilities. Although typically involving the visual arts (drawing, painting, sculpture, crafts, and the like), these courses may also include other forms of art (for example, dance, music, and theater). Specific course content conforms to any existing state standards for grade 6.", "u": null, "notes": "concept: NI001517163661", "dep": null}, {"v": "05194", "n": "IB Film", "d": "IB Film courses prepare students to take the International Baccalaureate Film exams. IB Film courses develop students' understanding and appreciation of the craft of film through the construction and deconstruction of film text. Course content includes textual analysis of film sequences, film theory and history, and the creative process of producing films.", "u": null, "notes": "concept: NI001517163685", "dep": null}, {"v": "05187", "n": "Art (grade 7)", "d": "Art (grade 7) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, make connections to other content areas, develop their own aesthetic, and strengthen their critical abilities. Although typically involving the visual arts (drawing, painting, sculpture, crafts, and the like), these courses may also include other forms of art (for example, dance, music, and theater). Specific course content conforms to any existing state standards for grade 7.", "u": null, "notes": "concept: NI001517163662", "dep": null}, {"v": "05155", "n": "Visual Arts�Drawing/Painting", "d": "Visual Arts�Drawing/Painting courses focus on the inter-relationships that occur between drawing and painting using a variety of media and techniques, emphasizing observation and interpretation of the visual environment. These courses typically include applying the elements of art and principles of design, along with a study of art and artists from a worldwide perspective, and instruction in the critique process. Advanced courses may encourage students to refine their creative process and develop their own artistic styles following and breaking from traditional conventions.", "u": null, "notes": "concept: NI001517163663", "dep": null}, {"v": "05156", "n": "Visual Arts�Drawing", "d": "Visual Arts�Drawing courses provide a foundation in drawing using a variety of techniques and media (such as pen-and-ink, pencil, chalk, and so on) in both black and white and color, emphasizing observation and interpretation of the visual environment, life drawing, and imaginative drawing. These courses typically include applying the elements of art and principles of design, along with a study of art and artists from a worldwide perspective, and instruction in the critique process. Advanced courses may encourage students to refine their creative processes and develop their own artistic styles following and breaking from traditional conventions.", "u": null, "notes": "concept: NI001517163664", "dep": null}, {"v": "05157", "n": "Visual Arts�Painting", "d": "Visual Arts�Painting courses provide a foundation in painting using a variety of techniques and media (such as watercolor, tempera, oils, acrylics), emphasizing observation and interpretation of the visual environment, life drawing, and imaginative painting. These courses typically include applying the elements of art and principles of design, along with a study of art and artists from a worldwide perspective, and instruction in the critique process. Advanced courses may encourage students to refine their creative processes and develop their own artistic styles following and breaking from traditional conventions.", "u": null, "notes": "concept: NI001517163665", "dep": null}, {"v": "05158", "n": "Visual Arts�Sculpture", "d": "Visual Arts�Sculpture courses promote creative expression through three-dimensional works. These courses explore representational and abstract sculpture through subtractive (carving), additive (modeling), and assemblage techniques in one or more media. Visual Arts�Sculpture courses typically include the production of representational and abstract sculptures while incorporating elements of art and principles of design, along with a study of historical and contemporary sculpture and sculptors from a worldwide perspective. These courses also provide instruction in the process of responding to art through analysis, critique, and interpretation for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163666", "dep": null}, {"v": "05159", "n": "Ceramics/Pottery", "d": "Ceramics/Pottery courses engage students in learning experiences that include the historical and cultural context of ceramics, aesthetic inquiry, and creative production. These courses provide knowledge of ceramic techniques (e.g., kiln firing and glazing) and processes with an emphasis on creative design and craftsmanship. Courses may include clay modeling, hand building, coil building, casting, and throwing on the potter's wheel.", "u": null, "notes": "concept: NI001517163667", "dep": null}, {"v": "05183", "n": "Art (grade 3)", "d": "Art (grade 3) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, and strengthen their critical abilities. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for grade 3.", "u": null, "notes": "concept: NI001517163668", "dep": null}, {"v": "05184", "n": "Art (grade 4)", "d": "Art (grade 4) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, make connections to other content areas, develop their own aesthetic, and strengthen their critical abilities. Although typically involving the visual arts (drawing, painting, sculpture, crafts, and the like), these courses may also include other forms of art (for example, dance, music, and theater). Specific course content conforms to any existing state standards for grade 4.", "u": null, "notes": "concept: NI001517163669", "dep": null}, {"v": "05170", "n": "Art Portfolio", "d": "Art Portfolio is designed to address a variety of factors and methods including evolving technologies when preparing and refining artwork for portfolio presentation and or when deciding if and how to preserve and protect art. Students will create, select, respond to, and present work that clearly reflects newly obtained technical skills, increasing conceptual thinking and is a reflection of their personal interests. These courses may include individual critiques and peer review.", "u": null, "notes": "concept: NI001517163670", "dep": null}, {"v": "05172", "n": "AP Drawing", "d": "AP Drawing is designed for students with a professional or academic interest in the art of drawing. These courses focus on a variety of concepts and approaches in drawing, enabling students to demonstrate a depth of knowledge of the processes, and a range of abilities, and versatility with media, technique, problem solving, and scope. They can demonstrate such conceptual variety through either the use of one or the use of several media.These courses enable students to refine their skills and create artistic works to submit via portfolio to the College Board for evaluation.", "u": null, "notes": "concept: NI001517163671", "dep": null}, {"v": "05173", "n": "IB Visual Arts", "d": "IB Visual Arts courses prepare students to take the International Baccalaureate (IB) Visual Arts exams. IB Visual Arts courses provide experiences that develop students' aesthetic and creative facukties, provide experiences in various visual art forms, offer training in awareness and criticism of art, and enable students to create their own quality works of art. Students perform both studio and research work; the research component is designed to investigate particular topics or concepts of interest in further detail. These courses were formerly known as IB Art/Design.", "u": null, "notes": "concept: NI001517163672", "dep": null}, {"v": "05174", "n": "AP 2-D Art and Design", "d": "AP 2-D Art and Design courses are designed for students with a professional or academic interest in two-dimensional art. These courses focus on a variety of concepts and approaches in drawing and 2-D design, enabling students to demonstrate a range of abilities and versatility with media, technique, problem solving, and scope. Such conceptual variety can be demonstrated through the use of one or several media. Students refine their skills and create artistic works to submit via a portfolio to the College Board for evaluation.", "u": null, "notes": "concept: NI001517163673", "dep": null}, {"v": "05175", "n": "AP 3-D Art and Design", "d": "AP 3-D Art and Design courses are designed for students with a professional or academic interest in three-dimensional art. These courses focus on a variety of concepts and approaches in 3-D design and creation, enabling students to demonstrate a range of abilities and versatility with media, technique, problem solving, and scope. They can demonstrate such conceptual variety through the use of one or several media. Students refine their skills and create artistic works to submit via portfolio to the College Board for evaluation.", "u": null, "notes": "concept: NI001517163674", "dep": null}, {"v": "05176", "n": "Calligraphy/Lettering", "d": "Calligraphy/Lettering courses teach various styles of inscribing letters, design developments by means of lettering, the romance of lettering through the ages, and modern use of lettering in advertising and art. These courses present historical and contemporary examples of calligraphy, typography, and lettering. Students engage in critiques and analysis of artists who practice these art forms, including professional calligraphers and typographers, and the relationship to the context in which they were created.", "u": null, "notes": "concept: NI001517163675", "dep": null}, {"v": "05188", "n": "Art (grade 8)", "d": "Art (grade 8) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, make connections to other content areas, develop their own aesthetic, and strengthen their critical abilities. Although typically involving the visual arts (drawing, painting, sculpture, crafts, and the like), these courses may also include other forms of art (for example, dance, music, and theater). Specific course content conforms to any existing state standards for grade 8.", "u": null, "notes": "concept: NI001517163676", "dep": null}, {"v": "05189", "n": "Art�General", "d": "Art�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Art, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163677", "dep": null}, {"v": "05190", "n": "Fashion Design", "d": "Fashion Design courses emphasize applying the fundamental processes of artistic expression in creating and merchandising apparel. Drawing the figure is a foundation of these courses. Students identify the relationships between design, clothing and expression of self through fashion statements. Courses may also include a study of historical and contemporary fashion design from a worldwide perspective. Students engage in critique of their designs, the designs of others, and those of professional fashion designers for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163678", "dep": null}, {"v": "05191", "n": "Industrial Design", "d": "Industrial Design courses emphasize applying the fundamental processes of artistic expression to designing manufactured products. Students analyze and apply a variety of media, techniques, and processes to improve the aesthetics, ergonomics, functionality, and/or usability of a product. Courses may also include an understanding of aesthetic issues associated with product design. Students study industrial designs throughout history, contemporary society, and many world cultures. Students engage in critique of their industrial designs, the designs of others, and designs by professional industrial designers for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163679", "dep": null}, {"v": "05192", "n": "Architectural Design", "d": "Architectural Design courses emphasize applying the fundamental processes of artistic expression to designing buildings, open areas, communities, and environments with an aesthetic effect. Students analyze and apply a variety of media, techniques, and processes to create architectural structures that incorporate aesthetics, functionality, and usability. Architectural Design courses may also include an understanding of aesthetic issues associated with designing such structures. Students study architectural designs throughout history, contemporary society, and many world cultures. Students engage in critique of their architectural designs, the designs of others, and designs by professional architects for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163680", "dep": null}, {"v": "05197", "n": "Visual Arts�Independent Study", "d": "Visual Arts�Independent Study courses, often conducted with instructors or professional artists as mentors, enable students to explore a particular art form or topic. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular form or style, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163686", "dep": null}, {"v": "11154", "n": "Commercial Graphic Design", "d": "Commercial Graphic Design courses teach students to use artistic techniques to effectively communicate ideas and information to business and customer audiences via illustration and other forms of digital or printed media. Topics covered may include concept design, layout, paste-up and techniques such as engraving, etching, silkscreen, lithography, offset, drawing and cartooning, painting, collage and computer graphics.", "u": null, "notes": "concept: NI001517163966", "dep": null}, {"v": "11155", "n": "Graphic Technology", "d": "Graphic Technology courses help students apply artistic and computer techniques to the interpretation of technical and commercial concepts. Topics covered may include computer assisted art and design, printmaking, concept sketching, technical drawing, color theory, imaging, studio techniques, still life modeling, and commercial art business operations. Advanced topics may include topographic arrangements of print and/or electronic graphic and textual products, printing and lithographic equipment and operations, digital imaging, print preparation, desktop publishing and web page design.", "u": null, "notes": "concept: NI001517163967", "dep": null}, {"v": "11156", "n": "Photography and Printing Technology", "d": "Photography and Printing Technology courses expose students to the tools, materials and processes involved in mass production of photography and printing. Types of printing covered in the course may include intaglio, relief, planographic, screen processes printing, silk screening, serigraphy processes and thermograph. Additional topics may include the use of cameras, composition, imposition, presswork, and computer aided publishing.", "u": null, "notes": "concept: NI001517163968", "dep": null}, {"v": "11157", "n": "Photoengraving", "d": "Photoengraving courses teach students to photograph illustration and other copy that cannot be set in type, to develop negatives, and to prepare photosensitized metal plates for use in printing.", "u": null, "notes": "concept: NI001517163969", "dep": null}, {"v": "11158", "n": "Print Press Operations", "d": "These courses expose students to the necessary skills for operating a print press. Topics covered in this course include how to prepare, operate and maintain printing processes.", "u": null, "notes": "concept: NI001517163970", "dep": null}, {"v": "11159", "n": "Particular Topics in Printing Technology and Production", "d": "These courses examine specific topics in printing production, such as bookbinding or silkscreen printmaking, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163971", "dep": null}, {"v": "11197", "n": "Printing Technology�Independent Study", "d": "Printing Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to the print medium. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163972", "dep": null}, {"v": "11198", "n": "Printing Technology�Workplace Experience", "d": "Printing Technology�Workplace Experience courses provide students with work experience in a field related to printing. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163973", "dep": null}, {"v": "11199", "n": "Printing Technology�Other", "d": "Other Printing Technology courses.", "u": null, "notes": "concept: NI001517163974", "dep": null}, {"v": "11995", "n": "Communication and Audio/Video Technology�Aide", "d": "Communication and Audio/Video Technology�Aide courses offer students the opportunity to assist instructors in preparing, organizing or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163975", "dep": null}, {"v": "11997", "n": "Communication and Audio/Video Technology�Independent Study", "d": "Communication and Audio/Video Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to mass communication and its technologies. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163976", "dep": null}, {"v": "12057", "n": "Human Resources and Labor Relations", "d": "Human Resources and Labor Relations courses focus on the managing of human resources essential to effective business operations. These courses cover such topics as the history of the labor movement in the United States, the nature of collective bargaining and conflict resolution in a unionized environment, and effective relationships between the employees of a business and the management.", "u": null, "notes": "concept: NI001517163977", "dep": null}, {"v": "12058", "n": "Human Resources Management", "d": "Human Resources Management courses provide students with an understanding of and skills in the effective use of leadership, management, communications, and interpersonal skills in achieving the goals of an organization.", "u": null, "notes": "concept: NI001517163978", "dep": null}, {"v": "12059", "n": "IB Business Management", "d": "IB Business Management courses prepare students to take the International Baccalaureate Business and Management exams. IB Business Management courses explore business decision-making processes and their relationship to internal and external environments. Course content includes business organization and environment, human resources, accounts and finance, marketing, and operations management.", "u": null, "notes": "concept: NI001517163979", "dep": null}, {"v": "12104", "n": "Accounting", "d": "Accounting courses introduce students to and expand their knowledge of the fundamental accounting principles and procedures used in businesses through integrating and using accounting-related software and information systems. Course content includes the recording and completion of the accounting cycle, payroll, taxes, debts, depreciation, and periodic adjustments through a computerized accounting program. Students may learn how to apply standard auditing principles and to prepare budgets and final reports. Calculators, electronic spreadsheets, or computer accounting software are usually used. Advanced topics may include principles of partnership and corporate accounting and the managerial uses of control systems and the accounting process.", "u": null, "notes": "concept: NI001517163980", "dep": null}, {"v": "12165", "n": "Principles of Advertising", "d": "Principles of Advertising courses expose students to the varied concepts underlying the promotion of products. The topics included in Principles of Advertising courses range considerably, but typically include the psychology of advertising, a study of various media, advertising planning and budgeting, and advertising layout and design principles. Course topics may also include an overview of commercial art and packaging.", "u": null, "notes": "concept: NI001517163981", "dep": null}, {"v": "12166", "n": "Marketing Management", "d": "Marketing Management courses typically cover the same scope of topics as Marketing� Comprehensive courses (purchasing and distribution systems; advertising and sales; and so on) but place a particular emphasis on business management and entrepreneurship, providing exposure to common techniques and problems of management.", "u": null, "notes": "concept: NI001517163982", "dep": null}, {"v": "12167", "n": "Marketing�Other Specialization", "d": "Marketing�Other Specialization courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer with attention to a particular industry not specified above. Topics may include purchasing and distribution systems, promotion, advertising, display and sales, financing, management, entrepreneurship, market research, pricing, global marketing, human relations, economics, and emerging technologies. These courses may also cover specific topics related to the particular industry being covered.", "u": null, "notes": "concept: NI001517163983", "dep": null}, {"v": "12105", "n": "Business Economics", "d": "Business Economics courses integrate economic principles (such as free market economy, consumerism, and the role of the U.S. government within the economic system) with entrepreneurship/business concepts (such as marketing principles, business law, and risk).", "u": null, "notes": "concept: NI001517163984", "dep": null}, {"v": "12106", "n": "Risk Management and Insurance", "d": "Risk Management and Insurance courses provide information about various risk management tools and techniques and may cover the perspective of insurance professionals and business owners. These courses may emphasize the specific uses, costs, and effectiveness of insurance products.", "u": null, "notes": "concept: NI001517163985", "dep": null}, {"v": "12107", "n": "Securities and Investments", "d": "Formerly known as Investing, Securities and Investments courses emphasize the formulation of business and individual investment decisions by comparing and contrasting the investment qualities of cash, stock, bonds, and mutual funds. Students typically review annual reports, predict growth rates, and analyze trends. Stock market simulations are often incorporated into these courses.", "u": null, "notes": "concept: NI001517163986", "dep": null}, {"v": "12108", "n": "Cost Accounting", "d": "Cost Accounting courses introduce students to the accounting concepts of manufacturing systems. In addition to job order and process costing systems, these courses emphasize profit planning and control programs.", "u": null, "notes": "concept: NI001517163987", "dep": null}, {"v": "12109", "n": "Income Tax Accounting", "d": "Income Tax Accounting courses introduce students to and expand their knowledge of the fundamental accounting principles and procedures used in businesses through integrating and using accounting-related software and information systems. These courses focus on federal, state, and local business tax laws; business tax accounting methods; and the preparation of business tax forms.", "u": null, "notes": "concept: NI001517163988", "dep": null}, {"v": "12110", "n": "Payroll Accounting", "d": "Payroll Accounting courses introduce students to and expand their knowledge of the fundamental accounting principles and procedures related to payroll transactions for businesses. These courses typically emphasize computing wages, social security taxes, income tax withholding, unemployment taxes, and recording payroll transactions while providing students with experience in preparing all the necessary monthly, quarterly, and annual reports.", "u": null, "notes": "concept: NI001517163989", "dep": null}, {"v": "12111", "n": "Particular Topics in Accounting", "d": "These courses examine particular topics, such as auditing or non-profit accounting, rather than provide a general overview.", "u": null, "notes": "concept: NI001517163990", "dep": null}, {"v": "12147", "n": "Finance�Independent Study", "d": "Finance�Independent Study courses, often conducted with instructors as mentors, enable students to explore business finance-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163991", "dep": null}, {"v": "12148", "n": "Finance�Workplace Experience", "d": "Finance�Workplace Experience courses provide students with work experience in fields related to finance. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163992", "dep": null}, {"v": "12149", "n": "Finance�Other", "d": "Other Finances courses.", "u": null, "notes": "concept: NI001517163993", "dep": null}, {"v": "12151", "n": "Marketing Career Exploration", "d": "Marketing Career Exploration courses expose students to the opportunities available in retail, wholesale, advertising, and other occupational fields using marketing principles.", "u": null, "notes": "concept: NI001517163994", "dep": null}, {"v": "12152", "n": "Marketing�Comprehensive", "d": "Marketing�Comprehensive courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer. Topics may include, but are not limited to, market research, the purchasing process, distribution systems, warehouse and inventory control, salesmanship, sales promotions, shoplifting and theft control, business management, and entrepreneurship. Human relations, computers, and economics are sometimes covered as well.", "u": null, "notes": "concept: NI001517163995", "dep": null}, {"v": "12153", "n": "Marketing�Fashion", "d": "Marketing�Fashion courses typically address basic knowledge of the apparel and accessories industry and the skills necessary for successful employment in apparel and accessory businesses. Students develop general marketing skills necessary for successful employment in fashion marketing, general marketing skills applicable to the apparel and accessories industry, and specialized skills unique to fashion marketing. Personal selling, sales promotion, purchasing, physical distribution, market planning, existing and emerging technology, and product/service management are usually included.", "u": null, "notes": "concept: NI001517163996", "dep": null}, {"v": "12154", "n": "Marketing�Real Estate", "d": "Marketing�Real Estate courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the real estate industry. Topics may include purchasing, advertising, sales, human relations, management, and entrepreneurship but with particular attention to the real estate industry. Emphasis may be placed on financing, investment, ownership rights, ethics, and other real estate principles.", "u": null, "notes": "concept: NI001517163997", "dep": null}, {"v": "12155", "n": "Marketing�Transportation", "d": "Marketing�Transportation courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the transportation industry. Topics may include purchasing and distribution systems, advertising, display and sales, management, and entrepreneurship with particular attention to the transportation industry. Emphasis may be placed on the identification and proper use of auto parts and accessories and the sales and service of new and used cars, vans, trucks, and related parts.", "u": null, "notes": "concept: NI001517163998", "dep": null}, {"v": "12156", "n": "Marketing�Food/Beverage Industry", "d": "Marketing�Food/Beverage Industry courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the food and beverage industry. Topics may include purchasing and distribution systems, advertising, display and sales, management, and entrepreneurship. Emphasis may be placed on the unique characteristics and functions of the food and beverage service industry.", "u": null, "notes": "concept: NI001517163999", "dep": null}, {"v": "12157", "n": "Marketing�Insurance", "d": "Marketing�Insurance courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the insurance industry. Topics may include purchasing and distribution systems, advertising, display and sales, management, and entrepreneurship. Emphasis may be placed on various categories of insurance including accident, health, life, marine, automobile, and causality insurance.", "u": null, "notes": "concept: NI001517164000", "dep": null}, {"v": "12158", "n": "Marketing�Floristry", "d": "Marketing�Floristry courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the floral industry. Topics may include purchasing and distribution systems, advertising, display and sales, management, and entrepreneurship. Emphasis may be placed on the unique characteristics and functions of retail and wholesale floral operations.", "u": null, "notes": "concept: NI001517164001", "dep": null}, {"v": "12159", "n": "Marketing�Hospitality/Tourism", "d": "Marketing�Hospitality/Tourism courses focus on the wide range of factors that influence the flow of goods and services from the producer to the consumer in the travel, tourism, and lodging industries. Topics may include purchasing and distribution systems, advertising, display and sales, management, and entrepreneurship. Emphasis may be placed on the unique characteristics and functions of travel services and hotel/motel operations.", "u": null, "notes": "concept: NI001517164002", "dep": null}, {"v": "12160", "n": "Marketing�Merchandising", "d": "Marketing�Merchandising courses address marketing in a retail/e-tail environment focusing on the buying and merchandising of products. Content includes, but is not limited to, marketing information management (including marketing research), market planning, channel management, sales, promotion, product/service management, and pricing.", "u": null, "notes": "concept: NI001517164003", "dep": null}, {"v": "12161", "n": "Retail Marketing", "d": "Retail Marketing courses cover marketing principles and concepts related to the provision of goods or services directly to the consumer, emphasizing store operation, advertisement and display of goods, store security, human relations, and business management and ownership.", "u": null, "notes": "concept: NI001517164004", "dep": null}, {"v": "12162", "n": "Internet Marketing", "d": "Internet Marketing covers the principles and functions of marketing from the standpoint of conducting business on the internet. Typically, students develop such skills as using the internet as a marketing tool, conducting a marketing analysis via the internet, planning marketing support activities, managing an electronic marketing campaign, managing/owning a business via the internet, and analyzing the impact of the internet on global marketing.", "u": null, "notes": "concept: NI001517164005", "dep": null}, {"v": "12163", "n": "Sports and Entertainment Marketing", "d": "Sports and Entertainment Marketing courses provide students with a thorough understanding of fundamental marketing and management concepts and theories as they relate to the sports and entertainment industries. Content may address promotion of sports/events, licensing, sponsorship and endorsements, branding, marketing research, product development, pricing and distribution strategies, sales, event planning, and the role of existing and emerging technologies. These courses may also encourage students to develop job skills and explore career options.", "u": null, "notes": "concept: NI001517164006", "dep": null}, {"v": "12164", "n": "Principles of Marketing", "d": "Principles of Marketing courses offer students insight into the processes affecting the flow of goods and services from the producer to the consumer. Course content ranges considerably as general marketing principles such as purchasing, distribution, and sales are covered; however, a major emphasis is often placed on kinds of markets; market identification; product planning, packaging, and pricing; and business management.", "u": null, "notes": "concept: NI001517164007", "dep": null}, {"v": "12168", "n": "Marketing �Commodities", "d": "Marketing �Commodities courses investigate the meaning and methods of marketing as related to agricultural commodities, products and services, and agricultural goods in domestic and international markets. Topics typically include appropriate market research; benefit/cost analysis of marketing; and methods of targeted agricultural marketing in domestic and international markets.", "u": null, "notes": "concept: NI001517164008", "dep": null}, {"v": "18303", "n": "Plant Processing", "d": "Plant Processing courses impart the knowledge and skills needed to bring plant products to market. They may cover a wide variety of topics, including plant production, quality selection and preservation, equipment care and sanitation, government regulations, and marketing and consumer trends. Plant Processing courses may present an overview of product processing or may specialize in specific plant products.", "u": null, "notes": "concept: NI001517164303", "dep": null}, {"v": "18304", "n": "Animal Processing", "d": "Animal Processing courses impart the knowledge and skills needed to bring animal products to market. Although these courses may present an overview of animal care and maintenance, they typically emphasize quality selection, product preservation, equipment care and sanitation, government regulations, and marketing and consumer trends. Animal Processing courses may present an overview of several types of animal products or may specialize in particular products, such as meat, leather, wool, dairy products, and so on.", "u": null, "notes": "concept: NI001517164304", "dep": null}, {"v": "18997", "n": "Agriculture, Food, and Natural Resources�Independent Study", "d": "Courses in Agriculture, Food, and Natural Resources�Independent Study, often conducted with instructors as mentors, enable students to explore topic of interest related to agriculture, food, and natural resources. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164305", "dep": null}, {"v": "18998", "n": "Agriculture, Food, and Natural Resources�Workplace Experience", "d": "Agriculture, Food, and Natural Resources�Workplace Experience courses provide students with work experience in fields related to agriculture, food, and natural resources. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164306", "dep": null}, {"v": "18999", "n": "Agriculture, Food, and Natural Resources�Other", "d": "Other Agriculture, Food, and Natural Resources courses.", "u": null, "notes": "concept: NI001517164307", "dep": null}, {"v": "19001", "n": "Human Services Career Exploration", "d": "Human Services Career Exploration courses introduce and expose students to career opportunities pertaining to the provision of individual, family, personal, and consumer services for other human beings. Course topics vary and may include, but are not limited to, child development and services, counseling and mental health services, family and community services, personal care services, and consumer services. Course activities depend upon the careers being explored.", "u": null, "notes": "concept: NI001517164308", "dep": null}, {"v": "19051", "n": "Child Care", "d": "Child Care courses provide students with knowledge about the physical, mental, emotional, and social growth and development of children from birth through pre-school age. Main topics include the fundamentals of working with infants, toddlers, and older children; providing healthy environments; evaluating child care settings; and examining the practices, regulations, and opportunities in the child care industry. Often Child Care courses provide students with practical experience, including observation time in a child care center. Advanced topics may include various learning theories; development of activities; operation of a child care center; recognition of childhood diseases, abuse, and neglect; and first aid/emergency training.", "u": null, "notes": "concept: NI001517164309", "dep": null}, {"v": "18449", "n": "Agricultural Mechanics and Construction�Other", "d": "Other Agricultural Mechanics and Construction courses.", "u": null, "notes": "concept: NI001517164310", "dep": null}, {"v": "18501", "n": "Wildlife and Recreation Management", "d": "Formerly known as Wildlife Management, Wildlife and Recreation Management courses provide students with the opportunity to understand and appreciate the importance of maintaining the land and ecological systems that enable nondomesticated animals to thrive. These courses emphasize how humans and animals may both take advantage of the same land or how to gain economic benefits from the land while not degrading its natural resources or depleting plant or animal populations. Students may also learn how to manage wildlife and lands for recreational purposes.", "u": null, "notes": "concept: NI001517164311", "dep": null}, {"v": "19106", "n": "Cosmetology�Facial Specialization", "d": "Cosmetology�Facial Specialization courses offer students information and experience related to skin care, the provision of facials, make-up application, and facial massage. These courses may also include topics such as hygiene and sanitation, human anatomy and skin conditions, entrepreneurship, and/or human relations.", "u": null, "notes": "concept: NI001517164317", "dep": null}, {"v": "18502", "n": "Forestry Management", "d": "Formerly known as Forestry, Forestry Management courses provide students with the information and experience necessary for the cultivation, management, and care of forests or timberlands. These courses cover topics such as the processes of regeneration and reforestation, harvesting and conservation of natural resources, erosion and pest control, trail development and maintenance, mapping and surveying, operation of forestry tools, government regulations, environmental stewardship, and urban forestry, including the principles of selecting, planting, and caring for trees in urban settings. Settings may include streets, parks, commercial/industrial landscape settings, and recreational use of forests. These courses also address forestry harvesting and methods to manage, protect, and harvest timber stands and specialty forest crops; equipment maintenance and repair; the selection, planting, transplanting, and harvesting of trees; forest management; and safety procedures.", "u": null, "notes": "concept: NI001517164312", "dep": null}, {"v": "18504", "n": "Natural Resources Management", "d": "Natural Resources Management courses combine the fields of ecology and conservation with planning for the efficient use and preservation of land, water, wildlife, and forests. Within the general area of natural resources management, these courses usually cover specific topics and uses, such as hunting or fishing preserves, safe usage initiatives, forest production and management, wildlife preservation, and commercial use of natural resources.", "u": null, "notes": "concept: NI001517164313", "dep": null}, {"v": "18505", "n": "Particular Topics in Natural Resources", "d": "These courses examine specific topics related to natural resources, such as urban forestry or hunter education, rather than provide a general study of natural resource principles and topics.", "u": null, "notes": "concept: NI001517164314", "dep": null}, {"v": "18506", "n": "Alternative Energy", "d": "Alternative Energy courses help students identify renewable and nonrenewable energy sources and natural resources. Topics typically include alternative energy sources and their respective advantages and disadvantages; the impact of conventional and alternative energy sources on the environment; the efficiency of energy production from various sources; and careers in the fields of alternative energy and sustainability.", "u": null, "notes": "concept: NI001517164315", "dep": null}, {"v": "19105", "n": "Cosmetology�Nail Specialization", "d": "Cosmetology�Nail Specialization courses offer students experience in providing manicures, pedicures, and nail extension treatments. These courses may also include topics such as hygiene, entrepreneurship, human relations, and other related subject matter.", "u": null, "notes": "concept: NI001517164316", "dep": null}, {"v": "19107", "n": "Particular Topics in Cosmetology", "d": "These courses examine specific topics related to cosmetology not otherwise described elsewhere in this classification system, such as electrolysis, rather than providing a general study.", "u": null, "notes": "concept: NI001517164318", "dep": null}, {"v": "19147", "n": "Cosmetology�Independent Study", "d": "Cosmetology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to cosmetology. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164319", "dep": null}, {"v": "19148", "n": "Cosmetology�Workplace Experience", "d": "Cosmetology�Workplace Experience courses provide students with work experience in the cosmetology field. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164320", "dep": null}, {"v": "19149", "n": "Cosmetology�Other", "d": "Other Cosmetology courses.", "u": null, "notes": "concept: NI001517164321", "dep": null}, {"v": "19151", "n": "Teaching Profession", "d": "Teaching Profession courses introduce students to the principles underlying teaching and learning, the responsibilities and duties of teachers, and the techniques of imparting knowledge and information. These courses typically expose students to and train them in classroom management, student behavior, leadership and human relations skills, assessment of student progress, teaching strategies, and various career opportunities in the field of education.", "u": null, "notes": "concept: NI001517164322", "dep": null}, {"v": "19152", "n": "Educational Methodology", "d": "Educational Methodology courses prepare students to teach and guide others. These courses typically provide opportunities for students to develop their own teaching objectives, to design lesson plans, and to experience teaching in a controlled environment. Students examine and practice teaching strategies, learning styles, time management and planning strategies, presentation and questioning skills, classroom management, and evaluation techniques.", "u": null, "notes": "concept: NI001517164323", "dep": null}, {"v": "19153", "n": "Teaching�Early Childhood Education", "d": "Formerly known as Early Childhood Education, Teaching�Early Childhood Education courses address child development and education issues, so that students can guide the development of children in educational settings. These courses typically include the planning and implementing of developmentally appropriate learning activities, health and safety practices, safe learning environments, and legal requirements for teaching young children.", "u": null, "notes": "concept: NI001517164324", "dep": null}, {"v": "19154", "n": "Particular Topics in Education", "d": "These courses examine specific topics in education other than those already described elsewhere in this classification system, such as management of school-age children, rather than providing a general study of the teaching profession.", "u": null, "notes": "concept: NI001517164325", "dep": null}, {"v": "19155", "n": "Instructional Technology", "d": "Instructional Technology courses address the implementation of technical devices and processes that are used to improve and facilitate learning. Content includes, but is not limited to, productivity tools, interactive multimedia, communications, educational software and hardware, instructional applications, and ethical, legal, social, and professional issues.", "u": null, "notes": "concept: NI001517164326", "dep": null}, {"v": "19054", "n": "Child and Adult Care Services", "d": "Formerly known as Caregiving Service, Child and Adult Care Services courses emphasize the care of human beings who are unable or who need assistance to care for themselves. These courses involve the study of the biological, physiological, social, and psychological needs and concerns of young children, the elderly, and/or the disabled. Additional topics may include economic and legal issues, planning daily routines; appropriate environments and activities; growth and aging processes; and techniques for managing a center or working in others' homes.", "u": null, "notes": "concept: NI001517164327", "dep": null}, {"v": "19254", "n": "Food Science", "d": "Food Science courses offer opportunities for students to study the composition, structure, and properties of foods and their components as well as the consumption of food and the chemical changes that occur during the processing, storage, preparation, and consumption of food for the consumer. These courses often explore the effects of various materials, microorganisms, and processes on food products through laboratory experiments and can address food innovations to meet the needs of society. Culinary techniques and the safe handling of food in the home environment are commonly included.", "u": null, "notes": "concept: NI001517164328", "dep": null}, {"v": "19055", "n": "Particular Topics in Child and Elder Care", "d": "These courses examine specific topics related to child and elder care, such as regulations of the industry or caring for people with special needs, rather than providing a general study of child and elder care.", "u": null, "notes": "concept: NI001517164329", "dep": null}, {"v": "19097", "n": "Child and Elder Care�Independent Study", "d": "Child and Elder Care�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to child and elder care. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164330", "dep": null}, {"v": "19098", "n": "Child and Elder Care�Workplace Experience", "d": "Child and Elder Care�Workplace Experience courses provide students with work experience in fields related to caring for others. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164331", "dep": null}, {"v": "19099", "n": "Child and Elder Care�Other", "d": "Other Child and Elder Care courses.", "u": null, "notes": "concept: NI001517164332", "dep": null}, {"v": "19101", "n": "Cosmetology�Licensing", "d": "Cosmetology�Licensing courses provide students with the knowledge and skills applicable to the care of hair, skin, and nails, and prepare students for the state's Board of Cosmetology examinations. Almost always a series of courses with a specified number of instructional hours, Cosmetology� Licensing courses also require applied experience. Course content covers such topics as human anatomy and skin conditions, chemistry and bacteriology, sanitation and sterilization, state laws and regulations, and shop management. These courses provide students with experiences in shampooing, cutting, styling, bleaching, coloring, tinting, waving, and relaxing hair and providing facials and manicures.", "u": null, "notes": "concept: NI001517164333", "dep": null}, {"v": "19102", "n": "Barbering", "d": "Barbering courses provide students with the skills and experience to shave, style, and trim mustaches and beards and to cut, shampoo, and style hair. Course topics include hygiene, skin and scalp disease, and use of equipment. Barbering courses may aim to prepare students for the state's licensing examinations, and may include topics similar to those included in Cosmetology courses.", "u": null, "notes": "concept: NI001517164334", "dep": null}, {"v": "19103", "n": "Hair Styling", "d": "Hair Styling courses provide students with the skills and experience to cut, shampoo, and style hair. Course topics include hygiene, skin and scalp disease, and use of equipment. These courses provide students with experiences in shampooing, cutting, styling, bleaching, coloring, tinting, waving, and relaxing hair.", "u": null, "notes": "concept: NI001517164335", "dep": null}, {"v": "19104", "n": "Cosmetology�Non-licensing", "d": "Cosmetology�Non-licensing courses provide students with the knowledge and skills applicable to the care of hair, skin, and nails, but do not necessarily prepare students for the state's Board of Cosmetology examinations. Students gain experience in hair care, facials, and manicures; course topics usually include human anatomy, sanitation and sterilization, and related chemistry and bacteriology. Shop management and state regulations may also be included.", "u": null, "notes": "concept: NI001517164336", "dep": null}, {"v": "19247", "n": "Apparel and Furnishings�Independent Study", "d": "Apparel and Furnishings�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to apparel, textiles, and furnishings. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164337", "dep": null}, {"v": "19248", "n": "Apparel and Furnishings�Workplace Experience", "d": "Apparel and Furnishings�Workplace Experience courses provide students with work experience in fields related to apparel, textiles, and furnishings. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164338", "dep": null}, {"v": "19249", "n": "Apparel and Furnishings�Other", "d": "Other Apparel and Furnishings courses.", "u": null, "notes": "concept: NI001517164339", "dep": null}, {"v": "19251", "n": "Family and Consumer Sciences�Comprehensive", "d": "Family and Consumer Sciences�Comprehensive courses help students to develop the knowledge and skills that are used to manage one's family and career efficiently and productively. Course topics typically include foods and nutrition; apparel; child care and development; housing, interior design, and maintenance; consumer decisions; personal financial management; interpersonal relationships; and careers available in family and consumer sciences.", "u": null, "notes": "concept: NI001517164340", "dep": null}, {"v": "19252", "n": "Food Preparation and Health Management", "d": "Formerly known as Food and Nutrition, Food Preparation and Health Management courses provide students with an understanding of food's role in society, instruction in how to plan and prepare meals, and information about the nutritional and health benefits of minimizing processed and prepared food and prepackaged/prepared meals from one's diet. These courses not only build on the basic skills of food preparation but also address financial considerations and recipe conversion to make foods healthier. Some courses place a heavier emphasis on a balanced diet, while others concentrate on specific types of food preparation (such as low sodium, low fat, or increased whole foods). These courses will also address current issues such as organic foods and vegan cooking.", "u": null, "notes": "concept: NI001517164341", "dep": null}, {"v": "19253", "n": "Nutrition and Wellness", "d": "Nutrition and Wellness courses focus on how physical, mental, social, psychological, and emotional wellness are related to food, food selection, and health. Topics typically include dietary needs across one's lifespan, stress management, special dietary issues, and eating disorders as well as societal and genetic health issues that are addressed through the prevention education component of the class. Other topics covered range from healthy food selection, label reading, and diet analysis to understanding additives, making wise food choices, and dealing with food allergies.", "u": null, "notes": "concept: NI001517164342", "dep": null}, {"v": "19204", "n": "Apparel and Textile Services", "d": "Apparel and Textile Services courses introduce students to and expand upon various services that concern the care and maintenance of apparel, textiles, and furnishing. Course topics may include upholstery, dry cleaning, commercial sewing, and tailoring.", "u": null, "notes": "concept: NI001517164355", "dep": null}, {"v": "03107", "n": "IB Chemistry", "d": "IB Chemistry courses prepare students to take the International Baccalaureate Chemistry exams. In keeping with the general aim of IB Experimental Sciences courses, IB Chemistry promotes understanding of the facts, patterns, and principles underlying the field of chemistry; critical analysis, evaluation, prediction, and generation of scientific information and hypotheses; improved ability to communicate scientific ideas; and an awareness of the impact of chemistry and scientific advances in chemistry upon both society and issues of ethical, philosophical, and political importance. Course content varies, but includes the study of quantitative and organic chemistry; atomic structure, periodicity, bonding, energetics, kinetics, equilibrium, acids and bases, oxidations and reduction, and measurement and data processing. Laboratory experimentation is an essential part of these courses.", "u": null, "notes": "concept: NI001517163384", "dep": null}, {"v": "03108", "n": "Particular Topics in Chemistry", "d": "Particular Topics in Chemistry courses concentrate on a particular subtopic within the field of chemistry (such as chromatography and spectrometry) that is not otherwise described in this classification system.", "u": null, "notes": "concept: NI001517163385", "dep": null}, {"v": "24610", "n": "Filipino Literature", "d": "Filipino Literature courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Filipino. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Filipino cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163029", "dep": null}, {"v": "24611", "n": "Particular Topics in Filipino", "d": "Particular Topics in Filipino courses examine particular topics focused on Filipino language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163030", "dep": null}, {"v": "24612", "n": "IB Language A: Literature�Filipino", "d": "IB Language A: Literature�Filipino courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Filipino in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163031", "dep": null}, {"v": "24616", "n": "IB Language B (Filipino), Middle Years Program", "d": "IB (International Baccalaureate) Language B (Filipino), Middle Years Program courses enable students to gain competence in modern Filipino and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163032", "dep": null}, {"v": "24649", "n": "Filipino�Other", "d": "Other Filipino courses", "u": null, "notes": "concept: NI001517163033", "dep": null}, {"v": "24650", "n": "Russian (prior-to-secondary)", "d": "Russian for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Russian and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Russian-speaking cultures.", "u": null, "notes": "concept: NI001517163034", "dep": null}, {"v": "24607", "n": "Filipino for Native Speakers", "d": "Filipino for Native Speakers courses prepare native and heritage speakers to communicate in Filipino in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Filipino for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Filipino-speaking world.", "u": null, "notes": "concept: NI001517163035", "dep": null}, {"v": "24651", "n": "Russian Immersion (prior-to-secondary)", "d": "Russian Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Russian and grade-specific content using Russian as the language of instruction. Russian Immersion courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Russian-speaking cultures.", "u": null, "notes": "concept: NI001517163036", "dep": null}, {"v": "24660", "n": "Russian Literature", "d": "Russian Literature courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Russian. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Russian cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163037", "dep": null}, {"v": "24661", "n": "Particular Topics in Russian", "d": "Particular Topics in Russian courses examine particular topics focused on Russian language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163038", "dep": null}, {"v": "24662", "n": "IB Language A: Literature�Russian", "d": "IB Language A: Literature�Russian courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Russian in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163039", "dep": null}, {"v": "24663", "n": "IB Language B�Russian", "d": "IB Language B�Russian courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517163040", "dep": null}, {"v": "24666", "n": "IB Language B (Russian), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Russian), Middle Years Program courses allow students to gain competence in modern Russian and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163041", "dep": null}, {"v": "24667", "n": "IB Language A: Language and Literature�Russian", "d": "IB Language A: Language and Literature�Russian courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Russian in an academic context.", "u": null, "notes": "concept: NI001517163042", "dep": null}, {"v": "24668", "n": "IB Language Ab Initio�Russian", "d": "IB Language Ab Initio�Russian courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517163043", "dep": null}, {"v": "24699", "n": "Russian�Other", "d": "Other Russian courses", "u": null, "notes": "concept: NI001517163044", "dep": null}, {"v": "24700", "n": "Hebrew (prior-to-secondary)", "d": "Hebrew for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Hebrew and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517163045", "dep": null}, {"v": "24652", "n": "Russian I", "d": "Designed to introduce students to Russian language and culture, Russian I courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Russian-speaking cultures.", "u": null, "notes": "concept: NI001517163046", "dep": null}, {"v": "24653", "n": "Russian II", "d": "Russian II courses build upon skills developed in Russian I, preparing students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Russian II courses introduce the relationships among the products, practices, and perspectives of Russian-speaking cultures.", "u": null, "notes": "concept: NI001517163047", "dep": null}, {"v": "24654", "n": "Russian III", "d": "Russian III courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Russian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163048", "dep": null}, {"v": "24655", "n": "Russian IV", "d": "Russian IV courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Russian IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Russian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163049", "dep": null}, {"v": "24656", "n": "Russian V", "d": "Russian V courses prepare students to communicate authentically in Russian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Russian V courses promote students' understanding of the relationships among the products, practices, and perspectives of Russian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163050", "dep": null}, {"v": "24657", "n": "Russian for Native Speakers", "d": "Russian for Native Speakers courses prepare native and heritage speakers to communicate in Russian in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Russian for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Russian-speaking world.", "u": null, "notes": "concept: NI001517163051", "dep": null}, {"v": "24658", "n": "Russian Field Experience", "d": "Russian Field Experience courses place students in environments in which they interact with native Russian speakers, typically in settings where Russian is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163052", "dep": null}, {"v": "24659", "n": "Russian Conversation and Culture", "d": "Russian Conversation and Culture courses provide students with an introduction to the Russian language and the culture(s) of Russian-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163053", "dep": null}, {"v": "24701", "n": "Hebrew Immersion (prior-to-secondary)", "d": "Hebrew Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Hebrew and grade-specific content using Hebrew as the language of instruction. Hebrew Immersion courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517163054", "dep": null}, {"v": "24710", "n": "Hebrew Literature", "d": "Hebrew Literature courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Hebrew. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Hebrew cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163055", "dep": null}, {"v": "24711", "n": "Particular Topics in Hebrew", "d": "Particular Topics in Hebrew courses examine particular topics focused on Hebrew language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163056", "dep": null}, {"v": "24712", "n": "IB Language A: Literature�Hebrew", "d": "IB Language A: Literature�Hebrew courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Hebrew in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163057", "dep": null}, {"v": "24713", "n": "IB Language B�Hebrew", "d": "IB Language B�Hebrew courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517163058", "dep": null}, {"v": "24716", "n": "IB Language B (Hebrew), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Hebrew), Middle Years Program courses enable students to gain competence in modern Hebrew and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163059", "dep": null}, {"v": "24749", "n": "Hebrew�Other", "d": "Other Hebrew courses", "u": null, "notes": "concept: NI001517163060", "dep": null}, {"v": "24750", "n": "Arabic (prior-to-secondary)", "d": "Arabic for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Arabic and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Arabic-speaking cultures.", "u": null, "notes": "concept: NI001517163061", "dep": null}, {"v": "24751", "n": "Arabic Immersion (prior-to-secondary)", "d": "Arabic Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Arabic and grade-specific content using Arabic as the language of instruction. Arabic Immersion courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Arabic-speaking cultures.", "u": null, "notes": "concept: NI001517163062", "dep": null}, {"v": "24752", "n": "Arabic I", "d": "Designed to introduce students to Arabic language and culture, Arabic I courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Arabic-speaking cultures.", "u": null, "notes": "concept: NI001517163063", "dep": null}, {"v": "24702", "n": "Hebrew I", "d": "Designed to introduce students to Hebrew language and culture, Hebrew I courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517163064", "dep": null}, {"v": "24703", "n": "Hebrew II", "d": "Hebrew II courses build upon skills developed in Hebrew I, preparing students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Hebrew II courses introduce the relationships among the products, practices, and perspectives of Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517163065", "dep": null}, {"v": "24704", "n": "Hebrew III", "d": "Hebrew III courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163066", "dep": null}, {"v": "03065", "n": "IB Sports, Exercise, and Health Science", "d": "IB Sports, Exercise, and Health Science courses prepare students to take the International Baccalaureate Sports, Exercise, and Health Science exam. These courses are designed to provide students with an understanding of the science of physical performance. Course topics may include anatomy and physiology, biomechanics, psychology and nutrition, and the measurement and evaluation of human performance.", "u": null, "notes": "concept: NI001517163351", "dep": null}, {"v": "03066", "n": "PLTW Principles of Biomedical Science", "d": "Following Project Lead the Way's suggested curriculum, PLTW Principles of Biomedical Science courses focus on a case study in which students investigate the cause of death of a fictional person. Students conduct research, in which they examine autopsy reports, review medical history, and study human physiology, biology, and medicine to diagnose and recommend treatments that could have been applied.", "u": null, "notes": "concept: NI001517163352", "dep": null}, {"v": "03048", "n": "Earth Science�Workplace Experience", "d": "Earth Science�Workplace Experience courses provide work experience in a field related to earth science. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163353", "dep": null}, {"v": "03049", "n": "Earth Science�Other", "d": "Other Earth Science courses.", "u": null, "notes": "concept: NI001517163354", "dep": null}, {"v": "03051", "n": "Biology", "d": "Biology courses are designed to provide information regarding the fundamental concepts of life and life processes. These courses include (but are not restricted to) such topics as cell structure and function, general plant and animal physiology, genetics, and taxonomy.", "u": null, "notes": "concept: NI001517163355", "dep": null}, {"v": "03052", "n": "Biology�Advanced Studies", "d": "Usually taken after a comprehensive initial study of biology, Biology�Advanced Studies courses cover biological systems in more detail. Topics that may be explored include cell organization, function, and reproduction; energy transformation; human anatomy and physiology; and the evolution and adaptation of organisms.", "u": null, "notes": "concept: NI001517163356", "dep": null}, {"v": "03053", "n": "Anatomy and Physiology", "d": "Usually taken after a comprehensive initial study of biology, Anatomy and Physiology courses present the human body and biological systems in more detail. In order to understand the structure of the human body and its functions, students learn anatomical terminology, study cells and tissues, explore functional systems (skeletal, muscular, circulatory, respiratory, digestive, reproductive, nervous, and so on), and may dissect mammals.", "u": null, "notes": "concept: NI001517163357", "dep": null}, {"v": "03054", "n": "Anatomy", "d": "Anatomy courses present an in-depth study of the human body and biological system. Students study such topics as anatomical terminology, cells, and tissues and typically explore functional systems such as skeletal, muscular, circulatory, respiratory, digestive, reproductive, and nervous systems.", "u": null, "notes": "concept: NI001517163358", "dep": null}, {"v": "03055", "n": "Physiology", "d": "Physiology courses examine all major systems, tissues, and muscle groups in the human body to help students understand how these systems interact and their role in maintaining homeostasis. These courses may also cover such topics as cell structure and function, metabolism, and the human life cycle.", "u": null, "notes": "concept: NI001517163359", "dep": null}, {"v": "03056", "n": "AP Biology", "d": "Adhering to the curricula recommended by the College Board and designed to parallel college-level introductory biology courses, AP Biology courses emphasize four general concepts: evolution; cellular processes (energy and communication); genetics and information transfer; and interactions of biological systems. For each concept, these courses emphasize the development of scientific inquiry and reasoning skills, such as designing a plan for collecting data, analyzing data, applying mathematical routines, and connecting concepts in and across domains. AP Biology courses include college-level laboratory investigations.", "u": null, "notes": "concept: NI001517163360", "dep": null}, {"v": "03062", "n": "Conceptual Biology", "d": "These courses provide students with a basic understanding of living things. Topics covered may include ecology and environmental problems such as overpopulation and pollution as well as cells, types of organisms, evolutionary behavior, and inheritance.", "u": null, "notes": "concept: NI001517163366", "dep": null}, {"v": "03057", "n": "IB Biology", "d": "IB Biology courses prepare students to take the International Baccalaureate Biology exams. In keeping with the general aim of IB Experimental Sciences courses, IB Biology promotes understanding of the facts, principles, and concepts underlying the biological field; critical analysis, evaluation, and generation of scientific information and hypotheses; improved ability to communicate scientific ideas; and an awareness of the impact of biology and scientific advances in biology upon both society and issues of ethical, philosophical, and political importance. Course content varies, but includes study of statistical analysis, cells, the chemistry of life, genetics, ecology and evolution, and human health and physiology, nucleic acids, metabolism, plant biology, genetics, and animal physiology. Laboratory experimentation is an essential component of these courses.", "u": null, "notes": "concept: NI001517163361", "dep": null}, {"v": "03058", "n": "Botany", "d": "Botany courses provide students with an understanding of plants, their life cycles, and their evolutionary relationships.", "u": null, "notes": "concept: NI001517163362", "dep": null}, {"v": "03059", "n": "Genetics", "d": "Genetics courses provide students with an understanding of general concepts concerning genes, heredity, and variation of organisms. Course topics typically include chromosomes, the structure of DNA and RNA molecules, and dominant and recessive inheritance and may also include lethal alleles, epistasis and hypostasis, and polygenic inheritance.", "u": null, "notes": "concept: NI001517163363", "dep": null}, {"v": "03060", "n": "Microbiology", "d": "Microbiology courses provide students with a general understanding of microbes, prokaryotic and eukaryotic cells, and the three domain systems. Additional topics covered may include bacterial control, cell structure, fungi, protozoa, viruses and immunity, microbial genetics, and metabolism.", "u": null, "notes": "concept: NI001517163364", "dep": null}, {"v": "03061", "n": "Zoology", "d": "Zoology courses provide students with an understanding of animals, the niche they occupy in their environment or habitat, their life cycles, and their evolutionary relationships to other organisms. These courses should also help students develop an awareness and understanding of biotic communities.", "u": null, "notes": "concept: NI001517163365", "dep": null}, {"v": "03067", "n": "PLTW Human Body Systems", "d": "Following Project Lead the Way's suggested curriculum, PLTW Human Body Systems courses are designed for students to assume the role of biomedical professionals to solve real-world medical cases and experience science in action. In these courses, students study the interactions of systems within the human body by building organs and tissues on a skeletal manikin and use data acquisition software to monitor bodily functions. Course content also includes the exploration of identity, power, movement, protection, and homeostasis.", "u": null, "notes": "concept: NI001517163367", "dep": null}, {"v": "03148", "n": "Chemistry�Workplace Experience", "d": "Chemistry�Workplace Experience courses provide work experience in a field related to chemistry. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163368", "dep": null}, {"v": "03149", "n": "Chemistry�Other", "d": "Other Chemistry courses.", "u": null, "notes": "concept: NI001517163369", "dep": null}, {"v": "03151", "n": "Physics", "d": "Physics courses involve the study of the forces and laws of nature affecting matter, such as equilibrium, motion, momentum, and the relationships between matter and energy. The study of physics includes examination of sound, light, and magnetic and electric phenomena.", "u": null, "notes": "concept: NI001517163370", "dep": null}, {"v": "03152", "n": "Physics�Advanced Studies", "d": "Usually taken after a comprehensive initial study of physics, Physics�Advanced Studies courses provide instruction in laws of conservation, thermodynamics, and kinetics; wave and particle phenomena; electromagnetic fields; and fluid dynamics.", "u": null, "notes": "concept: NI001517163371", "dep": null}, {"v": "03153", "n": "Principles of Technology", "d": "Principles of Technology courses focus on the study of the forces and laws of nature and their application to modern technology. Equilibrium, motion, momentum, energy conversion, electromagnetism, and optical phenomena are presented in the context of current, real-world applications. Demonstrations, mathematics labs, and applied laboratory experiments are an integral part of the Principles of Technology curriculum. These courses may enable students to gain a solid foundation for careers in electronics, robotics, telecommunications, and other technological fields.", "u": null, "notes": "concept: NI001517163372", "dep": null}, {"v": "03068", "n": "PLTW Medical Interventions", "d": "Following Project Lead the Way's suggested curriculum, PLTW Medical Interventions courses focus on the health of a fictitious family that students must support by providing disease prevention, diagnosis, and treatments. In these courses, students study infections, human DNA code, cancer treatment, and organ failure. Course topics may also include immunology, surgery, genetics, pharmacology, medical devices, and diagnostics.", "u": null, "notes": "concept: NI001517163373", "dep": null}, {"v": "03069", "n": "Nutrition Science", "d": "Nutrition Science courses focus on the examination of individual nutrients; their structure and function in the human body; nutrient composition of food; and selection of food to meet nutrient needs, maintain health and provide satisfaction. Topics covered include digestion, absorption, and metabolism of carbohydrates, lipids, and proteins; vitamins and minerals; physical activity; nutritional needs throughout the life cycle; and evaluation of nutritional claims.", "u": null, "notes": "concept: NI001517163374", "dep": null}, {"v": "03097", "n": "Biology�Independent Study", "d": "Biology�Independent Study courses, often conducted with instructors as mentors, enable students to explore scientific topics of interest, using advanced methods of scientific inquiry and experimentation. These courses may be offered in conjunction with other science courses or may serve as an opportunity for students to explore a topic of special interest.", "u": null, "notes": "concept: NI001517163375", "dep": null}, {"v": "03098", "n": "Biology�Workplace Experience", "d": "Biology�Workplace Experience courses provide work experience in a field related to biology. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163376", "dep": null}, {"v": "03099", "n": "Biology�Other", "d": "Other Biology courses.", "u": null, "notes": "concept: NI001517163377", "dep": null}, {"v": "03101", "n": "Chemistry", "d": "Chemistry courses involve studying the composition, properties, and reactions of substances. These courses typically explore such concepts as the behaviors of solids, liquids, and gases; acid/base and oxidation/reduction reactions; and atomic structure. Chemical formulas and equations and nuclear reactions are also studied.", "u": null, "notes": "concept: NI001517163378", "dep": null}, {"v": "03102", "n": "Chemistry�Advanced Studies", "d": "Usually taken after a comprehensive initial study of chemistry, Chemistry�Advanced Studies courses cover chemical properties and interactions in more detail. Advanced chemistry topics include organic chemistry, thermodynamics, electrochemistry, macromolecules, kinetic theory, and nuclear chemistry.", "u": null, "notes": "concept: NI001517163379", "dep": null}, {"v": "03103", "n": "Organic Chemistry", "d": "Organic Chemistry courses involve the study of organic molecules and functional groups. Topics covered may include nomenclature, bonding molecular structure and reactivity, reaction mechanisms, and current spectroscopic techniques.", "u": null, "notes": "concept: NI001517163380", "dep": null}, {"v": "03104", "n": "Physical Chemistry", "d": "Usually taken after completing a calculus course, Physical Chemistry courses cover chemical kinetics, quantum mechanics, molecular structure, molecular spectroscopy, and statistical mechanics.", "u": null, "notes": "concept: NI001517163381", "dep": null}, {"v": "03105", "n": "Conceptual Chemistry", "d": "Conceptual Chemistry courses are practical, nonquantitative chemistry courses designed for students who desire an understanding of chemical concepts and applications.", "u": null, "notes": "concept: NI001517163382", "dep": null}, {"v": "03106", "n": "AP Chemistry", "d": "Following the curricula recommended by the College Board, AP Chemistry courses usually follow high school chemistry and second-year algebra. Concepts covered may include the structure of matter; bonding of intermolecular forces; chemical reactions; kinetics; thermodynamics; and chemical equilibrium. For each concept, these courses emphasize the development of scientific inquiry and reasoning skills, such as designing a plan for collecting data, analyzing data, applying mathematical routines, and connecting concepts in and across domains. AP Chemistry courses include college-level laboratory investigations.", "u": null, "notes": "concept: NI001517163383", "dep": null}, {"v": "03147", "n": "Chemistry�Independent Study", "d": "Chemistry�Independent Study courses, often conducted with instructors as mentors, enable students to explore scientific topics of interest, using advanced methods of scientific inquiry and experimentation. These courses may be offered in conjunction with other rigorous science courses or may serve as an opportunity to explore a topic of special interest.", "u": null, "notes": "concept: NI001517163386", "dep": null}, {"v": "03156", "n": "AP Physics C", "d": "AP Physics C courses prepare students for the College Board's examinations in Physics C: Electricity and Magnetism and Physics C: Mechanics. These courses parallel college-level physics courses that serve as a partial foundation for science or engineering majors and primarily focus on mechanics and electricity and magnetism, with approximately equal emphasis placed on these two areas. See SCED Codes 03163 and 03164 for detailed content descriptions.", "u": null, "notes": "concept: NI001517163387", "dep": null}, {"v": "03157", "n": "IB Physics", "d": "IB Physics courses prepare students to take the International Baccalaureate Physics exams. In keeping with the general aim of IB Experimental Sciences courses, IB Physics promotes understanding of the facts, patterns, and principles underlying the field of physics; critical analysis, prediction, and application of scientific information and hypotheses; improved ability to communicate scientific ideas; and an awareness of the impact of scientific advances in physics upon both society and issues of ethical, philosophical, and political importance. Course content varies, but includes the study of physical measurement; mechanics; thermal, atomic, and nuclear physics; oscillations and waves; electric currents; fields and forces; and energy, power, and climate change. Laboratory experimentation is essential; calculus may be used in some courses.", "u": null, "notes": "concept: NI001517163388", "dep": null}, {"v": "03158", "n": "Life Science", "d": "Life Science courses cover the basic principles of life and life processes. These topics may include cells, species, ecosystems, reproduction, genetics, or other topics consistent with state academic standards for life science.", "u": null, "notes": "concept: NI001517163389", "dep": null}, {"v": "03159", "n": "Physical Science", "d": "Physical Science courses involve study of the structures and states of matter. Typically (but not always) offered as introductory survey courses, they may include such topics as forms of energy, wave phenomenon, electromagnetism, and physical and chemical interactions.", "u": null, "notes": "concept: NI001517163390", "dep": null}, {"v": "03161", "n": "Conceptual Physics", "d": "Conceptual Physics courses introduce students to the use of chemicals, characteristic properties of materials, and simple mechanics to better describe the world and nonliving matter. The courses emphasize precise measurements and descriptive analysis of experimental results. Topics covered may include energy and motion, electricity, magnetism, heat, the structure of matter, and how matter reacts to materials and forces.", "u": null, "notes": "concept: NI001517163391", "dep": null}, {"v": "03162", "n": "Particular Topics in Physics", "d": "Particular Topics in Physics courses concentrate on a particular subtopic within the field of physics (such as optics, thermodynamics, quantum physics, and so on) that is not otherwise described in this classification system.", "u": null, "notes": "concept: NI001517163392", "dep": null}, {"v": "03163", "n": "AP Physics C: Electricity and Magnetism", "d": "Designed by the College Board to parallel college-level physics courses that serve as a partial foundation for science or engineering majors, AP Physics C: Electricity and Magnetism courses focus on electricity and magnetism, including topics such as electrostatics; conductors, capacitors, and dielectrics; electric circuits; magnetic fields; and electromagnetism. AP Physics C courses require the use of calculus to solve the problems posed.", "u": null, "notes": "concept: NI001517163393", "dep": null}, {"v": "03164", "n": "AP Physics C: Mechanics", "d": "Designed by the College Board to parallel college-level physics courses that serve as a partial foundation for science or engineering majors, AP Physics C: Mechanics courses focus on classical mechanics, including topics in kinematics; Newton's laws of motion; work, energy, and power; systems of particles and linear momentum; circular motion and rotation; oscillations; and gravitation. AP Physics C courses require the use of calculus to solve the problems posed.", "u": null, "notes": "concept: NI001517163394", "dep": null}, {"v": "03165", "n": "AP Physics 1", "d": "Designed by the College Board to parallel first-semester college-level courses in algebra-based physics, AP Physics 1 courses focus on Newtonian mechanics (including rotational motion); work, energy, and power; mechanical waves and sound; and introductory circuits. These courses may also include college-level laboratory investigations.", "u": null, "notes": "concept: NI001517163395", "dep": null}, {"v": "03203", "n": "Applied Biology/Chemistry", "d": "Applied Biology/Chemistry courses integrate biology and chemistry into a unified domain of study and present the resulting body of knowledge in the context of work, home, society, and the environment, emphasizing field and laboratory activities. Topics include natural resources, water, air and other gases, nutrition, disease and wellness, plant growth and reproduction, life processes, microorganisms, synthetic materials, waste and waste management, and the community of life.", "u": null, "notes": "concept: NI001517163396", "dep": null}, {"v": "05193", "n": "Interior Design", "d": "Interior Design courses emphasize applying the fundamental processes of artistic expression to design an interior living or working space. Students analyze and apply a variety of media, techniques, and processes in their interior design work. Courses may also include an understanding of aesthetic issues associated with interior design. Students study the art or process of designing the interior of a room or building and focus on enhancing the interiors of a space to achieve a healthy and more aesthetically pleasing environment. Students will study interior designs from historical, contemporary, and world cultures. Students engage in critique of their interior designs, the designs of others, and designs by professional interior designers for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163681", "dep": null}, {"v": "05180", "n": "Art (kindergarten)", "d": "Art (kindergarten) courses provide to students developmentally appropriate activities to foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for kindergarten.", "u": null, "notes": "concept: NI001517163682", "dep": null}, {"v": "05181", "n": "Art (grade 1)", "d": "Art (grade 1) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, and strengthen their critical abilities. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for grade 1.", "u": null, "notes": "concept: NI001517163683", "dep": null}, {"v": "05182", "n": "Art (grade 2)", "d": "Art (grade 2) courses provide to students activities that foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, and strengthen their critical abilities. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for grade 2.", "u": null, "notes": "concept: NI001517163684", "dep": null}, {"v": "05165", "n": "Crafts", "d": "Crafts courses help students apply fundamental processes of artistic expression to the materials and accompanying aesthetics of crafts. Students may explore types of folk art and the materials and ways in which objects have been created for practical, religious, spiritual, and cultural needs of people around the world. These courses may survey a wide range of crafts or may focus on only one type of craft; some possibilities include calligraphy, quilting, silk-screening, cake-decorating, tole-painting, mask-making, knitting, crocheting, paper-making, and so on. These courses may also explore aesthetic issues surrounding folk art and artists and engage in critiques of this authentic art form.", "u": null, "notes": "concept: NI001517163687", "dep": null}, {"v": "05166", "n": "Jewelry", "d": "Jewelry courses help students apply fundamental processes of artistic expression to the fabrication of small-scale objects and pieces of jewelry, and include the study of ornamental design, its media, techniques, and processes. These courses typically help students develop expressive and technical skills in creating jewelry, using art metals, and exploring design concepts in form and surface decoration. Courses present a historical and contemporary view of using art metals and other elements in jewelry design and provide instruction in the critique process. Students participate in critiques of their jewelry and metal works, the jewelry and metal works of others, and those by professional jewelers and gemologists for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163688", "dep": null}, {"v": "05167", "n": "Photography", "d": "Photography courses provide students with an understanding of photographic media, techniques, and processes. These courses focus on development of photographic compositions through manipulation of the fundamental processes of artistic expression. Students may learn to make meaningful visual statements with an emphasis on personal creative expression to communicate ideas, feelings, or values. Photography courses may also include the history of photography, historic movements, image manipulation, critical analysis, and some creative special effects. Students engage in critiques of their photographic images, the works of other students, and those by professional photographers for the purpose of reflecting on and refining work.", "u": null, "notes": "concept: NI001517163689", "dep": null}, {"v": "08001", "n": "Physical Education", "d": "Physical Education courses provide students with knowledge, experience, and an opportunity to develop skills in more than one of the following sports or activities: team sports, individual/dual sports, recreational sports, and fitness/conditioning activities.", "u": null, "notes": "concept: NI001517163702", "dep": null}, {"v": "05168", "n": "Cinematography/Video Production", "d": "Formerly known as Film/Videotape, Cinematography/Video Production courses emphasize the application of the fundamental processes of artistic expression for the purpose of shooting and processing of the image. These courses include the history and development of cinema, television, and video production. Students explore a range of skills needed to explore contemporary social, cultural, and political issues and creatively solve problems within and through cinematic or video productions. Students engage in critiques of their cinematic or video productions, those of others, and productions of professional cinematographers or video artists for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163690", "dep": null}, {"v": "05169", "n": "Multimedia Art", "d": "Formerly known as Computer-Assisted Art, Multimedia Art courses emphasize applying the fundamental processes of artistic expression for the purpose of creating multimedia productions that explore contemporary social, cultural, and political issues. These courses include the history and development of multiple forms of media including a combination of text, audio, still images, animation, video, and interactive content. These courses provide students with the opportunity to develop foundational skills and knowledge while they also become more adept in cinema, video, digital live production, and electronic time-based media. Students engage in critique of their multimedia work, that of others, and the multimedia video, digital, and live production work of artists for the purpose of reflecting on and refining work for presentation.", "u": null, "notes": "concept: NI001517163691", "dep": null}, {"v": "05198", "n": "Visual Arts�Workplace Experience", "d": "Visual Arts�Workplace Experience courses provide students with work experience in a field related to visual arts. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163692", "dep": null}, {"v": "05199", "n": "Visual Arts�Other", "d": "Other Visual Arts courses.", "u": null, "notes": "concept: NI001517163693", "dep": null}, {"v": "05201", "n": "Interdisciplinary Arts", "d": "Formerly known as Integrated Fine Arts, Interdisciplinary Arts courses explore communication across the arts disciplines: any subset or all of the visual arts, music, drama, theater, dance, and literature may be addressed in the curriculum for these courses. Students study and critique the works of others and participate in or produce art themselves. These courses often include comparative study of various art forms over time (i.e., the interrelationship of theater and visual arts of a particular time period and culture).", "u": null, "notes": "concept: NI001517163694", "dep": null}, {"v": "05202", "n": "IB Arts, Middle Years Program", "d": "International Baccalaureate (IB) Arts, Middle Years Program courses include visual and performing arts and organize learning around the creative cycle. These courses bring students into contact with art forms and aesthetic values of several cultures and help students master artistic techniques.", "u": null, "notes": "concept: NI001517163695", "dep": null}, {"v": "05203", "n": "Film Appreciation and Analysis", "d": "Film Appreciation and Analysis courses help students understand the critical historical and stylistic elements of cinema. These courses help students form an aesthetic framework to examine social, political, and historical events in the world and to understand how moving images express the ideas of individuals and society. Course content may include analysis, discussion, and evaluation of multiple film styles including, but not limited to, documentary, short film, drama, horror, and comedy.", "u": null, "notes": "concept: NI001517163696", "dep": null}, {"v": "05995", "n": "Visual and Performing Art�Aide", "d": "Formerly Fine and Performing Arts�Aide, Visual and Performing Art�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163697", "dep": null}, {"v": "08002", "n": "Team Sports", "d": "Team Sports courses provide to students the knowledge, experience, and opportunity to develop skills in more than one team sport (such as volleyball, basketball, soccer, and so on).", "u": null, "notes": "concept: NI001517163703", "dep": null}, {"v": "08003", "n": "Individual/Dual Sports", "d": "Individual/Dual Sports courses provide students with knowledge, experience, and an opportunity to develop skills in more than one individual or dual sport (such as tennis, golf, badminton, jogging/running, racquetball, and so on).", "u": null, "notes": "concept: NI001517163704", "dep": null}, {"v": "05177", "n": "Animation", "d": "Animation courses focus on the fundamental processes of artistic expression as applied to creative and conceptual aspects of designing and producing two- or three-dimensional animated images for storytelling and multimedia presentations. These courses emphasize the interactive use of drawing and design fundamentals, storyboarding, composition and imaging, audio and sound creation, editing and presentation. Students learn to use various media, techniques, and processes necessary for animation development. Courses may also include a study of the history of animation, its aesthetic issues, and roles and functions. Students engage in critique of their animated work, the animated works of other students, and works by professional animators to reflect on and refine work.", "u": null, "notes": "concept: NI001517163698", "dep": null}, {"v": "05178", "n": "Art (early childhood education)", "d": "Art (early childhood education) courses provide to students developmentally appropriate activities to foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163699", "dep": null}, {"v": "05179", "n": "Art (pre-kindergarten)", "d": "Art (pre-kindergarten) courses provide to students developmentally appropriate activities to foster creative expression, communication through artistic endeavor, and appreciation of culture and heritage. Although the art form typically involves visual arts (drawing, painting, sculpture, crafts, and the like), students may also explore other forms of art such as dance, music, and theater. Specific course content conforms to any existing state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163700", "dep": null}, {"v": "05997", "n": "Visual and Performing Art�Independent Study", "d": "Formerly Fine and Performing Art�Independent Study, Visual and Performing Art�Independent Study courses, often conducted with instructors or professional artists as mentors, enable students to explore a particular art form. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular form or style, to explore a topic of in greater detail, or to develop more advanced skill.", "u": null, "notes": "concept: NI001517163701", "dep": null}, {"v": "08004", "n": "Recreation Sports", "d": "Recreation Sports courses provide students with knowledge, experience, and an opportunity to develop skills in more than one recreational sport or outdoor pursuit (such as adventure activities, croquet, Frisbee, wall climbing, bocce ball, fishing, hiking, cycling, and so on).", "u": null, "notes": "concept: NI001517163705", "dep": null}, {"v": "08005", "n": "Fitness/Conditioning Activities", "d": "Fitness/Conditioning Activities courses emphasize conditioning activities that help develop muscular strength, flexibility, and cardiovascular fitness.", "u": null, "notes": "concept: NI001517163706", "dep": null}, {"v": "08006", "n": "Corps Movement", "d": "Corps Movement courses emphasize physical conditioning, fundamentals of movement, group precision, and public performance. The courses may be intended for members of various teams, including flag corps, rifle corps, cheerleading squads, and so on.", "u": null, "notes": "concept: NI001517163707", "dep": null}, {"v": "08008", "n": "Gymnastics", "d": "Gymnastics courses are designed to help students develop knowledge and skills in gymnastics, stunts, and tumbling while emphasizing safety. Floor gymnastics may be supplemented by the use of gymnastic equipment such as balance beam, uneven bars, parallel bars, rings, and so on. Gymnastic courses may include other components such as the history of gymnastics and conditioning.", "u": null, "notes": "concept: NI001517163708", "dep": null}, {"v": "08009", "n": "Weight Training", "d": "Weight Training courses help students develop knowledge and skills with free weights and universal stations while emphasizing safety and proper body positioning; they may include other components such as anatomy and conditioning.", "u": null, "notes": "concept: NI001517163709", "dep": null}, {"v": "05998", "n": "Visual and Performing Art�Workplace Experience", "d": "Formerly Fine and Performing Art�Workplace Experience, Visual and Performing Art�Workplace Experience courses provide students with work experience in a field related to the fine and performing arts. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163710", "dep": null}, {"v": "05999", "n": "Visual and Performing Art�Other", "d": "Other Visual and Performing Art courses.", "u": null, "notes": "concept: NI001517163711", "dep": null}, {"v": "07001", "n": "Religious Foundations", "d": "Religious Foundations courses' primary objectives include instruction in the history, tenets, and organization of a religion; development of personal faith and conviction; and exposure to the ways in which daily life may reflect personal religious beliefs. These courses typically include various components particular to a specific religion, such as religious sacraments and symbols, food laws, the authority and structure of the church, the church calendar, and so on.", "u": null, "notes": "concept: NI001517163712", "dep": null}, {"v": "07002", "n": "Comparative Religion", "d": "Comparative Religion courses survey and compare the various forms and values of several world religions, offering students a basic understanding of the world's diverse religious faiths and practices. Course topics typically include the belief systems of adherents; the relationships among humans, nature, ancestors, and the spiritual world; and the historical development of each religion.", "u": null, "notes": "concept: NI001517163713", "dep": null}, {"v": "07003", "n": "Eastern Religions", "d": "Similar to Comparative Religion, Eastern Religions courses provide students with an overview of various religions and belief systems but focus on those of the Eastern World. Particular religious or philosophical systems of study usually include Buddhism, Hinduism, Islam, Taoism, Shintoism, and Confucianism, among others.", "u": null, "notes": "concept: NI001517163714", "dep": null}, {"v": "07004", "n": "Western Religions", "d": "Similar to Comparative Religion, Western Religions courses provide students with an overview of various religions and belief systems but focus on those of the Western World. Particular religious or philosophical systems of study usually include Judaism; Christianity (including various faiths such as those of Catholics, Episcopalians, Baptists, Quakers, Mormons, Mennonites, and others); and Native Indian belief systems, among others.", "u": null, "notes": "concept: NI001517163715", "dep": null}, {"v": "07005", "n": "Scriptures", "d": "Scriptures courses emphasize understanding and interpreting the sacred writings of a faith (such as the Bible, Torah, Koran, Book of Mormon, and so on) from the standpoint of a religious faith. Course objectives are designed so that students may comprehend the theological, doctrinal, and ethical messages contained within religious scriptures.", "u": null, "notes": "concept: NI001517163716", "dep": null}, {"v": "07006", "n": "Old Testament", "d": "Old Testament courses emphasize understanding and interpreting the sacred writings of the Old Testament from the standpoint of a religious faith and may focus on one or several books. Course content typically focuses on themes, theological concepts, and portrayal of ethical messages, but may also include critique and commentary.", "u": null, "notes": "concept: NI001517163717", "dep": null}, {"v": "07007", "n": "New Testament", "d": "New Testament courses emphasize understanding and interpreting the sacred writings of the New Testament from the standpoint of a religious faith and may focus on one or several religious books. Course content typically focuses on themes, theological concepts, and portrayal of ethical messages, but may also include critique and commentary.", "u": null, "notes": "concept: NI001517163718", "dep": null}, {"v": "07008", "n": "Bible History", "d": "Bible History courses treat the Bible as a historical document and provide an overview of significant biblical events. The content usually includes geography; the relationship among cultures, belief systems, and the events chronicled in the Bible; and early Jewish or Christian Church history.", "u": null, "notes": "concept: NI001517163719", "dep": null}, {"v": "07009", "n": "Christology", "d": "Christology courses concern the work and life of Jesus Christ and the literature related to him. Course content is typically based on Christian scriptures, leading to an examination of the message of Jesus Christ and applying His message to daily life.", "u": null, "notes": "concept: NI001517163720", "dep": null}, {"v": "07010", "n": "Religious Figures", "d": "Religious Figures courses offer students the opportunity to examine the lives and messages of one or several people who are central to a religious faith, such as a prophet, apostle, philosopher, or leader. In addition to a historical study of the person (or people), these courses typically emphasize how the teachings of these individuals influence the faith and culture of a religious group.", "u": null, "notes": "concept: NI001517163721", "dep": null}, {"v": "07011", "n": "Liturgy and Prayer", "d": "Liturgy and Prayer courses vary widely, usually depending upon the underlying religion, but generally seek to inform students about the meaning and message of public and private worship. Course content typically includes an examination or exploration of common rituals, spoken or sung prayers, and observed sacraments.", "u": null, "notes": "concept: NI001517163722", "dep": null}, {"v": "12169", "n": "Social Media Marketing", "d": "Social Media Marketing courses address social media as a marketing tool and emphasize social media tools, social media messages, and search engine optimization. Topics may include, but are not limited to, marketing information management (including marketing research), market planning, channel management, sales, promotion, product/service management, and pricing.", "u": null, "notes": "concept: NI001517164009", "dep": null}, {"v": "12197", "n": "Marketing�Independent Study", "d": "Marketing�Independent Study courses, often conducted with instructors as mentors, enable students to explore marketing-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164010", "dep": null}, {"v": "12198", "n": "Marketing�Workplace Experience", "d": "Marketing�Workplace Experience courses provide students with work experience in fields related to marketing. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164011", "dep": null}, {"v": "12199", "n": "Marketing�Other", "d": "Other Marketing courses.", "u": null, "notes": "concept: NI001517164012", "dep": null}, {"v": "12201", "n": "Cashier/Checker Operations", "d": "Cashier/Checker Operations courses provide students with the knowledge and skills to operate a cash register and to handle numerous transactions. Topics typically include cash register procedures; handling cash, credit, checks, food stamps, and other forms of legal tender; human relations; stocking and marking merchandise; and theft prevention. Job search and employability skills are often an integral part of the course.", "u": null, "notes": "concept: NI001517164013", "dep": null}, {"v": "12202", "n": "Principles of Selling", "d": "Principles of Selling courses provide students with the knowledge and opportunity to develop in-depth sales competencies. Course content typically includes types of selling, steps in a sale, sales strategies, and interpersonal skills and techniques.", "u": null, "notes": "concept: NI001517164014", "dep": null}, {"v": "12247", "n": "Sales�Independent Study", "d": "Sales�Independent Study courses, often conducted with instructors as mentors, enable students to explore sales-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164015", "dep": null}, {"v": "12248", "n": "Sales�Workplace Experience", "d": "Sales�Workplace Experience courses provide students with work experience in fields related to sales. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164016", "dep": null}, {"v": "12249", "n": "Sales�Other", "d": "Other Sales courses.", "u": null, "notes": "concept: NI001517164017", "dep": null}, {"v": "12995", "n": "Business and Marketing�Aide", "d": "Business and Marketing�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164018", "dep": null}, {"v": "12997", "n": "Business and Marketing�Independent Study", "d": "Business and Marketing�Independent Study courses, often conducted with instructors or professionals as mentors, enable students to explore business or marketing-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164019", "dep": null}, {"v": "13097", "n": "Processing/Production�Independent Study", "d": "Processing/Production�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to processing and production. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164020", "dep": null}, {"v": "13098", "n": "Processing/Production�Workplace Experience", "d": "Processing/Production�Workplace Experience courses provide students with work experience in fields related to manufacturing processing and production. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164021", "dep": null}, {"v": "13099", "n": "Processing/Production�Other", "d": "Other Processing/Production courses.", "u": null, "notes": "concept: NI001517164022", "dep": null}, {"v": "13101", "n": "Production Systems", "d": "Production Systems courses provide students with knowledge and skills related to manufacturing technologies from conception through production. Although courses vary, students typically analyze markets, design and develop prototypes, plan a marketing or sales strategy, manage a production plan, and manufacture useful products. These courses may also explore the evolution and impact of technology on society's social, cultural, and economic systems and institutions.", "u": null, "notes": "concept: NI001517164023", "dep": null}, {"v": "13102", "n": "Electro-Mechanical Systems", "d": "Electro-Mechanical Systems courses provide students with instruction and experience in components and equipment used within a manufacturing environment powered by electricity and physical forces. Students gain an understanding of basic and industrial electricity, industrial electronics, and the automated systems used in the manufacturing process or within manufactured goods.", "u": null, "notes": "concept: NI001517164024", "dep": null}, {"v": "13103", "n": "Product Development", "d": "Product Development courses provide students with the opportunity to focus on one or more areas of industrial technology to design or redesign a product to solve a problem. Students may build prototypes and working models and may evaluate the product and process according to industry standards.", "u": null, "notes": "concept: NI001517164025", "dep": null}, {"v": "13055", "n": "Metal Processing/Production", "d": "Metal Processing/Production courses allow students to study the physical and chemical properties of metals and metal alloys and to use these materials to construct usable products according to industry standards. These courses enable students to experience the process of translating an idea into a finished product, with instruction in planning, designing, selecting materials, and using tools and machines.", "u": null, "notes": "concept: NI001517164026", "dep": null}, {"v": "13056", "n": "Plastics Processing/Production", "d": "Plastics Processing/Production courses allow students to study the physical and chemical properties of plastics and composites and to use these materials to construct usable products according to industry standards. These courses enable students to experience the process of translating an idea into a finished product, with instruction in planning, designing, selecting materials, and using tools and machines.", "u": null, "notes": "concept: NI001517164027", "dep": null}, {"v": "13057", "n": "Ceramic Processing/Production", "d": "Ceramic Processing/Production courses allow students to study the physical and chemical properties of ceramics and heat-resistant composites and to use these materials to construct usable products according to industry standards. These courses enable students to experience the process of translating an idea into a finished product, with instruction in planning, designing, selecting materials, and using tools and machines.", "u": null, "notes": "concept: NI001517164028", "dep": null}, {"v": "13058", "n": "Particular Topics in Processing and Production", "d": "These courses examine specific topics in processing and production, such as substance analysis, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164029", "dep": null}, {"v": "13204", "n": "Particular Topics in Machining", "d": "These courses examine specific topics related to machining, emphasizing a particular type of machine, tool, or procedure, or concentrating on a particular application of machining techniques.", "u": null, "notes": "concept: NI001517164030", "dep": null}, {"v": "13302", "n": "Equipment Maintenance and Repair", "d": "Equipment Maintenance and Repair courses prepare students to adjust, maintain, replace, and repair parts of machinery and to repair tools, equipment, and machines. The courses may have a general emphasis or may focus on a specific type of machinery or equipment related to a particular industry. Depending upon the intent, course topics may include electric, hydraulic, pneumatic, or mechanic systems; programmable logic and motor control devices, valves, and gates; or supplemental equipment such as fans, hoses, and pipes.", "u": null, "notes": "concept: NI001517164031", "dep": null}, {"v": "13303", "n": "Industrial Maintenance", "d": "Industrial Maintenance courses introduce students to the care and maintenance of a wide range of industrial equipment, including chain and gear drives, couplings, and fluid power equipment. Course topics may include lubricants and lubrication, the replacement of seals and bearings, and the correct application and selection of hand and power tools. Advanced courses may emphasize motor alignment using laser alignment, milling operations, turning operations, welding, technical drawings, and quality control.", "u": null, "notes": "concept: NI001517164032", "dep": null}, {"v": "13347", "n": "Repair�Independent Study", "d": "Repair�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to repair. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164033", "dep": null}, {"v": "13348", "n": "Repair�Workplace Experience", "d": "Repair�Workplace Experience courses provide students with work experience in the fields involving repair, supported by classroom attendance and discussion. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164034", "dep": null}, {"v": "13205", "n": "Sheet Metal", "d": "Sheet Metal courses expose students to the skills and information necessary to lay out, fabricate, assemble, install, maintain, and repair items and structures created from sheet metal components. Students learn the safe and efficient operation of various tools and typically gain skill in blueprint reading, welding, and finishing and polishing metals.", "u": null, "notes": "concept: NI001517164035", "dep": null}, {"v": "13206", "n": "Particular Topics in Sheet Metal", "d": "In these courses students gain knowledge and skills in particular aspects of sheet metal. Examples include individual courses in radial line development, triangulation fabrication, and so on.", "u": null, "notes": "concept: NI001517164036", "dep": null}, {"v": "13207", "n": "Welding", "d": "Welding courses enable students to gain knowledge of the physical and chemical properties, uses, and applications of various metals. Students gain skills in various processes used to join and cut metals (such as oxyacetylene, shielded metal, metal inert gas, and tungsten arc processes) and experience in identifying, selecting, and rating appropriate techniques. Students read and interpret blueprints in order to identify, select, and rate appropriate techniques. These courses may prepare students to pass relevant industry certifications.", "u": null, "notes": "concept: NI001517164037", "dep": null}, {"v": "13208", "n": "Particular Topics in Welding", "d": "In these courses students gain knowledge and skills in particular aspects of welding. Examples include individual courses in each of the following types of welding: gas metal, gas tungsten, and shielded metal and flux core arc welding.", "u": null, "notes": "concept: NI001517164038", "dep": null}, {"v": "13209", "n": "Particular Topics in Metalwork", "d": "In these courses students gain knowledge and skills in particular aspects of metalwork (such as foundry work or metallurgy) not otherwise described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164039", "dep": null}, {"v": "13147", "n": "Production Systems�Independent Study", "d": "Production Systems�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to manufacturing systems and/or research. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164040", "dep": null}, {"v": "13148", "n": "Production Systems�Workplace Experience", "d": "Production Systems�Workplace Experience courses provide students with work experience in fields related to manufacturing systems and/or research. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164041", "dep": null}, {"v": "13149", "n": "Production Systems�Other", "d": "Other Production Systems courses.", "u": null, "notes": "concept: NI001517164042", "dep": null}, {"v": "13201", "n": "Metalwork Occupations", "d": "Metalwork Occupations courses introduce and expose students to the theoretical principles and career opportunities pertaining to planning, manufacturing, assembling, testing, and repairing of parts, mechanisms, and structures in which materials are cast, formed, treated, cut, fused, or otherwise processed in some fashion.", "u": null, "notes": "concept: NI001517164043", "dep": null}, {"v": "13202", "n": "Metalworking", "d": "Metalworking courses introduce students to the physical and chemical properties of various metals and the tools and equipment used to manipulate metal and form it into products. Students will develop planning, layout, and measurement skills; gain experience in cutting, bending, forging, casting, and/or welding metal; complete projects according to blueprints or other specifications; and may also learn how to polish and finish metals. Correct use of metalworking tools and equipment is stressed.", "u": null, "notes": "concept: NI001517164044", "dep": null}, {"v": "13203", "n": "Machining", "d": "Machining courses enable students to design and manufacture metal parts using various machine tools and equipment. Course content may include interpreting specifications using blueprints; preparing and using manual and computer numerical controlled (CNC) lathes and milling machines, shapers, and grinders with skill, safety, and precision; maintenance; developing part specifications; and selecting appropriate materials. Advanced course topics may include quality control; statistical process control; and application of measurements, metalworking theory, and properties of materials. Courses may prepare students for industry certification.", "u": null, "notes": "concept: NI001517164045", "dep": null}, {"v": "13247", "n": "Metalwork�Independent Study", "d": "Metalwork�Independent Study courses, often conducted with instructors as mentors, enable students to explore metalwork-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164046", "dep": null}, {"v": "13248", "n": "Metalwork�Workplace Experience", "d": "Metalwork�Workplace Experience courses provide students with work experience in the welding, machine technologies, or metalwork fields. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164047", "dep": null}, {"v": "13249", "n": "Metalwork�Other", "d": "Other Metalwork courses.", "u": null, "notes": "concept: NI001517164048", "dep": null}, {"v": "13301", "n": "Appliance Repair", "d": "Appliance Repair courses provide students with the knowledge and experience to repair, install, service, and inspect appliances such as stoves, refrigerators, washers, dryers, air conditioners, water heaters, and so on. Students gain an understanding of the mechanics and working systems of these appliances, the skills to read blueprints and specifications, and proficiency in using related tools and products.", "u": null, "notes": "concept: NI001517164049", "dep": null}, {"v": "13349", "n": "Repair�Other", "d": "Other Repair courses.", "u": null, "notes": "concept: NI001517164050", "dep": null}, {"v": "13995", "n": "Manufacturing�Aide", "d": "Manufacturing�Aide courses offer interested students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164051", "dep": null}, {"v": "19255", "n": "Child Development/Parenting", "d": "Child Development/Parenting courses provide students with knowledge about family systems and relationships and information about how parents can address the physical, mental, emotional, and social growth and development of children from conception to adolescence. In addition, these courses help students discover how parents should respond to the various stages of childhood. Course content typically includes topics such as prenatal development and birth processes, responsibilities and difficulties of parenthood, family structures, societal and cultural influences, fundamentals of children's emotional and physical development, and the appropriate care of infants, toddlers, and young and school-aged children. These courses may also cover topics specific to teen parenting.", "u": null, "notes": "concept: NI001517164343", "dep": null}, {"v": "19997", "n": "Human Services�Independent Study", "d": "Human Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to providing human services. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164344", "dep": null}, {"v": "19998", "n": "Human Services�Workplace Experience", "d": "Human Services�Workplace Experience courses provide students with work experience in a field related to the provision of human services. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164345", "dep": null}, {"v": "19256", "n": "Clothing/Sewing", "d": "Clothing/Sewing courses introduce students to and expand their knowledge of various aspects of wearing apparel, sewing, and fashion. These courses typically include wardrobe planning; selection, care, and repair of various materials; and construction of one or more garments. They may also include related topics, such as fashion design and history, the social and psychological aspects of clothing, careers in the clothing industry, and craft sewing.", "u": null, "notes": "concept: NI001517164346", "dep": null}, {"v": "19257", "n": "Life Skills", "d": "Life Skills courses provide students with information about a wide range of subjects to assist them in becoming wise consumers and productive adults. These courses often emphasize process skills, including goal-setting, decisionmaking, and other topics such as the setting of priorities, money and time management, interpersonal relationships, and the development of the self. Additionally, specific topics such as wellness, selecting and furnishing houses, meeting transportation needs, nutrition, preparing food, selecting clothing and building a wardrobe, insurance, taxation, and consumer protection may also be covered.", "u": null, "notes": "concept: NI001517164347", "dep": null}, {"v": "19258", "n": "Personal and Career Readiness", "d": "Formerly known as Self-Management, Personal and Career Readiness courses introduce students to the skills and strategies that are helpful in becoming more focused, productive individuals, wage earners, and family members. These courses typically emphasize goal-setting; decisionmaking; managing time, energy, and stress; and identifying alternatives and coping strategies. They may also allow students to explore various career and lifestyle choices.", "u": null, "notes": "concept: NI001517164348", "dep": null}, {"v": "19259", "n": "Family and Interpersonal Relationships", "d": "Formerly known as Family Living, Family and Interpersonal Relationships courses emphasize building and maintaining healthy interpersonal relationships among family members and other members of society. These courses often emphasize (but are not limited to) topics such as the responsibilities of a family and wage earner, balancing a career and personal life, human sexuality and reproduction, marriage preparation, parenthood and the function of the family unit, the family life cycle, and life stages. They also cover topics related to stages of growth and social/dating practices", "u": null, "notes": "concept: NI001517164349", "dep": null}, {"v": "19260", "n": "Personal Development", "d": "Personal Development courses emphasize strengthening self-esteem, recognizing and resisting negative peer pressure, and developing coping skills for dealing with life and career issues and changes (such as family changes). These courses include communication, conflict resolution, practical problem-solving, and decisionmaking. They may also include building resiliency skills and asset building.", "u": null, "notes": "concept: NI001517164350", "dep": null}, {"v": "19261", "n": "Human Growth and Development", "d": "Human Growth and Development courses focus on the application of human development theories and stages of growth to the relationships among individuals at various stages of life, as well as provide an understanding of how people change across their lifespans. Course content may include the application of human development theories in family systems and community settings. Interactions of grandparents and their grandchildren, adult children and their aging parents, as well the similarities between caring for the elderly and caring for young children may also be explored.", "u": null, "notes": "concept: NI001517164351", "dep": null}, {"v": "19262", "n": "Consumer Economics/Personal Finance", "d": "Consumer Economics/Personal Finance courses provide students with an understanding of the concepts and principles involved in managing one's personal finances. These courses emphasize lifespan goal-setting, individual and family decisionmaking, and consumer rights as well as topics that are commonly associated with personal finance so that one can become a financially responsible consumer. Topics may include savings and investing, credit, insurance, taxes and social security, spending patterns and budget planning, contracts, and consumer protection. These courses may also investigate the effects of the global economy on consumers and the family.", "u": null, "notes": "concept: NI001517164352", "dep": null}, {"v": "19263", "n": "Home Environments and Design", "d": "Formerly known as Home D�cor, Home Environments and Design courses provide students with knowledge and skills regarding interior design and decoration of the home for the individual or family. While exploring design principles, personal needs and style and decision making, students may have an opportunity to explore such topics as color, texture, furniture styles and arrangement, lighting, window treatments, floor, wall coverings and home improvement/modification. These courses emphasize personal (rather than commercial) use and application of home d�cor principles.", "u": null, "notes": "concept: NI001517164353", "dep": null}, {"v": "19203", "n": "Apparel Construction", "d": "Apparel Construction courses provide students with the knowledge and skill to construct, alter, and repair clothing and textile products. Course topics typically include taking measurements, creating and preparing patterns, and various sewing techniques; topics may also include customer service, fashion design principles, and business management. These courses may also offer specialized knowledge in a particular type of garment.", "u": null, "notes": "concept: NI001517164354", "dep": null}, {"v": "19205", "n": "Home Furnishing", "d": "Home Furnishing courses provide students with basic knowledge regarding furnishing and decorating home environments. While exploring design principles, personal or customer needs and style, and decisionmaking, students may also explore the following topics: color, texture, furniture styles and arrangement, lighting, window treatments, floor and wall coverings, and home improvement/modification. Home Furnishing courses may also cover architectural style and design and take a larger look at housing problems or current housing issues.", "u": null, "notes": "concept: NI001517164356", "dep": null}, {"v": "19206", "n": "Home Furnishings Production", "d": "Home Furnishings Production courses enable students to plan, select, and construct upholstery, slip covers, draperies and other window treatments, and other home accessories. Some courses may emphasize upholstery exclusively. Course content typically includes proper use of equipment, interior decorating principles, and employability skills.", "u": null, "notes": "concept: NI001517164357", "dep": null}, {"v": "19207", "n": "Particular Topics in Apparel and Furnishings", "d": "These courses examine specific topics in apparel and furnishings other than those already described elsewhere in this classification system, such as tailoring or shoe repair, rather than providing a general study.", "u": null, "notes": "concept: NI001517164358", "dep": null}, {"v": "19295", "n": "Family and Consumer Sciences�Aide", "d": "Family and Consumer Sciences�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164359", "dep": null}, {"v": "19297", "n": "Family and Consumer Sciences�Independent Study", "d": "Family and Consumer Sciences�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to home- and self-management. Independent Study courses may provide students with an opportunity to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164360", "dep": null}, {"v": "19298", "n": "Family and Consumer Sciences�Workplace Experience", "d": "Family and Consumer Sciences�Workplace Experience courses provide students with work experience in a fields related to family and consumer sciences. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164361", "dep": null}, {"v": "19299", "n": "Family and Consumer Sciences�Other", "d": "Other Family and Consumer Sciences courses.", "u": null, "notes": "concept: NI001517164362", "dep": null}, {"v": "19301", "n": "Counseling and Mental Health", "d": "Counseling and Mental Health courses provide students with the knowledge and skills necessary to pursue a counseling and mental health career through simulated environments. These courses allow students to apply their knowledge of ethical and legal responsibilities, the limitations of these responsibilities, and the implications of their actions.", "u": null, "notes": "concept: NI001517164363", "dep": null}, {"v": "19995", "n": "Human Services�Aide", "d": "Human Services�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164364", "dep": null}, {"v": "19197", "n": "Education�Independent Study", "d": "Education�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to education. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164365", "dep": null}, {"v": "19198", "n": "Education�Workplace Experience", "d": "Education�Workplace Experience courses provide students with work experience in fields related to education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164366", "dep": null}, {"v": "19199", "n": "Education�Other", "d": "Other Education courses.", "u": null, "notes": "concept: NI001517164367", "dep": null}, {"v": "19201", "n": "Clothing and Textiles", "d": "Clothing and Textiles courses introduce students to and expand upon the various aspects of apparel, garment construction, and the textile industry, conveying the commercial application of design principles, production processes, and maintenance techniques. These courses usually address the selection, characteristics, care, and repair of various textiles; operation and care of commercial sewing machines; design, construction, and production of fabrics and/or garments; and career opportunities in the garment or textile industry.", "u": null, "notes": "concept: NI001517164368", "dep": null}, {"v": "19202", "n": "Clothing/Textile Maintenance", "d": "Clothing/Textile Maintenance courses provide students with the knowledge and skills to clean, care for, and maintain clothing and textiles. Course topics typically include dry cleaning and laundering techniques, identifying fabrics and the optimal cleaning agents and processes, instruction in altering and repairing garments, and the safe use of the equipment, tools, and agents.", "u": null, "notes": "concept: NI001517164369", "dep": null}, {"v": "19999", "n": "Human Services�Other", "d": "Other Human Services Care courses.", "u": null, "notes": "concept: NI001517164370", "dep": null}, {"v": "20116", "n": "Automotive Body Repair and Refinishing�Comprehensive", "d": "Automotive Body Repair and Refinishing courses provide students with knowledge and skills regarding the repair and refinishing of damaged or used cars. Course content may include (but is not limited to) stretching and shrinking auto body sheet metal; welding skills; frame and metal straightening; repair of fiberglass and synthetic materials; removing, repairing, and installing auto body parts such as panels, hoods, doors, and windows/glass; preparing vehicles and vehicle surfaces for refinishing; painting; applying body fillers; and estimating material and labor costs.", "u": null, "notes": "concept: NI001517164371", "dep": null}, {"v": "20117", "n": "Particular Topics in Automotive Body Repair and Refinishing", "d": "These courses provide specific instruction in individual topics relevant to the repair and refinishing of automobile bodies and surfaces. One topic or several closely related topics (such as nonstructural part replacement, auto body welding, or plastic repair) receive particular attention in this type of course.", "u": null, "notes": "concept: NI001517164372", "dep": null}, {"v": "20118", "n": "Boat Repair/Refinishing", "d": "Boat Repair/Refinishing courses convey a broad range of information and skills about how to repair and refinish boat mechanics, structures, and surfaces. In these courses, students become proficient in marine terminology, learn how to describe types of marine manufacturing and occupations, and prepare new and existing wood, fiberglass, and metal surfaces for painting or refinishing. These courses often cover safety, employability skills, and entrepreneurship.", "u": null, "notes": "concept: NI001517164373", "dep": null}, {"v": "20001", "n": "Exploration of Transportation, Distribution and Logistics", "d": "Exploration of Transportation, Distribution, and Logistics courses introduce students to careers that involve the planning, management, and movement of people, materials, and products using any of several modes of transport. Such careers may also involve infrastructure, vehicular maintenance and repair, and operating or managing facilities that hold what is being transported. Therefore, specific course topics vary widely and depend upon the careers being explored.", "u": null, "notes": "concept: NI001517164374", "dep": null}, {"v": "20051", "n": "Truck and Bus Driving", "d": "Truck and Bus Driving courses instruct students in the proper and safe handling and operation of trucks and buses. Strategies for driving in hazardous conditions, observing laws and regulations, loading cargo or passengers, documenting cargo loads, and expectations of driving careers are all typical course topics.", "u": null, "notes": "concept: NI001517164375", "dep": null}, {"v": "20052", "n": "Heavy Equipment Operation", "d": "Heavy Equipment Operation courses enable students to safely operate the heavy equipment used for mining, construction, and utility industries. Typically, courses also include light maintenance principles and techniques.", "u": null, "notes": "concept: NI001517164376", "dep": null}, {"v": "20053", "n": "Aviation", "d": "Aviation courses provide students with an understanding of the science of flight and typically include the history, regulations, and possible career paths within the aviation industry. Aviation courses usually cover physics, the relationships of weight and balance, principles of navigation and flight control, ground and airport operations and services, and Federal Aviation Agency regulations.", "u": null, "notes": "concept: NI001517164377", "dep": null}, {"v": "20054", "n": "Boat Operation", "d": "Boat Operation courses typically cover operation and maintenance of marine vehicles, marine navigation, and emergency procedures, as well as other skills necessary or useful for work or life at sea (e.g., loading and unloading or cooking). Specific topics may include docking and undocking a vessel, engine maintenance, commercial fishing, firefighting aboard ship, and CPR.", "u": null, "notes": "concept: NI001517164378", "dep": null}, {"v": "20055", "n": "Pilot Training", "d": "Pilot Training courses prepare students to become pilots by participating in flight training, ground school, and simulator instruction. Topics covered typically include preflight operations; flight maneuvering with reference to ground objects; flying at critically slow air speeds and recovering from stalls; takeoffs and landings; controlling and maneuvering an aircraft; cross country flying; night flying; and emergency operation. Other course content may include meteorology, aerodynamics, navigation, physiology, and airfield and flight environments.", "u": null, "notes": "concept: NI001517164379", "dep": null}, {"v": "20097", "n": "Operation�Independent Study", "d": "Operation�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to the operation of vehicles. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164380", "dep": null}, {"v": "20098", "n": "Operation�Workplace Experience", "d": "Operation�Workplace Experience courses provide students with work experience in fields related to the operation of vehicles. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164381", "dep": null}, {"v": "20099", "n": "Operation�Other", "d": "Other Operation courses.", "u": null, "notes": "concept: NI001517164382", "dep": null}, {"v": "24705", "n": "Hebrew IV", "d": "Hebrew IV courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Hebrew IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163067", "dep": null}, {"v": "24706", "n": "Hebrew V", "d": "Hebrew V courses prepare students to communicate authentically in Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Hebrew V courses promote students' understanding of the relationships among the products, practices, and perspectives of Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163068", "dep": null}, {"v": "24707", "n": "Hebrew for Native Speakers", "d": "Hebrew for Native Speakers courses prepare native and heritage speakers to communicate in Hebrew in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Hebrew for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Hebrew-speaking world.", "u": null, "notes": "concept: NI001517163069", "dep": null}, {"v": "24708", "n": "Hebrew Field Experience", "d": "Hebrew Field Experience courses place students in environments in which they interact with native Hebrew speakers, typically in settings where Hebrew is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163070", "dep": null}, {"v": "24556", "n": "Vietnamese V", "d": "Vietnamese V courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Vietnamese V courses promote students' understanding of the relationships among the products, practices, and perspectives of Vietnamese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163071", "dep": null}, {"v": "24557", "n": "Vietnamese for Native Speakers", "d": "Vietnamese for Native Speakers courses prepare native and heritage speakers to communicate in Vietnamese in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Vietnamese for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Vietnamese-speaking world.", "u": null, "notes": "concept: NI001517163072", "dep": null}, {"v": "24558", "n": "Vietnamese Field Experience", "d": "Vietnamese Field Experience courses place students in environments in which they interact with native Vietnamese speakers, typically in settings where Vietnamese is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163073", "dep": null}, {"v": "24559", "n": "Vietnamese Conversation and Culture", "d": "Vietnamese Conversation and Culture courses provide students with an introduction to the Vietnamese language and the culture(s) of Vietnamese-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163074", "dep": null}, {"v": "24560", "n": "Vietnamese Literature", "d": "Vietnamese Literature courses prepare students to communicate authentically in Vietnamese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Vietnamese. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Vietnamese cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163075", "dep": null}, {"v": "24561", "n": "Particular Topics in Vietnamese", "d": "Particular Topics in Vietnamese courses examine particular topics focused on Vietnamese language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163076", "dep": null}, {"v": "24562", "n": "IB Language A: Literature�Vietnamese", "d": "IB Language A: Literature�Vietnamese courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Vietnamese in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163077", "dep": null}, {"v": "24566", "n": "IB Language B (Vietnamese), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Vietnamese), Middle Years Program courses enable students to gain competence in modern Vietnamese and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163078", "dep": null}, {"v": "24599", "n": "Vietnamese�Other", "d": "Other Vietnamese courses", "u": null, "notes": "concept: NI001517163079", "dep": null}, {"v": "24600", "n": "Filipino (prior-to-secondary)", "d": "Filipino for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Filipino and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Filipino-speaking cultures.", "u": null, "notes": "concept: NI001517163080", "dep": null}, {"v": "24601", "n": "Filipino Immersion (prior-to-secondary)", "d": "Filipino Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Filipino and grade-specific content using Filipino as the language of instruction. Filipino Immersion courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Filipino-speaking cultures.", "u": null, "notes": "concept: NI001517163081", "dep": null}, {"v": "24602", "n": "Filipino I", "d": "Designed to introduce students to Filipino language and culture, Filipino I courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Filipino-speaking cultures.", "u": null, "notes": "concept: NI001517163082", "dep": null}, {"v": "24603", "n": "Filipino II", "d": "Filipino II courses build upon skills developed in Filipino I, preparing students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Filipino II courses introduce the relationships among the products, practices, and perspectives of Filipino-speaking cultures.", "u": null, "notes": "concept: NI001517163083", "dep": null}, {"v": "24604", "n": "Filipino III", "d": "Filipino III courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Filipino-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163084", "dep": null}, {"v": "24605", "n": "Filipino IV", "d": "Filipino IV courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Filipino IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Filipino-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163085", "dep": null}, {"v": "24606", "n": "Filipino V", "d": "Filipino V courses prepare students to communicate authentically in Filipino by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Filipino V courses promote students' understanding of the relationships among the products, practices, and perspectives of Filipino-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163086", "dep": null}, {"v": "24709", "n": "Hebrew Conversation and Culture", "d": "Hebrew Conversation and Culture courses provide students with an introduction to the Hebrew language and the culture(s) of Hebrew-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163087", "dep": null}, {"v": "24753", "n": "Arabic II", "d": "Arabic II courses build upon skills developed in Arabic I, preparing students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Arabic II courses introduce the relationships among the products, practices, and perspectives of Arabic-speaking cultures.", "u": null, "notes": "concept: NI001517163088", "dep": null}, {"v": "24810", "n": "Swahili Literature", "d": "Swahili Literature courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Swahili. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Swahili cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163089", "dep": null}, {"v": "24754", "n": "Arabic III", "d": "Arabic III courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Arabic-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163090", "dep": null}, {"v": "24755", "n": "Arabic IV", "d": "Arabic IV courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Arabic IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Arabic-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163091", "dep": null}, {"v": "24756", "n": "Arabic V", "d": "Arabic V courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Arabic V courses promote students' understanding of the relationships among the products, practices, and perspectives of Arabic-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163092", "dep": null}, {"v": "24757", "n": "Arabic for Native Speakers", "d": "Arabic for Native Speakers courses prepare native and heritage speakers to communicate in Arabic in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Arabic for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Arabic-speaking world.", "u": null, "notes": "concept: NI001517163093", "dep": null}, {"v": "24758", "n": "Arabic Field Experience", "d": "Arabic Field Experience courses place students in environments in which they interact with native Arabic speakers, typically in settings where Arabic is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163094", "dep": null}, {"v": "24759", "n": "Arabic Conversation and Culture", "d": "Arabic Conversation and Culture courses provide students with an introduction to the Arabic language and the culture(s) of Arabic-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163095", "dep": null}, {"v": "24760", "n": "Arabic Literature", "d": "Arabic Literature courses prepare students to communicate authentically in Arabic by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Arabic. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Arabic cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163096", "dep": null}, {"v": "24761", "n": "Particular Topics in Arabic", "d": "Particular Topics in Arabic courses examine particular topics focused on Arabic language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163097", "dep": null}, {"v": "24762", "n": "IB Language A: Literature�Arabic", "d": "IB Language A: Literature�Arabic courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Arabic in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163098", "dep": null}, {"v": "24763", "n": "IB Language B�Arabic", "d": "IB Language B�Arabic courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517163099", "dep": null}, {"v": "24766", "n": "IB Language B (Arabic), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Arabic), Middle Years Program courses allow students to gain competence in modern Arabic and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163100", "dep": null}, {"v": "24767", "n": "IB Language A: Language and Literature�Arabic", "d": "IB Language A: Language and Literature�Arabic courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Arabic in an academic context.", "u": null, "notes": "concept: NI001517163101", "dep": null}, {"v": "24768", "n": "IB Language Ab Initio�Arabic", "d": "IB Language Ab Initio�Arabic courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517163102", "dep": null}, {"v": "24799", "n": "Arabic�Other", "d": "Other Arabic courses", "u": null, "notes": "concept: NI001517163103", "dep": null}, {"v": "24800", "n": "Swahili (prior-to-secondary)", "d": "Swahili for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Swahili and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Swahili-speaking cultures.", "u": null, "notes": "concept: NI001517163104", "dep": null}, {"v": "03204", "n": "Technological Inquiry", "d": "Technological Inquiry courses provide students with an understanding of the use of process skills as an integral part of scientific activity and technological development. Students learn how scientific phenomena are explained, measured, predicted, organized, and communicated.", "u": null, "notes": "concept: NI001517163397", "dep": null}, {"v": "03205", "n": "Origins of Science", "d": "Origins of Science courses explore the body of scientific knowledge and discoveries from an historical perspective, wherein students gain an understanding of how one discovery led to others or to entire revolutions of thought. In these courses, original experiments may be replicated, and students may study primary materials.", "u": null, "notes": "concept: NI001517163398", "dep": null}, {"v": "03206", "n": "IB Design Technology", "d": "IB Design Technology courses prepare students to take the International Baccalaureate Design Technology exams. In keeping with the general aim of IB Experimental Sciences courses, IB Design Technology courses promote using critical-thinking and design skills to solve problems in a practical context. Practical/investigative work centers on the design process; product design, development, and innovation; green design; materials; and evaluation.", "u": null, "notes": "concept: NI001517163399", "dep": null}, {"v": "03166", "n": "AP Physics 2", "d": "Designed by the College Board to parallel second-semester college-level courses in algebra-based physics, AP Physics 2 courses cover fluid statics and dynamics; thermodynamics with kinetic theory, PV diagrams and probability; electrostatics; electrical circuits with capacitors; magnetic fields; electromagnetism; physical and geometric optics; and quantum, atomic, and nuclear physics. These courses may also include college-level laboratory investigations.", "u": null, "notes": "concept: NI001517163400", "dep": null}, {"v": "03197", "n": "Physics�Independent Study", "d": "Physics�Independent Study courses, often conducted with instructors as mentors, enable students to explore scientific topics of interest, using advanced methods of scientific inquiry and experimentation. These courses may be offered in conjunction with other rigorous science courses or may provide students with an opportunity to explore a topic of special interest.", "u": null, "notes": "concept: NI001517163401", "dep": null}, {"v": "03198", "n": "Physics�Workplace Experience", "d": "Physics�Workplace Experience courses provide work experience in a field related to physics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163402", "dep": null}, {"v": "03199", "n": "Physics�Other", "d": "Other Physics courses.", "u": null, "notes": "concept: NI001517163403", "dep": null}, {"v": "03201", "n": "Integrated Science", "d": "The specific content of Integrated Science courses varies, but they draw upon the principles of several scientific specialties�earth science, physical science, biology, chemistry, and physics�and organize the material around thematic units. Common themes covered include systems, models, energy, patterns, change, and constancy. These courses use appropriate aspects from each specialty to investigate applications of the theme.", "u": null, "notes": "concept: NI001517163404", "dep": null}, {"v": "03202", "n": "Unified Science", "d": "Unified Science courses combine more than one branch of science into a cohesive study or may integrate science with another discipline. General scientific concepts are explored, including the principles underlying the scientific method and experimentation techniques.", "u": null, "notes": "concept: NI001517163405", "dep": null}, {"v": "03212", "n": "Scientific Research and Design", "d": "In Scientific Research and Design courses, students conceive of, design, and complete a project using scientific inquiry and experimentation methodologies. Emphasis is typically placed on safety issues, research protocols, controlling or manipulating variables, data analysis, and a coherent display of the project and its outcome(s).", "u": null, "notes": "concept: NI001517163406", "dep": null}, {"v": "03235", "n": "Science (grade 5)", "d": "Science (grade 5) courses build on the study of various systems. They may include identification and description of cycles, comparisons of forms of matter and energy, forces, or content consistent with state academic standards. Students may make comparisons and interpret and analyze information. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163407", "dep": null}, {"v": "03236", "n": "Science (grade 6)", "d": "Science (grade 6) courses typically include subject matter from several strands of science, including earth/space sciences, physical sciences, and life or environmental sciences, and may organize material around thematic units. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163408", "dep": null}, {"v": "03237", "n": "Science (grade 7)", "d": "Science (grade 7) courses build on previous years of scientific inquiry and typically include subject matter from several strands of science, including earth sciences, physical sciences, and life or environmental sciences, and may organize material around thematic units. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163409", "dep": null}, {"v": "03238", "n": "Science (grade 8)", "d": "Science (grade 8) courses typically include subject matter from several strands of science, including earth sciences, physical sciences, and life or environmental sciences, and may organize material around thematic units. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163410", "dep": null}, {"v": "03239", "n": "Science�General", "d": "Science�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Science, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163411", "dep": null}, {"v": "03213", "n": "IB Sciences, Middle Years Program", "d": "International Baccalaureate (IB) Sciences, Middle Years Program courses provide to students a body of knowledge and an understanding of the scientific approach to problem solving. It may be organized as biology, chemistry, and physics, or as an integrated sciences course. The course requires students to formulate hypotheses, design and carry out experiments to test them, and evaluate results.", "u": null, "notes": "concept: NI001517163412", "dep": null}, {"v": "03214", "n": "Forensic Laboratory Science", "d": "Forensic Laboratory Science courses involve the application of biological, chemical, and physical science principles to data and physical evidence related to evidence collection and analysis. The courses focus on the application of scientific knowledge and scientific principles to collect, preserve, and analyze evidence in a laboratory setting. Topics may include but are not limited to entomology, forensic anthropology, serology, and fingerprinting.", "u": null, "notes": "concept: NI001517163413", "dep": null}, {"v": "03228", "n": "Science (early childhood education)", "d": "Science (early childhood education) courses cover foundational skills and concepts related to science, such as investigation and observation. Content is age appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163414", "dep": null}, {"v": "03207", "n": "AP Environmental Science", "d": "AP Environmental Science courses are designed by the College Board to provide students with the scientific principles, concepts, and methodologies required to understand the interrelationships of the natural world, identify and analyze environmental problems (both natural and human made), evaluate the relative risks associated with the problems, and examine alternative solutions for resolving and/or preventing them. Topics covered include science as a process, ecological processes and energy conversions, earth as an interconnected system, the impact of humans on natural systems, cultural and societal contexts of environmental problems, and the development of practices that will ensure sustainable systems.", "u": null, "notes": "concept: NI001517163415", "dep": null}, {"v": "03208", "n": "IB Environmental Systems and Societies", "d": "IB Environmental Systems courses prepare students to take the International Baccalaureate Environmental Systems exam by providing them with the knowledge, methods, and techniques to understand the nature and functioning of natural systems, the relationships that affect environmental equilibrium, and human impact on the biosphere. Topics also include ecosystem integrity and sustainability, students' own relationships to the environment, and the nature of internationalism in resolving major environmental issues. This is considered an interdisciplinary course and students may receive credit within two IB subject areas: sciences, and individuals and societies.", "u": null, "notes": "concept: NI001517163416", "dep": null}, {"v": "03209", "n": "Aerospace", "d": "Aerospace courses explore the connection between meteorology, astronomy, and flight across and around the earth as well as into outer space. In addition to principles of meteorology (e.g., atmosphere, pressures, winds and jet streams) and astronomical concepts (e.g., solar system, stars, and interplanetary bodies), course topics typically include the history of aviation, principles of aeronautical decisionmaking, airplane systems, aerodynamics, and flight theory.", "u": null, "notes": "concept: NI001517163417", "dep": null}, {"v": "03210", "n": "Science, Technology and Society", "d": "Science, Technology, and Society courses encourage students to explore and understand the ways in which science and technology shape culture, values, and institutions and how such factors, in turn, shape science and technology. Topics covered may include how science and technology enter society and how they change as a result of social processes.", "u": null, "notes": "concept: NI001517163418", "dep": null}, {"v": "03211", "n": "Technical Science", "d": "Technical Science courses introduce students to scientific tools and methods and provide an introduction to chemistry and physics. Topics covered typically include measurement conversion, model creation, use of scientific methods, interpretation of atoms, identification of the properties of common compounds, analysis of chemical equations, the impact of force on linear motion, and the study of various physical phenomena and forms of energy.", "u": null, "notes": "concept: NI001517163419", "dep": null}, {"v": "03229", "n": "Science (pre-kindergarten)", "d": "Science (pre-kindergarten) courses cover foundational skills and concepts related to science, such as investigation and observation. Content is age-appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163420", "dep": null}, {"v": "03230", "n": "Science (kindergarten)", "d": "Science (kindergarten) courses encourage students to observe and describe properties of organisms, systems, and the environment. Students may raise questions, identify patterns, and record observations. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163421", "dep": null}, {"v": "03231", "n": "Science (grade 1)", "d": "Science (grade 1) courses allow students to identify interactions and patterns in objects and events and to record observations in written or visual form. Typically, students investigate systems of living organisms and the environment. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163422", "dep": null}, {"v": "03232", "n": "Science (grade 2)", "d": "Science (grade 2) courses continue to introduce students to basic scientific processes and principles. Course content may include identification of patterns, classification and sequencing, or manipulation of systems to observe interactions between parts and record the effects of change. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163423", "dep": null}, {"v": "03233", "n": "Science (grade 3)", "d": "Science (grade 3) courses involve observation, measurement, and description of simple systems. Course content may include the scientific process; life and environmental science; and physical, earth, and space science. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163424", "dep": null}, {"v": "03234", "n": "Science (grade 4)", "d": "Science (grade 4) courses typically explore complex systems, such as plant and animal adaptation, forces and motion, and physical and chemical changes in matter, or content consistent with state academic standards. Students may identify causes and effects of change, make predictions, and gather data from multiple sources. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163425", "dep": null}, {"v": "03994", "n": "Life and Physical Sciences�Proficiency Development", "d": "Life and Physical Sciences�Proficiency Development courses are designed to assist students in acquiring the skills necessary to pass proficiency examinations related to the life sciences and physical sciences.", "u": null, "notes": "concept: NI001517163426", "dep": null}, {"v": "04052", "n": "World History and Geography", "d": "In addition to covering the objectives of World History�Overview courses, World History and Geography courses provide an overview of world geography. These courses are often developed in response to increased national concern regarding the importance of geography, and they explore geographical concepts.", "u": null, "notes": "concept: NI001517163427", "dep": null}, {"v": "04053", "n": "Modern World History", "d": "Modern World History courses provide an overview of the history of human society in the past few centuries�from the Renaissance period, or later, to the contemporary period�exploring political, economic, social, religious, military, scientific, and cultural developments.", "u": null, "notes": "concept: NI001517163428", "dep": null}, {"v": "04054", "n": "IB History", "d": "IB History courses prepare students to take the International Baccalaureate History exams. In these courses, students study historical developments at national, regional, and international levels; critically reflect on their relationship to the present; and explore the nature of historical documentation and the methods used by historians. IB History courses may survey the history of Europe and the Islamic world or focus on 20th-century topics in an international context and may enable students to undertake individual study on a subject of interest in greater detail and depth.", "u": null, "notes": "concept: NI001517163429", "dep": null}, {"v": "04055", "n": "Modern European History", "d": "Modern European History courses examine the development of political, social, and economic movements in Europe over the past few centuries (from the Renaissance period, or later, to the contemporary period) and usually include such topics as the rise of the modern nation state, scientific and industrial revolutions, the age of exploration and nationalism, imperialism, and world war.", "u": null, "notes": "concept: NI001517163430", "dep": null}, {"v": "04056", "n": "AP European History", "d": "Following the College Board's suggested curriculum designed to parallel college-level European History courses, AP European History courses examine European civilization in four chronological periods, from 1450 to the present, and also expose students to the factual narrative. In addition, these courses help students develop an understanding of some of the principal themes in modern European history and the abilities to analyze historical evidence and to express that understanding and analysis in writing.", "u": null, "notes": "concept: NI001517163431", "dep": null}, {"v": "04058", "n": "Ancient Civilizations", "d": "Ancient Civilizations courses provide a survey of the evolution of society from the ancient Middle East through Greek and Roman civilizations. Typically, in these courses, students study the rise and fall of civilizations and empires, with an emphasis on the legacies they provide to successive societies.", "u": null, "notes": "concept: NI001517163432", "dep": null}, {"v": "03995", "n": "Life and Physical Sciences�Aide", "d": "Life and Physical Sciences�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students and may serve as laboratory assistants.", "u": null, "notes": "concept: NI001517163433", "dep": null}, {"v": "03996", "n": "Life and Physical Sciences�Supplemental", "d": "Life and Physical Sciences�Supplemental courses, designed to be taken in addition or in coordination with other life and physical science courses, provide instruction to assist students in acquiring science skills so that students attain necessary grade-level skills or reach a desired competency level.", "u": null, "notes": "concept: NI001517163434", "dep": null}, {"v": "03997", "n": "Life and Physical Sciences�Independent Study", "d": "Life and Physical Sciences�Independent Study courses, often conducted with instructors as mentors, enable students to explore scientific topics of interest, using advanced methods of scientific inquiry and experimentation. These courses may be offered in conjunction with other rigorous science courses or may serve as an opportunity to explore a topic of special interest.", "u": null, "notes": "concept: NI001517163435", "dep": null}, {"v": "03998", "n": "Life and Physical Sciences�Workplace Experience", "d": "Life and Physical Sciences�Workplace Experience courses provide work experience in a field related to life and/or physical science. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163436", "dep": null}, {"v": "03999", "n": "Life and Physical Sciences�Other", "d": "Other Life and Physical Sciences courses.", "u": null, "notes": "concept: NI001517163437", "dep": null}, {"v": "04001", "n": "World Geography", "d": "World Geography courses provide students with an overview of world geography, but may vary widely in the topics they cover. Topics typically include the physical environment; the political landscape; the relationship between people and the land; economic production and development; and the movement of people, goods, and ideas.", "u": null, "notes": "concept: NI001517163438", "dep": null}, {"v": "07012", "n": "Prayer and Spirituality", "d": "Prayer and Spirituality courses vary widely, but seek to enable students to experience deeper communion with the divine through public and private worship. Course content may include an examination or exploration of traditional and contemporary practices.", "u": null, "notes": "concept: NI001517163723", "dep": null}, {"v": "07013", "n": "Religious Ethics and Morality", "d": "Usually including an introduction to or examination of the tenets of a particular faith, Religious Ethics and Morality courses seek to enable students to apply the moral teachings of a faith to their own lives, to the larger community, and to their decision-making processes. Course content may focus on such issues as peace and justice, death and dying, human sexuality, professional ethics, and human rights.", "u": null, "notes": "concept: NI001517163724", "dep": null}, {"v": "07014", "n": "Justice, Peace, and Faith", "d": "Justice, Peace, and Faith courses examine the scriptural foundations for justice, typically with a historical overview of a faith's social teaching. These courses discuss such topics as poverty, hunger, conflict, discrimination, justice, and environmental issues, with a view toward developing students' ability to critically reflect upon and analyze their own roles and responsibilities.", "u": null, "notes": "concept: NI001517163725", "dep": null}, {"v": "07015", "n": "Faith and Lifestyle", "d": "Faith and Lifestyle courses focus on the development of young adults from puberty to adulthood, approached from the perspective of a faith or church. In these courses, the religion's values and traditions provide an underpinning for examining such topics as identity, independence, sexuality, employment, and leisure. Typically, Faith and Lifestyle courses include discussions about adult roles� single life, marriage, religious life, and ordained ministry.", "u": null, "notes": "concept: NI001517163726", "dep": null}, {"v": "07016", "n": "Ministry", "d": "Ministry courses introduce students to the vocation of service. Students may learn counseling skills, plan and participate in religious services, and minister to younger students or to members of the local community (assisting in hospitals and convalescent homes, crisis centers, soup kitchens, and so on).", "u": null, "notes": "concept: NI001517163727", "dep": null}, {"v": "07017", "n": "IB World Religions", "d": "IB World Religions courses prepare students to take the International Baccalaureate exam. These courses are designed to provide students with the means to study the beliefs and practices of nine main religions of the world. These courses may include an in-depth study of several religions with an emphasis on thematic elements. An investigative study of the religious experience is also included.", "u": null, "notes": "concept: NI001517163728", "dep": null}, {"v": "07018", "n": "Particular Topics in Religion", "d": "Particular Topics in Religion courses focus on a specific topic within the field of religion (such as religious identity or the investigation of a particular figure) not otherwise described in this classification system.", "u": null, "notes": "concept: NI001517163729", "dep": null}, {"v": "07995", "n": "Religious Education and Theology�Aide", "d": "Religious Education and Theology�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163730", "dep": null}, {"v": "07997", "n": "Religious Education and Theology�Independent Study", "d": "Religious Education and Theology�Independent Study courses, often conducted with instructors, members of the clergy, or religious leaders as mentors, enable students to explore topics of interest related to religion or theology. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular religion, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163731", "dep": null}, {"v": "07998", "n": "Religious Education and Theology�Workplace Experience", "d": "Religious Education and Theology�Workplace Experience courses provide students with work experience in a field related to religion and theology. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163732", "dep": null}, {"v": "07999", "n": "Religious Education and Theology�Other", "d": "Other Religious Education and Theology courses.", "u": null, "notes": "concept: NI001517163733", "dep": null}, {"v": "08010", "n": "Aquatics/Water Sports", "d": "Aquatic/Water Sports courses help students develop skills useful or necessary in an aquatic environment. They may focus on swimming and competitive strokes, such as freestyle, breaststroke, butterfly, and so on or may involve team-oriented water sports, such as water polo and relay swimming. These courses may also include (or concentrate exclusively on) diving and/or lifesaving skills.", "u": null, "notes": "concept: NI001517163734", "dep": null}, {"v": "08011", "n": "Tennis", "d": "Tennis courses help students develop knowledge, skills, and abilities related to the sport of singles or doubles tennis, including shots (such as serves, forehand strokes, backhand strokes, and lobs), scoring, and strategy.", "u": null, "notes": "concept: NI001517163735", "dep": null}, {"v": "08012", "n": "Self-defense", "d": "Self-defense courses help students develop knowledge, skills, and abilities to defend themselves against attack by others, usually incorporating traditional self-defense methods. Students may also be taught techniques from martial arts, addressing the differences among those arts and their contribution to defense and sport.", "u": null, "notes": "concept: NI001517163736", "dep": null}, {"v": "08013", "n": "Specific Sports Activities", "d": "Specific Sports Activities courses help students develop knowledge, experience, and skills in a single sport or activity (such as basketball, volleyball, football, baseball, hockey, wrestling, soccer, track and field, and equestrian events) other than those coded within this section. (Dance is included under the Fine and Performing Arts subject area.)", "u": null, "notes": "concept: NI001517163737", "dep": null}, {"v": "08014", "n": "Physical Education Equivalent", "d": "Physical Education Equivalent courses award physical education credit for other at-school activities, such as marching band or cheerleading. (Dance is included under the Fine and Performing Arts subject area.)", "u": null, "notes": "concept: NI001517163738", "dep": null}, {"v": "08015", "n": "Off-Campus Sports", "d": "Off-Campus Sports courses award physical education credit for off-campus sports activities (e.g., swimming, weight training, or any individual or team sports) taken at a community center or other location off the school campus.", "u": null, "notes": "concept: NI001517163739", "dep": null}, {"v": "08016", "n": "Lifetime Fitness Education", "d": "Lifetime Fitness Education courses emphasize acquiring knowledge and skills regarding lifetime physical fitness; content may include related topics such as nutrition, stress management, and consumer issues. Students may develop and implement a personal fitness plan.", "u": null, "notes": "concept: NI001517163740", "dep": null}, {"v": "08017", "n": "Sports Physiology", "d": "Courses in Sports Physiology examine human anatomy and physiology as they pertain to human movement and physical performance in sports activities. These courses may also emphasize the prevention and treatment of athletic injuries.", "u": null, "notes": "concept: NI001517163741", "dep": null}, {"v": "08018", "n": "Coaching", "d": "Coaching courses emphasize the responsibilities, duties, and problems in training and instructing athletes and athletic teams. Course topics typically include principles of behavior, teaching, physical and mental training, and team management. Different coaching philosophies, outcomes, and styles may also be covered.", "u": null, "notes": "concept: NI001517163742", "dep": null}, {"v": "08019", "n": "Officiating", "d": "Officiating courses provide students with the knowledge, skills, and abilities to serve as a referee, umpire, judge, or other official for a sports contest, emphasizing rule interpretation and the proper mechanics of officiating.", "u": null, "notes": "concept: NI001517163743", "dep": null}, {"v": "08028", "n": "Physical Education (early childhood education)", "d": "Physical Education (early childhood education) courses emphasize fundamental movement skills, body awareness and control, safety, and the enjoyment of physical activity. Specific content depends upon state standards for early childhood education.", "u": null, "notes": "concept: NI001517163744", "dep": null}, {"v": "08029", "n": "Physical Education (pre-kindergarten)", "d": "Physical Education (pre-kindergarten) courses emphasize fundamental movement skills, body awareness and control, safety, and the enjoyment of physical activity. Specific content depends upon state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163745", "dep": null}, {"v": "08030", "n": "Physical Education (kindergarten)", "d": "Physical Education (kindergarten) courses emphasize fundamental movement skills, body awareness and control, safety, and the enjoyment of physical activity. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163746", "dep": null}, {"v": "08049", "n": "Physical Education�Other", "d": "Other Physical Education courses.", "u": null, "notes": "concept: NI001517163747", "dep": null}, {"v": "08051", "n": "Health Education", "d": "Topics covered within Health Education courses may vary widely, but typically include personal health (nutrition, mental health and stress management, drug/alcohol abuse prevention, disease prevention, and first aid) and consumer health issues. The courses may also include brief studies of environmental health, personal development, and/or community resources.", "u": null, "notes": "concept: NI001517163748", "dep": null}, {"v": "08052", "n": "Health and Fitness", "d": "Health and Fitness courses combine the topics of Health Education courses (nutrition, stress management, substance abuse prevention, disease prevention, first aid, and so on) with an active fitness component (typically including aerobic activity and fitness circuits) with the intention of conveying the importance of life-long wellness habits.", "u": null, "notes": "concept: NI001517163749", "dep": null}, {"v": "08053", "n": "Community Health", "d": "Community Health courses cover not only personal health topics (nutrition, stress management, substance abuse prevention, disease prevention, first aid, and so on), but also more general health issues. These additional topics may include (among others) available community resources, fundamentals of the nation's health care system, contemporary world health issues, and career options within the health field.", "u": null, "notes": "concept: NI001517163750", "dep": null}, {"v": "08038", "n": "Physical Education (grade 8)", "d": "Physical Education (grade 8) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Activities typically include those that increase strength, endurance, and flexibility; reinforce safe technique; teach the rules and conventions of games and sports; and explore the relationship between physical activity and health. Health topics (such as the effects of drugs and alcohol, sexual education, and healthy lifestyles) may also be included. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163751", "dep": null}, {"v": "08039", "n": "Physical Education�General", "d": "Physical Education�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Physical Education, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163752", "dep": null}, {"v": "08040", "n": "IB Physical and Health Education, Middle Years Program", "d": "International Baccalaureate (IB) Physical and Health Education, Middle Years Program courses aim to facilitate physical, intellectual, emotional, and social development, and to cultivate a healthy and active lifestyle. These courses include activities that are enjoyable and contribute to healthy living. They help students develop motor skills necessary to participate in a variety of physical activities, and to learn about the nature of physical fitness.", "u": null, "notes": "concept: NI001517163753", "dep": null}, {"v": "08047", "n": "Physical Education�Independent Study", "d": "Courses in Physical Education�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to physical education. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular sport or activity, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163754", "dep": null}, {"v": "08048", "n": "Physical Education�Workplace Experience", "d": "Physical Education�Workplace Experience courses provide work experience in a field related to physical education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences encountered in the workplace.", "u": null, "notes": "concept: NI001517163755", "dep": null}, {"v": "08073", "n": "Health Education (grade 3)", "d": "Health Education (grade 3) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163756", "dep": null}, {"v": "08074", "n": "Health Education (grade 4)", "d": "Health Education (grade 4) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163757", "dep": null}, {"v": "08075", "n": "Health Education (grade 5)", "d": "Health Education (grade 5) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163758", "dep": null}, {"v": "08076", "n": "Health Education (grade 6)", "d": "Health Education (grade 6) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163759", "dep": null}, {"v": "08072", "n": "Health Education (grade 2)", "d": "Health Education (grade 2) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163760", "dep": null}, {"v": "08077", "n": "Health Education (grade 7)", "d": "Health Education (grade 7) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163761", "dep": null}, {"v": "08078", "n": "Health Education (grade 8)", "d": "Health Education (grade 8) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163762", "dep": null}, {"v": "08079", "n": "Health Education�General", "d": "Health Education�General courses involve health-related content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Health Education, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163763", "dep": null}, {"v": "08099", "n": "Health Education�Other", "d": "Other Health Education courses.", "u": null, "notes": "concept: NI001517163764", "dep": null}, {"v": "08108", "n": "Physical and Health Education (grade 4)", "d": "Physical and Health Education (grade 4) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163765", "dep": null}, {"v": "13997", "n": "Manufacturing�Independent Study", "d": "Manufacturing�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to manufacturing. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164052", "dep": null}, {"v": "13998", "n": "Manufacturing�Workplace Experience", "d": "Manufacturing�Workplace Experience courses provide students with work experience in fields involving manufacturing, supported by classroom attendance and discussion. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164053", "dep": null}, {"v": "13999", "n": "Manufacturing�Other", "d": "Other Manufacturing courses.", "u": null, "notes": "concept: NI001517164054", "dep": null}, {"v": "14001", "n": "Exploration of Health Care Occupations", "d": "Exploration of Health Care Occupations courses expose students to the variety of opportunities available within the health care industry (e.g., nursing, therapy, dental care, administrative services, and lab technology). These courses provide experiences in several of these occupational clusters, along with information and knowledge related to the health care industry as a whole.", "u": null, "notes": "concept: NI001517164055", "dep": null}, {"v": "14002", "n": "Health Care Occupations�Comprehensive", "d": "Health Care Occupations�Comprehensive courses provide students with an orientation to the health care industry and help refine their health care-related knowledge and skills. Topics covered usually include (but are not limited to) an overview of health care delivery; patient care, including assessment of vital signs, body mechanics, and diet; anatomy and physiology; identification and use of medical equipment and supplies; medical terminology; hygiene and disease prevention; first aid and CPR procedures; laboratory procedures; and ethical and legal responsibilities.", "u": null, "notes": "concept: NI001517164056", "dep": null}, {"v": "14003", "n": "Medical Law and Ethics", "d": "Medical Law and Ethics courses introduce students to the principles of medical law, medical ethics, and bioethics. These courses emphasize the function of law and ethical issues as it applies to the medical environment.", "u": null, "notes": "concept: NI001517164057", "dep": null}, {"v": "14051", "n": "Nursing", "d": "Nursing courses place a special emphasis on the particular knowledge and skills required of nurses and/or nursing assistants and aides while covering general health care topics (i.e., patient care, anatomy and physiology, medical terminology, hygiene and disease prevention, first aid and CPR, and laboratory procedures). Topics covered typically include normal growth and development; bathing, feeding, dressing, and transporting patients; basic pharmacology; doctor, nurse, and patient relationships and roles; medical and professional ethics; death and dying; and care of various kinds of patients (e.g., chronically ill, children, new mothers, and so on).", "u": null, "notes": "concept: NI001517164058", "dep": null}, {"v": "14052", "n": "Nursing�LPN", "d": "Covering the same scope of topics as Nursing courses, Nursing�LPN courses delve into more depth in order to prepare students for the state's practical nurse licensing examination. Nursing�LPN courses offer the knowledge and experience needed to provide nursing care for patients of all ages, in various stages of sickness or health, and with a variety of disease conditions. Additional topics covered may include community health, nutrition, drug therapy and administration, and mental illness.", "u": null, "notes": "concept: NI001517164059", "dep": null}, {"v": "14059", "n": "Gerontology", "d": "Gerontology courses provide students with knowledge and understanding of the processes of adult development and aging. Topics covered may include the study of the biological, economic, psychological, social, and health/fitness aspects of the aging process.", "u": null, "notes": "concept: NI001517164060", "dep": null}, {"v": "14060", "n": "Physical Therapy", "d": "Physical Therapy courses provide students with the knowledge and skills necessary to work with patients who need to achieve and maintain functional rehabilitation and to prevent malfunction or deformity. Topics covered typically include therapeutic exercises and activities (such as stretching and strengthening), how to train patients to perform the activities of daily living, the use of special equipment, and evaluation of patient progress.", "u": null, "notes": "concept: NI001517164061", "dep": null}, {"v": "14053", "n": "Home Health Care", "d": "Home Health Care courses teach students how to care for individuals within their homes. Course content relates health care practices and procedures to the home environment, and typically includes patient care, comfort, and safety; anatomy and physiology; the prevention of disease and infection; nutrition and meal preparation; human relations; and first aid and CPR. Topics covered may also include therapy strategies, household management, and employability.", "u": null, "notes": "concept: NI001517164062", "dep": null}, {"v": "14054", "n": "Dental Science", "d": "Dental Science courses expose students to the tools, terminology, and procedures necessary for a career in the dental industry. Course content covers a wide range of topics and typically includes dental anatomy and terminology; the identification and use of dental equipment; dental pathologies and procedures; asepsis; dental laboratory procedures; emergency first aid; and the ethical and legal responsibilities of dental care workers. These courses often explore dental specialties and career options.", "u": null, "notes": "concept: NI001517164063", "dep": null}, {"v": "14055", "n": "Emergency Medical Technology", "d": "Emergency Medical Technology courses place a special emphasis on the knowledge and skills needed in medical emergencies. Topics typically include clearing airway obstructions, controlling bleeding, bandaging, methods for lifting and transporting injured persons, simple spinal immobilization, infection control, stabilizing fractures, and responding to cardiac arrest. The courses may also cover the legal and ethical responsibilities involved in dealing with medical emergencies. These courses may prepare students to obtain certification in Emergency Medical Response (EMR), CPR, First Aid, Incident Command System (ICS), and Wilderness First Responder.", "u": null, "notes": "concept: NI001517164064", "dep": null}, {"v": "14056", "n": "Surgical Technology", "d": "Surgical Technology courses emphasize the care and needs of patients undergoing surgery while covering general health care topics (i.e., patient care, anatomy and physiology, medical terminology, hygiene and disease prevention, first aid and CPR, and laboratory procedures). In keeping with that focus, topics may include operation room materials, tools, and procedures; aseptic surgical techniques; preparation and handling of surgical instruments; efficiency in the operating room; and the roles of various medical personnel who are present during surgery.", "u": null, "notes": "concept: NI001517164065", "dep": null}, {"v": "14057", "n": "Vision Care", "d": "Vision Care courses expose students to the tools, terminology, and procedures necessary for a career in the optometric or optic field. Vision Care courses typically include the physics of light and refraction; the anatomy, physiology, and terminology associated with the eyes; identification and use of optometric and/or optical equipment; optical procedures; human relations; and the ethical and legal responsibilities of vision care workers.", "u": null, "notes": "concept: NI001517164066", "dep": null}, {"v": "14058", "n": "Optometrics", "d": "Optometrics courses provide students with the knowledge, ability, and experiences to prepare, assemble, and/or fit corrective lenses prescribed by a physician or optometrist. Topics covered may include layout and marking, cutting and chipping, edging and beveling, inspection, alignment, dispensing, and selection of eyewear.", "u": null, "notes": "concept: NI001517164067", "dep": null}, {"v": "14103", "n": "EKG Technology", "d": "In EKG Technology courses, students acquire the knowledge and skills to perform electrocardiograph activities and learn about the cardiovascular system (including its function, diseases, and rhythms); EKG machinery; and the use of drugs and their effects. These courses usually include general health care topics as well, such as basic anatomy and physiology, patient care, first aid and CPR, identification and use of medical equipment, and medical terminology.", "u": null, "notes": "concept: NI001517164068", "dep": null}, {"v": "14153", "n": "Medical Office Procedures", "d": "Medical Office Procedures courses expose students to clerical knowledge, abilities, and procedures as they apply to the medical field. These courses typically include (but are not limited to) topics such as medical transcription, medical insurance, financial accounting, scheduling, and patient record-keeping. Medical terminology and routine medical procedures are covered to provide a context for clerical duties.", "u": null, "notes": "concept: NI001517164069", "dep": null}, {"v": "14154", "n": "Medical Terminology", "d": "In Medical Terminology courses, students learn how to identify medical terms by analyzing their components. These courses emphasize defining medical prefixes, root words, suffixes, and abbreviations. The primary focus is on developing both oral and written skills in the language used to communicate within health care professions.", "u": null, "notes": "concept: NI001517164070", "dep": null}, {"v": "14155", "n": "Particular Topics in Health Information", "d": "These courses examine particular topics in health Information other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164071", "dep": null}, {"v": "14156", "n": "Medical Coding and Transcription", "d": "Medical Coding and Transcription courses introduce students to the International Classification of Diseases, Clinical Modification and its system of hospital codes for diagnoses and procedures. These courses provide opportunities for students to practice and develop skills in the use of transcription equipment and to gain familiarity with common formats of medical terminology and reports.", "u": null, "notes": "concept: NI001517164072", "dep": null}, {"v": "14157", "n": "Health Informatics and Data Management", "d": "Health Informatics and Data Management courses introduce students to automated information systems in the health care delivery system. These courses teach students terminology and essential concepts of health information systems and management of data, including the purpose, content, and structure of health data; numbering and filing systems; storage and retention methods; and the construction and design of forms, records, indexes, and registers. These courses may also examine data integrity, privacy/security issues, and the purposes of accreditation and regulatory standards in developing health record practice guidelines.", "u": null, "notes": "concept: NI001517164073", "dep": null}, {"v": "14104", "n": "Phlebotomy", "d": "In Phlebotomy courses, students acquire knowledge, skills, and experiences related to the drawing of blood and typically learn about such topics as infection control, sterilization practices, medical/hospital procedures and environments, diagnostic procedures, proper storage and handling of specimens, and the process of drawing blood.", "u": null, "notes": "concept: NI001517164074", "dep": null}, {"v": "14061", "n": "Respiratory Therapy", "d": "Respiratory Therapy courses provide students with the knowledge and skills necessary to work with patients who have breathing or other cardiopulmonary difficulties or disorders. Topics covered typically include identifying deficiencies and abnormalities of the cardiopulmonary system, understanding the various methods of therapies, and understanding how to use special equipment.", "u": null, "notes": "concept: NI001517164075", "dep": null}, {"v": "14062", "n": "Sports Medicine", "d": "Formerly known as Care of Athletes, Sports Medicine courses provide students with the knowledge and skills to understand and perform therapeutic tasks that would be designated by an athletic or fitness trainer. Topics covered may include taping and bandaging, proper use of protective padding, treatment modalities, anatomy and physiology, and medical terminology. Students may learn to measure cardiorespiratory endurance, muscular strength and endurance, flexibility, body composition, and blood pressure. More advanced topics may include injury assessment, the phases of healing, and the use of exercise and equipment to help in the reconditioning of injured athletes.", "u": null, "notes": "concept: NI001517164076", "dep": null}, {"v": "14063", "n": "Particular Topics in Therapeutic Services", "d": "These courses examine particular topics in medical therapeutic services other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164077", "dep": null}, {"v": "14097", "n": "Therapeutic Services�Independent Study", "d": "Therapeutic Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to therapeutic services. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164078", "dep": null}, {"v": "14098", "n": "Therapeutic Services�Workplace Experience", "d": "Therapeutic Services�Workplace Experience courses provide students with work experience in fields related to therapeutic services. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164079", "dep": null}, {"v": "14099", "n": "Therapeutic Services�Other", "d": "Other Therapeutic Services courses.", "u": null, "notes": "concept: NI001517164080", "dep": null}, {"v": "14101", "n": "Dental Laboratory Technology", "d": "Dental Laboratory Technology courses expose students to the principals, tools, terminology, and procedures necessary for a career in a dental laboratory. These courses typically cover many of the same topics as Dental Science, but emphasize making mouth guards, taking impressions, creating various types of dental molds and models, and fabricating prostheses and dental appliances.", "u": null, "notes": "concept: NI001517164081", "dep": null}, {"v": "14102", "n": "Medical Lab Technology", "d": "Medical Lab Technology courses provide students with the knowledge and skills necessary for employment in health care-related laboratories. Topics include basic principles of anatomy and physiology, relevant concepts in microbiology and chemistry, and laboratory techniques (including preparation and analysis of various cultures and specimens). The courses may also cover such components as venipuncture, EKG, and CPR procedures.", "u": null, "notes": "concept: NI001517164082", "dep": null}, {"v": "14105", "n": "Particular Topics in Diagnostic Services", "d": "These courses examine particular topics in diagnostic services other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164083", "dep": null}, {"v": "14147", "n": "Diagnostic Services�Independent Study", "d": "Diagnostic Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to diagnostic services. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164084", "dep": null}, {"v": "14148", "n": "Diagnostic Services�Workplace Experience", "d": "Diagnostic Services�Workplace Experience courses provide students with work experience in fields related to diagnostic services. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164085", "dep": null}, {"v": "14149", "n": "Diagnostic Services�Other", "d": "Other Diagnostic Services courses.", "u": null, "notes": "concept: NI001517164086", "dep": null}, {"v": "14151", "n": "Medical/Clerical Assisting", "d": "Medical/Clerical Assisting courses enable students to develop knowledge and skills that combine the medical and clerical fields. Students typically develop skills such as patient exam preparation, assessment of vital signs, routine lab procedures, medical transcription, financial accounting, patient and insurance company billing, and record-keeping.", "u": null, "notes": "concept: NI001517164087", "dep": null}, {"v": "14152", "n": "Pharmacy Assisting", "d": "Pharmacy Assisting courses emphasize the knowledge and skills necessary to assist a pharmacist or pharmacy technician. Course topics and experiences enable students to understand medical terminology, keep and maintain records, label medications, perform computer patient billing, perform stock inventory, and order supplies. These courses also emphasize pharmaceutical classification, drug interactions, and interpersonal/communication skills.", "u": null, "notes": "concept: NI001517164088", "dep": null}, {"v": "14197", "n": "Health Information�Independent Study", "d": "Health Information�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to health information systems. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164089", "dep": null}, {"v": "14298", "n": "Health Sciences�Workplace Experience", "d": "Health Sciences�Workplace Experience courses provide students with work experience in fields involving the health sciences. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164090", "dep": null}, {"v": "14299", "n": "Health Sciences�Other", "d": "Other Health Sciences courses.", "u": null, "notes": "concept: NI001517164091", "dep": null}, {"v": "14995", "n": "Health Care Sciences�Aide", "d": "Health Care Sciences�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164092", "dep": null}, {"v": "20101", "n": "Energy/Power", "d": "Energy/Power courses focus on one or several aspects of energy and power in transportation and work. Course content may include various sources of energy and their use in society (for example, characteristics, availability, conversion, storage, environmental impact, and socioeconomic aspects of various energy sources); principles involved in various means of energy transfer, such as electricity/electronics, hydraulics, pneumatics, heat transfer, and wind/nuclear/solar energies; and the transmission and control of power through mechanical or electrical devices such as motors and engines.", "u": null, "notes": "concept: NI001517164383", "dep": null}, {"v": "20102", "n": "Power and Mechanics", "d": "Power and Mechanics courses enable students to understand the principles underlying various kinds of mechanics (aircraft, auto, diesel, and marine) and how energy is converted, transmitted, and controlled. Topics typically include maintaining and servicing machines, engines, and devices while emphasizing energy sources, electricity, and power transmission. The courses may also provide information on career opportunities within the field of mechanics and/or transportation.", "u": null, "notes": "concept: NI001517164384", "dep": null}, {"v": "20103", "n": "Introduction to Automobiles", "d": "Primarily intended as a personal automobile mechanics course, but also useful for students exploring future careers in automotive technologies, Introduction to Automobiles courses expose students to the various mechanical systems in automobiles and provide basic experience in maintenance tasks. The course may also cover career opportunities in the automotive and/or transportation fields.", "u": null, "notes": "concept: NI001517164385", "dep": null}, {"v": "20104", "n": "Automotive Mechanics�Comprehensive", "d": "Automotive Mechanics�Comprehensive courses emphasize the diagnosis and repair of automobile engines and support systems such as brakes, cooling, drive trains, electrical/electronics components, emission, fuel, ignition, steering, suspension, and transmissions. Course topics often include the comprehension and use of repair manuals, safety, and employability skills (including shop management and entrepreneurship).", "u": null, "notes": "concept: NI001517164386", "dep": null}, {"v": "20105", "n": "Particular Topics in Automotive Mechanics", "d": "These courses provide instruction in the mechanics of a particular system or condition, such as transmissions, brakes, fuel, exhaust, or electrical systems, rather than providing a general study of diagnosis and repair of automobile mechanics.", "u": null, "notes": "concept: NI001517164387", "dep": null}, {"v": "20106", "n": "Automotive Service", "d": "Automotive Service courses emphasize preventative auto maintenance and automobile troubleshooting. Course content typically includes tune-up, oil change, and lubrication skills; tire replacement, alignment, and balancing; and basic knowledge of brake, cooling, electrical, emission, fuel, ignition, steering, suspension, and transmission systems. These courses may also include public relations, sales techniques, and service station management.", "u": null, "notes": "concept: NI001517164388", "dep": null}, {"v": "20107", "n": "Diesel Mechanics�Comprehensive", "d": "Diesel Mechanics�Comprehensive courses prepare students to maintain and repair diesel engines and related systems. Specific course topics may include principles underlying diesel engines, analyzing electrical circuits and systems, troubleshooting and repairing cooling systems, testing and repairing air conditioning charging systems, reading and interpreting service manuals, and identifying the principles and components of fuel injection systems. Courses may also cover safety, employability skills, and entrepreneurship.", "u": null, "notes": "concept: NI001517164389", "dep": null}, {"v": "20108", "n": "Particular Topics in Diesel Mechanics", "d": "These courses cover specific topics relevant to occupations involving the maintenance and repair of vehicles with diesel engines, such as buses and trucks. One topic (or several closely related topics) concerning diesel mechanics is covered in specific detail in this type of course.", "u": null, "notes": "concept: NI001517164390", "dep": null}, {"v": "20109", "n": "Small Vehicle Mechanics", "d": "Small Vehicle Mechanics courses equip students with the knowledge and skill to repair and maintain engines in small vehicles (e.g., motorcycles, all-terrain vehicles, snowmobiles, and mopeds). Topics include (but are not limited to) maintaining frames and suspension, wheels and brakes, and drive trains; servicing fuel, exhaust, and electrical systems; performing tune-ups; and maintaining and repairing engines. Students may also learn safety on the job, employability skills, and entrepreneurship.", "u": null, "notes": "concept: NI001517164391", "dep": null}, {"v": "20110", "n": "Small Engine Mechanics", "d": "Small Engine Mechanics courses provide students with the opportunity to learn how to service and recondition small engines, typically emphasizing two- and four-cycle engines. These courses provide students with opportunities to troubleshoot and repair speed controls, lubrication, ignition, fuel, power transfer, cooling, exhaust, and starting systems; use hand, power, and overhaul tools; and read and interpret service manuals and parts' catalogs. Applications may include lawn mowers, tractors, tillers, power tools, and so on.", "u": null, "notes": "concept: NI001517164392", "dep": null}, {"v": "20111", "n": "Marine Mechanics", "d": "The content of Marine Mechanics courses includes the service and repair of electrical, mechanical, power transfer, hydraulic, fuel, and cooling systems as applied to boat and/or ship engines; boat rigging; trailers; and marine-related merchandise. Courses may also cover communication, human relations, and employability skills, as well as safe, efficient work practices.", "u": null, "notes": "concept: NI001517164393", "dep": null}, {"v": "20112", "n": "Heavy Equipment Mechanics", "d": "Heavy Equipment Mechanics courses include the service and repair of electrical, mechanical, power transfer, hydraulic, fuel, and cooling systems of heavy equipment such as that used in mining, construction, and utility industries.", "u": null, "notes": "concept: NI001517164394", "dep": null}, {"v": "20113", "n": "Aircraft Power Plant", "d": "Aircraft Power Plant courses provide students with the information necessary to troubleshoot, test, repair, and install aircraft engines. Course content usually includes engine ignition, electrical, lubrication, cooling, exhaust, and fuel systems, along with aircraft instrumentation and safety features.", "u": null, "notes": "concept: NI001517164395", "dep": null}, {"v": "20114", "n": "Aircraft Airframe", "d": "Aircraft Airframe courses offer students information and instruction related to the structure and mechanics of aircraft, typically including hydraulic, pneumatic, instrumental, fuel, electrical, cabin atmosphere, and landing gear systems. Aircraft Airframe courses may also cover aircraft metals and coverings and related welding skills.", "u": null, "notes": "concept: NI001517164396", "dep": null}, {"v": "20115", "n": "Automotive Detailing and Reconditioning", "d": "Automotive Detailing and Reconditioning courses provide students with knowledge and skills related to repairing, refinishing, and detailing automobiles. Course topics typically include painting and refinishing, plastics and adhesives, damage analysis, and repair, in addition to occupational safety, employability, and entrepreneurship skills.", "u": null, "notes": "concept: NI001517164397", "dep": null}, {"v": "20119", "n": "Hybrid Engines", "d": "Hybrid Engines courses introduce students to the fundamentals of hybrid electric vehicles. These courses explore the hybrid power plant and may include such topics as hybrid batteries, high- and low-voltage systems, inverters, safety procedures, hybrid maintenance and diagnostics, and alternative fuels.", "u": null, "notes": "concept: NI001517164398", "dep": null}, {"v": "20120", "n": "Motorsports Technology", "d": "Motorsports Technology courses provide students with an understanding of the principles of race car fabrication and all facets of the racing industry. Technical aspects of the courses may include skill development in vehicle assembly of high-performance engines and components using specialty tools, welding, and auto body procedures. Course content may also explore the motorsports technology industry, address safety issues, and identify careers in the field.", "u": null, "notes": "concept: NI001517164399", "dep": null}, {"v": "20147", "n": "Mechanics and Repair�Independent Study", "d": "Mechanics and Repair�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to the maintenance of vehicles and engines. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164400", "dep": null}, {"v": "20148", "n": "Mechanics and Repair�Workplace Experience", "d": "Mechanics and Repair�Workplace Experience courses provide students with work experience in fields related to the maintenance of vehicles and engines. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164401", "dep": null}, {"v": "20149", "n": "Mechanics and Repair�Other", "d": "Other Mechanics and Repair courses.", "u": null, "notes": "concept: NI001517164402", "dep": null}, {"v": "20151", "n": "Distribution�Comprehensive", "d": "Distribution�Comprehensive courses provide students with knowledge and skills related to the safe and efficient delivery of commodities to various markets. Course content typically includes the comparative advantages of various forms of transportation, distribution networks, processes for tracking large shipments of material, transportation of goods in a safe and secure manner, and packaging.", "u": null, "notes": "concept: NI001517164403", "dep": null}, {"v": "20152", "n": "Warehouse Operations", "d": "Warehouse Operations courses convey the principles and processes underlying the receiving, loading and unloading, tracking, and storing of large quantities of materials. Course topics typically include a variety of logistical implications for moving materials by several different modes of transportation, safety and security, and appropriate storage techniques.", "u": null, "notes": "concept: NI001517164404", "dep": null}, {"v": "20197", "n": "Distribution and Logistics�Independent Study", "d": "Distribution and Logistics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to distribution and logistics. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164405", "dep": null}, {"v": "20198", "n": "Distribution and Logistics�Workplace Experience", "d": "Distribution and Logistics�Workplace Experience courses provide students with work experience in fields related to distribution and logistics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164406", "dep": null}, {"v": "20199", "n": "Distribution and Logistics�Other", "d": "Other Distribution and Logistics courses.", "u": null, "notes": "concept: NI001517164407", "dep": null}, {"v": "20995", "n": "Transportation, Distribution and Logistics�Aide", "d": "Transportation, Distribution, and Logistics�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164408", "dep": null}, {"v": "21017", "n": "PLTW Introduction to Engineering Design", "d": "Following Project Lead the Way's suggested curriculum, PLTW Introduction to Engineering Design courses provide an opportunity for students to become involved in hands-on projects that require mathematics, science, and engineering applications. In these courses, students review problems, document work in an engineering notebook, and design solutions using 3D modeling software.", "u": null, "notes": "concept: NI001517164414", "dep": null}, {"v": "21012", "n": "Civil Engineering and Architecture", "d": "Civil Engineering and Architecture courses provide students with an overview of the fields of Civil Engineering and Architecture while emphasizing the interrelationship of both fields. Students typically use software to address real world problems and to communicate the solutions that they develop. Course topics typically include the roles of civil engineers and architects, project-planning, site-planning, building design, project documentation, and presentation.", "u": null, "notes": "concept: NI001517164409", "dep": null}, {"v": "21013", "n": "Aerospace Engineering", "d": "Aerospace Engineering courses introduce students to the world of aeronautics, flight, and engineering. Topics covered in the course may include the history of flight, aerodynamics and aerodynamics testing, flight systems, astronautics, space life systems, aerospace materials, and systems engineering.", "u": null, "notes": "concept: NI001517164410", "dep": null}, {"v": "21014", "n": "Biotechnical Engineering", "d": "Biotechnical Engineering courses enable students to develop and expand their knowledge and skills in biology, physics, technology, and mathematics. Course content may vary widely, drawing upon diverse fields such as biomedical engineering, biomolecular genetics, bioprocess engineering, agricultural biology, or environmental engineering. Students may engage in problems related to biomechanics, cardiovascular engineering, genetic engineering, agricultural biotechnology, tissue engineering, biomedical devices, human interfaces, bioprocesses, forensics, and bioethics.", "u": null, "notes": "concept: NI001517164411", "dep": null}, {"v": "21015", "n": "Particular Topics in Engineering", "d": "These courses examine specific topics in engineering other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164412", "dep": null}, {"v": "21016", "n": "Engineering Analysis", "d": "Engineering Analysis courses help students apply engineering design processes to areas of the designed world, explore ethics in a technological world, and examine systems in civil, mechanical, electrical, and chemical engineering. These courses may provide STEM-based projects to teach students to communicate information through team-based presentations, proposals, and technical reports.", "u": null, "notes": "concept: NI001517164413", "dep": null}, {"v": "21008", "n": "Digital Electronics", "d": "Digital Electronics courses teach students how to use applied logic in the development of electronic circuits and devices. Students may use computer simulation software to design and test digital circuitry prior to the actual construction of circuits and devices.", "u": null, "notes": "concept: NI001517164415", "dep": null}, {"v": "21009", "n": "Robotics", "d": "Robotics courses help students develop and expand their skills and knowledge of robotics and related scientific and engineering topics. Course topics may include principles of mechanics, electronics, hydraulics, pneumatics, programmable logic controllers. These courses may emphasize the use of engineering principles to design and build robots, construct and connect sensors, and program robots in the programming language.", "u": null, "notes": "concept: NI001517164416", "dep": null}, {"v": "21010", "n": "Computer Integrated Manufacturing", "d": "Computer Integrated Manufacturing courses involve the study of robotics and automation. Building on computer solid modeling skills, students may use computer numerical control (CNC) equipment to produce actual models of their three-dimensional designs. Course topics may also include fundamental concepts of robotics, automated manufacturing, and design analysis.", "u": null, "notes": "concept: NI001517164417", "dep": null}, {"v": "21011", "n": "Civil Engineering", "d": "Civil Engineering courses expose students to the concepts and skills used by urban planners, developers, and builders. Students may be trained in soil sampling and analysis, topography and surveying, and drafting or blueprint-reading. Additional course topics may include traffic analysis, geologic principles, and urban design.", "u": null, "notes": "concept: NI001517164418", "dep": null}, {"v": "21024", "n": "PLTW Environmental Sustainability", "d": "Following Project Lead the Way's suggested curriculum and using hands-on activities and simulations, PLTW Environmental Sustainability courses help students investigate and design solutions in response to real-world challenges related to supply and access to drinking water, food supply issues, and renewable energy.", "u": null, "notes": "concept: NI001517164419", "dep": null}, {"v": "21057", "n": "Laser/Fiber Optics", "d": "Laser/Fiber Optics courses cover the history, safety, and theory of laser light and laser systems. In these courses, various laser system configurations and operations are examined.", "u": null, "notes": "concept: NI001517164420", "dep": null}, {"v": "21058", "n": "Geospatial Technology", "d": "Geospatial Technology courses provide students with experiences pertaining to the study of geographic information systems (GIS), global positioning systems (GPS), remote sensing (RS), digital image processing simulator (DIPS), Geodesy, automated cartography (Auto-Carto), land surveying (LS), and navigation. These courses may use spatial analysis models and guidelines for integrating, interpreting, analyzing, and synthesizing geographic data, with a focus on both the implications and limitations of such technologies. Other topics may include interfacing with telecommunications and automated database management systems.", "u": null, "notes": "concept: NI001517164421", "dep": null}, {"v": "21059", "n": "Modeling and Simulation Technology", "d": "Modeling and Simulation Technology courses allow students to explore the use of modeling, simulation, and game development software to solve real-world problems in science, technology, engineering, and mathematics (STEM). These courses typically address the systems, processes, tools, and implications of the field of modeling and simulation technology. Courses topics may also include evaluating and testing engineering designs, modeling geospatial data, observing and analyzing physics simulations, programming games for educational purposes, and creating visualization systems with 3D models.", "u": null, "notes": "concept: NI001517164422", "dep": null}, {"v": "21060", "n": "Wind Energy", "d": "Wind Energy courses introduce students to the terminology and other aspects of the wind industry. Course topics may include, but are not limited to, the history and development of the wind industry, types and applications of various wind turbines, environmental and economic issues of the wind industry, and the future of the industry.", "u": null, "notes": "concept: NI001517164423", "dep": null}, {"v": "21061", "n": "Wind Turbine Construction and Operation", "d": "Wind Turbine Construction and Operation courses provide students with an understanding of wind turbine operation and the wind energy industry. These course enable students to study site preparation and construction, turbine component specifications and manufacturing, operation and maintenance programs, and data acquisition and assessment.", "u": null, "notes": "concept: NI001517164424", "dep": null}, {"v": "21062", "n": "IB Design, Middle Years Program", "d": "International Baccalaureate (IB) Design, Middle Years Program courses are essentially concerned with solving problems, and they encourage students to investigate, design, plan, create, and evaluate. Content is balanced among systems, information, and materials, but the particular technology subjects may vary. These courses were formerly known as IB Technology, Middle Years Program.", "u": null, "notes": "concept: NI001517164425", "dep": null}, {"v": "23010", "n": "Grade 7", "d": "Grade 7 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 7.", "u": null, "notes": "concept: NI001517162801", "dep": null}, {"v": "23011", "n": "Grade 8", "d": "Grade 8 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 8.", "u": null, "notes": "concept: NI001517162802", "dep": null}, {"v": "23012", "n": "Prior-to-Secondary Education", "d": "Prior-to-secondary Education--General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards.", "u": null, "notes": "concept: NI001517162803", "dep": null}, {"v": "23041", "n": "IB Primary Years Program", "d": "International Baccalaureate (IB) Primary Years Program courses incorporate six transdisciplinary themes defined by the International Baccalaureate Organization as the framework for exploration and study at the primary level. Those themes are who we are, where we are in place and time, how we express ourselves, how the world works, how we organize ourselves, and sharing the planet. The course addresses multiple subject areas through the framework of these themes, including language; social studies; mathematics; arts; science; and personal, social, and physical education.", "u": null, "notes": "concept: NI001517162804", "dep": null}, {"v": "23009", "n": "Grade 6", "d": "Grade 6 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 6.", "u": null, "notes": "concept: NI001517162805", "dep": null}, {"v": "23008", "n": "Grade 5", "d": "Grade 5 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 5.", "u": null, "notes": "concept: NI001517162806", "dep": null}, {"v": "23007", "n": "Grade 4", "d": "Grade 4 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 4.", "u": null, "notes": "concept: NI001517162807", "dep": null}, {"v": "23006", "n": "Grade 3", "d": "Grade 3 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 3.", "u": null, "notes": "concept: NI001517162808", "dep": null}, {"v": "23005", "n": "Grade 2", "d": "Grade 2 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 2.", "u": null, "notes": "concept: NI001517162809", "dep": null}, {"v": "23004", "n": "Grade 1", "d": "Grade 1 courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for Grade 1.", "u": null, "notes": "concept: NI001517162810", "dep": null}, {"v": "23003", "n": "Kindergarten", "d": "Kindergarten courses involve content that is not differentiated by subject area. These courses focus on content that is grade-specific and cover various subjects throughout the day, rather than a single subject-specific content area. Specific course content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517162811", "dep": null}, {"v": "22251", "n": "Community Living", "d": "Community Living courses place a special emphasis on the student's relationship to the surrounding community. Instruction varies with the students and their needs; however, these courses provide the skills neceassry for independent functioning within the surrounding environment. Course topics may also include available community resources and how to access them, emergency skills, and independent living strategies.", "u": null, "notes": "concept: NI001517162812", "dep": null}, {"v": "22250", "n": "Exploratory", "d": "Exploratory courses provide a brief introduction to a variety of topics, typically elective subject areas, often in the form of discrete units or modules. Students may choose to take courses later that allow them to pursue the topics introduced in more depth. Topics may vary widely and span multiple subject areas within one course.", "u": null, "notes": "concept: NI001517162813", "dep": null}, {"v": "22153", "n": "Diversified Occupations", "d": "Diversified Occupations courses help students enter the workforce through career exploration, job search and application, and the development of positive work attitudes and work-related skills. These courses typically cover such topics as career planning and selection, money management, communication skills, interpersonal business relationships and behaviors, and personal responsibility. Employment may be a required component of these courses, or students may be required to enroll concurrently in a work experience course.", "u": null, "notes": "concept: NI001517162814", "dep": null}, {"v": "22152", "n": "Employability Skills", "d": "Employability Skills courses help students match their interests and aptitudes to career options with a focus on using employment information effectively, acquiring and improving job-seeking and interview skills, composing job applications and resumes, and learning the skills needed to remain in and advance within the workplace. Course content may also include consumer education and personal money management topics.", "u": null, "notes": "concept: NI001517162815", "dep": null}, {"v": "22151", "n": "Career Exploration", "d": "Career Exploration courses help students identify and evaluate personal goals, priorities, aptitudes, and interests with the goal of helping them make informed decisions about their careers. These courses expose students to various sources of information on career and training options and may also assist them in developing job search and employability skills.", "u": null, "notes": "concept: NI001517162816", "dep": null}, {"v": "22115", "n": "Academic Competition", "d": "Academic Competition courses prepare students to compete individually or in teams in organized contests that test their academic knowledge and skills. Specific content depends upon the competition (examples include Academic Decathlon or Pentathlon, Model UN, subject-specific Olympiads, and Odyssey of the Mind); however, these courses typically foster research, public speaking, critical thinking, and teamwork skills. (Courses that focus on Forensics/Debate competitions should be coded with one of the Forensic Speech course codes.)", "u": null, "notes": "concept: NI001517162817", "dep": null}, {"v": "22113", "n": "IB Personal and Professional Skills", "d": "IB Personal and Professional Skills (PPS) courses are a required component of the International Baccalaureate's Career-related program. Intended to develop attitudes, skills, and strategies applicable to both personal and professional situations, these courses emphasize personal growth and development, interpersonal skills, intercultural understanding, and the use of ethics. IB Personal and Professional Skills courses are linked to students' career-related studies and may include work-based experiences.", "u": null, "notes": "concept: NI001517162818", "dep": null}, {"v": "24039", "n": "World Language�General", "d": "World Language�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., World Language, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517162819", "dep": null}, {"v": "24063", "n": "IB Language B�Spanish", "d": "IB Language B�Spanish courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162820", "dep": null}, {"v": "24064", "n": "AP Spanish Language and Culture", "d": "Designed by the College Board to parallel third-year college-level courses in Spanish language, AP Spanish Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in Spanish, both orally and in writing. These courses also help students understand and interpret written and spoken Spanish. In addition, students explore the culture of Spanish-speaking people in historical and contemporary contexts.", "u": null, "notes": "concept: NI001517162821", "dep": null}, {"v": "24040", "n": "Exploration of Multiple World Languages", "d": "Designed to introduce students to two or more languages in a single course of study, Exploration of Multiple World Languages courses provide students with general information about the spoken and written languages and introduce the relationships among the products, practices, and perspectives of the associated cultures.", "u": null, "notes": "concept: NI001517162822", "dep": null}, {"v": "24050", "n": "Spanish for Young Learners (prior-to-secondary)", "d": "Spanish for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Spanish and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Spanish-speaking cultures.", "u": null, "notes": "concept: NI001517162823", "dep": null}, {"v": "24051", "n": "Spanish Immersion (prior-to-secondary)", "d": "Spanish Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Spanish and grade-specific content using Spanish as the language of instruction. Spanish Immersion courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Spanish-speaking cultures.", "u": null, "notes": "concept: NI001517162824", "dep": null}, {"v": "24052", "n": "Spanish I", "d": "Designed to introduce students to Spanish language and culture, Spanish I courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Spanish-speaking cultures.", "u": null, "notes": "concept: NI001517162825", "dep": null}, {"v": "24053", "n": "Spanish II", "d": "Spanish II courses build upon skills developed in Spanish I, preparing students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Spanish II courses introduce the relationships among the products, practices, and perspectives of Spanish-speaking cultures.", "u": null, "notes": "concept: NI001517162826", "dep": null}, {"v": "24054", "n": "Spanish III", "d": "Spanish III courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Spanish-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162827", "dep": null}, {"v": "24055", "n": "Spanish IV", "d": "Spanish IV courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Spanish IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Spanish-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162828", "dep": null}, {"v": "24056", "n": "Spanish V", "d": "Spanish V courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Spanish V courses promote students' understanding of the relationships among the products, practices, and perspectives of Spanish-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162829", "dep": null}, {"v": "24057", "n": "Spanish for Native Speakers", "d": "Spanish for Native Speakers courses prepare native and heritage speakers to communicate in Spanish in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Spanish for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Spanish-speaking world.", "u": null, "notes": "concept: NI001517162830", "dep": null}, {"v": "24058", "n": "Spanish Field Experience", "d": "Spanish Field Experience courses place students in environments in which they interact with native Spanish speakers, typically in settings where Spanish is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162831", "dep": null}, {"v": "24059", "n": "Spanish Conversation and Culture", "d": "Spanish Conversation and Culture courses provide students with an introduction to the Spanish language and the culture(s) of Spanish-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162832", "dep": null}, {"v": "24060", "n": "Spanish Literature", "d": "Spanish Literature courses prepare students to communicate authentically in Spanish by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Spanish. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Hispanic cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162833", "dep": null}, {"v": "24061", "n": "Particular Topics in Spanish", "d": "Particular Topics in Spanish courses examine particular topics focused on Spanish language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162834", "dep": null}, {"v": "24062", "n": "IB Language A: Literature�Spanish", "d": "IB Language A: Literature�Spanish courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Spanish in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162835", "dep": null}, {"v": "24801", "n": "Swahili Immersion (prior-to-secondary)", "d": "Swahili Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Swahili and grade-specific content using Swahili as the language of instruction. Swahili Immersion courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Swahili-speaking cultures.", "u": null, "notes": "concept: NI001517163105", "dep": null}, {"v": "24802", "n": "Swahili I", "d": "Designed to introduce students to Swahili language and culture, Swahili I courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Swahili-speaking cultures.", "u": null, "notes": "concept: NI001517163106", "dep": null}, {"v": "24803", "n": "Swahili II", "d": "Swahili II courses build upon skills developed in Swahili I, preparing students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Swahili II courses introduce the relationships among the products, practices, and perspectives of Swahili-speaking cultures.", "u": null, "notes": "concept: NI001517163107", "dep": null}, {"v": "24804", "n": "Swahili III", "d": "Swahili III courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Swahili-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163108", "dep": null}, {"v": "24805", "n": "Swahili IV", "d": "Swahili IV courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Swahili IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Swahili-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163109", "dep": null}, {"v": "24806", "n": "Swahili V", "d": "Swahili V courses prepare students to communicate authentically in Swahili by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Swahili V courses promote students' understanding of the relationships among the products, practices, and perspectives of Swahili-speaking countries and cultures.", "u": null, "notes": "concept: NI001517163110", "dep": null}, {"v": "24807", "n": "Swahili for Native Speakers", "d": "Swahili for Native Speakers courses prepare native and heritage speakers to communicate in Swahili in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Swahili for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Swahili-speaking world.", "u": null, "notes": "concept: NI001517163111", "dep": null}, {"v": "24808", "n": "Swahili Field Experience", "d": "Swahili Field Experience courses place students in environments in which they interact with native Swahili speakers, typically in settings where Swahili is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163112", "dep": null}, {"v": "24809", "n": "Swahili Conversation and Culture", "d": "Swahili Conversation and Culture courses provide students with an introduction to the Swahili language and the culture(s) of Swahili-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163113", "dep": null}, {"v": "24811", "n": "Particular Topics in Swahili", "d": "Particular Topics in Swahili courses examine particular topics focused on Swahili language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163114", "dep": null}, {"v": "24812", "n": "IB Language A: Literature�Swahili", "d": "IB Language A: Literature�Swahili courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Swahili in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163115", "dep": null}, {"v": "24816", "n": "IB Language B (Swahili), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Swahili), Middle Years Program courses allow students to gain competence in modern Swahili and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163116", "dep": null}, {"v": "24818", "n": "IB Language Ab Initio�Swahili", "d": "IB Language Ab Initio�Swahili courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517163117", "dep": null}, {"v": "24849", "n": "Swahili�Other", "d": "Other Swahili courses", "u": null, "notes": "concept: NI001517163118", "dep": null}, {"v": "24911", "n": "Particular Topics in American Indian Language", "d": "Particular Topics in American Indian Language courses examine particular topics focused on an American Indian language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described.", "u": null, "notes": "concept: NI001517163131", "dep": null}, {"v": "24850", "n": "American Sign Language (prior-to-secondary)", "d": "American Sign Language for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in American Sign Language and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information on concrete topics. These courses introduce the relationship among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163119", "dep": null}, {"v": "24851", "n": "American Sign Language Immersion (prior-to-secondary)", "d": "American Sign Language Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in American Sign Language and grade-specific content using American Sign Language as the language of instruction. American Sign Language Immersion courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information about standards-based academic content and incorporate the relationships among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163120", "dep": null}, {"v": "24852", "n": "American Sign Language I", "d": "Designed to introduce students to American Sign Language language and culture, American Sign Language I courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information on a variety of topics. They introduce the relationship among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163121", "dep": null}, {"v": "24853", "n": "American Sign Language II", "d": "American Sign Language II courses build upon skills developed in American Sign Language I, preparing students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information on concrete topics. American Sign Language II courses introduce the relationship among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163122", "dep": null}, {"v": "24901", "n": "American Indian Language Immersion (prior-to-secondary)", "d": "American Indian Language Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in an American Indian Language (e.g., Navajo, Cherokee, or Cree) and grade-specific content using that American Indian Language as the language of instruction. American Indian Language Immersion courses prepare students to communicate authentically in an American Indian Language by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163123", "dep": null}, {"v": "24902", "n": "American Indian Language I", "d": "Designed to introduce students to American Indian Language language and culture, American Indian Language I courses prepare students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163124", "dep": null}, {"v": "24903", "n": "American Indian Language II", "d": "American Indian Language II courses build upon skills developed in American Indian Language I, preparing students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. American Indian Language II courses introduce the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163125", "dep": null}, {"v": "24904", "n": "American Indian Language III", "d": "American Indian Language III courses prepare students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics. These courses expand students' knowledge of relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163126", "dep": null}, {"v": "24905", "n": "American Indian Language IV", "d": "American Indian Language IV courses prepare students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. American Indian Language IV courses promote students' understanding of the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163127", "dep": null}, {"v": "24906", "n": "American Indian Language V", "d": "American Indian Language V courses prepare students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. American Indian Language V courses promote students' understanding of the relationships among the products, practices, and perspectives of of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163128", "dep": null}, {"v": "24909", "n": "American Indian Language Conversation and Culture", "d": "American Indian Language Conversation and Culture courses provide students with an introduction to an American Indian Language (e.g., Navajo, Cherokee, or Cree) and the culture(s) of the people associated with the language of study, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163129", "dep": null}, {"v": "24910", "n": "American Indian Literature", "d": "American Indian Language Literature courses prepare students to communicate authentically in an American Indian Language (e.g., Navajo, Cherokee, or Cree) by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in the American Indian Language of study. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of American Indian cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163130", "dep": null}, {"v": "24916", "n": "IB Language B (American Indian Language), Middle Years Program", "d": "International Baccalaureate (IB) Language B (American Indian Language), Middle Years Program courses allow students to gain competence in a modern American Indian Language and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163132", "dep": null}, {"v": "24949", "n": "American Indian Language�Other", "d": "Other American Indian language courses.", "u": null, "notes": "concept: NI001517163133", "dep": null}, {"v": "24950", "n": "World Language (Other Language) for Young Learners (prior-to-secondary)", "d": "World Language (Other Language) for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in a language not specified elsewhere in this classification system and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in the language of study by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of culture(s) associated with the language of study.", "u": null, "notes": "concept: NI001517163134", "dep": null}, {"v": "24951", "n": "World Language (Other Language) Immersion (prior-to-secondary)", "d": "World Language (Other Language) Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in a language not specified elsewhere in this classification system and grade-specific content using that langugage as the language of instruction. World Language (Other Language) Immersion courses prepare students to communicate authentically in the language of study by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163135", "dep": null}, {"v": "24961", "n": "Particular Topics in World Language (Other Language)", "d": "Particular Topics in World Language (Other Language) courses examine particular topics focused on a language (or associated culture) not specified elsewhere in this classification system, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163144", "dep": null}, {"v": "24952", "n": "World Language (Other Language) I", "d": "Designed to introduce students to a language and culture not specified elsewhere in this classification system, World Language (Other Language) I courses prepare students to communicate authentically in the language of study by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163136", "dep": null}, {"v": "24953", "n": "World Language (Other Language) II", "d": "World Language (Other Language) II courses build upon skills developed in World Language I (Other Language), preparing students to communicate authentically in a language not specified elsewhere in this classification system by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. World Language II (Other Language) courses introduce the relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163137", "dep": null}, {"v": "24954", "n": "World Language (Other Language) III", "d": "World Language (Other Language) III courses prepare students to communicate authentically in a language not specified elsewhere in this classification system by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163138", "dep": null}, {"v": "24955", "n": "World Language (Other Language) IV", "d": "World Language (Other Language) IV courses prepare students to communicate authentically in a language not specified elsewhere in this classification system by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. World Language (Other Language) IV courses promote students' understanding of the relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163139", "dep": null}, {"v": "04002", "n": "Particular Topics in Geography", "d": "Particular Topics in Geography courses examine a particular topic in geography, such as physical or cultural geography, or the geography of a particular area or region, rather than provide an overview of the field.", "u": null, "notes": "concept: NI001517163439", "dep": null}, {"v": "04003", "n": "IB Geography", "d": "IB Geography courses prepare students to take the International Baccalaureate Geography exams. These courses integrate both physical and human geography and explore scientific and socio-economic methodologies and fieldwork. In general, IB Geography courses aim to help students understand the relationships within society, the relationships between society and the natural environment, and how those relationships change over time.", "u": null, "notes": "concept: NI001517163440", "dep": null}, {"v": "04004", "n": "AP Human Geography", "d": "Following the College Board's suggested curriculum designed to parallel college-level Human Geography courses, AP Human Geography introduces students to the systematic study of patterns and processes that have shaped the ways in which humans understand, use, and alter the earth's surface. Students use spatial concepts and landscape analysis to examine human social organization and its environmental consequences and also learn about the methods and tools geographers use in their science and practice.", "u": null, "notes": "concept: NI001517163441", "dep": null}, {"v": "04005", "n": "U.S. Geography", "d": "U.S. Geography courses provide an overview of the geography of the United States. Topics typically include the physical environment, the political landscape, the relationship between people and the land, and economic production and development.", "u": null, "notes": "concept: NI001517163442", "dep": null}, {"v": "04047", "n": "Geography�Independent Study", "d": "Geography�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within geography. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163443", "dep": null}, {"v": "04048", "n": "Geography�Workplace Experience", "d": "Geography�Workplace Experience courses provide work experience in a field related to geography. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163444", "dep": null}, {"v": "04049", "n": "Geography�Other", "d": "Other Geography courses.", "u": null, "notes": "concept: NI001517163445", "dep": null}, {"v": "04051", "n": "World History�Overview", "d": "World History�Overview courses provide students with an overview of the history of human society from early civilization to the contemporary period, examining political, economic, social, religious, military, scientific, and cultural developments. World History�Overview courses may include geographical studies, but often these components are not as explicitly taught as geography.", "u": null, "notes": "concept: NI001517163446", "dep": null}, {"v": "04059", "n": "Medieval European History", "d": "Medieval European History courses provide a survey of European civilization from the fall of Rome through the late Middle Ages.", "u": null, "notes": "concept: NI001517163447", "dep": null}, {"v": "04106", "n": "Contemporary U.S. Issues", "d": "Contemporary U.S. Issues courses study the political, economic, and social issues facing the United States, with or without an emphasis on state and local issues. These courses may focus on current issues or may examine selected issues that span throughout the 20th century to the present.", "u": null, "notes": "concept: NI001517163448", "dep": null}, {"v": "04107", "n": "U.S. Ethnic Studies", "d": "U.S. Ethnic Studies courses examine the history, politics, economics, society, and/or culture of one or more of the racial/ethnic groups in the United States. These courses may focus primarily on the history of an individual racial/ethnic group or may take a more comprehensive approach to studying the contemporary issues affecting racial/ethnic groups overall.", "u": null, "notes": "concept: NI001517163449", "dep": null}, {"v": "04108", "n": "U.S. Gender Studies", "d": "U.S. Gender Studies courses examine the history, politics, economics, and/or culture of gender in U.S. society. These courses may focus primarily on gender relations or may take a more comprehensive approach to studying the contemporary issues related to gender.", "u": null, "notes": "concept: NI001517163450", "dep": null}, {"v": "04109", "n": "Particular Topics in U.S. History", "d": "These courses examine a particular topic in U.S. History, such as particular time periods in the history of the United States, or they may focus on the history of particular U.S. regions rather than provide an overview of the subject.", "u": null, "notes": "concept: NI001517163451", "dep": null}, {"v": "04110", "n": "U.S. Wars and Military Conflicts", "d": "U.S. Wars and Military Conflicts courses focus on the study of one or more wars and major military conflicts in which the United States had a significant role. These courses concentrate on one of many topics related to war, including the causes; U.S. involvement; and social, political, and economic effects. Specific wars may include the Revolutionary War, American Civil War, World War I, World War II, Korean War, Vietnam War, Gulf War, or other contemporary military conflicts.", "u": null, "notes": "concept: NI001517163452", "dep": null}, {"v": "04147", "n": "U.S. History�Independent Study", "d": "U.S. History�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within U.S. History. Independent Study courses may provide students with an opportunity to expand their expertise in a particular period or area, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163453", "dep": null}, {"v": "04148", "n": "U.S. History�Workplace Experience", "d": "U.S. History�Workplace Experience courses provide work experience in a field related to U.S. history. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163454", "dep": null}, {"v": "04060", "n": "Ancient and Medieval History", "d": "Ancient and Medieval History courses combine a study of ancient civilizations and Medieval Europe, beginning with the civilizations of the ancient Middle East and continuing through the late Middle Ages in Europe.", "u": null, "notes": "concept: NI001517163455", "dep": null}, {"v": "04061", "n": "World Area Studies", "d": "World Area Studies courses examine the history, politics, economics, society, and/or culture of one or more regions of the world, such as Africa, Latin America, the former Soviet Union, Far East Asia, and the Middle East. These courses may focus primarily on the history of a particular region or may take an interdisciplinary approach to the contemporary issues affecting the region. Furthermore, these courses may emphasize one particular country (other than the United States), rather than emphasizing a region or continent.", "u": null, "notes": "concept: NI001517163456", "dep": null}, {"v": "04062", "n": "World People Studies", "d": "World People Studies courses allow students to study various types of subgroups that have something in common such as religion, gender, or culture. Similar in style to World Area Studies, but focusing on a group of people rather than on a specific region, these courses examine a subgroup's history, politics, economics, and/or culture.", "u": null, "notes": "concept: NI001517163457", "dep": null}, {"v": "04063", "n": "Western Civilization", "d": "Western Civilization courses apply an interdisciplinary approach to the study of western cultural traditions, frequently using a chronological framework. Course content typically includes a survey of the major developments in and contributors to art and architecture, literature, religion and philosophy, and culture. These courses may also cover intellectual and political movements.", "u": null, "notes": "concept: NI001517163458", "dep": null}, {"v": "04064", "n": "Contemporary World Issues", "d": "Contemporary World Issues courses enable students to study political, economic, and social issues facing the world. These courses may focus on current issues, examine selected issues throughout the 20th century, and look at historical causes or possible solutions.", "u": null, "notes": "concept: NI001517163459", "dep": null}, {"v": "04065", "n": "Particular Topics in World History", "d": "These courses examine particular topics in world history other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163460", "dep": null}, {"v": "04097", "n": "World History�Independent Study", "d": "World History�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within world history. Independent Study courses may provide students with an opportunity to expand their expertise in a particular period or area, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163461", "dep": null}, {"v": "04098", "n": "World History�Workplace Experience", "d": "World History�Workplace Experience courses provide work experience in a field related to world history. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163462", "dep": null}, {"v": "04099", "n": "World History�Other", "d": "Other World History courses.", "u": null, "notes": "concept: NI001517163463", "dep": null}, {"v": "04101", "n": "U.S. History�Comprehensive", "d": "U.S. History�Comprehensive courses provide students with an overview of the history of the United States, examining time periods from discovery or colonialism through World War II or after. These courses typically include a historical overview of political, military, scientific, and social developments. Course content may include a history of the North American peoples before European settlement.", "u": null, "notes": "concept: NI001517163464", "dep": null}, {"v": "04102", "n": "Early U.S. History", "d": "Early U.S. History courses examine the history of the United States from the colonial period to the Civil War or Reconstruction era (some courses end after this period). Some courses include North American history before European settlement, while others may begin at the formation of the new nation. These courses typically include a historical overview of political, military, scientific, and social developments.", "u": null, "notes": "concept: NI001517163465", "dep": null}, {"v": "04103", "n": "Modern U.S. History", "d": "Modern U.S. History courses examine the history of the United States from the Civil War or Reconstruction era (some courses begin at a later period) through the present time. These courses typically include a historical review of political, military, scientific, and social developments.", "u": null, "notes": "concept: NI001517163466", "dep": null}, {"v": "04104", "n": "AP U.S. History", "d": "Following the College Board's suggested curriculum designed to parallel college-level U.S. History courses, AP U.S. History courses provide students with the analytical skills and factual knowledge necessary to address critically problems and materials in U.S. history. Students learn to assess historical materials and to weigh the evidence and interpretations presented in historical scholarship. The course examines the discovery and settlement of the New World through the recent past.", "u": null, "notes": "concept: NI001517163467", "dep": null}, {"v": "04105", "n": "State-Specific Studies", "d": "State-Specific Studies courses examine the history, politics, economics, society, and/or cultures of one state in the United States. This course may focus primarily on the history of that state or may take an interdisciplinary approach to the contemporary issues affecting it.", "u": null, "notes": "concept: NI001517163468", "dep": null}, {"v": "04149", "n": "U.S. History�Other", "d": "Other U.S. History courses.", "u": null, "notes": "concept: NI001517163469", "dep": null}, {"v": "04165", "n": "Legal System", "d": "Legal System courses examine the workings of the U.S. criminal and civil justice systems, including providing an understanding of civil and criminal law and the legal process, the structure and procedures of courts, and the role of various legal or judicial agencies. Although these courses emphasize the legal process, they may also cover the history and foundation of U.S. law (the Constitution, statutes, and precedents). Course content may also include contemporary problems in the criminal justice system.", "u": null, "notes": "concept: NI001517163470", "dep": null}, {"v": "04166", "n": "Particular Topics in Law", "d": "These courses examine a particular topic in law such as the Constitution, specific statutes, or the legal process rather than provide an overview.", "u": null, "notes": "concept: NI001517163471", "dep": null}, {"v": "04167", "n": "Simulated Political Process", "d": "Simulated Political Process courses provide students with the opportunity to confront and resolve national and international issues by mirroring local, national, or international governmental bodies. These courses focus on government and international relations, conflict resolution, and policies and procedures of government. Course topics may include simulations of jury trials and national or international governmental organizations.", "u": null, "notes": "concept: NI001517163472", "dep": null}, {"v": "04169", "n": "IB Global Politics", "d": "IB Global Politics prepare students to take the International Baccalaureate Global Politics exams through the exploration of political concepts and development of an understanding of local, national, international, and global dimensions of political activity. Topics may include contemporary global political challenges.", "u": null, "notes": "concept: NI001517163473", "dep": null}, {"v": "04171", "n": "IB Individuals and Societies, Middle Years Program", "d": "International Baccalaureate (IB) Individuals and Societies, Middle Years Program courses aim to develop the understanding and application of concepts (time, place and space, change, systems and global awareness) and skills (technical, analytical, problem solving, and investigative). Content may include topics such as geography, history, economics, politics, civics, sociology, anthropology, and psychology. These courses were formerly known as IB Humanities, Middle Years Program.", "u": null, "notes": "concept: NI001517163474", "dep": null}, {"v": "04151", "n": "U.S. Government�Comprehensive", "d": "U.S. Government�Comprehensive courses provide an overview of the structure and functions of the U.S. government and political institutions and examine constitutional principles, the concepts of rights and responsibilities, the role of political parties and interest groups, and the importance of civic participation in the democratic process. These courses may examine the structure and function of state and local governments and may cover certain economic and legal topics.", "u": null, "notes": "concept: NI001517163475", "dep": null}, {"v": "04152", "n": "Particular Topics in U.S. Government", "d": "These courses examine a particular topic pertaining to U.S. government and political institutions rather than provide a general overview of the subject. They may concentrate on one of many topics related to governmental structure, function, and purposes, such as the Constitution, the Supreme Court, Congress, or the Office of the President.", "u": null, "notes": "concept: NI001517163476", "dep": null}, {"v": "04153", "n": "Political Science", "d": "Political Science courses approach the study of politics from a theoretical perspective, including an examination of the role of government and the nature of political behavior, political power, and political action.", "u": null, "notes": "concept: NI001517163477", "dep": null}, {"v": "04154", "n": "Comparative Government", "d": "Comparative Government courses study the basic tenets of government, searching for the differences and similarities among several forms of government. These courses take a comparative approach to the study of government and politics, focusing on how the United States compares with other nations.", "u": null, "notes": "concept: NI001517163478", "dep": null}, {"v": "04155", "n": "International Relations", "d": "International Relations courses provide students with an introduction to the relationships that exist among nations, including an examination of the modern state; the foreign policies of nations; the dynamics of nationalism, ideology, and culture; and the role of international organizations. The courses may also emphasize contemporary events.", "u": null, "notes": "concept: NI001517163479", "dep": null}, {"v": "04156", "n": "United States and World Affairs", "d": "United States and World Affairs courses provide a study of global interrelationships. Topics covered may include geographic, political, economic, and social issues of a particular country or region, with an emphasis on how these issues influence (or are influenced by) the way in which the United States relates to other countries in an interdependent world context.", "u": null, "notes": "concept: NI001517163480", "dep": null}, {"v": "04157", "n": "AP U.S. Government and Politics", "d": "Following the College Board's suggested curriculum designed to parallel college-level U.S. Government and Politics courses, these courses provide students with an analytical perspective on government and politics in the United States, involving both the study of general concepts used to interpret U.S. politics and the analysis of specific case studies and foundational documents. The courses generally cover foundations of American democracy, interaction among branches of government, political beliefs and behaviors, political participation, and civil rights and liberties.", "u": null, "notes": "concept: NI001517163481", "dep": null}, {"v": "04158", "n": "AP Comparative Government and Politics", "d": "Following the College Board's suggested curriculum designed to parallel college-level Comparative Government and Politics courses, these courses offer students an understanding of the world's diverse political structures and practices. The courses encompass the study of both specific countries and general concepts used to interpret the key political relationships found in virtually all national policies. Course content generally includes sovereignty, authority, and power; political institutions; the relationships among citizens, society, and the state; political and economic change; and public policy.", "u": null, "notes": "concept: NI001517163482", "dep": null}, {"v": "04159", "n": "AP Government", "d": "AP Government courses prepare students for the AP exams in both U.S. Government and Politics and Comparative Government and Politics. Course content includes the topics covered in those two separate courses. See SCED Codes 04157 and 04158 for detailed content descriptions.", "u": null, "notes": "concept: NI001517163483", "dep": null}, {"v": "08109", "n": "Physical and Health Education (grade 5)", "d": "Physical and Health Education (grade 5) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163766", "dep": null}, {"v": "08110", "n": "Physical and Health Education (grade 6)", "d": "Physical and Health Education (grade 6) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163767", "dep": null}, {"v": "08111", "n": "Physical and Health Education (grade 7)", "d": "Physical and Health Education (grade 7) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163768", "dep": null}, {"v": "08101", "n": "Physical and Health Education", "d": "Physical and Health Education courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues.", "u": null, "notes": "concept: NI001517163769", "dep": null}, {"v": "08102", "n": "Physical and Health Education (early childhood education)", "d": "Physical and Health Education (early childhood education) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for early childhood education.", "u": null, "notes": "concept: NI001517163770", "dep": null}, {"v": "08103", "n": "Physical and Health Education (pre-kindergarten)", "d": "Physical and Health Education (pre-kindergarten) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163771", "dep": null}, {"v": "08055", "n": "Safety and First Aid", "d": "Safety and First Aid courses provide specialized instruction in first aid techniques, cardiopulmonary resuscitation (CPR), relief of obstructed airways, and general safety procedures and behaviors. These courses may include such topics as an overview of community agencies and hotlines providing emergency care and information and opportunities for first aid and CPR certification.", "u": null, "notes": "concept: NI001517163772", "dep": null}, {"v": "08056", "n": "Health for Parenting Teens", "d": "Designed for pregnant teens and/or parents, topics within Health for Parenting Teens courses cover a wide range of both health and parenting issues, typically including prenatal and postnatal care, health and well-being of young parents, child development, stress management, and parental/adult roles. The courses may also involve academic assistance, career exploration, financial management, and so on.", "u": null, "notes": "concept: NI001517163773", "dep": null}, {"v": "08057", "n": "Health and Life Management", "d": "Health and Life Management courses focus as much on consumer education topics (such as money management and evaluation of consumer information and advertising) as on personal health topics (such as nutrition, stress management, drug/alcohol abuse prevention, disease prevention, and first aid). Course objectives include helping students develop decision-making, communication, interpersonal, and coping skills and strategies.", "u": null, "notes": "concept: NI001517163774", "dep": null}, {"v": "08058", "n": "Substance Abuse Prevention", "d": "Substance Abuse Prevention courses focus specifically on the health risks of drugs, alcohol and tobacco. These courses provide information on the negative consequences of these products and teach students coping strategies to resist the influences (such as peers and media images) that may entice them to use these substances. Students may also explore the community resources available to them.", "u": null, "notes": "concept: NI001517163775", "dep": null}, {"v": "08068", "n": "Health Education (early childhood education)", "d": "Health Education (early childhood education) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for early childhood education.", "u": null, "notes": "concept: NI001517163776", "dep": null}, {"v": "08069", "n": "Health Education (pre-kindergarten)", "d": "Health Education (pre-kindergarten) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163777", "dep": null}, {"v": "08033", "n": "Physical Education (grade 3)", "d": "Physical Education (grade 3) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Locomotor skills, strength, endurance, flexibility, safety, and rules and conventions of games and sports are often the focus; health education topics may also be included. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163783", "dep": null}, {"v": "08070", "n": "Health Education (kindergarten)", "d": "Health Education (kindergarten) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163778", "dep": null}, {"v": "08071", "n": "Health Education (grade 1)", "d": "Health Education (grade 1) courses emphasize the knowledge and skills that promote sound bodies and minds, prevent disease and dysfunction, and reduce risk. Topics typically involve nutrition and healthy eating habits; growth and development; injury prevention and safety; mental, emotional, and social health; alcohol, tobacco, and other drugs; physical activity; community health; and factors that influence health. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163779", "dep": null}, {"v": "08104", "n": "Physical and Health Education (kindergarten)", "d": "Physical and Health Education (kindergarten) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163780", "dep": null}, {"v": "08031", "n": "Physical Education (grade 1)", "d": "Physical Education (grade 1) courses typically emphasize knowledge and skills that lead to health, enjoyment, and social development through physical activity. Course content may include activities that strengthen gross and fine motor skills, body awareness, safety, and the relationship between physical activity and health. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163781", "dep": null}, {"v": "08032", "n": "Physical Education (grade 2)", "d": "Physical Education (grade 2) courses typically emphasize knowledge and skills that lead to health, enjoyment, and social development through physical activity. Course content may include activities that strengthen gross and fine motor skills, body awareness, safety, and the relationship between physical activity and health. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163782", "dep": null}, {"v": "08034", "n": "Physical Education (grade 4)", "d": "Physical Education (grade 4) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Locomotor skills, strength, endurance, flexibility, safety, and rules and conventions of games and sports are often the focus; health education topics may also be included. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163784", "dep": null}, {"v": "08035", "n": "Physical Education (grade 5)", "d": "Physical Education (grade 5) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Locomotor skills, strength, endurance, flexibility, safety, and rules and conventions of games and sports are often the focus; health education topics may also be included. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163785", "dep": null}, {"v": "08036", "n": "Physical Education (grade 6)", "d": "Physical Education (grade 6) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Activities typically include those that increase strength, endurance, and flexibility; reinforce safe technique; teach the rules and conventions of games and sports; and explore the relationship between physical activity and health. Health topics (such as the effects of drugs and alcohol, sexual education, and healthy lifestyles) may also be included. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163786", "dep": null}, {"v": "08037", "n": "Physical Education (grade 7)", "d": "Physical Education (grade 7) courses typically involve the acquisition of knowledge and skills that provide the foundation for sport, a physically active lifestyle, and social development through physical activity. Activities typically include those that increase strength, endurance, and flexibility; reinforce safe technique; teach the rules and conventions of games and sports; and explore the relationship between physical activity and health. Health topics (such as the effects of drugs and alcohol, sexual education, and healthy lifestyles) may also be included. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163787", "dep": null}, {"v": "08105", "n": "Physical and Health Education (grade 1)", "d": "Physical and Health Education (grade 1) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163788", "dep": null}, {"v": "08106", "n": "Physical and Health Education (grade 2)", "d": "Physical and Health Education (grade 2) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163789", "dep": null}, {"v": "08107", "n": "Physical and Health Education (grade 3)", "d": "Physical and Health Education (grade 3) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163790", "dep": null}, {"v": "08097", "n": "Health Education�Independent Study", "d": "Courses in Health Education�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to health and health education. Independent Study courses may provide students with opportunity to expand expertise in a particular application, to explore a topic of special interest in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163791", "dep": null}, {"v": "08098", "n": "Health Education�Workplace Experience", "d": "Health Education�Workplace Experience courses provide work experience in a field related to health education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences encountered in the workplace.", "u": null, "notes": "concept: NI001517163792", "dep": null}, {"v": "08112", "n": "Physical and Health Education (grade 8)", "d": "Physical and Health Education (grade 8) courses provide students with knowledge, experience, and an opportunity to develop skills in a variety of sports or activities (for example, team sports, individual/dual sports, recreational sports, and fitness/conditioning activities) integrated with instruction in personal health (for example, nutrition, mental health and stress management, drug/alcohol abuse prevention, injury and disease prevention, and first aid) and consumer health issues. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163793", "dep": null}, {"v": "08113", "n": "Physical and Health Education�General", "d": "Physical and Health Education�General courses involve physical- and health-related content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Physical and Health Education, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163794", "dep": null}, {"v": "08147", "n": "Physical and Health Education�Independent Study", "d": "Courses in Physical and Health Education�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to Physical and Health Education. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular sport or activity, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163795", "dep": null}, {"v": "08148", "n": "Physical and Health Education�Workplace Experience", "d": "Physical and Health Education�Workplace Experience courses provide work experience in a field related to Physical and Health Education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences encountered in the workplace.", "u": null, "notes": "concept: NI001517163796", "dep": null}, {"v": "08149", "n": "Physical and Health Education�Other", "d": "Other Physical and Health Education courses.", "u": null, "notes": "concept: NI001517163797", "dep": null}, {"v": "08151", "n": "Drivers' Education�Classroom Only", "d": "Drivers' Education�Classroom Only courses provide students with the knowledge to become safe drivers on America's roadways. Topics in these courses include legal obligations and responsibility, rules of the road and traffic procedures, safe driving strategies and practices, and the physical and mental factors affecting the driver's capability (including alcohol and other drugs).", "u": null, "notes": "concept: NI001517163798", "dep": null}, {"v": "08152", "n": "Drivers' Education�Classroom and Laboratory", "d": "Drivers' Education�Classroom and Laboratory courses provide students with the knowledge and experience to become safe drivers on America's roadways. Topics in these courses cover legal obligations and responsibility, rules of the road and traffic procedures, safe driving strategies and practices, and the physical and mental factors affecting the driver's capability (including alcohol and other drugs). Experience in driving a vehicle is an essential component of these courses.", "u": null, "notes": "concept: NI001517163799", "dep": null}, {"v": "08197", "n": "Drivers' Education�Independent Study", "d": "Courses in Drivers' Education�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to drivers' education. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163800", "dep": null}, {"v": "14997", "n": "Health Care Sciences�Independent Study", "d": "Health Care Sciences�Independent Study courses, often conducted with instructors as mentors, enable students to explore health-related topics of interest. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164093", "dep": null}, {"v": "14998", "n": "Health Care Sciences�Workplace Experience", "d": "Health Care Sciences�Workplace Experience courses provide students with work experience in the health care industry. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164094", "dep": null}, {"v": "14198", "n": "Health Information�Workplace Experience", "d": "Health Information�Workplace Experience courses provide students with work experience in fields related to health Information. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164095", "dep": null}, {"v": "14199", "n": "Health Information�Other", "d": "Other Health Information courses.", "u": null, "notes": "concept: NI001517164096", "dep": null}, {"v": "14201", "n": "Central Service Technology", "d": "Central Service Technology courses provide students with knowledge and skills related to the procurement, handling, storage, and distribution of sterile goods and equipment. Course components usually include quality assurance, infection control and isolation techniques, medical terminology and processes, decontamination and sterilization, microbiology, and chemistry.", "u": null, "notes": "concept: NI001517164097", "dep": null}, {"v": "14202", "n": "Health Support Services", "d": "Health Support Services courses provide students with knowledge and skills to be used in activities that support patients' primary health care, such as counseling, health education, disease management, and risk reduction. Because support services can be widely defined, course topics typically also include general health care, such as anatomy and physiology, medical terminology, first aid and CPR procedures, and ethical and legal responsibilities.", "u": null, "notes": "concept: NI001517164098", "dep": null}, {"v": "14203", "n": "Health Unit Coordination", "d": "Health Unit Coordination courses provide students with instruction and experiences so that they can manage components of nonpatient care activities in health care facilities. Topics covered usually include medical terminology, transcription, and general reception duties and responsibilities; recordkeeping; and stocking medical and office supplies and equipment.", "u": null, "notes": "concept: NI001517164099", "dep": null}, {"v": "14204", "n": "Particular Topics in Health Support Services", "d": "These courses examine particular topics in health support services other than those described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164100", "dep": null}, {"v": "14247", "n": "Health Support Services�Independent Study", "d": "Health Support Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to health support services. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164101", "dep": null}, {"v": "14248", "n": "Health Support Services�Workplace Experience", "d": "Health Support Services�Workplace Experience courses provide students with work experience in careers related to health support services. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164102", "dep": null}, {"v": "14249", "n": "Health Support Services�Other", "d": "Other Health Support Services courses.", "u": null, "notes": "concept: NI001517164103", "dep": null}, {"v": "14251", "n": "Health Science", "d": "Health Science courses integrate chemistry, microbiology, chemical reactions, disease processes, growth and development, and genetics with anatomy and physiology of the body systems. Typically, these courses reinforce science, mathematics, communications, health, and social studies principles and relate them to health care.", "u": null, "notes": "concept: NI001517164104", "dep": null}, {"v": "14252", "n": "Biotechnology", "d": "Biotechnology courses involve the study of the bioprocesses of organisms, cells, and/or their components and enable students to use this knowledge to produce or refine products, procedures, and techniques. Course topics typically include laboratory measurement, monitoring, and calculation; growth and reproduction; chemistry and biology of living systems; quantitative problem-solving; data acquisition and display; and ethics. Advanced topics may include elements of biochemistry, genetics, and protein purification techniques.", "u": null, "notes": "concept: NI001517164105", "dep": null}, {"v": "14253", "n": "Pharmacology", "d": "Pharmacology courses involve a study of how living animals can be changed by chemical substances, especially by the actions of drugs and other substances used to treat disease. Basic concepts of physiology, pathology, biochemistry, and bacteriology are typically brought into play as students examine the effects of drugs and their mechanisms of action.", "u": null, "notes": "concept: NI001517164106", "dep": null}, {"v": "14254", "n": "Particular Topics in Health Sciences", "d": "These courses examine particular topics in health sciences other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164107", "dep": null}, {"v": "14255", "n": "Biomedical Innovation", "d": "Biomedical Innovation courses help students apply their knowledge and skills to answer questions or solve problems related to the biomedical sciences. These courses help students design innovative solutions for emerging health challenges and address topics such as clinical medicine, human physiology, medical innovation, water contamination, public health, molecular biology, and forensic autopsy, and public health. These courses may also provide students with the opportunity to work with a mentor or advisor from a university or hospital, physician's office, or industry. Students may design and complete an independent project as part of the course.", "u": null, "notes": "concept: NI001517164108", "dep": null}, {"v": "14297", "n": "Health Sciences�Independent Study", "d": "Health Sciences�Independent Study courses, often conducted with instructors as mentors, enable students to explore health-related topics of interest. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164109", "dep": null}, {"v": "14999", "n": "Health Care Sciences�Other", "d": "Other Health Care Sciences courses.", "u": null, "notes": "concept: NI001517164110", "dep": null}, {"v": "15104", "n": "Public Safety Telecommunications", "d": "Public Safety Telecommunications courses provide students with the skills and knowledge necessary to obtain national certification in Public Safety Telecommunications and/or employment as a 911 telecommunicator. Course content may include, but is not limited to, understanding standard federal, state, and local telecommunication operating procedures; functions, terminology, and types of telecommunication equipment; malfunctions and maintenance agreements; proper and correct telephone and dispatching procedures and techniques; emergency situations and operating procedures; and emergency medical dispatch procedures.", "u": null, "notes": "concept: NI001517164111", "dep": null}, {"v": "15147", "n": "Security and Protection�Independent Study", "d": "Security and Protection�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related the security and protection of the public. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164112", "dep": null}, {"v": "15148", "n": "Security and Protection�Workplace Experience", "d": "Security and Protection�Workplace Experience courses provide work experience in fields related to security and protection. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164113", "dep": null}, {"v": "15149", "n": "Security and Protection�Other", "d": "Other Security and Protection courses.", "u": null, "notes": "concept: NI001517164114", "dep": null}, {"v": "15151", "n": "Fire Science", "d": "Fire Science courses introduce students to the field of fire prevention and control and enable them to extend their knowledge through the use of chemical, physical, and engineering principles to understand factors involved in fires. Course topics typically include the chemistry of combustion, factors that influence fire (such as structural design and meteorology), and safety procedures.", "u": null, "notes": "concept: NI001517164115", "dep": null}, {"v": "15001", "n": "Exploration of Public Service Careers", "d": "Exploration of Public Service Careers courses expose students to the duties, responsibilities, requirements, and career opportunities within public service. Course topics vary and may include, but are not limited to, public safety, police, fire, emergency services, law, forensics, corrections, fire/EMS and homeland security issues. Course activities depend upon the career clusters that students explore.", "u": null, "notes": "concept: NI001517164116", "dep": null}, {"v": "15051", "n": "Criminal Justice", "d": "Criminal Justice courses train students to understand and apply the principles and procedures essential to the overall U.S. criminal justice system. Course topics vary and may include, but are not limited to, structure, history and philosophy of the federal, state, county, and municipal court systems; judicial appointment processes; arrest-to-sentencing sequences; laboratory, forensic, and trial procedure; probation and parole; state and federal correctional facilities; and system interrelationships with law enforcement agencies.", "u": null, "notes": "concept: NI001517164117", "dep": null}, {"v": "15052", "n": "Corrections", "d": "Corrections courses provide instruction regarding the principles and techniques used by institutions that incarcerate, rehabilitate, and monitor people accused or convicted of crimes. As applicable, students may prepare for certification as a corrections officer or deputy. Course topics vary and may include, but are not limited to, infection control in corrections, taking fingerprints, self-defense pressure points, organization of correctional systems, and current and future issues in corrections.", "u": null, "notes": "concept: NI001517164118", "dep": null}, {"v": "15053", "n": "Particular Topics in Law Enforcement", "d": "These courses examine specific topics related to law enforcement (such as juvenile justice), rather than provide a general study of the field.", "u": null, "notes": "concept: NI001517164119", "dep": null}, {"v": "15054", "n": "Law Enforcement", "d": "Law Enforcement courses provide an overview of the history, organization, and functions of local, state, and federal law enforcement and foundational skills necessary to fulfill law enforcement duties. Course topics vary and may include, but are not limited to, the role of constitutional law, the United States legal system, criminal law, law enforcement terminology, physical fitness, self-defense, and skill necessary to fulfill law enforcement duties. Advanced courses may explore specific types of crimes, ethical and legal responsibilities, crime scene investigations, emergency medical procedures, use of force, and prisoner transport.", "u": null, "notes": "concept: NI001517164120", "dep": null}, {"v": "15055", "n": "Forensic Science", "d": "Forensic Science courses provide an overview of the theoretical understanding and practical application of forensic science techniques. These courses explore the applied science and the fields of biology, chemistry, physics, and crime science investigation. Topics typically covered may include genetics, anthropology, toxicology, entomology, ballistics, pathology, computer forensics, fire debris and trace evidence among others.", "u": null, "notes": "concept: NI001517164121", "dep": null}, {"v": "15056", "n": "Crime Scene Management", "d": "Crime Scene Management courses provide the skills and knowledge necessary for criminalistics - the securing, investigating, and processing of a crime scene. Topics may include, but are not limited to, evidence collection and preservation, finger printing, sketching, securing and photographing the crime scene, and chain of custody.", "u": null, "notes": "concept: NI001517164122", "dep": null}, {"v": "15057", "n": "Criminal Law and Procedures", "d": "Criminal Law and Procedures courses provide students with knowledge and skills related to understanding criminal law, constitutional amendments, and due process. Course content may include specific types of crimes, such as vehicle crimes, personal crimes, cyber crimes, drug crimes, and crimes related to child pornography or pedophiles.", "u": null, "notes": "concept: NI001517164123", "dep": null}, {"v": "15058", "n": "Ethics in Criminal Justice", "d": "Ethics in Criminal Justice courses cover ethical standards and codes of professional behavior for police officers and others placed in positions of public trust. Topics may include use of force, gratuities, intra- and inter-agency conduct, integrity, ethical necessity of due process, and on-duty and off-duty conduct.", "u": null, "notes": "concept: NI001517164124", "dep": null}, {"v": "15097", "n": "Law Enforcement�Independent Study", "d": "Law Enforcement�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to law enforcement. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164125", "dep": null}, {"v": "15098", "n": "Law Enforcement�Workplace Experience", "d": "Law Enforcement�Workplace Experience courses provide work experience in fields related to law enforcement. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164126", "dep": null}, {"v": "15099", "n": "Law Enforcement�Other", "d": "Other Law Enforcement courses.", "u": null, "notes": "concept: NI001517164127", "dep": null}, {"v": "15101", "n": "Public Safety", "d": "Public Safety courses introduce students to the field of public safety and extend their knowledge and skills pertaining to the safety and security of homes, workplaces, and the community. These courses cover such topics as policing, law enforcement, emergency service, and private security and corrections and may cover all or a subset of these services.", "u": null, "notes": "concept: NI001517164128", "dep": null}, {"v": "15102", "n": "Security Services", "d": "Security Services courses provide instruction regarding the safety and security of (1) people, (2) personal property, (3) intellectual property, and (4) buildings and facilities.", "u": null, "notes": "concept: NI001517164129", "dep": null}, {"v": "15103", "n": "Particular Topics in Security", "d": "These courses examine specific topics related to security and protective services, rather than provide a general study.", "u": null, "notes": "concept: NI001517164130", "dep": null}, {"v": "15152", "n": "Fire Fighting", "d": "Fire Fighting courses offer students the opportunity to learn fire prevention and control under controlled conditions. Typically, students learn about the organization, rules, requirements, and regulations of fire departments; study and practice the tools and techniques used by firefighters to control or extinguish fires; and examine the behavior of fires. These courses also usually include emergency medical procedures and present fire investigation techniques.", "u": null, "notes": "concept: NI001517164131", "dep": null}, {"v": "16051", "n": "Exploration of Restaurant, Food and Beverage Services", "d": "Exploration of Restaurant, Food, and Beverage Services courses provide students with an overview of the restaurant, food, and beverage service industry. Topics covered include industry terminology, the history of restaurant, food, and beverage services, introduction to marketing, and the various careers available in the industry.", "u": null, "notes": "concept: NI001517164132", "dep": null}, {"v": "16052", "n": "Restaurant, Food and Beverage Services�Comprehensive", "d": "Restaurant, Food, and Beverage Services�Comprehensive courses provide students with knowledge and skills related to commercial and institutional food service establishments. Course topics range widely, but usually include sanitation and safety procedures, nutrition and dietary guidelines, food preparation (and quantity food production), and meal planning and presentation. Restaurant, Food, and Beverage Service courses may include both \"back-of-the-house\" and \"front-of-the-house\" experiences, and may therefore also cover reservation systems, customer service, and restaurant/business management.", "u": null, "notes": "concept: NI001517164133", "dep": null}, {"v": "16053", "n": "Food Service", "d": "Food Service courses provide students with instruction regarding nutrition, principles of healthy eating, and the preparation of food. Among the topics covered are large-scale meal preparation, preserving nutrients throughout the food preparation process, use and care of commercial cooking equipment, food storage, advances in food technology, safety, sanitation, management, production, service skills, menu planning, the operation of institutional food establishments and the careers available in the food service industry.", "u": null, "notes": "concept: NI001517164134", "dep": null}, {"v": "21047", "n": "Engineering�Independent Study", "d": "Engineering�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to engineering. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164426", "dep": null}, {"v": "21048", "n": "Engineering�Workplace Experience", "d": "Engineering�Workplace Experience courses provide students with work experience in an engineering-related field. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164427", "dep": null}, {"v": "21049", "n": "Engineering�Other", "d": "Other Engineering courses.", "u": null, "notes": "concept: NI001517164428", "dep": null}, {"v": "21051", "n": "Technological Literacy", "d": "Technological Literacy courses expose students to the communication, transportation, energy, production, biotechnology, and integrated technology systems and processes that affect their lives. The study of these processes enables students to better understand technological systems and their applications and uses.", "u": null, "notes": "concept: NI001517164429", "dep": null}, {"v": "21052", "n": "Technological Processes", "d": "Technological Processes courses provide students with the opportunity to focus on one or more areas of industrial technology, applying technological processes to solve real problems and developing the knowledge and skills to design, modify, use, and apply technology appropriately. Students may examine case studies, explore simulations, or design and build prototypes and working models.", "u": null, "notes": "concept: NI001517164430", "dep": null}, {"v": "21018", "n": "PLTW Principles of Engineering", "d": "Following Project Lead the Way's suggested curriculum, PLTW Principles of Engineering courses focus on solving a wide range of engineering problems. Topics such as mechanisms, structure and material strength, and automation are explored as students research, strategize, and document the design process.", "u": null, "notes": "concept: NI001517164431", "dep": null}, {"v": "21019", "n": "PLTW Aerospace Engineering", "d": "Following Project Lead the Way's suggested curriculum, PLTW Aerospace Engineering courses are designed to teach students the fundamentals of atmospheric and space flight. These courses emphasize physics and robot system concepts by focusing on the design of an airfoil, propulsion systems, rockets, and remotely operated vehicles. Course content may include the study of orbital mechanics using industry-standard software.", "u": null, "notes": "concept: NI001517164432", "dep": null}, {"v": "21021", "n": "PLTW Civil Engineering and Architecture", "d": "Following Project Lead the Way's suggested curriculum, PLTW Civil Engineering and Architecture courses focus on building and site design and development. In these courses, students use 3D architecture design software and apply mathematics, science, and standard engineering projects to create residential and commercial designs.", "u": null, "notes": "concept: NI001517164433", "dep": null}, {"v": "21022", "n": "PLTW Computer Integrated Manufacturing", "d": "Following Project Lead the Way's suggested curriculum, PLTW Computer Integrated Manufacturing courses introduce students to high-tech innovations related to modern manufacturing. These courses emphasize manufacturing processes, product design, robotics, and automation.", "u": null, "notes": "concept: NI001517164434", "dep": null}, {"v": "21023", "n": "PLTW Digital Electronics", "d": "Following Project Lead the Way's suggested curriculum, PLTW Digital Electronics courses introduce students to digital circuits in appliances and mobile devices. Course topics include combinational and sequential logic, logic gates, integrated circuits, programmable logic devices, along with other circuit design tools.", "u": null, "notes": "concept: NI001517164435", "dep": null}, {"v": "21053", "n": "Emerging Technologies", "d": "Emerging Technologies courses expose students to and help them understand new and emerging technologies. The range of technological issues covered in this course can vary widely and content covered can be flexible. Topics covered may include, but are not limited to, lasers, fiber optics, robotics, and transportation technologies.", "u": null, "notes": "concept: NI001517164436", "dep": null}, {"v": "21054", "n": "Technology Innovation and Assessment", "d": "Technology Innovation and Assessment courses use engineering design activities to help students understand how criteria, constraints, and processes affect design solutions and provide students with the skills to systematically assess technological developments or solutions. Course topics may include brainstorming, visualizing, modeling, simulating, constructing, testing, and refining designs.", "u": null, "notes": "concept: NI001517164437", "dep": null}, {"v": "21055", "n": "Aerospace Technology", "d": "Aerospace Technology courses introduce students to the technology systems used in the aerospace industry and their interrelationships. Examples of such systems include satellite communications systems, composite materials in airframe manufacturing, space station constructions techniques, space shuttle propulsion systems, aerostatics, and aerodynamics.", "u": null, "notes": "concept: NI001517164438", "dep": null}, {"v": "21056", "n": "Particular Topics in Technology Applications", "d": "These courses examine specific topics in technology applications other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517164439", "dep": null}, {"v": "21097", "n": "Technology�Independent Study", "d": "Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to technology systems and processes. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164440", "dep": null}, {"v": "21997", "n": "Engineering and Technology�Independent Study", "d": "Engineering and Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to engineering and/or technology. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164441", "dep": null}, {"v": "21998", "n": "Engineering and Technology�Workplace Experience", "d": "Engineering and Technology�Workplace Experience courses provide students with work experience in a field related to engineering or technology. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164442", "dep": null}, {"v": "21999", "n": "Engineering and Technology�Other", "d": "Other Engineering and Technology courses.", "u": null, "notes": "concept: NI001517164443", "dep": null}, {"v": "22001", "n": "Standardized Test Preparation", "d": "Standardized Test Preparation courses help prepare students for national standardized tests such as the PSAT, SAT, and ACT. In particular, these courses assist students in developing and/or expanding their vocabulary, test-taking, and reasoning skills through study, lecture, and practice drills. Course topics may include vocabulary review; root words, prefixes, and suffixes; mathematical concepts, logic, and rules; and general problem-solving and test-taking strategies.", "u": null, "notes": "concept: NI001517164444", "dep": null}, {"v": "21098", "n": "Technology�Workplace Experience", "d": "Technology�Workplace Experience courses provide students with work experience in a field related to technological systems and structures. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164445", "dep": null}, {"v": "21099", "n": "Technology�Other", "d": "Other Technology courses.", "u": null, "notes": "concept: NI001517164446", "dep": null}, {"v": "21101", "n": "Drafting Careers Exploration", "d": "Geared for students with an interest in careers that use drafting skills and applications, Drafting Careers Exploration courses expose students to the opportunities available for draftspeople (engineering, architectural, industrial, and so on). These courses serve to introduce basic skills and the field in general, providing students with the opportunity to identify a focus for continued study or to determine that their interests lie elsewhere.", "u": null, "notes": "concept: NI001517164447", "dep": null}, {"v": "21102", "n": "Drafting�General", "d": "Drafting�General courses introduce students to the technical craft of drawing illustrations to represent and/or analyze design specifications and then refine the skills necessary for this craft. Drafting�General courses use exercises from a variety of applications to provide to students the knowledge and experience to develop the ability to perform freehand sketching, lettering, geometric construction, and multiview projections and to produce various types of drawings (working, detail, assembly, schematic, perspective, and so on). Computer-aided drafting (CAD) systems (if available) are typically introduced and used to fulfill course objectives.", "u": null, "notes": "concept: NI001517164448", "dep": null}, {"v": "21103", "n": "Drafting�Architectural", "d": "Drafting�Architectural courses introduce students to and help them refine the technical craft of drawing illustrations to represent and/or analyze design specifications, using examples drawn from architectural applications. These courses are intended to help students develop general drafting skills, but place a particular emphasis on interior and exterior residential (and light commercial) design, site orientation, floor plans, electrical plans, design sketches, and presentation drawings. In addition, students may prepare scale models.", "u": null, "notes": "concept: NI001517164449", "dep": null}, {"v": "21104", "n": "Drafting�Civil/Structural", "d": "Drafting�Civil/Structural courses introduce students to and help them refine the technical craft of drawing illustrations to represent and/or analyze design specifications, using examples drawn from civil engineering and/or structural applications. These courses are intended to help students develop general drafting skills, but place a particular emphasis on skills needed for typography and survey work.", "u": null, "notes": "concept: NI001517164450", "dep": null}, {"v": "21105", "n": "Drafting�Electrical/Electronic", "d": "Drafting�Electrical/Electronic courses introduce students to and help them refine the technical craft of drawing illustrations to represent and/or analyze design specifications, using examples drawn from electric and/or electronic fields. These courses are intended to help students develop general drafting skills, but place a particular emphasis on those skills needed for electrical and electronic schematics.", "u": null, "notes": "concept: NI001517164451", "dep": null}, {"v": "21106", "n": "Drafting�Technical/Mechanical", "d": "Drafting�Technical/Mechanical courses introduce students to and help them refine the technical craft of drawing illustrations to represent and/or analyze design specifications, using examples drawn from industrial applications. These courses are intended to help students develop general drafting skills, but place a particular emphasis on sectioning, auxiliary views, revolutions, and surface development. In these courses, students typically learn basic machining and fabrication processes as they draw schematic diagrams featuring cams, gears, linkages, levers, pulleys, and so on.", "u": null, "notes": "concept: NI001517164452", "dep": null}, {"v": "21107", "n": "CAD Design and Software", "d": "Frequently offered as an intermediary step to more advanced drafting courses (or as a concurrent course), CAD Design and Software courses introduce students to the computer-aided drafting systems available in the industry.", "u": null, "notes": "concept: NI001517164453", "dep": null}, {"v": "21108", "n": "Blueprint Reading", "d": "Blueprint Reading courses provide students with the knowledge and ability to interpret the lines, symbols, and conventions of drafted blueprints. They generally emphasize interpreting, not producing, blueprints, although the courses may provide both types of experiences. Blueprint Reading courses typically use examples from a wide variety of industrial and technological applications.", "u": null, "notes": "concept: NI001517164454", "dep": null}, {"v": "21147", "n": "Drafting�Independent Study", "d": "Drafting�Independent Study courses, often conducted with instructors as mentors, enable students to explore drafting-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164455", "dep": null}, {"v": "21148", "n": "Drafting�Workplace Experience", "d": "Drafting�Workplace Experience courses provide work experience in a field related to drafting. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164456", "dep": null}, {"v": "21149", "n": "Drafting�Other", "d": "Other Drafting courses.", "u": null, "notes": "concept: NI001517164457", "dep": null}, {"v": "21995", "n": "Engineering and Technology�Aide", "d": "Engineering and Technology�Aide courses offer students the opportunity to assist instructors in preparing, organizing or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164458", "dep": null}, {"v": "22002", "n": "State Test Preparation", "d": "State Test Preparation courses prepare students for particular state tests required for graduation. These courses may cover specific content areas (such as citizenship, mathematics, language arts, and so on) according to individual student needs, or they may provide a more general course of study, similar to the Standardized Test Preparation course described above.", "u": null, "notes": "concept: NI001517164459", "dep": null}, {"v": "22106", "n": "Seminar", "d": "Seminar courses vary widely, but typically offer a small peer group the opportunity to investigate areas of interest. Course objectives may include improvement of research and investigatory skills, presentation skills, interpersonal skills, group process skills, and problem-solving and critical-thinking skills. Seminars aimed at juniors and seniors often include a college and career exploration and planning component.", "u": null, "notes": "concept: NI001517164460", "dep": null}, {"v": "22107", "n": "Peer Counseling", "d": "Peer Counseling courses allow students to serve as leaders to reduce conflict among their fellow students. Students may work individually or as part of a group to solve problems and promote mutual support among their peers.", "u": null, "notes": "concept: NI001517164461", "dep": null}, {"v": "22108", "n": "IB Creativity, Activity, Service", "d": "IB Creativity, Activity, and Service (CAS) courses are a required extracurricular component of the International Baccalaureate program. The CAS requirement emphasizes the importance of life outside of the world of scholarship and encourages young people to share their energies and special talents while they develop awareness, concern, and the ability to work cooperatively with others. Participation in theater productions, sports, and community service are examples of activities that fulfill the CAS course requirements.", "u": null, "notes": "concept: NI001517164462", "dep": null}, {"v": "22109", "n": "IB Extended Essay", "d": "Obligatory for every International Baccalaureate degree candidate, IB Extended Essay aim to help students develop an independent, self-directed piece of research, culminating in a 4,000 word paper. These courses provide students with practical preparation for later research and help build their analysis, synthesis, and evaluation skills.", "u": null, "notes": "concept: NI001517164463", "dep": null}, {"v": "22003", "n": "Study Skills", "d": "Study Skills courses prepare students for success in high school and/or for postsecondary education. Course topics may vary according to the students involved, but typically include reading improvement skills, such as scanning, note-taking, and outlining; library and research skills; listening and note-taking; vocabulary skills; and test-taking skills. The courses may also include exercises designed to generate organized, logical thinking and writing.", "u": null, "notes": "concept: NI001517164464", "dep": null}, {"v": "22004", "n": "Dropout Prevention Program", "d": "Dropout Prevention Program courses vary widely, but typically are targeted at students who have been identified as being at risk of dropping out of or failing in school. Course content may include study skills and individual tutorials; career exploration or job readiness skills; communication skills; personal assessment and awareness activities; speaker presentations; and small-group seminars.", "u": null, "notes": "concept: NI001517164465", "dep": null}, {"v": "22005", "n": "Tutorial", "d": "Tutorial courses provide students with the assistance they need to successfully complete their coursework. Students may receive help in one or several subjects.", "u": null, "notes": "concept: NI001517164466", "dep": null}, {"v": "22006", "n": "Study Hall", "d": "Study Hall courses provide students with the opportunity and time to complete classroom assignments or school projects. Students typically work on their own, without the help of a tutor; however, they are supervised and usually remain in the classroom.", "u": null, "notes": "concept: NI001517164467", "dep": null}, {"v": "22007", "n": "Advancement Via Individual Determination (AVID)", "d": "AVID courses encourage students to pursue college readiness (and eventual enrollment). Typically, the courses offer activities that enable students to learn organizational and study skills, enhance their critical thinking skills, receive academic assistance as necessary, and be motivated to aspire to college education.", "u": null, "notes": "concept: NI001517164468", "dep": null}, {"v": "24065", "n": "AP Spanish Literature and Culture", "d": "Designed by the College Board to parallel college-level Introduction to Hispanic Literature courses, AP Spanish Literature and Culture courses cover representative works from the literatures of Spain and Spanish America, encompassing all genres. The courses build students' Spanish language proficiency, with special attention given to critical opinions and literary analyses in oral and written Spanish. Students are encouraged to relate the texts to their cultural contexts.", "u": null, "notes": "concept: NI001517162836", "dep": null}, {"v": "24110", "n": "French Literature", "d": "French Literature courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in French. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of French cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162837", "dep": null}, {"v": "24111", "n": "Particular Topics in French", "d": "Particular Topics in French courses examine particular topics focused on French language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162838", "dep": null}, {"v": "24066", "n": "IB Language B (Spanish), Middle Years Program", "d": "IB Language B (Spanish), Middle Years Program courses enable students to gain competence in modern Spanish; these courses also encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162839", "dep": null}, {"v": "24067", "n": "IB Language A: Language and Literature�Spanish", "d": "IB Language A: Language and Literature�Spanish courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Spanish in an academic context.", "u": null, "notes": "concept: NI001517162840", "dep": null}, {"v": "24068", "n": "IB Language Ab Initio�Spanish", "d": "IB Language Ab Initio�Spanish courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517162841", "dep": null}, {"v": "24099", "n": "Spanish�Other", "d": "Other Spanish courses.", "u": null, "notes": "concept: NI001517162842", "dep": null}, {"v": "24100", "n": "French for Young Learners (prior-to-secondary)", "d": "French for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in French and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of French-speaking cultures.", "u": null, "notes": "concept: NI001517162843", "dep": null}, {"v": "24101", "n": "French Immersion (prior-to-secondary)", "d": "French Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in French and grade-specific content using French as the language of instruction. French Immersion courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of French-speaking cultures.", "u": null, "notes": "concept: NI001517162844", "dep": null}, {"v": "24102", "n": "French I", "d": "Designed to introduce students to French language and culture, French I courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of French-speaking cultures.", "u": null, "notes": "concept: NI001517162845", "dep": null}, {"v": "24103", "n": "French II", "d": "French II courses build upon skills developed in French I, preparing students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. French II courses introduce the relationships among the products, practices, and perspectives of French-speaking cultures.", "u": null, "notes": "concept: NI001517162846", "dep": null}, {"v": "24104", "n": "French III", "d": "French III courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of French-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162847", "dep": null}, {"v": "24105", "n": "French IV", "d": "French IV courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. French IV courses promote students' understanding of the relationships among the products, practices, and perspectives of French-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162848", "dep": null}, {"v": "24106", "n": "French V", "d": "French V courses prepare students to communicate authentically in French by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. French V courses promote students' understanding of the relationships among the products, practices, and perspectives of French-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162849", "dep": null}, {"v": "24107", "n": "French for Native Speakers", "d": "French for Native Speakers courses prepare native and heritage speakers to communicate in French in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. French for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the French-speaking world.", "u": null, "notes": "concept: NI001517162850", "dep": null}, {"v": "24108", "n": "French Field Experience", "d": "French Field Experience courses place students in environments in which they interact with native French speakers, typically in settings where French is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162851", "dep": null}, {"v": "24109", "n": "French Conversation and Culture", "d": "French Conversation and Culture courses provide students with an introduction to the French language and the culture(s) of French-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162852", "dep": null}, {"v": "24112", "n": "IB Language A: Literature�French", "d": "IB Language A: Literature�French courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using French in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162853", "dep": null}, {"v": "24158", "n": "Italian Field Experience", "d": "Italian Field Experience courses place students in environments in which they interact with native Italian speakers, typically in settings where Italian is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162854", "dep": null}, {"v": "24159", "n": "Italian Conversation and Culture", "d": "Italian Conversation and Culture courses provide students with an introduction to the Italian language and the culture(s) of Italian-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162855", "dep": null}, {"v": "24113", "n": "IB Language B�French", "d": "IB Language B�French courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162856", "dep": null}, {"v": "24114", "n": "AP French Language and Culture", "d": "Designed by the College Board to parallel third-year college-level courses in French language, AP French Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in French, both orally and in writing. These courses also help students understand and interpret written and spoken French. In addition, students explore the culture of French-speaking people in historical and contemporary contexts.", "u": null, "notes": "concept: NI001517162857", "dep": null}, {"v": "24116", "n": "IB Language B (French), Middle Years Program", "d": "International Baccalaureate (IB) Language B (French), Middle Years Program courses enable students to gain competence in modern French and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162858", "dep": null}, {"v": "24117", "n": "IB Language A: Language and Literature�French", "d": "IB Language A: Language and Literature�French courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using French in an academic context.", "u": null, "notes": "concept: NI001517162859", "dep": null}, {"v": "24118", "n": "IB Language Ab Initio�French", "d": "IB Language Ab Initio�French courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517162860", "dep": null}, {"v": "24149", "n": "French�Other", "d": "Other French courses.", "u": null, "notes": "concept: NI001517162861", "dep": null}, {"v": "24150", "n": "Italian for Young Learners (prior-to-secondary)", "d": "Italian for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Italian and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Italian-speaking cultures.", "u": null, "notes": "concept: NI001517162862", "dep": null}, {"v": "24151", "n": "Italian Immersion (prior-to-secondary)", "d": "Italian Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Italian and grade-specific content using Italian as the language of instruction. Italian Immersion courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Italian-speaking cultures.", "u": null, "notes": "concept: NI001517162863", "dep": null}, {"v": "24152", "n": "Italian I", "d": "Designed to introduce students to Italian language and culture, Italian I courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Italian-speaking cultures.", "u": null, "notes": "concept: NI001517162864", "dep": null}, {"v": "24153", "n": "Italian II", "d": "Italian II courses build upon skills developed in Italian I, preparing students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Italian II courses introduce the relationships among the products, practices, and perspectives of Italian-speaking cultures.", "u": null, "notes": "concept: NI001517162865", "dep": null}, {"v": "24154", "n": "Italian III", "d": "Italian III courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Italian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162866", "dep": null}, {"v": "24155", "n": "Italian IV", "d": "Italian IV courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Italian IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Italian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162867", "dep": null}, {"v": "24156", "n": "Italian V", "d": "Italian V courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Italian V courses promote students' understanding of the relationships among the products, practices, and perspectives of Italian-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162868", "dep": null}, {"v": "24157", "n": "Italian for Native Speakers", "d": "Italian for Native Speakers courses prepare native and heritage speakers to communicate in Italian in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Italian for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Italian-speaking world.", "u": null, "notes": "concept: NI001517162869", "dep": null}, {"v": "24160", "n": "Italian Literature", "d": "Italian Literature courses prepare students to communicate authentically in Italian by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Italian. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Italian cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162870", "dep": null}, {"v": "24206", "n": "Portuguese V", "d": "Portuguese V courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Portuguese V courses promote students' understanding of the relationships among the products, practices, and perspectives of Portuguese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162871", "dep": null}, {"v": "24207", "n": "Portuguese for Native Speakers", "d": "Portuguese for Native Speakers courses prepare native and heritage speakers to communicate in Portuguese in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Portuguese for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Portuguese-speaking world.", "u": null, "notes": "concept: NI001517162872", "dep": null}, {"v": "24161", "n": "Particular Topics in Italian", "d": "Particular Topics in Italian courses examine particular topics focused on Italian language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162873", "dep": null}, {"v": "24162", "n": "IB Language A: Literature�Italian", "d": "IB Language A: Literature�Italian courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Italian in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162874", "dep": null}, {"v": "24956", "n": "World Language (Other Language) V", "d": "World Language (Other Language) V courses prepare students to communicate authentically in a language not specified elsewhere in this classification system by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. World Language (Other Language) V courses promote students' understanding of the relationships among the products, practices, and perspectives of the countries and cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163140", "dep": null}, {"v": "24907", "n": "American Indian Language for Native Speakers", "d": "American Indian Language for Native Speakers courses prepare native and heritage speakers to communicate in an American Indian Language (e.g., Navajo, Cherokee, or Cree) in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. American Indian Language for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163141", "dep": null}, {"v": "24908", "n": "American Indian Language Field Experience", "d": "American Indian Language Field Experience courses place students in environments in which they interact with native American Indian Language speakers, typically in settings where the American Indian Language of study is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163142", "dep": null}, {"v": "24960", "n": "World Language (Other Language) Literature", "d": "World Language (Other Language) Literature courses prepare students to communicate authentically in a language not specified elsewhere in this classification system by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in the language of study. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of the cultures using the studied language into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517163143", "dep": null}, {"v": "24962", "n": "IB Language A: Literature�World Language (Other Language)", "d": "IB Language A: Literature�World Language (Other Language) courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using the language of study in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517163145", "dep": null}, {"v": "24963", "n": "IB Language B�World Language (Other Language)", "d": "IB Language B�World Language (Other Language) courses prepare students to take the International Baccalaureate Language B exams for a language not specified elsewhere in this classification system. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517163146", "dep": null}, {"v": "24957", "n": "World Language (Other Language) for Native Speakers", "d": "World Language (Other Language) for Native Speakers courses prepare native and heritage speakers to communicate in a language not specified elsewhere in this classification system in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. World Language (Other Language) for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures speaking the language of study.", "u": null, "notes": "concept: NI001517163147", "dep": null}, {"v": "24958", "n": "World Language (Other Language) Field Experience", "d": "World Language (Other Language) Field Experience courses place students in environments in which they interact with native speakers of a language not specified elsewhere in this classification system, typically in settings where the language of study is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163148", "dep": null}, {"v": "24959", "n": "World Language (Other Language) Conversation and Culture", "d": "World Language (Other Language) Conversation and Culture courses provide students with an introduction to a language not specified elsewhere in this classification system and the culture(s) of people speaking the language of study, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517163149", "dep": null}, {"v": "24966", "n": "IB Language B (Other World Language), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Other World Language), Middle Years Program courses allow students to gain competence in a language not specified elsewhere in this classification system and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163150", "dep": null}, {"v": "24967", "n": "IB Language A: Language and Literature�(Other World Language)", "d": "IB Language A: Language and Literature�(Other World Language) courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using the language of study in an academic context.", "u": null, "notes": "concept: NI001517163151", "dep": null}, {"v": "24968", "n": "IB Language Ab Initio�(Other World Language)", "d": "IB Language Ab Initio�(Other World Language) courses prepare students to take the International Baccalaureate exam for a language not specified elsewhere in this classification system. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517163152", "dep": null}, {"v": "24989", "n": "World Language (Other Language)�Other", "d": "Other courses specific to a world language not elsewhere specified.", "u": null, "notes": "concept: NI001517163153", "dep": null}, {"v": "24995", "n": "World Language and Literature�Aide", "d": "World Language and Literature�Aide courses offer students the opportunity to assist instructors in preparing, organizing or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163154", "dep": null}, {"v": "24997", "n": "World Language and Literature�Independent Study", "d": "World Language and Literature�Independent Study courses, often conducted with instructors as mentors, enable students to explore (non-English) world language-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular language, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163155", "dep": null}, {"v": "24998", "n": "World Language and Literature�Workplace Experience", "d": "World Language and Literature�Workplace Experience courses provide students with work experience in a field related to a (non-English) world language or literature. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163156", "dep": null}, {"v": "24999", "n": "World Language and Literature�Other", "d": "Other World Language and Literature courses.", "u": null, "notes": "concept: NI001517163157", "dep": null}, {"v": "01001", "n": "English/Language Arts I (9th grade)", "d": "English/Language Arts I (9th grade) courses build upon students' prior knowledge of grammar, vocabulary, word usage, and the mechanics of writing and usually include the four aspects of language use: reading, writing, speaking, and listening. Typically, these courses introduce and define various genres of literature, with writing exercises often linked to reading selections.", "u": null, "notes": "concept: NI001517163158", "dep": null}, {"v": "01002", "n": "English/Language Arts II (10th grade)", "d": "English/Language Arts II (10th grade) courses usually offer a balanced focus on composition and literature. Typically, students learn about the alternate aims and audiences of written compositions by writing persuasive, critical, and creative multi-paragraph essays and compositions. Through the study of various genres of literature, students can improve their reading rate and comprehension and develop the skills to determine the author's intent and theme and to recognize the techniques used by the author to deliver his or her message.", "u": null, "notes": "concept: NI001517163159", "dep": null}, {"v": "01003", "n": "English/Language Arts III (11th grade)", "d": "English/Language Arts III (11th grade) courses continue to develop students' writing skills, emphasizing clear, logical writing patterns, word choice, and usage, as students write essays and begin to learn the techniques of writing research papers. Students continue to read works of literature, which often form the backbone of the writing assignments. Literary conventions and stylistic devices may receive greater emphasis than in previous courses.", "u": null, "notes": "concept: NI001517163160", "dep": null}, {"v": "01004", "n": "English/Language Arts IV (12th grade)", "d": "English/Language Arts IV (12th grade) courses blend composition and literature into a cohesive whole as students write critical and comparative analyses of selected literature, continuing to develop their language arts skills. Typically, students primarily write multi-paragraph essays, but they may also write one or more major research papers.", "u": null, "notes": "concept: NI001517163161", "dep": null}, {"v": "01005", "n": "AP English Language and Composition", "d": "Following the College Board's suggested curriculum designed to parallel college-level English courses, AP English Language and Composition courses expose students to prose written in a variety of periods, disciplines, and rhetorical contexts. These courses emphasize the interaction of authorial purpose, intended audience, and the subject at hand, and through them, students learn to develop stylistic flexibility as they write compositions covering a variety of subjects that are intended for various purposes.", "u": null, "notes": "concept: NI001517163162", "dep": null}, {"v": "01006", "n": "AP English Literature and Composition", "d": "Following the College Board's suggested curriculum designed to parallel college-level English courses, AP English Literature and Composition courses enable students to develop critical standards for evaluating literature. Students study the language, character, action, and theme in works of recognized literary merit; enrich their understanding of connotation, metaphor, irony, syntax, and tone; and write compositions of their own (including literary analysis, exposition, argument, narrative, and creative writing).", "u": null, "notes": "concept: NI001517163163", "dep": null}, {"v": "01010", "n": "IB Language A (English), Middle Years Program", "d": "International Baccalaureate (IB) Language A (English), Middle Years Program courses include instruction in the instrumental function of a language, emphasizing skills in listening, viewing, speaking, reading, presenting, and writing, as well as literature encompassing a variety of periods and genres.", "u": null, "notes": "concept: NI001517163164", "dep": null}, {"v": "01011", "n": "IB Language A: Language and Literature�English", "d": "IB Language A: Language and Literature�English courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using English in an academic context.", "u": null, "notes": "concept: NI001517163165", "dep": null}, {"v": "01012", "n": "IB Literature and Performance", "d": "IB Literature and Performance courses prepare students to take the International Baccalaureate Literature and Performance exam. Course content focuses on the relationship between literature and theatre. These courses may cover the critical study of literary texts, the exploration of chosen approaches to a text, and the performance of written texts.", "u": null, "notes": "concept: NI001517163166", "dep": null}, {"v": "01026", "n": "Language Arts (early childhood education)", "d": "Language Arts (early childhood education) courses develop students' readiness for language arts learning in reading, writing, listening, and speaking. Courses may include activities related to phonics, phonemic awareness, and vocabulary. Content is age appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163167", "dep": null}, {"v": "01027", "n": "Language Arts (pre-kindergarten)", "d": "Language Arts (pre-kindergarten) courses develop students' readiness for language arts learning in reading, writing, listening, and speaking. Courses may include activities related to phonics, phonemic awareness, and vocabulary. Content is age appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163168", "dep": null}, {"v": "24854", "n": "American Sign Language III", "d": "American Sign Language III courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163169", "dep": null}, {"v": "24855", "n": "American Sign Language IV", "d": "American Sign Language IV courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. American Sign Language IV courses promote students' understanding of the relationships among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163170", "dep": null}, {"v": "24856", "n": "American Sign Language V", "d": "American Sign Language V courses prepare students to communicate authentically in American Sign Language by interpreting (reading/viewing), exchanging (signing and reading), and presenting (signing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. American Sign Language V courses promote students' understanding of the relationships among the practices, perspectives, and cultures of deaf people and communities.", "u": null, "notes": "concept: NI001517163171", "dep": null}, {"v": "24858", "n": "American Sign Language Field Experience", "d": "American Sign Language Field Experience courses place students in environments in which they interact with native American Sign Language speakers, typically in settings where American Sign Language is the main language spoken. These courses enable students to strengthen their skills in exchanging (signing and reading/viewing), interpreting, and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517163172", "dep": null}, {"v": "24861", "n": "Particular Topics in American Sign Language", "d": "Particular Topics in American Sign Language courses examine particular topics focused on American Sign Language language or culture, such as translation, interpreting, application(s) to career/technical fields, or a specific dialect, other than those already described.", "u": null, "notes": "concept: NI001517163173", "dep": null}, {"v": "24866", "n": "IB Language B (American Sign Language), Middle Years Program", "d": "International Baccalaureate (IB) Language B (American Sign Language), Middle Years Program courses allow students to gain competence in modern American Sign Language and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517163174", "dep": null}, {"v": "24899", "n": "American Sign Language�Other", "d": "Other American Sign Language courses.", "u": null, "notes": "concept: NI001517163175", "dep": null}, {"v": "24900", "n": "American Indian Language (prior-to-secondary)", "d": "American Indian Language for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in an American Indian Language (e.g., Navajo, Cherokee, or Cree) and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in an American Indian Language by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of the cultures associated with the language of study.", "u": null, "notes": "concept: NI001517163176", "dep": null}, {"v": "01028", "n": "Language Arts (kindergarten)", "d": "Language Arts (kindergarten) courses engage students in activities to develop their language arts skills (reading, writing, listening, and speaking). Course content may emphasize storytelling or reading aloud and evoking a written, oral, or pictorial response. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163177", "dep": null}, {"v": "01029", "n": "Language Arts (grade 1)", "d": "Language Arts (grade 1) courses include the four aspects of language use: reading, writing, speaking, and listening. These courses may emphasize recognition of and response to various types of text, extension of vocabulary and writing skills, and the connection of language to the expression of ideas. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163178", "dep": null}, {"v": "04160", "n": "U.S. Government, Civics, and Economics", "d": "U.S. Government, Civics, and Economics courses combine a study of the structure of national, state, and local U.S. government with an overview of the principles of market economics. Course content may include contemporary U.S. issues. These courses prepare students to perform effectively as informed citizens.", "u": null, "notes": "concept: NI001517163484", "dep": null}, {"v": "04161", "n": "Civics", "d": "Civics courses examine the general structure and functions of U.S. systems of government, the roles and responsibilities of citizens to participate in the political process, and the relationship of the individual to the law and legal system. These courses do not typically delve to the same degree of detail into constitutional principles or the role of political parties and interest groups as do comprehensive courses in U.S. Government.", "u": null, "notes": "concept: NI001517163485", "dep": null}, {"v": "04162", "n": "Law Studies", "d": "Law Studies courses examine the history and philosophy of law as part of U.S. society and include the study of the major substantive areas of both criminal and civil law, such as constitutional rights, torts, contracts, property, criminal law, family law, and equity. Although these courses emphasize the study of law, they may also cover the workings of the legal system.", "u": null, "notes": "concept: NI001517163486", "dep": null}, {"v": "04163", "n": "Consumer Law", "d": "Consumer Law courses present a history and philosophy of law and the legal system in the United States, with a particular emphasis on those topics affecting students as consumers and young adults (such as contractual laws, laws pertaining to housing and marriage, and constitutional rights).", "u": null, "notes": "concept: NI001517163487", "dep": null}, {"v": "04164", "n": "Business Law (04164)", "d": "Business Law courses present a history and philosophy of law and the legal system in the United States, with a particular emphasis on those topics affecting students as future business leaders and employees. Such topics may include contracts, commercial paper and debt instruments, property rights, employer/employee relationships, and constitutional rights and responsibilities.", "u": null, "notes": "concept: NI001517163488\nprefLabel: Business Law", "dep": null}, {"v": "04197", "n": "Government, Politics and Law�Independent Study", "d": "Government, Politics, and Law�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within one of the fields of Government, Politics, and Law. These courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163489", "dep": null}, {"v": "04251", "n": "Anthropology", "d": "Anthropology courses introduce students to the study of human evolution with regard to the origin, distribution, physical attributes, environment, and culture of human beings. These courses provide an overview of anthropology, including but not limited to both physical and cultural anthropology.", "u": null, "notes": "concept: NI001517163490", "dep": null}, {"v": "04252", "n": "Particular Topics in Anthropology", "d": "These courses examine a particular topic in anthropology, such as physical anthropology, cultural anthropology, or archeology, rather than provide a more comprehensive overview of the field.", "u": null, "notes": "concept: NI001517163491", "dep": null}, {"v": "04253", "n": "IB Social and Cultural Anthropology", "d": "IB Social and Cultural Anthropology courses prepare students to take the International Baccalaureate Social and Cultural Anthropology exams. The courses aim to promote students' awareness of underlying patterns and causes of social relationships and systems, preconceptions and assumptions within the social environment, and the use of ethnographic data in creating models, drawing inferences, and making comparisons.", "u": null, "notes": "concept: NI001517163492", "dep": null}, {"v": "04254", "n": "Psychology", "d": "Psychology courses introduce students to the study of individual human behavior. Course content typically includes (but is not limited to) an overview of the field of psychology, topics in human growth and development, personality and behavior, and abnormal psychology.", "u": null, "notes": "concept: NI001517163493", "dep": null}, {"v": "04255", "n": "Particular Topics in Psychology", "d": "These courses examine a particular topic in psychology, such as human growth and development or personality, rather than provide a more comprehensive overview of the field.", "u": null, "notes": "concept: NI001517163494", "dep": null}, {"v": "04256", "n": "AP Psychology", "d": "Following the College Board's suggested curriculum designed to parallel a college-level introductory psychology course, AP Psychology courses introduce students to the systematic and scientific study of the behavior and mental processes of human beings and other animals, expose students to each major subfield within psychology, and enable students to examine the methods and ethics that psychologists use in their science and practice.", "u": null, "notes": "concept: NI001517163495", "dep": null}, {"v": "04257", "n": "IB Psychology", "d": "IB Psychology courses prepare students to take the International Baccalaureate Psychology exams. Course content includes biological, cognitive, and socio-cultural influences on human behavior, as well as experimental research methodology. Course content may also include the study of abnormal, developmental, health or sport psychology, the psychology of human relationships, and qualitative research in psychology.", "u": null, "notes": "concept: NI001517163496", "dep": null}, {"v": "04258", "n": "Sociology", "d": "Sociology courses introduce students to the study of human behavior in society. These courses provide an overview of sociology, generally including (but not limited to) topics such as social institutions and norms, socialization and social change, and the relationships among individuals and groups in society.", "u": null, "notes": "concept: NI001517163497", "dep": null}, {"v": "04198", "n": "Government, Politics and Law�Workplace Experience", "d": "Government, Politics, and Law�Workplace Experience courses provide students with work experience in a field related government, politics, and/or law. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163498", "dep": null}, {"v": "04199", "n": "Government, Politics and Law�Other", "d": "Other Government, Politics and Law courses.", "u": null, "notes": "concept: NI001517163499", "dep": null}, {"v": "04201", "n": "Economics", "d": "Economics courses provide students with an overview of economics with primary emphasis on the principles of microeconomics and the U.S. economic system. These courses may also cover topics such as principles of macroeconomics, international economics, and comparative economics. Economic principles may be presented in formal theoretical contexts, applied contexts, or both.", "u": null, "notes": "concept: NI001517163500", "dep": null}, {"v": "04202", "n": "Comparative Economics", "d": "Comparative Economics courses offer students an opportunity to study different economies and economic systems, including an examination of various approaches to problems in micro- and macroeconomics.", "u": null, "notes": "concept: NI001517163501", "dep": null}, {"v": "04203", "n": "AP Microeconomics", "d": "Following the College Board's suggested curriculum designed to parallel college-level microeconomics, AP Microeconomics courses provide students with a thorough understanding of the principles of economics that apply to the functions of individual decision makers (both consumers and producers). They place primary emphasis on the nature and functions of product markets, while also including a study of factor markets and the role of government in the economy.", "u": null, "notes": "concept: NI001517163502", "dep": null}, {"v": "04204", "n": "AP Macroeconomics", "d": "Following the College Board's suggested curriculum designed to parallel college-level macroeconomics, AP Macroeconomics courses provide students with a thorough understanding of the principles of economics that apply to an economic system as a whole. They place particular emphasis on the study of national income and price determination and developing students' familiarity with economic performance measures, economic growth, and international economics.", "u": null, "notes": "concept: NI001517163503", "dep": null}, {"v": "04205", "n": "AP Economics", "d": "AP Economics courses prepare students for the College Board's examinations in both AP Microeconomics and AP Macroeconomics. See SCED codes 04203 and 04204 for detailed content descriptions.", "u": null, "notes": "concept: NI001517163504", "dep": null}, {"v": "04206", "n": "IB Economics", "d": "Economics courses prepare students to take the International Baccalaureate Economics exams. The courses provide students with the basic tools of economic reasoning and teach them to use those tools to explain or interpret economic problems. Course content includes international and development economics, microeconomics, and macroeconomics.", "u": null, "notes": "concept: NI001517163505", "dep": null}, {"v": "04207", "n": "Particular Topics in Economics", "d": "These courses examine a particular topic in Economics rather than provide a general overview of the field. Course topics may include international economics, economic development and growth of a particular country or region, or resource allocation.", "u": null, "notes": "concept: NI001517163506", "dep": null}, {"v": "04208", "n": "Microeconomics", "d": "Microeconomics courses provide students with an understanding of the principles of economics that apply to the decision-making behaviors of individuals. Economic principles may be presented in a formal theoretical context, applied contexts, or both.", "u": null, "notes": "concept: NI001517163507", "dep": null}, {"v": "04209", "n": "Macroeconomics", "d": "Macroeconomics courses provide students with an understanding of the principles of economics that apply to the performance, structure, behavior, and decision-making of an economy (regional, national, or global) as a whole. Economic principles may be presented in a formal theoretical context, applied contexts, or both.", "u": null, "notes": "concept: NI001517163508", "dep": null}, {"v": "04247", "n": "Economics�Independent Study", "d": "Economics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the field of economics. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163509", "dep": null}, {"v": "04248", "n": "Economics�Workplace Experience", "d": "Economics�Workplace Experience courses provide work experience in a field related to economics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163510", "dep": null}, {"v": "04249", "n": "Economics�Other", "d": "Other Economics courses.", "u": null, "notes": "concept: NI001517163511", "dep": null}, {"v": "04259", "n": "Particular Topics in Sociology", "d": "These courses examine a particular topic in sociology, such as culture and society or the individual in society, rather than provide an overview of the field of sociology.", "u": null, "notes": "concept: NI001517163512", "dep": null}, {"v": "04310", "n": "Particular Topics in Humanities", "d": "These courses cover particular topics in humanities such as the interrelationships among painting, sculpture, architecture, and music or the exploration of a particular time period rather than provide a general overview of the subject.", "u": null, "notes": "concept: NI001517163513", "dep": null}, {"v": "04347", "n": "Humanities�Independent Study", "d": "Humanities�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the field of humanities. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163514", "dep": null}, {"v": "04348", "n": "Humanities�Workplace Experience", "d": "Humanities�Workplace Experience courses provide work experience in a field related to humanities. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163515", "dep": null}, {"v": "04349", "n": "Humanities�Other", "d": "Other Humanities courses.", "u": null, "notes": "concept: NI001517163516", "dep": null}, {"v": "04428", "n": "Social Studies (early childhood education)", "d": "Social Studies (early childhood education) courses provide a developmentally appropriate understanding of social studies concepts, helping students begin to develop an understanding of self and others; the concept of time (past and present events); and skills conducive to citizenship, such as group decisionmaking. Content is age appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163517", "dep": null}, {"v": "04429", "n": "Social Studies (pre-kindergarten)", "d": "Social Studies (pre-kindergarten) courses provide a developmentally appropriate understanding of social studies concepts, helping students begin to develop an understanding of self and others; the concept of time (past and present events); and skills conducive to citizenship, such as group decisionmaking. Content is age appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163518", "dep": null}, {"v": "04430", "n": "Social Studies (kindergarten)", "d": "Social Studies (kindergarten) courses generally provide initial foundations in the social studies disciplines: history, geography, civics and government, and economics. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163519", "dep": null}, {"v": "04260", "n": "Social Science", "d": "Social Science courses provide students with an introduction to the various disciplines in the social sciences, including anthropology, economics, geography, history, political science, psychology, and sociology. Typically, these courses emphasize the methodologies of the social sciences and the differences among the various disciplines.", "u": null, "notes": "concept: NI001517163520", "dep": null}, {"v": "04261", "n": "Social Science Research", "d": "Social Science Research courses emphasize the methods of social science research, including statistics and experimental design.", "u": null, "notes": "concept: NI001517163521", "dep": null}, {"v": "04297", "n": "Social Sciences�Independent Study", "d": "Social Sciences�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within one of the social science fields. Independent Study courses may provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163522", "dep": null}, {"v": "04298", "n": "Social Sciences�Workplace Experience", "d": "Social Sciences�Workplace Experience courses provide work experience in a field related to the social sciences. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163523", "dep": null}, {"v": "04299", "n": "Social Sciences�Other", "d": "Other Social Studies courses.", "u": null, "notes": "concept: NI001517163524", "dep": null}, {"v": "04301", "n": "Humanities Survey", "d": "Humanities Survey courses provide an overview of major expressions of the cultural heritage of selected western and eastern civilizations. Content typically includes (but is not limited to) the examination of selected examples of art, music, literature, architecture, technology, philosophy, and religion of the cultures studied. These courses may also cover the languages and political institutions of these cultures.", "u": null, "notes": "concept: NI001517163525", "dep": null}, {"v": "04302", "n": "Humanities", "d": "Humanities courses examine and evoke student responses to human creative efforts and the world in particular historical periods and in particular cultures. Course content includes exploration, analysis, synthesis, and various responses to cultural traditions, including viewing, listening, speaking, reading, writing, performing, and creating. The courses may also examine relationships among painting, sculpture, architecture, and music.", "u": null, "notes": "concept: NI001517163526", "dep": null}, {"v": "04303", "n": "Issues of Western Humanities", "d": "Issues of Western Humanities courses introduce students to the study of the cultural heritage of human beings and provide an opportunity to explore our fundamental humanity. The content typically includes definitions of the humanities in relation to history, literature, religion, philosophy, art, music, and architecture and study of the cultures of Greece, Rome, and one or more settings in contemporary periods. Students are asked to analyze and clarify their sense of themselves; examine and clarify their responsibilities in relation to those of others; examine philosophies concerning moral responsibility for the future; and examine philosophies about human mortality.", "u": null, "notes": "concept: NI001517163527", "dep": null}, {"v": "04304", "n": "IB Theory of Knowledge", "d": "Obligatory for every International Baccalaureate Diploma degree candidate, IB Theory of Knowledge courses aim to stimulate critical self-reflection of students' knowledge and experiences. Course content generates questions regarding the bases of knowledge and their verification in the disciplines of mathematics, natural sciences, human sciences, the arts, history, ethics, religious knowledge systems, and indigenous knowledge systems, with an awareness of moral, political, and aesthetic judgments and biases. Students learn to appreciate the strengths and limitations of various kinds of knowledge; to relate studied subjects to one another, general knowledge, and living experiences; to formulate rational arguments; and to evaluate the role of language in knowledge and as a way to convey knowledge.", "u": null, "notes": "concept: NI001517163528", "dep": null}, {"v": "08198", "n": "Drivers' Education�Workplace Experience", "d": "Drivers' Education�Workplace Experience courses provide work experience in a field related to drivers' education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163801", "dep": null}, {"v": "08199", "n": "Drivers' Education�Other", "d": "Other Driver's Education courses.", "u": null, "notes": "concept: NI001517163802", "dep": null}, {"v": "08201", "n": "Physical Education/Health/Drivers' Education", "d": "Physical Education/Health/Drivers' Education courses combine a range of activities and topics involving physical skills, human health issues, and safe driving. They are offered in ways that cover two or three of these areas. The physical education portion of these courses draws on team, individual, dual, recreational, and/or conditioning activities. The human health portion typically covers issues such as nutrition, stress management, drug/alcohol abuse prevention, and first aid. The drivers' education portion usually includes legal obligations and responsibilities, rules of the road and traffic procedures, safe driving strategies, and related topics.", "u": null, "notes": "concept: NI001517163803", "dep": null}, {"v": "08995", "n": "Physical, Health, and Safety Education�Aide", "d": "Physical, Health, and Safety Education�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163804", "dep": null}, {"v": "08997", "n": "Physical, Health, and Safety Education�Independent Study", "d": "Courses in Physical, Health, and Safety Education�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to physical, health, and safety education. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced physical, health and/or safety skills.", "u": null, "notes": "concept: NI001517163805", "dep": null}, {"v": "08998", "n": "Physical, Health, and Safety Education�Workplace Experience", "d": "Physical, Health, and Safety Education�Workplace Experience courses provide work experience in a field related to physical, health, and safety education. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163806", "dep": null}, {"v": "08999", "n": "Physical, Health, and Safety Education�Other", "d": "Other Physical, Health, and Safety Education courses.", "u": null, "notes": "concept: NI001517163807", "dep": null}, {"v": "09001", "n": "Introduction to Jr. ROTC", "d": "Introduction to Junior Reserve Officer Training Corps (ROTC) courses introduce students to the purposes and objectives of the Reserve Officer Training Corps program, which seeks to educate high school students in citizenship, promote community service, and instill responsibility. As part of that introduction, course topics typically include a brief history of the military branches in the United States and the basics of military drill, ceremony, and rank structure.", "u": null, "notes": "concept: NI001517163808", "dep": null}, {"v": "09002", "n": "Military Jr. ROTC�unspecified branch", "d": "Although individual course sequences may vary, the primary objectives of Military Junior Reserve Officer Training Corps (ROTC) courses are to provide students with instruction in the history, organization, role, objectives, and achievements of a particular branch of the U.S. Armed Forces; help them develop personal fitness, strong character, and leadership qualities; and expose them to the career opportunities provided by the U.S. Armed Services. These courses typically cover such topics as military customs, courtesies, rank, drill, and ceremonies and also emphasize citizenship and scholarship. The course content typically includes subjects related to the particular branch being studied (such as map-reading, nautical skills, aerospace technology, or communication technologies), as well as more general subjects (international law, national defense, celestial navigation, and geopolitical strategy).", "u": null, "notes": "concept: NI001517163809", "dep": null}, {"v": "09003", "n": "ROTC Drill", "d": "Reserve Officer Training Corps (ROTC) Drill courses provide students with an additional opportunity to improve their skills in military precision. These courses emphasize marching style and formations, firearm manipulation, body coordination and mechanics, and performing as a member of an orchestrated team. Class members typically participate in ceremonies and competitions.", "u": null, "notes": "concept: NI001517163810", "dep": null}, {"v": "09004", "n": "Military Leadership", "d": "Military Leadership courses focus solely on increasing students' leadership skills, particularly as they relate to military operations, customs, and hierarchies. These courses are typically a regular part of the ROTC programs described below (typically the final course within a program series); this Military Leadership course code and title should be used when those descriptions do not apply. The principles and skills taught in these courses include supervision, motivation, evaluation, and setting an example, and their application typically include military drill and inspections, athletic events, and other school activities.", "u": null, "notes": "concept: NI001517163811", "dep": null}, {"v": "09051", "n": "Army Junior ROTC I", "d": "Army Junior Reserve Officer Training Corps (ROTC) I courses include instruction in the organization and functions of the U.S. Army, leadership skills, and life skills education. The content of these courses cover (but is not limited to) the history and evolution of the Army, including its structure, operations, customs and courtesies; maps and navigation; first aid, personal hygiene, and field sanitation; and substance abuse prevention. These courses also introduce students to principles of leadership and citizenship.", "u": null, "notes": "concept: NI001517163812", "dep": null}, {"v": "09052", "n": "Army Junior ROTC II", "d": "Army Junior Reserve Officer Training Corps (ROTC) II courses build upon the content of Army Junior ROTC I and include (but are not limited to) ongoing instruction in leadership principles and citizenship; drill and ceremonies; organizational structure; command and staff relationships, functions, and responsibilities; significant military campaigns and leaders; map-reading and orienteering; weapon safety and marksmanship; and survival training.", "u": null, "notes": "concept: NI001517163813", "dep": null}, {"v": "09053", "n": "Army Junior ROTC III", "d": "Army Junior Reserve Officer Training Corps (ROTC) III courses build upon prior Army Junior ROTC courses, giving more emphasis to leadership development. These courses serve to strengthen students' leadership skills (including planning, problem-solving, motivation, and performance appraisal) and management skills (with regard to time, personnel, and other resources) through allowing them to assume leadership duties. Students study topics introduced in earlier years�such as military history, map-reading and orienteering, marksmanship, and drill and ceremonies�at a more advanced level and are also provided with military service opportunities.", "u": null, "notes": "concept: NI001517163814", "dep": null}, {"v": "09054", "n": "Army Junior ROTC IV", "d": "Army Junior Reserve Officer Training Corps (ROTC) IV courses focus on practical leadership by assigning students to command and staff positions in which they present instruction to lower Army Junior ROTC classes and continue to study and review staff functions and actions, staff-commander relationships, and leadership principles. Topics introduced in earlier years may be studied at more advanced levels.", "u": null, "notes": "concept: NI001517163815", "dep": null}, {"v": "09101", "n": "Naval Junior ROTC I", "d": "Naval Junior Reserve Officer Training Corps (ROTC) I courses emphasize citizenship and leadership development, as well as maritime heritage, sea power, and Naval operations and customs. These courses include (but are not limited to) an introduction to the Naval Junior ROTC program, U.S. Navy mission and organization, maritime geography, naval history, basic seamanship, oceanography, and health education.", "u": null, "notes": "concept: NI001517163816", "dep": null}, {"v": "09102", "n": "Naval Junior ROTC II", "d": "Naval Junior Reserve Officer Training Corps (ROTC) II courses build upon the content of Naval Junior ROTC I. These courses include (but are not limited to) leadership principles and discipline, citizenship, naval opportunities and career planning, naval ships and weaponry, seamanship, meteorology and weather, and survival training. Students continue to learn teamwork, naval history, and military principles.", "u": null, "notes": "concept: NI001517163817", "dep": null}, {"v": "09103", "n": "Naval Junior ROTC III", "d": "Naval Junior Reserve Officer Training Corps (ROTC) III courses build upon prior Naval Junior ROTC courses. These courses include (but are not limited to) leadership principles and discipline, military justice, international law and the sea, naval intelligence/strategies and national security, and sciences involved in naval operations, such as electricity, electronics, communications technologies, and so on. Students continue to learn teamwork, naval history, and military principles.", "u": null, "notes": "concept: NI001517163818", "dep": null}, {"v": "09104", "n": "Naval Junior ROTC IV", "d": "Naval Junior Reserve Officer Training Corps (ROTC) IV courses are focused on practical leadership, placing students in positions where they can learn, practice, and understand skills involved in leading others, such as supervision, motivation, evaluation, setting examples, and problem-solving. Application of these skills usually includes military drill and inspections, athletic events, and other school activities. Topics introduced in earlier years may be studied at more advanced levels.", "u": null, "notes": "concept: NI001517163819", "dep": null}, {"v": "09151", "n": "Air Force Junior ROTC I", "d": "Air Force Junior Reserve Officer Training Corps (ROTC) I courses include both aerospace studies and leadership/life skills education. In these courses, leadership/life skills lessons cover the heritage and development of the Air Force, including its structure, operations, customs, and courtesies. Aerospace topics include the development, history, and impact of flight; aircraft and spacecraft; and the environment in which these crafts operate.", "u": null, "notes": "concept: NI001517163820", "dep": null}, {"v": "09152", "n": "Air Force Junior ROTC II", "d": "Air Force Junior Reserve Officer Training Corps (ROTC) II courses include both aerospace studies and leadership/life skills education. In these courses, leadership/life skills lessons cover intercommunication skills, drill, and military ceremonies. Aerospace topics emphasize the science of flight, including factors of aerospace power, aircraft flight, and navigation.", "u": null, "notes": "concept: NI001517163821", "dep": null}, {"v": "09153", "n": "Air Force Junior ROTC III", "d": "Air Force Junior Reserve Officer Training Corps (ROTC) III courses include both aerospace studies and leadership/life skills education. These courses continue to develop students' life and leadership skills and the ways in which they apply to military life. Aerospace topics emphasize space technology and exploration; examine national defense systems; and advance students' knowledge of aviation, propulsion, and navigation.", "u": null, "notes": "concept: NI001517163822", "dep": null}, {"v": "09154", "n": "Air Force Junior ROTC IV", "d": "Air Force Junior Reserve Officer Training Corps (ROTC) IV courses include both aerospace studies and leadership/life skills education. The life skills education portion of these courses concentrates on leadership and management principles and career opportunities, and aerospace topics include advanced aerodynamics and aeronautics. Course content may also cover elements of national power and relationships between the nations of the world.", "u": null, "notes": "concept: NI001517163823", "dep": null}, {"v": "09201", "n": "Marine Corps Junior ROTC I", "d": "Marine Corps Junior Reserve Officer Training Corps (ROTC) I courses introduce the Marine Corps Junior ROTC program, with an emphasis on personal growth and responsibility along with general military subjects. These courses include (but are not limited to) physical training; health education, including hygiene, first aid, nutrition, and substance abuse prevention; and communication skills. In these courses, students are introduced to and study Marine Corps values and code of conduct; drill and ceremony; military uniforms, customs, and courtesies; military history; and the Marine Corps structure and chain of command.", "u": null, "notes": "concept: NI001517163824", "dep": null}, {"v": "10013", "n": "PLTW Computer Science Essentials", "d": "Following Project Lead the Way's suggested curriculum, PLTW Computer Science Essentials (formerly known as PLTW Introduction to Computer Science) courses introduce students to computational thinking concepts, fundamentals, and tools. Students will increase their understanding of programming languages through the use of visual and text-based programming. Projects will include the creation of apps and websites to address real-life topics and problems.", "u": null, "notes": "concept: NI001517163825", "dep": null}, {"v": "10049", "n": "Computer Literacy�Other", "d": "Other Computer Literacy courses.", "u": null, "notes": "concept: NI001517163826", "dep": null}, {"v": "10051", "n": "Information Management", "d": "Information Management courses provide students with the knowledge and skills to develop and implement a plan for an information system that meets the needs of business. Students develop an understanding of information system theory, skills in administering and managing information systems, and the ability to analyze and design information systems.", "u": null, "notes": "concept: NI001517163827", "dep": null}, {"v": "10052", "n": "Database Management and Data Warehousing", "d": "Database Management and Data Warehousing courses provide students with the skills necessary to design databases to meet user needs. Courses typically address how to enter, retrieve, and manipulate data into useful information. More advanced topics may cover implementing interactive applications for common transactions and the utility of mining data.", "u": null, "notes": "concept: NI001517163828", "dep": null}, {"v": "10053", "n": "Database Applications", "d": "Database Application courses provide students with an understanding of database development, modeling, design, and normalization. These courses typically cover such topics as SELECT statements, data definition, manipulation, control languages, records, and tables. In these courses, students may use Oracle WebDB, SQL, PL/SQL, SPSS, and SAS and may prepare for certification.", "u": null, "notes": "concept: NI001517163829", "dep": null}, {"v": "10054", "n": "Data Systems/Processing", "d": "Data Systems/Processing courses introduce students to the uses and operation of computer hardware and software and to the programming languages used in business applications. Students typically use BASIC, COBOL, and/or RPL languages as they write flowcharts or computer programs and may also learn data-processing skills.", "u": null, "notes": "concept: NI001517163830", "dep": null}, {"v": "10055", "n": "Particular Topics in Management Information Systems", "d": "These courses examine particular topics in management information systems other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163831", "dep": null}, {"v": "10097", "n": "Management Information Systems�Independent Study", "d": "Management Information Systems�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to management information systems. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163832", "dep": null}, {"v": "10098", "n": "Management Information Systems�Workplace Experience", "d": "Management Information Systems�Workplace Experience courses provide work experience in fields related to management information systems. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163833", "dep": null}, {"v": "10099", "n": "Management Information Systems�Other", "d": "Other Management Information Systems courses.", "u": null, "notes": "concept: NI001517163834", "dep": null}, {"v": "10101", "n": "Network Technology", "d": "Network Technology courses address the technology involved in the transmission of data between and among computers through data lines, telephone lines, or other transmission media, such as hard wiring, wireless, cable networks, and so on. These courses may emphasize the capabilities of networks, network technology itself, or both. Students typically learn about network capabilities and network technology, including the software, hardware, and peripherals involved in setting up and maintaining a computer network.", "u": null, "notes": "concept: NI001517163835", "dep": null}, {"v": "10014", "n": "PLTW Computer Science A", "d": "Following Project Lead the Way's suggested curriculum to prepare students for the College Board's Advanced Placement Computer Science A exam, PLTW Computer Science A (formerly known as PLTW Computer Science Applications) courses focus on extending students' computational thinking skills through the use of various industry-standard programming and software tools. In these courses, students collaborate to design and produce solutions to real-life problems.", "u": null, "notes": "concept: NI001517163836", "dep": null}, {"v": "10015", "n": "PLTW Computer Science Principles", "d": "Following Project Lead the Way's suggested curriculum to prepare students for the College Board's Advanced Placement Computer Science Principles exam, PLTW Computer Science Principles (formerly known as PLTW Computer Science and Software Engineering) courses are designed to help students develop computational thinking, and introduce students to possible career paths involving computing. These courses help students build programming expertise and familiarity with the Internet using multiple platforms and programming languages. Course content may include application development, visualization of data, cybersecurity, and simulation.", "u": null, "notes": "concept: NI001517163837", "dep": null}, {"v": "10016", "n": "PLTW Cybersecurity", "d": "Following Project Lead the Way's suggested curriculum, PLTW Cybersecurity courses introduce students to the tools and concepts of cybersecurity. In these courses, students are encouraged to understand vulnerabilities in computational resources and to create solutions that allow people to share computing resources while retaining privacy. These courses also introduce students to issues related to ethical computing behavior.", "u": null, "notes": "concept: NI001517163838", "dep": null}, {"v": "10019", "n": "AP Computer Science Principles", "d": "Following the College Board's suggested curriculum designed to parallel college-level computer science principles courses, AP Computer Science Principles courses introduce students to the fundamental ideas of computer science and how to apply computational thinking across multiple disciplines. These courses teach students to apply creative designs and innovative solutions when developing computational artifacts. These courses cover such topics as creative development, data, algorithms and programming, computer systems and networks, and the impact of computing.", "u": null, "notes": "concept: NI001517163839", "dep": null}, {"v": "16054", "n": "Nutrition and Food Preparation", "d": "Nutrition and Food Preparation courses provide students with knowledge and skills related to commercial food preparation and/or production, with a strong emphasis on nutrition, balanced diets, and satisfying special dietary needs. Topics typically include assessing nutrient content, the science of food and nutrition, physiology and utilization of nutrients. Course content may also cover additives, contaminants, food- borne illnesses, and food technology.", "u": null, "notes": "concept: NI001517164135", "dep": null}, {"v": "15153", "n": "Particular Topics in Fire Management", "d": "These courses examine specific topics related to fire management (such as hazardous materials handling), rather than provide a general study of the field.", "u": null, "notes": "concept: NI001517164136", "dep": null}, {"v": "15197", "n": "Fire Management�Independent Study", "d": "Fire Management�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related fire management. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164137", "dep": null}, {"v": "15198", "n": "Fire Management�Workplace Experience", "d": "Fire Management�Workplace Experience courses provide work experience in fields related to fire management. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164138", "dep": null}, {"v": "15199", "n": "Fire Management�Other", "d": "Other Fire Management courses.", "u": null, "notes": "concept: NI001517164139", "dep": null}, {"v": "15249", "n": "Government Service�Other", "d": "Other Government Service courses.", "u": null, "notes": "concept: NI001517164145", "dep": null}, {"v": "15201", "n": "Public Administration", "d": "Public Administration courses provide an overview of the structure, roles, and duties of public governments and associated agencies. These courses explore the foundation and evolution of the public service sector, issues related to the provision of services by governmental bodies, and the missions and constraints of various departments within local and state, and the federal government. In addition, students may explore a particular public administration topic (such as the tax base and structure, the legislative process, selection of public servants, resource management, and so on) in greater detail.", "u": null, "notes": "concept: NI001517164140", "dep": null}, {"v": "15202", "n": "Community Protection", "d": "Community Protection courses provide students with information regarding the personnel and agencies concerned with protection of the home, city, state, and nation. Topics covered typically include civil defense; homeland security; disaster, terrorism, and emergency preparedness; crime prevention; pollution control; fire prevention and control; legal and social systems and principles; and public health.", "u": null, "notes": "concept: NI001517164141", "dep": null}, {"v": "15203", "n": "Public Policy", "d": "Public Policy courses provide students with the opportunity to design, propose, and analyze programs and policies implemented by government agencies. Activities typically include identifying social issues and problems, generating recommendations, using data to quantify the extent of a problem or evaluate its solution, communicating ideas and findings, and understanding decisionmaking processes.", "u": null, "notes": "concept: NI001517164142", "dep": null}, {"v": "15247", "n": "Government Service�Independent Study", "d": "Government Service�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related the provision of government services. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164143", "dep": null}, {"v": "15248", "n": "Government Service�Workplace Experience", "d": "Government Service�Workplace Experience courses provide work experience in fields related to government service. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164144", "dep": null}, {"v": "15995", "n": "Public, Protective, and Government Service�Aide", "d": "Public, Protective, and Government Service�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164146", "dep": null}, {"v": "12998", "n": "Business and Marketing�Workplace Experience", "d": "Business and Marketing�Workplace Experience courses provide students with work experience in fields related to business and marketing. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164147", "dep": null}, {"v": "12999", "n": "Business and Marketing�Other", "d": "Other Business and Marketing courses.", "u": null, "notes": "concept: NI001517164148", "dep": null}, {"v": "13001", "n": "Exploration of Manufacturing Occupations", "d": "Exploration of Manufacturing Occupations courses introduce and expose students to the career opportunities pertaining to the processing and production of goods. Course topics vary and may include (but are not limited to) systems pertinent to the manufacturing process, properties of various raw materials, and the methods used to transform materials into consumer products. Course activities depend upon the careers being explored; course topics may include entrepreneurship, labor laws, economic impact, and customer service.", "u": null, "notes": "concept: NI001517164149", "dep": null}, {"v": "13002", "n": "Manufacturing�Comprehensive", "d": "Manufacturing�Comprehensive courses introduce students to the various methods used to process and transform materials. Processing techniques covered usually include casting, forming, separating, assembling, and finishing. The courses may also include an overview of management techniques in planning, organizing, and controlling various segments of the manufacturing process, including design, automation, engineering, production, and marketing.", "u": null, "notes": "concept: NI001517164150", "dep": null}, {"v": "13003", "n": "Industrial Arts", "d": "Industrial Arts courses expose students to the tools and equipment that they may encounter in manufacturing-related occupations and enable them to develop the skills they need to use these tools in various applications. Course topics typically include (but are not limited to) planning and design, electricity and electronics, materials properties and testing, basic materials processing, and power technology. These courses typically cover general safety and career exploration as well.", "u": null, "notes": "concept: NI001517164151", "dep": null}, {"v": "13004", "n": "Industrial Safety/First Aid", "d": "Industrial Safety/First Aid courses immerse students in the study of safe operating procedures related to various industrial environments, as well as more general training in emergency first aid and CPR. Course topics may include the importance of standard operation procedures, appropriate use of equipment, agencies and regulations related to occupational safety and hazard prevention, and the dangers of particular materials.", "u": null, "notes": "concept: NI001517164152", "dep": null}, {"v": "13052", "n": "Material and Processes", "d": "Material and Processes courses expose students to the tools, equipment, and processes that may be encountered in manufacturing-related occupations. In particular, these courses stress the analysis, testing, and processing of metals, plastics, woods, ceramics, and composite materials.", "u": null, "notes": "concept: NI001517164153", "dep": null}, {"v": "13053", "n": "Metal and Wood Processing/Production", "d": "Metal and Wood Processing/Production courses allow students to study the physical and chemical properties of metals, woods, and composites and to use these materials to construct usable products according to industry standards. These courses enable students to experience the process of translating an idea into a finished product, with instruction in planning, designing, selecting materials, and using tools and machines.", "u": null, "notes": "concept: NI001517164154", "dep": null}, {"v": "13054", "n": "Wood Processing/Production", "d": "Wood Processing/Production courses allow students to study the physical and chemical properties of woods and composites made from woods and to use these materials to construct usable products according to industry standards. These courses enable students to experience the process of translating an idea into a finished product, with instruction in planning, designing, selecting materials, and using tools and machines.", "u": null, "notes": "concept: NI001517164155", "dep": null}, {"v": "15997", "n": "Public, Protective, and Government Service�Independent Study", "d": "Public, Protective, and Government Service�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to public, protective, and government service. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164156", "dep": null}, {"v": "15998", "n": "Public, Protective, and Government Service�Workplace Experience", "d": "Public, Protective, and Government Service�Workplace Experience courses provide students with work experience in a field related to public, protective, and/or government service. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164157", "dep": null}, {"v": "15999", "n": "Public, Protective, and Government Service�Other", "d": "Other Public, Protective, and Government Service courses.", "u": null, "notes": "concept: NI001517164158", "dep": null}, {"v": "16001", "n": "Exploration of Hospitality Careers", "d": "Exploration of Hospitality Careers courses survey a wide array of topics while exposing students to the variety of career opportunities in hospitality fields (such as food service, lodging, tourism, and recreation). These courses serve to introduce students to the general field of hospitality, providing an opportunity to identify a focus for continued study.", "u": null, "notes": "concept: NI001517164159", "dep": null}, {"v": "16055", "n": "Restaurant Management and Operations", "d": "Restaurant Management and Operations courses provide students with knowledge and skills related to commercial and institutional food service establishments, with an emphasis on management. Course topics therefore include guest service and relationships, planning, resource management, and other topics related to managing and operating restaurants.", "u": null, "notes": "concept: NI001517164160", "dep": null}, {"v": "16056", "n": "Culinary Art Specialty", "d": "Culinary Art Specialty courses provide instruction in a particular type of cooking or culinary style. Examples of such specialty fields include baking, creating and decorating wedding cakes, Middle Eastern cuisine, and so on. These courses emphasize skills specific to the type of culinary art being studied.", "u": null, "notes": "concept: NI001517164161", "dep": null}, {"v": "16057", "n": "Particular Topics in Restaurant, Food and Beverage Services", "d": "These courses examine specific topics related to Restaurant, Food, and Beverage Services, such as catering, rather than provide a general study of the industry or of specific topics already described.", "u": null, "notes": "concept: NI001517164162", "dep": null}, {"v": "16097", "n": "Restaurant, Food and Beverage Services�Independent Study", "d": "Restaurant, Food, and Beverage Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the restaurant, food, and beverage services industry. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164163", "dep": null}, {"v": "16098", "n": "Restaurant, Food and Beverage Services�Workplace Experience", "d": "Restaurant, Food, and Beverage Services�Workplace Experience courses provide work experience in fields related to restaurant, food, and beverage services. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164164", "dep": null}, {"v": "16099", "n": "Restaurant, Food and Beverage Services�Other", "d": "Other Restaurant, Food and Beverage Service courses.", "u": null, "notes": "concept: NI001517164165", "dep": null}, {"v": "16101", "n": "Exploration of Lodging Careers", "d": "Exploration of Lodging Careers courses provide an overview of the lodging industry. Topics covered include lodging terminology, the history of lodging, introduction to marketing, and the various careers available in the lodging industry.", "u": null, "notes": "concept: NI001517164166", "dep": null}, {"v": "16102", "n": "Lodging�Comprehensive", "d": "Lodging�Comprehensive courses introduce students to the lodging industry and refine their related knowledge and skills. Topics covered typically include property management, guest psychology and relationships, lodging operations, food and beverage services, and other topics related to support services within the lodging industry.", "u": null, "notes": "concept: NI001517164167", "dep": null}, {"v": "16103", "n": "Institutional Maintenance", "d": "Institutional Maintenance courses present the knowledge and skills required for service work within institutions. Topics covered typically include housekeeping and laundry services, care and cleaning of facilities, and safety and sanitation procedures, in addition to career opportunities, business responsibilities, and other types of ongoing maintenance.", "u": null, "notes": "concept: NI001517164168", "dep": null}, {"v": "16104", "n": "Particular Topics in Lodging", "d": "These courses examine specific topics in lodging such as convention planning or hotel management rather than provide a general study of the industry or of specific topics already described.", "u": null, "notes": "concept: NI001517164169", "dep": null}, {"v": "16147", "n": "Lodging�Independent Study", "d": "Lodging�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the lodging industry. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164170", "dep": null}, {"v": "16148", "n": "Lodging�Workplace Experience", "d": "Lodging�Workplace Experience courses provide work experience in fields related to lodging. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164171", "dep": null}, {"v": "16149", "n": "Lodging�Other", "d": "Other Lodging courses.", "u": null, "notes": "concept: NI001517164172", "dep": null}, {"v": "16151", "n": "Introduction to Travel and Tourism", "d": "Introduction to Travel and Tourism courses provide an overview of the travel and tourism industry. Topics covered in this course may include travel and tourism terminology, the history of travel, introduction to marketing, and the various careers available in travel and tourism.", "u": null, "notes": "concept: NI001517164173", "dep": null}, {"v": "16152", "n": "Travel and Tourism�Comprehensive", "d": "Travel and Tourism�Comprehensive courses provide the knowledge and skills necessary to work in the travel industry such as sales techniques, marketing principles, and entrepreneurial skills. Additional skills learned in these courses typically include travel agency procedures, airline reservation systems, public relations, hotel/motel registration systems and services, and conference and convention planning.", "u": null, "notes": "concept: NI001517164174", "dep": null}, {"v": "16153", "n": "World Travel and Tourism", "d": "World Travel and Tourism courses provide the knowledge and skills necessary to work in the travel industry, with a focus on travel outside of the United States. Topics covered may include geography of the continents; customs, cultures, and tourist destinations in other countries; special documentation needed for international travel; and planning events to client specifications.", "u": null, "notes": "concept: NI001517164175", "dep": null}, {"v": "16154", "n": "Eco-tourism", "d": "Eco-tourism courses provide the knowledge and skills necessary to work in the travel industry, with particular attention paid to conservation and environmental issues surrounding travel and tourism. Topics covered may include recreational opportunities related to on- and off-site attractions and environmental and ecological principles.", "u": null, "notes": "concept: NI001517164176", "dep": null}, {"v": "16155", "n": "Particular Topics in Travel and Tourism", "d": "These courses examine specific topics in travel and tourism such as the airline reservation and ticketing system rather than provide a general study of the industry or of specific topics already described.", "u": null, "notes": "concept: NI001517164177", "dep": null}, {"v": "22051", "n": "Office Aide", "d": "Office Aide courses provide students with the opportunity to work in campus offices, developing skills related to clerical office work. Duties may include typing, filing, record-keeping, receiving visitors, answering the telephone, and duplicating, among others. These courses emphasize appropriate work attitudes, human relations, and proper office procedures.", "u": null, "notes": "concept: NI001517164469", "dep": null}, {"v": "22052", "n": "Guidance Aide", "d": "Guidance Aide courses provide students with the opportunity to work in the campus guidance office. Duties may include typing, filing, record-keeping, assisting students, answering the telephone, and duplicating, among others. Students may also act as guides to new students. These courses emphasize appropriate work attitudes, human relations, and proper office procedures.", "u": null, "notes": "concept: NI001517164470", "dep": null}, {"v": "22053", "n": "Library/AVC Aide", "d": "Library/AVC Aide courses provide students with the opportunity to work in the library or in media and audiovisual centers. Duties may include collecting, distributing, and categorizing materials; operating audiovisual equipment; assisting students and teachers; and performing clerical duties. Students typically gain experience in library science and/or media and audiovisual technology.", "u": null, "notes": "concept: NI001517164471", "dep": null}, {"v": "22054", "n": "Tutoring Practicum", "d": "Tutoring Practicum courses provide students with the opportunity to offer tutorial assistance to their peers or to younger students. After an initial training period during which students learn how to work with other students and how to make use of the available resources (e.g., staff, written material, audiovisual aids, and so on), students engage in tutoring and assisting others who need or request help.", "u": null, "notes": "concept: NI001517164472", "dep": null}, {"v": "22101", "n": "Leadership", "d": "Leadership courses are designed to strengthen students' personal and group leadership skills. Typically intended for students involved in extracurricular activities (especially as officers of organizations or student governing bodies), these courses may cover such topics as public speaking, effective communication, human relations, parliamentary law and procedures, organization and management, and group dynamics.", "u": null, "notes": "concept: NI001517164473", "dep": null}, {"v": "22102", "n": "School Orientation", "d": "School Orientation courses provide students with an introduction to the culture of their school so that they understand staff expectations and the school's structure and conventions. These courses may vary widely according to the philosophy, aims, and methods of each school.", "u": null, "notes": "concept: NI001517164474", "dep": null}, {"v": "22103", "n": "School Governance", "d": "School Governance courses convene students as an entire student body to discuss common concerns, organize groups for action, make decisions, and solve school-related problems. Because of the nature of these courses, they are typically offered at private, alternative, or experimental schools.", "u": null, "notes": "concept: NI001517164475", "dep": null}, {"v": "22104", "n": "Community Service", "d": "Community Service courses provide students with the opportunity to volunteer their time, energy, and talents to serve a community project or organization. These courses are usually (but not always) conducted with a seminar component, so that students can use their volunteer experiences to learn how to solve problems, make decisions, and communicate effectively.", "u": null, "notes": "concept: NI001517164476", "dep": null}, {"v": "22105", "n": "Values Clarification", "d": "Values Clarification courses enable students to explore individual and societal actions and implications in order to help them develop personal values and make decisions about their lives. Examples of discussion topics include philosophy and religion, world resource allocation, genetic engineering, environmental issues, and death-related issues (euthanasia, suicide, and abortion).", "u": null, "notes": "concept: NI001517164477", "dep": null}, {"v": "22110", "n": "AP Seminar", "d": "Designed by the College Board to parallel college-level courses in critical thinking and communications, AP Seminar courses provide students with the opportunity to explore complex real world issues through cross-curricular lenses. Course topics vary and may include local, civic, or global issues and interdisciplinary subject areas. Courses typically emphasize research, communication, and critical-thinking skills to explore the issues addressed. Students may also examine source materials such as articles and other texts; speeches and personal accounts; and relevant artistic and literary works.", "u": null, "notes": "concept: NI001517164478", "dep": null}, {"v": "05251", "n": "Digital Imaging", "d": "Digital Imaging courses explore the creative and conceptual aspects of designing and producing digital imagery, graphics, and photography. Students study the techniques, genres, and styles from multiple mediums and forms. Topics may include aesthetic meaning, appreciation and analysis; composing, capturing, processing, and programming of imagery and graphical information; their transmission, distribution, and marketing; and contextual, cultural and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164479", "dep": null}, {"v": "05252", "n": "Interactive Design", "d": "Interactive Design courses explore the creative, technical, and conceptual aspects of designing and producing interactive media arts experiences, products, and services, including reactive (sensory-based devices) and interactive technologies, 3D game mechanics, interface design, mobile device applications, social media-based and web multimedia, physical spaces, augmented reality, and/or virtual reality. Topics may include aesthetic meaning; artistic, design and technical methods and practices; story and audience engagement; analysis and media literacy; construction, development, processing, modeling, simulation, and programming of interactive experiences; their transmission, distribution, placement and marketing; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164480", "dep": null}, {"v": "22112", "n": "AP Research", "d": "Designed by the College Board to parallel college-level courses in independent research, AP Research courses provide students with the opportunity to conduct an in-depth, mentored research project. Course topics include research methods, ethical research practicies, and accessing, analyzing, and synthesizing information to address a research question. Courses culminate with an academic thesis paper and an oral defense of the research design, approach, and findings.", "u": null, "notes": "concept: NI001517164481", "dep": null}, {"v": "02139", "n": "IB Mathematics: Applications and Interpretation", "d": "IB Mathematics: Applications and Interpretation courses prepare students to take the International Baccalaureate Mathematics: Applications and Interpretation exams. Intended to provide students with an understanding of the role of mathematics in an increasing technological world, these courses focus on mathematical concepts used as applications and in mathematical modeling. Course topics include numbers and algebra, functions, geometry and trigonometry, statistics and probability, and calculus.", "u": null, "notes": "concept: NI001517164482", "dep": null}, {"v": "02140", "n": "IB Mathematics: Analysis and Approaches", "d": "IB Mathematics: Analysis and Approaches courses prepare students to take the International Baccalaureate Mathematics: Analysis and Approaches exams. These courses prepare students to use analytical concepts within mathematics to solve abstract problems in a variety of contexts. These concepts are applied to course topics such as numbers and algebra, functions, geometry and trigonometry, statistics and probability, and calculus.", "u": null, "notes": "concept: NI001517164483", "dep": null}, {"v": "03070", "n": "PLTW Biomedical Innovation", "d": "Following Project Lead the Way's suggested curriculum, PLTW Biomedical Innovation courses help students apply their knowledge and skills to design innovative solutions related to biomedical challenges. These courses address topics ranging from public health and biomedical engineering to clinical medicine and physiology. Theses courses may also provide students with the opportunity to work with a mentor or advisor from a university, medical facility, or research institution. Students may design and complete an independent project as part of the course.", "u": null, "notes": "concept: NI001517164484", "dep": null}, {"v": "04067", "n": "AP World History: Modern", "d": "Following the College Board's suggested curriculum designed to parallel college-level World History courses, AP World History: Modern courses examine world history from 1200 CE to the present with the aim of helping students make connections of historical evolution across times and places. These courses highlight the interaction between humans and the environment; development and interaction of cultures; state-building, expansion and conflict; creation, expansion and interaction of economic systems; development and transformation of social structures; and technology and innovation.", "u": null, "notes": "concept: NI001517164485", "dep": null}, {"v": "05013", "n": "Dance for Musical Theater", "d": "Dance for Musical Theater courses teach students how dance can be used in musical theater. Students learn the history of musical theater and types of dance that are typically used in musical theater including tap, jazz, ballet, and contemporary dance forms.", "u": null, "notes": "concept: NI001517164486", "dep": null}, {"v": "05014", "n": "Ballet", "d": "Ballet courses provide students with ongoing training in ballet and emphasize improving students' technique.", "u": null, "notes": "concept: NI001517164487", "dep": null}, {"v": "05015", "n": "Jazz Dance", "d": "Jazz Dance courses provide students with ongoing training in jazz dance and emphasize improving students' technique.", "u": null, "notes": "concept: NI001517164488", "dep": null}, {"v": "05016", "n": "Modern Dance", "d": "Modern Dance courses provide students with ongoing training in modern dance and emphasize improving students' technique.", "u": null, "notes": "concept: NI001517164489", "dep": null}, {"v": "05017", "n": "Hip Hop", "d": "Hip Hop courses provide students with ongoing training in hip hop and emphasize improving students' technique.", "u": null, "notes": "concept: NI001517164490", "dep": null}, {"v": "05018", "n": "Tap Dance", "d": "Tap Dance courses provide students with ongoing training in tap dance and emphasize improving students' technique.", "u": null, "notes": "concept: NI001517164491", "dep": null}, {"v": "05195", "n": "Fundamentals of Design", "d": "Fundamentals of Design courses provide an introduction to and help students respond to the function of fundamental processes of artistic expression in two- and three-dimensional designs. Students apply the concepts and approaches in the symbolic aspects of art and design to two- and three-dimensional problems so that they demonstrate a range of abilities and versatility with technique, problem solving, and ideation. Students study, analyze, and respond to the function of fundamental processes of artistic expression in their work. Students learn to respond to their work and the work of others.", "u": null, "notes": "concept: NI001517164492", "dep": null}, {"v": "05250", "n": "Media Arts�Comprehensive", "d": "Media Arts�Comprehensive courses introduce students to the creative and conceptual aspects of designing media arts experiences and products, including techniques, genres and styles from various mediums and forms, such as moving image, sound, interactive, spatial and/or interactive design. Topics may include aesthetic meaning, appreciation and analysis; composing, capturing, processing and programming of media arts products, experiences and communications; transmission, distribution and marketing;and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164493", "dep": null}, {"v": "05253", "n": "Interactive Game Design", "d": "Interactive Game Design courses explore the creative, technical, and conceptual aspects of designing and producing interactive game experiences and products, including reactive (sensory-based devices) and interactive technologies, 3D game mechanics, interface design, games for mobile device applications, social media and web multimedia, and/or augmented and virtual reality games. Topics may include aesthetic meaning; artistic, design and technical methods and practices; game construction and development, game theory and dynamics; analysis and media literacy; construction, development, processing, modeling, and programming of game-based experiences; their transmission, distribution, placement and marketing; and contextual, cultural and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164494", "dep": null}, {"v": "05254", "n": "Web Design", "d": "Web Design courses explore the creative and conceptual aspects of designing and developing interactive, multimedia web sites that emphaisze the principles of graphic design, interactivity, and usability. Students learn about a variety of visual, navigational, and structural approaches to navigation systems, visual hierarchy, basic animations, image preparation and file transferring protocols. Topics may include conceptual development and structure, interactivity, and design aesthetics; appreciation and analysis development, construction, and programming of virtual, multimedia, and interactive experiences; their applications in Internet communications; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164495", "dep": null}, {"v": "05255", "n": "Moving Image", "d": "Moving Image courses explore the creative and conceptual aspects of designing and producing moving images for cinematic, film/video, animation, and multimedia presentations, such as documentaries, music videos, and performance media. Topics may include aesthetic meaning, appreciation and analysis of moving imagery; all processes of development including pre-production planning and organization, production and post-production methods, tools, and processes; moving image presentation; transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164496", "dep": null}, {"v": "05298", "n": "Media Arts�Workplace Experience", "d": "Media Arts�Workplace Experience courses provide students with work experience in a field related to media arts. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164506", "dep": null}, {"v": "05256", "n": "Moving Image � Animation", "d": "Moving Image�Animation courses explore the creative and conceptual aspects of designing and producing animated images for storytelling and multimedia presentations including dramatic narratives; artistic and experimental presentations and installations; and ambient, interactive, immersive and performance media. Topics may include motion graphics; compositing and visual effects; 2D and 3D animation; timing and spacing; aspect ratio; video editing; animation physics and expressions; pre- and post-production methods, tools and processes; animation presentation, transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164497", "dep": null}, {"v": "05257", "n": "Digital Sound Design", "d": "Digital Sound Design courses explore the creative and conceptual aspects of designing and producing sound for a variety of multimedia and popular musical forms, including artistic and experimental presentations and/or installations; soundtracks for moving image; and interactive, immersive and performance media. Topics may include aesthetic meaning, appreciation and analysis of sound and music; processes of development; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164498", "dep": null}, {"v": "05258", "n": "Virtual Design", "d": "Virtual Desgin courses explore the creative and conceptual aspects of designing and producing simulative, virtual, and 3D media arts experiences, products, and services, including environments, structures, objects, architecture and ecologies, virtual, and augmented reality. Topics may include aesthetic meaning, appreciation and analysis; construction, development, processing, modeling, simulation and programming of experiences, structures, architecture and/or environments; presentation, transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164499", "dep": null}, {"v": "05259", "n": "Media for Performance", "d": "Media for Performance courses explore the creative and conceptual aspects of designing and producing media for performing, informational, and entertainment arts presentations and experiences including dance, music, theatre, opera, performance art, political, and sports and entertainment events. Topics may include aesthetic meaning, appreciation and analysis of live performance and integrated media; processes of development; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164500", "dep": null}, {"v": "05260", "n": "Multimedia Design", "d": "Multimedia Design courses explore the creative and conceptual aspects of designing and producing media arts experiences, products, and services that combine imagery, text, sound, motion, interactivity and/or virtual media into a unified presentation. Topics may include aesthetic meaning, appreciation and analysis; composition, development, processing and programming of combined physical, interactive, and virtual experiences and environments; presentation, transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.", "u": null, "notes": "concept: NI001517164501", "dep": null}, {"v": "05261", "n": "Intermedia Design", "d": "Intermedia Design courses explore the creative and conceptual aspects of designing and producing interdisciplinary media arts, intermedia and/or transmedia, that merges media in diverse combinations and emerging hybrids. Topics may include aesthetic meaning, appreciation and analysis; construction, development, processing, modeling, simulation, and programming of blended physical, interactive, multimedia, and virtual experiences and/or environments across arts forms, platforms, media, and technologies; presentation, transmission, distribution and marketing; and contextual, cultural, and historical aspects/considerations.", "u": null, "notes": "concept: NI001517164502", "dep": null}, {"v": "05262", "n": "Media Arts Theory", "d": "Media Arts Theory courses instruct students on the conceptual, social, and philosophical aspects of the variety, purposes, and nature of media arts. Topics may include aesthetic meaning; appreciation and analysis of the range of media art experiences, styles, genres, and forms; limited experience in its production tools, methods, and processes; and the role of media technologies in society.", "u": null, "notes": "concept: NI001517164503", "dep": null}, {"v": "05263", "n": "Media Literacy", "d": "Media Literacy courses provide a history of the media, including advertising and persuasive techniques, and study propaganda. Students learn how contemporary and historical images are used to make art, sell products, motivate populations, and alter opinions. Topics may include debates surrounding television, the internet, and other sources for media, and exploring alternatives to the mainstream media.", "u": null, "notes": "concept: NI001517164504", "dep": null}, {"v": "05297", "n": "Media Arts�Independent Study", "d": "Media Arts�Independent Study courses, often conducted with instructors or professional artists as mentors, enable students to explore a particular art form or topic. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular form or style, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164505", "dep": null}, {"v": "24163", "n": "IB Language B�Italian", "d": "IB Language B�Italian courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162875", "dep": null}, {"v": "24164", "n": "AP Italian Language and Culture", "d": "Designed by the College Board to parallel third-year college-level courses in Italian language, AP Italian Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in Italian, both orally and in writing. These courses also help students understand and interpret written and spoken Italian. In addition, students explore the culture of Italian-speaking people in historical and contemporary contexts.", "u": null, "notes": "concept: NI001517162876", "dep": null}, {"v": "24166", "n": "IB Language B (Italian), Middle Years Program", "d": "Language B (Italian), Middle Years Program courses enable students to gain competence in modern Italian and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162877", "dep": null}, {"v": "24167", "n": "IB Language A: Language and Literature�Italian", "d": "IB Language A: Language and Literature�Italian courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Italian in an academic context.", "u": null, "notes": "concept: NI001517162878", "dep": null}, {"v": "24168", "n": "IB Language Ab Initio�Italian", "d": "IB Language Ab Initio�Italian courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517162879", "dep": null}, {"v": "24199", "n": "Italian�Other", "d": "Other Italian courses", "u": null, "notes": "concept: NI001517162880", "dep": null}, {"v": "24200", "n": "Portuguese for Young Learners (prior-to-secondary)", "d": "Portuguese for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Portuguese and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Portuguese-speaking cultures.", "u": null, "notes": "concept: NI001517162881", "dep": null}, {"v": "24201", "n": "Portuguese Immersion (prior-to-secondary)", "d": "Portuguese Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Portuguese and grade-specific content using Portuguese as the language of instruction. Portuguese Immersion courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Portuguese-speaking cultures.", "u": null, "notes": "concept: NI001517162882", "dep": null}, {"v": "24202", "n": "Portuguese I", "d": "Designed to introduce students to Portuguese language and culture, Portuguese I courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Portuguese-speaking cultures.", "u": null, "notes": "concept: NI001517162883", "dep": null}, {"v": "24203", "n": "Portuguese II", "d": "Portuguese II courses build upon skills developed in Portuguese I, preparing students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Portuguese II courses introduce the relationships among the products, practices, and perspectives of Portuguese-speaking cultures.", "u": null, "notes": "concept: NI001517162884", "dep": null}, {"v": "24204", "n": "Portuguese III", "d": "Portuguese III courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Portuguese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162885", "dep": null}, {"v": "24205", "n": "Portuguese IV", "d": "Portuguese IV courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Portuguese IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Portuguese-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162886", "dep": null}, {"v": "24208", "n": "Portuguese Field Experience", "d": "Portuguese Field Experience courses place students in environments in which they interact with native Portuguese speakers, typically in settings where Portuguese is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162887", "dep": null}, {"v": "24256", "n": "German V", "d": "German V courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. German V courses promote students' understanding of the relationships among the products, practices, and perspectives of German-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162888", "dep": null}, {"v": "24254", "n": "German III", "d": "German III courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of German-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162903", "dep": null}, {"v": "24257", "n": "German for Native Speakers", "d": "German for Native Speakers courses prepare native and heritage speakers to communicate in German in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. German for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the German-speaking world.", "u": null, "notes": "concept: NI001517162889", "dep": null}, {"v": "24258", "n": "German Field Experience", "d": "German Field Experience courses place students in environments in which they interact with native German speakers, typically in settings where German is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162890", "dep": null}, {"v": "24209", "n": "Portuguese Conversation and Culture", "d": "Portuguese Conversation and Culture courses provide students with an introduction to the Portuguese language and the culture(s) of Portuguese-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162891", "dep": null}, {"v": "24210", "n": "Portuguese Literature", "d": "Portuguese Literature courses prepare students to communicate authentically in Portuguese by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Portuguese. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Portuguese cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162892", "dep": null}, {"v": "24211", "n": "Particular Topics in Portuguese", "d": "Particular Topics in Portuguese courses examine particular topics focused on Portuguese language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162893", "dep": null}, {"v": "24212", "n": "IB Language A: Literature�Portuguese", "d": "IB Language A: Literature�Portuguese courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Portuguese in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162894", "dep": null}, {"v": "24213", "n": "IB Language B�Portuguese", "d": "IB Language B�Portuguese courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162895", "dep": null}, {"v": "24216", "n": "IB Language B (Portuguese), Middle Years Program", "d": "International Baccalaureate (IB) Language B (Portuguese), Middle Years Program courses enable students to gain competence in modern Portuguese and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162896", "dep": null}, {"v": "24217", "n": "IB Language A: Language and Literature�Portuguese", "d": "IB Language A: Language and Literature�Portuguese courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Portuguese in an academic context.", "u": null, "notes": "concept: NI001517162897", "dep": null}, {"v": "24249", "n": "Portuguese�Other", "d": "Other Portuguese courses", "u": null, "notes": "concept: NI001517162898", "dep": null}, {"v": "24250", "n": "German for Young Learners (prior-to-secondary)", "d": "German for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in German and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of German-speaking cultures.", "u": null, "notes": "concept: NI001517162899", "dep": null}, {"v": "24251", "n": "German Immersion (prior-to-secondary)", "d": "German Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in German and grade-specific content using German as the language of instruction. German Immersion courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of German-speaking cultures.", "u": null, "notes": "concept: NI001517162900", "dep": null}, {"v": "24252", "n": "German I", "d": "Designed to introduce students to German language and culture, German I courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of German-speaking cultures.", "u": null, "notes": "concept: NI001517162901", "dep": null}, {"v": "24253", "n": "German II", "d": "German II courses build upon skills developed in German I, preparing students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. German II courses introduce the relationships among the products, practices, and perspectives of German-speaking cultures.", "u": null, "notes": "concept: NI001517162902", "dep": null}, {"v": "24255", "n": "German IV", "d": "German IV courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. German IV courses promote students' understanding of the relationships among the products, practices, and perspectives of German-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162904", "dep": null}, {"v": "24259", "n": "German Conversation and Culture", "d": "German Conversation and Culture courses provide students with an introduction to the German language and the culture(s) of German-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162905", "dep": null}, {"v": "24306", "n": "Greek V", "d": "Greek V courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Greek V courses promote students' understanding of the relationships among the products, practices, and perspectives of Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162906", "dep": null}, {"v": "24307", "n": "Greek for Native Speakers", "d": "Greek for Native Speakers courses prepare native and heritage speakers to communicate in Greek in all modes. These courses reinforce and expand students' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Greek for Native Speakers courses advance students' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Greek-speaking world.", "u": null, "notes": "concept: NI001517162907", "dep": null}, {"v": "24260", "n": "German Literature", "d": "German Literature courses prepare students to communicate authentically in German by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in German. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of German cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162908", "dep": null}, {"v": "24261", "n": "Particular Topics in German", "d": "Particular Topics in German courses examine particular topics focused on German language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162909", "dep": null}, {"v": "24262", "n": "IB Language A: Literature�German", "d": "IB Language A: Literature�German courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using German in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162910", "dep": null}, {"v": "24263", "n": "IB Language B�German", "d": "IB Language B�German courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517162911", "dep": null}, {"v": "24264", "n": "AP German Language and Culture", "d": "Designed by the College Board to parallel third-year college-level courses in German language, AP German Language and Culture courses build upon prior knowledge and develop students' ability to express ideas, exchange opinions, and present information in German, both orally and in writing. These courses also help students understand and interpret written and spoken German. In addition, students explore the culture of German-speaking people in historical and contemporary contexts.", "u": null, "notes": "concept: NI001517162912", "dep": null}, {"v": "24266", "n": "IB Language B (German), Middle Years Program", "d": "International Baccalaureate (IB) Language B (German), Middle Years Program courses enable students to gain competence in modern German and encourage respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162913", "dep": null}, {"v": "01030", "n": "Language Arts (grade 2)", "d": "Language Arts (grade 2) courses include the four aspects of language use: reading, writing, speaking, and listening. These courses may build students' skills in independent reading and writing by increasing reading and writing fluency, vocabulary, and recognition of word and language patterns. They may also introduce or reinforce the rules of grammar. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163179", "dep": null}, {"v": "01007", "n": "IB Language A: Literature�English", "d": "IB Language A: Literature�English courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using English in an academic context.", "u": null, "notes": "concept: NI001517163180", "dep": null}, {"v": "01008", "n": "English as a Second Language", "d": "English as a Second Language (ESL) courses are designed for the acquisition and rapid mastery of the English language, focusing on reading, writing, speaking, and listening skills. ESL courses usually begin with extensive listening and speaking practice, building on auditory and oral skills, and then move on to reading and writing. These courses provide an explanation of basic structures of the English language, enabling students to progress from an elementary understanding of English words and verb tenses to a more comprehensive grasp of various formal and informal styles and then to advance to \"regular\" English courses. ESL classes may also include an orientation to the customs and culture of the diverse population in the United States.", "u": null, "notes": "concept: NI001517163181", "dep": null}, {"v": "01009", "n": "Language Arts Laboratory", "d": "Language Arts Laboratory courses provide instruction in basic language skills, integrating reading, writing, speaking, and listening, while placing great emphasis on the progress of individual students. Course content depends upon students' abilities and may include vocabulary building, improving spelling and grammar, developing writing and composition skills, reading silently or aloud, and improving listening and comprehension abilities.", "u": null, "notes": "concept: NI001517163182", "dep": null}, {"v": "01031", "n": "Language Arts (grade 3)", "d": "Language Arts (grade 3) courses include the four aspects of language use: reading, writing, speaking, and listening. These courses may emphasize independent reading and writing in a variety of assignments. Some emphasis may also be placed on presentation or oral communication skills. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163183", "dep": null}, {"v": "01032", "n": "Language Arts (grade 4)", "d": "Language Arts (grade 4) courses include the four aspects of language use: reading, writing, speaking, and listening. These courses may emphasize independent reading and writing in a variety of assignments and require students to respond to different material in different ways. Grammar and usage of the English language may also be emphasized. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163184", "dep": null}, {"v": "01033", "n": "Language Arts (grade 5)", "d": "Language Arts (grade 5) courses include the four aspects of language use: reading, writing, speaking, and listening. These courses may extend students' skills in composition, writing for particular purposes or audiences, distinguishing meaning and literary functions in texts, and fluency in reading. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163185", "dep": null}, {"v": "01059", "n": "Biblical Literature", "d": "Biblical Literature courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills), focusing on the books of the Bible. Students may compare techniques, styles, and themes of the various books; examine the Bible's influence on secular literature; and may study historical events of Biblical times. Oral discussion is an integral part of these courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163186", "dep": null}, {"v": "01060", "n": "Literature of an Author", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills), focusing on a particular author and his or her work. Students determine the underlying assumptions and values within the selected works; compare techniques, styles, and themes of the author; and reflect upon the time period in which the author lived. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163187", "dep": null}, {"v": "01061", "n": "Literature of a Genre", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills), focusing on one or several genres, such as poetry, essay, biography, short story, drama, film, and so on. Students determine the underlying assumptions and values within the selected works and also examine the structure, techniques, and intentions of the genre being studied. Oral discussion is an integral part of these genre-oriented courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163188", "dep": null}, {"v": "01034", "n": "Language Arts (grade 6)", "d": "Language Arts (grade 6) courses build upon students' prior knowledge of grammar, vocabulary, word usage, and the mechanics of writing, and include the four aspects of language use: reading, writing, speaking, and listening. These courses may emphasize the use of language for different effects, in different contexts, and for different purposes. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163189", "dep": null}, {"v": "01035", "n": "Language Arts (grade 7)", "d": "Language Arts (grade 7) courses build upon students' prior knowledge of grammar, vocabulary, word usage, and the mechanics of writing, and include the four aspects of language use: reading, writing, speaking, and listening. Beyond emphasizing different uses for language, these courses may also include using language (particularly written text) to construct meaning and connections. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163190", "dep": null}, {"v": "01036", "n": "Language Arts (grade 8)", "d": "Language Arts (grade 8) courses build upon students' prior knowledge of grammar, vocabulary, word usage, and the mechanics of writing, and include the four aspects of language use: reading, writing, speaking, and listening. Typically, these courses use various genres of literature to improve reading skills, and they link writing exercises for different purposes to those reading selections. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163191", "dep": null}, {"v": "01037", "n": "Language Arts�General", "d": "Language Arts�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Language Arts, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163192", "dep": null}, {"v": "01038", "n": "Reading (early childhood education)", "d": "Reading (early childhood education) courses develop students' readiness for language arts, particularly focusing on reading skills. Courses may include activities related to phonics, phonemic awareness, and vocabulary. Content is age-appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163193", "dep": null}, {"v": "01039", "n": "Reading (pre-kindergarten)", "d": "Reading (pre-kindergarten) courses develop students' readiness for language arts, particularly focusing on reading skills. Courses may include activities related to phonics, phonemic awareness, and vocabulary. Content is age-appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163194", "dep": null}, {"v": "01040", "n": "Reading (kindergarten)", "d": "Reading (kindergarten) courses engage students in activities to develop their reading skills. Course content may emphasize storytelling or reading aloud and evoking a written, oral, or pictorial response. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163195", "dep": null}, {"v": "01041", "n": "Reading (grade 1)", "d": "Reading (grade 1) courses focus on reading skills and may emphasize recognition of and response to various types of text; extension of vocabulary; and the connection of language to the expression of ideas. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163196", "dep": null}, {"v": "01042", "n": "Reading (grade 2)", "d": "Reading (grade 2) courses focus on reading skills and may build students' skills in independent reading by increasing reading fluency, vocabulary, and recognition of word and language patterns. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163197", "dep": null}, {"v": "01054", "n": "American Literature", "d": "American Literature courses focus upon commonly known American authors and their work. Students improve their critical-thinking skills as they determine the underlying assumptions and values within the selected works and as they understand how the literature reflects the society of the time. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163198", "dep": null}, {"v": "01055", "n": "American Literature/History", "d": "American Literature/History courses integrate the study of American literature with an overview of U.S. history. These courses may also include other aspects of American culture, such as art or music. A two-year sequence or two-period per day class may be required to cover the same objectives as would be covered separately in U.S. History Overview and American Literature.", "u": null, "notes": "concept: NI001517163199", "dep": null}, {"v": "01056", "n": "British Literature", "d": "British Literature courses may provide a survey of British literature or may focus on a selected timeframe of England's history. Students improve their critical-thinking skills as they determine the underlying assumptions and values within the selected works and as they understand how the literature reflects the society of the time. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163200", "dep": null}, {"v": "01057", "n": "British Literature/History", "d": "British Literature/History courses integrate the study of British literature with an overview of the history of England. These courses may also include other aspects of British culture, such as art or music. A two-year sequence or two-period per day class may be required to cover the same objectives as would be covered separately in English History Overview and British Literature.", "u": null, "notes": "concept: NI001517163201", "dep": null}, {"v": "01058", "n": "World Literature", "d": "World Literature courses use representative literature selections from ancient and/or modern times from countries around the world. Students improve their critical-thinking skills as they comprehend the diversity of literary traditions and the influences of those traditions. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163202", "dep": null}, {"v": "01062", "n": "Literature of a Period", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills), focusing on the literature written during or reflecting a particular time period (such as the French Revolution, the 1960s, or the 20th century). Students determine the underlying assumptions and values within the selected works, reflect upon the influence of societal events and social attitudes, and compare the points of view of various authors. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163203", "dep": null}, {"v": "01063", "n": "Literature of a Place", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills), focusing on a particular geographic region. Students determine the underlying assumptions and values within the selected works; study how the literature reflects the land, society, and history of the region; and may study the influence of this literature on others. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163204", "dep": null}, {"v": "01064", "n": "Literature of a People", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills) but use literature written by authors who share a particular characteristic such as religion, culture, or gender. Students determine the underlying assumptions and values within the selected works, reflect upon the influence of a common characteristic, and compare the points of view of various authors. Oral discussion is an integral part of literature courses, and written compositions are often required.", "u": null, "notes": "concept: NI001517163205", "dep": null}, {"v": "01065", "n": "Literature of a Theme", "d": "These courses have the same aim as general literature courses (to improve students' language arts and critical-thinking skills) but use selected literature to explore a particular theme as expressed from several points of view. Such themes might include The American Dream, Society and Self, Exploration, War and Peace, and the like.", "u": null, "notes": "concept: NI001517163206", "dep": null}, {"v": "01066", "n": "Strategic Reading", "d": "Strategic Reading courses are intended to improve a student's vocabulary, critical-thinking and analysis skills, or reading rate and comprehension level. Although these courses typically emphasize works of fiction, they may also include works of nonfiction (including textbooks). Strategic Reading courses often have a time-management focus, offering strategies for note-taking or for understanding and evaluating the important points of a text.", "u": null, "notes": "concept: NI001517163207", "dep": null}, {"v": "01067", "n": "Assisted Reading", "d": "Assisted Reading courses offer students the opportunity to focus on their reading skills. Assistance is targeted to students' particular weaknesses and is designed to bring students' reading comprehension up to the desired level or to develop strategies to read more efficiently.", "u": null, "notes": "concept: NI001517163208", "dep": null}, {"v": "01068", "n": "Corrective Reading", "d": "Corrective Reading courses offer diagnostic and remedial activities designed to correct reading difficulties and habits that interfere with students' progress in developing reading skills and understandings. Activities are chosen to increase or improve students' reading comprehension, reading technique, and general literacy skills.", "u": null, "notes": "concept: NI001517163209", "dep": null}, {"v": "01069", "n": "Mythology", "d": "Mythology courses introduce students to the origins and meaning of myths, including how cultures use myths to explain natural or social phenomenon. Students will explore the major themes, stories, characters, and archetypes present in the mythologies of several different cultures.", "u": null, "notes": "concept: NI001517163210", "dep": null}, {"v": "01097", "n": "Literature�Independent Study", "d": "Courses in Literature�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to literature. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163211", "dep": null}, {"v": "01105", "n": "Research/Technical Writing", "d": "Research/Technical Writing classes prepare students to write research papers and/or technical reports. These classes emphasize researching (primary and secondary sources), organizing (material, thoughts, and arguments), and writing in a persuasive or technical style.", "u": null, "notes": "concept: NI001517163212", "dep": null}, {"v": "01136", "n": "Writing (grade 6)", "d": "Writing (grade 6) courses build upon students' prior knowledge and skill in writing and may emphasize the use of language for different effects, in different contexts, and for different purposes. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163213", "dep": null}, {"v": "01137", "n": "Writing (grade 7)", "d": "Writing (grade 7) courses build upon students' prior knowledge and skill in writing and may emphasize the use of language for different effects and to construct meaning and connections. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163214", "dep": null}, {"v": "01138", "n": "Writing (grade 8)", "d": "Writing (grade 8) courses build upon students' prior knowledge and skill in writing. Typically, these courses use writing exercises to expand students' understanding of the different purposes of written communication. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163215", "dep": null}, {"v": "01139", "n": "Writing�General", "d": "Writing�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Writing, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163216", "dep": null}, {"v": "01147", "n": "Composition�Independent Study", "d": "Composition�Independent study, often conducted with instructors as mentors, allow students to explore particular topics within the field of language arts (emphasizing composition). Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163217", "dep": null}, {"v": "01148", "n": "Composition�Workplace Experience", "d": "Composition�Workplace Experience courses provide work experience in a field related to English composition. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163218", "dep": null}, {"v": "01128", "n": "Writing (early childhood education)", "d": "Writing (early childhood education) courses develop students' readiness for language arts, particularly focusing on writing. Content is age appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163219", "dep": null}, {"v": "01129", "n": "Writing (pre-kindergarten)", "d": "Writing (pre-kindergarten) courses develop students' readiness for language arts, particularly focusing on writing. Content is age appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163220", "dep": null}, {"v": "04305", "n": "Social Studies", "d": "Social Studies courses enable students to study a group of related subjects addressing the elements and structures of human society that may include economics, geography, history, citizenship, and other social studies-related disciplines.", "u": null, "notes": "concept: NI001517163529", "dep": null}, {"v": "04306", "n": "Philosophy", "d": "Philosophy courses introduce students to the discipline of philosophy as a way to analyze the principles underlying conduct, thought, knowledge, and the nature of the universe. Course content typically includes examination of the major philosophers and their writings.", "u": null, "notes": "concept: NI001517163530", "dep": null}, {"v": "04307", "n": "Particular Topics in Philosophy", "d": "These courses examine a particular topic in philosophy, such as aesthetic judgment, ethics, cosmology, or the philosophy of knowledge, rather than providing a more general overview of the subject.", "u": null, "notes": "concept: NI001517163531", "dep": null}, {"v": "04308", "n": "Modern Intellectual History", "d": "Modern Intellectual History courses provide a historical overview of modern intellectual movements, generally drawing from different disciplines such as political science, economics, and philosophy.", "u": null, "notes": "concept: NI001517163532", "dep": null}, {"v": "04309", "n": "IB Philosophy", "d": "IB Philosophy courses prepare students to take the International Baccalaureate Philosophy exams. These courses challenge students to reflect upon and question the bases of knowledge and experience, to develop critical and systematic thinking, and to carefully analyze and formulate rational arguments. Students closely examine conceptual themes and philosophical texts, and also undertake philosophical analysis of a non-philosophical stimulus, such as a painting or poem.", "u": null, "notes": "concept: NI001517163533", "dep": null}, {"v": "04431", "n": "Social Studies (grade 1)", "d": "Social Studies (grade 1) courses develop foundational skills in the social studies disciplines: history, geography, civics and government, and economics. These disciplines are often taught together and organized around a theme. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163534", "dep": null}, {"v": "05001", "n": "Dance Technique", "d": "Dance Technique courses provide students with experience in one or more dance forms (e.g., modern, jazz, ballet, and tap). Initial classes are usually introductory in nature, while the more advanced classes concentrate on improving students' technique.", "u": null, "notes": "concept: NI001517163535", "dep": null}, {"v": "05002", "n": "Dance Repertory", "d": "Dance Repertory courses provide an opportunity for students to learn about choreographer's unique approaches to dance and choreography by studying and performing excerpts or complete works from a choreographer's repertoire. Dance repertory will train the dancers to capture the nuances and characteristics of the selected piece so that the artist's intent is fully expressed. These courses emphasize performance and typically require auditions.", "u": null, "notes": "concept: NI001517163536", "dep": null}, {"v": "05003", "n": "General Dance", "d": "Formerly known as Expressive Movement, General Dance courses explore dance content through the artistic processes of creating, performing, responding, and connecting. These courses may introduce dance history, culture, and vocabulary in the context of these processes. General Dance courses may also develop students' ability to move expressively, without an emphasis on particular dance forms or on developing specific dance techniques.", "u": null, "notes": "concept: NI001517163537", "dep": null}, {"v": "05004", "n": "Dance History and Appreciation", "d": "Formerly known as Dance Appreciation, Dance History and Appreciation courses help students develop an understanding of how dance serves different civilizations (recreational, social,cultural, theatrical, educational, and liturgical, etc.) and expand their knowledge of and ability to critique dance as an art form. Students learn the history of dance, build an aesthetic point of view, and develop a dance vocabulary. Students view or experience a variety of dance forms, styles, and choreographic approaches to provide a historical and aesthetic context.", "u": null, "notes": "concept: NI001517163538", "dep": null}, {"v": "05005", "n": "Dance�Choreography", "d": "Dance�Choreography courses teach students how to apply choreographic principles and dance forms to create fully developed choreography for formal or informal presentations. These courses may also help students create dances with a beginning, middle, and conclusion.", "u": null, "notes": "concept: NI001517163539", "dep": null}, {"v": "04432", "n": "Social Studies (grade 2)", "d": "Social Studies (grade 2) courses help students reach greater understanding of the social studies disciplines: history, geography, civics and government, and economics. Courses often offer study of these disciplines in an integrated fashion, through the context of a specific theme or discipline, such as state-based social studies or the history of a people. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163540", "dep": null}, {"v": "04433", "n": "Social Studies (grade 3)", "d": "Social Studies (grade 3) courses build on previous knowledge and introduce concepts in the social studies disciplines: history, geography, civics and government, and economics. Instruction of the disciplines is often integrated for instructional purposes. Students may study these disciplines through the context of a specific theme or discipline, such as state-based social studies or U.S. history. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163541", "dep": null}, {"v": "04434", "n": "Social Studies (grade 4)", "d": "Social Studies (grade 4) courses continue to develop skills in history, geography, civics and government, and economics. Although the four disciplines are typically integrated, these courses may take a more discipline-specific approach, such as concentrating on U.S. history, state-specific history, or civic engagement for periods of time. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163542", "dep": null}, {"v": "04435", "n": "Social Studies (grade 5)", "d": "Social Studies (grade 5) courses continue to develop skills in history, geography, civics and government, and economics. These courses may be more discipline-specific (dividing up state history, U.S. history, geography, government, and so on). Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163543", "dep": null}, {"v": "04436", "n": "Social Studies (grade 6)", "d": "Social Studies (grade 6) courses provide a greater understanding of social studies disciplines, including history, geography, civics and government, and economics. These courses often focus on the history, culture, and government of various specific world societies. Typically, students develop skills used in the social studies disciplines. Specific content depends upon state standards for grade 6.", "u": null, "notes": "concept: NI001517163544", "dep": null}, {"v": "04437", "n": "Social Studies (grade 7)", "d": "Social Studies (grade 7) courses provide continued development of understanding and skills in the social studies disciplines: history, geography, civics and government, and economics. Specific content depends upon state standards for grade 7.", "u": null, "notes": "concept: NI001517163545", "dep": null}, {"v": "04438", "n": "Social Studies (grade 8)", "d": "Social Studies (grade 8) courses provide continued development of understanding and skills in the social studies disciplines: history, geography, civics and government, and economics. Typically, these courses focus on single disciplines at a time (e.g., state-specific history and government, U.S. history, world history, or civics) to develop discipline-related skills. Specific content depends upon state standards for grade 8.", "u": null, "notes": "concept: NI001517163546", "dep": null}, {"v": "04439", "n": "Social Studies�General", "d": "Social Studies�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Social Studies, early childhood education through grade 8.]", "u": null, "notes": "concept: NI001517163547", "dep": null}, {"v": "04994", "n": "Social Sciences and History�Proficiency Development", "d": "Social Sciences and History�Proficiency Development courses are designed to assist students in acquiring the skills necessary to pass proficiency examinations related to history and/or other social sciences.", "u": null, "notes": "concept: NI001517163548", "dep": null}, {"v": "04995", "n": "Social Sciences and History�Aide", "d": "Social Sciences and History�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163549", "dep": null}, {"v": "04996", "n": "Social Sciences and History�Supplemental", "d": "Social Sciences and History�Supplemental courses, designed to be taken in addition to or in coordination with other social sciences and history courses, provide instruction to assist students in acquiring social studies/social science skills so that students attain necessary grade-level skills or reach a desired competency level.", "u": null, "notes": "concept: NI001517163550", "dep": null}, {"v": "04997", "n": "Social Sciences and History�Independent Study", "d": "Social Sciences and History�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within one of the fields of social studies. These courses provide students with an opportunity to expand their expertise in a particular specialization, to explore a topic of special interest, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163551", "dep": null}, {"v": "04998", "n": "Social Sciences and History�Workplace Experience", "d": "Social Sciences and History�Workplace Experience courses provide work experience in a field related to social sciences and/or history. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163552", "dep": null}, {"v": "04999", "n": "Social Sciences and History�Other", "d": "Other Social Sciences and History courses.", "u": null, "notes": "concept: NI001517163553", "dep": null}, {"v": "05006", "n": "Dance Survey", "d": "Dance Survey courses provide students with experience in several dance forms (e.g., modern, jazz, ballet, contemporary, tap). Classes introduce students to the fundamental elements of each technique and the common and unique traits among them.", "u": null, "notes": "concept: NI001517163554", "dep": null}, {"v": "05036", "n": "Dance (grade 6)", "d": "Dance (grade 6) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen the ability to discern and critique. Specific course content conforms to any existing state standards for grade 6.", "u": null, "notes": "concept: NI001517163555", "dep": null}, {"v": "05037", "n": "Dance (grade 7)", "d": "Dance (grade 7) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen the ability to discern and critique. Specific course content conforms to any existing state standards for grade 7.", "u": null, "notes": "concept: NI001517163556", "dep": null}, {"v": "05038", "n": "Dance (grade 8)", "d": "Dance (grade 8) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen the ability to discern and critique. Specific course content conforms to any existing state standards for grade 8.", "u": null, "notes": "concept: NI001517163557", "dep": null}, {"v": "05007", "n": "Dance Improvisation", "d": "Dance Improvisation courses help students develop an ability to respond kinesthetically in the moment, understand the elements of dance, relate to each other through movement, experiment with choreographic principles, and expand the boundaries of the definition of dance. These courses may emphasize the process of exploration, individual investigation, and group work.", "u": null, "notes": "concept: NI001517163558", "dep": null}, {"v": "05008", "n": "World/Cultural Dance", "d": "World/Cultural Dance courses help students develop an understanding of authentic dances from other nations in the context of the people's history, culture, and customs. These courses may involve creating, performing, and responding to dances of other cultures and/or time periods.", "u": null, "notes": "concept: NI001517163559", "dep": null}, {"v": "05009", "n": "Technical Theater for Dance", "d": "Technical Theater for Dance courses teach students the basics of lighting, sound, makeup, costuming, stage management, and other aspects of dance concert production. These courses may also include the practical application of skills.", "u": null, "notes": "concept: NI001517163560", "dep": null}, {"v": "05010", "n": "Social Dance", "d": "Social Dance courses teach students the steps, spatial formations and patterns, appropriate partner etiquette, and the relationship of the dance(s) to specific music or musical forms as well as historical or cultural contexts. These courses emphasize the distinct forms of partner or group dances and may include a variety of options (e.g., ballroom, square, folk, barn, contra, circle, and line dances).", "u": null, "notes": "concept: NI001517163561", "dep": null}, {"v": "05011", "n": "Dance Composition/Composition Seminar", "d": "Dance Composition/Composition Seminar courses help students gain an understanding of specific choreographic principles and apply those principles to individual movement studies. These courses may emphasize the process of building dance compositions and discovering methods for connecting different dances.", "u": null, "notes": "concept: NI001517163562", "dep": null}, {"v": "05012", "n": "IB Dance", "d": "IB Dance courses prepare students to take the International Baccalaureate (IB) Dance assessments. IB Dance courses help students develop skills in the composition, performance, and analysis of dance. These courses also help students form an historical and global awareness of dance forms and styles.", "u": null, "notes": "concept: NI001517163563", "dep": null}, {"v": "05028", "n": "Dance (early childhood education)", "d": "Dance (early childhood education) courses provide developmentally appropriate activities to create awareness of bodily movement and its potential for creativity, expression, and communication. Specific course content conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163564", "dep": null}, {"v": "05029", "n": "Dance (pre-kindergarten)", "d": "Dance (pre-kindergarten) courses provide developmentally appropriate activities to create awareness of bodily movement and its potential for creativity, expression, and communication. Specific course content conforms to any existing state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163565", "dep": null}, {"v": "05030", "n": "Dance (kindergarten)", "d": "Dance (kindergarten) courses provide developmentally appropriate activities to create awareness of bodily movement and its potential for creativity, expression, and communication. Specific course content conforms to any existing state standards for kindergarten.", "u": null, "notes": "concept: NI001517163566", "dep": null}, {"v": "05031", "n": "Dance (grade 1)", "d": "Dance (grade 1) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 1.", "u": null, "notes": "concept: NI001517163567", "dep": null}, {"v": "05032", "n": "Dance (grade 2)", "d": "Dance (grade 2) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 2.", "u": null, "notes": "concept: NI001517163568", "dep": null}, {"v": "05033", "n": "Dance (grade 3)", "d": "Dance (grade 3) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 3.", "u": null, "notes": "concept: NI001517163569", "dep": null}, {"v": "05034", "n": "Dance (grade 4)", "d": "Dance (grade 4) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 4.", "u": null, "notes": "concept: NI001517163570", "dep": null}, {"v": "10047", "n": "Computer Literacy�Independent Study", "d": "Computer Literacy�Independent Study courses, often conducted with instructors as mentors, enable students to explore computer-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163840", "dep": null}, {"v": "10048", "n": "Computer Literacy�Workplace Experience", "d": "Computer Literacy�Workplace Experience courses provide work experience in fields related to computer literacy. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163841", "dep": null}, {"v": "10003", "n": "Computer and Information Technology", "d": "Computer and Information Technology courses teach students to operate and use computer and information technology, emphasizing their role as tools to communicate more effectively, conduct research more efficiently, and increase productivity. Course content includes the legal and ethical issues involved with computer technology and use.", "u": null, "notes": "concept: NI001517163842", "dep": null}, {"v": "10004", "n": "Computer Applications", "d": "In Computer Applications courses, students acquire knowledge of and experience in the proper and efficient use of previously written software packages. These courses explore a wide range of applications, including (but not limited to) word-processing, spreadsheet, presentation, graphics, and database programs. Courses may also cover the use of electronic mail and online collaborative software.", "u": null, "notes": "concept: NI001517163843", "dep": null}, {"v": "10005", "n": "Business Computer Applications", "d": "In Business Computer Applications courses, students expand their knowledge of and experience in the proper and efficient use of previously written software packages, particularly those used in business. Generally, these courses explore a wide range of applications including (but not limited to) word processing, spreadsheet, presentation, graphics, and database programs, and they may also cover topics such as electronic mail, desktop publishing, and telecommunications. Advanced topics may include integrated software applications, including printed, electronic, and Web publications; computer maintenance activities; and Web site development.", "u": null, "notes": "concept: NI001517163844", "dep": null}, {"v": "10006", "n": "Telecommunications", "d": "Telecommunications courses address the growth in global communications and the emerging equipment and systems needed to successfully communicate in a global environment. These courses cover such topics as data communication protocol and systems, government regulations of the communications industry, the use of cost-effective and productive tools to transmit messages and data, and live synchronistic video exchanges. Other topics may include telecommunications terminology, tools and test equipment; customer service experience; and installation, repair, and delivery of telecommunications systems. In these courses, students may learn about such communication systems as e-mail, internet, or e-commerce, local area network (LAN), wide area network (WAN), voice transmission, cell phone technology, teleconferencing, and videoconferencing.", "u": null, "notes": "concept: NI001517163845", "dep": null}, {"v": "10007", "n": "IB Digital Society", "d": "IB Digital Society courses prepare students to take the International Baccalaureate Digital Society exams and examine the interaction among information, technology, and society. Course content is designed to help students develop a systematic, problem solving approach to processing and analyzing information using a range of information tools. In these courses, students also discuss and evaluate how modern information technology affects individuals, relationships among people, and institutions and societies. This course is also called IB Information Technology in a Global Society.", "u": null, "notes": "concept: NI001517163846", "dep": null}, {"v": "10008", "n": "Particular Topics in Computer Literacy", "d": "These courses examine particular topics related to general computer literacy other than those already described elsewhere in this classification system, such as privacy issues or instruction in using a particular software application.", "u": null, "notes": "concept: NI001517163847", "dep": null}, {"v": "10009", "n": "Internet Skills", "d": "Internet Skills courses introduce students to the World Wide Web and the Internet. Course content may include search techniques and algorithms, web browser utilization, website creation, and the history of the Internet.", "u": null, "notes": "concept: NI001517163848", "dep": null}, {"v": "10105", "n": "NetWare Routing", "d": "NetWare Routing courses introduce students to such topics as Virtual LANs (VLAN) and switched internetworking, comparing traditional shared local area network (LAN) configurations with switched LAN configurations, and they also discuss the benefits of using a switched VLAN architecture. These courses also may cover routing protocols like RIP, IGRP, Novell IPX, and Access Control Lists (ACLs).", "u": null, "notes": "concept: NI001517163854", "dep": null}, {"v": "10011", "n": "Computer Science Principles", "d": "Computer Science Principles courses provide students the opportunity use programming, computational thinking, and data analytics to create digital artifacts and documents representing design and analysis in areas including the Internet, algorithms, and the impact that these have on science, business, and society. Computer Science Principles courses teach students to use computational tools and techniques including abstraction, modeling, and simulation to collaborate in solving problems that connect computation to their lives.", "u": null, "notes": "concept: NI001517163849", "dep": null}, {"v": "10012", "n": "Exploring Computer Science", "d": "Exploring Computer Science courses present students with the conceptual underpinnings of computer science through an exploration of human computer interaction, web design, computer programming, data modeling, and robotics. While these courses include programming, the focus is on the computational practices associated with doing computer science, rather than just a narrow focus on coding, syntax, or tools. Exploring Computer Science courses teach students the computational practices of algorithm design, problem solving, and programming within a context that is relevant to their lives.", "u": null, "notes": "concept: NI001517163850", "dep": null}, {"v": "10102", "n": "Networking Systems", "d": "Networking Systems courses are designed to provide students with the opportunity to understand and work with hubs, switches, and routers. Students develop an understanding of LAN (local area network), WAN (wide area network), wireless connectivity, and Internet-based communications (including cloud-based computing), with a strong emphasis on network function, design, and installation practices. Students acquire skills in the design, installation, maintenance, and management of network systems that may help them obtain network certification.", "u": null, "notes": "concept: NI001517163851", "dep": null}, {"v": "10103", "n": "Area Network Design and Protocols", "d": "Area Network Design and Protocols courses address the role of computers in a network system, the Open Systems Interconnection (OSI) model, structured wiring systems, and simple LAN (local area network) and WAN (wide area network) designs.", "u": null, "notes": "concept: NI001517163852", "dep": null}, {"v": "10104", "n": "Router Basics", "d": "Router Basics courses teach students about router components, installation, and configuration using routers (e.g., CISCO) switches and the IOS (Internetwork Operation System). These courses also cover such topics as TCP/IP protocol, IP addressing, subnetting concepts, and network trouble-shooting.", "u": null, "notes": "concept: NI001517163853", "dep": null}, {"v": "10106", "n": "Wide Area Telecommunications and Networking", "d": "Wide Area Telecommunications and Networking courses provide students with the knowledge and skills to enable them to design Wide Area Networks (WANs) using ISDN, Frame-Relay, and PPP. These courses provide students with an understanding of internetworking and expertise in trouble-shooting and assessing the adequacy of network configurations to meet changing conditions. Topics may include also Local Area Network (LAN) segmentation.", "u": null, "notes": "concept: NI001517163855", "dep": null}, {"v": "10107", "n": "Wireless Networks", "d": "Wireless Networks courses focus on the design, planning, implementation, operation, and trouble-shooting of wireless computer networks, including local access networks (LANs). These courses typically include a comprehensive overview of best practices in technology, security, and design.", "u": null, "notes": "concept: NI001517163856", "dep": null}, {"v": "10108", "n": "Network Security", "d": "Network Security courses provide students with an understanding of network security principles and implementation. Course topics usually include authentication, the types of attacks and malicious code that may be used against computer networks, the threats and countermeasures for e-mail, Web applications, remote access, and file and print services. These courses may also cover a variety of security topologies as well as technologies and concepts used for providing secure communication channels, secure internetworking devices, intrusion detection systems, and firewalls.", "u": null, "notes": "concept: NI001517163857", "dep": null}, {"v": "09202", "n": "Marine Corps Junior ROTC II", "d": "Marine Corps Junior Reserve Officer Training Corps (ROTC) II courses build upon Marine Corps Junior ROTC I. These courses emphasize personal growth and responsibility, leadership, and citizenship along with military subjects that typically include the mission, organization, and history of the Marine Corps; geography, maps, and navigation; drill and ceremony; and military justice. Students learn about such leadership skills as authority, responsibility, and accountability and citizenship topics including U.S. government structures, documents, and symbols.", "u": null, "notes": "concept: NI001517163858", "dep": null}, {"v": "09999", "n": "Military Science�Other", "d": "Other Military Sciences courses.", "u": null, "notes": "concept: NI001517163864", "dep": null}, {"v": "09203", "n": "Marine Corps Junior ROTC III", "d": "Marine Corps Junior Reserve Officer Training Corps (ROTC) III courses build upon prior Marine Corps Junior ROTC courses. These courses include (but are not limited to) leadership practice, including training, inspection and evaluation; public service career opportunities; and citizenship responsibilities. These courses cover such personal skills as financial planning, saving and investing, and evaluating credit and insurance terms. Students learn about the structures of other armed service branches, advance their mapping and navigation skills, and may study firearm use, safety and marksmanship. Students continue to learn teamwork, Marine Corps history, and military principles.", "u": null, "notes": "concept: NI001517163859", "dep": null}, {"v": "09204", "n": "Marine Corps Junior ROTC IV", "d": "Marine Corps Junior Reserve Officer Training Corps (ROTC) IV courses focus on the practical application of skills learned throughout the program: leadership, communication (written and verbal), personal growth, and public service. These courses emphasize drill and ceremony, physical fitness, marksmanship, land navigation, and military history at more advanced levels than in previous courses.", "u": null, "notes": "concept: NI001517163860", "dep": null}, {"v": "09995", "n": "Military Science�Aide", "d": "Military Science�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163861", "dep": null}, {"v": "09997", "n": "Military Science�Independent Study", "d": "Courses in Military Science�Independent Study, often conducted with instructors/armed services personnel as mentors, enable students to explore topics of interest related to military science. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163862", "dep": null}, {"v": "09998", "n": "Military Science�Workplace Experience", "d": "Military Science�Workplace Experience courses provide students with work experience within the field of military science and are supported by classroom attendance and discussion. In these courses, goals are set for the employment period, and classroom experience may involve further study in the field, improvement of employability skills, or discussion regarding the experiences and problems that students encounter on the job.", "u": null, "notes": "concept: NI001517163863", "dep": null}, {"v": "10001", "n": "Introduction to Computer Technology", "d": "Formerly known as Introduction to Computers, Introduction to Computer Technology courses introduce students to computers, including peripheral and mobile devices; the functions and uses of computer technology; the language used in the industry; possible applications of various computer-based technologies; and occupations related to computer technology hardware and software industries. These courses typically explore legal and ethical issues associated with computer technology use, as well as how changes influence modern society. Students may also be required to perform some computer technology operations.", "u": null, "notes": "concept: NI001517163865", "dep": null}, {"v": "10002", "n": "Computing Systems", "d": "Computing Systems courses offer a broad exploration of the use of computers in a variety of fields. These courses have a considerable range of content, but typically include the introduction of robotics and control systems, computer-assisted design, computer-aided manufacturing systems, and other computer technologies as they relate to industry applications.", "u": null, "notes": "concept: NI001517163866", "dep": null}, {"v": "10109", "n": "Essentials of Network Operating Systems", "d": "Essentials of Network Operating Systems courses provide students with an overview of multi-user, multi-tasking network operating systems. In these courses, students study the characteristics of operating systems, such as Linux, and various Windows network operating systems and explore a range of topics including installation procedures, security issues, back-up procedures, and remote access. Advanced topics may include network administration, including account management, training, evaluating new technology, developing system policies, troubleshooting, e-mail and business communications and Web site management.", "u": null, "notes": "concept: NI001517163867", "dep": null}, {"v": "10153", "n": "Visual Basic (VB) Programming", "d": "Visual Basic (VB) Programming courses provide an opportunity for students to gain expertise in computer programs using the Visual Basic (VB) language. As with more general computer programming courses, the emphasis is on how to structure and document computer programs and how to use problem-solving techniques. These courses cover such topics as the use of text boxes, scroll bars, menus, buttons, and Windows applications. More advanced topics may include mathematical and business functions and graphics.", "u": null, "notes": "concept: NI001517163868", "dep": null}, {"v": "10248", "n": "Media Technology�Workplace Experience", "d": "Media Technology�Workplace Experience courses provide students with work experience in fields related to media technology. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163869", "dep": null}, {"v": "10249", "n": "Media Technology�Other", "d": "Other Media Technology courses.", "u": null, "notes": "concept: NI001517163870", "dep": null}, {"v": "10251", "n": "Computer Technology", "d": "Computer Technology courses introduce students to the features, functions, and design of computer hardware and provide instruction in the maintenance and repair of computer components and peripheral devices.", "u": null, "notes": "concept: NI001517163871", "dep": null}, {"v": "10252", "n": "Computer Maintenance", "d": "Computer Maintenance courses prepare students to apply basic electronic theory and principles in diagnosing and repairing personal computers and input/output devices. Topics may include operating, installing, maintaining, and repairing computers, network systems, digital control instruments, programmable controllers, and processors.", "u": null, "notes": "concept: NI001517163872", "dep": null}, {"v": "10154", "n": "C++ Programming", "d": "C++ Programming courses provide an opportunity for students to gain expertise in computer programs using the C++ language. As with more general computer programming courses, the emphasis is on how to write logically structured programs, include appropriate documentation, and use problem-solving techniques. More advanced topics may include multi-dimensional arrays, functions, sorting, loops, and records.", "u": null, "notes": "concept: NI001517163873", "dep": null}, {"v": "10155", "n": "Java Programming", "d": "Java Programming courses provide students with the opportunity to gain expertise in computer programs using the Java language. As with more general computer programming courses, the emphasis is on how to structure and document computer programs, using problem-solving techniques. Topics covered in the course include syntax, I/O classes, string manipulation, and recursion.", "u": null, "notes": "concept: NI001517163874", "dep": null}, {"v": "10156", "n": "Computer Programming�Other Language", "d": "Computer Programming�Other Language courses provide students with the opportunity to gain expertise in computer programs using languages other than those specified (such as Pascal, FORTRAN, Python, or emerging languages). As with other computer programming courses, the emphasis is on how to structure and document computer programs, using problem-solving techniques. As students advance, they learn how to best utilize the features and strengths of the language being used.", "u": null, "notes": "concept: NI001517163875", "dep": null}, {"v": "10157", "n": "AP Computer Science A", "d": "Following the College Board's suggested curriculum designed to mirror college-level computer science courses, AP Computer Science A courses emphasize object-oriented programming methodology with a focus on problem solving and algorithm development. These courses cover such topics as object-oriented program design; program implementation; program analysis; standard data structures; standard algorithms; and the ethical and social implications of computing systems.", "u": null, "notes": "concept: NI001517163876", "dep": null}, {"v": "10159", "n": "IB Computer Science", "d": "IB Computer Science courses prepare students to take the International Baccalaureate Computer Science exams. The courses emphasize system fundamentals, computer organization, and networks, as well as the fundamental concepts of computational thinking, the development of practical computational solutions, and programming. IB Computer Science courses also cover the applications and effects of the computer on modern society as well as the limitations of computer technology.", "u": null, "notes": "concept: NI001517163877", "dep": null}, {"v": "10160", "n": "Particular Topics in Computer Programming", "d": "These courses examine particular topics in computer programming other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163878", "dep": null}, {"v": "10197", "n": "Computer Programming�Independent Study", "d": "Computer Programming�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to computer programming. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163879", "dep": null}, {"v": "16197", "n": "Travel and Tourism�Independent Study", "d": "Travel and Tourism�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the travel and tourism industry. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164178", "dep": null}, {"v": "16198", "n": "Travel and Tourism�Workplace Experience", "d": "Travel and Tourism�Workplace Experience courses provide work experience in fields related to travel and tourism. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164179", "dep": null}, {"v": "16199", "n": "Travel and Tourism�Other", "d": "Other Travel and Tourism courses.", "u": null, "notes": "concept: NI001517164180", "dep": null}, {"v": "16201", "n": "Exploration of Recreation, Amusement and Attractions", "d": "Exploration of Recreation, Amusement, and Attractions courses provide an overview of the recreation industry. Topics covered in this course may include industry terminology; the history of recreation, amusement, and attractions; introduction to marketing; and the various careers available in the industry.", "u": null, "notes": "concept: NI001517164181", "dep": null}, {"v": "16202", "n": "Recreation, Amusement and Attractions�Comprehensive", "d": "Recreation, Amusement, and Attractions�Comprehensive courses provide students with the attitudes, skills, and knowledge needed for employment in theme parks, attractions and outdoor recreation facilities, exhibitions, and event planning. Topics covered may include planning trade shows, fairs, and conferences; outdoor recreation and management; financial transactions; salesmanship; guest services and satisfaction; culture and customs; computer and industry technology; eco-tourism; client information; and planning specialized events while incorporating themes, timelines, budgets, target audiences, agendas, and public relations.", "u": null, "notes": "concept: NI001517164182", "dep": null}, {"v": "16247", "n": "Recreation, Amusement and Attractions�Independent Study", "d": "Recreation, Amusement, and Attractions�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the recreation, amusement, and attractions industry. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164183", "dep": null}, {"v": "17017", "n": "Particular Topics in Construction", "d": "These courses provide students with specialized knowledge and help them develop skills in particular topics concerning the processes, responsibilities, and occupations of the construction industry.", "u": null, "notes": "concept: NI001517164184", "dep": null}, {"v": "17047", "n": "General Construction�Independent Study", "d": "General Construction�Independent Study courses, often conducted with instructors as mentors, enable students to explore construction-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164185", "dep": null}, {"v": "17048", "n": "General Construction�Workplace Experience", "d": "General Construction�Workplace Experience courses provide work experience in a field related to construction. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164186", "dep": null}, {"v": "17049", "n": "General Construction�Other", "d": "Other General Construction courses.", "u": null, "notes": "concept: NI001517164187", "dep": null}, {"v": "16248", "n": "Recreation, Amusement and Attractions�Workplace Experience", "d": "Recreation, Amusement, and Attractions�Workplace Experience courses provide work experience in fields related to recreation, amusement, and attractions. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164188", "dep": null}, {"v": "16249", "n": "Recreation, Amusement and Attractions�Other", "d": "Other Recreation, Amusement and Attractions courses.", "u": null, "notes": "concept: NI001517164189", "dep": null}, {"v": "16995", "n": "Hospitality and Tourism�Aide", "d": "Hospitality and Tourism�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164190", "dep": null}, {"v": "16997", "n": "Hospitality and Tourism�Independent Study", "d": "Hospitality and Tourism�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest within the hospitality and tourism industry. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164191", "dep": null}, {"v": "16998", "n": "Hospitality and Tourism�Workplace Experience", "d": "Hospitality and Tourism�Workplace Experience courses provide work experience in fields related to hospitality and tourism. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164192", "dep": null}, {"v": "16999", "n": "Hospitality and Tourism�Other", "d": "Other Hospitality and Tourism courses.", "u": null, "notes": "concept: NI001517164193", "dep": null}, {"v": "17001", "n": "Construction Careers Exploration", "d": "Construction Careers Exploration courses expose students to the opportunities available in the architecture and construction industry, including occupations such as carpenter, electrician, plumber, heating/air conditioning technician, safety supervisor, architect, engineer, and other occupations. Students learn about the processes involved in construction projects and may engage in a variety of small projects. These courses emphasize responsibilities, qualifications, work environment, rewards, and career paths within construction-related fields.", "u": null, "notes": "concept: NI001517164194", "dep": null}, {"v": "17002", "n": "Construction�Comprehensive", "d": "Construction�Comprehensive courses provide students with basic knowledge and skills required for construction of commercial, residential, and institutional structures. These courses provide experiences and information (typically including career opportunities and training requirements) regarding construction-related occupations such as carpentry, cabinetmaking, bricklaying, electrical trades, plumbing, concrete masonry, and so on. Students engage in activities such as reading blueprints, preparing building sites, starting foundations, erecting structures, installing utilities, finishing surfaces, and providing maintenance.", "u": null, "notes": "concept: NI001517164195", "dep": null}, {"v": "17003", "n": "Carpentry", "d": "Carpentry courses provide information related to the building of wooden structures, enabling students to gain an understanding of wood grades and construction methods and to learn skills such as laying sills and joists; erecting sills and rafters; applying sheathing, siding, and shingles; setting door jambs; and hanging doors. Carpentry courses may teach skills for rough construction, finish work, or both. Students learn to read blueprints, draft, use tools and machines properly and safely, erect buildings from construction lumber, perform finish work inside of buildings, and do limited cabinet work. Carpentry courses may also include career exploration, good work habits, and employability skills.", "u": null, "notes": "concept: NI001517164196", "dep": null}, {"v": "17004", "n": "Framing Carpentry", "d": "Framing Carpentry courses provide students with much of the same knowledge as general carpentry courses (knowledge of various types and grades of woods, proper and safe use of hand and power tools, and site selection and preparation), but place a special emphasis on construction methods applicable to floor, wall, roof, and/or stair framing. Course content may also include insulation installation and painting.", "u": null, "notes": "concept: NI001517164197", "dep": null}, {"v": "17005", "n": "Particular Topics in Carpentry", "d": "These courses cover specific aspects of building construction or carpentry. All coursework focuses upon a particular skill or set of skills related to one subtopic, such as floor framing, wall and partition framing, interior finishing, or exterior finishing.", "u": null, "notes": "concept: NI001517164198", "dep": null}, {"v": "17006", "n": "Woodworking", "d": "Woodworking courses introduce students to the various kinds of woods used in industry and offer experience in using selected woodworking tools. Students design and construct one or more projects and may prepare a bill of materials. Correct and safe use of tools and equipment is emphasized. As students advance, they focus on learning the terminology necessary to use power tools successfully, developing skills to safely use these tools in the workshop and becoming familiar with various kinds of wood-finishing materials. Advanced students typically design a project, prepare bills of materials, construct, and finish proposed projects.", "u": null, "notes": "concept: NI001517164199", "dep": null}, {"v": "17007", "n": "Cabinetmaking", "d": "Cabinetmaking courses provide students with experience in constructing cases, cabinets, counters, and other interior woodwork. Students learn to distinguish between various types of furniture construction and their appropriate applications, and how to use various woodworking machines and power tools for cutting and shaping wood. Cabinetmaking courses cover the different methods of joining pieces of wood, how to use mechanical fasteners, and how to attach hardware. Initial topics may resemble those taught in Woodworking courses; more advanced topics may include how to install plastic laminates on surfaces and how to apply spray finishes.", "u": null, "notes": "concept: NI001517164200", "dep": null}, {"v": "17008", "n": "Masonry", "d": "Masonry courses enable students to learn to construct interior and exterior walls, columns, doorways, window openings, fireplaces, chimneys, and foundations from brick and concrete block. Along with other activities, students may mix and spread cement and mortar, read blueprints and plans, and estimate materials needed for a project. Other topics may also include how to layout buildings on footings and how to establish grades using a surveying transit.", "u": null, "notes": "concept: NI001517164201", "dep": null}, {"v": "17009", "n": "Building Repair and Maintenance", "d": "Formerly known as Building Maintenance, Building Repair and Maintenance courses train students to maintain commercial, industrial, and residential buildings and homes. Instruction is provided in the basic maintenance and repair of air conditioning, heating, plumbing, electrical, and other mechanical systems. Topics covered may include identifying and using hand and power tools safely; installing and repairing floor coverings, walls, and ceilings; installing and repairing doors, windows, screens, and cabinets; applying finishes to prepared surfaces; and repairing roofs, masonry, plumbing, and electrical systems.", "u": null, "notes": "concept: NI001517164202", "dep": null}, {"v": "17010", "n": "Home Maintenance", "d": "Home Maintenance courses provide students with knowledge and skills related to devices and systems found in the home. Course content may include electrical wiring, plumbing, window and door repair and installation, wall and floor repair and finishing, furniture repair and finishing, and small appliance repair.", "u": null, "notes": "concept: NI001517164203", "dep": null}, {"v": "17011", "n": "Wall Finishings", "d": "Wall Finishings courses prepare students to finish exterior or interior surfaces by applying protective coating materials such as paint, lacquer, wallpaper, plaster, or stucco. Course topics may include instruction in making, mixing, and matching paint colors; applying coating with various types of equipment; applying wallpaper; lathing, preparing surfaces, smoothing, and finishing.", "u": null, "notes": "concept: NI001517164204", "dep": null}, {"v": "17012", "n": "Upholstering", "d": "Upholstering courses prepare students in all aspects of upholstering furniture. Topics covered may include installing, repairing, arranging, and securing the springs, filler, padding and cover materials of chairs, couches and mattresses; cutting, sewing and trimming; cushion filling, tufting, and buttoning; and wood refinishing.", "u": null, "notes": "concept: NI001517164205", "dep": null}, {"v": "17013", "n": "Commercial Construction", "d": "Commercial Construction courses focus on residential construction principles and their relationship to commercial applications. Topics typically covered include commercial concrete forming, reinforcement and placement methods, stair construction, metal framing, interior finishes, suspended ceiling systems, metal framing and drywall applications, and commercial roofing methods and systems. These courses may also address equipment and tool usage in commercial construction.", "u": null, "notes": "concept: NI001517164206", "dep": null}, {"v": "17014", "n": "Concrete Foundations", "d": "Concrete Foundations courses cover concrete and its relationship to construction and concrete safety and testing techniques.", "u": null, "notes": "concept: NI001517164207", "dep": null}, {"v": "17015", "n": "Construction Estimating", "d": "Construction Estimating courses provide students with the opportunity to learn the fundamental principles of construction estimating. Course topics typically include procedures for estimating costs in different divisions of a project and determining the critical quantities of materials obtained from a set of plans.", "u": null, "notes": "concept: NI001517164208", "dep": null}, {"v": "17016", "n": "Construction Management", "d": "Construction Management courses introduce students to the concept of the project team, use of documents on a construction site, submittals, shop drawings, jobsite layout, meeting control, safety management, changes and claims forms, documents, and project closeout record keeping. Topics may also include construction law, construction contracts, and how to work with owners and subcontractors.", "u": null, "notes": "concept: NI001517164209", "dep": null}, {"v": "16203", "n": "Particular Topics in Recreation, Amusement and Attractions", "d": "These courses examine specific topics in recreation, amusement, and attractions such as local opportunities rather than provide a general study of the industry.", "u": null, "notes": "concept: NI001517164210", "dep": null}, {"v": "16204", "n": "Recreation, Amusement, and Attractions Management", "d": "Recreation, Amusement, and Attractions Management courses teach students about the development and management of recreational areas and parks and cover the economic and environmental impact of tourism. These courses may also emphasize career skills relative to the outdoor parks, recreation, and tourism industries.", "u": null, "notes": "concept: NI001517164211", "dep": null}, {"v": "17051", "n": "Air Conditioning", "d": "Air Conditioning courses offer students specialized training related to the design, installation, and repair of air conditioning systems for residential and commercial use. These courses may emphasize the theory and design of electrical, electronic, mechanical, and pneumatic control systems used in air conditioning systems. They might also (or instead) focus on procedures used in troubleshooting, servicing, and installing electric, gas, and ground source components of air conditioning systems.", "u": null, "notes": "concept: NI001517164212", "dep": null}, {"v": "17052", "n": "Refrigeration", "d": "Refrigeration courses provide students with exposure to and training in the theories, equipment, and skills needed to design, install, and repair commercial and residential refrigeration systems. Course topics typically include the theory of thermodynamics, measurement of pressures and temperatures, components and common accessories of refrigeration systems, and repair and safety procedures.", "u": null, "notes": "concept: NI001517164213", "dep": null}, {"v": "17053", "n": "Heating", "d": "Heating courses offer students training specific to the design, installation, and repair of heating systems for residential use. Topics typically include electric, gas, steam, and ground-source systems; ventilation procedures; safety practices; and installation and trouble-shooting techniques.", "u": null, "notes": "concept: NI001517164214", "dep": null}, {"v": "17054", "n": "Air Conditioning/Refrigeration", "d": "Air Conditioning/Refrigeration courses enable students to develop the combined skills and knowledge to install, maintain, adjust, and repair both air conditioning and refrigeration systems.", "u": null, "notes": "concept: NI001517164215", "dep": null}, {"v": "17055", "n": "Air Conditioning, Heating, and Refrigeration", "d": "In Air Conditioning, Heating, and Refrigeration courses, students learn the basic principles of these systems, along with how to identify and safely use tools/equipment used in the trade.", "u": null, "notes": "concept: NI001517164216", "dep": null}, {"v": "17056", "n": "Heating, Ventilation, and Air Conditioning", "d": "These courses synthesize basic and advanced principles in heating, ventilation, and air conditioning and include topics such as air filtration methods, humidity control, and the installation and maintenance of heat pumps, furnaces, and air conditioners. Students also learn about climate control systems; electrical wiring; systems design; sizing, fabricating, and installing ductwork; installing and maintaining climate control systems; and safety.", "u": null, "notes": "concept: NI001517164217", "dep": null}, {"v": "17057", "n": "Particular Topics in HVACR", "d": "These courses offer students specialized training in aspects or topics that are common to various climate control systems (heating, ventilation, air conditioning, and refrigeration systems); such topics may include electrical components, diagrams and blueprints, welding and soldering techniques, and so on.", "u": null, "notes": "concept: NI001517164218", "dep": null}, {"v": "17058", "n": "Plumbing", "d": "Plumbing courses provide students with instruction in installing waste and vent systems, water and gas pipes, trim, and fixtures. Skills taught include cutting and joining various types of pipe (for instance, steel, plastic) using various methods (cement, seat method, and so on).", "u": null, "notes": "concept: NI001517164219", "dep": null}, {"v": "05299", "n": "Media Arts�Other", "d": "Other Media Arts courses.", "u": null, "notes": "concept: NI001517164507", "dep": null}, {"v": "10010", "n": "Computer Literacy", "d": "Computer Literacy courses provide to students the knowledge and ability to use computers and technology efficiently. Typically, course content includes exposure to word-processing, spreadsheet, and presentation applications, but also may include the various uses of computers in modern society. Specific course content aligns with state standards to promote students' technological literacy.", "u": null, "notes": "concept: NI001517164508", "dep": null}, {"v": "10020", "n": "Cybersecurity", "d": "Cybersecurity courses introduce students to the concepts of cybersecurity. These courses provide students with the knowledge and skills to assess cyber risks to computers, networks, and software programs. Students will learn how to create solutions to mitigate cybersecurity risks. These courses may also cover the legal environment and ethical computing behavior related to cybersecurity.", "u": null, "notes": "concept: NI001517164509", "dep": null}, {"v": "24279", "n": "IB Language Ab Initio�Swedish", "d": "IB Language Ab Initio�Swedish courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517164510", "dep": null}, {"v": "24272", "n": "IB Language B�Danish", "d": "IB Language B�Danish courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517164511", "dep": null}, {"v": "24273", "n": "IB Language B�Dutch", "d": "IB Language B�Dutch courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517164512", "dep": null}, {"v": "24274", "n": "IB Language B�Swedish", "d": "IB Language B�Swedish courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517164513", "dep": null}, {"v": "21026", "n": "PLTW Engineering Essentials", "d": "Following Project Lead the Way's suggested curriculum, PLTW Engineering Essentials courses focus on introducing students to engineering-related career opportunities. Students learn about engineers and how their work is used to solve real-world problems. Topics include the engineering design process, machines and mechanical systems, energy forms, and the application of geographic information systems and modeling software.", "u": null, "notes": "concept: NI001517164514", "dep": null}, {"v": "21025", "n": "PLTW Engineering Design and Development", "d": "Following Project Lead the Way's curriculum, the PLTW Engineering Design and Development course is a capstone course for the PLTW Engineering program. Students use knowledge obtained in previous courses to identify an issue and research and design a solution. Students may present the results of their solution to a panel of engineers.", "u": null, "notes": "concept: NI001517164515", "dep": null}, {"v": "24041", "n": "Braille", "d": "Braille courses prepare students to read Braille. These courses may include varying formats of Braille and are available to vision-impaired and sighted students.", "u": null, "notes": "concept: NI001517164516", "dep": null}, {"v": "24042", "n": "IB Language B�English", "d": "IB Language B�English courses prepare students to take the International Baccalaureate Language B exams. These courses focus on improving students' accuracy and fluency in oral and written communication (usually in the students' \"second\" language).", "u": null, "notes": "concept: NI001517164517", "dep": null}, {"v": "24043", "n": "IB Language Ab Initio�English", "d": "IB Language Ab Initio�English courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517164518", "dep": null}, {"v": "24303", "n": "Greek II", "d": "Greek II courses build upon skills developed in Greek I, preparing students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Greek II courses introduce the relationships among the products, practices, and perspectives of Greek-speaking cultures.", "u": null, "notes": "concept: NI001517164519", "dep": null}, {"v": "24400", "n": "Chinese Languages for Young Learners (prior-to-secondary)", "d": "Chinese Languages for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Chinese languages and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Chinese languages by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Chinese language-speaking cultures. These courses may be used for any Chinese language, including Mandarin and Cantonese.", "u": null, "notes": "concept: NI001517164520", "dep": null}, {"v": "10021", "n": "Computer Science Discoveries", "d": "Computer Science Discoveries is a highly interactive and collaborative introduction to the field of computer science. The course takes a wide lens on computer science by covering topics such as problem solving, programming, physical computing, user centered design, and data. Students build their own websites, apps, animations, games, and physical computing systems. Students create and share their own content to meet various design challenges, as well as implement computational solutions to problems that impact their communities. Along the way, they practice design, testing, and iteration, as they come to see that failure and debugging are an expected and valuable part of the programming process.", "u": null, "notes": "concept: NI001517164521", "dep": null}, {"v": "24275", "n": "IB Language A: Language and Literature�Dutch", "d": "IB Language A: Language and Literature�Dutch courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Dutch in an academic context.", "u": null, "notes": "concept: NI001517164522", "dep": null}, {"v": "24276", "n": "IB Language A: Language and Literature�Swedish", "d": "IB Language A: Language and Literature�Swedish courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Swedish in an academic context.", "u": null, "notes": "concept: NI001517164523", "dep": null}, {"v": "24269", "n": "IB Language A: Literature�Danish", "d": "IB Language A: Literature�Danish courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Danish in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517164524", "dep": null}, {"v": "24270", "n": "IB Language A: Literature�Dutch", "d": "IB Language A: Literature�Dutch courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Dutch in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517164525", "dep": null}, {"v": "24271", "n": "IB Language A: Literature�Swedish", "d": "IB Language A: Literature�Swedish courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Swedish in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517164526", "dep": null}, {"v": "24277", "n": "IB Language Ab Initio�Danish", "d": "IB Language Ab Initio�Danish courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517164527", "dep": null}, {"v": "24278", "n": "IB Language Ab Initio�Dutch", "d": "IB Language Ab Initio�Dutch courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517164528", "dep": null}, {"v": "20997", "n": "Transportation, Distribution and Logistics�Independent Study", "d": "Transportation, Distribution, and Logistics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to transportation, distribution, and logistics. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164529", "dep": null}, {"v": "20998", "n": "Transportation, Distribution and Logistics�Workplace Experience", "d": "Transportation, Distribution, and Logistics�Workplace Experience courses provide students with work experience in fields related to transportation, distribution, and logistics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences encountered in the workplace.", "u": null, "notes": "concept: NI001517164530", "dep": null}, {"v": "20999", "n": "Transportation, Distribution and Logistics�Other", "d": "Other Transportation, Distribution and Logistics courses.", "u": null, "notes": "concept: NI001517164531", "dep": null}, {"v": "21001", "n": "Pre-Engineering Technology", "d": "Pre-Engineering Technology courses integrate technology-oriented applications of mathematics and science into pre-engineering activities for students. Course topics may include material sciences, technology processes, enterprises, and career opportunities.", "u": null, "notes": "concept: NI001517164532", "dep": null}, {"v": "21002", "n": "Engineering Applications", "d": "Engineering Applications courses provide students with an overview of the practical uses of a variety of engineering applications. Topics covered usually include hydraulics, pneumatics, computer interfacing, robotics, computer-aided design, computer numerical control, and electronics.", "u": null, "notes": "concept: NI001517164533", "dep": null}, {"v": "21003", "n": "Engineering Technology", "d": "Engineering Technology courses provide students with the opportunity to focus on one or more areas of industrial technology. Students apply technological processes to solve real engineering problems; develop the knowledge and skills to design, modify, use, and apply technology; and may also design and build prototypes and working models. Topics covered in the course include the nature of technology, use of technology, and design processes.", "u": null, "notes": "concept: NI001517164534", "dep": null}, {"v": "21004", "n": "Principles of Engineering", "d": "Principles of Engineering courses provide students with an understanding of the engineering/technology field. Students typically explore how engineers use various technology systems and manufacturing processes to solve problems; they may also gain an appreciation of the social and political consequences of technological change.", "u": null, "notes": "concept: NI001517164535", "dep": null}, {"v": "21005", "n": "Engineering�Comprehensive", "d": "Engineering�Comprehensive courses introduce students to and expand their knowledge of major engineering concepts such as modeling, systems, design, optimization, technology-society interaction, and ethics. Particular topics often include applied engineering graphic systems, communicating technical information, engineering design principles, material science, research and development processes, and manufacturing techniques and systems. The courses may also cover the opportunities and challenges in various branches of engineering.", "u": null, "notes": "concept: NI001517164536", "dep": null}, {"v": "21006", "n": "Engineering Design", "d": "Engineering Design courses offer students experience in solving problems by applying a design development process. Often using solid modeling computer design software, students develop, analyze, and test product solutions models as well as communicate the features of those models.", "u": null, "notes": "concept: NI001517164537", "dep": null}, {"v": "21007", "n": "Engineering Design and Development", "d": "Engineering Design and Development courses provide students with the opportunity to apply engineering research principles as they design and construct a solution to an engineering problem. Students typically develop and test solutions using computer simulations or models but eventually create a working prototype as part of the design solution.", "u": null, "notes": "concept: NI001517164538", "dep": null}, {"v": "13104", "n": "Mechatronics", "d": "Mechatronics courses provide students with instruction and experience in mechatronics, a multidisciplinary subject involving mechanics, electronics, control theory, and computer science to design and manufacture products. Mechatronic systems form the foundation of robotics, automation, and advanced manufacturing (such as 3D printing). These courses typically expose students to the theoretical basis of mechatronics in addition to applying these theories to hands-on projects", "u": null, "notes": "concept: NI001517164539", "dep": null}, {"v": "02158", "n": "Quantitative Reasoning", "d": "Quantitative Reasoning courses allow students to apply basic mathematical skills and analytical concepts to real-world situations. These courses focus on strategies required for problem solving, critical evaluation of numerical information, decision making, and economic productivity in real-world applications. Topics may include numeracy, ratio and proportional reasoning, modeling, financial literacy, validity studies (logic and set theory), and statistics.", "u": null, "notes": "concept: NI001517164540", "dep": null}, {"v": "02114", "n": "AP Precalculus", "d": "Following the College Board's suggested curriculum designed to parallel college-level precalculus courses, AP Precalculus courses introduce students to mathematical modeling and functions that serve as a foundation for calculus and other college-level mathematics needed for a variety of STEM majors and careers. Topics typically include polynomial and rational functions, exponential and logarithmic functions, trigonometric and polar functions, and functions involving parameters, vectors, and matrices.", "u": null, "notes": "concept: NI001517164541", "dep": null}, {"v": "01013", "n": "AP Seminar: English", "d": "Following the College Board's suggested curriculum designed to parallel college-level English courses, AP Seminar: English courses expose students to a variety of texts covering multiple genres, topics, and rhetorical contexts in a seminar-style setting. These courses foster students' ability to summarize and explain the salient ideas in a text by analyzing an author's perspective, rhetorical choices, and argumentative structure. Students evaluate a variety of literary, informational, and visual texts, and synthesize perspectives to develop evidence-based arguments. Students convey their findings through multiple written formats, multimedia presentations, and oral defenses.", "u": null, "notes": "concept: NI001517164542", "dep": null}, {"v": "01106", "n": "CI English General Paper", "d": "Cambridge International (CI) English General Paper courses prepare students to take the Cambridge English General Paper assessments. These courses teach students to write in English through the study of a wide range of contemporary topics, to analyze opinions and ideas, and to construct arguments. Students will gain the skill of English writing comprehension as well as skills of developing arguments, independent reasoning, interpretation, persuasion, and presenting a clear point of view.", "u": null, "notes": "concept: NI001517164543", "dep": null}, {"v": "01014", "n": "CI English Language", "d": "Cambridge International (CI) English Language courses prepare students to take the Cambridge English Language assessments. These courses teach students to critically respond to a variety of texts in a range of forms, styles, and contexts, and promote skills of communication, reading, research, and analysis. Students will gain an understanding of English language features and issues as well as develop writing skills for different purposes and audiences.", "u": null, "notes": "concept: NI001517164544", "dep": null}, {"v": "01070", "n": "CI English Literature", "d": "Cambridge International (CI) English Literature courses prepare students to take the Cambridge English Literature assessments. These courses teach students the three main forms of literature; prose, poetry, and drama, through texts from a wide range of different periods and cultures. Students will learn to read, analyze, and discuss the critical context of literature as well as develop skills of effective and appropriate communication.", "u": null, "notes": "concept: NI001517164545", "dep": null}, {"v": "24267", "n": "IB Language A: Language and Literature�German", "d": "IB Language A: Language and Literature�German courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using German in an academic context.", "u": null, "notes": "concept: NI001517162914", "dep": null}, {"v": "24268", "n": "IB Language Ab Initio�German", "d": "IB Language Ab Initio�German courses prepare students to take the International Baccalaureate exam. These courses focus on developing the linguistic abilities of students with little or no experience with the language of study. Course content includes the study of individuals and society, leisure and work, and urban and rural environments. These courses also provide students with the opportunity to practice and explore this language.", "u": null, "notes": "concept: NI001517162915", "dep": null}, {"v": "24299", "n": "German�Other", "d": "Other German courses", "u": null, "notes": "concept: NI001517162916", "dep": null}, {"v": "24300", "n": "Greek for Young Learners (prior-to-secondary)", "d": "Greek for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Greek and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162917", "dep": null}, {"v": "24301", "n": "Greek Immersion (prior-to-secondary)", "d": "Greek Immersion (prior-to-secondary) courses engage students in developmentally appropriate activities to acquire literacy in Greek and grade-specific content using Greek as the language of instruction. Greek Immersion courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information about standards-based academic content and incorporate the relationships among the products, practices, and perspectives of Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162918", "dep": null}, {"v": "24302", "n": "Greek I", "d": "Designed to introduce students to Greek language and culture, Greek I courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162919", "dep": null}, {"v": "24304", "n": "Greek III", "d": "Greek III courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162920", "dep": null}, {"v": "24305", "n": "Greek IV", "d": "Greek IV courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Greek IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162921", "dep": null}, {"v": "24308", "n": "Greek Field Experience", "d": "Greek Field Experience courses place students in environments in which they interact with native Greek speakers, typically in settings where Greek is the main language spoken. These courses enable students to strengthen their skills in exchanging (speaking/listening and writing/reading), interpreting (reading, listening, and viewing), and presenting information and their ability to interact in culturally appropriate ways.", "u": null, "notes": "concept: NI001517162922", "dep": null}, {"v": "24352", "n": "IB Classical Languages�Latin", "d": "IB Classical Languages�Latin courses seek to strike a balance between the study of the classic Latin language itself (structure, meaning, and formulation) and the civilization it reflects (particularly its culture, philosophies, and institutions). Course content enables students to understand, translate, and appreciate a classical Latin text; relate literature to its historical or social background; recognize current relevance of ancient literature; and apply acquired knowledge to other subjects.", "u": null, "notes": "concept: NI001517162923", "dep": null}, {"v": "24355", "n": "AP Latin (Virgil, Catullus and Horace)", "d": "Designed to parallel advanced college-level courses in Latin studies, AP Latin courses build upon and increase knowledge of Latin, enabling students to read the language with comprehension, to accurately translate Latin into English, and to appreciate the stylistic literary techniques used by the authors. AP Latin courses also include study of the political, social, and cultural background of the literary works and their authors, as well as their influence on later literature.", "u": null, "notes": "concept: NI001517162924", "dep": null}, {"v": "24369", "n": "Latin�Other", "d": "Other Latin courses.", "u": null, "notes": "concept: NI001517162925", "dep": null}, {"v": "24370", "n": "Classical Greek for Young Learners (prior-to-secondary)", "d": "Classical Greek for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Classical Greek and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Classical Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162926", "dep": null}, {"v": "24309", "n": "Greek Conversation and Culture", "d": "Greek Conversation and Culture courses provide students with an introduction to the Greek language and the culture(s) of Greek-speaking people, placing greater emphasis on speaking and listening skills while deemphasizing writing and reading the language.", "u": null, "notes": "concept: NI001517162927", "dep": null}, {"v": "24310", "n": "Greek Literature", "d": "Greek Literature courses prepare students to communicate authentically in Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, opinions, and ideas drawn from literature written in Greek. Emphasis is typically placed on critical and analytical reading and writing, understanding the integration of Greek cultures into literature, and exploring interdisciplinary connections.", "u": null, "notes": "concept: NI001517162928", "dep": null}, {"v": "24311", "n": "Particular Topics in Greek", "d": "Particular Topics in Greek courses examine particular topics focused on Greek language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162929", "dep": null}, {"v": "24312", "n": "IB Language A: Literature�Greek", "d": "IB Language A: Literature�Greek courses prepare students to take the International Baccalaureate Language A: Literature exams. Course content includes in-depth study of a range of literary texts in a number of literary forms and from different times and places, written analyses and critiques of this literature, and other oral and written assignments. The course is designed for students highly competent in using Greek in an academic context and is intended for students with native or near-native fluency in the language.", "u": null, "notes": "concept: NI001517162930", "dep": null}, {"v": "24316", "n": "IB Language B (Greek), Middle Years Program", "d": "This course allows students to gain competence in modern Greek and encourages respect for and understanding of other languages and cultures.", "u": null, "notes": "concept: NI001517162931", "dep": null}, {"v": "24317", "n": "IB Language A: Language and Literature�Greek", "d": "IB Language A: Language and Literature�Greek courses prepare students to take the International Baccalaureate Language A: Language and Literature exams. Course content includes in-depth study of various text types and literary forms, composition for purpose and audience, and the context and elements of literature. The course includes oral and written assignments and is designed for students highly competent in using Greek in an academic context.", "u": null, "notes": "concept: NI001517162932", "dep": null}, {"v": "24339", "n": "Greek�Other", "d": "Other Greek courses.", "u": null, "notes": "concept: NI001517162933", "dep": null}, {"v": "24340", "n": "Latin for Young Learners (prior-to-secondary)", "d": "Latin for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Latin and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Latin-speaking cultures.", "u": null, "notes": "concept: NI001517162934", "dep": null}, {"v": "24342", "n": "Latin I", "d": "Designed to introduce students to Latin language and culture, Latin I courses prepare students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Latin-speaking cultures.", "u": null, "notes": "concept: NI001517162935", "dep": null}, {"v": "24343", "n": "Latin II", "d": "Latin II courses build upon skills developed in Latin I, preparing students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Latin II courses introduce the relationships among the products, practices, and perspectives of Latin-speaking cultures.", "u": null, "notes": "concept: NI001517162936", "dep": null}, {"v": "24344", "n": "Latin III", "d": "Latin III courses prepare students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Latin-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162937", "dep": null}, {"v": "24345", "n": "Latin IV", "d": "Latin IV courses prepare students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Latin IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Latin-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162938", "dep": null}, {"v": "24346", "n": "Latin V", "d": "Latin V courses prepare students to communicate authentically in Latin by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Latin V courses promote students' understanding of the relationships among the products, practices, and perspectives of Latin-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162939", "dep": null}, {"v": "24351", "n": "Particular Topics in Latin", "d": "Particular Topics in Latin courses examine particular topics focused on Latin language or culture, such as film, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162940", "dep": null}, {"v": "24372", "n": "Classical Greek I", "d": "Designed to introduce students to Classical Greek language and culture, Classical Greek I courses prepare students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Classical Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162941", "dep": null}, {"v": "24399", "n": "Classical Hebrew�Other", "d": "Other Classical Hebrew courses.", "u": null, "notes": "concept: NI001517162942", "dep": null}, {"v": "24373", "n": "Classical Greek II", "d": "Classical Greek II courses build upon skills developed in Classical Greek I, preparing students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Classical Greek II courses introduce the relationships among the products, practices, and perspectives of Classical Greek-speaking cultures.", "u": null, "notes": "concept: NI001517162943", "dep": null}, {"v": "24374", "n": "Classical Greek III", "d": "Classical Greek III courses prepare students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Classical Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162944", "dep": null}, {"v": "24375", "n": "Classical Greek IV", "d": "Classical Greek IV courses prepare students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Classical Greek IV courses promote students' understanding of the relationships among the products, practices, and perspectives of Classical Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162945", "dep": null}, {"v": "24376", "n": "Classical Greek V", "d": "Classical Greek V courses prepare students to communicate authentically in Classical Greek by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. Classical Greek V courses promote students' understanding of the relationships among the products, practices, and perspectives of Classical Greek-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162946", "dep": null}, {"v": "24381", "n": "Particular Topics in Classical Greek", "d": "Particular Topics in Classical Greek courses examine particular topics focused on Classical Greek language or culture, such as drama, music, application(s) to career/technical fields, or a specific dialect, other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517162947", "dep": null}, {"v": "24382", "n": "IB Classical Languages�Greek", "d": "IB Classical Languages�Greek courses seek to strike a balance between the study of the classic Greek language itself (structure, meaning, and formulation) and the civilization it reflects (particularly its culture, philosophies, and institutions). Course content enables students to understand, translate, and appreciate a classical Greek text; relate literature to its historical or social background; recognize current relevance of ancient literature; and apply acquired knowledge to other subjects.", "u": null, "notes": "concept: NI001517162948", "dep": null}, {"v": "24389", "n": "Classical Greek�Other", "d": "Other Classical Greek courses.", "u": null, "notes": "concept: NI001517162949", "dep": null}, {"v": "24390", "n": "Classical Hebrew for Young Learners (prior-to-secondary)", "d": "Classical Hebrew for Young Learners (prior-to-secondary) courses provide instruction at multiple grade levels in Classical Hebrew and may apply to a range of consecutive grades. These courses prepare students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. These courses introduce the relationships among the products, practices, and perspectives of Classical Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517162950", "dep": null}, {"v": "24391", "n": "Classical Hebrew I", "d": "Designed to introduce students to Classical Hebrew language and culture, Classical Hebrew I courses prepare students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on a variety of topics. They introduce the relationships among the products, practices, and perspectives of Classical Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517162951", "dep": null}, {"v": "24392", "n": "Classical Hebrew II", "d": "Classical Hebrew II courses build upon skills developed in Classical Hebrew I, preparing students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information on concrete topics. Classical Hebrew II courses introduce the relationships among the products, practices, and perspectives of Classical Hebrew-speaking cultures.", "u": null, "notes": "concept: NI001517162952", "dep": null}, {"v": "24393", "n": "Classical Hebrew III", "d": "Classical Hebrew III courses prepare students to communicate authentically in Classical Hebrew by interpreting (reading, listening, viewing), exchanging (speaking and listening; reading and writing), and presenting (speaking, writing) information, concepts, and ideas on a variety of topics, including connections to other subject areas. These courses expand students' knowledge of relationships among the products, practices, and perspectives of Classical Hebrew-speaking countries and cultures.", "u": null, "notes": "concept: NI001517162953", "dep": null}, {"v": "01130", "n": "Writing (kindergarten)", "d": "Writing (kindergarten) courses engage students in activities to develop their writing skills. Course content may emphasize storytelling or personal expression. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163221", "dep": null}, {"v": "01131", "n": "Writing (grade 1)", "d": "Writing (grade 1) courses focus on writing skills and may emphasize recognition and creation of various types of text; extension of vocabulary and writing skills; and the connection of language to the expression of ideas. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163222", "dep": null}, {"v": "01132", "n": "Writing (grade 2)", "d": "Writing (grade 2) courses focus on writing skills and may build students' skills in independent writing by increasing writing fluency, vocabulary, and recognition of word and language patterns. They may also introduce or reinforce the rules of grammar and spelling. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163223", "dep": null}, {"v": "01133", "n": "Writing (grade 3)", "d": "Writing (grade 3) courses focus on writing skills and may emphasize independent writing in a variety of assignments. Some emphasis may also be placed on presentation skills. Specific content depends upon state standards for grade 3.", "u": null, "notes": "concept: NI001517163224", "dep": null}, {"v": "01134", "n": "Writing (grade 4)", "d": "Writing (grade 4) courses focus on writing skills and may emphasize independent writing in a variety of assignments and require students to respond to different materials in different ways. Grammar and usage of the English language may also be emphasized. Specific content depends upon state standards for grade 4.", "u": null, "notes": "concept: NI001517163225", "dep": null}, {"v": "01135", "n": "Writing (grade 5)", "d": "Writing (grade 5) courses focus on writing skills and may extend students' skills in writing for particular purposes or audiences, distinguishing meaning and literary functions in texts, and fluency in writing. Specific content depends upon state standards for grade 5.", "u": null, "notes": "concept: NI001517163226", "dep": null}, {"v": "01098", "n": "Literature�Workplace Experience", "d": "Literature�Workplace Experience courses provide work experience in a field related to English literature. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163227", "dep": null}, {"v": "01099", "n": "Literature�Other", "d": "Other Literature courses.", "u": null, "notes": "concept: NI001517163228", "dep": null}, {"v": "01101", "n": "English/Composition (freshmen and sophomores)", "d": "English/Composition (freshmen and sophomores) courses are designed for freshmen and/or sophomores and build upon previous writing skills. These courses seek to develop the writing processes and practices necessary for producing successful high school compositions. Students typically learn to write persuasive, critical, and creative multiparagraph essays and compositions. While emphasizing composition, these courses may also incorporate some literature study to expose students to exemplary illustrations of various forms of writing.", "u": null, "notes": "concept: NI001517163229", "dep": null}, {"v": "01102", "n": "English/Composition (juniors and seniors)", "d": "English/Composition (juniors and seniors) courses are designed for juniors and/or seniors and build upon previous writing skills. Reinforcing the logic and critical-thinking skills that accompany good writing, these courses�which emphasize word choice, usage, and writing mechanics�provide continued and advanced instruction in writing for a variety of purposes and audiences. English/Composition (juniors and seniors) courses may emphasize college or business preparation; literature study may be offered as an additional component in which students analyze examples of several genres.", "u": null, "notes": "concept: NI001517163230", "dep": null}, {"v": "01103", "n": "Composition", "d": "Composition courses focus on students' writing skills and develop their ability to compose different types of papers for a range of purposes and audiences. These courses enable students to explore and practice descriptive, narrative, persuasive, or expositive styles as they write paragraphs, essays, letters, applications, formal documented papers, or technical reports. Although composition courses may present some opportunities for creative writing, their focus usually remains on nonfiction, scholarly, or formal writing.", "u": null, "notes": "concept: NI001517163231", "dep": null}, {"v": "01104", "n": "Creative Writing", "d": "Creative Writing courses offer students the opportunity to develop and improve their technique and individual style in poetry, short story, drama, essays, and other forms of prose. The emphasis of the courses is on writing; however, students may study exemplary representations and authors to obtain a fuller appreciation of the form and craft. Although most creative writing classes cover several expressive forms, others concentrate exclusively on one particular form (such as poetry or playwriting).", "u": null, "notes": "concept: NI001517163232", "dep": null}, {"v": "01149", "n": "Composition�Other", "d": "Other Composition courses.", "u": null, "notes": "concept: NI001517163233", "dep": null}, {"v": "01995", "n": "English Language and Literature�Aide", "d": "English Language and Literature�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163234", "dep": null}, {"v": "01996", "n": "English Language and Literature�Supplemental", "d": "English Language and Literature�Supplemental courses, designed to be taken in addition to or in coordination with other English language and literature courses, provide instruction to assist students in acquiring English language arts skills so that students attain necessary grade-level skills or reach a desired competency level.", "u": null, "notes": "concept: NI001517163235", "dep": null}, {"v": "01997", "n": "English Language and Literature�Independent Study", "d": "English Language and Literature�Independent study courses, often conducted with instructors as mentors, allow students to explore particular topics within the field of language arts. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163236", "dep": null}, {"v": "01998", "n": "English Language and Literature�Workplace Experience", "d": "English Language and Literature�Workplace Experience courses provide students with work experience in a field related to English language or literature. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163237", "dep": null}, {"v": "01999", "n": "English Language and Literature�Other", "d": "Other English Language and Literature courses.", "u": null, "notes": "concept: NI001517163238", "dep": null}, {"v": "01151", "n": "Public Speaking", "d": "Public Speaking courses enable students, through practice, to develop communication skills that can be used in a variety of speaking situations (such as small and large group discussions, delivery of lectures or speeches in front of audiences, and so on). Course topics may include (but are not limited to) research and organization, writing for verbal delivery, stylistic choices, visual and presentation skills, analysis and critique, and development of self-confidence.", "u": null, "notes": "concept: NI001517163239", "dep": null}, {"v": "01152", "n": "Forensic Speech�Inclusive", "d": "Forensic Speech�Inclusive courses offer students the opportunity to learn how to use oral skills effectively in formal and informal situations. Students learn such skills as logic and reasoning, the organization of thought and supporting materials, and effective presentation of one's voice and body. Often linked to an extracurricular program, these courses introduce students to numerous public speaking situations, and they learn the methods, aims, and styles of a variety of events (e.g., formal debate, Lincoln-Douglas debate, expository speaking, radio broadcast, oral interpretation, and dramatic interpretation). Participation in competition is encouraged, but not always required.", "u": null, "notes": "concept: NI001517163240", "dep": null}, {"v": "01153", "n": "Forensic Speech�Debate", "d": "Forensic Speech�Debate courses offer students the opportunity to learn how to use oral skills in formal and informal situations. In these courses, students are able to develop such skills as logic and reasoning, research and analysis, organization of thought and supporting materials, argumentative style and skill, and effective presentation of one's voice and body. Often linked to an extracurricular program, these courses introduce students to the methods, aims, and styles used in various kinds of debates (formal debate or Lincoln-Douglas). Participation in competition is encouraged, but not always required.", "u": null, "notes": "concept: NI001517163241", "dep": null}, {"v": "01199", "n": "Speech�Other", "d": "Other Speech courses.", "u": null, "notes": "concept: NI001517163247", "dep": null}, {"v": "01154", "n": "Forensic Speech�Individual Event", "d": "Forensic Speech�Individual Event courses offer students the opportunity to learn how to use oral skills in formal and informal situations. Topics included depend upon the event(s) being taught, but they usually emphasize effective presentation of one's voice and body, thoughtful understanding and interpretation of literature, logic and reasoning, and the organization of thought and supporting materials. Often linked to an extracurricular program, these courses introduce students to one or several individual event categories (e.g., exposition, oral interpretation, dramatic interpretation, and radio broadcast). Participation in competition is encouraged, but not always required.", "u": null, "notes": "concept: NI001517163242", "dep": null}, {"v": "01155", "n": "Communications", "d": "Communications courses focus on the application of written and oral communication skills through a variety of formal and informal experiences. The courses are performance-based and emphasize effective interpersonal and team-building skills. Communications courses may also involve the study of how interpersonal communications are affected by stereotypes, nonverbal cues, vocabulary, and stylistic choices.", "u": null, "notes": "concept: NI001517163243", "dep": null}, {"v": "01156", "n": "Applied English and Communications", "d": "Applied English and Communications courses teach students communication skills�reading, writing, listening, speaking�concentrating on \"real-world\" applications. These courses usually emphasize the practical application of communication as a business tool�using technical reports and manuals, business letters, resumes, and applications as examples�rather than emphasize language arts skills as applied to scholarly and literary materials.", "u": null, "notes": "concept: NI001517163244", "dep": null}, {"v": "01197", "n": "Speech�Independent Study", "d": "Speech�Independent Study courses, often conducted with instructors as mentors, allow students to explore particular topics within the field of language arts (emphasizing speech). Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163245", "dep": null}, {"v": "01198", "n": "Speech�Workplace Experience", "d": "Speech�Workplace Experience courses provide work experience in a field related to public speaking and speech. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163246", "dep": null}, {"v": "01201", "n": "English Morphology and Grammar", "d": "English Morphology and Grammar courses involve the study of the English language�its roots and derivations, structure and sentence patterns, dialects, writing and spelling systems, and uses as a communication tool.", "u": null, "notes": "concept: NI001517163248", "dep": null}, {"v": "01202", "n": "History of the English Language", "d": "History of the English Language courses trace the development of English, concentrating on historical and cultural influences and how the language has changed over time. Although language roots, structures, and dialects may be examined, the emphasis remains on the process of language development rather than on morphology.", "u": null, "notes": "concept: NI001517163249", "dep": null}, {"v": "01203", "n": "English�Test Preparation", "d": "English�Test Preparation courses provide students with activities in analytical thinking and with the skills and strategies associated with standardized test taking. Topics covered include vocabulary, reading comprehension, and writing strategies, as well as time management, scoring procedures, and dealing with test-related stress. Course materials may include national and state standardized test review materials (such as ACT, SAT, or PSAT test review materials), current assessment software programs, and previous standardized examinations.", "u": null, "notes": "concept: NI001517163250", "dep": null}, {"v": "01204", "n": "English Grammar", "d": "English Grammar courses focus on the structure of the formal standard American English language, involving sentence structure; parts of speech; the function of words, phrases, and clauses; and proper punctuation.", "u": null, "notes": "concept: NI001517163251", "dep": null}, {"v": "01992", "n": "English Proficiency Development", "d": "English Proficiency Development courses are designed to assist students in acquiring the skills necessary to pass proficiency examinations.", "u": null, "notes": "concept: NI001517163252", "dep": null}, {"v": "02001", "n": "Informal Mathematics", "d": "Informal Mathematics courses emphasize the teaching of mathematics as problem solving, communication, and reasoning, and highlight the connections among mathematical topics and between mathematics and other disciplines. These courses approach the teaching of general mathematics, pre-algebra, and pre-geometry topics by applying numbers, and algebraic and geometric concepts and relationships to real world problems.", "u": null, "notes": "concept: NI001517163253", "dep": null}, {"v": "02047", "n": "Foundation Mathematics�Independent Study", "d": "Foundation Mathematics�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to foundation mathematics. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163254", "dep": null}, {"v": "02049", "n": "Foundation Mathematics�Other", "d": "Other Foundation Mathematics courses.", "u": null, "notes": "concept: NI001517163255", "dep": null}, {"v": "02051", "n": "Pre-Algebra", "d": "Pre-Algebra courses increase students' foundational mathematics skills and prepare them for Algebra I by covering a variety of topics, such as properties of rational numbers (i.e., number theory), ratio, proportion, estimation, exponents and radicals, the rectangular coordinate system, sets and logic, formulas, and solving first-degree equations and inequalities.", "u": null, "notes": "concept: NI001517163256", "dep": null}, {"v": "02052", "n": "Algebra I", "d": "Algebra I courses include the study of properties and operations of the real number system; evaluating rational algebraic expressions; solving and graphing first-degree equations and inequalities; translating word problems into equations; operations with and factoring of polynomials; solving quadratic equations; and modeling linear data. Specific content depends upon state standards.", "u": null, "notes": "concept: NI001517163257", "dep": null}, {"v": "02053", "n": "Algebra I�Part 1", "d": "The first part in a multipart sequence of Algebra I. This course generally covers the same topics as the first semester of Algebra I, including the study of properties of rational numbers (i.e., number theory), ratio, proportion, and estimation, exponents and radicals, the rectangular coordinate system, sets and logic, formulas, and solving first-degree equations and inequalities. Specific content depends upon state standards.", "u": null, "notes": "concept: NI001517163258", "dep": null}, {"v": "02002", "n": "General Mathematics", "d": "General Mathematics courses reinforce and expand students' foundational mathematic skills, such as arithmetic operations using rational numbers; area, perimeter, and volume of geometric figures, congruence and similarity, angle relationships, the Pythagorean theorem, the rectangular coordinate system, sets and logic, ratio and proportion, estimation, formulas, solving and graphing simple equations and inequalities.", "u": null, "notes": "concept: NI001517163259", "dep": null}, {"v": "02003", "n": "Particular Topics in Foundation Mathematics", "d": "These courses examine particular topics in Foundation Mathematics, such as arithmetic, sequences, or basic conceptual skills, rather than provide a general overview.", "u": null, "notes": "concept: NI001517163260", "dep": null}, {"v": "02028", "n": "Mathematics (early childhood education)", "d": "Mathematics (early childhood education) courses cover foundational skills and concepts related to mathematics. Content is age appropriate and conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163261", "dep": null}, {"v": "02029", "n": "Mathematics (pre-kindergarten)", "d": "Mathematics (pre-kindergarten) courses cover foundational skills and concepts related to mathematics. Content is age appropriate and conforms to any existing state standards for pre-kindergarten education.", "u": null, "notes": "concept: NI001517163262", "dep": null}, {"v": "02030", "n": "Mathematics (kindergarten)", "d": "Mathematics (kindergarten) courses typically introduce and reinforce basic concepts of mathematics such as counting whole numbers and understanding patterns. Specific content depends upon state standards for kindergarten.", "u": null, "notes": "concept: NI001517163263", "dep": null}, {"v": "02031", "n": "Mathematics (grade 1)", "d": "Mathematics (grade 1) courses typically help build a conceptual foundation in number, operation, and quantitative reasoning; patterns, relationships, and algebraic thinking; geometry and spatial reasoning; time and non-standard length units. These courses often require students to develop their numerical fluency and to make calculation predictions. Specific content depends upon state standards for grade 1.", "u": null, "notes": "concept: NI001517163264", "dep": null}, {"v": "02032", "n": "Mathematics (grade 2)", "d": "Mathematics (grade 2) courses typically continue to build a conceptual foundation in number, operation, and quantitative reasoning; patterns, relationships, and algebraic thinking; geometry and spatial reasoning; and measurement. Students begin to incorporate the context of time and money. These courses often require students to develop their numerical fluency, particularly in addition and subtraction, and to solve problems using those operations as well as estimation. Specific content depends upon state standards for grade 2.", "u": null, "notes": "concept: NI001517163265", "dep": null}, {"v": "05035", "n": "Dance (grade 5)", "d": "Dance (grade 5) courses typically provide activities that foster creative expression, communication through artistic endeavor, appreciation of culture and heritage, and evaluative and critical thinking using the art of dance. Activities may include those that enable students to develop their technique, learn different styles of dance, appreciate the culture and history of dance forms, and strengthen the ability to discern and critique. Specific course content conforms to any existing state standards for grade 5.", "u": null, "notes": "concept: NI001517163571", "dep": null}, {"v": "05039", "n": "Dance�General", "d": "Dance�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Dance, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163572", "dep": null}, {"v": "05068", "n": "Drama (early childhood education)", "d": "Drama (early childhood education) courses provide developmentally appropriate activities to enable students to express themselves through dramatic play and storytelling. Specific course content conforms to any existing state standards for early childhood education.", "u": null, "notes": "concept: NI001517163573", "dep": null}, {"v": "05069", "n": "Drama (pre-kindergarten)", "d": "Drama (pre-kindergarten) courses provide developmentally appropriate activities to enable students to express themselves through dramatic play and storytelling. Specific course content conforms to any existing state standards for pre-kindergarten.", "u": null, "notes": "concept: NI001517163574", "dep": null}, {"v": "05070", "n": "Drama (kindergarten)", "d": "Drama (kindergarten) courses provide developmentally appropriate activities to enable students to express themselves through dramatic play and storytelling. Specific course content conforms to any existing state standards for kindergarten.", "u": null, "notes": "concept: NI001517163575", "dep": null}, {"v": "05047", "n": "Dance�Independent Study", "d": "Dance�Independent Study courses, often conducted with instructors or professional artists as mentors, provide training in a specific area of emphasis (ballet, tap, jazz, modern, musical theater, world dance, etc.) or in the areas of choreography, production, criticism, etc. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular form or style, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163576", "dep": null}, {"v": "05048", "n": "Dance�Workplace Experience", "d": "Dance�Workplace Experience courses provide students with work experience in a field related to dance. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163577", "dep": null}, {"v": "05049", "n": "Dance�Other", "d": "Other Dance courses.", "u": null, "notes": "concept: NI001517163578", "dep": null}, {"v": "05051", "n": "Introduction to Theater", "d": "Introduction to Theater courses provide an overview of the art, conventions, and history of the theater arts. Although the courses sometimes include experiential exercises, they emphasize learning about theater processes rather than theatrical production and performance. Course topics include one or more of the following: basic techniques in acting, major developments in dramatic literature, major playwrights, the evolution of theater as a cultural tradition, and critical appreciation of the art and craft of the theater profession.", "u": null, "notes": "concept: NI001517163579", "dep": null}, {"v": "05052", "n": "Theater Arts", "d": "Theater Arts courses focus on the study and performance of drama in its many forms, including musical theater, drama, and comedy. These courses review a wide range of scripted materials (such as plays, screenplays, teleplays, readers' theater scripts); dramatic criticism; techniques for creating original dramatic works; and the role of dramatic arts in society. Theater Arts courses typically require students to perform collaboratively, be involved in the critique of dramatic works, and learn methods for self-expression.", "u": null, "notes": "concept: NI001517163580", "dep": null}, {"v": "05053", "n": "Theater�Comprehensive", "d": "Theater�Comprehensive courses help students experience and develop skill in one or more aspects of theatrical production. Introductory courses provide an overview of theatrical elements including acting, set design, stage management, directing, playwriting, and production. Advanced courses concentrate on extending and refining dramatic technique, expanding students' exposure to different types of theatrical styles, genres, and traditions, and increasing their participation in public productions.", "u": null, "notes": "concept: NI001517163581", "dep": null}, {"v": "05055", "n": "Theater�Acting/Performance", "d": "Theater�Acting/Performance courses provide students with experience and skill development in one or more aspects of theatrical production, by concentrating on acting and performance skills. Introductory courses explore fundamental techniques, while advanced courses extend and refine technique, expand students' exposure to different types of theatrical craft and traditions from varied social and historical contexts, and increase their participation in public productions.", "u": null, "notes": "concept: NI001517163582", "dep": null}, {"v": "05056", "n": "Theater�Stagecraft", "d": "Theater�Stagecraft courses provide students with an understanding of the various aspects of theatrical production, including lighting, costuming, sound, set construction, makeup, stage management, and the use of computer and media-based applications. These courses prepare students to engage in the hands-on application of these production elements in design and technology courses.", "u": null, "notes": "concept: NI001517163583", "dep": null}, {"v": "05057", "n": "Theater�Directing", "d": "Theater�Directing courses focus on developing students' skills in translating a script into a final production. Directing courses enable each student to create an artistic vision and develop a personal aesthetic. These courses may expose students to different types of theatrical techniques and traditions. They also provide students with opportunities to direct the performances of others (either in scenes or in a full production).", "u": null, "notes": "concept: NI001517163584", "dep": null}, {"v": "05062", "n": "IB Theatre", "d": "IB Theatre courses prepare students to take the International Baccalaureate (IB) Theatre exams. IB Theatre courses encourage students to examine the theory, history, and culture of theatre. These courses also help students develop the organizational and technical skills to express themselves through scripted performance, workshops, and independent project(s).", "u": null, "notes": "concept: NI001517163589", "dep": null}, {"v": "05058", "n": "Playwriting and Screenwriting", "d": "Formerly known as Playwriting, Playwriting and Screenwriting courses help students understand and employ writing principles and techniques to create original scripts suitable for theater, film, and/or television production. These courses explore the appropriate techniques of each genre and develop a personal voice, style, and aesthetic by examining the work of various playwrights and screenwriters. Students may examine the creative writing craft, scene writing, script development, stage and/or camera instructions, line and moment analysis, script reading, script editing, and the creation of a production.", "u": null, "notes": "concept: NI001517163585", "dep": null}, {"v": "05059", "n": "History and Literature of the Theater", "d": "History and Literature of the Theatre courses explore in depth the structure, elements, and style of dramatic compositions, and, as an extension, how the dramatic literature influenced theatrical production and acting styles throughout history. Some courses may focus more on the literature component than on the theatre (with increased emphasis on critique and analysis), but most courses connect these subjects, exploring their interrelationship. Major contributors (i.e. playwrights, directors, designers) and the architecture of the theater may also be included as topics of study.", "u": null, "notes": "concept: NI001517163586", "dep": null}, {"v": "05060", "n": "Musical Theater", "d": "Musical Theater courses provide students with the opportunity to explore and/or participate in various aspects of musical theater, including auditioning, singing, acting, and dancing. These courses review the history and evolution of musical theatre, its literature and artists, and styles of composition and vocal presentation. Students work collaboratively on performances, including solo, duet, and ensemble work.", "u": null, "notes": "concept: NI001517163587", "dep": null}, {"v": "05061", "n": "Theatrical Production and Management", "d": "Theatrical Production and Management courses prepare students to manage the planning, design, preparation, and production of plays and other theatrical performances. Course content may include instruction in theatrical design, program management, dramatic production, rehearsal management, personnel management and casting, actor coaching, directing concepts and techniques, dramaturgy, script interpretation, business management, marketing, public relations, and communications skills.", "u": null, "notes": "concept: NI001517163588", "dep": null}, {"v": "05071", "n": "Drama (grade 1)", "d": "Drama (grade 1) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Specific course content conforms to any existing state standards for grade 1.", "u": null, "notes": "concept: NI001517163590", "dep": null}, {"v": "05104", "n": "Orchestra", "d": "Orchestra courses help develop students' technique for playing strings along with woodwind, brass, and percussion instruments. These courses may emphasize collaboration through rehearsal and performance experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163591", "dep": null}, {"v": "05105", "n": "Contemporary Instrumental Ensemble", "d": "Formerly known as Contemporary Band, Contemporary Instrumental Ensemble courses help students perform a variety of contemporary styles, such as traditional jazz, jazz improvisation, and rock. At the same time, these courses cultivate students' technique on instruments appropriate to the style(s) performed�brass, woodwind, string, percussion instruments, and/or electronic. These ensembles emphasize instrumental music but may also include vocal music. Advanced coursework provides students with opportunities for growth through rehearsal and performance, improvisation, or creating and performing their own compositions.", "u": null, "notes": "concept: NI001517163592", "dep": null}, {"v": "05106", "n": "Small Ensemble", "d": "Formerly known as Instrumental Ensemble, Small Ensemble courses help students perform a variety of musical styles (e.g., traditional chamber music, jazz, and rock). At the same time, these courses help cultivate students' technique on instruments appropriate to the style(s) performed�brass, woodwind, string, percussion instruments, and/or electronic and provide experiences in creating and responding to music. Courses typically range in size from 2 to 20 performers.", "u": null, "notes": "concept: NI001517163593", "dep": null}, {"v": "05107", "n": "Piano", "d": "Piano courses provide students an introduction to, and refine the fundamentals of, music and keyboard including literature and techniques such as scales, chords, and melodic lines and may offer instruction in more advanced techniques. Formal and informal performances are typically included as well as experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163594", "dep": null}, {"v": "05072", "n": "Drama (grade 2)", "d": "Drama (grade 2) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Specific course content conforms to any existing state standards for grade 2.", "u": null, "notes": "concept: NI001517163595", "dep": null}, {"v": "05073", "n": "Drama (grade 3)", "d": "Drama (grade 3) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Specific course content conforms to any existing state standards for grade 3.", "u": null, "notes": "concept: NI001517163596", "dep": null}, {"v": "05074", "n": "Drama (grade 4)", "d": "Drama (grade 4) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 4.", "u": null, "notes": "concept: NI001517163597", "dep": null}, {"v": "05075", "n": "Drama (grade 5)", "d": "Drama (grade 5) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 5.", "u": null, "notes": "concept: NI001517163598", "dep": null}, {"v": "05076", "n": "Drama (grade 6)", "d": "Drama (grade 6) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. Activities may include those that enable students to refine their technique, increase their artistic vocabulary, express themselves and their world view, and strengthen their critical abilities. Specific course content conforms to any existing state standards for grade 6.", "u": null, "notes": "concept: NI001517163599", "dep": null}, {"v": "05077", "n": "Drama (grade 7)", "d": "Drama (grade 7) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. As appropriate, students may focus on acting techniques and traditions, other aspects of drama (staging, lighting, costuming), or both. Specific course content conforms to any existing state standards for grade 7.", "u": null, "notes": "concept: NI001517163600", "dep": null}, {"v": "05078", "n": "Drama (grade 8)", "d": "Drama (grade 8) courses enable students to express themselves through dramatic play and storytelling. Course content typically includes the use of movement, language, character, plot, and spectacle to portray imaginary or real experiences. As appropriate, students may focus on acting techniques and traditions, other aspects of drama (staging, lighting, costuming), or both. Specific course content conforms to any existing state standards for grade 8.", "u": null, "notes": "concept: NI001517163601", "dep": null}, {"v": "05079", "n": "Drama�General", "d": "Drama�General courses involve content that is not grade differentiated and may apply to a range of consecutive grades (e.g., \"by third grade, students should know and be able to do...\"). These courses include content that may be applicable to states or localities that do not employ grade-level content standards. [These courses provide broad content that is not organized as described elsewhere (i.e., Drama, early childhood education through grade 8).]", "u": null, "notes": "concept: NI001517163602", "dep": null}, {"v": "05097", "n": "Theater�Independent Study", "d": "Theater�Independent Study courses, often conducted with instructors or professional artists as mentors, enable students to focus on a specific area of emphasis within the discipline. These courses enable students to independently explore one or more aspects of theater. Independent Study courses may serve as an opportunity for students to expand expertise in a particular theatrical genre or style, explore a topic in greater detail, or develop more advanced skills.", "u": null, "notes": "concept: NI001517163603", "dep": null}, {"v": "05098", "n": "Theater�Workplace Experience", "d": "Theater�Workplace Experience courses provide work experience in a field related to drama and the theater. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163604", "dep": null}, {"v": "05099", "n": "Theater�Other", "d": "Other Theater courses.", "u": null, "notes": "concept: NI001517163605", "dep": null}, {"v": "05101", "n": "General Band", "d": "General Band courses help students develop techniques for playing brass, woodwind, and percussion instruments and their ability to perform a variety of concert band literature styles. These courses may emphasize rehearsal and performance experiences in a range of styles (e.g., concert, marching, orchestral, and modern) and also include experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163606", "dep": null}, {"v": "05102", "n": "Concert Band", "d": "Courses in Concert Band are designed to promote students' technique for playing brass, woodwind, and percussion instruments and cover a variety of band literature styles, primarily for concert performances and also include experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163607", "dep": null}, {"v": "05103", "n": "Marching Band", "d": "Courses in Marching Band are intended to develop students' technique for playing brass, woodwind, and percussion instruments and cover appropriate band literature styles, primarily for marching performances.", "u": null, "notes": "concept: NI001517163608", "dep": null}, {"v": "05108", "n": "Guitar", "d": "Guitar courses provide students an introduction to, and refine the fundamentals of, music and guitar literature and techniques, such as strumming and chords and may offer instruction in more advanced techniques. These courses may include bass, ukelele and other plucked string instruments. Formal and informal performances are typically included as well as experiences in creating and responding to music.", "u": null, "notes": "concept: NI001517163609", "dep": null}, {"v": "05123", "n": "Recording and Production", "d": "Recording and Production courses provide students with an opportunity to learn and apply skills in music recording techniques, music editing, mixing, and creating finished musical recordings for distribution as sound files in order to enhance, convey, and capture the expressive intent of music.", "u": null, "notes": "concept: NI001517163610", "dep": null}, {"v": "10198", "n": "Computer Programming�Workplace Experience", "d": "Computer Programming�Workplace Experience courses provide students with work experience in fields related to computer programming. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163880", "dep": null}, {"v": "10199", "n": "Computer Programming�Other", "d": "Other Computer Programming courses.", "u": null, "notes": "concept: NI001517163881", "dep": null}, {"v": "10201", "n": "Web Page Design", "d": "Web Page Design courses teach students how to design websites by introducing them to and refining their knowledge of site planning, page layout, graphic design, and the use of markup languages�such as Extensible Hypertext Markup, JavaScript, Dynamic HTML, Document Object Model, and Cascading Style Sheets�to develop and maintain a web page. These courses may also cover security and privacy issues, copyright infringement, trademarks, and other legal issues relating to the use of the Internet. Advanced topics may include the use of forms and scripts for database access, transfer methods, and networking fundamentals.", "u": null, "notes": "concept: NI001517163882", "dep": null}, {"v": "10202", "n": "Computer Graphics", "d": "Computer Graphics courses provide students with the opportunity to explore the ways in which computers can produce visual imagery that communicates information and ideas effectively to multiple audiences using a variety of media and formats. Course topics may include principles and elements of design, image creation, image manipulation, and image types.", "u": null, "notes": "concept: NI001517163883", "dep": null}, {"v": "10203", "n": "Interactive Media", "d": "Interactive Media courses provide students with the knowledge and skills to create, design, and produce interactive digital media products and services. The courses may emphasize the development of digitally generated and/or computer-enhanced media. Course topics may include 3D animation, graphic media, web development, and virtual reality. Upon completion of these courses, students may be prepared for industry certification.", "u": null, "notes": "concept: NI001517163884", "dep": null}, {"v": "10204", "n": "Particular Topics in Media Technology", "d": "These courses examine particular topics in internet design and applications other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163885", "dep": null}, {"v": "10205", "n": "Computer Gaming and Design", "d": "Computer Gaming and Design courses prepare students to design computer games by studying design, animation, artistic concepts, digital imaging, coding, scripting, multimedia production, and game play strategies. Advanced course topics include, but are not limited to, level design, environment and 3D modeling, scene and set design, motion capture, and texture mapping.", "u": null, "notes": "concept: NI001517163886", "dep": null}, {"v": "10206", "n": "Mobile Applications", "d": "Mobile Applications courses provide students with opportunities to create applications for mobile devices using a variety of commercial and open source software. These courses typically address the installation and modification of these applications, as well as customer service skills to handle user issues.", "u": null, "notes": "concept: NI001517163887", "dep": null}, {"v": "10247", "n": "Media Technology�Independent Study", "d": "Media Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to media technology. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163888", "dep": null}, {"v": "10110", "n": "Microsoft Certified Professional (MCP)", "d": "Microsoft Certified Professional courses provide students with the knowledge and skills necessary to be employed as a network administrator in the latest Windows server-networking environment. Topics include installing, configuring, and trouble-shooting the Windows server. These courses prepare students to set up network connections; manage security issues and shares; and develop policies. Students are typically encouraged to take the MCP exam.", "u": null, "notes": "concept: NI001517163889", "dep": null}, {"v": "10111", "n": "Particular Topics in Networking Systems", "d": "These courses examine particular topics in networking systems other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163890", "dep": null}, {"v": "10112", "n": "Local Area Networking", "d": "Local Area Networking courses introduce students to local area networking (LAN) administration skills, operating systems, basic user skills, defining network objects, building a simple LAN topology applying principles of cabling, LAN switching, designing file systems, managing user access, securing file systems, working with directory service software security, implementing network printing, implementing login scripts, and managing user environments.", "u": null, "notes": "concept: NI001517163891", "dep": null}, {"v": "10147", "n": "Networking Systems�Independent Study", "d": "Networking Systems�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to networking systems. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163892", "dep": null}, {"v": "10148", "n": "Networking Systems�Workplace Experience", "d": "Networking Systems�Workplace Experience courses provide students with work experience in fields related to networking systems. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163893", "dep": null}, {"v": "10149", "n": "Networking Systems�Other", "d": "Other Networking Systems courses.", "u": null, "notes": "concept: NI001517163894", "dep": null}, {"v": "10151", "n": "Business Programming", "d": "Business Programming courses provide students with experience in using previously written software packages. Topics may include loops, arrays, and functions as well as instruction on how to design and write programs of their own. These courses contain a business industry focus and provide an overview of the principles of object-oriented design and programming (e.g., Visual Basic [VB], C++, Java, RPL) related to the business industry.", "u": null, "notes": "concept: NI001517163895", "dep": null}, {"v": "10152", "n": "Computer Programming", "d": "Computer Programming courses provide students with the knowledge and skills necessary to construct computer programs in one or more languages. Computer coding and program structure are often introduced with the BASIC language, but other computer languages, such as Visual Basic (VB), Java, Pascal, C++, and C#, may be used instead. Students learn to structure, create, document, and debug computer programs. Advanced courses may include instruction in object-oriented programming to help students develop applications for Windows, database, multimedia, games, mobile and/or Web environments. An emphasis is placed on design, style, clarity, and efficiency. In these courses, students apply the skills they learn to relevant authentic applications.", "u": null, "notes": "concept: NI001517163896", "dep": null}, {"v": "10253", "n": "Information Support and Services", "d": "Information Support and Services courses prepare students to assist users of personal computers by diagnosing their problems in using application software packages and maintaining security requirements.", "u": null, "notes": "concept: NI001517163897", "dep": null}, {"v": "11056", "n": "Particular Topics in Audio/Video Technology and Film", "d": "These courses examine specific topics in audio and video technology and film other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163898", "dep": null}, {"v": "11097", "n": "Audio/Video Technology and Film�Independent Study", "d": "Audio/Video Technology and Film�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to A/V technology or film. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163899", "dep": null}, {"v": "11098", "n": "Audio/Video Technology and Film�Workplace Experience", "d": "Audio/Video Technology and Film�Workplace Experience courses provide students with work experience in a field related to audio/visual technology and/or film. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163900", "dep": null}, {"v": "11099", "n": "Audio/Video Technology and Film�Other", "d": "Other Audio/Video Technology and Film courses.", "u": null, "notes": "concept: NI001517163901", "dep": null}, {"v": "11101", "n": "Journalism", "d": "Journalism courses (typically associated with the production of a school newspaper, yearbook, or literary magazine) emphasize writing style and technique as well as production values and organization. Journalism courses introduce students to the concepts of newsworthiness and press responsibility; develop students' skills in writing and editing stories, headlines, and captions; and teach students the principles of production design, layout, and printing. Photography, photojournalism, and digital technology skills may be included.", "u": null, "notes": "concept: NI001517163902", "dep": null}, {"v": "11102", "n": "Photojournalism", "d": "Photojournalism courses expose students to the manner in which photography is used to convey information and experiences. Typically coordinated with production of the school newspaper, yearbook, or other media product, photojournalism courses provide students with the opportunity to improve their photo composition and digital technology skills, and to apply their art to journalistic endeavors. These courses may also cover film development.", "u": null, "notes": "concept: NI001517163903", "dep": null}, {"v": "10254", "n": "IT Essentials: PC Hardware and Software", "d": "IT Essentials: PC Hardware and Software courses provide students with in-depth exposure to computer hardware and operating systems. Course topics include the functionality of hardware and software components as well as suggested best practices in maintenance and safety issues. Students learn to assemble and configure a computer, install operating systems and software, and troubleshoot hardware and software problems. In addition, these courses introduce students to networking and often prepare them for industry certification.", "u": null, "notes": "concept: NI001517163904", "dep": null}, {"v": "10255", "n": "CISCO�The Panduit Network Infrastructure Essentials (PNIE)", "d": "CISCO�PNIE courses provide students with the knowledge to create innovative network infrastructure solutions. These courses offer students basic cable installer information and help them acquire the skills to build and use the physical layer of network infrastructure and develop a deeper understanding of networking devices.", "u": null, "notes": "concept: NI001517163905", "dep": null}, {"v": "10256", "n": "Particular Topics in Information Support and Services", "d": "These courses examine particular topics in computer support, maintenance, and repair other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163906", "dep": null}, {"v": "10297", "n": "Information Support and Services�Independent Study", "d": "Information Support and Services�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics related to computer information support and services. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163907", "dep": null}, {"v": "10298", "n": "Information Support and Services�Workplace Experience", "d": "Information Support and Services�Workplace Experience courses provide students with work experience in fields related to information support and/or service. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163908", "dep": null}, {"v": "10299", "n": "Information Support and Services�Other", "d": "Other Information Support and Services courses.", "u": null, "notes": "concept: NI001517163909", "dep": null}, {"v": "10301", "n": "Computer Forensics", "d": "Computer Forensics courses address the preservation, identification, extraction, documentation, and interpretation of computer data. Topics covered may include legal concepts, evidence handling and preservation, file system structures, chain of custody, and identification and recovery of computer data. These courses may also cover the need to perform an investigation and how to collect evidence and analyze data.", "u": null, "notes": "concept: NI001517163910", "dep": null}, {"v": "10302", "n": "Cyber Crime", "d": "Cyber Crime courses cover legal and ethical behavior associated with network security. Topics may include discussions about current common practices used to secure networks, how to test these networks, and presents methods that can be used to create a secure network environment. These courses may also cover the impact federal and state legislation has had on information technology practices.", "u": null, "notes": "concept: NI001517163911", "dep": null}, {"v": "10995", "n": "Information Technology�Aide", "d": "Formerly Computer and Information Sciences�Aide, Information Technology�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517163912", "dep": null}, {"v": "10997", "n": "Information Technology�Independent Study", "d": "Formerly Computer and Information Sciences�Independent Study, Information Technology�Independent Study courses, often conducted with instructors as mentors, enable students to explore computer-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular specialization, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163913", "dep": null}, {"v": "10998", "n": "Information Technology�Workplace Experience", "d": "Formerly Computer and Information Sciences �Workplace Experience, Information Technology�Workplace Experience courses provide students with work experience in fields related to computer and/or information sciences. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163914", "dep": null}, {"v": "10999", "n": "Information Technology�Other", "d": "Other Information Technology courses.", "u": null, "notes": "concept: NI001517163915", "dep": null}, {"v": "11001", "n": "Introduction to Communication", "d": "Introduction to Communication courses enable students to understand and critically evaluate the role of media in society. Course content typically includes investigation of visual images, printed material, and audio segments as tools of information, entertainment, and communication to influence opinion; improvement of presentation and evaluative skills in relation to mass media; recognition of various techniques for delivery of a particular message; and, in some cases, creation of a media product. The course may concentrate on a particular medium.", "u": null, "notes": "concept: NI001517163916", "dep": null}, {"v": "11002", "n": "Communication Technology", "d": "Communication Technology courses enable students to effectively communicate ideas and information through experiences dealing with drafting, design, electronic communication, graphic arts, printing process, photography, telecommunications, and computers. Additional topics covered in the course include information storage and retrieval. Drafting equipment may be used to make scale drawings, including multi-view drawing, photographs, and poster mock-ups.", "u": null, "notes": "concept: NI001517163917", "dep": null}, {"v": "11003", "n": "Particular Topics in Communication", "d": "These courses examine specific topics in communication other than those already described elsewhere in this classification system.", "u": null, "notes": "concept: NI001517163918", "dep": null}, {"v": "11004", "n": "Social Media", "d": "Social Media courses expose students to various types of social media and how social media has influenced society. These courses emphasize the forms, functions, regulations, implications, and utilization of social media.", "u": null, "notes": "concept: NI001517163919", "dep": null}, {"v": "11047", "n": "Communication�Independent Study", "d": "Communication�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to mass communications. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517163920", "dep": null}, {"v": "11048", "n": "Communication�Workplace Experience", "d": "Communication�Workplace Experience courses provide students with work experience in a field related to communication. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517163921", "dep": null}, {"v": "11049", "n": "Communication�Other", "d": "Other Communication courses.", "u": null, "notes": "concept: NI001517163922", "dep": null}, {"v": "17059", "n": "Plumbing and Heating", "d": "Plumbing and Heating courses address the installation, assembly, maintenance, and repair of piping, plumbing, heating equipment, and water and drainage systems. Topics covered include the computation of heat losses and BTU requirements and blueprint reading. Students gain experience with electric, gas, and oil furnaces; vacuum pumps; air compressors; and mechanical and pneumatic testing equipment.", "u": null, "notes": "concept: NI001517164220", "dep": null}, {"v": "17097", "n": "Air Conditioning, Heating and Plumbing�Independent Study", "d": "Air Conditioning, Heating, and Plumbing�Independent Study courses, often conducted with instructors as mentors, enable students to explore topics of interest related to air conditioning, heating and plumbing. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164221", "dep": null}, {"v": "17148", "n": "Electricity/Electronics�Workplace Experience", "d": "Electricity/Electronics�Workplace Experience courses provide students with work experience in a field related to electricity and/or electronics. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164222", "dep": null}, {"v": "17149", "n": "Electricity/Electronics�Other", "d": "Other Electricity/Electronics courses.", "u": null, "notes": "concept: NI001517164223", "dep": null}, {"v": "17995", "n": "Architecture and Construction�Aide", "d": "Architecture and Construction�Aide courses offer students the opportunity to assist instructors in preparing, organizing, or delivering course curricula. Students may provide tutorial or instructional assistance to other students.", "u": null, "notes": "concept: NI001517164224", "dep": null}, {"v": "17997", "n": "Architecture and Construction�Independent study", "d": "Architecture and Construction�Independent Study courses, often conducted with instructors as mentors, enable students to explore architecture and construction-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164225", "dep": null}, {"v": "17998", "n": "Architecture and Construction�Workplace Experience", "d": "Architecture and Construction�Workplace Experience courses provide students with work experience in a field related to architecture or construction. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164226", "dep": null}, {"v": "17098", "n": "Air Conditioning, Heating and Plumbing�Workplace Experience", "d": "Air Conditioning, Heating, and Plumbing�Workplace Experience courses provide work experience in a field related to air conditioning, heating, and/or plumbing. Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164227", "dep": null}, {"v": "17099", "n": "Air Conditioning, Heating and Plumbing�Other", "d": "Other Air Conditioning, Heating and Plumbing courses.", "u": null, "notes": "concept: NI001517164228", "dep": null}, {"v": "17101", "n": "Exploration of Electricity/Electronics", "d": "Exploration of Electricity/Electronics courses offer instruction in the theory of electricity and in the terminology, skills, and safety procedures common to careers involving electricity and electronics. Topics include (but are not limited to) Ohm's law, electrical equipment, wire systems, and so on; career exploration is often (but not always) an integral part of these courses.", "u": null, "notes": "concept: NI001517164229", "dep": null}, {"v": "17102", "n": "Electricity�Comprehensive", "d": "Electricity�Comprehensive courses provide a survey of the theory, terminology, equipment, and practical experience in the skills needed for careers in the electrical field. These courses typically include AC and DC circuitry, safety, and the National Electrical Code and may cover such skills as those involved in building circuits; wiring residential, commercial, and/or industrial buildings; installing lighting, power circuits, and cables; and estimating job costs. As students progress, their projects become more complex and expansive. In these courses, safety is stressed, and a career exploration component may be offered.", "u": null, "notes": "concept: NI001517164230", "dep": null}, {"v": "17103", "n": "Residential Wiring", "d": "Covering many of the same topics as Electricity�Comprehensive courses, Residential Wiring courses apply the knowledge and skills that students acquire to the electrical systems found in family dwellings. Because these courses emphasize residential electricity, topics may also include cable installation, telephone systems, and the installation of lighting fixtures, outlets, and so on. Maintenance and repair skills are often included as course topics.", "u": null, "notes": "concept: NI001517164231", "dep": null}, {"v": "17104", "n": "Industrial Electricity", "d": "Covering many of the same topics as Electricity�Comprehensive courses, Industrial Electricity courses apply the knowledge and skills that students acquire to the electrical systems used in industry. Because of this emphasis, these courses may also cover the installation of transformers and control devices, emergency generator systems, and other industrial applications.", "u": null, "notes": "concept: NI001517164232", "dep": null}, {"v": "17105", "n": "Particular Topics in Electricity", "d": "These courses provide students with specialized knowledge and help them develop skills in particular topics concerning the nature, behavior, and application of electrical current.", "u": null, "notes": "concept: NI001517164233", "dep": null}, {"v": "17106", "n": "Electronics�Comprehensive", "d": "Electronics�Comprehensive courses provide a survey of the theory, terminology, equipment, and practical experience in the skills needed for careers in the electronic field as well as typically cover the theory of electricity. Course topics may include AC, DC, analog, and integrated circuitry and solid state and digital devices, amplifiers, and semiconductors. Skills covered may involve the repair, maintenance, and building of electronic equipment such as radios, television sets, and industrial equipment.", "u": null, "notes": "concept: NI001517164234", "dep": null}, {"v": "17107", "n": "Particular Topics in Electronics", "d": "Individual courses in this category offer specialized training in topics related to electronics such as diodes, transistors, digital techniques, solid-state devices, analog circuits, and microprocessors.", "u": null, "notes": "concept: NI001517164235", "dep": null}, {"v": "17108", "n": "Electricity/Electronics�General", "d": "Electricity/Electronics�General courses teach fundamental concepts of electricity and electronics, including safety procedures, and may introduce students to the available occupations in electrical and electronic industries. Topics covered typically include components of circuits; reading schematics and diagrams; electricity and electronics as sources of energy; signal transmission; and using equipment common to these occupations, such as ammeters, voltmeters, capacitor checkers, transistor testers, signal generators, and ohmmeters.", "u": null, "notes": "concept: NI001517164236", "dep": null}, {"v": "17109", "n": "Particular Topics in Electricity/Electronics", "d": "These courses provide instruction in the theory and skills needed in fields involving electricity and electronics and related fields that focus on electrical wiring or electronic signals.", "u": null, "notes": "concept: NI001517164237", "dep": null}, {"v": "17110", "n": "Analog and Digital Circuits", "d": "In these courses, analog and digital circuits and systems are compared. Topics covered include binary and continuously variable currents and signals (typically in the context of voltage), waveforms, signal loss and distortion, modulation, and signal processing. These courses may also introduce other media, such as sound waves and liquids.", "u": null, "notes": "concept: NI001517164238", "dep": null}, {"v": "17111", "n": "Analog Circuits", "d": "Analog Circuit courses emphasize currents and voltages that have continuously variable signals and, due to that emphasis, concentrate on signal modulation, transmission and reception, signal loss and distortion, and waveforms. These courses may also address conversion techniques.", "u": null, "notes": "concept: NI001517164239", "dep": null}, {"v": "17112", "n": "Digital Circuits", "d": "Digital Circuit courses emphasize currents and voltages that have binary states and, due to that emphasis, concentrate on transmission and reception of binary data, signal loss, and processing circuitry. These courses may also address conversion techniques.", "u": null, "notes": "concept: NI001517164240", "dep": null}, {"v": "17147", "n": "Electricity/Electronics�Independent Study", "d": "Electricity/Electronics�Independent Study courses, often conducted with instructors as mentors, enable students to explore electricity- or electronics-related topics of interest. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164241", "dep": null}, {"v": "18005", "n": "Particular Topics in Environmental Service Systems", "d": "These courses provide students with specialized knowledge and help them develop skills in particular topics concerning the structure, processes, and implementation of environmental service systems.", "u": null, "notes": "concept: NI001517164242", "dep": null}, {"v": "18051", "n": "Plant Systems/Science", "d": "Formerly Plant Production/Science, Plant Systems/Science courses provide knowledge about the propagation of plants for food and fiber. These courses may cover such topics as soil science, irrigation, pest and weed control, food and fiber processing, and farm operations. These courses may also cover the knowledge and skills needed to produce all types of crops or may emphasize a particular area of the agricultural industry.", "u": null, "notes": "concept: NI001517164243", "dep": null}, {"v": "18052", "n": "Horticultural Science", "d": "Formerly known as General Horticulture, Horticultural Science courses expose students to the art and science of growing plants, shrubs, trees, flowers, fruits, and vegetables. In doing so, they cover a wide variety of topics, including principles of plant science, greenhouse and nursery operations, soils and growing media mixtures, fruit and vegetable production, turf/golf course management, interior and exterior plantscaping, irrigation systems, weed and pest control, and floral design.", "u": null, "notes": "concept: NI001517164244", "dep": null}, {"v": "18053", "n": "Ornamental Horticulture", "d": "Ornamental Horticulture courses provide information regarding the care and propagation of plants, flowers, trees, and shrubs, but place a special emphasis on those plants that are used for decorative and aesthetic purposes. Because of this particular emphasis, Ornamental Horticulture courses usually concentrate on nurseries and greenhouses and on the floristry industry.", "u": null, "notes": "concept: NI001517164245", "dep": null}, {"v": "18054", "n": "Turf and Landscape Management", "d": "Turf and Landscape Management courses provide instruction that incorporates plant science, soil and growing media mixtures, plant identification and optimal environments, and landscape design. These courses emphasize applying such knowledge and skill to the design, establishment, and maintenance of lawns, parks, open space, golf courses and other sports facilities, and similar environments.", "u": null, "notes": "concept: NI001517164246", "dep": null}, {"v": "17999", "n": "Architecture and Construction�Other", "d": "Other Architecture and Construction courses.", "u": null, "notes": "concept: NI001517164247", "dep": null}, {"v": "18001", "n": "Introduction to Agriculture and Natural Resources", "d": "Introduction to Agriculture and Natural Resources courses survey a wide array of topics within the agricultural industry, exposing students to the many and varied types of agriculture and career opportunities and those in related fields. These courses serve to introduce students to the agricultural field, providing them an opportunity to identify an area for continued study or to determine that their interest lies elsewhere. These courses often focus on developing communication skills, scientific research, types of business ownership, business principles, and leadership skills.", "u": null, "notes": "concept: NI001517164248", "dep": null}, {"v": "18002", "n": "Agriculture�Comprehensive", "d": "Agriculture�Comprehensive courses cover a wide range of agricultural topics, including plant and animal science, production, and processing; agricultural mechanics; food production for global populations; construction and repair of farm structures; business operations and management; and the careers available in the agricultural industry. These courses may also include topics such as chemical and soil science, ecology, agricultural marketing, and veterinary science.", "u": null, "notes": "concept: NI001517164249", "dep": null}, {"v": "18003", "n": "Agriculture and Natural Resources�Comprehensive", "d": "Agriculture and Natural Resources�Comprehensive courses may cover a wide range of topics concerning agriculture and natural resources, including plant and animal science, production, and processing; environmental science and conservation; ecology; agricultural mechanics; agricultural construction; food production for a growing global population, business operations and management; and the careers available in the agricultural/natural resources industry. These courses may also include topics such as chemical and soil science, forestry, agricultural marketing, and veterinary science.", "u": null, "notes": "concept: NI001517164250", "dep": null}, {"v": "18004", "n": "Biological Applications in Agriculture", "d": "Biological Applications in Agriculture courses are designed to integrate topics in science and agriculture. In these courses, students explore the world of agriculture and the associated biological principles. Competencies emphasize and reinforce standards for biology with agricultural applications.", "u": null, "notes": "concept: NI001517164251", "dep": null}, {"v": "18055", "n": "Soil Science", "d": "Soil Science courses involve the study of soil properties, including soil chemistry, biology, fertility, mineralogy, and hydrology. Topics covered may also include soil conservation, irrigation, soil genesis, soil surveys, and management.", "u": null, "notes": "concept: NI001517164252", "dep": null}, {"v": "18056", "n": "Particular Topics in Plant Systems", "d": "These courses examine specific topics related to Plant Systems, such as floral design, hydroponics, or landscaping, rather than provide a general study of plant systems or horticulture.", "u": null, "notes": "concept: NI001517164253", "dep": null}, {"v": "18097", "n": "Plant Systems�Independent Study", "d": "Courses in Plant Systems�Independent Study, often conducted with instructors as mentors, enable students to explore topics of interest related to plant systems. Independent Study courses may serve as an opportunity for students to expand their expertise in a particular application, to explore a topic in greater detail, or to develop more advanced skills.", "u": null, "notes": "concept: NI001517164254", "dep": null}, {"v": "18098", "n": "Plant Systems�Workplace Experience", "d": "Plant Systems�Workplace Experience courses provide work experience in fields related to plant systems (care, propagation, and processing). Goals are typically set cooperatively by the student, teacher, and employer (although students are not necessarily paid). These courses may include classroom activities as well, involving further study of the field or discussion regarding experiences that students encounter in the workplace.", "u": null, "notes": "concept: NI001517164255", "dep": null}, {"v": "18099", "n": "Plant Systems�Other", "d": "Other Plant Systems courses.", "u": null, "notes": "concept: NI001517164256", "dep": null}, {"v": "18101", "n": "Animal Production/Science", "d": "Animal Production/Science courses impart information about the care and management of companion and farm animals. These courses may cover animal nutrition, health, behavior, selection, reproduction, anatomy and physiology, facilities, product processing, research, qualitative and quantitative analyses as a basis for decisionmaking, and marketing. Students may study a particular species, or they may learn how to care for and maintain livestock as a more inclusive study.", "u": null, "notes": "concept: NI001517164257", "dep": null}, {"v": "18102", "n": "Small Animal Care", "d": "Small Animal Care courses focus on the care and management of small animals. Animal nutrition, health, behavior, reproduction and breeding, anatomy and physiology, use of qualitative and quantitative analyses for decisionmaking, facilities, handling and training, and grooming are typical areas of study.", "u": null, "notes": "concept: NI001517164258", "dep": null}, {"v": "18103", "n": "Large Animal Care", "d": "Large Animal Care courses focus on the care and management of large animals. Animal nutrition, health, behavior, reproduction and breeding, anatomy and physiology, use of qualitative and quantitative analyses for decisionmaking, facilities, handling and training, and grooming are typical areas of study. Course topics may include product processing and marketing.", "u": null, "notes": "concept: NI001517164259", "dep": null}, {"v": "18104", "n": "Equine Science", "d": "Equine Science courses focus on the care and management of horses. Animal nutrition, health, behavior, reproduction and breeding, anatomy and physiology, use of qualitative and quantitative analyses for decisionmaking, facilities, handling and training, and grooming are typical areas of study.", "u": null, "notes": "concept: NI001517164260", "dep": null}, {"v": "18105", "n": "Veterinary Science", "d": "Veterinary Science courses impart information about the causes, diagnosis, and treatment of diseases and injuries of animals, typically emphasizing domestic companion and farm animals. Course topics focus on anatomy and physiology, nutrition, behavior and training, disease prevention, reproduction, ethics of animal care, grooming, feeding, maintaining equipment and facilities, and other areas of study as appropriate.", "u": null, "notes": "concept: NI001517164261", "dep": null}, {"v": "04068", "n": "CI Global Perspectives and Independent Research", "d": "Cambridge International (CI) Global Perspectives and Research courses prepare students to take the Cambridge Global Perspectives and Research assessments. These courses teach students to broaden their outlook on our rapidly changing world through critical analysis and reflection on significant global issues. Students will develop the high-demand skills of research, critical thinking and reasoning, and communication through the 'Critical Path' approach.", "u": null, "notes": "concept: NI001517164546", "dep": null}, {"v": "03013", "n": "CI Marine Science", "d": "Cambridge International (CI) Marine Science courses prepare students to take the Cambridge Marine Science assessments and serve as an ideal subject combination for students who want to study Marine Biology or Environmental Science or follow a career in shipping, fisheries, tourism, or aquaculture. These courses teach students about observation and experimentation, the science of water, forming and shaping the ocean floor, organisms in the marine biome, and human influences. Students will develop practical skills, such as accurate and safe scientific practices, in addition to skills in data analysis and scientific communication.", "u": null, "notes": "concept: NI001517164547", "dep": null}, {"v": "04311", "n": "CI Thinking Skills", "d": "Cambridge International (CI) Thinking Skills courses prepare students to take the Cambridge Thinking Skills assessments and develop skills essential for successful progression to higher education or professional employment. These courses develop students' abilities to analyze unfamiliar problems, devise problem solving strategies, and evaluate the diverse ways a problem may be solved through evidence-based arguments. Students will gain language skills in areas of problem solving, critical thinking, problem analysis and solution, and applied reasoning.", "u": null, "notes": "concept: NI001517164548", "dep": null}, {"v": "04111", "n": "CI U.S. History", "d": "Cambridge International (CI) U.S. History courses prepare students to take the American history options of the Cambridge History assessments. These courses teach students the periods and themes in U.S. history as well as the significance and interpretations of cause and consequence, change and continuity, and similarity and difference in U.S. history. Students will learn both foundational and modern history of the U.S., historical sources, interpretations of U.S. historical issues, and methods used by historians.", "u": null, "notes": "concept: NI001517164549", "dep": null}, {"v": "22160", "n": "Data Literacy", "d": "Data Literacy courses focus on developing students' ability to read, interpret, and analyze data. These courses teach students how to assess the reliability and validity of data, as well as to understand data to draw conclusions and explain the results, such as through summary statistics or data visualization.", "u": null, "notes": "concept: NI001517164550", "dep": null}, {"v": "22161", "n": "Data Science", "d": "Data Science courses prepare students to think critically about data and develop the tools, techniques, and principles for reasoning about the world with data. These courses teach students to use scientific methods, data sampling and probability, algorithms, and systems to analyze structured and unstructured data. Students will use modern data analysis tools, including computer programming languages. Course topics may include big data, data cleaning, data modeling, data mining, artificial intelligence, correlation and causation, and bias and uncertainty.", "u": null, "notes": "concept: NI001517164551", "dep": null}, {"v": "22162", "n": "Data Science Applications", "d": "Data Science Applications courses emphasize the practical uses of data science concepts and the transformation of data to knowledge. Students will explore real-world datasets and answer questions using hands-on analysis, project-based learning, and programming software.", "u": null, "notes": "concept: NI001517164552", "dep": null}, {"v": "22114", "n": "Personal and Professional Skills", "d": "Personal and Professional Skills courses develop the attitudes, skills, and strategies students need for personal and professional settings. Topics include personal growth and development, interpersonal skills, intercultural understanding, and ethics.", "u": null, "notes": "concept: NI001517164553", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CarnegieBasicClassification', 'The Basic Classification is an update of the traditional classification framework developed by the Carnegie Commission on Higher Education in 1970 to support its research program, and later published in 1973 for use by other researchers.', NULL, 'scheme: C000038', NULL, $j$[{"v": "Assoc/PrivFP", "n": "Associate's--Private For-profit", "d": "Associate's--Private For-profit is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115285", "dep": null}, {"v": "Assoc/PrivFP4", "n": "Associate's--Private For-profit 4-year Primarily Associate's", "d": "Associate's--Private For-profit 4-year Primarily Associate's is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115286", "dep": null}, {"v": "Assoc/PrivNFP", "n": "Associate's--Private Not-for-profit", "d": "Associate's--Private Not-for-profit is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115287", "dep": null}, {"v": "Assoc/PrivNFP4", "n": "Associate's--Private Not-for-profit 4-year Primarily Associate's", "d": "Associate's--Private Not-for-profit 4-year Primarily Associate's is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115288", "dep": null}, {"v": "Assoc/Pub2in4", "n": "Associate's--Public 2-year Colleges under 4-year Universities", "d": "Associate's--Public 2-year Colleges under 4-year Universities is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115289", "dep": null}, {"v": "Assoc/Pub4", "n": "Associate's--Public 4-year Primarily Associate's", "d": "Associate's--Public 4-year Primarily Associate's is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115290", "dep": null}, {"v": "Assoc/Pub-R-L", "n": "Associate's--Public Rural-serving Large", "d": "Associate's--Public Rural-serving Large is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115291", "dep": null}, {"v": "Assoc/Pub-R-M", "n": "Associate's--Public Rural-serving Medium", "d": "Associate's--Public Rural-serving Medium is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115292", "dep": null}, {"v": "Assoc/Pub-R-S", "n": "Associate's--Public Rural-serving Small", "d": "Associate's--Public Rural-serving Small is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115293", "dep": null}, {"v": "Assoc/Pub-S-MC", "n": "Associate's--Public Suburban-serving Multicampus", "d": "Associate's--Public Suburban-serving Multicampus is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115294", "dep": null}, {"v": "Assoc/Pub-Spec", "n": "Associate's--Public Special Use", "d": "Associate's--Public Special Use is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115295", "dep": null}, {"v": "Assoc/Pub-S-SC", "n": "Associate's--Public Suburban-serving Single Campus", "d": "Associate's--Public Suburban-serving Single Campus is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115296", "dep": null}, {"v": "Assoc/Pub-U-MC", "n": "Associate's--Public Urban-serving Multicampus", "d": "Associate's--Public Urban-serving Multicampus is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115297", "dep": null}, {"v": "Assoc/Pub-U-SC", "n": "Associate's--Public Urban-serving Single Campus", "d": "Associate's--Public Urban-serving Single Campus is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115298", "dep": null}, {"v": "Bac/AandS", "n": "Baccalaureate Colleges--Arts and Sciences", "d": "Baccalaureate Colleges--Arts and Sciences is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115336", "dep": null}, {"v": "Bac/Assoc", "n": "Baccalaureate/Associate's Colleges", "d": "Baccalaureate/Associate's Colleges is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115337", "dep": null}, {"v": "Bac/Diverse", "n": "Baccalaureate Colleges--Diverse Fields", "d": "Baccalaureate Colleges--Diverse Fields is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115338", "dep": null}, {"v": "DRU", "n": "Doctoral/Research Universities", "d": "Doctoral/Research Universities is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038115597", "dep": null}, {"v": "Masters/L", "n": "Master's Colleges and Universities (larger programs)", "d": "Master's Colleges and Universities (larger programs) is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116074", "dep": null}, {"v": "Masters/M", "n": "Master's Colleges and Universities (medium programs)", "d": "Master's Colleges and Universities (medium programs) is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116075", "dep": null}, {"v": "Masters/S", "n": "Master's Colleges and Universities (smaller programs)", "d": "Master's Colleges and Universities (smaller programs) is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116076", "dep": null}, {"v": "RU/H", "n": "Research Universities (high research activity)", "d": "Research Universities (high research activity) is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116778", "dep": null}, {"v": "RU/VH", "n": "Research Universities (very high research activity)", "d": "Research Universities (very high research activity) is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116779", "dep": null}, {"v": "Spec/Arts", "n": "Special Focus Institutions--Schools of art, music, and design", "d": "Special Focus Institutions--Schools of art, music, and design is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116881", "dep": null}, {"v": "Spec/Bus", "n": "Special Focus Institutions--Schools of business and management", "d": "Special Focus Institutions--Schools of business and management is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116882", "dep": null}, {"v": "Spec/Engg", "n": "Special Focus Institutions--Schools of engineering", "d": "Special Focus Institutions--Schools of engineering is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116883", "dep": null}, {"v": "Spec/Faith", "n": "Special Focus Institutions--Theological seminaries, Bible colleges, other faith-related institutions", "d": "Special Focus Institutions--Theological seminaries, Bible colleges, other faith-related institutions is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116884", "dep": null}, {"v": "Spec/Health", "n": "Special Focus Institutions--Other health professions schools", "d": "Special Focus Institutions--Other health professions schools is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116885", "dep": null}, {"v": "Spec/Law", "n": "Special Focus Institutions--Schools of law", "d": "Special Focus Institutions--Schools of law is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116886", "dep": null}, {"v": "Spec/Med", "n": "Special Focus Institutions--Medical schools and medical centers", "d": "Special Focus Institutions--Medical schools and medical centers is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116887", "dep": null}, {"v": "Spec/Other", "n": "Special Focus Institutions-Other special-focus institutions", "d": "Special Focus Institutions-Other special-focus institutions is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116888", "dep": null}, {"v": "Spec/Tech", "n": "Special Focus Institutions--Other technology-related schools", "d": "Special Focus Institutions--Other technology-related schools is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038116889", "dep": null}, {"v": "Tribal", "n": "Tribal Colleges", "d": "Tribal Colleges is specified as the Carnegie Basic Classification for a postsecondary institution.", "u": null, "notes": "concept: NI000038117084", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('ActivityTimeMeasurementType', 'The type of measurement for the amount of time the student participated in the events and procedures of an activity, such as a co-curricular or extra-curricular activity that is offered at an education institution.', NULL, 'scheme: C001528', NULL, $j$[{"v": "WeeklyHours", "n": "Weekly hours", "d": "Weekly hours is specified as the type of measurement for the amount of time the student participated in the events and procedures of an activity.", "u": null, "notes": "concept: NI001528117180", "dep": null}, {"v": "YearlyWeeks", "n": "Yearly weeks", "d": "Yearly weeks is specified as the type of measurement for the amount of time the student participated in the events and procedures of an activity.", "u": null, "notes": "concept: NI001528117219", "dep": null}]$j$::jsonb);
