SELECT public.ceds_tmp_valueset('PersonIdentifierType', 'A coding scheme of identifiers assigned to an individual, distinguishing between various roles and contexts within an educational or organizational setting. It ensures accurate identification and classification of individuals based on their specific type of identifier.', NULL, 'scheme: C002114', NULL, $j$[{"v": "PersonIdentifier", "n": "Person Identifier", "d": "A coding scheme that is used for identification of a person.", "u": null, "notes": "concept: NI002114100000", "dep": null}, {"v": "ChildIdentifier", "n": "Child Identifier", "d": "A coding scheme that is used for identification and record-keeping purposes by programs, schools, social services, or other agencies to refer to a child.", "u": null, "notes": "concept: NI002114100001", "dep": null}, {"v": "StudentIdentifier", "n": "Student Identifier", "d": "A coding scheme that is used for identification and record-keeping purposes by schools, social services, or other agencies to refer to a student.", "u": null, "notes": "concept: NI002114100002", "dep": null}, {"v": "StaffMemberIdentifier", "n": "Staff Member Identifier", "d": "A coding scheme that is used for identification and record-keeping purposes by schools, social services, registry, or other agencies to refer to a staff member.", "u": null, "notes": "concept: NI002114100003", "dep": null}, {"v": "001444", "n": "Professional Development Instructor Identifier", "d": "A unique number or alphanumeric code assigned to a staff member by a school, school system, a state, registry, or other agency or entity.", "u": null, "notes": "concept: NI002114001444", "dep": null}, {"v": "000410", "n": "Assessment Session Administrator Identifier", "d": "The unique identifier of the person overseeing the administration of an assessment. This is typically at a district or school level or at an administrator at a testing facility.", "u": null, "notes": "concept: NI002114000410", "dep": null}, {"v": "000411", "n": "Assessment Session Proctor Identifier", "d": "The unique identifier of the person overseeing the assessment session in the setting.", "u": null, "notes": "concept: NI002114000411", "dep": null}]$j$::jsonb);
