SELECT public.ceds_tmp_valueset('PostsecondaryExitOrWithdrawalType', 'The circumstances under which the student exited from enrollment in a postsecondary institution.', NULL, 'scheme: C001617', NULL, $j$[{"v": "Withdrawn", "n": "Withdrawn", "d": "A student enrolled in a postsecondary institution who has withdrawn, dropped out, failed to re-enroll or been terminated, expelled or dismissed by the institution is considered withdrawn.", "u": null, "notes": "concept: NI001617106062", "dep": null}, {"v": "Graduated", "n": "Graduated", "d": "A student who was enrolled in an eligible postsecondary institution and completed the requirements for graduation or the program of study in which he/she was enrolled is considered graduated.", "u": null, "notes": "concept: NI001617106063", "dep": null}, {"v": "ApprovedLeaveOfAbsence", "n": "Approved Leave of Absence", "d": "A student who is enrolled in an eligible postsecondary institution and has met the requirements for an approved student loan leave of absence and, therefore, is not required to attend classes for a specified period of time. For purposes of Title IV, HEA program loan borrower, an institution does not have to treat a leave of absence as a withdrawal if it is an approved leave of absence. An approved student loan leave of absence must not exceed 180 days in any 12-month-period. The number of days in a leave of absence is counted beginning with the first day of the student's initial leave of absence in a 12-month period. If a student does not resume attendance at the institution at or before the end of a leave of absence, the institution must treat the student as a withdrawal in accordance with CFR 668.22(d).", "u": null, "notes": "concept: NI001617106064", "dep": null}, {"v": "Deceased", "n": "Deceased", "d": "Student is deceased.", "u": null, "notes": "concept: NI001617106065", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": "Student's exit circumstances are unknown.", "u": null, "notes": "concept: NI001617106066", "dep": null}]$j$::jsonb);
