SELECT public.ceds_tmp_valueset('MilitaryBranch', 'A branch of the U.S. Military applicable for specifying more details when using Military Connected Student Indicator, Military Active Student Indicator, Military Veteran Student Indicator, and Military Enlistment After Exit elements.', NULL, 'scheme: C001640', NULL, $j$[{"v": "Army", "n": "Army", "d": "U.S. Army", "u": null, "notes": "concept: NI001640151056", "dep": null}, {"v": "Navy", "n": "Navy", "d": "U.S. Navy", "u": null, "notes": "concept: NI001640151057", "dep": null}, {"v": "AirForce", "n": "Air Force", "d": "U.S. Air Force", "u": null, "notes": "concept: NI001640151058", "dep": null}, {"v": "MarineCorps", "n": "Marine Corps", "d": "U.S. Marine Corps", "u": null, "notes": "concept: NI001640151059", "dep": null}, {"v": "CoastGuard", "n": "Coast Guard", "d": "U.S. Coast Guard", "u": null, "notes": "concept: NI001640151060", "dep": null}, {"v": "SpaceForce", "n": "Space Force", "d": "U.S. Space Force", "u": null, "notes": "concept: NI001640151061", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('DQPCategoriesOfLearning', 'The Lumina Foundation''s Degree Qualifications Profile offers reference points for what students should know and be able to do upon completion of associate, bachelor''s and master''s degrees � in any field of study. The DQP Categories of Learning provide a profile of what degrees mean within which specific proficiencies may be defined.', NULL, 'scheme: C001641', NULL, $j$[{"v": "SpecializedKnowledge", "n": "Specialized Knowledge", "d": "A category of learning addressing specialized knowledge and skill requirements of a student pursuing a specialized degree.", "u": null, "notes": "concept: NI001641117784", "dep": null}, {"v": "BroadAndIntegrativeKnowledge", "n": "Broad and Integrative Knowledge", "d": "Liberal and general education category of learning with emphasis on students' broad learning across the humanities, arts, sciences and social sciences.", "u": null, "notes": "concept: NI001641117785", "dep": null}, {"v": "IntellectualSkills", "n": "Intellectual Skills", "d": "Proficiencies that transcend the boundaries of particular fields of study including analytic inquiry, use of information resources, engaging diverse perspectives, ethical reasoning, quantitative fluency, and communicative fluency.", "u": null, "notes": "concept: NI001641117786", "dep": null}, {"v": "AppliedAndCollaborativeLearning", "n": "Applied and Collaborative Learning", "d": "A category of learning addressing what graduates can do with what they know.", "u": null, "notes": "concept: NI001641117787", "dep": null}, {"v": "CivicAndGlobalLearning", "n": "Civic and Global Learning", "d": "A category of learning addressing proficiencies needed for both civic and global inquiry and interaction.", "u": null, "notes": "concept: NI001641117788", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CharterSchoolManagementOrganizationType', 'The type of organization that is a separate legal entity that 1) contracts with one or more charter schools to manage, operate, and oversee the charter schools; or 2) holds a charter, or charters, to operate multiple charter schools.', NULL, 'scheme: C001650', NULL, $j$[{"v": "CMO", "n": "Charter Management Organization", "d": "A non-profit organization that operates or manages a network of charter schools (either through a contract with the charter schools or as the charter holder) linked by centralized support, operations, and oversight.", "u": null, "notes": "concept: NI001650151062", "dep": null}, {"v": "EMO", "n": "Education Management Organization", "d": "A for-profit organization that operates or manages a network of charter schools (either through a contract with the charter schools or as the charter holder) linked by centralized support, operations, and oversight.", "u": null, "notes": "concept: NI001650151063", "dep": null}, {"v": "SMFP", "n": "Single Management (for-profit)", "d": "A for-profit entity that is not a CMO or EMO and that provides management services to one charter school.", "u": null, "notes": "concept: NI001650151065", "dep": null}, {"v": "SMNP", "n": "Single Management (non-profit)", "d": "A non-profit organization that is not a CMO or EMO and that provides management services.", "u": null, "notes": "concept: NI001650151066", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('NationalSchoolLunchProgramDirectCertificationIndicator', 'Indicates that the student''s National School Lunch Program (NSLP) eligibility has been determined through direct certification.', NULL, 'scheme: C001654', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI001654100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI001654100002", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IDEAPartCEligibilityCategory', 'The category under which a person under 3 years of age is eligible for early intervention services under IDEA Part C.', NULL, 'scheme: C001656', NULL, $j$[{"v": "DevelopmentalDelay", "n": "Developmental Delay", "d": "The child has one or more delays as measured by appropriate diagnostic instruments and procedures in 1 or more of the areas of cognitive development, physical development, communication development, social or emotional development, and adaptive development.", "u": null, "notes": "concept: NI001656117792", "dep": null}, {"v": "DiagnosedCondition", "n": "Diagnosed Condition", "d": "The child has a diagnosed physical or mental condition that has a high probability of resulting in developmental delay.", "u": null, "notes": "concept: NI001656117793", "dep": null}, {"v": "AtRisk", "n": "At-risk", "d": "The child would be at risk of experiencing a substantial developmental delay if early intervention services were not provided to the child.", "u": null, "notes": "concept: NI001656117794", "dep": null}]$j$::jsonb);
