{"v": "IPEDS19", "n": "Doctor's degree - other Award Levels", "d": "Doctor's degree - other Award Levels", "u": null, "notes": "concept: NI001668151685", "dep": null}, {"v": "CEGEP", "n": "CEGEP (an award made by Canadian secondary schools that is typically equivalent to a high school diploma plus one year of college level courses)", "d": "CEGEP (an award made by Canadian secondary schools that is typically equivalent to a high school diploma plus one year of college level courses)", "u": null, "notes": "concept: NI001668151686", "dep": null}, {"v": "FrenchBaccalaureate", "n": "French Baccalaureate (award made to high school students that allows French and international students to obtain a standardized qualification)", "d": "French Baccalaureate (an award made to high school students who complete a rigorous program of study including foreign languages. It allows French and international students to obtain a standardized qualification, typically at the age of 18)", "u": null, "notes": "concept: NI001668151687", "dep": null}, {"v": "4.0", "n": "Graduate non-degree - value to represent an award from graduate coursework that is not a certificate or degree", "d": "Graduate non-degree - value to represent an award from graduate coursework that is not a certificate or degree", "u": null, "notes": "concept: NI001668151688", "dep": null}, {"v": "3.3", "n": "Graduate Professional - value to represent an award from graduate coursework in a professional program", "d": "Graduate Professional - value to represent an award from graduate coursework in a professional program", "u": null, "notes": "concept: NI001668151689", "dep": null}, {"v": "0.0", "n": "Other - value to represent an award that does not otherwise fit existing enumerations", "d": "Other - value to represent an award that does not otherwise fit existing enumerations", "u": null, "notes": "concept: NI001668151690", "dep": null}, {"v": "1.5", "n": "Statement of achievement", "d": "Statement of achievement", "u": null, "notes": "concept: NI001668151691", "dep": null}, {"v": "1.4", "n": "Statement of completion", "d": "Statement of completion", "u": null, "notes": "concept: NI001668151692", "dep": null}, {"v": "1.3", "n": "Statement of participation", "d": "Statement of participation", "u": null, "notes": "concept: NI001668151693", "dep": null}, {"v": "2.8", "n": "Undergraduate non-degree - value to represent an award from undergraduate coursework that is not a certificate or degree", "d": "Undergraduate non-degree - value to represent an award from undergraduate coursework that is not a certificate or degree", "u": null, "notes": "concept: NI001668151694", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceGASBFinancialPositionCategory', 'IPEDS financial position classification used by degree-granting public institutions using GASB Reporting Standards for reporting the assets, liabilities, and net position in a manner consistent with the Statement of Net Position in the General Purpose Financial Statements (GPFS).', NULL, 'scheme: C001670', NULL, $j$[{"v": "Totalcurrentassets", "n": "Total current assets", "d": "Used for reporting all current assets, including cash and cash equivalents, investments, accounts and notes receivables (net of allowance for uncollectible amounts), inventories, and all other assets classified as current assets.", "u": null, "notes": "concept: NI001670127576", "dep": null}, {"v": "Depreciablecapitalassetsnetofdepreciation", "n": "Depreciable capital assets, net of depreciation", "d": "Used for reporting all capital assets reduced by the total accumulated depreciation, including improvements to land, easements, buildings, building improvements, vehicles, machinery, equipment, infrastructure, and all other tangible or intangible depreciable assets that are used in operations and that have initial useful lives extending beyond a single reporting period. Includes the net amount of all depreciable capital assets after reducing the gross amount for accumulated depreciation.", "u": null, "notes": "concept: NI001670127577", "dep": null}, {"v": "Deferredoutflowsofresources", "n": "Deferred outflows of resources", "d": "Used for reporting the deferred outflows of resources as recognized in the institution's GPFS and in accordance with GASB 63.", "u": null, "notes": "concept: NI001670127579", "dep": null}, {"v": "Longtermdebtcurrentportion", "n": "Long-term debt, current portion", "d": "Used for reporting the amount due in the next operating cycle (usually a year) for amounts otherwise reported as long-term or noncurrent debt. Includes only outstanding debt.", "u": null, "notes": "concept: NI001670127580", "dep": null}, {"v": "Longtermdebt", "n": "Long-term debt", "d": "Used for reporting the amount for long-term debt arising from debt issuance and lease-purchase agreements.", "u": null, "notes": "concept: NI001670127582", "dep": null}, {"v": "Deferredinflowsofresources", "n": "Deferred inflows of resources", "d": "Used for reporting the deferred inflows of resources as recognized in the institution's GPFS and in accordance with GASB 63.", "u": null, "notes": "concept: NI001670127584", "dep": null}, {"v": "Netassetsinvestedincapitalassetsnetofrelateddebt", "n": "Net assets invested in capital assets, net of related debt", "d": "Used for reporting the component of net assets represented by the total of all capital assets, reduced by accumulated depreciation, and reduced by the amount of outstanding bonds, mortgages, notes, or other borrowings that are attributable to the acquisition, construction, or improvement of those assets (see indebtedness on capital assets). Some outstanding debt may be reported in both current and noncurrent liabilities.", "u": null, "notes": "concept: NI001670127585", "dep": null}, {"v": "Restrictedexpendablenetassets", "n": "Restricted expendable net assets", "d": "Used for reporting restricted net assets that are expendable. Net assets should be reported as restricted when constraints placed on use are either (a) externally imposed by creditors, grantors, contributors, or laws and regulations of other governments or (b) imposed by law through constitutional provisions or enabling legislation. Expendable net assets are all those not required to be retained in perpetuity.", "u": null, "notes": "concept: NI001670127586", "dep": null}, {"v": "Restrictednonexpendablenetassets", "n": "Restricted non-expendable net assets", "d": "Used for reporting net assets that are restricted and nonexpendable. Net assets should be reported as restricted when constraints placed on use are either (a) externally imposed by creditors, grantors, contributors, or laws and regulations of other governments or (b) imposed by law through constitutional provisions or enabling legislation. Nonexpendable net assets are those that are required to be retained in perpetuity.", "u": null, "notes": "concept: NI001670127587", "dep": null}, {"v": "Unrestrictednetassets", "n": "Unrestricted net assets", "d": "This should be the amount of net assets that do not meet the definition of \"restricted\" or \"invested in capital assets, net of related debt.\"", "u": null, "notes": "concept: NI001670127588", "dep": null}, {"v": "CapitalAssetsLandlandimprovements", "n": "Capital Assets: Land and land improvements", "d": "Used for reporting land and other land improvements, such as athletic fields, golf courses, lakes, etc.", "u": null, "notes": "concept: NI001670127589", "dep": null}, {"v": "CapitalAssetsInfrastructure", "n": "Capital Assets: Infrastructure", "d": "Used for reporting infrastructure assets such as roads, bridges, drainage systems, water and sewer systems, etc.", "u": null, "notes": "concept: NI001670127590", "dep": null}, {"v": "CapitalAssetsBuildings", "n": "Capital Assets: Buildings", "d": "Used for reporting structures built for occupancy or use, such as for classrooms, research, administrative offices, storage, etc. Includes built-in fixtures and equipment that are essentially part of the permanent structure.", "u": null, "notes": "concept: NI001670127591", "dep": null}, {"v": "CapitalAssetsEquipmentincludingartlibrary", "n": "Capital Assets: Equipment, including art and library collections", "d": "Used for reporting moveable tangible property such as research equipment, vehicles, office equipment, library collections (capitalized amount of books, films, tapes, and other materials maintained in library collections intended for use by patrons), and capitalized art collections.", "u": null, "notes": "concept: NI001670127592", "dep": null}, {"v": "CapitalAssetsConstructioninprogress", "n": "Capital Assets: Construction in progress", "d": "Used for reporting capital assets under construction and not yet placed into service.", "u": null, "notes": "concept: NI001670127593", "dep": null}, {"v": "CapitalAssetsAccumulateddepreciation", "n": "Capital Assets: Accumulated depreciation", "d": "Used for reporting all depreciation amounts, including depreciation on assets that may not be included in other capital assets categories.", "u": null, "notes": "concept: NI001670127594", "dep": null}, {"v": "CapitalAssetsIntangibleassetsnetof", "n": "Capital Assets: Intangible assets, net of accumulated amortization", "d": "Used for reporting all assets consisting of certain nonmaterial rights and benefits of an institution, such as patents, copyrights, trademarks and goodwill. The amount should be reduced by total accumulated amortization.", "u": null, "notes": "concept: NI001670127595", "dep": null}, {"v": "Othernoncurrentassets", "n": "Other noncurrent assets", "d": null, "u": null, "notes": "concept: NI001670127578", "dep": null}, {"v": "Othercurrentliabilities", "n": "Other current liabilities", "d": null, "u": null, "notes": "concept: NI001670127581", "dep": null}, {"v": "Othernoncurrentliabilities", "n": "Other non-current liabilities", "d": null, "u": null, "notes": "concept: NI001670127583", "dep": null}, {"v": "CapitalAssetsOthercapitalassets", "n": "Capital Assets: Other capital assets", "d": null, "u": null, "notes": "concept: NI001670127596", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceFASBFinancialPositionCategory', 'IPEDS financial position classification used by degree-granting private, not-for-profit institutions and public institutions using FASB Reporting Standards for reporting the assets, liabilities, and net assets in a manner consistent with the Statement of Financial Position in the General Purpose Financial Statements (GPFS).', NULL, 'scheme: C001671', NULL, $j$[{"v": "LiabilitiesAccountspayable", "n": "Liabilities: Accounts payable", "d": "Includes the total of accounts payable to suppliers. (FARM para. 420)", "u": null, "notes": "concept: NI001671127607", "dep": null}, {"v": "LiabilitiesDeferredrevenuesrefundableadvances", "n": "Liabilities: Deferred revenues and refundable advances", "d": "Includes short-term deferrals and advances including student deposits, advances from third parties for services not yet performed, short-term advances on grants or contracts (including those from the government), and refunds due third parties for amounts previously received. (FARM para. 422)", "u": null, "notes": "concept: NI001671127608", "dep": null}, {"v": "LiabilitiesPostretirementpostemploymentobligations", "n": "Liabilities: Post-retirement and post-employment obligations", "d": "Includes amounts for pension obligations, post-retirement healthcare benefit obligations, severance obligations, and similar post-retirement and post-employment obligations. (FARM para. 478 and 479)", "u": null, "notes": "concept: NI001671127609", "dep": null}, {"v": "AssetsCashcashequivalentstemporaryinvestments", "n": "Assets: Cash, cash equivalents, and temporary investments", "d": "Cash equivalents are short term, highly liquid investments that are (1) readily converted to known amounts of cash, and (2) so near their maturity that they present insignificant risk of changes in value because of changes in interest rates. Examples are U.S. Treasury bills, certificates of deposit, bankers acceptances, repurchase agreements, and commercial paper. Includes amounts for currency on hand and deposits held by financial institutions that can be added to or withdrawn without limitation, such as demand deposits. (FARM para. 402)", "u": null, "notes": "concept: NI001671127600", "dep": null}, {"v": "AssetsReceivablesnetofallowancefor", "n": "Assets: Receivables (net of allowance for uncollectible amounts)", "d": "Includes amounts receivable for all purposes, including billings for educational and general programs and auxiliary enterprise activities; student loans receivable; government appropriations receivable; amounts receivable on grants and contracts; accrued dividends and interest receivable; claims against vendors; advances to employees; and reimbursements receivable from affiliated organizations. All amounts receivable should be reported net of an allowance for uncollectible accounts. (FARM para. 403)", "u": null, "notes": "concept: NI001671127601", "dep": null}, {"v": "AssetsInventoriesprepaidexpensesdeferredcharges", "n": "Assets: Inventories, prepaid expenses, and deferred charges", "d": "Inventories, prepaid expenses, and deferred charges � For inventories, include amounts for merchandise inventory held for resale, for example, items held for sale by a bookstore or a dining service. Include supplies and other inventoried items for internal use if recognized as an asset in the GPFS. For prepaid expenses and deferred charges, include amounts paid in advance of services received and expenses deferred because benefits relate to future rather than to current period activities. Examples include prepaid rent, prepaid insurance, bond issue costs, pension costs or other outflows applicable to future periods. (FARM para. 407)", "u": null, "notes": "concept: NI001671127602", "dep": null}, {"v": "AssetsAmountsheldbytrusteesfor", "n": "Assets: Amounts held by trustees for construction and debt service", "d": "Includes cash and investments held by trustees in accordance with agreements that limit expenditure of those amounts to purchase of plant, property, or equipment or to payment of principal and interest on bonds and notes payable or other long-term debt.", "u": null, "notes": "concept: NI001671127603", "dep": null}, {"v": "AssetsOtherassets", "n": "Assets: Other assets", "d": "Includes all other assets not reported elsewhere.", "u": null, "notes": "concept: NI001671127606", "dep": null}, {"v": "Longterminvestments", "n": "Long-term investments", "d": "Used for reporting the end-of-year market value for all assets held for long-term investment. Long-term investments should be distinguished from temporary investments based on the intention of the organization regarding the term of the investment rather than the nature of the investment itself. Thus, cash and cash equivalents which are held until appropriate long-term investments are identified should be treated as long-term investments. Similarly, cash equivalents strategically invested and reinvested for long-term purposes should be treated as long-term investments. (FARM para. 405)", "u": null, "notes": "concept: NI001671127597", "dep": null}, {"v": "PropertyPlantEquipmentnetofaccumulateddepreciation", "n": "Property, Plant, and Equipment, net of accumulated depreciation", "d": "Includes end-of-year market value for categories such as land, buildings, improvements other than buildings, equipment, and library books, combined and net of accumulated depreciation. (FARM para. 415)", "u": null, "notes": "concept: NI001671127598", "dep": null}, {"v": "IntangibleAssetsnetofaccumulatedamortization", "n": "Intangible Assets, net of accumulated amortization", "d": "Used for reporting all assets consisting of certain nonmaterial rights and benefits of an institution, such as patents, copyrights, trademarks and goodwill. The amount reported should be reduced by total accumulated amortization. (FARM para. 409)", "u": null, "notes": "concept: NI001671127599", "dep": null}, {"v": "LiabilitiesOtheraccruedliabilities", "n": "Liabilities: Other accrued liabilities", "d": "Includes amounts for any accrued liabilities, including accrued interest payable, salary and benefit (payroll) accruals, and similar accrued expenses not found in another category. (FARM para. 420)", "u": null, "notes": "concept: NI001671127610", "dep": null}, {"v": "LiabilitiesAnnuitylifeincomeobligationsother", "n": "Liabilities: Annuity and life income obligations and other amounts held for the benefit of others", "d": "Includes agency obligations, the beneficiaries' interests in assets held by the institution subject to split-interest agreements (i.e., the obligation, measured at present value of payments to be made), deferred compensation amounts, and similar obligations recognized in the GPFS.", "u": null, "notes": "concept: NI001671127611", "dep": null}, {"v": "LiabilitiesBondsnotescapitalleases", "n": "Liabilities: Bonds, notes, and capital leases payable and other long-term debt, including current portion", "d": "Includes amounts for all long-term debt obligations including bonds payable, mortgages payable, capital leases payable, and long-term notes payable. If the current portion of long-term debt is separately reported in your GPFS, include that amount. (FARM para. 420 and 423)", "u": null, "notes": "concept: NI001671127612", "dep": null}, {"v": "LiabilitiesGovernmentgrantsrefundableunder", "n": "Liabilities: Government grants refundable under student loan programs", "d": "Includes amounts advanced to the institution by a governmental entity for purposes of making loans to students (if recognized as a liability in the GPFS).", "u": null, "notes": "concept: NI001671127613", "dep": null}, {"v": "LiabilitiesOtherliabilities", "n": "Liabilities: Other liabilities", "d": "Includes all other liabilities not reported elsewhere.", "u": null, "notes": "concept: NI001671127614", "dep": null}, {"v": "DebtrelatedtoPropertyPlantEquipment", "n": "Debt related to Property, Plant, and Equipment", "d": "Includes amounts for all long-term debt obligations including bonds payable, mortgages payable, capital leases payable, and long-term notes payable. (FARM para. 420.3, 423) If the current portion of long-term debt is separately reported in the GPFS, include that amount.", "u": null, "notes": "concept: NI001671127615", "dep": null}, {"v": "Totalunrestrictednetassets", "n": "Total unrestricted net assets", "d": "Used for reporting the amount of unrestricted (designated and undesignated) net assets. Unrestricted net assets are amounts that are available for the general purposes of the institution without restriction. Include amounts specifically designated by the governing board, such as those designated as quasi-endowments, for building additions and replacement, for debt service, and for loan programs. In addition, include the unrestricted portion of net investment in plant, property, and equipment less related debt. This amount is computed as the amount of plant, property, and equipment, net of accumulated depreciation, reduced by any bonds, mortgages, notes, capital leases, or other borrowings that are clearly attributable to the acquisition, construction, or improvement of those assets. (FARM para. 450)", "u": null, "notes": "concept: NI001671127616", "dep": null}, {"v": "Permanentlyrestrictednetassets", "n": "Permanently restricted net assets", "d": "Used for reporting the portion of net assets required by the donor or grantor to be held in perpetuity. (FARM para 450.2)", "u": null, "notes": "concept: NI001671127617", "dep": null}, {"v": "Temporarilyrestrictednetassets", "n": "Temporarily restricted net assets", "d": "Used for reporting net assets that are subject to a donor's or grantor's restriction are restricted net assets. Include long-term but temporarily restricted net assets, such as term endowments, and net assets held subject to trust agreements if those agreements permit expenditure of the resources at a future date. (FARM para. 450.3)", "u": null, "notes": "concept: NI001671127618", "dep": null}, {"v": "GrossPropertyPlantEquipmentLandlandimprovements", "n": "Gross Property Plant Equipment: Land and land improvements", "d": "Used for reporting end of year values for land and land improvements as a reconciliation of beginning of the year values with additions to and retirements of land and land improvements to obtain end of year values. Use your underlying institutional records.", "u": null, "notes": "concept: NI001671127619", "dep": null}, {"v": "GrossPropertyPlantEquipmentBuildings", "n": "Gross Property Plant Equipment: Buildings", "d": "Used for reporting end of year values for buildings as a reconciliation of beginning of the year values with additions to and retirements of building values to obtain end of year values. Capitalized leasehold improvements should be included if the improvements are to leased facilities.", "u": null, "notes": "concept: NI001671127620", "dep": null}, {"v": "GrossPropertyPlantEquipmentEquipment", "n": "Gross Property Plant Equipment: Equipment, including art and library collections", "d": "Used for reporting end of year values for equipment as a reconciliation of beginning of the year values with additions to and retirements of equipment values to obtain end of year values. Capitalized leasehold improvements should be included if the improvements are to leased equipment.", "u": null, "notes": "concept: NI001671127621", "dep": null}, {"v": "GrossPropertyPlantEquipmentConstructioninProgress", "n": "Gross Property Plant Equipment: Construction in Progress", "d": "Used for reporting capital assets under construction and not yet placed into service.", "u": null, "notes": "concept: NI001671127622", "dep": null}, {"v": "GrossPropertyPlantEquipmentOther", "n": "Gross Property Plant Equipment: Other", "d": "Used for reporting all other amounts for capital assets not reported elsewhere.", "u": null, "notes": "concept: NI001671127623", "dep": null}, {"v": "Accumulateddepreciation", "n": "Accumulated depreciation", "d": "Used for reporting all depreciation amounts, including depreciation on assets that may not be included elsewhere.", "u": null, "notes": "concept: NI001671127624", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceGASBRevenueCategory', 'IPEDS revenue classification used by degree-granting public institutions using GASB Reporting Standards for reporting revenues and other additions by source including all operating revenues, nonoperating revenues, and other additions for the reporting period. This includes unrestricted and restricted revenues and additions, whether expendable or nonexpendable.', NULL, 'scheme: C001672', NULL, $j$[{"v": "Tuitionfeesnetofdiscountsallowances", "n": "Tuition and fees (net discounts and allowances)", "d": "Used for reporting all tuition and fees (including student activity fees) revenue received from students for education purposes. Include revenues for tuition and fees net of discounts and allowances from institutional and governmental scholarships, waivers, etc. (report gross revenues minus discounts and allowances). Includes those tuition and fees that are remitted to the state as an offset to state appropriations. (Charges for room, board, and other services rendered by auxiliary enterprises are not reported here.)", "u": null, "notes": "concept: NI001672127625", "dep": null}, {"v": "Federaloperatinggrantscontracts", "n": "Federal operating grants and contracts", "d": "Used for reporting revenues from federal governmental agencies that are for specific research projects or other types of programs and that are classified as operating revenues. Examples are research projects and similar activities for which amounts are received or expenditures are reimbursable under the terms of a grant or contract. Includes federal land grant appropriations if considered operating revenue. Does not include Pell grants or other federal student aid. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001672127626", "dep": null}, {"v": "Stateoperatinggrantscontracts", "n": "State operating grants and contracts", "d": "Used for reporting revenues from state governmental agencies that are for specific research projects or other types of programs and that are classified as operating revenues. Examples are research projects and similar activities for which amounts are received or expenditures are reimbursable under the terms of a grant or contract. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001672127627", "dep": null}, {"v": "Localgovernmentoperatinggrantscontracts", "n": "Local government operating grants and contracts", "d": "Used for reporting revenues from local governmental agencies that are for specific research projects or other types of programs and that are classified as operating revenues. Examples are research projects and similar activities for which amounts are received or expenditures are reimbursable under the terms of a grant or contract.", "u": null, "notes": "concept: NI001672127628", "dep": null}, {"v": "Privateoperatinggrantscontracts", "n": "Private operating grants and contracts", "d": "Used for reporting revenues from nongovernmental agencies and organizations that are for specific research projects or other types of programs and that are classified as operating revenues. Examples are research projects and similar activities for which amounts are received or expenditures are reimbursable under the terms of a grant or contract.", "u": null, "notes": "concept: NI001672127629", "dep": null}, {"v": "Salesservicesofauxiliaryenterprisesnetofdiscounts", "n": "Sales and services of auxiliary enterprises (net discounts and allowances)", "d": "Used for reporting revenues (net of discounts and allowances) generated by auxiliary enterprises that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics, college unions, college stores, and movie theaters.", "u": null, "notes": "concept: NI001672127630", "dep": null}, {"v": "Salesservicesofhospitalsafterdeducting", "n": "Sales and services of hospitals (after deducting patient contractual allowances)", "d": "Includes operating revenues (net of patient contractual allowances) for a hospital operated by the institution and clinics associated with training. Excludes clinics that are part of the student health services program.", "u": null, "notes": "concept: NI001672127631", "dep": null}, {"v": "Salesservicesofeducationalactivities", "n": "Sales and services of educational activities", "d": "Includes all operating revenues derived from the sales of goods or services that are incidental to the conduct of instruction, research or public service, and revenues of activities that exist to provide instructional and laboratory experience for students and that incidentally create goods and services that may be sold. Examples include film rentals, scientific and literary publications, testing services, university presses, dairies, and patient care clinics that are not part of a hospital.", "u": null, "notes": "concept: NI001672127632", "dep": null}, {"v": "Independentoperations", "n": "Independent operations", "d": "Includes all operating revenues associated with operations independent of the primary missions of the institution. This category generally includes only those revenues associated with major federally funded research and development centers. Does not include the net profit (or loss) from operations owned and managed as investments of the institution's endowment funds.", "u": null, "notes": "concept: NI001672127633", "dep": null}, {"v": "Otheroperatingrevenue", "n": "Other operating revenue", "d": "Used for reporting all other sources not reported elsewhere.", "u": null, "notes": "concept: NI001672127634", "dep": null}, {"v": "Federalappropriations", "n": "Federal appropriations", "d": "Used for reporting all amounts received by the institution through acts of a federal legislative body, except grants and contracts. Funds reported in this category are for meeting current operating expenses, not for specific projects or programs. An example is federal land-grant appropriations. If your institution accounts for land grant appropriations as operating revenue, they are excluded from this amount. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001672127635", "dep": null}, {"v": "Stateappropriations", "n": "State appropriations", "d": "Used for reporting all amounts received by the institution through acts of a state legislative body, except grants and contracts and amounts reportable as capital appropriations. Funds reported in this category are for meeting current operating expenses, not for specific projects or programs. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001672127636", "dep": null}, {"v": "Localappropriationseducationdistrict", "n": "Local appropriations, education district taxes, and similar support", "d": "Used for reporting all amounts received from property or other taxes assessed directly by or for an institution below the state level. Include any other similar general support provided to the institution from governments below the state level, including local government appropriations.", "u": null, "notes": "concept: NI001672127637", "dep": null}, {"v": "Federalnonoperatinggrants", "n": "Federal nonoperating grants", "d": "Used for reporting all amounts reported as nonoperating revenues from federal governmental agencies that are provided on a nonexchange basis. Includes Pell Grants and other Federal student grant aid. Does not include revenues from the Federal Direct Student Loan (FDSL) Program, Federal Work-Study or federal veteran education benefits. These amounts should be captured as tuition and fees and/or sales and services of auxiliary enterprise revenue upon receipt from the student. Does not include capital grants and gifts or any ARRA revenues.", "u": null, "notes": "concept: NI001672127638", "dep": null}, {"v": "Statenonoperatinggrants", "n": "State nonoperating grants", "d": "Used for reporting all amounts reported as nonoperating revenues from state governmental agencies that are provided on a nonexchange basis. Does not include capital grants and gifts or any ARRA revenues.", "u": null, "notes": "concept: NI001672127639", "dep": null}, {"v": "Localgovernmentnonoperatinggrants", "n": "Local government nonoperating grants", "d": "Used for reporting all amounts reported as nonoperating revenues from local governmental agencies and organizations that are provided on a nonexchange basis. Does not include capital grants and gifts.", "u": null, "notes": "concept: NI001672127640", "dep": null}, {"v": "Giftsincludingcontributionsfromaffiliated", "n": "Gifts, including contributions from affiliated organizations", "d": "Used for reporting revenues from private donors for which no legal consideration is provided; these would be nonexchange transactions as defined in GASB Statement No. 33 Accounting and Financial Reporting for Nonexchange Transactions. Includes all gifts or contributions to the institution except those classified as additions to permanent endowments or capital grants and gifts. Includes gifts from affiliated organizations. Includes the amount of contributed services recognized by the institution. Does not include capital grants and gifts.", "u": null, "notes": "concept: NI001672127641", "dep": null}, {"v": "Investmentincome", "n": "Investment income", "d": "Used for reporting all investment income not reported elsewhere.", "u": null, "notes": "concept: NI001672127642", "dep": null}, {"v": "Othernonoperatingrevenues", "n": "Other nonoperating revenues", "d": "Used for reporting all other nonoperating revenues not reported elsewhere. For institutions that received American Recovery and Reinvestment Act (ARRA) revenues during the reporting period, allow inclusion of these amounts.", "u": null, "notes": "concept: NI001672127643", "dep": null}, {"v": "Capitalappropriations", "n": "Capital appropriations", "d": "Used for reporting amounts provided by government appropriations intended primarily for acquisition or construction of capital assets for the institution.", "u": null, "notes": "concept: NI001672127644", "dep": null}, {"v": "Capitalgrantsgifts", "n": "Capital grants and gifts", "d": "Used for reporting amounts received from gifts or grants primarily intended to provide for the acquisition or construction of capital assets for the institution.", "u": null, "notes": "concept: NI001672127645", "dep": null}, {"v": "Additionstopermanentendowments", "n": "Additions to permanent endowments", "d": "Used for reporting gifts and other additions to endowments that are permanently nonexpendable.", "u": null, "notes": "concept: NI001672127646", "dep": null}, {"v": "Otherrevenuesadditions", "n": "Other revenues and additions", "d": "Used for reporting all other revenues and additions not reported elsewhere.", "u": null, "notes": "concept: NI001672127647", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceFASBRevenueCategory', 'IPEDS revenue classification used by degree-granting private, not-for-profit institutions and public institutions using FASB Reporting Standards for reporting revenues and investment return by source in a manner consistent with the definitions from the National Association of College and University Business Officers (NACUBO) Financial Accounting and Reporting Manual for Higher Education (FARM).', NULL, 'scheme: C001673', NULL, $j$[{"v": "Tuitionfeesnetofallowance", "n": "Tuition and fees (net of allowance)", "d": "Used for reporting the amount of tuition and educational fees, net of any allowances applied in the GPFS. Include in this amount all fees for continuing education programs, conferences, and seminars.", "u": null, "notes": "concept: NI001673127648", "dep": null}, {"v": "Federalappropriations", "n": "Federal appropriations", "d": "Used for reporting all amounts received from the federal government through a direct appropriation of Congress, except grants and contracts. An example of a federal appropriation is a federal land-grant appropriation. Does not include Pell Grants or any ARRA revenues.", "u": null, "notes": "concept: NI001673127649", "dep": null}, {"v": "Stateappropriations", "n": "State appropriations", "d": "Used for reporting all amounts received from a state government through a direct appropriation of its legislative body, except for state grants and contracts. An example of a state appropriation is an annual state appropriation for operating expenses of the institution. (FARM para. 463) Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001673127650", "dep": null}, {"v": "Localappropriations", "n": "Local appropriations", "d": "Used for reporting all amounts received from a local government (i.e., city and/or county) through a direct appropriation of its legislative body, except for local grants and contracts. An example of a local appropriation is an annual local appropriation for operating expenses of the institution.", "u": null, "notes": "concept: NI001673127651", "dep": null}, {"v": "Federalgrantscontracts", "n": "Federal grants and contracts", "d": "Used for reporting all revenues from federal agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from federal agencies. If federal Pell and similar student aid grants are treated as agency transactions in your GPFS, they are excluded from this amount. If federal Pell and similar student aid grants are treated as student aid expenses or as allowances when awarded, they are included from this amount. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001673127652", "dep": null}, {"v": "Stategrantscontracts", "n": "State grants and contracts", "d": "Used for reporting all revenues from state government agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from state agencies. If state grants for student aid are treated as agency transactions in your GPFS, they are excluded from this amount. If state grants for student aid are treated in your GPFS as student aid expenses or as allowances when awarded, include the grant revenue on this line and in Part C. Does not include any ARRA revenues.", "u": null, "notes": "concept: NI001673127653", "dep": null}, {"v": "Localgrantscontracts", "n": "Local grants and contracts", "d": "Used for reporting all revenues from local government agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from local agencies. If local grants for student aid are treated as agency transactions in your GPFS, they are excluded from this amount. If local grants for student aid are treated in your GPFS as student aid expenses or as allowances when awarded, they are included from this amount.", "u": null, "notes": "concept: NI001673127654", "dep": null}, {"v": "Privategifts", "n": "Private gifts", "d": "Used for reporting revenues from private (non-governmental) entities including revenues received from gift or contribution nonexchange transactions (including contributed services) except those from affiliated entities. Includes bequests, promises to give (pledges), gifts from an affiliated organization or a component unit not blended or consolidated, and income from funds held in irrevocable trusts or distributable at the direction of the trustees of the trusts. Includes any contributed services recognized (recorded) by the institution.", "u": null, "notes": "concept: NI001673127655", "dep": null}, {"v": "Privategrantscontracts", "n": "Private grants and contracts", "d": "Used for reporting revenues from private (non-governmental) entities that are for specific research projects, other types of programs, or for general institutional operations (if not government appropriations). Examples are research projects, training programs, and similar activities for which amounts are received or expenses are reimbursable under the terms of a grant or contract, including amounts to cover both direct and indirect expenses.", "u": null, "notes": "concept: NI001673127656", "dep": null}, {"v": "Contributionsfromaffiliatedentities", "n": "Contributions from affiliated entities", "d": "Used for reporting all revenues received from non-consolidated affiliated entities, such as fund raising foundations, booster clubs, other institutionally-related foundations, and similar organizations created to support the institution or organizational components of the institution.", "u": null, "notes": "concept: NI001673127657", "dep": null}, {"v": "Investmentreturn", "n": "Investment return", "d": "Used for reporting all investment income (i.e., interest, dividends, rents and royalties), gains and losses (realized and unrealized) from holding investments (regardless of the nature of the investment), student loan interest, and amounts distributed from irrevocable trusts held by others (collectively referred to as \"investment return\"). Changes in the value of interest rate swaps should be included in this amount.", "u": null, "notes": "concept: NI001673127658", "dep": null}, {"v": "Salesservicesofeducationalactivities", "n": "Sales and services of educational activities", "d": "Used for reporting all revenues derived from the sales of goods or services that are incidental to the conduct of instruction, research or public service, and revenues of activities that exist to provide instructional and laboratory experience for students and that incidentally create goods and services that may be sold. Examples include film rentals, scientific and literary publications, testing services, university presses, dairies, and patient care clinics that are not part of a hospital.", "u": null, "notes": "concept: NI001673127659", "dep": null}, {"v": "Salesservicesofauxiliaryenterprisesnetofallowance", "n": "Sales and services of auxiliary enterprises (net of allowance)", "d": "Used for reporting the amount of revenues generated by the auxiliary enterprise operations, net of any allowances applied in the general purpose financial statements. Auxiliary enterprises are operations that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics, college unions, college stores, and movie theaters.", "u": null, "notes": "concept: NI001673127660", "dep": null}, {"v": "Hospitalrevenuenottobereportedby", "n": "Hospital revenue (not to be reported by less-than-4-year institutions)", "d": "Used for reporting the amount of revenues generated by the auxiliary enterprise operations, net of any allowances applied in the general purpose financial statements. Auxiliary enterprises are operations that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics, college unions, college stores, and movie theaters.", "u": null, "notes": "concept: NI001673127661", "dep": null}, {"v": "Independentoperationsrevenuenottobe", "n": "Independent operations revenue (not to be reported by less-than-4-year institutions)", "d": "Used for reporting the revenues and gains of hospitals operated as a component of a reporting institution of higher education. If your hospital is reporting in IPEDS educational program activity that is conducted separate from an institution of higher education, they are excluded from this amount.", "u": null, "notes": "concept: NI001673127662", "dep": null}, {"v": "Otherrevenue", "n": "Other revenue", "d": "Used for reporting all revenues associated with operations independent of the primary missions of the institution. This category generally includes only those revenues associated with major federally-funded research and development centers. Does not include the profit (or loss) from operations owned and managed as investments of the institution's endowment funds.", "u": null, "notes": "concept: NI001673127663", "dep": null}, {"v": "Netassetsreleasedfromrestriction", "n": "Net assets released from restriction", "d": "Includes all other revenue not reported elsewhere.", "u": null, "notes": "concept: NI001673127664", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceFASBRevenueRestrictionCategory', 'IPEDS revenue restriction classification used by degree-granting private, not-for-profit institutions and public institutions using FASB Reporting Standards for reporting revenues by restriction.', NULL, 'scheme: C001674', NULL, $j$[{"v": "Unrestricted", "n": "Unrestricted", "d": "Used for reporting revenues that are not subject to limitations by a donor-imposed restriction.", "u": null, "notes": "concept: NI001674127665", "dep": null}, {"v": "TemporarilyRestricted", "n": "Temporarily Restricted", "d": "Used for reporting revenues that are subject to limitation by donor specification as to use or the time when use may occur (such as a later period of time or after specified events have occurred).", "u": null, "notes": "concept: NI001674127666", "dep": null}, {"v": "PermanentlyRestricted", "n": "Permanently Restricted", "d": "Used for reporting revenues that must be maintained in perpetuity due to a donor-imposed restriction.", "u": null, "notes": "concept: NI001674127667", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceGASBFunctionalExpenseCategory', 'A functional expense classification is a method of grouping expenses according to the purpose for which the costs are incurred. The classifications tell why an expense was incurred rather than what was purchased.', NULL, 'scheme: C001675', NULL, $j$[{"v": "Academicsupport", "n": "Academic support", "d": "A functional expense category that includes expenses of activities and services that support the institution's primary missions of instruction, research, and public service. It includes the retention, preservation, and display of educational materials (for example, libraries, museums, and galleries); organized activities that provide support services to the academic functions of the institution (such as a demonstration school associated with a college of education or veterinary and dental clinics if their primary purpose is to support the instructional program); media such as audiovisual services; academic administration (including academic deans but not department chairpersons); and formally organized and separately budgeted academic personnel development and course and curriculum development expenses. Also included are information technology expenses related to academic support activities; if an institution does not separately budget and expense information technology resources, the costs associated with the three primary programs will be applied to this function and the remainder to institutional support. Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001675127668", "dep": null}, {"v": "Instruction", "n": "Instruction", "d": "A functional expense category that includes expenses of the colleges, schools, departments, and other instructional divisions of the institution and expenses for departmental research and public service that are not separately budgeted. Includes general academic instruction, occupational and vocational instruction, community education, preparatory and adult basic education, and regular, special, and extension sessions. Also includes expenses for both credit and non-credit activities. Excludes expenses for academic administration where the primary function is administration (e.g., academic deans). Information technology expenses related to instructional activities if the institution separately budgets and expenses information technology resources are included (otherwise these expenses are included in academic support). Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001675127669", "dep": null}, {"v": "Research", "n": "Research", "d": "A functional expense category that includes expenses for activities specifically organized to produce research outcomes and commissioned by an agency either external to the institution or separately budgeted by an organizational unit within the institution. The category includes institutes and research centers, and individual and project research. This function does not include nonresearch sponsored programs (e.g., training programs). Also included are information technology expenses related to research activities if the institution separately budgets and expenses information technology resources (otherwise these expenses are included in academic support.) Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001675127670", "dep": null}, {"v": "Publicservice", "n": "Public service", "d": "A functional expense category that includes expenses for activities established primarily to provide noninstructional services beneficial to individuals and groups external to the institution. Examples are conferences, institutes, general advisory service, reference bureaus, and similar services provided to particular sectors of the community. This function includes expenses for community services, cooperative extension services, and public broadcasting services. Also includes information technology expenses related to the public service activities if the institution separately budgets and expenses information technology resources (otherwise these expenses are included in academic support). Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001675127671", "dep": null}, {"v": "Studentservices", "n": "Student services", "d": "A functional expense category that includes expenses for admissions, registrar activities, and activities whose primary purpose is to contribute to students emotional and physical well-being and to their intellectual, cultural, and social development outside the context of the formal instructional program. Examples include student activities, cultural events, student newspapers, intramural athletics, student organizations, supplemental instruction outside the normal administration, and student records. Intercollegiate athletics and student health services may also be included except when operated as self-supporting auxiliary enterprises. Also may include information technology expenses related to student service activities if the institution separately budgets and expenses information technology resources(otherwise these expenses are included in institutional support.) Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001675127672", "dep": null}, {"v": "Institutionalsupport", "n": "Institutional support", "d": "A functional expense category that includes expenses for the day-to-day operational support of the institution. Includes expenses for general administrative services, central executive-level activities concerned with management and long range planning, legal and fiscal operations, space management, employee personnel and records, logistical services such as purchasing and printing, and public relations and development. Also includes information technology expenses related to institutional support activities. If an institution does not separately budget and expense information technology resources, the IT costs associated with student services and operation and maintenance of plant will also be applied to this function.", "u": null, "notes": "concept: NI001675127673", "dep": null}, {"v": "Auxiliaryenterprises", "n": "Auxiliary enterprises", "d": "Expenses for essentially self-supporting operations of the institution that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to, although not necessarily equal to, the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics (only if essentially self-supporting), college unions, college stores, faculty and staff parking, and faculty housing. Institutions include actual or allocated costs for operation and maintenance of plant, interest and depreciation.", "u": null, "notes": "concept: NI001675127674", "dep": null}, {"v": "Scholarshipsfellowships", "n": "Scholarships and fellowships", "d": "That portion of scholarships and fellowships granted that exceeds the amount applied to institutional charges such as tuition and fees or room and board. The amount reported as expense excludes allowances and discounts. The FASB survey uses the term \"net grants in aid to students\" rather than \"scholarships and fellowships.\"", "u": null, "notes": "concept: NI001675127675", "dep": null}, {"v": "Hospitalservices", "n": "Hospital services", "d": "Expenses associated with a hospital operated by the postsecondary institution (but not as a component unit) and reported as a part of the institution. This classification includes nursing expenses, other professional services, general services, administrative services, and fiscal services. Also included are information technology expenses, actual or allocated costs for operation and maintenance of plant, interest and depreciation related to hospital capital assets.", "u": null, "notes": "concept: NI001675127676", "dep": null}, {"v": "Independentoperations", "n": "Independent operations", "d": "Expenses associated with operations that are independent of or unrelated to the primary missions of the institution (i.e., instruction, research, public service) although they may contribute indirectly to the enhancement of these programs. This category is generally limited to expenses of a major federally funded research and development center. Also includes information technology expenses, actual or allocated costs for operation and maintenance of plant, interest and depreciation related to the independent operations. Expenses of operations owned and managed as investments of the institution's endowment funds are excluded.", "u": null, "notes": "concept: NI001675127677", "dep": null}, {"v": "Other", "n": "Other", "d": null, "u": null, "notes": "concept: NI001675127678", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceNaturalExpenseCategory', 'A natural expense classification is a method of grouping expenses according to the type of costs that are incurred. The classifications tell what was purchased rather than why an expense was incurred.', NULL, 'scheme: C001676', NULL, $j$[{"v": "Salarieswages", "n": "Salaries and wages", "d": "Amounts paid as compensation for services to all employees - faculty, staff, part-time, full-time, regular employees, and student employees. This includes regular or periodic payment to a person for the regular or periodic performance of work or a service and payment to a person for more sporadic performance of work or a service (overtime, extra compensation, summer compensation, bonuses, sick or annual leave, etc.).", "u": null, "notes": "concept: NI001676127679", "dep": null}, {"v": "Benefits", "n": "Benefits", "d": "Cash contributions in the form of supplementary or deferred compensation other than salary. Excludes the employee's contribution. Employee fringe benefits include retirement plans, social security taxes, medical/dental plans, guaranteed disability income protection plans, tuition plans, housing plans, unemployment compensation plans, group life insurance plans, worker's compensation plans, and other benefits in-kind with cash options.", "u": null, "notes": "concept: NI001676127680", "dep": null}, {"v": "Operationmaintenanceofplant", "n": "Operation and maintenance of plant", "d": "An expense category that includes expenses for operations established to provide service and maintenance related to campus grounds and facilities used for educational and general purposes. Specific expenses include utilities, fire protection, property insurance, and similar items. This expense does include amounts charged to auxiliary enterprises, hospitals, and independent operations. Also includes information technology expenses related to operation and maintenance of plant activities if the institution separately budgets and expenses information technology resources (otherwise these expenses are included in institutional support).", "u": null, "notes": "concept: NI001676127681", "dep": null}, {"v": "Depreciation", "n": "Depreciation", "d": "The allocation or distribution of the cost of capital assets, less any salvage value, to expenses over the estimated useful life of the asset in a systematic and rational manner. Depreciation for the year is the amount of the allocation or distribution for the year involved.", "u": null, "notes": "concept: NI001676127682", "dep": null}, {"v": "Interest", "n": "Interest", "d": "The price paid (or received) for the use of money over a period of time. Interest income is one component of investment income. Interest paid by the institution is interest expense.", "u": null, "notes": "concept: NI001676127683", "dep": null}, {"v": "Other", "n": "Other", "d": null, "u": null, "notes": "concept: NI001676127684", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceGASBScholarshipsandFellowshipsRevenueCategory', 'IPEDS revenue category used by degree-granting public institutions using GASB Reporting Standards for the reporting of resources received for supporting student scholarships and fellowships.', NULL, 'scheme: C001677', NULL, $j$[{"v": "Pellgrants", "n": "Pell grants", "d": "The gross amount of Pell Grants made available to recipients by your institution. This is the gross Pell Grants received as federal grant revenue for the fiscal year.", "u": null, "notes": "concept: NI001677127685", "dep": null}, {"v": "Otherfederalgrants", "n": "Other federal grants", "d": "Federal monies awarded to the institution under federal government student aid programs, such as the Federal Supplemental Educational Opportunity Grants (FSEOG), DHHS training grants (aid portion only), the Leveraging Education Assistance Partnership (LEAP) program, and other federal student aid programs. Pell Grants are not included in this classification. Note: if the federal government selects the student recipients and simply transmits the funds to the institution for disbursement to the student, the amounts are not considered as revenues and subsequently there are no discounts and allowances or scholarships and fellowships expenses. If the funds are made available to the institution for selection of student recipients, then the amounts received are considered as nonoperating revenues and subsequently as discounts and allowances or scholarships and fellowships expenses.", "u": null, "notes": "concept: NI001677127686", "dep": null}, {"v": "Grantsbystategovernment", "n": "Grants by state government", "d": "Grant monies provided by the state such as Leveraging Educational Assistance Partnerships (LEAP) (formerly SSIG's); merit scholarships provided by the state; and tuition and fee waivers for which the institution was reimbursed by a state agency.", "u": null, "notes": "concept: NI001677127687", "dep": null}, {"v": "Grantsbylocalgovernment", "n": "Grants by local government", "d": "Local government grants include scholarships or gift-aid awarded directly to the student.", "u": null, "notes": "concept: NI001677127688", "dep": null}, {"v": "Institutionalgrantsfromrestrictedresources", "n": "Institutional grants from restricted resources", "d": "Institutional grants to students funded from restricted-expendable resources for student aid, such as scholarships and fellowships.", "u": null, "notes": "concept: NI001677127689", "dep": null}, {"v": "Institutionalgrantsfromunrestrictedresources", "n": "Institutional grants from unrestricted resources", "d": "Institutional grants to students that are funded from resources that are not restricted to any particular purpose.", "u": null, "notes": "concept: NI001677127690", "dep": null}, {"v": "Discountsallowancesappliedtotuitionfees", "n": "Discounts and allowances applied to tuition and fees", "d": "The amount of discounts and allowances that were recorded as an offset (reduction) to student tuition and fees.", "u": null, "notes": "concept: NI001677127691", "dep": null}, {"v": "Discountsallowancesappliedtosalesservices", "n": "Discounts and allowances applied to sales and services of auxiliary enterprises", "d": "The amount of discounts and allowances that were recorded as an offset (reduction) to revenues of auxiliary enterprises (room and board, books, meals, etc.).", "u": null, "notes": "concept: NI001677127692", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceFASBScholarshipsandFellowshipsRevenueCategory', 'IPEDS revenue category used by degree-granting private, not-for-profit institutions and public institutions using FASB Reporting Standards for the reporting of resources received for supporting student grant aid.', NULL, 'scheme: C001678', NULL, $j$[{"v": "Pellgrants", "n": "Pell grants", "d": "The gross amount of Pell Grants made available to recipients by your institution. This is the gross Pell Grants received as federal grant revenue for the fiscal year.", "u": null, "notes": "concept: NI001678127693", "dep": null}, {"v": "Otherfederalgrants", "n": "Other federal grants", "d": "Federal monies awarded to the institution under federal government student aid programs, such as the Federal Supplemental Educational Opportunity Grants (FSEOG), DHHS training grants (aid portion only), the Leveraging Education Assistance Partnership (LEAP) program, and other federal student aid programs. Pell Grants are not included in this classification. Note: if the federal government selects the student recipients and simply transmits the funds to the institution for disbursement to the student, the amounts are not considered as revenues and subsequently there are no discounts and allowances or scholarships and fellowships expenses. If the funds are made available to the institution for selection of student recipients, then the amounts received are considered as nonoperating revenues and subsequently as discounts and allowances or scholarships and fellowships expenses.", "u": null, "notes": "concept: NI001678127694", "dep": null}, {"v": "Grantsbystategovernment", "n": "Grants by state government", "d": "Grant monies provided by the state such as Leveraging Educational Assistance Partnerships (LEAP) (formerly SSIG's); merit scholarships provided by the state; and tuition and fee waivers for which the institution was reimbursed by a state agency.", "u": null, "notes": "concept: NI001678127695", "dep": null}, {"v": "Grantsbylocalgovernment", "n": "Grants by local government", "d": "Local government grants include scholarships or gift-aid awarded directly to the student.", "u": null, "notes": "concept: NI001678127696", "dep": null}, {"v": "Institutionalgrantsrestricted", "n": "Institutional grants (restricted)", "d": "Scholarships and fellowships awarded to students from institutional resources that are restricted to student aid. Private institutions generally report these grants as allowances. If control over these resources passes to the student, the amount is reported as an expense.", "u": null, "notes": "concept: NI001678127697", "dep": null}, {"v": "Institutionalgrantsunrestricted", "n": "Institutional grants (unrestricted)", "d": "Scholarships and fellowships awarded to students from unrestricted institutional resources. Private institutions generally report these grants as allowances. If control over these resources passes to the student, the amount is reported as an expense.", "u": null, "notes": "concept: NI001678127698", "dep": null}, {"v": "Discountsallowancesappliedtotuitionfees", "n": "Discounts and allowances applied to tuition and fees", "d": "The amount of allowances (scholarships) applied to tuition and fees.", "u": null, "notes": "concept: NI001678127699", "dep": null}, {"v": "Discountsallowancesappliedtoauxiliary", "n": "Discounts and allowances applied to auxiliary enterprise revenues", "d": "The amount of allowances (scholarships) applied to auxiliary enterprise revenues (e.g., dormitory charges).", "u": null, "notes": "concept: NI001678127700", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceIntercollegiateAthleticsExpenses', 'Identifies the functional expense category where the institution allocates its intercollegiate athletics expenses.', NULL, 'scheme: C001679', NULL, $j$[{"v": "Auxiliaryenterprises", "n": "Auxiliary enterprises", "d": "Expenses for essentially self-supporting operations of the institution that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to, although not necessarily equal to, the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics (only if essentially self-supporting), college unions, college stores, faculty and staff parking, and faculty housing. Institutions include actual or allocated costs for operation and maintenance of plant, interest and depreciation.", "u": null, "notes": "concept: NI001679127701", "dep": null}, {"v": "Studentservices", "n": "Student services", "d": "A functional expense category that includes expenses for admissions, registrar activities, and activities whose primary purpose is to contribute to students emotional and physical well-being and to their intellectual, cultural, and social development outside the context of the formal instructional program. Examples include student activities, cultural events, student newspapers, intramural athletics, student organizations, supplemental instruction outside the normal administration, and student records. Intercollegiate athletics and student health services may also be included except when operated as self-supporting auxiliary enterprises. Also may include information technology expenses related to student service activities if the institution separately budgets and expenses information technology resources(otherwise these expenses are included in institutional support.) Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.", "u": null, "notes": "concept: NI001679127702", "dep": null}, {"v": "Doesnotparticipateinintercollegiateathletics", "n": "Does not participate in intercollegiate athletics", "d": null, "u": null, "notes": "concept: NI001679127703", "dep": null}, {"v": "Other", "n": "Other", "d": null, "u": null, "notes": "concept: NI001679127704", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IPEDSFinanceFASBPellGrantTransactions', 'Method of reporting Pell Grants in IPEDS by degree-granting private, not-for-profit institutions and public institutions using FASB Reporting Standards.', NULL, 'scheme: C001680', NULL, $j$[{"v": "Passthrough", "n": "Pass through", "d": "A pass-through transaction is essentially a payment on the student's account where the institution is purely processing the Pell Grant and those monies are not counted by the institution until they come in as a tuition payment from the student. The latter option is sometimes referred to as an agency transaction. With this option Pell grants are not counted as federal revenues and are not considered to be a discount/allowance to tuition and fees or auxiliary enterprises.", "u": null, "notes": "concept: NI001680127705", "dep": null}, {"v": "Federalgrantrevenue", "n": "Federal grant revenue", "d": "Pell grants are counted as federal revenue and allowance to tuition and fees and/or auxiliary enterprises (for room and board, books, meals, etc.). There should be an offsetting discount/allowance to tuition and fees revenue and/or auxiliary enterprise revenue so that the Pell grants are not being double counted in the institution's revenues.", "u": null, "notes": "concept: NI001680127706", "dep": null}, {"v": "DoesnotawardPellgrants", "n": "Does not award Pell grants", "d": null, "u": null, "notes": "concept: NI001680127707", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IndividualizedProgramServicePlanProgressReportSchedule', 'Frequency by which parents are notified of the student''s progress on annual goals and if the progress is sufficient to achieve the goals by the end of the individualized program service plan year.', NULL, 'scheme: C001681', NULL, $j$[{"v": "Daily", "n": "Daily", "d": "Daily is the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127708", "dep": null}, {"v": "Weekly", "n": "Weekly", "d": "Weekly is the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127709", "dep": null}, {"v": "Monthly", "n": "Monthly", "d": "Monthly is the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127710", "dep": null}, {"v": "Quarterly", "n": "Quarterly", "d": "Quarterly is the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127711", "dep": null}, {"v": "Term", "n": "Term", "d": "Term is the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127712", "dep": null}, {"v": "Other", "n": "Other", "d": "Other is specified as the frequency by which parents are notified of the student's progress on annual goals.", "u": null, "notes": "concept: NI001681127713", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('GoalMeasurementType', 'Type of evidence appropriate for assessing achievement of a goal or short-term objective.', NULL, 'scheme: C001697', NULL, $j$[{"v": "Observationlog", "n": "Observation log", "d": "Observation log is specified as the type of evidence appropriate for assessing achievement of a goal or short-term objective.", "u": null, "notes": "concept: NI001697127714", "dep": null}, {"v": "Datacharts", "n": "Data charts", "d": "Data charts are specified as the type of evidence appropriate for assessing achievement of a goal or short-term objective.", "u": null, "notes": "concept: NI001697127715", "dep": null}, {"v": "Tests", "n": "Tests", "d": "Tests are specified as the type of evidence appropriate for assessing achievement of a goal or short-term objective.", "u": null, "notes": "concept: NI001697127716", "dep": null}, {"v": "Other", "n": "Other", "d": "The type of evidence appropriate for assessing achievement of a goal or short-term objective is in a category not yet defined in CEDS.", "u": null, "notes": "concept: NI001697127717", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IEPGoalType', 'Legal category for an IEP annual goal or short-term objectives.', NULL, 'scheme: C001698', NULL, $j$[{"v": "Academic", "n": "Academic", "d": "Academic is the legal category for an IEP annual goal or short-term objectives.", "u": null, "notes": "concept: NI001698127718", "dep": null}, {"v": "Functional", "n": "Functional", "d": "Functional is the legal category for an IEP annual goal or short-term objectives.", "u": null, "notes": "concept: NI001698127719", "dep": null}, {"v": "Transitional", "n": "Transitional", "d": "Transitional is the legal category for an IEP annual goal or short-term objectives.", "u": null, "notes": "concept: NI001698127720", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IndividualizedProgramServicePlanProgressReportType', 'A method by which parents are notified of the student''s progress on annual goals and if the progress is sufficient to achieve the goals by the end of the individualized program service plan.', NULL, 'scheme: C001701', NULL, $j$[{"v": "Reportcard", "n": "Report card", "d": "Report card is a method by which parents are notified of the student's progress on annual goal.", "u": null, "notes": "concept: NI001701127721", "dep": null}, {"v": "Progressreports", "n": "Progress reports", "d": "Progress reports are a method by which parents are notified of the student's progress on annual goal.", "u": null, "notes": "concept: NI001701127722", "dep": null}, {"v": "Parentconference", "n": "Parent conference", "d": "Parent conference is a method by which parents are notified of the student's progress on annual goal.", "u": null, "notes": "concept: NI001701127723", "dep": null}, {"v": "Other", "n": "Other", "d": "The method by which parents are notified of the student's progress on annual goal is in a category not yet defined in CEDS.", "u": null, "notes": "concept: NI001701127724", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('GoalStatusType', 'Status toward achievement of the annual goal or short-term objectives.', NULL, 'scheme: C001702', NULL, $j$[{"v": "SatisfactoryProgress", "n": "Satisfactory Progress", "d": "Satisfactory Progress is specified as the status toward achievement of the annual goal or short-term objectives.", "u": null, "notes": "concept: NI001702127725", "dep": null}, {"v": "UnsatisfactoryProgress", "n": "Unsatisfactory Progress", "d": "Unsatisfactory Progress is specified as the status toward achievement of the annual goal or short-term objectives.", "u": null, "notes": "concept: NI001702127726", "dep": null}, {"v": "Completed", "n": "Completed", "d": "Completed is specified as the status toward achievement of the annual goal or short-term objectives.", "u": null, "notes": "concept: NI001702127727", "dep": null}, {"v": "Other", "n": "Other", "d": "The status toward achievement of the annual goal or short-term objectives is in a category not yet defined in CEDS.", "u": null, "notes": "concept: NI001702127728", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FrequencyUnit', 'The unit of time by which a cycle is defined.', NULL, 'scheme: C001713', NULL, $j$[{"v": "Minute", "n": "Minute", "d": "Minute is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127729", "dep": null}, {"v": "Hour", "n": "Hour", "d": "Hour is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127730", "dep": null}, {"v": "Day", "n": "Day", "d": "Day is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127731", "dep": null}, {"v": "Week", "n": "Week", "d": "Week is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127732", "dep": null}, {"v": "Month", "n": "Month", "d": "Month is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127733", "dep": null}, {"v": "Year", "n": "Year", "d": "Year is the unit of time by which a cycle is defined.", "u": null, "notes": "concept: NI001713127734", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IEPAuthorizationDocumentType', 'Type of Individualized Education Plan document authorized.', NULL, 'scheme: C001719', NULL, $j$[{"v": "Placement", "n": "Placement", "d": "Placement is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127735", "dep": null}, {"v": "Amendment", "n": "Amendment", "d": "Amendment is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127736", "dep": null}, {"v": "AnnualGoal", "n": "Annual Goal", "d": "Annual Goal is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127737", "dep": null}, {"v": "MeasurableObjective", "n": "Measurable Objective", "d": "Measurable Objective is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127738", "dep": null}, {"v": "IEP", "n": "IEP", "d": "IEP is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127739", "dep": null}, {"v": "Revoke", "n": "Revoke", "d": "Revoke is specified as the type of Individualized Education Plan document authorized.", "u": null, "notes": "concept: NI001719127740", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AuthorizerType', 'Type of person who authorized the decision or document.', NULL, 'scheme: C001720', NULL, $j$[{"v": "Staff", "n": "Staff", "d": "Staff is specified as the type of person who authorized the decision or document.", "u": null, "notes": "concept: NI001720127741", "dep": null}, {"v": "Student", "n": "Student", "d": "Student is specified as the type of person who authorized the decision or document.", "u": null, "notes": "concept: NI001720127742", "dep": null}, {"v": "Parent/Guardian", "n": "Parent/Guardian", "d": "Parent/Guardian is specified as the type of person who authorized the decision or document.", "u": null, "notes": "concept: NI001720127743", "dep": null}, {"v": "LEARepresentative", "n": "LEA Representative", "d": "LEA Representative is specified as the type of person who authorized the decision or document.", "u": null, "notes": "concept: NI001720127744", "dep": null}, {"v": "OutsideAgencySupportRepresentative", "n": "Outside Agency Support Representative", "d": "Outside Agency Support Representative is specified as the type of person who authorized the decision or document.", "u": null, "notes": "concept: NI001720127745", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IEPEligibilityEvaluationType', 'Purpose within the IEP lifecycle for which the eligibility evaluation is conducted.', NULL, 'scheme: C001728', NULL, $j$[{"v": "Initial", "n": "Initial", "d": "Initial is the purpose within the IEP lifecycle for which the eligibility evaluation is conducted.", "u": null, "notes": "concept: NI001728127746", "dep": null}, {"v": "Reevaluation", "n": "Reevaluation", "d": "Reevaluation is the purpose within the IEP lifecycle for which the eligibility evaluation is conducted.", "u": null, "notes": "concept: NI001728127747", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('IDEADisabilityType', 'A category of disability that describes a person''s impairment defined by the Individuals with Disabilities Education Act.', NULL, 'scheme: C001733', NULL, $j$[{"v": "Specificlearningdisability", "n": "Specific learning disability", "d": "Specific learning disability means a disorder in one or more of the basic psychological processes involved in understanding or in using language, spoken or written, that may manifest itself in the imperfect ability to listen, think, speak, read, write, spell, or to do mathematical calculations, including conditions such as perceptual disabilities, brain injury, minimal brain dysfunction, dyslexia, and developmental aphasia.", "u": null, "notes": "concept: NI001733127775", "dep": null}, {"v": "Speechlanguageimpairment", "n": "Speech or language impairment", "d": "Speech or language impairment means a communication disorder, such as stuttering, impaired articulation, a language impairment, or a voice impairment, that adversely affects a child's educational performance.", "u": null, "notes": "concept: NI001733127776", "dep": null}, {"v": "Traumaticbraininjury", "n": "Traumatic brain injury", "d": "Traumatic brain injury means an acquired injury to the brain caused by an external physical force, resulting in total or partial functional disability or psychosocial impairment, or both, that adversely affects a child's educational performance. Traumatic brain injury applies to open or closed head injuries resulting in impairments in one or more areas, such as cognition; language; memory; attention; reasoning; abstract thinking; judgment; problem-solving; sensory, perceptual, and motor abilities; psychosocial behavior; physical functions; information processing; and speech. Traumatic brain injury does not apply to brain injuries that are congenital or degenerative, or to brain injuries induced by birth trauma.", "u": null, "notes": "concept: NI001733127777", "dep": null}, {"v": "Visualimpairment", "n": "Visual impairment", "d": "Visual impairment including blindness means an impairment in vision that, even with correction, adversely affects a child's educational performance. The term includes both partial sight and blindness.", "u": null, "notes": "concept: NI001733127778", "dep": null}, {"v": "Autism", "n": "Autism", "d": "Autism means a developmental disability significantly affecting verbal and nonverbal communication and social interaction, generally evident before age three, that adversely affects a child's educational performance. Other characteristics often associated with autism are engagement in repetitive activities and stereotyped movements, resistance to environmental change or change in daily routines, and unusual responses to sensory experiences.", "u": null, "notes": "concept: NI001733127765", "dep": null}, {"v": "Deafblindness", "n": "Deaf-blindness", "d": "Deaf-blindness means concomitant hearing and visual impairments, the combination of which causes such severe communication and other developmental and educational needs that they cannot be accommodated in special education programs solely for children with deafness or children with blindness.", "u": null, "notes": "concept: NI001733127766", "dep": null}, {"v": "Deafness", "n": "Deafness", "d": "Deafness means a hearing impairment that is so severe that the child is impaired in processing linguistic information through hearing, with or without amplification, that adversely affects a child's educational performance.", "u": null, "notes": "concept: NI001733127767", "dep": null}, {"v": "Developmentaldelay", "n": "Developmental delay", "d": "Developmental delays are defined by the State and as measured by appropriate diagnostic instruments and procedures in one or more of the following areas: Physical development, cognitive development, communication development, social or emotional development, or adaptive development; and result in the need of special education and related services.", "u": null, "notes": "concept: NI001733127768", "dep": null}, {"v": "Emotionaldisturbance", "n": "Emotional disturbance", "d": "Emotional disturbance means a condition exhibiting one or more of the following characteristics over a long period of time and to a marked degree that adversely affects a child's educational performance: an inability to learn that cannot be explained by intellectual, sensory, or health factors; an inability to build or maintain satisfactory interpersonal relationships with peers and teachers; inappropriate types of behavior or feelings under normal circumstances; a general pervasive mood of unhappiness or depression, or tendency to develop physical symptoms or fears associated with personal or school problems.", "u": null, "notes": "concept: NI001733127769", "dep": null}, {"v": "Hearingimpairment", "n": "Hearing impairment", "d": "Hearing impairment means an impairment in hearing, whether permanent or fluctuating, that adversely affects a child's educational performance but that is not included under the definition of deafness.", "u": null, "notes": "concept: NI001733127770", "dep": null}, {"v": "Intellectualdisability", "n": "Intellectual disability", "d": "Intellectual disability means significantly subaverage general intellectual functioning, existing concurrently with deficits in adaptive behavior and manifested during the developmental period, that adversely affects a child's educational performance.", "u": null, "notes": "concept: NI001733127771", "dep": null}, {"v": "Multipledisabilities", "n": "Multiple disabilities", "d": "Multiple disabilities means concomitant impairments (such as intellectual disability-blindness or intellectual disability-orthopedic impairment), the combination of which causes such severe educational needs that they cannot be accommodated in special education programs solely for one of the impairments. Multiple disabilities does not include deaf-blindness.", "u": null, "notes": "concept: NI001733127772", "dep": null}, {"v": "Orthopedicimpairment", "n": "Orthopedic impairment", "d": "Orthopedic impairment means a severe orthopedic impairment that adversely affects a child's educational performance. The term includes impairments caused by a congenital anomaly, impairments caused by disease (e.g., poliomyelitis, bone tuberculosis), and impairments from other causes (e.g., cerebral palsy, amputations, and fractures or burns that cause contractures).", "u": null, "notes": "concept: NI001733127773", "dep": null}, {"v": "Otherhealthimpairment", "n": "Other health impairment", "d": "Other health impairment means having limited strength, vitality, or alertness, including a heightened alertness to environmental stimuli, that results in limited alertness with respect to the educational environment, that is due to chronic or acute health problems such as asthma, attention deficit disorder or attention deficit hyperactivity disorder, diabetes, epilepsy, a heart condition, hemophilia, lead poisoning, leukemia, nephritis, rheumatic fever, sickle cell anemia, and Tourette syndrome; and diversely affects a child's educational performance.", "u": null, "notes": "concept: NI001733127774", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialDefinitionAssessmentMethodType', 'The method used to conduct the assessment being referenced.', NULL, 'scheme: C001738', NULL, $j$[{"v": "Artifact", "n": "Artifact", "d": "A work or product created to be persistent in some medium. Artifact includes, but is not limited to, an academic paper, video documentary, computer software, music composition, choreography, novel, short story, journal article, news article, report, lesson plan, product design, manufactured product, etc. Methods of evaluation may include multiple evaluators either individually or as an expert panel using general criteria or more structured rubrics whose scores are combined, etc. Criteria and methods of evaluation are often very similar to those for assessing a performance, without the facets specific to a live performance.", "u": null, "notes": "concept: NI001738127779", "dep": null}, {"v": "Exam", "n": "Exam", "d": "A mix of scored items presented in fixed or open response formats. Exams may be human- or machine-scored and include, but are not limited to, multiple choice, true-false, written essay, short-answer, fill-in or oral response formats that could include measurements of reasoning, problem-solving, critical thinking.", "u": null, "notes": "concept: NI001738127780", "dep": null}, {"v": "Performance", "n": "Performance", "d": "A demonstration or performance that is usually assessed while the performance is taking place or as recorded for assessment purposes after the performance. Performance includes, but is not limited to, dance, music, teaching, acting, medical procedures, truck driving, manufacturing production, etc. Criteria include the categories and benchmarks on which the performance is assessed. Methods of evaluation can include multiple evaluators either individually or as an expert panel using general criteria or more structured rubrics whose scores are combined.", "u": null, "notes": "concept: NI001738127781", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialDefinitionIdentifierSystem', 'A coding scheme that is used for identification and record-keeping purposes by a credentialing organization to refer to a qualification, achievement, personal or organizational quality, or aspect of an identity.', NULL, 'scheme: C001739', NULL, $j$[{"v": "CTID", "n": "Credential Transparency Identifier", "d": "A globally unique Credential Transparency Identifier issued by the Credential Registry Service by which the creator/owner/provider of a credential recognizes the credential in transactions with the external environment.", "u": null, "notes": "concept: NI001739127782", "dep": null}, {"v": "URI", "n": "Uniform Resource Identifier", "d": "A string of characters used to identify a resource.", "u": null, "notes": "concept: NI001739127783", "dep": null}, {"v": "URL", "n": "Uniform Resource Locator", "d": "A Uniform Resource Locator, commonly informally termed a web address is a reference to a web resource that specifies its location on a computer network and a mechanism for retrieving it.", "u": null, "notes": "concept: NI001739127784", "dep": null}, {"v": "URN", "n": "Uniform Resource Name", "d": "A string of characters used to identify a name of a web resource.", "u": null, "notes": "concept: NI001739127785", "dep": null}, {"v": "UUID", "n": "Universally Unique Identifier", "d": "128-bit number used to identify information in computer systems.", "u": null, "notes": "concept: NI001739127786", "dep": null}, {"v": "ARK", "n": "Archival Resource Key", "d": "A Uniform Resource Locator that is a multi-purpose persistent identifier for information objects of any type.", "u": null, "notes": "concept: NI001739127787", "dep": null}, {"v": "DOI", "n": "Digital Document Identifier", "d": "A persistent identifier or handle used to uniquely identify objects, standardized by the ISO.", "u": null, "notes": "concept: NI001739127788", "dep": null}, {"v": "INFO", "n": "INFO URI Scheme", "d": "An identifier for information assets that have identifiers in public namespaces but are not part of the URI allocation.", "u": null, "notes": "concept: NI001739127789", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialDefinitionStatusType', 'The status of the credential offered by a credentialing organization.', NULL, 'scheme: C001740', NULL, $j$[{"v": "Active", "n": "Active", "d": "Awards of the credential are ongoing.", "u": null, "notes": "concept: NI001740127790", "dep": null}, {"v": "Deprecated", "n": "Deprecated", "d": "The credential is no longer awarded.", "u": null, "notes": "concept: NI001740127791", "dep": null}, {"v": "Probationary", "n": "Probationary", "d": "The credential award is provisional or temporary; frequently pending further assessment of qualification.", "u": null, "notes": "concept: NI001740127792", "dep": null}, {"v": "Superseded", "n": "Superseded", "d": "The credential is no longer awarded and has been superseded by another credential.", "u": null, "notes": "concept: NI001740127793", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialDefinitionIntendedPurposeType', 'The intended type of application of the credential by the holder.', NULL, 'scheme: C001749', NULL, $j$[{"v": "GeneralEducation", "n": "General Education", "d": "The intended purpose of the credential by the holder is general education.", "u": null, "notes": "concept: NI001749127794", "dep": null}, {"v": "JobOrCareerPreparation", "n": "Job/Career Preparation", "d": "The intended purpose of the credential by the holder is job or career preparation.", "u": null, "notes": "concept: NI001749127795", "dep": null}, {"v": "MidCareer", "n": "Mid-Career Level", "d": "The intended purpose of the credential by the holder is for mid-career, experienced worker preparation and advancement.", "u": null, "notes": "concept: NI001749127796", "dep": null}, {"v": "PriorExperience", "n": "Prior Learning Experience", "d": "The intended purpose of the credential by the holder is for determining prior learning experience of the holder, including but not limited to college credit.", "u": null, "notes": "concept: NI001749127797", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialDefinitionVerificationType', 'A resource describing the means by which someone can verify whether a credential has been attained by a person.', NULL, 'scheme: C001753', NULL, $j$[{"v": "BadgeClaim", "n": "Badge Claim", "d": "Verifiable representation of a credential holder's badge that is controlled by the credentialing organization.", "u": null, "notes": "concept: NI001753127798", "dep": null}, {"v": "TranscriptClaim", "n": "Transcript Claim", "d": "Verifiable representation of postsecondary courses and degrees that is controlled by the credentialing organization.", "u": null, "notes": "concept: NI001753127799", "dep": null}, {"v": "VerifiedClaim", "n": "Verified Claim", "d": "Verifiable representation of the credential holder's credential that is controlled by the credentialing organization.", "u": null, "notes": "concept: NI001753127800", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CTDLOrganizationType', 'The type of credentialing organization or entity as defined by the Credential Transparency Description Language.', NULL, 'scheme: C001755', NULL, $j$[{"v": "AssessmentBody", "n": "Assessment Body", "d": "Primarily offers access to assessments for credentials as a service.", "u": null, "notes": "concept: NI001755127801", "dep": null}, {"v": "Business", "n": "Business", "d": "An organization that primarily sells products or services and employs one or more individuals.", "u": null, "notes": "concept: NI001755127802", "dep": null}, {"v": "BusinessAssociation", "n": "Business or Industry Association", "d": "A membership organization primarily engaged in promoting the interests of their business members and providing them with services that may involve the provision of education and credentialing services.", "u": null, "notes": "concept: NI001755127803", "dep": null}, {"v": "CertificationBody", "n": "Certification Body", "d": "An independent, third-party organization that operates a certification program. A certification body may or may not be governmental, and may or may not have regulatory authority.", "u": null, "notes": "concept: NI001755127804", "dep": null}, {"v": "FourYear", "n": "Four-Year College", "d": "Authorized postsecondary institution that primarily offers bachelor or higher degrees, but may also award associate degrees. Includes free-standing medical, law or other first-professional schools, schools that offer postbaccalaureate certificates only, those that offer graduate programs only, etc.", "u": null, "notes": "concept: NI001755127805", "dep": null}, {"v": "Government", "n": "Government Agency", "d": "An organization in the public sector at the federal, state or local levels. Includes quasi-governmental organizations, special districts (e.g., libraries), corrections organizations, etc., except college and school districts. Is also responsible for the oversight and administration of specific functions other than the military services.", "u": null, "notes": "concept: NI001755127806", "dep": null}, {"v": "HighSchool", "n": "High School", "d": "A secondary school providing instruction and educational services that do not focus primarily on career and technical education or alternative education.", "u": null, "notes": "concept: NI001755127807", "dep": null}, {"v": "LaborUnion", "n": "Labor Union", "d": "A membership organization of workers formed for the purpose of advancing its members' interests in respect to wages, benefits, and working conditions.", "u": null, "notes": "concept: NI001755127808", "dep": null}, {"v": "Magnet", "n": "Magnet/Competitive Admissions School", "d": "A public school offering special instruction and programs not available elsewhere, designed to attract a more diverse student body from throughout a school district.", "u": null, "notes": "concept: NI001755127809", "dep": null}, {"v": "Military", "n": "Military", "d": "The armed services of a government entity.", "u": null, "notes": "concept: NI001755127810", "dep": null}, {"v": "NonTraditional", "n": "Alternative/Non-Traditional School", "d": "A secondary school that: 1) addresses needs of students which cannot typically be met in a regular school; 2) provides nontraditional education; and 3) falls outside of the categories of regular, magnet/special program emphasis, or career and technical education.", "u": null, "notes": "concept: NI001755127811", "dep": null}, {"v": "Postsecondary", "n": "Postsecondary Educational Institution", "d": "An organization such as a college or university: (1) whose sole purpose is to provide postsecondary education defined as the provision of a formal instructional program whose curriculum is designed primarily for students who are beyond the compulsory age for high school and (2) has the authority to award degrees. This includes programs whose purpose is academic, vocational, and continuing professional education.", "u": null, "notes": "concept: NI001755127812", "dep": null}, {"v": "PrimarilyOnline", "n": "Primarily Online", "d": "An organization that primarily operates online.", "u": null, "notes": "concept: NI001755127813", "dep": null}, {"v": "ProfessionalAssociation", "n": "Professional Association", "d": "A membership organization primarily engaged in promoting the interests of a particular profession, the interests of individuals engaged in that profession, and providing them with services that may involve the provision of education and credentialing services.", "u": null, "notes": "concept: NI001755127814", "dep": null}, {"v": "QualityAssurance", "n": "Quality Assurance Body", "d": "External body that performs accreditation, endorsement, approval, and/or recognition of a credential issuer.", "u": null, "notes": "concept: NI001755127815", "dep": null}, {"v": "SecondarySchool", "n": "Secondary School", "d": "A secondary school primarily providing education to students at the ninth grade or higher.", "u": null, "notes": "concept: NI001755127816", "dep": null}, {"v": "Technical", "n": "Career and Technical School", "d": "A secondary school that focuses primarily on providing formal preparation for skilled, technical or professional occupations or careers.", "u": null, "notes": "concept: NI001755127817", "dep": null}, {"v": "TrainingProvider", "n": "Education and Training Provider", "d": "An organization whose major purpose is to provide education and training services but is not a postsecondary education institution with the authority to award degrees. Includes community-based organizations, non-degree granting proprietary schools which are education and training providers that are recognized by states as schools and are Title IV eligible but do not award degrees, etc.", "u": null, "notes": "concept: NI001755127818", "dep": null}, {"v": "TwoYear", "n": "Two-Year College", "d": "Authorized postsecondary institution that primarily offers associate degrees, but may also award higher degrees.", "u": null, "notes": "concept: NI001755127819", "dep": null}, {"v": "Vendor", "n": "Vendor", "d": "Sells, maintains, and issues credentials for its own products and services for public access and use.", "u": null, "notes": "concept: NI001755127820", "dep": null}]$j$::jsonb);
