SELECT public.ceds_tmp_valueset('BuildingCharterSchoolRealtyAccessType', 'The type of real estate vehicle through which a public charter school has access and control of its building space.', NULL, 'scheme: C001865', NULL, $j$[{"v": "13691", "n": "Leasehold", "d": "Legal interest in real property acquired by a tenant (lessee) when he/she enters into a rental agreement with the owner of the property (landlord or lessor). Normally for a fixed period of time at a specified price, without transfer of ownership.", "u": null, "notes": "concept: NI001865128603", "dep": null}, {"v": "13692", "n": "Ownership by Charter Non-Profit Corporation", "d": "The charter non-profit corporation owns the facility and pays for the expenses, including the mortgage payments, utilities, maintenance, and repairs.", "u": null, "notes": "concept: NI001865128604", "dep": null}, {"v": "13693", "n": "Third Party Non-Profit Ownership", "d": "A third party non-profit corporation owns the facility where the charter school operates in.", "u": null, "notes": "concept: NI001865128605", "dep": null}, {"v": "14907", "n": "Third-party public sector ownership", "d": "Third-party public sector ownership is specified as the type of real estate vehicle through which a public charter school has access and control of its building space.", "u": null, "notes": "concept: NI001865128606", "dep": null}]$j$::jsonb);
