SELECT public.ceds_tmp_valueset('BuildingCleaningStandardType', 'The standard for cleanliness, and benchmarks for how much space can be assigned to one properly supplied custodian to meet these standards.', NULL, 'scheme: C001866', NULL, $j$[{"v": "02831", "n": "Level 1 cleaning", "d": "`Spotless` cleaning, such as might be found in a hospital or corporate suite. One custodian, properly supplied and equipped, should be able to clean 10,000 square feet in an 8-hour period, depending upon the condition and level of utilization of the facility.", "u": null, "notes": "concept: NI001866128616", "dep": null}, {"v": "02832", "n": "Level 2 cleaning", "d": "Intensive cleaning, reserved for areas such as restrooms, special education areas, kindergarten areas, or food service areas. One custodian, properly supplied and equipped, can clean approximately 11,000-18,000 square feet in an 8-hour period, depending upon the condition and level of utilization of the facility.", "u": null, "notes": "concept: NI001866128617", "dep": null}, {"v": "02833", "n": "Level 3 cleaning", "d": "Cleaning required to ensure the health and comfort of building users. One custodian, properly supplied and equipped, should be able to clean 19,000-25,000 square feet of space in 8 hours to this standard, depending upon the condition and utilization of the facility.", "u": null, "notes": "concept: NI001866128618", "dep": null}, {"v": "02834", "n": "Level 4 cleaning", "d": "Not generally acceptable for a school environment. One custodian cleans 26,000-46,000 square feet in an 8-hour period.", "u": null, "notes": "concept: NI001866128619", "dep": null}, {"v": "02835", "n": "Level 5 cleaning", "d": "Not considered healthy. One custodian, even properly supplied and equipped, will not be able to clean 47,000-80,000 square feet in an 8-hour period, to a healthy standard, whatever the underlying condition or utilization of the facility.", "u": null, "notes": "concept: NI001866128620", "dep": null}]$j$::jsonb);
