SELECT public.ceds_tmp_valueset('SchoolType', 'The type of education institution as classified by its primary focus.', NULL, 'scheme: C000242', NULL, $j$[{"v": "Regular", "n": "Regular School", "d": "A school that does not focus primarily on career and technical, special, or alternative education, although it may provide these programs in addition to a regular curriculum.", "u": null, "notes": "concept: NI000242129394", "dep": null}, {"v": "Special", "n": "Special Education School", "d": "A school that focuses primarily on serving the educational needs of students with disabilities (IDEA) and which adapts curriculum, materials, or instruction for these students.", "u": null, "notes": "concept: NI000242129395", "dep": null}, {"v": "CareerAndTechnical", "n": "Career and Technical Education School", "d": "A school that focuses primarily on providing secondary students with an occupationally relevant or career�related curriculum, including formal preparation for technical or professional occupations.", "u": null, "notes": "concept: NI000242129396", "dep": null}, {"v": "Alternative", "n": "Alternative Education School", "d": "A school that addresses the needs of students that typically cannot be met in a regular school program and is designed to meet the needs of students with academic difficulties, students with discipline problems, or both students with academic difficulties and discipline problems.", "u": null, "notes": "concept: NI000242129397", "dep": null}, {"v": "Reportable", "n": "Reportable Program", "d": "The permitted value \"reportable program\" is available for SEAs that have data to report to EDFacts at the school level that the SEA has determined does not meet the definition of a public elementary/secondary school.", "u": null, "notes": "concept: NI000242129398", "dep": null}]$j$::jsonb);
