SELECT public.ceds_tmp_valueset('BuildingJointUseSchedulingType', 'The type of designation of non school district users by the amount of time they have access to public school for joint use.', NULL, 'scheme: C001853', NULL, $j$[{"v": "13694", "n": "Drop-in use", "d": "When the space is made available for informal, drop-in activities. In this case, the user does not reserve the space in advance. Usually, spaces are made available for drop-in use during specified hours and often the spaces available for drop-in use are outside the school building on the school grounds.", "u": null, "notes": "concept: NI001853128774", "dep": null}, {"v": "13697", "n": "Long term lease", "d": "When a school space is shared or dedicated in a contractual lease to provide exclusive access to an outside entity for a period of time of at least five years and if associated with joint development may be over 20 years.", "u": null, "notes": "concept: NI001853128775", "dep": null}, {"v": "13695", "n": "One-time event use", "d": "When a non-district entity utilizes a school space through a one time written use agreement.", "u": null, "notes": "concept: NI001853128776", "dep": null}, {"v": "13696", "n": "Short-term lease", "d": "When a non-district entity enters into a written agreement for the use of school space for a specified number of hours over a period of time of less than 5 years.", "u": null, "notes": "concept: NI001853128777", "dep": null}]$j$::jsonb);
