SELECT public.ceds_tmp_valueset('FacilitiesPlanType', 'The type of management and accountability plan.', NULL, 'scheme: C001883', NULL, $j$[{"v": "02828", "n": "Capital improvement plan", "d": "A 5- or 6-year plan, based on the master plan, that sets priorities and budgets for school-specific major capital projects, such as component replacement, system upgrades, whole or partial school modernization, new construction, and site acquisition.", "u": null, "notes": "concept: NI001883129004", "dep": null}, {"v": "02827", "n": "Educational facilities master plan", "d": "A long-term plan (often 10 years) that describes the scope, schedule, and cost estimates to bring all facilities up to desired standards from current conditions.", "u": null, "notes": "concept: NI001883129005", "dep": null}, {"v": "02825", "n": "Emergency response plan", "d": "A plan that addresses the immediate and short-term effects of an emergency or disaster. Response includes immediate actions to save lives, protect property, and meet basic human needs.", "u": null, "notes": "concept: NI001883129006", "dep": null}, {"v": "02829", "n": "Energy management plan", "d": "A plan that includes historical utility consumption and cost data and targets, with scope of work and schedule to meet cost and consumption targets.", "u": null, "notes": "concept: NI001883129007", "dep": null}, {"v": "02830", "n": "Hazardous materials management plan", "d": "A plan that identifies hazardous materials in the building and/or site and describes scope of work, schedule, cost, and appropriate entities to carry out the plan.", "u": null, "notes": "concept: NI001883129008", "dep": null}, {"v": "02826", "n": "Maintenance plan", "d": "A plan that includes the specific scope, schedule, responsible party, estimated cost, and source of funds for routine, preventive, and predictive maintenance of a district or school.", "u": null, "notes": "concept: NI001883129009", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified 