SELECT public.ceds_tmp_valueset('FacilityApplicableFederalMandateType', 'The particular federal law, regulation, or standard that pertains to a school facility.', NULL, 'scheme: C001796', NULL, $j$[{"v": "02584", "n": "Americans with Disabilities Act (ADA)", "d": "Public Law 101-336 which prohibits discrimination against individuals with disabilities as regards to employment, public accommodations and certain public services. Also known as Americans with Disabilities Act (ADA).", "u": null, "notes": "concept: NI001796129011", "dep": null}, {"v": "02588", "n": "Asbestos Hazardous Emergency Response Act (AHERA)", "d": "Asbestos Hazardous Emergency Response Act (AHERA) is specified as the particular federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001796129012", "dep": null}, {"v": "02585", "n": "Individuals with Disabilities Education Act (IDEA)", "d": "Public Law 105-17 is designed to insure that all children with disabilities have available to them a free appropriate public education. Public Law. (Formerly called Education of the Handicapped Act P.L. 91-230.) Also known as Individuals with Disabilities Education Act (IDEA).", "u": null, "notes": "concept: NI001796129013", "dep": null}, {"v": "02587", "n": "Lead Contamination Control Act", "d": "Lead Contamination Control Act is specified as the particular federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001796129014", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the particular federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001796129015", "dep": null}, {"v": "02586", "n": "Safe Drinking Water Act", "d": "Safe Drinking Water Act is specified as the particular federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001796129016", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityAuditType', 'The type of systematic review or audit of facility quality, management, decision making processes, controls, schedule and cost.', NULL, 'scheme: C001864', NULL, $j$[{"v": "02979", "n": "Building commissioning", "d": "A systematic review of the quality and operation of a new or substantially improved building to ensure that it functions according to its design and construction specifications.", "u": null, "notes": "concept: NI001864129017", "dep": null}, {"v": "02977", "n": "Financial audit", "d": "A systematic review of the approved budget and actual expenditures and encumbrances.", "u": null, "notes": "concept: NI001864129018", "dep": null}, {"v": "02980", "n": "Fiscal audit", "d": "A systematic review of the capacity of a school district or municipality to generate and sustain funds to support plans, projects, or other requirements.", "u": null, "notes": "concept: NI001864129019", "dep": null}, {"v": "02976", "n": "Management audit", "d": "A systematic review of the decision-making, staffing, contracts, and governing procedures.", "u": null, "notes": "concept: NI001864129020", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the type of systematic review or audit of facility quality, management, decision making processes, controls, schedule and cost.", "u": null, "notes": "concept: NI001864129021", "dep": null}, {"v": "02978", "n": "Performance audit", "d": "A systematic review of the quality of work performed and its relationship to outcomes.", "u": null, "notes": "concept: NI001864129022", "dep": null}, {"v": "13688", "n": "Post Occupancy Evaluation", "d": "The review of building program specifications, design and construction after the building alteration, addition or new construction has been in service for at least one year, to assess how well the facility supports the educational program and how well the design is meeting expectation for building performance.", "u": null, "notes": "concept: NI001864129023", "dep": null}, {"v": "02981", "n": "Process audit", "d": "A systematic review of procurement procedures and decision-making.", "u": null, "notes": "concept: NI001864129024", "dep": null}, {"v": "13687", "n": "Retro-commissioning", "d": "Retro-commissioning (RCx) is a one-time, systematic investigation of a building's operations and maintenance process for improving and optimizing a building's operation and maintenance done in buildings that have been in operation for at least 3 years, but usually many more years.", "u": null, "notes": "concept: NI001864129025", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityBuildingPermanency', 'An indication of whether the building is built for permanent use in the same location or is relocatable.', NULL, 'scheme: C001770', NULL, $j$[{"v": "02432", "n": "Nonpermanent building", "d": "A building or portion of a building made up of prefabricated units that may be disassembled and reassembled and transported to another location, or transported without reassembling.", "u": null, "notes": "concept: NI001770129026", "dep": null}, {"v": "02431", "n": "Permanent building", "d": "A structure built with a fixed foundation that has permanently attached walls, roof, and floor that cannot be transported either as a unit or in sections.", "u": null, "notes": "concept: NI001770129027", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityCapitalProgramManagementType', 'The type of management organization for planning, design, and construction of major capital projects.', NULL, 'scheme: C001872', NULL, $j$[{"v": "02913", "n": "District management", "d": "The school district procures and oversees the design and construction services for its capital projects.", "u": null, "notes": "concept: NI001872129028", "dep": null}, {"v": "02824", "n": "Nonschool public agency management", "d": "A nonschool governmental agency procures and oversees the design and construction of the school district's capital projects. May be a municipal clerk of the works, separate building authority, or even the Army Corps of Engineers.", "u": null, "notes": "concept: NI001872129029", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the type of management organization for planning, design, and construction of major capital projects.", "u": null, "notes": "concept: NI001872129030", "dep": null}, {"v": "02823", "n": "Private management", "d": "The school district contracts with private program managers who procure and oversee the design and construction of its capital projects.", "u": null, "notes": "concept: NI001872129031", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityComplianceAgencyType', 'The type of agency that has ultimate responsibility for the compliance determination.', NULL, 'scheme: C001867', NULL, $j$[{"v": "00865", "n": "Charter board", "d": "The charter agency or agencies with responsibility and authority for evaluating and enforcing compliance with requirements affecting school facilities.", "u": null, "notes": "concept: NI001867129032", "dep": null}, {"v": "13652", "n": "Federal Agency", "d": "The federal agency or agencies with responsibility and authority for evaluating and enforcing compliance with federal requirements affecting public school facilities.", "u": null, "notes": "concept: NI001867129033", "dep": null}, {"v": "00862", "n": "Local (e.g., school board, city council, municipal board)", "d": "The local public agency or agencies with responsibility and authority for evaluating and enforcing compliance with local municipal requirements affecting public school facilities.", "u": null, "notes": "concept: NI001867129034", "dep": null}, {"v": "00864", "n": "Private/Religious", "d": "The private/religious agency or agencies with responsibility and authority for evaluating and enforcing compliance with requirements affecting school facilities.", "u": null, "notes": "concept: NI001867129035", "dep": null}, {"v": "00214", "n": "Regional or intermediate educational agency", "d": "The regional or intermediate educational agency or agencies with responsibility and authority for evaluating and enforcing compliance with requirements affecting public school facilities.", "u": null, "notes": "concept: NI001867129036", "dep": null}, {"v": "00860", "n": "State agency", "d": "The state agency or agencies with responsibility and authority for evaluating and enforcing compliance with state requirements affecting public school facilities.", "u": null, "notes": "concept: NI001867129037", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityComplianceStatus', 'An indication of whether the school, building, site, system, component, equipment, vehicle, or fixture conforms to the requirements or standards specified in federal, state, or local standards or codes or other officially required guidelines or regulations.', NULL, 'scheme: C001792', NULL, $j$[{"v": "02570", "n": "In compliance", "d": "The building, site, system, component, equipment, vehicle, or fixture conforms to the requirements or standards specified in federal, state, or local standards or codes.", "u": null, "notes": "concept: NI001792129038", "dep": null}, {"v": "02571", "n": "Not in compliance", "d": "The building, site, system, component, equipment, vehicle, or fixture does not conform to the requirements or standards specified in federal, state, or local standards or codes.", "u": null, "notes": "concept: NI001792129039", "dep": null}, {"v": "02572", "n": "Planned compliance", "d": "Planned compliance activities have been set for the building, site, system, component, equipment, vehicle, or fixture to ensure that it conforms to the requirements or standards specified in federal, state, or local standards or codes.", "u": null, "notes": "concept: NI001792129040", "dep": null}, {"v": "02573", "n": "Waived compliance", "d": "The building, site, system, component, equipment, vehicle, or fixture's compliance to the requirements or standards specified in federal, state, or local standards or codes have been waived.", "u": null, "notes": "concept: NI001792129041", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityConstructionDateType', 'Designation of the nature of the construction completion date.', NULL, 'scheme: C001781', NULL, $j$[{"v": "02420", "n": "Actual", "d": "Construction was completed as judged by the owner putting the building or improvement into use.", "u": null, "notes": "concept: NI001781129042", "dep": null}, {"v": "02421", "n": "Estimated", "d": "The new building, addition, or improvement is expected to be completed so the owner is able to put the building or improvement into use.", "u": null, "notes": "concept: NI001781129043", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityConstructionMaterialType', 'The primary material used for the construction of a building.', NULL, 'scheme: C001782', NULL, $j$[{"v": "02430", "n": "Adobe", "d": "Adobe is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129044", "dep": null}, {"v": "02428", "n": "Aluminum", "d": "Aluminum is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129045", "dep": null}, {"v": "02424", "n": "Block", "d": "Block is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129046", "dep": null}, {"v": "02422", "n": "Brick", "d": "Brick is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129047", "dep": null}, {"v": "02423", "n": "Brick veneer", "d": "Brick veneer is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129048", "dep": null}, {"v": "02426", "n": "Concrete", "d": "Concrete is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129049", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129050", "dep": null}, {"v": "02427", "n": "Prefabricated", "d": "Prefabricated is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129051", "dep": null}, {"v": "02429", "n": "Steel", "d": "Steel is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129052", "dep": null}, {"v": "02425", "n": "Wood frame", "d": "Wood frame is specified as the primary material used for the construction of a building.", "u": null, "notes": "concept: NI001782129053", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityFederalMandateInterestType', 'The area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.', NULL, 'scheme: C001797', NULL, $j$[{"v": "02579", "n": "Asbestos contamination", "d": "Asbestos contamination is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129054", "dep": null}, {"v": "75026", "n": "Child nutrition", "d": "Child nutrition is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129055", "dep": null}, {"v": "02577", "n": "Drinking water safety", "d": "Drinking water safety is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129056", "dep": null}, {"v": "02574", "n": "Facility accessibility and usability for individuals with disabilities", "d": "Facility accessibility and usability for individuals with disabilities is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129057", "dep": null}, {"v": "02580", "n": "Hazardous materials", "d": "Hazardous materials is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129058", "dep": null}, {"v": "02575", "n": "Indoor air quality", "d": "Indoor air quality is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129059", "dep": null}, {"v": "02583", "n": "Integrated pest control", "d": "Integrated pest control is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129060", "dep": null}, {"v": "02578", "n": "Lead contamination", "d": "Lead contamination is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129061", "dep": null}, {"v": "02582", "n": "Material Safety Data Sheet (MSDS)", "d": "Material Safety Data Sheet (MSDS) is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129062", "dep": null}, {"v": "03264", "n": "National School Lunch Act", "d": "National School Lunch Act is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129063", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129064", "dep": null}, {"v": "02576", "n": "Radon contamination", "d": "Radon contamination is specified as the area of interest controlled by a federal law, regulation, or standard that pertains to a school facility.", "u": null, "notes": "concept: NI001797129065", "dep": null}, {"v": "02581", "n": "Underground storage tank", "d": "Underground storage tanks (USTs) store petroleum or hazardous substances. The greatest potential threat from a leaking UST is contamination of groundwater, the source of drinking water for most Americans.", "u": null, "notes": "concept: NI001797129066", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityFinancingFeeType', 'The type of fee that one must pay when getting a mortgage.', NULL, 'scheme: C001886', NULL, $j$[{"v": "13717", "n": "Application fee", "d": "Some lenders may require a small fee as part of the application process. It may be nonrefundable.", "u": null, "notes": "concept: NI001886129067", "dep": null}, {"v": "13718", "n": "Legal fee", "d": "A fee paid to a lender for legal fees.", "u": null, "notes": "concept: NI001886129068", "dep": null}, {"v": "13719", "n": "Origination fee", "d": "A fee paid to a lender for processing a loan application; it is often stated as a percentage of the mortgage amount, or basis points, and paid at closing.", "u": null, "notes": "concept: NI001886129069", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityFurnishingsType', 'Moveable assets that are provided so the building or interior assets can be utilized by occupants for their intended purposes.', NULL, 'scheme: C001820', NULL, $j$[{"v": "00103", "n": "Administrative office", "d": "A building or site used to house offices to support activities concerned with the overall business/management, planning, and evaluation of an education agency or school.", "u": null, "notes": "concept: NI001820129070", "dep": null}, {"v": "02792", "n": "Cafeteria", "d": "A space equipped primarily for the preparation, serving, consumption and clean-up of food.", "u": null, "notes": "concept: NI001820129071", "dep": null}, {"v": "03014", "n": "Classroom", "d": "A location on campus inside a classroom.", "u": null, "notes": "concept: NI001820129072", "dep": null}, {"v": "00309", "n": "Occupational therapy", "d": "Services that address the functional needs of an individual relating to adaptive development, adaptive behavior and play, and sensory, motor, and postural development. These services are designed to improve the individual's functional ability to perform tasks in the home, school, and community settings and include: 1) identification assessment and intervention; 2) adaptation of the environment, and selection, design and fabrication of assistive and orthodontic devices to facilitate the development and promote the acquisition of functional skills; and 3) prevention or minimization of the impact of initial or future impairment, delay in development, or loss of functional ability.", "u": null, "notes": "concept: NI001820129073", "dep": null}, {"v": "00559", "n": "Physical education", "d": "A space equipped primarily for physical education.", "u": null, "notes": "concept: NI001820129074", "dep": null}, {"v": "00313", "n": "Physical therapy", "d": "Services to prevent or alleviate movement dysfunction and related functional problems that include: 1) screening, evaluation, and assessment of children and youth with disabilities to identify movement dysfunction; 2) obtaining, interpreting, and integrating information appropriate to program planning to prevent or alleviate movement dysfunction and related functional problems; and 3) providing individual or group services or treatment to prevent, alleviate, or compensate for movement dysfunction and related functional problems.", "u": null, "notes": "concept: NI001820129075", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityHazardousMaterialsOrConditionType', 'The type of hazardous materials or conditions tested for at a site or building.', NULL, 'scheme: C001874', NULL, $j$[{"v": "13660", "n": "Drip Lines", "d": "Drip lines can carry pollutants from air deposition and roof runoff.", "u": null, "notes": "concept: NI001874129081", "dep": null}, {"v": "13661", "n": "Ground Level Ozone", "d": "Ozone (O3) is a gas composed of three oxygen atoms. It is not usually emitted directly into the air, but at ground-level is created by a chemical reaction between oxides of nitrogen (NOx) and volatile organic compounds (VOC) in the presence of sunlight.", "u": null, "notes": "concept: NI001874129082", "dep": null}, {"v": "13662", "n": "Hazardous Air Pollutants", "d": "Hazardous air pollutants, also known as toxic air pollutants or air toxics, are those pollutants that cause or may cause cancer or other serious health effects, such as reproductive effects or birth defects, or adverse environmental and ecological effects.", "u": null, "notes": "concept: NI001874129083", "dep": null}, {"v": "02898", "n": "Asbestos", "d": "Asbestos is a mineral fiber that has been used commonly in a variety of building construction materials (such as roofing shingles, ceiling and floor tiles, paper products, and asbestos cement products) for insulation and as a fire-retardant. When asbestos-containing materials are damaged or disturbed by repair, remodeling or demolition activities, microscopic fibers become airborne and can be inhaled into the lungs, where they can cause significant health problems such as asbestosis, lung cancer and mesothelioma.", "u": null, "notes": "concept: NI001874129076", "dep": null}, {"v": "13656", "n": "Carbon Monoxide", "d": "Carbon monoxide is an odorless, colorless and toxic gas. At lower levels of exposure, CO causes mild effects that are often mistaken for the flu. These symptoms include headaches, dizziness, disorientation, nausea and fatigue. At high levels, CO can cause death. The effects of CO exposure can vary greatly from person to person depending on age, overall health and the concentration and length of exposure.", "u": null, "notes": "concept: NI001874129077", "dep": null}, {"v": "13657", "n": "Chlorofluorocarbons", "d": "A chlorofluorocarbon (CFC) is an organic compound that contains carbon, chlorine, and fluorine, produced as a volatile derivative of methane and ethane. Many CFCs have been widely used as refrigerants, propellants (in aerosol applications), and solvents.", "u": null, "notes": "concept: NI001874129078", "dep": null}, {"v": "13658", "n": "Concentrated animal feeding operations (CAFOs)", "d": "CAFOs generate manure, litter, and process wastewater that can contain pollutants like nitrogen, phosphorus, metals, and bacteria. Potential concerns include spills, overflows, or runoff that can pollute surface waters and threaten the health of people and animals.", "u": null, "notes": "concept: NI001874129079", "dep": null}, {"v": "13659", "n": "Criteria Air Pollutants", "d": "Criteria air pollutants include the six most common air pollutants in the U.S.: carbon monoxide, lead, nitrogen dioxide, ozone, particulate matter, and sulfur dioxide. These pollutants endanger public health and the environment, are widespread throughout the U.S. and come from a variety of sources. Criteria air pollutants are responsible for many adverse effects on human health, causing thousands of cases of premature mortality and tens of thousands of emergency room visits annually. They also cause acid rain and can significantly harm ecosystems and the built environment.", "u": null, "notes": "concept: NI001874129080", "dep": null}, {"v": "13663", "n": "Hazardous, industrial, or municipal waste sites", "d": "Fuel or chemical contaminants can appear on land or in groundwater, which has the potential for vapor intrusion.", "u": null, "notes": "concept: NI001874129084", "dep": null}, {"v": "13664", "n": "Hydrochlorofluorocarbons", "d": "Compounds containing hydrogen, fluorine, chlorine, and carbon atoms. Although ozone depleting substances, they are less potent at destroying stratospheric ozone than chlorofluorocarbons (CFCs). They have been introduced as temporary replacements for CFCs and are also greenhouse gases.", "u": null, "notes": "concept: NI001874129085", "dep": null}, {"v": "02899", "n": "Lead", "d": "Lead is a toxic metal that was used for many years in various products. Lead can affect children's brains and developing nervous systems, causing reduced IQ, learning disabilities, and behavioral problems. Lead is also harmful to adults. Lead in dust is the most common way people are exposed to lead. People can also get lead in their bodies from lead in soil, paint chips and drinking water from lead-containing pipes or plumbing fixtures.", "u": null, "notes": "concept: NI001874129086", "dep": null}, {"v": "13665", "n": "Mercury", "d": "Mercury is a naturally occurring element that is found in air, water and soil. Mercury is found in many rocks including coal. When coal is burned, mercury is released into the environment. High levels can harm the brain, heart, kidneys, lungs, and immune system of people of all ages.", "u": null, "notes": "concept: NI001874129087", "dep": null}, {"v": "13666", "n": "Methane", "d": "A hydrocarbon that is a greenhouse gas with a global warming potential most recently estimated at 23 times that of carbon dioxide. Methane is produced through anaerobic (without oxygen) decomposition of waste in landfills, animal digestion, decomposition of animal wastes, production and distribution of natural gas and petroleum, coal production, and incomplete fossil fuel combustion.", "u": null, "notes": "concept: NI001874129088", "dep": null}, {"v": "02900", "n": "Mold", "d": "Molds are part of the natural environment. Outdoors, molds break down dead organic matter such as fallen leaves and dead trees, but indoors, mold growth should be avoided. Molds reproduce by means of tiny spores. Mold may begin growing indoors when mold spores land on surfaces that are wet. Molds have the potential to cause health problems. Molds produce allergens, irritants, and in some cases, potentially toxic substances (mycotoxins). Inhaling or touching mold or mold spores may cause allergic reactions in sensitive individuals.", "u": null, "notes": "concept: NI001874129089", "dep": null}, {"v": "13667", "n": "Nitrogen Oxides", "d": "Gases consisting of one molecule of nitrogen and varying numbers of oxygen molecules. Nitrogen oxides are produced in the emissions of vehicle exhausts and from power stations. In the atmosphere, nitrogen oxides can contribute to formation of photochemical ozone (smog), can impair visibility and have health consequences, they are thus considered plants.", "u": null, "notes": "concept: NI001874129090", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the type of hazardous materials or conditions tested for at a site or building.", "u": null, "notes": "concept: NI001874129091", "dep": null}, {"v": "13668", "n": "Particulate Matter", "d": "Very small pieces of solid or liquid matter such as particles of soot, dust, fumes, mists or aerosols. The physical characteristics of particles, and how they combine with other particles, are part of the feedback mechanisms of the atmosphere.", "u": null, "notes": "concept: NI001874129092", "dep": null}, {"v": "02903", "n": "Pesticides", "d": "A pesticide is any substance or mixture of substances intended for preventing, destroying, repelling, or mitigating any pest. The health effects of pesticides depend on the type of pesticide. Some, such as the organophosphates and carbamates, affect the nervous system. Others may irritate the skin or eyes. Some pesticides may be carcinogens. Others may affect the hormone or endocrine system in the body.", "u": null, "notes": "concept: NI001874129093", "dep": null}, {"v": "13669", "n": "Polychlorinated biphenyls (PCBs)", "d": "PCBs belong to a broad family of man-made organic chemicals known as chlorinated hydrocarbons. PCBs were domestically manufactured from 1929 until their manufacture was banned in 1979. They have a range of toxicity and vary in consistency from thin, light-colored liquids to yellow or black waxy solids. Due to their non-flammability, chemical stability, high boiling point, and electrical insulating properties, PCBs were used in hundreds of industrial and commercial applications including electrical, heat transfer, and hydraulic equipment. Caulk containing PCBs was used in some buildings, including schools, in the 1950s through the 1970s. Although no longer commercially produced in the United States, PCBs may be present in products and materials produced before the ban. PCBs have been demonstrated to cause cancer, as well as a variety of other adverse health effects on the immune system, reproductive system, nervous system, and endocrine system.", "u": null, "notes": "concept: NI001874129094", "dep": null}, {"v": "13670", "n": "Propellants", "d": "A propellant is a chemical used to create thrust. The material is usually expelled by gas pressure. The pressure may be from a compressed gas, or a gas produced by a chemical reaction. It may be a gas, liquid, plasma, or, before the chemical reaction, a solid.", "u": null, "notes": "concept: NI001874129095", "dep": null}, {"v": "02902", "n": "Radon", "d": "Radon comes from the natural, radioactive breakdown of uranium in soil, rock and water and gets into the air. Radon gas decays into radioactive particles that can get trapped in the lungs through breathing. As they break down further, these particles release small bursts of energy. This can damage lung tissue and lead to lung cancer. The most common method used to reduce radon is a vent pipe system and fan, which pulls radon from beneath the building and vents it to the outside.", "u": null, "notes": "concept: NI001874129096", "dep": null}, {"v": "13671", "n": "Refrigerants", "d": "A refrigerant is a compound used in a heat cycle that reversibly undergoes a phase change from a gas to a liquid. Traditionally, fluorocarbons, especially chlorofluorocarbons were used as refrigerants, but they are being phased out because of their ozone depletion effects. Other refrigerants are ammonia, sulfur dioxide, carbon dioxide, and non-halogenated hydrocarbons such as methane. It is illegal to release refrigerants into the atmosphere (intentional or accidental) because they can cause severe damage to the ozone layer. When CFCs are removed they should be recycled to clean out any contaminants and return it to a usable condition. Refrigerants should never be mixed together. Some CFCs must be managed as hazardous waste even if recycled, and special precautions are required for their transport, depending on the legislation of the country's government.", "u": null, "notes": "concept: NI001874129097", "dep": null}, {"v": "13672", "n": "Sediment, sludge, reuse material", "d": "Waste not regulated as \"hazardous\" may contain toxic metals such as mercury and lead, etc.", "u": null, "notes": "concept: NI001874129098", "dep": null}, {"v": "13673", "n": "Sulfur dioxide", "d": "Sulfur dioxide (SO2) is one of a group of highly reactive gasses known as \"oxides of sulfur.\" The largest sources of SO2 emissions are from fossil fuel combustion at power plants and other industrial facilities. Smaller sources of SO2 emissions include industrial processes such as extracting metal from ore, and the burning of high sulfur containing fuels by locomotives, large ships and non-road equipment. SO2 is linked with a number of adverse effects on the respiratory system.", "u": null, "notes": "concept: NI001874129099", "dep": null}, {"v": "02901", "n": "Underground storage tanks (USTs)", "d": "Underground storage tanks (USTs) is specified as the type of hazardous materials or conditions tested for at a site or building.", "u": null, "notes": "concept: NI001874129100", "dep": null}, {"v": "13674", "n": "Vapor intrusion", "d": "Vapor intrusion is defined as vapor phase migration of volatile organic and/or inorganic compounds into occupied buildings from underlying contaminated ground water and/or soil.", "u": null, "notes": "concept: NI001874129101", "dep": null}, {"v": "13675", "n": "Volatile organic compounds", "d": "Volatile organic compounds (VOCs) are emitted as gases from certain solids or liquids. VOCs include a variety of chemicals, some of which may have short- and long-term adverse health effects. Concentrations of many VOCs are consistently higher indoors (up to ten times higher) than outdoors. VOCs are emitted by a wide array of products numbering in the thousands. Examples include: paints and lacquers, paint strippers, cleaning supplies, pesticides, building materials and furnishings, office equipment such as copiers and printers, correction fluids and carbonless copy paper, graphics and craft materials including glues and adhesives, permanent markers and photographic solutions VOCs can cause eye, nose and throat irritation, headaches, loss of coordination, nausea, damage to liver, kidney and central nervous system.", "u": null, "notes": "concept: NI001874129102", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityJointDevelopmentType', 'The type of development where two or more entities partner to plan, site, design, and/or build a new school or renovate an existing school to better support the joint use of the building and/or land.', NULL, 'scheme: C001875', NULL, $j$[{"v": "13690", "n": "Dedicated", "d": "When a school space is exclusively available to the outside entity during the school day and after school. For example, an after-school office or storage area.", "u": null, "notes": "concept: NI001875129103", "dep": null}, {"v": "13689", "n": "Shared", "d": "When the space is used by the school during school hours and by a non-school user after school hours. For example, a classroom for instruction during the school day and for after school program activities after school.", "u": null, "notes": "concept: NI001875129104", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityLeaseAmountCategory', 'The category of payment that a school must pay to rent the facility that it is in.', NULL, 'scheme: C001888', NULL, $j$[{"v": "13720", "n": "Base rent", "d": "Base rent is specified as the category of payment that a school must pay to rent the facility that it is in.", "u": null, "notes": "concept: NI001888129105", "dep": null}, {"v": "13721", "n": "Credit", "d": "Credit is specified as the category of payment that a school must pay to rent the facility that it is in.", "u": null, "notes": "concept: NI001888129106", "dep": null}, {"v": "13722", "n": "Escalator", "d": "Escalator is specified as the category of payment that a school must pay to rent the facility that it is in.", "u": null, "notes": "concept: NI001888129107", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityLeaseType', 'The type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.', NULL, 'scheme: C001889', NULL, $j$[{"v": "13723", "n": "Building lease", "d": "Building lease is specified as the type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.", "u": null, "notes": "concept: NI001889129108", "dep": null}, {"v": "13724", "n": "Ground lease", "d": "Ground lease is specified as the type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.", "u": null, "notes": "concept: NI001889129109", "dep": null}, {"v": "13725", "n": "Lease build to suit", "d": "Lease build to suit is specified as the type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.", "u": null, "notes": "concept: NI001889129110", "dep": null}, {"v": "13726", "n": "Lease shell with significant leasehold improvements", "d": "Lease shell with significant leasehold improvements is specified as the type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.", "u": null, "notes": "concept: NI001889129111", "dep": null}, {"v": "13727", "n": "Triple-net lease", "d": "Triple-net lease is specified as the type of agreement that allows the use and possession of a school, building, or other facility from a third party in return for a regularly scheduled installment payment over an agreed-upon period.", "u": null, "notes": "concept: NI001889129112", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityMaintenanceStandardType', 'The standard for maintenance of a component, system, or building.', NULL, 'scheme: C001876', NULL, $j$[{"v": "02989", "n": "Emergency maintenance repair", "d": "A plan that addresses the maintenance in which a critical system, component, equipment, or furnishing breaks down and must be repaired to secure the safety of students, staff, or visitors and/or for operation of the program or service to continue. Unexpected events beyond normal wear and tear may mandate overtime, as situations may have to be dealt with immediately.", "u": null, "notes": "concept: NI001876129113", "dep": null}, {"v": "02839", "n": "Predictive", "d": "The process of monitoring selected performance data for a system, component, or equipment against a baseline reference to identify and predict impending failures for just-in-time maintenance attention. A system of maintenance in which computers and software are used to forecast the failure of a piece of equipment based on its age, user demand, and various performance measures.", "u": null, "notes": "concept: NI001876129114", "dep": null}, {"v": "02838", "n": "Preventive", "d": "The process of performing scheduled equipment inspection, testing, and repair services. Activities are performed on a scheduled basis annually, or more frequently, to identify additional maintenance or required systems testing.", "u": null, "notes": "concept: NI001876129115", "dep": null}, {"v": "02837", "n": "Routine", "d": "A work-order based approach to maintenance that addresses lists of broken items, deteriorated finishes or equipment/parts nearing the end of their life cycle, maintenance required as a result of normal wear and tear, equipment/parts that should be fixed or replaced during a regular work day eliminating the need for overtime pay.", "u": null, "notes": "concept: NI001876129116", "dep": null}, {"v": "02836", "n": "Run to fail", "d": "An approach to maintenance in which management allows equipment and parts to run until they break down or wear out beyond repair.", "u": null, "notes": "concept: NI001876129117", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityMortgageInterestType', 'The type of interest paid on a mortgage to the lender to compensate the lender for the use of money to purchase a building or facility.', NULL, 'scheme: C001891', NULL, $j$[{"v": "13730", "n": "Add-on interest", "d": "Interest added to the amount of the loan on the front end, or beginning of the loan repayment period. The balance (of principal and interest) is then paid by installments. This form of interest is much more expensive than simple interest paid on the entire amount for the entire term of the loan.", "u": null, "notes": "concept: NI001891129118", "dep": null}, {"v": "13731", "n": "Adjustable-Rate Mortgage (ARM)", "d": "A mortgage in which interest and payment rates vary periodically, based on a specific index, such as 30-year Treasury bills or the Cost-of-Funds index.", "u": null, "notes": "concept: NI001891129119", "dep": null}, {"v": "13732", "n": "Balloon Mortgage", "d": "A short-term mortgage, generally at a fixed rate of interest, to be paid back in pre-determined, equal monthly payments, with a large, final payment for the balance of the loan paid at the end of the term.", "u": null, "notes": "concept: NI001891129120", "dep": null}, {"v": "13733", "n": "Deferred Interest", "d": "Interest due but unpaid. Mortgages that permit negative amortization (such as a graduated-payment mortgage or a floating rate loan without a rate cap) will allow deferred interest.", "u": null, "notes": "concept: NI001891129121", "dep": null}, {"v": "13734", "n": "Fixed Payment Mortgage", "d": "Periodic payments of principal and interest on a mortgage which remain constant over the loan term.", "u": null, "notes": "concept: NI001891129122", "dep": null}, {"v": "13735", "n": "Fixed-rate Mortgage", "d": "A mortgage in which the interest rate does not change during the entire term of the loan.", "u": null, "notes": "concept: NI001891129123", "dep": null}, {"v": "13736", "n": "Floating Rate", "d": "An interest rate on a loan which changes during the life of the loan, often monthly, but can change quarterly or annually. These variable rates are based on an index rate and can be used for mortgages and other loans such as lines of credit.", "u": null, "notes": "concept: NI001891129124", "dep": null}, {"v": "13737", "n": "Fully Amortizing Mortgage", "d": "A method of loan amortization in which equal periodic payments completely repay the loan during the loan term.", "u": null, "notes": "concept: NI001891129125", "dep": null}, {"v": "13738", "n": "Graduated-payment Mortgage (GPM)", "d": "A type of stepped-payment loan in which the borrower's payments are initially lower than those on a comparable level-rate mortgage. The payments gradually increase over a predetermined period, and then cap at a final level for the duration of the mortgage.", "u": null, "notes": "concept: NI001891129126", "dep": null}, {"v": "13739", "n": "Interest-only loan", "d": "A method of loan amortization in which interest is paid periodically over the term of the loan and the entire loan amount (principal) is paid at maturity.", "u": null, "notes": "concept: NI001891129127", "dep": null}, {"v": "13740", "n": "Open-end Mortgage", "d": "A mortgage agreement that allows the mortgagor to borrow additional funds from the mortgage lender in the future, normally with a borrowing limit. This limit may be based on loan-to-value or may simply be the original loan amount.", "u": null, "notes": "concept: NI001891129128", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityMortgageType', 'The status of a mortgage as it relates to priority of payment.', NULL, 'scheme: C001892', NULL, $j$[{"v": "13741", "n": "Junior Mortgage", "d": "Any mortgage on a property that is subordinate to a senior mortgage in priority. Also called subordinated mortgage.", "u": null, "notes": "concept: NI001892129129", "dep": null}, {"v": "13742", "n": "Multiple", "d": "A property may have multiple mortgages on it. Second mortgages are subordinate, meaning that in the event of default, the primary, or first mortgage would get paid off first, and then any funds remaining would be used to pay off any second mortgages.", "u": null, "notes": "concept: NI001892129130", "dep": null}, {"v": "13743", "n": "Senior or first mortgage", "d": "The mortgage that has first claim in the event of a default. The first or senior mortgage typically has to be satisfied before the second or junior mortgage can enforce any claims against the property.", "u": null, "notes": "concept: NI001892129131", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityNaturallyOccurringHazardType', 'Type of natural hazard that can affect the health, safety and operation of school facilities and their occupants.', NULL, 'scheme: C001877', NULL, $j$[{"v": "13678", "n": "Arsenic", "d": "Arsenic is a semi-metal element in the periodic table. It is odorless and tasteless. It enters drinking water supplies from natural deposits in the earth or from agricultural and industrial practices. Non-cancer effects can include thickening and discoloration of the skin, stomach pain, nausea, vomiting; diarrhea; numbness in hands and feet; partial paralysis; and blindness. Arsenic has been linked to cancer of the bladder, lungs, skin, kidney, nasal passages, liver, and prostate.", "u": null, "notes": "concept: NI001877129132", "dep": null}, {"v": "13679", "n": "Earthquake prone area", "d": "Building in an earthquake prone area is a structural hazard.", "u": null, "notes": "concept: NI001877129133", "dep": null}, {"v": "13680", "n": "Floodplain", "d": "Building in a floodplain is a structural hazard.", "u": null, "notes": "concept: NI001877129134", "dep": null}, {"v": "13681", "n": "Liquefaction, landslide areas", "d": "Building in a landslide area is a structural hazard.", "u": null, "notes": "concept: NI001877129135", "dep": null}, {"v": "13682", "n": "Naturally Occurring Asbestos (NOA)", "d": "Naturally occurring asbestos (NOA) includes fibrous minerals found in certain types of rock formations. NOA can take the form of long, thin, separable fibers. Natural weathering or human disturbance can break NOA down to microscopic fibers, easily suspended in air. There is no health threat if NOA remains undisturbed and does not become airborne.", "u": null, "notes": "concept: NI001877129136", "dep": null}, {"v": "13683", "n": "Sinkholes, Karst terrain", "d": "Building in a sinkhole is a structural hazard.", "u": null, "notes": "concept: NI001877129137", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('FacilityOperationsManagementType', 'The type of management arrangements whereby a district oversees and manages its facilities operations.', NULL, 'scheme: C001873', NULL, $j$[{"v": "02821", "n": "District and private sector management", "d": "The school district supervises and employs district staff for cleaning, maintenance, and repair, but also contracts with a private sector company for support in the cleaning, maintenance, and repair of its schools and other facilities.", "u": null, "notes": "concept: NI001873129138", "dep": null}, {"v": "02822", "n": "Nonschool public sector management", "d": "School district building cleaning, maintenance, and repair are the responsibility of a nonschool governmental agency or public authority.", "u": null, "notes": "concept: NI001873129139", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as the type of management arrangements whereby a district oversees and manages its facilities operations.", "u": null, "notes": "concept: NI001873129140", "dep": null}, {"v": "02820", "n": "Private sector management", "d": "The school district contracts with a private sector company for the supervision and staffing for school-based cleaning, maintenance, and repair.", "u": null, "notes": "concept: NI001873129141", "dep": null}, {"v": "02819", "n": "School district management", "d": "The school district supervises and employs district staff in the schools and the central office for cleaning, maintenance, and repair.", "u": null, "notes": "concept: NI001873129142", "dep": null}]$j$::jsonb);
