SELECT public.ceds_tmp_valueset('FacilityStandardType', 'An indication of the district or state requirements or guidelines for the design and construction of school facilities.', NULL, 'scheme: C001884', NULL, $j$[{"v": "02622", "n": "Design guidelines", "d": "The guidelines that establish site, building and room sizes, quality and type of finishes, systems, components, furnishings and fixtures of a facility.", "u": null, "notes": "concept: NI001884129175", "dep": null}, {"v": "02626", "n": "Energy performance standards", "d": "The metrics for the levels of water, electricity, gas, oil, or coal consumption that a district seeks to meet on a district wide or facility specific basis.", "u": null, "notes": "concept: NI001884129176", "dep": null}, {"v": "13628", "n": "Environmental Standards", "d": "A policy guideline that regulates the effect of human activity upon the environment. Standards may specify a desired state (e.g. daylighting should provide 75% of lighting needed for classrooms)or limit alterations (e.g. new school sites should be no more than 4 acres for an elementary school).", "u": null, "notes": "concept: NI001884129177", "dep": null}, {"v": "02625", "n": "Health and safety standards", "d": "A set of rules which require conditions, or the adoption or use of one or more practices, means, methods, operations, or processes, reasonably necessary or appropriate to provide for a safe and healthy school environment.", "u": null, "notes": "concept: NI001884129178", "dep": null}, {"v": "02624", "n": "Master construction specifications", "d": "A written or printed description of work to be done, forming part of the contract and describing qualities of material and mode of construction, and also giving dimensions and other information not shown in the drawings.", "u": null, "notes": "concept: NI001884129179", "dep": null}, {"v": "09999", "n": "Other", "d": "Other is specified as an indication of the district or state requirements or guidelines for the design and construction of school facilities.", "u": null, "notes": "concept: NI001884129180", "dep": null}, {"v": "02627", "n": "Site selection guidelines", "d": "Guidelines to assist the school district identify school building sites that are environmentally, educationally, and community appropriate.", "u": null, "notes": "concept: NI001884129181", "dep": null}, {"v": "02623", "n": "Space standards", "d": "A set of rules that specify the minimum acceptable amount of space required per student in a school building.", "u": null, "notes": "concept: NI001884129182", "dep": null}]$j$::jsonb);
