SELECT public.ceds_tmp_valueset('CredentialDefinitionAgentRoleType', 'The role that an organization or person has in relation to this Credential Definition based on terms defined by Credential Engine.', NULL, 'scheme: C001914', NULL, $j$[{"v": "accreditedBy", "n": "Accredited By", "d": "Quality assurance organization that provides official authorization to, or approval of, a credential, organization, assessment, or learning opportunity.", "u": null, "notes": "concept: NI001914129428", "dep": null}, {"v": "approvedBy", "n": "Approved By", "d": "Organization that pronounces favorable judgment for this credential, assessment, learning opportunity, or organization.", "u": null, "notes": "concept: NI001914129429", "dep": null}, {"v": "offeredBy", "n": "Offered By", "d": "Agent that offers the resource.", "u": null, "notes": "concept: NI001914129430", "dep": null}, {"v": "ownedBy", "n": "Owned By", "d": "Organization or person with an enforceable claim or legal title to the Credential Definition resource.", "u": null, "notes": "concept: NI001914129431", "dep": null}, {"v": "recognizedBy", "n": "Recognized By", "d": "Agent that acknowledges the validity of the credential, learning opportunity, or assessment.", "u": null, "notes": "concept: NI001914129432", "dep": null}, {"v": "regulatedBy", "n": "Regulated By", "d": "Quality assurance organization that enforces the legal requirements of the credential, learning resource, or assessment.", "u": null, "notes": "concept: NI001914129433", "dep": null}, {"v": "renewedBy", "n": "Renewed By", "d": "Organization or person that handles the renewal of the credential.", "u": null, "notes": "concept: NI001914129434", "dep": null}, {"v": "revokedBy", "n": "Revoked By", "d": "Organization or person that handles revocation of an awarded credential due to violations or failure to renew.", "u": null, "notes": "concept: NI001914129435", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CTDLAudienceLevelType', 'Type of level indicating a point in a progression through an educational or training context, for which the credential is intended; select from an existing enumeration of such types.', NULL, 'scheme: C001913', NULL, $j$[{"v": "ApprenticeshipCertificate", "n": "Apprenticeship Certificate", "d": "Credential earned through work-based learning and earn-and-learn models that meet standards and are applicable to industry trades and professions.", "u": null, "notes": "concept: NI001913129436", "dep": null}, {"v": "AssociateDegree", "n": "Associate Degree", "d": "College/university award for students typically completing the first one to two years of post secondary school education.", "u": null, "notes": "concept: NI001913129437", "dep": null}, {"v": "BachelorDegree", "n": "Bachelor Degree", "d": "College/university award for students typically completing three to five years of education where course work and activities advance skills beyond those of the first one to two years of college/university study.", "u": null, "notes": "concept: NI001913129438", "dep": null}, {"v": "Badge", "n": "Badge", "d": "Recognition designed to be displayed as a marker of accomplishment, activity, achievement, skill, interest, association, or identity.", "u": null, "notes": "concept: NI001913129439", "dep": null}, {"v": "Certificate", "n": "Certificate", "d": "Credential that designates requisite knowledge and skills of an occupation, profession, or academic program.", "u": null, "notes": "concept: NI001913129440", "dep": null}, {"v": "Certification", "n": "Certification", "d": "Time-limited, revocable, renewable credential awarded by an authoritative body for demonstrating the knowledge, skills, and abilities to perform specific tasks or an occupation.", "u": null, "notes": "concept: NI001913129441", "dep": null}, {"v": "ConditionProfile", "n": "Condition Profile", "d": "Entity describing a constraint, prerequisite, entry condition, or requirement.", "u": null, "notes": "concept: NI001913129442", "dep": null}, {"v": "Credential", "n": "Credential", "d": "Qualification, achievement, personal or organizational quality, or aspect of an identity typically used to indicate suitability. The ceterms:Credential class is broadly defined to encompass credentials used across domains and communities of practice. The class should be used only when speaking of credentials in general. Subclasses of ceterms:Credential as defined by Credential Engine (or other communities) should be used when referencing specific types of credentials.", "u": null, "notes": "concept: NI001913129443", "dep": null}, {"v": "Degree", "n": "Degree", "d": "Academic credential conferred upon completion of a program or course of study, typically over multiple years at a college or university.", "u": null, "notes": "concept: NI001913129444", "dep": null}, {"v": "DigitalBadge", "n": "Digital Badge", "d": "Badge offered in digital form.", "u": null, "notes": "concept: NI001913129445", "dep": null}, {"v": "Diploma", "n": "Diploma", "d": "Credential awarded by educational institutions for successful completion of a course of study or its equivalent.", "u": null, "notes": "concept: NI001913129446", "dep": null}, {"v": "DoctoralDegree", "n": "Doctoral Degree", "d": "Highest credential award for students who have completed both a bachelor's degree and a master's degree or their equivalent as well as independent research and/or a significant project or paper.", "u": null, "notes": "concept: NI001913129447", "dep": null}, {"v": "GeneralEducationDevelopment", "n": "General Education Development", "d": "Credential awarded by examination that demonstrates that an individual has acquired secondary school-level academic skills.", "u": null, "notes": "concept: NI001913129448", "dep": null}, {"v": "JourneymanCertificate", "n": "Journeyman Certificate", "d": "Credential awarded to skilled workers on successful completion of an apprenticeship in industry trades and professions.", "u": null, "notes": "concept: NI001913129449", "dep": null}, {"v": "License", "n": "License", "d": "Credential awarded by a government agency that constitutes legal authority to do a specific job and/or utilize a specific item, system or infrastructure and are typically earned through some combination of degree or certificate attainment, certifications, assessments, work experience, and/or fees, and are time-limited and must be renewed periodically.", "u": null, "notes": "concept: NI001913129450", "dep": null}, {"v": "MasterCertificate", "n": "Master Certificate", "d": "Credential awarded upon demonstration through apprenticeship of the highest level of skills and performance in industry trades and professions.", "u": null, "notes": "concept: NI001913129451", "dep": null}, {"v": "MasterDegree", "n": "Master Degree", "d": "Credential awarded for a graduate level course of study where course work and activities advance skills beyond those of the bachelor's degree or its equivalent.", "u": null, "notes": "concept: NI001913129452", "dep": null}, {"v": "MicroCredential", "n": "Micro Credential", "d": "Credential that addresses a subset of field-specific knowledge, skills, or competencies; often developmental with relationships to other micro-credentials and field credentials.", "u": null, "notes": "concept: NI001913129453", "dep": null}, {"v": "OpenBadge", "n": "Open Badge", "d": "Visual symbol containing verifiable claims in accordance with the Open Badges specification and delivered digitally.", "u": null, "notes": "concept: NI001913129454", "dep": null}, {"v": "ProfessionalDoctorate", "n": "Professional Doctorate", "d": "Doctoral degree conferred upon completion of a program providing the knowledge and skills for the recognition, credential, or license required for professional practice.", "u": null, "notes": "concept: NI001913129455", "dep": null}, {"v": "QualityAssuranceCredential", "n": "Quality Assurance Credential", "d": "Credential assuring that an organization, program, or awarded credential meets prescribed requirements and may include development and administration of qualifying examinations.", "u": null, "notes": "concept: NI001913129456", "dep": null}, {"v": "ResearchDoctorate", "n": "Research Doctorate", "d": "Doctoral degree conferred for advanced work beyond the master level, including the preparation and defense of a thesis or dissertation based on original research, or the planning and execution of an original project demonstrating substantial artistic or scholarly achievement.", "u": null, "notes": "concept: NI001913129457", "dep": null}, {"v": "SecondarySchoolDiploma", "n": "Secondary School Diploma", "d": "Diploma awarded by secondary education institutions for successful completion of a secondary school program of study.", "u": null, "notes": "concept: NI001913129458", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('ProgressAchievingEnglishLanguageProficiencyIndicatorType', 'The category used to report the school''s performance on the progress of achieving the English language proficiency indicator.', NULL, 'scheme: C001915', NULL, $j$[{"v": "NOSTUDENTS", "n": "No students in the subgroup", "d": "There are no students in a student subgroup.", "u": null, "notes": "concept: NI001915129459", "dep": null}, {"v": "STTDEF", "n": "State defined status", "d": "A status defined by the state.", "u": null, "notes": "concept: NI001915129460", "dep": null}, {"v": "TOOFEW", "n": "Too few students", "d": "The number of students in the school or for a student group was less than the minimum group size necessary or required to reliably calculate the indicator.", "u": null, "notes": "concept: NI001915129461", "dep": null}]$j$::jsonb);
