SELECT public.ceds_tmp_valueset('OutOfWorkforceIndicator', 'An individual: (A) who is a displaced homemaker, as defined in section 3 of the Workforce Innovation and Opportunity Act (29 U.S.C. 3102); or (B) who (i)(I) has worked primarily without remuneration to care for a home and family, and for that reason has diminished marketable skills; or (II) is a parent whose youngest dependent child will become ineligible to receive assistance under part A of title IV of the Social Security Act (42 U.S.C. 601 et seq.) not later than 2 years after the date on which the parent applies for assistance under such title; and (ii) is unemployed or underemployed and is experiencing difficulty in obtaining or upgrading employment.', NULL, 'scheme: C001930', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI001930100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI001930100002", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": null, "u": null, "notes": "concept: NI001930100003", "dep": null}]$j$::jsonb);
