SELECT public.ceds_tmp_valueset('AdultEducationProgramExitReason', 'The documented or assumed reason the person is no longer being served by the adult education program.', NULL, 'scheme: C001939', NULL, $j$[{"v": "1003", "n": "Deceased", "d": "The participant is deceased.", "u": null, "notes": "concept: NI001939162252", "dep": null}, {"v": "1000", "n": "Incarceration in a correctional institution or resident of 24-hour support facility", "d": "The participant exits the program because he or she has become incarcerated in a correctional institution or has become a resident of an institution or facility providing 24-hour support such as a hospital or treatment center during the course of receiving services as a participant.", "u": null, "notes": "concept: NI001939162253", "dep": null}, {"v": "1001", "n": "Medical treatment", "d": "The participant exits the program because of medical treatment and that treatment is expected to last longer than 90 days and precludes entry into unsubsidized employment or continued participation in the program.", "u": null, "notes": "concept: NI001939162254", "dep": null}, {"v": "1006", "n": "Moved out of state", "d": "The participant moved out of state.", "u": null, "notes": "concept: NI001939162255", "dep": null}, {"v": "1002", "n": "National guard or other reserve active duty", "d": "The participant exits the program because the participant is a member of the National Guard or other reserve military unit of the armed forces and is called to active duty for at least 90 days.", "u": null, "notes": "concept: NI001939162256", "dep": null}, {"v": "1999", "n": "Other", "d": "The reason why the person is no longer being served in the adult education program is not yet defined in CEDS.", "u": null, "notes": "concept: NI001939162257", "dep": null}, {"v": "1004", "n": "Permanently incapacitated", "d": "The participant is permanently incapacitated.", "u": null, "notes": "concept: NI001939162258", "dep": null}, {"v": "1010", "n": "Program completion with credential or certification", "d": "The participant completed the program with one or more credentials or certifications.", "u": null, "notes": "concept: NI001939162259", "dep": null}, {"v": "1007", "n": "Program completion without credential or certification", "d": "The participant completed the program without credentials or certifications.", "u": null, "notes": "concept: NI001939162260", "dep": null}, {"v": "1008", "n": "Program discontinued", "d": "The participant exited the program because the program was discontinued.", "u": null, "notes": "concept: NI001939162261", "dep": null}, {"v": "1009", "n": "Unknown", "d": "It is unknown why the participant exited the program.", "u": null, "notes": "concept: NI001939162262", "dep": null}, {"v": "1005", "n": "Voluntary exit", "d": "The participant voluntarily exited the program without completing.", "u": null, "notes": "concept: NI001939162263", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('WIOABarrierstoEmployment', 'A self-identified barrier as defined by the Workforce Innovation and Opportunity Act (WIOA) that is presumed to affect placement of a participant in unsubsidized employment.', NULL, 'scheme: C001940', NULL, $j$[{"v": "805", "n": "Cultural barriers", "d": "The participant has a perception of him-or herself as possessing attitudes, beliefs, customs, or practices that influence a way of thinking, acting, or working that may serve as a hindrance to employment.", "u": null, "notes": "concept: NI001940181067", "dep": null}, {"v": "807", "n": "Displaced Caregiver", "d": "The participant has been providing unpaid services to family members in the home and (a) has been dependent on the income of another family member but is no longer supported by that income; (b) is the dependent spouse of a member of the armed forces on active duty whose family income is significantly reduced because of (i) a deployment or a call or order to active duty pursuant to a provision of law, (ii) a permanent change of station, or (iii) the service-connected death or disability of the member; and (c) is unemployed or underemployed and is experiencing difficulty in obtaining or upgrading employment.", "u": null, "notes": "concept: NI001940181068", "dep": null}, {"v": "806", "n": "Single parent", "d": "The participant is a single, separated, divorced, or widowed individual who has primary responsibility for one or more dependent children under age 18 (including single pregnant women).", "u": null, "notes": "concept: NI001940181070", "dep": null}, {"v": "808", "n": "Migrant and seasonal farmworker", "d": "The participant is a low-income individual who for 12 consecutive months out of the 24 months prior to application for the program involved has been primarily employed in agriculture or fish farming labor that is characterized by chronic unemployment or underemployment, and faces multiple barriers to economic self-sufficiency.", "u": null, "notes": "concept: NI001940181071", "dep": null}, {"v": "802", "n": "Low-income", "d": "The participant (a) receives, or in the 6 months prior to application to the program has received, or is a member of a family that is receiving in the past 6 months assistance through the Supplemental Nutrition Assistance Program (SNAP), the TANF program, the Supplemental Security Income (SSI) program, or State or local income-based public assistance; (b) is in a family with total family income that does not exceed the higher of the poverty line or 70% of the lower living standard income level; (c) is a youth who receives, or is eligible to receive, a free or reduced-price lunch; (d) is a foster child on behalf of whom State or local government payments are made; (e) is a participant with a disability whose own income is the poverty line but who is a member of a family whose income does not meet this requirement; (f) is a homeless participant or homeless child or youth or runaway youth; or (g) is a youth living in a high-poverty area.", "u": null, "notes": "concept: NI001940181072", "dep": null}, {"v": "804", "n": "Low literacy level", "d": "The participant has an inability to compute and solve problems or read, write, or speak English at a level necessary to function on the job, in the participant's family, or in society, which may serve as a hindrance to employment.", "u": null, "notes": "concept: NI001940181073", "dep": null}, {"v": "402", "n": "Long-term unemployed", "d": "The participant has been unemployed for 27 or more consecutive weeks.", "u": null, "notes": "concept: NI001940181074", "dep": null}, {"v": "202", "n": "Individual with disabilities", "d": "The participant indicates that he or she has a disability, defined as a physical or mental impairment, that substantially limits one or more of the person's major life activities, as defined under the Americans with Disabilities Act of 1990.", "u": null, "notes": "concept: NI001940181075", "dep": null}, {"v": "800", "n": "Homeless or runaway youth", "d": "The participant lacks a fixed, regular, and adequate nighttime residence; has a primary nighttime residence that is a public or private place not designed for or ordinarily used as a regular sleeping accommodation for human beings; is a migratory child who in the preceding 36 months was required to move from one school district to another due to changes in the parent's or parent's spouse's seasonal employment in agriculture, dairy, or fishing work; or is under 18 years of age and absents himself or herself from home or place of legal residence without the permission of his or her family (i.e., runaway youth). However, a participant who may be sleeping in a temporary accommodation while away from home should not, as a result of that fact alone, be recorded as homeless.", "u": null, "notes": "concept: NI001940181076", "dep": null}, {"v": "801", "n": "Ex-offender", "d": "The participant is a person who either (a) has been subject to any stage of the criminal justice process for committing a status offense or delinquent act, or (b) requires assistance in overcoming barriers to employment resulting from a record of arrest or conviction.", "u": null, "notes": "concept: NI001940181077", "dep": null}, {"v": "601", "n": "Exhausting Temporary Assistance for Needy Families (TANF) within 2 years", "d": "The participant is within 2 years of exhausting lifetime eligibility under Part A of Title IV of the Social Security Act (42 U.S.C. 601 et seq.), regardless of whether he or she is receiving these benefits at program entry.", "u": null, "notes": "concept: NI001940181078", "dep": null}, {"v": "803", "n": "English language learner", "d": "The participant has limited ability in speaking, reading, writing, or understanding the English language that may serve as a hindrance to employment.", "u": null, "notes": "concept: NI001940181079", "dep": null}, {"v": "798", "n": "Current Foster Care Youth", "d": "The participant is a person who is currently in foster care.", "u": null, "notes": "concept: NI001940181080", "dep": null}, {"v": "799", "n": "Former Foster Care Youth", "d": "The participant is a person who has aged out of the foster care system or who has attained 16 years of age and left foster care for kinship, guardianship or adoption, or an individual who were formerly in foster care, but returned to their families before turning 18.", "u": null, "notes": "concept: NI001940181081", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('WIOACareerServices', 'An indication of whether or not the individual has received services as identified in sec. 134(c)(2) of the Workforce Innovation and Opportunity Act (WIOA) consisting of (a) basic career services, (b) individualized career services, or (c) follow-up services.', NULL, 'scheme: C001941', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI001941100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI001941100002", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": null, "u": null, "notes": "concept: NI001941100003", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('WIOATrainingServices', 'An indication of whether or not the individual has received services as defined by the Workforce Innovation and Opportunity Act (WIOA), one or more courses or classes, or a structured regimen that provides the services in 20 CFR part 680.200 and leads to: (a) An industry-recognized certificate or certification, a certificate of completion of a registered apprenticeship, a license recognized by the State involved or the Federal Government, an associate or baccalaureate degree, or community college certificate of completion; (b) Consistent with � 680.350, a secondary school diploma or its equivalent; (c) Employment; or (d) Measurable skill gains toward a credential described in paragraph (a) or (b) of this section or employment.', NULL, 'scheme: C001942', NULL, $j$[{"v": "Yes", "n": "Yes", "d": null, "u": null, "notes": "concept: NI001942100001", "dep": null}, {"v": "No", "n": "No", "d": null, "u": null, "notes": "concept: NI001942100002", "dep": null}, {"v": "Unknown", "n": "Unknown", "d": null, "u": null, "notes": "concept: NI001942100003", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('RaceAndEthnicity', 'The origins of a person.', NULL, 'scheme: C001943', NULL, $j$[{"v": "AmericanIndianOrAlaskaNative", "n": "American Indian or Alaska Native", "d": "Individuals with origins in any of the original peoples of North, Central, and South America, including, for example, Navajo Nation, Blackfeet Tribe of the Blackfeet Indian Reservation of Montana, Native Village of Barrow Inupiat Traditional Government, Nome Eskimo Community, Aztec, and Maya.", "u": null, "notes": "concept: NI001943162277", "dep": null}, {"v": "Asian", "n": "Asian", "d": "Individuals with origins in any of the original peoples of Central or East Asia, Southeast Asia, or South Asia, including, for example, Chinese, Asian Indian, Filipino, Vietnamese, Korean, and Japanese.", "u": null, "notes": "concept: NI001943162278", "dep": null}, {"v": "BlackOrAfricanAmerican", "n": "Black or African American", "d": "Individuals with origins in any of the Black racial groups of Africa, including, for example, African American, Jamaican, Haitian, Nigerian, Ethiopian, and Somali.", "u": null, "notes": "concept: NI001943162279", "dep": null}, {"v": "(Deprecated) DemographicRaceTwoOrMoreRaces", "n": "(Deprecated) Demographic Race Two or More Races", "d": "(Deprecated) A person having origins in any of more than one of the racial groups.", "u": "Deprecated in CEDS: Deprecated in favor of using the new option Multiracial and/or Multiethnic", "notes": "concept: NI001943162280", "dep": "2026-03-11T00:00:00Z"}, {"v": "NativeHawaiianOrPacificIslander", "n": "Native Hawaiian or Pacific Islander", "d": "Individuals with origins in any of the original peoples of Hawaii, Guam, Samoa, or other Pacific Islands, including, for example, Native Hawaiian, Samoan, Chamorro, Tongan, Fijian, and Marshallese.", "u": null, "notes": "concept: NI001943162281", "dep": null}, {"v": "HispanicOrLatino", "n": "Hispanic or Latino", "d": "Includes individuals of Mexican, Puerto Rican, Salvadoran, Cuban, Dominican, Guatemalan, and other Central or South American or Spanish culture or origin.", "u": null, "notes": "concept: NI001943162284", "dep": null}, {"v": "MultiracialAndOrMultiethnic", "n": "Multiracial and/or Multiethnic", "d": "A person having origins in any of more than one of the race and ethnicity options.", "u": null, "notes": "concept: NI001943928202", "dep": null}, {"v": "MiddleEasternOrNorthAfrican", "n": "Middle Eastern or North African", "d": "Individuals with origins in any of the original peoples of the Middle East or North Africa, including, for example, Lebanese, Iranian, Egyptian, Syrian, Iraqi, and Israeli.", "u": null, "notes": "concept: NI001943928204", "dep": null}, {"v": "RaceAndEthnicityUnknown", "n": "Race and Ethnicity Unknown", "d": "The category used to report a person whose race and ethnicity are not known.", "u": null, "notes": "concept: NI001943162282", "dep": null}, {"v": "White", "n": "White", "d": "Individuals with origins in any of the original peoples of Europe, including, for example, English, German, Irish, Italian, Polish, and Scottish.", "u": null, "notes": "concept: NI001943162283", "dep": null}]$j$::jsonb);
