SELECT public.ceds_tmp_valueset('RecordStatusType', 'A process indicator of the level of stability, quality, and/or preparedness of the record.', NULL, 'scheme: C001972', NULL, $j$[{"v": "Certified", "n": "Certified", "d": "A person or organization with authority over this record or this process indicated the record was complete and accurate to the best of their knowledge.", "u": null, "notes": "concept: NI001972162309", "dep": null}, {"v": "Decertified", "n": "Decertified", "d": "A person or organization with authority over this record or this process indicated they wish to reverse the decision that was previously indicated through the status of Certified.", "u": null, "notes": "concept: NI001972162310", "dep": null}, {"v": "Deleted", "n": "Deleted", "d": "This record is no longer valid.", "u": null, "notes": "concept: NI001972162311", "dep": null}, {"v": "InProcess", "n": "In Process", "d": "The data in this record are potentially transactional in nature.", "u": null, "notes": "concept: NI001972162312", "dep": null}, {"v": "Published", "n": "Published", "d": "The data in this record is in use or was used for federal, state, or local reporting or to fulfill research or data request purposes.", "u": null, "notes": "concept: NI001972162313", "dep": null}, {"v": "Retired", "n": "Retired", "d": "The data in this record was once valid for use and is no longer valid for use per the requirements defined by the organization responsible for the record.", "u": null, "notes": "concept: NI001972162314", "dep": null}, {"v": "Submitted", "n": "Submitted", "d": "The data in this record are not transactional in nature but are complete and do not require any formal certification process.", "u": null, "notes": "concept: NI001972162315", "dep": null}]$j$::jsonb);
