SELECT public.ceds_tmp_valueset('ResponsibleDistrictType', 'The type of responsibility the district has for the student.', NULL, 'scheme: C000594', NULL, $j$[{"v": "Transportation", "n": "Transportation", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for transporting the student to the physical location of the school or facility in which educational services are delivered.", "u": null, "notes": "concept: NI000594172951", "dep": null}, {"v": "IndividualizedEducationProgram", "n": "Individualized education program (IEP)", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for creating and maintaining the student's IEP, a written instructional plan for students with disabilities designated as special education students under the Individuals with Disabilities Education Act (IDEA-Part B) which includes: 1) a statement of present levels of educational performance of a child; 2) a statement of annual goals including short-term instructional objectives; 3) a statement of specific education and related services to be provided and the extent to which the child will be able to participate in regular educational programs; 4) a projected date for initiation and anticipated duration of services; and 5) appropriate objectives, criteria and evaluation procedures and schedules for determining, on at least an annual basis, whether instructional objectives are being achieved.", "u": null, "notes": "concept: NI000594172952", "dep": null}, {"v": "Graduation", "n": "Graduation", "d": "The role/relationship assigned to an organization, institution, or agency responsible for issuing/awarding diplomas. (e.g. for graduation-rate reporting)", "u": null, "notes": "concept: NI000594172953", "dep": null}, {"v": "Funding", "n": "Funding", "d": "The role/relationship assigned to an organization, institution, or agency responsible for funding related to a student enrollment.", "u": null, "notes": "concept: NI000594172954", "dep": null}, {"v": "Attendance", "n": "Attendance", "d": "The role/relationship assigned to an organization, institution, or agency operating the physical or virtual site in which delivery of educational services take place.", "u": null, "notes": "concept: NI000594172955", "dep": null}, {"v": "Accountability", "n": "Accountability", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for student learning under Federal ESEA and State accountability plans. (e.g. for AYP reporting)", "u": null, "notes": "concept: NI000594172956", "dep": null}, {"v": "IEPServiceProvider", "n": "Individualized education program service provider", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for providing services to meet the requirements of the student's Individualized Education Program (IEP).", "u": null, "notes": "concept: NI000594172957", "dep": null}, {"v": "Assessment", "n": "Assessment", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for assessing the student.", "u": null, "notes": "concept: NI000594172958", "dep": null}, {"v": "Instruction", "n": "Instruction", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for providing instruction to the student.", "u": null, "notes": "concept: NI000594172959", "dep": null}, {"v": "Resident", "n": "Resident", "d": "The role/relationship type assigned to an organization, institution, or agency in which the student resides.", "u": null, "notes": "concept: NI000594172960", "dep": null}]$j$::jsonb);
