SELECT public.ceds_tmp_valueset('AccessibilityFeatureType', 'The type of design elements or functionalities integrated into products, services, or environments to ensure equitable access for all individuals, aiming to eliminate barriers and facilitate ease of use.', NULL, 'scheme: C000385', NULL, $j$[{"v": "1000", "n": "Adaptive and specialized equipment or furniture", "d": "Furniture or equipment used to address physical or sensory needs.", "u": null, "notes": "concept: NI000385928224", "dep": null}, {"v": "1001", "n": "Adaptive calculator", "d": "A specialized calculator designed to accommodate users with diverse needs, such as visual impairments or motor difficulties, by customizing its interface and functionality to enhance accessibility and usability.", "u": null, "notes": "concept: NI000385928225", "dep": null}, {"v": "1002", "n": "Alternate response option", "d": "An alternate method for providing a response.", "u": null, "notes": "concept: NI000385928226", "dep": null}, {"v": "1003", "n": "Alternative text", "d": "Scripted statements describing graphics and images (e.g., tables, charts, graphs, timelines, photos, and illustrations).", "u": null, "notes": "concept: NI000385928227", "dep": null}, {"v": "1004", "n": "Amplification", "d": "The ability to adjust the volume control beyond standard volume using other non-embedded devices including, but not limited to, assistive technology, personal hearing aids, or FM systems", "u": null, "notes": "concept: NI000385928228", "dep": null}, {"v": "1005", "n": "Auditory calming", "d": "The use of auditory stimuli to promote relaxation and reduce stress or anxiety.", "u": null, "notes": "concept: NI000385928229", "dep": null}, {"v": "1006", "n": "Bilingual dictionary", "d": "A comprehensive dictionary containing definitions and contextual information in two languages that may contain construct-relevant terms.", "u": null, "notes": "concept: NI000385928230", "dep": null}, {"v": "1007", "n": "Word to word bilingual dictionary", "d": "A comprehensive collection of individual words or short phrases translated in two languages that may contain construct-relevant terms.", "u": null, "notes": "concept: NI000385928231", "dep": null}, {"v": "1008", "n": "Word to word bilingual glossary", "d": "A collection of construct-irrelevant individual words or short phrases translated in two languages.", "u": null, "notes": "concept: NI000385928232", "dep": null}, {"v": "1009", "n": "Braille", "d": "Braille code is a tactile system of raised dots that enables a person to read through touch.", "u": null, "notes": "concept: NI000385928233", "dep": null}, {"v": "1010", "n": "Breaks", "d": "A pause allowing the individual to temporarily suspend activities.", "u": null, "notes": "concept: NI000385928234", "dep": null}, {"v": "1011", "n": "Calculator", "d": "An electronic device or software that performs mathematical calculations.", "u": null, "notes": "concept: NI000385928235", "dep": null}, {"v": "1012", "n": "Closed captioning", "d": "Text-based transcriptions of dialogue, sounds, and relevant audio cues that are synchronized with a video or audio content.", "u": null, "notes": "concept: NI000385928236", "dep": null}, {"v": "1013", "n": "Reference sheet", "d": "A structured document specifically designed for providing reference materials, such as multiplication tables, periodic tables, etc.", "u": null, "notes": "concept: NI000385928237", "dep": null}, {"v": "1014", "n": "Assessment countdown timer", "d": "A timer which shows the time allowed for the assessment and counts down when the administration starts.", "u": null, "notes": "concept: NI000385928238", "dep": null}, {"v": "1015", "n": "English dictionary", "d": "A comprehensive dictionary containing definitions and contextual information in English that may contain construct-relevant terms.", "u": null, "notes": "concept: NI000385928239", "dep": null}, {"v": "1016", "n": "English glossary", "d": "A collection of grade and context appropriate definitions of specific construct-irrelevant terms in English.", "u": null, "notes": "concept: NI000385928240", "dep": null}, {"v": "1017", "n": "Assessment extended time", "d": "Additional time to complete an assessment beyond the standard time allotment.", "u": null, "notes": "concept: NI000385928241", "dep": null}, {"v": "1018", "n": "Highlighter", "d": "A tool for marking desired text.", "u": null, "notes": "concept: NI000385928242", "dep": null}, {"v": "1019", "n": "Illustration glossaries", "d": "A collection of key terms, concepts, or subjects accompanied by illustrative visuals, such as images, diagrams, or graphics. It is designed to enhance understanding and learning by combining written definitions with visual representations, making complex or abstract ideas more accessible and engaging.", "u": null, "notes": "concept: NI000385928243", "dep": null}, {"v": "1020", "n": "Large print paper assessment booklet", "d": "A larger size version of a paper- based assessment that increases the font size, illustrations, and other test elements.", "u": null, "notes": "concept: NI000385928244", "dep": null}, {"v": "1021", "n": "Line guide", "d": "A tool used to emphasize a line of text.", "u": null, "notes": "concept: NI000385928245", "dep": null}, {"v": "1022", "n": "Masking", "d": "A tool used to cover the text above and below the line or lines that the individual is reading, so that only one line or lines of text is visible at a time.", "u": null, "notes": "concept: NI000385928246", "dep": null}, {"v": "1023", "n": "Medical supports", "d": "Support for a person with a medical condition.", "u": null, "notes": "concept: NI000385928247", "dep": null}, {"v": "1024", "n": "Assessment multiple days", "d": "Assessment activities are completed over multiple days without extending the time available to complete the assessment.", "u": null, "notes": "concept: NI000385928248", "dep": null}, {"v": "1025", "n": "Noise canceling", "d": "Equipment used to block external sounds and reduce distractions.", "u": null, "notes": "concept: NI000385928249", "dep": null}, {"v": "1026", "n": "Group size", "d": "An adjustment to the number of individuals in the setting.", "u": null, "notes": "concept: NI000385928250", "dep": null}, {"v": "1027", "n": "Read aloud", "d": "Text is read aloud to the individual.", "u": null, "notes": "concept: NI000385928251", "dep": null}, {"v": "1028", "n": "Read aloud to self", "d": "The individual may read content aloud to themselves, with or without a device.", "u": null, "notes": "concept: NI000385928252", "dep": null}, {"v": "1029", "n": "Assessment Refocus", "d": "Redirecting the individual's focus during the assessment ensuring that such redirections do not suggest revisiting a prior item or imply potential errors.", "u": null, "notes": "concept: NI000385928253", "dep": null}, {"v": "1030", "n": "Repeat test directions", "d": "The individual being assessed may request that the test administrator repeat test directions prior to beginning the actual test items.", "u": null, "notes": "concept: NI000385928254", "dep": null}, {"v": "1031", "n": "Screen reader", "d": "A technology tool that describes what is being displayed on the screen (e.g., text, images), converting the content into audio or braille output.", "u": null, "notes": "concept: NI000385928255", "dep": null}, {"v": "1032", "n": "Setting", "d": "An adjustment in the environment based on individual needs.", "u": null, "notes": "concept: NI000385928256", "dep": null}, {"v": "1033", "n": "Signed administration", "d": "Content is presented via a form of sign language.", "u": null, "notes": "concept: NI000385928257", "dep": null}, {"v": "1034", "n": "Simplified test directions", "d": "Test directions, provided prior to beginning the test, are simplified or clarified.", "u": null, "notes": "concept: NI000385928258", "dep": null}, {"v": "1035", "n": "Specific test administrator", "d": "A designated test administrator.", "u": null, "notes": "concept: NI000385928259", "dep": null}, {"v": "1036", "n": "Display Format Adjustment", "d": "Content is presented in a streamlined, stacked, or simplified format.", "u": null, "notes": "concept: NI000385928260", "dep": null}, {"v": "1037", "n": "Strikethrough", "d": "A tool to visually mark or cancel out text.", "u": null, "notes": "concept: NI000385928261", "dep": null}, {"v": "1038", "n": "Tactile graphics", "d": "Tactile graphics convey non-textual information through touch. These may include tactile representations of pictures, maps, graphs, diagrams and other images.", "u": null, "notes": "concept: NI000385928262", "dep": null}, {"v": "1039", "n": "Tactile symbols", "d": "A static communication form that conveys concepts through touch, encompassing tactile objects, symbols, or manipulatives used to support assessment or instructional content.", "u": null, "notes": "concept: NI000385928263", "dep": null}, {"v": "1040", "n": "Thesaurus", "d": "A thesaurus contains synonyms of words.", "u": null, "notes": "concept: NI000385928264", "dep": null}, {"v": "1041", "n": "Assessment time of day", "d": "Altering the schedule for administering assessments to the time of day optimal for the individual's needs.", "u": null, "notes": "concept: NI000385928265", "dep": null}, {"v": "1042", "n": "Translation", "d": "Converting text or speech from one language into another.", "u": null, "notes": "concept: NI000385928266", "dep": null}, {"v": "1043", "n": "Bilingual glossary", "d": "A collection of grade and context appropriate definitions of specific construct-irrelevant terms provided in two languages.", "u": null, "notes": "concept: NI000385928267", "dep": null}, {"v": "1044", "n": "Turn off any universal tools", "d": "Deactivating one or more universal tools the individual does not require, is unable to use, or could potentially cause distraction.", "u": null, "notes": "concept: NI000385928268", "dep": null}, {"v": "1045", "n": "Unlimited replays", "d": "The individual is allowed to replay multimedia components an unlimited number of times.", "u": null, "notes": "concept: NI000385928269", "dep": null}, {"v": "1046", "n": "Unlimited rerecording", "d": "The individual is allowed to re-record responses an unlimited number of times.", "u": null, "notes": "concept: NI000385928270", "dep": null}, {"v": "9999", "n": "Other", "d": "The type of design elements or functionalities integrated into products, services, or environments to ensure equitable access for all individuals, aiming to eliminate barriers and facilitate ease of use is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI000385928271", "dep": null}]$j$::jsonb);
