SELECT public.ceds_tmp_valueset('DistanceEducationCourseEnrollment', 'An individual''s enrollment in a course or courses in which the instructional content is delivered exclusively via distance education. Distance education is education that uses one or more technologies to deliver instruction to students who are separated from the instructor and to support regular and substantive interaction between the students and the instructor synchronously or asynchronously. Technologies used for instruction may include: Internet; one-way and two-way transmissions through open broadcasts, closed circuit, cable, microwave, broadband lines, fiber optics, satellite or wireless communication devices; audio conferencing; and video cassette, DVDs, and CD-ROMs, if the cassette, DVDs, and CD-ROMs are used in a course in conjunction with the technologies listed above.', NULL, 'scheme: C000728', NULL, $j$[{"v": "EnrolledExclusively", "n": "Enrolled exclusively in distance education courses", "d": "The student is enrolled exclusively in distance education courses.", "u": null, "notes": "concept: NI000728115658", "dep": null}, {"v": "EnrolledInSome", "n": "Enrolled in some but not all distance education courses", "d": "The student is enrolled in some but not all distance education courses.", "u": null, "notes": "concept: NI000728115659", "dep": null}, {"v": "NotEnrolled", "n": "Not enrolled in distance education courses", "d": "The student is not enrolled in distance education courses.", "u": null, "notes": "concept: NI000728116264", "dep": null}]$j$::jsonb);
