SELECT public.ceds_tmp_valueset('AcademicRank', 'The academic rank of staff whose primary responsibility is instruction, research, and/or public service. Institutions without standard academic ranks should code staff whose primary responsibility is instruction, research, and/or public service as "No Academic Rank."', NULL, 'scheme: C000740', NULL, $j$[{"v": "AssistantProfessor", "n": "Assistant Professor", "d": "Assistant Professor is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740115283", "dep": null}, {"v": "AssociateProfessor", "n": "Associate Professor", "d": "Associate Professor is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740115299", "dep": null}, {"v": "Instructor", "n": "Instructor", "d": "Instructor is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740115943", "dep": null}, {"v": "Lecturer", "n": "Lecturer", "d": "Lecturer is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740116018", "dep": null}, {"v": "NoAcademicRank", "n": "No Academic Rank", "d": "No Academic Rank is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740116216", "dep": null}, {"v": "Professor", "n": "Professor", "d": "Professor is specified as the academic rank of staff whose primary responsibility is instruction, research, and/or public service.", "u": null, "notes": "concept: NI000740116625", "dep": null}]$j$::jsonb);
