SELECT public.ceds_tmp_valueset('ExitOrWithdrawalType', 'The circumstances under which the student exited from membership in an educational institution.', NULL, 'scheme: C000110', NULL, $j$[{"v": "03503", "n": "Enrolled in a foreign exchange program", "d": "The student exited from membership in the educational institution and is enrolled in a foreign exchange program.", "u": null, "notes": "concept: NI000110172646", "dep": null}, {"v": "03505", "n": "Exited", "d": "The student was exited from membership in the educational institution for administrative or system requirements and will be reenrolled in the same educational institution with a new Enrollment Entry Date.", "u": null, "notes": "concept: NI000110172647", "dep": null}, {"v": "03508", "n": "Student is in a charter school managed by the same local education agency", "d": "The student exited from membership in the educational institution and is in a charter school managed by the same local education agency.", "u": null, "notes": "concept: NI000110172648", "dep": null}, {"v": "03509", "n": "Completed with a state-recognized equivalency certificate", "d": "The student exited from membership in the educational institution and completed with a state-recognized equivalency certificate.", "u": null, "notes": "concept: NI000110172649", "dep": null}, {"v": "09999", "n": "Other", "d": "The circumstances under which the student exited from membership in an educational institution is in a category not yet defined in CEDS.", "u": null, "notes": "concept: NI000110172650", "dep": null}, {"v": "03502", "n": "Not enrolled, eligible to return", "d": "The student exited from membership in the education institution for an extended period unrelated to any other existing exit code. It is expected the student will return to this school after the reason for the extended period has completed", "u": null, "notes": "concept: NI000110172651", "dep": null}, {"v": "03499", "n": "Student is in the same LEA, receiving education services, but is not assigned to a particular school", "d": "The student exited from membership in the educational institution and the student is in the same LEA, receiving education services, but is not assigned to a particular school.", "u": null, "notes": "concept: NI000110172652", "dep": null}, {"v": "01931", "n": "Not enrolled, unknown status", "d": "The student exited from membership in the educational institution and the reason is presently unknown. It is expected this temporary option will be changed when the reason for exit has been determined.", "u": null, "notes": "concept: NI000110172653", "dep": null}, {"v": "01930", "n": "Enrolled in a postsecondary early admission program", "d": "The student exited from membership in the educational institution and enrolled in a postsecondary early admission program.", "u": null, "notes": "concept: NI000110172654", "dep": null}, {"v": "01928", "n": "Completed grade 12, but did not meet all graduation requirements", "d": "The student exited from membership in the educational institution and completed grade 12, but did not meet all graduation requirements.", "u": null, "notes": "concept: NI000110172655", "dep": null}, {"v": "01927", "n": "Discontinued schooling", "d": "The student exited from membership in the educational institution and discontinued schooling.", "u": null, "notes": "concept: NI000110172656", "dep": null}, {"v": "01926", "n": "Reached maximum age for services", "d": "The student reached maximum age for services.", "u": null, "notes": "concept: NI000110172657", "dep": null}, {"v": "01925", "n": "Expelled or involuntarily withdrawn", "d": "The student was expelled or involuntarily withdrawn.", "u": null, "notes": "concept: NI000110172658", "dep": null}, {"v": "01924", "n": "Withdrawn due to illness", "d": "The student was withdrawn due to illness.", "u": null, "notes": "concept: NI000110172659", "dep": null}, {"v": "01922", "n": "Completed school with other credentials", "d": "The student exited from membership in the educational institution and completed school with other credentials.", "u": null, "notes": "concept: NI000110172660", "dep": null}, {"v": "01921", "n": "Graduated with regular, advanced, International Baccalaureate, or other type of diploma", "d": "The student exited from membership in the educational institution and graduated with regular, advanced, International Baccalaureate, or other type of diploma.", "u": null, "notes": "concept: NI000110172661", "dep": null}, {"v": "01919", "n": "Transferred to a charter school in a different LEA in the state", "d": "The student exited from membership in the educational institution and transferred to a charter school in a different LEA in the same state.", "u": null, "notes": "concept: NI000110172662", "dep": null}, {"v": "01918", "n": "Transferred to home schooling", "d": "The student exited from membership in the educational institution and transferred to home schooling.", "u": null, "notes": "concept: NI000110172663", "dep": null}, {"v": "01917", "n": "Transferred to an institution", "d": "The student exited from membership in the educational institution and transferred to an institution.", "u": null, "notes": "concept: NI000110172664", "dep": null}, {"v": "01916", "n": "Transferred to a school outside of the country", "d": "The student exited from membership in the educational institution and transferred to a school outside of the country.", "u": null, "notes": "concept: NI000110172665", "dep": null}, {"v": "01915", "n": "Transferred to a private, religiously-affiliated school in a different state", "d": "The student exited from membership in the educational institution and transferred to a private, religiously-affiliated school in a different state.", "u": null, "notes": "concept: NI000110172666", "dep": null}, {"v": "01914", "n": "Transferred to a private, religiously-affiliated school within the geographic boundaries of a different LEA in the same state", "d": "The student exited from membership in the educational institution and transferred to a private, religiously-affiliated school within the geographic boundaries of a different LEA in the same state.", "u": null, "notes": "concept: NI000110172667", "dep": null}, {"v": "01913", "n": "Transferred to a private, religiously-affiliated school within the geographic boundaries of the same local education agency", "d": "The student exited from membership in the educational institution and transferred to a private, religiously-affiliated school within the geographic boundaries of the same local education agency.", "u": null, "notes": "concept: NI000110172668", "dep": null}, {"v": "01912", "n": "Transferred to a private, non-religiously-affiliated school in a different state", "d": "The student exited from membership in the educational institution and transferred to a private, non-religiously-affiliated school in a different state.", "u": null, "notes": "concept: NI000110172669", "dep": null}, {"v": "01911", "n": "Transferred to a private, non-religiously-affiliated school within the geographic boundaries of a different LEA in the same state", "d": "The student exited from membership in the educational institution and transferred to a private, non-religiously-affiliated school within the geographic boundaries of a different LEA in the same state.", "u": null, "notes": "concept: NI000110172670", "dep": null}, {"v": "01910", "n": "Transferred to a private, non-religiously-affiliated school within the geographic boundaries as the same local education agency", "d": "The student exited from membership in the educational institution and transferred to a private, non-religiously-affiliated school within the geographic boundaries as the same local education agency.", "u": null, "notes": "concept: NI000110172671", "dep": null}, {"v": "01909", "n": "Transferred to a public school in a different state", "d": "The student exited from membership in the educational institution and transferred to a public school in a different state.", "u": null, "notes": "concept: NI000110172672", "dep": null}, {"v": "01908", "n": "Transferred to a public school in a different local education agency in the same state", "d": "The student exited from membership in the educational institution and transferred to a public school in a different local education agency in the same state.", "u": null, "notes": "concept: NI000110172673", "dep": null}, {"v": "01907", "n": "Student is in a different public school in the same local education agency", "d": "The student exited from membership in the educational institution and is in a different public school in the same local education agency.", "u": null, "notes": "concept: NI000110172674", "dep": null}, {"v": "73060", "n": "Officially withdrew and enrolled in ABE, adult secondary education, or adult ESL program", "d": "The student officially withdrew and enrolled in an adult basic education, adult secondary education, or adult English as a Second Language program.", "u": null, "notes": "concept: NI000110172675", "dep": null}, {"v": "73061", "n": "Officially withdrew and enrolled in a workforce training program", "d": "The student officially withdrew and enrolled in a workforce training program.", "u": null, "notes": "concept: NI000110172676", "dep": null}, {"v": "73064", "n": "Died", "d": "The student exited from membership in the educational institution due to death.", "u": null, "notes": "concept: NI000110172677", "dep": null}, {"v": "73065", "n": "Permanently incapacitated", "d": "The student exited from membership in the educational institution and is permanently incapacitated.", "u": null, "notes": "concept: NI000110172678", "dep": null}, {"v": "73062", "n": "Student is expected to return to the same school", "d": "The student is expected to return to the same school at the beginning of the next school year.", "u": null, "notes": "concept: NI000110172679", "dep": null}, {"v": "73063", "n": "Transferred to a charter school in a different state", "d": "The student exited from membership in the educational institution and transferred to a charter school in a different state.", "u": null, "notes": "concept: NI000110172680", "dep": null}, {"v": "73066", "n": "Matriculation to another school in the same local education agency", "d": "The student exited from membership in the educational institution after successful completion of the highest instructional level offered at the school with the exception of graduation and is expected to enroll in another school in the same local education agency offering the next instructional level.", "u": null, "notes": "concept: NI000110172681", "dep": null}, {"v": "73068", "n": "Transfer to a private school in the state", "d": "The student exited from membership in the education institution and transferred to a private school in the state.", "u": null, "notes": "concept: NI000110172682", "dep": null}, {"v": "73067", "n": "Transferred to a school outside of the state", "d": "The student exited from membership in the education institution and transferred to a public or private school outside of the state.", "u": null, "notes": "concept: NI000110172683", "dep": null}]$j$::jsonb);
