SELECT public.ceds_tmp_valueset('ERSRuralUrbanContinuumCode', 'Rural-Urban Continuum Codes form a classification scheme that distinguishes metropolitan (metro) counties by the population size of their metro area, and nonmetropolitan (nonmetro) counties by degree of urbanization and adjacency to a metro area or areas. The metro and nonmetro categories have been subdivided into three metro and six nonmetro groupings, resulting in a nine-part county codification. The codes allow researchers working with county data to break such data into finer residential groups beyond a simple metro-nonmetro dichotomy, particularly for the analysis of trends in nonmetro areas that may be related to degree of rurality and metro proximity.', NULL, 'scheme: C000862', NULL, $j$[{"v": "1", "n": "Counties in metro areas of 1 million population or more", "d": "Counties in metro areas of 1 million population or more", "u": null, "notes": "concept: NI000862114381", "dep": null}, {"v": "2", "n": "Counties in metro areas of 250,000 to 1 million population", "d": "Counties in metro areas of 250,000 to 1 million population", "u": null, "notes": "concept: NI000862114698", "dep": null}, {"v": "3", "n": "Counties in metro areas of fewer than 250,000 population", "d": "Counties in metro areas of fewer than 250,000 population", "u": null, "notes": "concept: NI000862114809", "dep": null}, {"v": "4", "n": "Urban population of 20,000 or more, adjacent to a metro area", "d": "Urban population of 20,000 or more, adjacent to a metro area", "u": null, "notes": "concept: NI000862114838", "dep": null}, {"v": "5", "n": "Urban population of 20,000 or more, not adjacent to a metro area", "d": "Urban population of 20,000 or more, not adjacent to a metro area", "u": null, "notes": "concept: NI000862114961", "dep": null}, {"v": "6", "n": "Urban population of 2,500 to 19,999, adjacent to a metro area", "d": "Urban population of 2,500 to 19,999, adjacent to a metro area", "u": null, "notes": "concept: NI000862115000", "dep": null}, {"v": "7", "n": "Urban population of 2,500 to 19,999, not adjacent to a metro area", "d": "Urban population of 2,500 to 19,999, not adjacent to a metro area", "u": null, "notes": "concept: NI000862115024", "dep": null}, {"v": "8", "n": "Completely rural or less than 2,500 urban population, adjacent to a metro area", "d": "Completely rural or less than 2,500 urban population, adjacent to a metro area", "u": null, "notes": "concept: NI000862115094", "dep": null}, {"v": "9", "n": "Completely rural or less than 2,500 urban population, not adjacent to a metro area", "d": "Completely rural or less than 2,500 urban population, not adjacent to a metro area", "u": null, "notes": "concept: NI000862115112", "dep": null}]$j$::jsonb);
