SELECT public.ceds_tmp_valueset('WeaponType', 'Identifies the type of weapon used during an incident.', NULL, 'scheme: C001211', NULL, $j$[{"v": "OtherObject", "n": "Other object", "d": "The weapon involved was another known object.", "u": null, "notes": "concept: NI001211173087", "dep": null}, {"v": "OtherSharpObject", "n": "Other sharp object", "d": "The weapon involved was another type of sharp object, (e.g., razor blade, ice pick, dirk, Chinese star, other pointed instrument [used as a weapon]).", "u": null, "notes": "concept: NI001211173088", "dep": null}, {"v": "KnifeGreaterThanThreeInches", "n": "Knife Greater Than Three Inches", "d": "Knife with blade length greater than or equal to 3 inches - the weapon involved was a knife with a blade 3 inches or greater in length.", "u": null, "notes": "concept: NI001211173089", "dep": null}, {"v": "KnifeLessThanThreeInches", "n": "Knife Less Than Three Inches", "d": "Knife with blade length less than 3 inches in length - the weapon involved was a knife with a blade at least 2.5 inches in length, but less than 3 inches in length.", "u": null, "notes": "concept: NI001211173090", "dep": null}, {"v": "KnifeLessThanTwoPointFiveInches", "n": "Knife Less Than 2.5 Inches", "d": "Knife with blade length less than 2.5 inches - the weapon involved was a knife with a blade less than 2.5 inches in length.", "u": null, "notes": "concept: NI001211173091", "dep": null}, {"v": "Knife", "n": "Knife", "d": "The weapon involved was a knife.", "u": null, "notes": "concept: NI001211173092", "dep": null}, {"v": "OtherFirearm", "n": "Other Firearm", "d": "Other type of firearm", "u": null, "notes": "concept: NI001211173093", "dep": null}, {"v": "Rifle", "n": "Rifle", "d": "A weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger.", "u": null, "notes": "concept: NI001211173094", "dep": null}, {"v": "Shotgun", "n": "Shotgun", "d": "A weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shots or a single projectile for each single pull of the trigger.", "u": null, "notes": "concept: NI001211173095", "dep": null}, {"v": "Handgun", "n": "Handgun", "d": "Any firearm which has a short stock and is designed to be held and fired by the use of a single hand.", "u": null, "notes": "concept: NI001211173096", "dep": null}, {"v": "Firearm", "n": "Firearm", "d": "Any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; the frame or receiver of any such weapon; any firearm muffler or firearm silencer; or any destructive device.", "u": null, "notes": "concept: NI001211173097", "dep": null}, {"v": "BBGun", "n": "BB Gun", "d": "The weapon involved was a BB gun.", "u": null, "notes": "concept: NI001211173098", "dep": null}, {"v": "DestructiveDevice", "n": "Destructive Device", "d": "Any explosive, incendiary (e.g., bomb, grenade), or poison gas; any weapon which may expel a projectile by explosive or another propellant with the barrel bore is more than one-half inch in diameter.", "u": null, "notes": "concept: NI001211173099", "dep": null}, {"v": "IEPServiceProvider", "n": "Individualized education program service provider", "d": "The role/relationship type assigned to an organization, institution, or agency responsible for providing services to meet the requirements of the student's Individualized Education Program (IEP).", "u": null, "notes": "concept: NI001211173100", "dep": null}, {"v": "Unknown", "n": "Unknown weapon", "d": "A weapon was used in the incident, but the type is unknown.", "u": null, "notes": "concept: NI001211173083", "dep": null}, {"v": "None", "n": "None", "d": "No weapon was used in the incident", "u": null, "notes": "concept: NI001211173084", "dep": null}, {"v": "OtherWeapon", "n": "Other weapon", "d": "The incident involved a weapon other than those described above.", "u": null, "notes": "concept: NI001211173085", "dep": null}, {"v": "Substance", "n": "Substance used as weapon", "d": "The weapon involved was a substance (e.g., mace, tear gas) that was used as a weapon.", "u": null, "notes": "concept: NI001211173086", "dep": null}]$j$::jsonb);
