SELECT public.ceds_tmp_valueset('AssessmentItemResponseStatus', 'The status of the response for a given item.', NULL, 'scheme: C000405', NULL, $j$[{"v": "Attempted", "n": "Attempted", "d": "Attempted is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115309", "dep": null}, {"v": "Complete", "n": "Complete", "d": "Complete is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115472", "dep": null}, {"v": "Correct", "n": "Correct", "d": "Correct is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115500", "dep": null}, {"v": "Incomplete", "n": "Incomplete", "d": "Incomplete is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115917", "dep": null}, {"v": "Incorrect", "n": "Incorrect", "d": "Incorrect is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115919", "dep": null}, {"v": "InProgress", "n": "In Progress", "d": "In Progress is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405115932", "dep": null}, {"v": "NotProficient", "n": "Not Yet Proficient", "d": "Not Yet Proficient is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405116275", "dep": null}, {"v": "NotViewed", "n": "Not Viewed", "d": "Not Viewed is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405116289", "dep": null}, {"v": "PartialComplete", "n": "Partial Complete", "d": "Partial Complete is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405116499", "dep": null}, {"v": "Proficient", "n": "Proficient", "d": "Proficient is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405116627", "dep": null}, {"v": "Viewed", "n": "Viewed", "d": "Viewed is specified as the status of the response for a given item.", "u": null, "notes": "concept: NI000405117155", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('AssessmentItemType', 'The specific type of assessment item.', NULL, 'scheme: C000390', NULL, $j$[{"v": "MultipleChoice", "n": "Multiple-choice", "d": "A forced-choice assessment item featuring a stem (which is a prompt) and two or more choices, one of which is the correct answer, and the remainder are distractors.", "u": null, "notes": "concept: NI000390101916", "dep": null}, {"v": "FillInTheBlank", "n": "Fill-in-the-blank", "d": "A short-answer item in which examinees are presented with a sentence in which a word or words is missing, and are asked to provide the missing word(s).", "u": null, "notes": "concept: NI000390101917", "dep": null}, {"v": "TrueFalse", "n": "True/False", "d": "A declarative statement that examinees judge true or false. Variants of the true/false item have examinees identify: fact/opinion, supported by the narrative or not, etc.", "u": null, "notes": "concept: NI000390101918", "dep": null}, {"v": "Matching", "n": "Matching", "d": "An assessment item in which examinees are presented with a set of premises and are asked to link them to a set of responses, via directions for identifying the correspondences.", "u": null, "notes": "concept: NI000390101920", "dep": null}, {"v": "ShortAnswer", "n": "Short answer", "d": "An assessment item that asks examinees to provide a very short response, such as an item asking for a correct computational or text-based answer, or a closed item.", "u": null, "notes": "concept: NI000390101921", "dep": null}, {"v": "Labeling", "n": "Labeling", "d": "An assessment item that presents an image or object, such as a graph, diagram, or geometric shape, and asks examinees to apply one or more descriptive, symbolic, or quantitative labels.", "u": null, "notes": "concept: NI000390101922", "dep": null}, {"v": "VisualRepresentation", "n": "Visual representation", "d": "An assessment item that asks examinees to create simple graphics (e.g., sketches, schematics, diagrams) to generate evidence of understanding a key concept or its application.", "u": null, "notes": "concept: NI000390101923", "dep": null}, {"v": "ShowYourWork", "n": "Show your work", "d": "An assessment item that asks examinees to show preparatory work for the creation of a product, performance, or extended text. The item may be treated as one component of a task leading to a final product or may be stand-alone, as evidence of preliminary thinking and problem-solving.", "u": null, "notes": "concept: NI000390101924", "dep": null}, {"v": "OtherConstructedResponse", "n": "Other constructed response", "d": "Any assessment item that asks the examinee to develop answers without suggested answer choices and that does not fit the definition of the other assessment item types.", "u": null, "notes": "concept: NI000390101925", "dep": null}, {"v": "PerformanceTask", "n": "Performance task", "d": "An item or set of items that directs examinees to demonstrate what they know and can do via a performance, given a set of conditions and expectations for the task(s). The range of possible performances is long, and may include oral, written, procedural, artistic, and/or psychomotor performances such as conducting science experiments, developing informational materials, or participating in a recital, to name a few. An extended constructed response or essay item is a specific instance of a performance task.", "u": null, "notes": "concept: NI000390101926", "dep": null}, {"v": "Reordering", "n": "Reordering", "d": "An assessment item that asks examinees to reorder items, such as pictures of events within a chronological sequence, items forming a pattern, or text within a passage.", "u": null, "notes": "concept: NI000390101929", "dep": null}, {"v": "Substitution", "n": "Substitution", "d": "An assessment item that presents visual or written stimulus with incomplete or incorrect information and asks examinees to correct or complete the information.", "u": null, "notes": "concept: NI000390101930", "dep": null}, {"v": "Other", "n": "Other", "d": "Other assessment item type.", "u": null, "notes": "concept: NI000390101931", "dep": null}, {"v": "MultipleResponse", "n": "Multiple Response", "d": "A multiple choice assessment item that directs examinees to select all of the options that apply.", "u": null, "notes": "concept: NI000390104760", "dep": null}, {"v": "ExtendedResponse", "n": "Extended Response (Essay)", "d": "An assessment item type that asks examinees to prepare and deliver an organized, cohesive response to an item prompt. The essay item is one type of extended constructed response. Others include the development and sequencing of mathematical proofs, extended analytical papers, and research papers.", "u": null, "notes": "concept: NI000390104761", "dep": null}, {"v": "TechnologyEnhancedInteractive", "n": "Technology Enhanced / Interactive", "d": "An interactive assessment item delivered in an online or computerized testing environment such that the manipulation of the stem, options, or other facet of the item by the examinees becomes part of the item prompt or part of the item response. Scalise and Gifford (2006**) present a taxonomy of 28 innovative item types that include: Drag and Drop, Reordering, and other experiential items.", "u": null, "notes": "concept: NI000390104762", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('BlendedLearningModelType', 'A type of formal education program in which a student learns at least in part through online learning, with some element of student control over time, place, path, and/or pace; at least in part in a supervised brick-and-mortar location away from home; and the modalities along each student''s learning path within a course or subject are connected to provide an integrated learning experience.', NULL, 'scheme: C001287', NULL, $j$[{"v": "Rotation", "n": "Rotation model", "d": "A model in which within a given course or subject, students rotate between learning modalities, at least one of which is online learning. Other modalities might include activities such as small-group or full-class instruction, group projects, individual tutoring, and pencil-and-paper assignments.", "u": null, "notes": "concept: NI001287141404", "dep": null}, {"v": "FlexModel", "n": "Flex model", "d": "A model in which online learning is the backbone of student learning, even if it directs students to offline activities at times. Students move on an individually customized, fluid schedule among learning modalities, and the teacher of record is on-site. The teacher-of-record or other adults provide face-to-face support on a flexible and adaptive as-needed basis through activities such as small-group instruction, group projects, and individual tutoring.", "u": null, "notes": "concept: NI001287141405", "dep": null}, {"v": "ALaCarte", "n": "A La Carte model", "d": "A model in which students take one or more courses entirely online with an online teacher of record and at the same time continue to have brick-and-mortar educational experiences. Students may take the online courses either on the brick-and-mortar campus or off-site. This differs from full-time online learning and the Enriched Virtual model because it is not a whole-school experience.", "u": null, "notes": "concept: NI001287141406", "dep": null}, {"v": "EnrichedVirtual", "n": "Enriched Virtual model", "d": "A whole-school experience in which within each course, students divide their time between attending a brick-and-mortar campus and learning remotely, off-site, using online delivery of content and instruction.", "u": null, "notes": "concept: NI001287141407", "dep": null}, {"v": "Other", "n": "Other", "d": "A model for implementing blended learning that does not fit the definition of the other blended learning model types", "u": null, "notes": "concept: NI001287141408", "dep": null}]$j$::jsonb);
