SELECT public.ceds_tmp_valueset('RetentionExemptionReason', 'The reason why a student was exempted from retention in a grade level.', NULL, 'scheme: C002119', NULL, $j$[{"v": "1000", "n": "English Learner Less Than 2 Years", "d": "The reason why this student was exempted from retention in a grade level because the student was an English Learner student who has less than two years of instruction in an English Learner program.", "u": null, "notes": "concept: NI002119190640", "dep": null}, {"v": "1001", "n": "English Learner Less than 3 Years", "d": "The reason why this student was exempted from retention in a grade level because the student was an English Learner student who has less than three years of instruction in an English Learner program.", "u": null, "notes": "concept: NI002119190641", "dep": null}, {"v": "1002", "n": "Not assessed IEP", "d": "The reason why this student was exempted from retention in a grade level was because the student has a disability whose individualized education plan (IEP) indicates that participation in the statewide accountability assessment program is not appropriate, as authorized under state law.", "u": null, "notes": "concept: NI002119190643", "dep": null}, {"v": "1003", "n": "Assessed IEP or Section 504", "d": "The reason why this student was exempted from retention in a grade level because the student with a disability (1) participated in the state annual accountability assessment and (2) has an Individualized Education Program (IEP) or Section 504 Plan that reflects the student has either (a) received intensive remediation in reading for two years but still demonstrates a deficiency or (b) was previously retained in the same grade or an earlier grade.", "u": null, "notes": "concept: NI002119190639", "dep": null}, {"v": "1004", "n": "Alternative assessment", "d": "The reason why this student was exempted from retention in a grade level because the student demonstrated proficiency on an alternative standardized assessment approved by the State Board of Education.", "u": null, "notes": "concept: NI002119190638", "dep": null}, {"v": "1005", "n": "Intensive intervention with retention 2 years", "d": "The reason why this student was exempted from retention in a grade level because the student received intensive intervention in reading for two years but still demonstrated a deficiency in reading and was previously retained in the same grade or an earlier grade for a total of two years and has not met proficient education criteria.", "u": null, "notes": "concept: NI002119190642", "dep": null}, {"v": "1006", "n": "Student Portfolio", "d": "The reason why this student was exempted from retention in a grade level was because student demonstrated a reading level through a portfolio demonstrating competency in all state standards for this grade level.", "u": null, "notes": "concept: NI002119190645", "dep": null}, {"v": "1007", "n": "Parent Request", "d": "The student’s parent or legal guardian has requested, in the appropriate time frame, the student not be retained, and the superintendent, chief administrator, or their designee has determined that promotion is in the best interest of the student.", "u": null, "notes": "concept: NI002119190644", "dep": null}, {"v": "9999", "n": "Other", "d": "The reason why this student was exempted from retention in a grade level is an option not yet defined in CEDS.", "u": null, "notes": "concept: NI002119190646", "dep": null}]$j$::jsonb);
