SELECT public.ceds_tmp_valueset('CRDCJusticeFacilityType', 'The type of public or private facility that confines pre-adjudicated/pre-convicted individuals, post-adjudicated/post-convicted individuals, or both.', NULL, 'scheme: C002192', NULL, $j$[{"v": "Preadjudication", "n": "Pre-adjudication facility", "d": "Confines pre-adjudicated juveniles. A pre-adjudicated juvenile is an individual (typically under 21 years of age) who has been charged, but who has not participated in the court process that determines whether the juvenile has committed the crime. Adjudication is the court process that determines (judges) if the juvenile committed the act for which the juvenile is charged.", "u": null, "notes": "concept: NI002192928196", "dep": null}, {"v": "Postadjudication", "n": "Post-adjudication facility", "d": "Confines post-adjudicated juveniles. A post-adjudicated juvenile is an individual (typically under 21 years of age) who has been charged and determined to have committed the crime. Adjudication is the court process that determines (judges) if the juvenile committed the act for which the juvenile is charged.", "u": null, "notes": "concept: NI002192928197", "dep": null}, {"v": "Preconviction", "n": "Pre-conviction facility", "d": "Confines pre-convicted adults. A pre-convicted adult is an individual (typically 21 years of age or older) who has been charged, but who has not participated in the court process that determines (judges) if the adult committed the act for which the adult is charged.", "u": null, "notes": "concept: NI002192928198", "dep": null}, {"v": "Postconviction", "n": "Post-conviction facility", "d": "Confines post-convicted adults. A post-convicted adult is an individual (typically 21 years of age or older) who has been charged and determined to have committed the crime.", "u": null, "notes": "concept: NI002192928199", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('JusticeFacilityIndicator', 'An indication a facility is a public or private facility that confines pre-adjudicated/pre-convicted individuals, post-adjudicated/post-convicted individuals, or both.', NULL, 'scheme: C002193', NULL, $j$[{"v": "Yes", "n": "Yes", "d": "Facility is a public or private facility that confines pre-adjudicated/pre-convicted individuals, post-adjudicated/post-convicted individuals, or both.", "u": null, "notes": "concept: NI002193928200", "dep": null}, {"v": "No", "n": "No", "d": "Facility is not a public or private facility that confines pre-adjudicated/pre-convicted individuals, post-adjudicated/post-convicted individuals, or both.", "u": null, "notes": "concept: NI002193928201", "dep": null}]$j$::jsonb);
