SELECT public.ceds_tmp_valueset('CredentialAwardStatusType', 'An indication of whether a credential is valid for use.', NULL, 'scheme: C002196', NULL, $j$[{"v": "Valid", "n": "Valid", "d": "The credential is valid.", "u": null, "notes": "concept: NI002196928213", "dep": null}, {"v": "Expired", "n": "Expired", "d": "The credential is no longer valid because the Credential Award End Date has passed.", "u": null, "notes": "concept: NI002196928214", "dep": null}, {"v": "LapsedInactivity", "n": "Lapsed due to Inactivity", "d": "The credential is no longer valid because the recipient has failed to use the credential for the required minimum amount of time needed to keep it active.", "u": null, "notes": "concept: NI002196928215", "dep": null}, {"v": "Nullified", "n": "Nullified", "d": "The credential is no longer valid at the request of the recipient.", "u": null, "notes": "concept: NI002196928216", "dep": null}, {"v": "Revoked", "n": "Revoked", "d": "The credential has been revoked by the credential issuer.", "u": null, "notes": "concept: NI002196928217", "dep": null}, {"v": "Suspended", "n": "Suspended", "d": "The credential is not currently valid pending investigation and/or disciplinary action.", "u": null, "notes": "concept: NI002196928218", "dep": null}, {"v": "Withdrawn", "n": "Withdrawn", "d": "This credential is no longer valid. This credential was initially awarded but it was later determined by the credential issuer that it should not have been awarded and thus withdrawn.", "u": null, "notes": "concept: NI002196928219", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('CredentialAwardIdentificationSystem', 'A coding scheme that is used for identification and record-keeping purposes by a program, school, school system, state, or other organization to refer to the award of a credential.', NULL, 'scheme: C002199', NULL, $j$[{"v": "School", "n": "School-assigned number", "d": "The related Credential Award Identifier uses a school-assigned number.", "u": null, "notes": "concept: NI002199928272", "dep": null}, {"v": "District", "n": "District-assigned number", "d": "The related Credential Award Identifier uses a district-assigned number.", "u": null, "notes": "concept: NI002199928273", "dep": null}, {"v": "State", "n": "State-assigned number", "d": "The related Credential Award Identifier uses a state-assigned number.", "u": null, "notes": "concept: NI002199928274", "dep": null}, {"v": "Federal", "n": "Federal identification number", "d": "The related Credential Award Identifier uses a federal identification number.", "u": null, "notes": "concept: NI002199928275", "dep": null}, {"v": "Other", "n": "Other", "d": "The related Credential Award Identifier uses a Credential Award identification system not yet defined in CEDS.", "u": null, "notes": "concept: NI002199928276", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('HarassmentOrBullyingReligionType', 'The actual or perceived religious affiliation of a student that is the basis of an allegation of harassment or bullying.', NULL, 'scheme: C002202', NULL, $j$[{"v": "Agnostic", "n": "Agnostic", "d": "A person who believes that the existence or nature of an ultimate reality, such as a deity, is unknown, and probably unknowable.", "u": null, "notes": "concept: NI002202928280", "dep": null}, {"v": "Atheist", "n": "Atheist", "d": "A person who does not believe in the existence of a deity.", "u": null, "notes": "concept: NI002202928281", "dep": null}, {"v": "Buddhist", "n": "Buddhist", "d": "A person who follows the religion of eastern or central Asia that grew out of the teaching of Siddhartha Gautama, the Buddha, or Enlightened One. People of this faith believe that suffering is inherent in life and that one can be liberated from it by mental and moral self-purification by following the Four Noble Truths and the Eightfold Path in order to reach nirvana.", "u": null, "notes": "concept: NI002202928282", "dep": null}, {"v": "Catholic", "n": "Catholic", "d": "A person who follows the monotheistic religion of Catholic Christianity, especially that of the Roman Catholic Church. Followers of this faith believe the teachings of the Bible, and place emphasis on church traditions, including the historical continuity of the church, the Pope as the head of the church, and the requirement of celibacy of those in the priesthood.", "u": null, "notes": "concept: NI002202928283", "dep": null}, {"v": "EasternOrthodox", "n": "Eastern Orthodox (Russian, Greek, Other)", "d": "A person who follows the monotheistic religion of the Eastern Christian Church. This faith follows the teachings of the Bible and church traditions, accords primacy of honor to the Patriarch of Constantinople as head of the church, and adheres to the decisions of the First Seven Ecumenical Councils and the Byzantine Rite.", "u": null, "notes": "concept: NI002202928284", "dep": null}, {"v": "Hindu", "n": "Hindu", "d": "A person who observes the traditions and practices of the dominant religion of India, which include acceptance of the sanctity of the Vedas (sacred texts); the understanding of one Divine Reality manifested in multiple forms; acceptance of the laws of karma (principle of cause and effect), dharma (righteous modes of conduct), belief in reincarnation, and the ultimate spiritual goal of enlightenment (moksha).", "u": null, "notes": "concept: NI002202928285", "dep": null}, {"v": "Islamic", "n": "Islamic (Muslim)", "d": "A person who follows the monotheistic religion of Muslims, which includes belief in Allah as the sole deity and in Muhamad as his prophet. Practitioners of the Islamic faith follow the teachings of the Koran and practice the Five Pillars of Islam: praying, fasting during Ramadan, almsgiving, pilgrimage, and declaration of faith.", "u": null, "notes": "concept: NI002202928286", "dep": null}, {"v": "JehovahsWitness", "n": "Jehovah's Witness", "d": "A person who follows the religion founded by Charles Taze Russell. Members witness by distributing literature and by personal evangelism of beliefs in the theocratic rule of God, the sinfulness of organized religions and governments, and an imminent millennium. The activities of Jehovah's Witnesses are governed by the Watchtower Society which makes all major decisions, interprets the Bible, and counsels Witnesses using Watchtower materials. Members of the faith are often seen giving generously of their time in proclaiming their faith and teaching in private homes.", "u": null, "notes": "concept: NI002202928287", "dep": null}, {"v": "Jewish", "n": "Jewish (Judaism)", "d": "A person who identifies himself or herself as a member of the religious and/or ethnic group that descended from the ancient Hebrews and is characterized by belief in one transcendent God who revealed Himself to Abraham, Moses, and the Hebrew prophets. Jewish religious practice is based on the Hebrew Scriptures (the \"Torah\") and rabbinic laws and customs.", "u": null, "notes": "concept: NI002202928288", "dep": null}, {"v": "Mormon", "n": "Mormon (Latter-day Saint)", "d": "A person who follows the Church of Jesus Christ of Latter-day Saints tracing its modern origin to Joseph Smith and accepting the Book of Mormon as scripture. Latter-day Saints consider the following writings to be scripture: 1) The Holy Bible; 2) The Book of Mormon, Another Testament of Jesus Christ; 3) The Doctrine and Covenants; and 4) The Pearl of Great Price. Mormons are often associated with members of the faith who serve as full-time volunteer missionaries in the U.S. and abroad.", "u": null, "notes": "concept: NI002202928289", "dep": null}, {"v": "MultipleReligions", "n": "Multiple Religions, Group", "d": "A group of persons demonstrating a commitment or devotion to religious faith or observance based upon multiple faiths.", "u": null, "notes": "concept: NI002202928290", "dep": null}, {"v": "OtherChristian", "n": "Other Christian", "d": "A person who follows other denominations or nondenominational religions based on the life and teachings of Jesus Christ but not described in the other religion categories. Examples of these religions include Metaphysical-Christ Church Unity, Spiritualist, Unity/Unitarianist, Unity Church, Universalist, and Other Metaphysical.", "u": null, "notes": "concept: NI002202928291", "dep": null}, {"v": "OtherReligions", "n": "Other Religions", "d": "A person who follows other non-Christian religions not described in the other religion categories. Examples of these religions include the Baha'I Faith, Jainism, Shintoism, Taoism, Tenrikyo, Wicca, and Zoroastrianism.", "u": null, "notes": "concept: NI002202928292", "dep": null}, {"v": "Protestant", "n": "Protestant", "d": "A person who follows the monotheistic religion of Christianity that is not part of Catholic or Eastern Orthodox faith. Members of this faith affirm the Reformation principles of justification by faith alone, the priesthood of all believers, and the primacy of the Bible as the only source of revealed truth. Moreover, believers deny the universal authority of the Pope and some churches are governed by federated councils on the local, national, and international levels.", "u": null, "notes": "concept: NI002202928293", "dep": null}, {"v": "Sikh", "n": "Sikh", "d": "A person who follows the monotheistic religion of India founded about 1500 by Guru Nanak and marked by rejection of idolatry and caste. Sikhs follow the teachings of 10 gurus; study from the religion's primary sacred text (i.e., the Guru Granth Sahib), and worship in Gurdwaras. Some members of the Sikh faith may be distinguished by the dastaar (Sikh turban) and five religious articles: kesh (unshorn hair, including a beard), kanga (wooden comb), kara (bracelet), kachera (short trousers), and kirpan (religious article resembling a sword).", "u": null, "notes": "concept: NI002202928294", "dep": null}]$j$::jsonb);
SELECT public.ceds_tmp_valueset('TitleIIILanguageInstructionIndicator', 'An indication of whether a teacher teaches in language instruction educational programs designed for English learners supported with Title III of ESEA, as amended by ESSA, funds.', NULL, 'scheme: C002203', NULL, $j$[{"v": "Yes", "n": "Yes", "d": "The teacher teaches in language instruction educational programs designed for English learners supported with Title III of ESEA, as amended by ESSA, funds.", "u": null, "notes": "concept: NI002203928163", "dep": null}, {"v": "No", "n": "No", "d": "The teacher does not teach in language instruction educational programs designed for English learners supported with Title III of ESEA, as amended by ESSA, funds.", "u": null, "notes": "concept: NI002203928164", "dep": null}]$j$::jsonb);

