SELECT public.ceds_tmp_attr('hasFacultyStatus', 'hasFacultyStatus', 'Persons identified by the institution as such and typically those whose initial assignments are made for the purpose of conducting instruction, research or public service as a principal activity (or activities). They may hold academic rank titles of professor, associate professor, assistant professor, instructor, lecturer or the equivalent of any of those academic ranks. Faculty may also include the chancellor/president, provost, vice provosts, deans, directors or the equivalent, as well as associate deans, assistant deans and executive officers of academic departments (chairpersons, heads or the equivalent) if their principal activity is instruction combined with research and/or public service. The designation as "faculty" is separate from the activities to which they may be currently assigned. For example, a newly appointed president of an institution may also be appointed as a faculty member. Graduate, instruction, and research assistants are not included in this category.', 'As defined in IPEDS.', 'enum', 'FacultyStatus', 'property: P000734
rangeIncludes: C000734 (FacultyStatus)', NULL, $j$["PostsecondaryStaffEmployment"]$j$::jsonb);
SELECT public.ceds_tmp_attr('hasGraduateAssistantStatus', 'hasGraduateAssistantStatus', 'Graduate-level students employed on a part-time basis, not limited to, but often employed for the primary purpose of assisting in classroom or laboratory instruction or in the conduct of research. Graduate students having titles such as graduate assistant, teaching assistant, teaching associate, teaching fellow, or research assistant typically hold these positions.', 'As defined in IPEDS', 'enum', 'GraduateAssistantStatus', 'property: P000742
rangeIncludes: C000742 (GraduateAssistantStatus)', NULL, $j$["PostsecondaryStaffEmployment"]$j$::jsonb);
SELECT public.ceds_tmp_attr('hasInstructionalStaffStatus', 'hasInstructionalStaffStatus', 'Staff whose primary function/occupational activity is primarily instruction or instruction combined with research and/or public service. Does not include medical school staff.', 'As defined in IPEDS.', 'enum', 'InstructionalStaffStatus', 'property: P000732
rangeIncludes: C000732 (InstructionalStaffStatus)', NULL, $j$["PostsecondaryStaffEmployment"]$j$::jsonb);
SELECT public.ceds_tmp_attr('hasMedicalSchoolStaffStatus', 'hasMedicalSchoolStaffStatus', 'Staff employed by or employees working in the medical school component of a postsecondary institution or in a free standing medical school. Does not include staff employed by or employees working strictly in a hospital associated with a medical school or those who work in health or allied health schools or departments such as dentistry, veterinary medicine, nursing or dental hygiene.', 'As defined in IPEDS.', 'enum', 'MedicalSchoolStaffStatus', 'property: P000733
rangeIncludes: C000733 (MedicalSchoolStaffStatus)', NULL, $j$["PostsecondaryStaffEmployment"]$j$::jsonb);
SELECT public.ceds_tmp_attr('hasPostsecondaryApplicant', 'hasPostsecondaryApplicant', 'An individual who has fulfilled the institution''s requirements to be considered for admission (including payment or waiving of the application fee, if any) and who has been notified of one of the following actions: admission, nonadmission, placement on waiting list, or application withdrawn (by applicant or institution). Include early decision, early action, and students who began studies during summer in this cohort.', 'CDS definition/instructions; first part matches IPEDS', 'enum', 'PostsecondaryApplicant', 'property: P000755
