format: xsd:integer
textFormat: Integer', NULL, $j$["LocalEducationAgencyFederalReporting"]$j$::jsonb);
SELECT public.ceds_tmp_attr('hasHarassmentOrBullyingReligionType', 'hasHarassmentOrBullyingReligionType', 'The actual or perceived religious affiliation of a student that is the basis of an allegation of harassment or bullying.', 'Supports CRDC School Form reporting, specifically HIBS-2 (Allegations of Harassment or Bullying - By Religion Type).', 'enum', 'HarassmentOrBullyingReligionType', 'property: P002202
